(function(){"use strict";window.NamazDuaLibrary=Object.freeze([{"id":2,"title":"Namazdan Sonra Rızık ve Yardım için Dua","ref":"Buhârî: 844","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_2.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","latin":"Lâ ilâhe illallahu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve hüve alâ külli şey'in kadîr. Allâhümme lâ mâni'a limâ a'tayte ve lâ mu'tiye limâ mena'te ve lâ yenfe'u zel-ceddi minke'l-cedd","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır ve O her şeye kadirdir. Allah'ım! Senin verdiğini kimse tutamaz, tuttuğunu da kimse veremez. Hiçbir servet ve imkân sahibinin serveti, Senden gelmeden kendisine fayda vermez.","en":"There is none worthy of worship except Allah alone with no partner or associate. He is the Dominion and to Him be all praise, and He is able to do all things. O Allah, one can withhold what You have given and none can give what You have withheld, and no wealth or fortune can benefit anyone for from You comes all wealth and fortune."},{"id":3,"title":"Lâ İlâhe İllallah'ın Gücü (Köle Azat Etme)","ref":"Buhârî: 6404","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_3.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","latin":"Lâ ilâhe illallahu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve hüve alâ külli şey'in kadîr","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır ve O her şeye kadirdir.\n\nPeygamber (ﷺ) şöyle buyurmuştur: Kim yukarıdaki zikri 10 kez tekrarlarsa, İsmail'in (as) neslinden dört köleyi azat etmiş gibi sevap kazanır.","en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the dominion and His is the praise, and He is Able to do all things.\n\nThe Prophet (ﷺ) said: The person who says the above statement 10 times It would be as if he had freed four of Ishmael's (As) children from slavery."},{"id":4,"title":"Hidayet için Dua (Fâtiha Suresinin Okunması)","ref":"Fâtiha Suresi 1:5","url":"https://quran.com/1/5","ar":"إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ","latin":"İyyâke na'büdü ve iyyâke nesta'în","tr":"Yalnız Sana ibadet eder ve yalnız Senden yardım dileriz.\n\nAllah kimi hidayete erdirirse o doğru yolu bulmuştur; kimi de saptırırsa, artık onun için yol gösteren bir dost bulamazsın. (Kehf Suresi 18:17)","en":"It is You we worship and It is You we ask for help.\n\nHe whom Allah guides is the [rightly] guided, but he whom He leaves astray - never will you find for him a protecting guide. (Surah Al-Kahf 18:17)"},{"id":5,"title":"Hidayet için Nebevî Dua (Sahîh-i Müslim)","ref":"Müslim: 770","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_5.json","ar":"اِهْدِنِي لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُّسْتَقِيْمٍ","latin":"İhdinî limâhtelefe fîhi mine'l-hakkı bi-iznik, inneke tehdî men teşâü ilâ sırâtın müstakîm","tr":"Hak konusunda ihtilaf edilen meselelerde beni Senin iznin ile doğruya ilet; şüphesiz Sen dilediğini doğru yola iletirsin.","en":"Guide me through that which there has been difference concerning the truth, verily, You are upon a straight path."},{"id":6,"title":"İbadette Yardım için Namazdan Sonra Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1522","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_6.json","ar":"اَللَّهُمَّ أَعِنِّيْ عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","latin":"Allâhümme eınnî alâ zikrike ve şükrike ve husni ibâdetik","tr":"Allah'ım! Seni zikretmem, Sana şükretmem ve Sana en güzel şekilde ibadet etmem konusunda bana yardım et.","en":"O Allah, help me to remember You, to give You thanks, and to perform Your worship in the best manner."},{"id":7,"title":"Güzel Ahlak için Dua (Meşru Dua)","ref":"Müslim: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_7.json","ar":"وَاهْدِنِيْ لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِيْ لِأَحْسَنِهَا إِلَّا أَنْتَ وَاصْرِفْ عَنِّي سَيِّئَهَا لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ","latin":"Vehdini li ahseni'l-ahlâk, lâ yehdî li ahsenihâ illâ ente, vasrif annî seyyiehâ, lâ yasrifu annî seyyiehâ illâ ente","tr":"Beni en güzel ahlaka ilet; zira en güzel ahlaka ancak Sen iletebilirsin. Benden kötü ahlakı uzak tut; zira onu benden ancak Sen uzaklaştırabilirsin.","en":"Guide me to the best of manners for none can guide to the best of them but You. Protect me from bad manners for none can protect against them but You."},{"id":8,"title":"Hidayet için Dua","ref":"Müslim: 2725","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_8.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالسَّدَادَ","latin":"Allâhümme innî es'elüke'l-hudâ ve's-sedâd","tr":"Allah'ım! Senden doğruluğu ve Sırat-ı Müstakim'e sıkıca tutunmayı istiyorum.","en":"O Allah, I beg of Thee righteousness and adhering to the straight path."},{"id":9,"title":"Vitir Namazında Güçlü Gece Duası (Kunut Duası)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1425","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_9.json","ar":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ وَعَافِنِي فِيمَنْ عَافَيْتَ وَتَوَلَّنِيْ فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِي شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِي وَلَا يُقْضَى عَلَيْكَ إِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبَارَكْتَ رَبَّنَا وَتَعَالَيْتَ","latin":"Allâhümme'hdinî fîmen hedayte, ve âfinî fîmen âfeyte, ve tevelleni fîmen teveileyte, ve bârik lî fîmâ a'tayte, ve kınî şerre mâ kadayte, fe inneke takdî ve lâ yukdâ aleyke, innehû lâ yezillü men vâleyte, ve lâ ye'izzü men âdeyte, tebârekte Rabbenâ ve teâleyte","tr":"Allah'ım! Hidayete erdirdiklerin arasında beni de hidayete erdir. Afiyet verdiklerin arasında bana da afiyet ver. Velayetine aldıkların arasında beni de velayetine al. Verdiğin şeylerde bana bereket ver. Hükmettiğin şeylerin kötülüğünden beni koru. Şüphesiz Sen hükmedersin, Sana karşı hüküm verilmez. Dost edindiğin kimse asla zelil olmaz, düşman tuttuğun kimse ise asla izzet kazanamaz. Rabbimiz! Sen mübareksin ve yücesin.","en":"O Allah, guide me with those whom You have guided, and strengthen me with those whom You have given strength. Take me to Your care with those whom You have taken to Your care. Bless me in what You have given me. Protect me from the evil You have ordained. Surely, You command and are not commanded, and none whom You have committed to Your care shall be humiliated and none whom You have taken as an enemy shall taste glory. You are Blessed, Our Lord, and Exalted."},{"id":11,"title":"Mağfiret Duası (Rabbigfir lî ve tüb aleyye inneke)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1516","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_11.json","ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَىَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ","latin":"Rabbigfir lî ve tüb aleyye inneke ente't-Tevvâbü'r-Rahîm","tr":"Ey Rabbim! Beni bağışla ve tövbemi kabul et; zira Sen tövbeleri çokça kabul eden ve çok merhametli olansın.","en":"O Allah forgive me and accept my repentance, for You are the Accepter of repentance, the Most Merciful."},{"id":12,"title":"Büyük Günahların Bağışlanması için Dua","ref":"Sahîh (Elbânî). Tirmizî: 3577","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_12.json","ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْحَىُّ الْقَيُّوْمُ وَأَتُوبُ إِلَيْهِ","latin":"Estağfirullâhe'l-Azîme'llezî lâ ilâhe illâ Hüve'l-Hayyü'l-Kayyûmü ve etûbü ileyh","tr":"İbadet edilmeye layık O'ndan başka hiçbir ilah olmayan, diri ve her şeyi ayakta tutan Yüce Allah'tan bağışlanma diler ve O'na tövbe ederim.\n\nPeygamber (ﷺ) şöyle buyurmuştur: 'Kim şunu söylerse — Yüce Allah'tan bağışlanma dilerim; O'ndan başka ibadete layık hiçbir ilah yoktur, O Hayy'dır (diridir), Kayyûm'dur (her şeyi ayakta tutandır) ve O'na tövbe ederim — savaş meydanından kaçmış olsa dahi bağışlanır.'","en":"I seek the forgiveness of Allah the Mighty, Whom there is none worthy of worship except Him, the Living, the Eternal, and I repent to Him.\n\nThe Prophet (ﷺ) said, \"Whoever says, 'I seek forgiveness from Allah, the Exalted, there is no god but He, the Ever-Living, the Everlasting, and I repent to Him', is forgiven even if he flees from the battlefield.\""},{"id":13,"title":"Cennet ve Cehennemden Korunma Duası","ref":"Sahîh (Elbânî). İbn Mâce: 910","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_13.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوذُ بِكَ مِنَ النَّارِ","latin":"Allâhümme innî es'elüke'l-cennete ve eûzü bike mine'n-nâr","tr":"Allah'ım! Senden cenneti istiyorum ve ateşten Sana sığınıyorum.\n\nEbû Hüreyre'den (ra) rivayet edilmiştir: Allah'ın Resulü (ﷺ) bir adama, 'Namazında ne dua ediyorsun?' diye sordu. Adam şöyle dedi: Tahiyyat okuyorum, ardından — (yukarıdaki dua) — diyorum. Senin gibi güzel dua edemiyorum, Muaz gibi de okuyamıyorum! Peygamber (ﷺ) şöyle buyurdu: 'Biz de senin gibi dua ediyoruz!'","en":"O Allah, I ask You for Paradise and seek Your protection from the Fire.\n\nNarrated by Abu Huraira (RA): The Messenger of Allah (ﷺ), asked a man, \"What do you supplicate in your prayer?\" The man says, I recite Tashahhud and say- (The dua is mentioned above) I can’t recite dua as beautifully as you, nor can I recite dua like Mu'adh!\" Then Prophet (ﷺ) said, “We also supplicate like you!”"},{"id":15,"title":"Kalplerin İtaate Yönelmesi için Dua (Sahîh-i Müslim)","ref":"Müslim: 2655","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_15.json","ar":"اَللَّهُمَّ مُصَرِّفَ الْقُلُوبِ صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ","latin":"Allâhümme musarrifel-kulûb, sarrif kulûbenâ alâ tâatik","tr":"Allah'ım! Kalpleri dilediği yöne çeviren! Kalplerimizi Sana itaate yönelt.\n\nAbdullah b. Amr b. el-Âs (ra) Allah'ın Resulü'nden (ﷺ) şunu işittiğini rivayet etmiştir: Şüphesiz Âdem oğullarının tüm kalpleri, Rahman'ın parmaklarından iki parmağı arasında tek bir kalp gibidir. O kalbi dilediği yöne çevirir. Ardından Allah'ın Resulü (ﷺ) şöyle dua etti: (Yukarıda geçen dua)","en":"O Allah! Controller of the hearts, direct our hearts to Your obedience.\n\nAbdullah bin Amr bin al-'As (RA) reported that he heard Allah's Messenger (ﷺ) as saying: Verily, the hearts of all the sons of Adam are between the two fingers out of the fingers of the Compassionate Lord as one heart. He turns that to any (direction) He likes. Then Allah’s Messenger (ﷺ) said: (Dua mentioned above)"},{"id":16,"title":"Dinde Sebat için Dua (Meşru Dua)","ref":"Sahîh (Elbânî). Tirmizî: 3522","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_16.json","ar":"يَا مُقَلِّبَ الْقُلُوبِ ثَبِّتْ قَلْبِيْ عَلَى دِيْنِكَ","latin":"Yâ mukallibe'l-kulûb, sebbit kalbî alâ dînik","tr":"Ey Kalpleri Çeviren! Kalbimi Senin Dininde sabit kıl.\n\nBen de: 'Ey Allah'ın Resulü! Neden bu kadar çok dua ediyorsunuz?' dedim. O şöyle buyurdu: 'Ey Ümmü Seleme! Hiçbir insan yoktur ki kalbi Allah'ın parmaklarından iki parmak arasında olmasın; O dilediğini sabit kılar, dilediğini saptırır.'","en":"O Changer of the Hearts! Strengthen my heart upon Your Religion.\n\nSo I said: O Messenger of Allah (ﷺ), why do you supplicate so frequently. He said: ‘O Umm Salamah! Verily, there is no human being except that his heart is between Two Fingers of the Fingers of Allah, so whomsoever He wills He makes steadfast, and whomever He wills He causes to deviate."},{"id":17,"title":"Tüm İşlerde Korunma için Dua (Meşru Dua)","ref":"Sahîh (Süyûtî). Câmiu's-Sağîr: 1450","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_17.json","ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآَخِرَةِ","latin":"Allâhümme ahsin âkıbetenâ fi'l-umûri küllihâ ve ecirnâ min hızyid-dünyâ ve azâbi'l-âhirah","tr":"Allah'ım! Tüm işlerimizde bize güzel bir âkıbet nasip et ve bizi dünyanın rezilliğinden ve ahiretin azabından koru.","en":"O Allah! grant us a good outcome on all of our affairs and save us from the disgrace of this world and the punishment of the Hereafter."},{"id":18,"title":"Dinde Başarı için Dua (Allâhümme aslih lî dînî)","ref":"Müslim: 2720","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_18.json","ar":"اَللَّهُمَّ أَصْلِحْ لِي دِينِيَ الَّذِي هُوَ عِصْمَةُ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي فِيهَا مَعَاشِي، وَأَصْلِحْ لِي آخِرَتِي الَّتِي فِيهَا مَعَادِي، وَاجْعَلِ الْحَيَاةَ زِيَادَةً لِي فِي كُلِّ خَيْرٍ، وَاجْعَلِ الْمَوْتَ رَاحَةً لِي مِنْ كُلِّ شَرٍّ","latin":"Allâhümme aslih lî dîniyellezî hüve ısmetü emrî, ve aslih lî dünyâyelleti fîhâ meâşî, ve aslih lî âhiretiyelleti fîhâ meâdî, vec'ali'l-hayâte ziyâdeten lî fî külli hayr, vec'ali'l-mevte râhaten lî min külli şerr","tr":"Allah'ım! İşlerimin güvencesi olan Dinimi benim için ıslah et. Geçimimin bağlı olduğu dünya hayatımı benim için ıslah et. Döneceğim ahiretimi benim için ıslah et. Hayatı benim için her hayırda artış kıl; ölümü de benim için her şerden kurtuluş kıl.","en":"O Allah perfect for me my religion on which success of all my affairs depends, And perfect my worldly affairs on which my livelihood depends, And perfect my hereafter to which I will return, And make in life for me an increase of all good, And make death for me a comfort from all evil."},{"id":19,"title":"Korunma ve Allah'ın Yardımını Dilemek için Dua","ref":"Müslim: 2739","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_19.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ وَتَحَوُّلِ عَافِيَتِكَ وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيعِ سَخَطِكَ","latin":"Allâhümme innî eûzü bike min zevâli ni'metik, ve tehavvüli âfiyetik, ve fucâeti nikmetik, ve cemîi sahâtik","tr":"Allah'ım! Nimetinin gitmesinden, afiyetinin değişmesinden, gazabının ansızın çatmasından ve Senin her türlü öfkenden Sana sığınıyorum.","en":"O Allah, I seek refuge with You from deprivation of Your blessing, alteration of Your protection, sudden infliction of Your anger, and all Your wrath."},{"id":20,"title":"Stres, Kaygı ve Üzüntü için Dua","ref":"Buhârî: 2893","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_20.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","latin":"Allâhümme innî eûzü bike mine'l-hemmi ve'l-hazeni, ve'l-aczi ve'l-keseli, ve'l-buhli ve'l-cubni, ve dalai'd-dayni ve galabeti'r-ricâl","tr":"Allah'ım! Keder ve tasadan, acizlikten ve tembellikten, cimrilikten ve korkaklıktan, borç yükünden ve insanların baskısına maruz kalmaktan Sana sığınıyorum.","en":"O Allah, I seek refuge in you from grief and sadness, from weakness and from laziness, from miserliness and from cowardice, from being overcome by debt and overpowered by men (i.e. others)."},{"id":22,"title":"Günahların Bağışlanması için Dua","ref":"Buhârî: 6405","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_22.json","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","latin":"Sübhânallahi ve bihamdih","tr":"Allah'ı noksan sıfatlardan tenzih eder ve O'na hamd ederim.\n\nPeygamber (ﷺ) şöyle buyurdu: Günde 100 kez (yukarıda geçen duayı) söyleyen kimsenin, denizin köpüğü kadar da olsa tüm günahları bağışlanır.","en":"Glorified is Allah and praised is He.\n\nThe Prophet (ﷺ) said, A person who says 100 times a day (dua mentioned above) It will be forgiven all his sins even if they were as much as the foam of the sea."},{"id":23,"title":"Bağışlanma için Zikir (Sübhânallahi ve Bihamdih Duası)","ref":"Buhârî: 6406","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_23.json","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ","latin":"Sübhânallahi ve bihamdih, Sübhânallâhi'l-Azîm","tr":"Allah'ı tüm eksikliklerden tenzih eder ve O'na hamd ederim; yüce Allah'ı tenzih ederim.","en":"Glory be to Allah and all praise is due to him, glory be to Allah the great."},{"id":24,"title":"Allah'ın Sevdiği Güçlü Zikir (Meşru Dua)","ref":"[1] Müslim: 2137 [2] Müslim: 2695","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_24.json","ar":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","latin":"Sübhânallahi, velhamdülillâhi, ve lâ ilâhe illallahu, vallahu ekber","tr":"Allah'ı tüm eksikliklerden tenzih ederim, hamd Allah'adır. Allah'tan başka ibadete layık hiçbir ilah yoktur ve Allah en büyüktür. [1]\n\nAllah'ın Resulü (ﷺ) şöyle buyurdu: 'Bu kelimeleri söylemek, güneşin doğduğu her şeyden bana daha sevimlidir.' [2]","en":"How perfect Allah is, and all praise is for Allah. None has the right to be worshipped except Allah, and Allah is the greatest. [1]\n\nAllah's Messenger (ﷺ) said, \"The uttering of (these words) is dearer to me than anything over which the sun rises. [2]"},{"id":25,"title":"Sübhânallah Demenin Faziletleri","ref":"Müslim: 2698","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_25.json","ar":"سُبْحَانَ اللَّهِ","latin":"Sübhânallah","tr":"Allah'ı tüm eksikliklerden tenzih ederim.\n\nBin iyilik (hesabına) kaydedilir ve bin kötülük silinir.","en":"How perfect Allah is.\n\nOne thousand virtues are recorded (to your credit) and one thousand vices are blotted out."},{"id":26,"title":"İhlâs Suresini Her Gün Okumanın Faziletleri","ref":"Sahîh (Elbânî). Sahîhu'l-Câmi: 6472","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_26.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ﴿١﴾ اللَّـهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿٤﴾","latin":"Bismillâhirrahmânirrahîm. (1) Kul hüvallahu ehad. (2) Allâhüssamed. (3) Lem yelid ve lem yûled. (4) Ve lem yekün lehû küfüven ehad","tr":"Rahman ve Rahim olan Allah'ın adıyla. (1) De ki: 'O Allah tektir. (2) Allah Samed'dir (her şey O'na muhtaçtır, O hiçbir şeye muhtaç değildir). (3) O doğurmamış ve doğurulmamıştır. (4) Hiçbir şey O'na denk ve benzer değildir.' (İhlâs Suresi: 1-4)\n\nSahih bir hadiste Muaz b. Enes (ra) şöyle dedi: Allah'ın Resulü (ﷺ) şöyle buyurdu: Kim İhlâs Suresini 10 kez okursa Allah ona cennette bir ev inşa eder.","en":"In the name of Allah, the Entirely Merciful, the Especially Merciful. (1) Say, \"He is Allah, [who is] One, (2) Allah, the Eternal Refuge. (3) He neither begets nor is born, (4) Nor is there to Him any equivalent.\" (Sura Ikhlas: 1-4)\n\nIn a saheeh hadeeth, Mu'adh ibn Anas (RA) said: The Messenger of Allah (ﷺ) said: Whoever recites Surah Ikhlas 10 times, Allah will make a house for him in Paradise."},{"id":27,"title":"Cennette Ağaç Dikmek için Günlük Dua","ref":"Sahîh (Elbânî). Tirmizî: 3464","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_27.json","ar":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","latin":"Sübhânallâhi'l-Azîmi ve bihamdih","tr":"Yüce Allah'ı tüm eksikliklerden tenzih eder ve O'na hamd ederim.\n\nOnun için cennette bir hurma ağacı dikilir.","en":"How perfect Allah is, The Supreme, and I praise Him.\n\nA palm tree will be planted in Paradise for him."},{"id":28,"title":"Cennet için Dua (Lâ Havle ve Lâ Kuvvete)","ref":"Buhârî: 6384","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_28.json","ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Lâ havle ve lâ kuvvete illâ billâh","tr":"Güç ve kuvvet yalnızca Allah iledir.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Ey Abdullah b. Kays! Sana cennet hazinelerinden birini haber vereyim mi?' Ben dedim ki: 'Evet, ey Allah'ın Resulü!' O şöyle buyurdu: 'Onu söyle.' — (Dua yukarıda geçmektedir)","en":"There is no might nor power except with Allah.\n\nThe Prophet (ﷺ) said, “O 'Abdullah ibn Qays! Shall I not inform you of one of the treasures of Paradise? ” I said, \"Surely, O Messenger of Allah.\" He said, \"Say it.\" - (The dua is mentioned above)"},{"id":29,"title":"Allah'ı Tüm Övgülerle Yüceltme Duası (Meşru Dua)","ref":"Müslim: 2696","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_29.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، سُبْحَانَ اللَّهِ رَبِّ الْعَالَمِينَ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَزِيزِ الْحَكِيمِ","latin":"Lâ ilâhe illallahu vahdehû lâ şerîke leh, Allahu ekber kebîrâ, velhamdülillâhi kesîrâ, Sübhânallahi Rabb'il-âlemîn, lâ havle ve lâ kuvvete illâ billâhi'l-Azîzi'l-Hakîm","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, ortağı yoktur. Allah en büyüktür; hamd Allah'a aittir bolca. Alemlerin Rabbi Allah'ı tüm eksikliklerden tenzih ederim. Güç ve kuvvet yalnızca Azîz ve Hakîm olan Allah iledir.","en":"None has the right to be worshipped except Allah, alone without any partener. Allah is most great and much praise is for Allah. How perfect Allah is, Lord of the worlds. There is no might nor power except with Allah, The Exalted in might, The Wise."},{"id":30,"title":"İslam'ı Kabul Ettikten Sonra Dua (Meşru Dua)","ref":"Müslim: 2697","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_30.json","ar":"اَللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي","latin":"Allâhümmagfir lî, verhamnî, vehdini, ve âfinî verzuknî","tr":"Allah'ım! Beni bağışla, bana merhamet et, bana hidayet ver, bana afiyet ver ve bana rızık nasip et.\n\nMüslim'in diğer bir rivayetinde şöyle geçmektedir: 'Bu kelimeler, dünya ve ahirette ihtiyacın olan her şeyi sana bir araya getirecektir.'","en":"O Allah, forgive me, have mercy upon me, guide me and grant me sustenance.\n\nAnother narration of Muslim says, \"These will combine everything in this world and the Hereafter for you.\""},{"id":31,"title":"İslam'ın En Güçlü Zikri ve Duası","ref":"Hasen (Elbânî). Tirmizî: 3383","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_31.json","ar":"اَلْحَمْدُ لِلَّهِ","latin":"Elhamdülillâh","tr":"Hamd yalnızca Allah'adır.","en":"All praise is for Allah."},{"id":32,"title":"Cennette Sonsuza Dek Kalan Güçlü Zikir","ref":"Müsned-i Ahmed (no. 513) (Ahmed Şâkir neşri); senedi sahihtir. Bkz. Mecmeu'z-Zevâid 1/297. İbn Hacer, Bülûğu'l-Merâm'da İbn Hibbân ve Hâkim'in onu sahih saydığını belirtir.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_32.json","ar":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Sübhânallahi, velhamdülillâhi, ve lâ ilâhe illallahu, vallahu ekber, lâ havle ve lâ kuvvete illâ billâh","tr":"Allah'ı tüm eksikliklerden tenzih ederim; hamd yalnızca Allah'adır. Allah'tan başka ibadete layık hiçbir ilah yoktur ve Allah en büyüktür. Güç ve kuvvet yalnızca Allah iledir.","en":"How perfect Allah is, and all praise is for Allah. None has the right to be worshipped except Allah, and Allah is the greatest. There is no might nor power except with Allah."},{"id":36,"title":"Kadir Gecesi Suresinin Fazileti","ref":"Kadir Suresi 97:1-5","url":"https://quran.com/97/1","ar":"إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ ﴿١﴾ وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ ﴿٢﴾ لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ ﴿٣﴾ تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ ﴿٤﴾ سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ ﴿٥﴾","latin":"İnnâ enzelnâhü fî leyletil-kadr. Ve mâ edrâke mâ leyletül-kadr. Leyletül-kadri hayrum-min elfi şehr. Tenezzelül-melâ'iketü ver-rûhu fîhâ bi-izni rabbihim min külli emr. Selâmün hiye hattâ matla'il-fecr.","tr":"(1) Şüphesiz Biz onu (Kur'an'ı) Kadir Gecesi'nde indirdik. (2) Kadir Gecesi'nin ne olduğunu sana bildiren nedir? (3) Kadir Gecesi bin aydan daha hayırlıdır. (4) Melekler ve Ruh (Cebrail), o gecede Rablerinin izniyle her türlü iş için iner. (5) O gece, fecrin doğuşuna kadar bir esenliktir.","en":"(1) Indeed, We sent the Qur'an down during the Night of Decree. (2) And what can make you know what is the Night of Decree? (3) The Night of Decree is better than a thousand months. (4) The angels and the Spirit descend therein by permission of their Lord for every matter. (5) Peace it is until the emergence of dawn."},{"id":37,"title":"Kadir Gecesi Bağışlanma Duası","ref":"Sahîh (Elbânî). Tirmizî: 3513","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_37.json","ar":"اَللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","latin":"Allâhümme inneke afüvvün kerîm, tuhibbül-afve, fa'fü annî","tr":"Allah'ım! Sen çok affedicisin, çok kerîmsin. Affetmeyi seversin; beni de affet.","en":"O Allah, You are Most Forgiving, Generous. You love forgiveness; so forgive me."},{"id":39,"title":"Teheccüd Vaktinde Bağışlanma Duası","ref":"[1] Buhârî: 1145 [2] Zâriyât Suresi 51: 17-18","url":"https://quran.com/51/17","ar":"كَانُوا قَلِيلًا مِّنَ اللَّيْلِ مَا يَهْجَعُونَ ﴿١٧﴾ وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ ﴿١٨﴾","latin":"Kânû kalîlem mine'l-leyli mâ yehceûn. Ve bil-eshâri hüm yestağfirûn.","tr":"(17) Geceleyin pek az uyurlardı. (18) Seher vakitlerinde ise bağışlanma dilerlerdi. [2]","en":"(17) They used to sleep but little of the night, (18) And in the hours before dawn they would ask forgiveness. [2]"},{"id":45,"title":"Gece Uyanıldığında Dua (Meşru Dua)","ref":"Buhârî: 1154","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_45.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ‏ اَلْحَمْدُ لِلَّهِ وَسُبْحَانَ اللَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Lâ ilâhe illallahu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve hüve alâ külli şey'in kadîr. Elhamdülillâhi ve sübhânallâhi ve lâ ilâhe illallahu vallâhu ekber ve lâ havle velâ kuvvete illâ billâh","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur. O tektir, ortağı yoktur. Mülk O'nundur, hamd O'nadır ve O her şeye kadirdir. Hamd Allah'adır. Allah'ı tüm eksikliklerden tenzih ederim. Allah'tan başka ibadete layık hiçbir ilah yoktur. Allah en büyüktür. Güç ve kuvvet yalnızca Allah iledir.\n\nAllah'ım! Beni bağışla. Ya da Allah'a dua ederse icabet olunur; abdest alıp namaz kılarsa namazı kabul edilir.","en":"None has the right to be worshipped but Allah. He is the Only One and has no partners. For Him is the Kingdom and all the praises are due for Him. He is Omnipotent. All the praises are for Allah. All the glories are for Allah. And none has the right to be worshipped but Allah, And Allah is Great And there is neither Might nor Power Except with Allah.\n\nO Allah! Forgive me. Or invokes (Allah), he will be responded to and if he performs ablution (and prays), his prayer will be accepted."},{"id":47,"title":"Musibet için Dua (Meşru Dua)","ref":"Müslim: 918","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_47.json","ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ، اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","latin":"İnnâ lillâhi ve innâ ileyhi râciûn, Allâhümme'-cürnî fî musîbetî ve'hlif lî hayren minhâ","tr":"Şüphesiz biz Allah'a aidiz ve şüphesiz O'na döneceğiz. Allah'ım! Bu musibetimde bana ecir ver ve bunun yerine daha hayırlısını ver.\n\nÜmmü Seleme (ra) Allah'ın Resulü'nün (ﷺ) şöyle buyurduğunu rivayet etmiştir: Herhangi bir müslüman bir musibete uğrar da Allah'ın emrettiğini — (yukarıdaki dua) — söylerse, Allah ona bunun yerine daha hayırlısını verir.","en":"We are from Allah and unto Him we return. O Allah take me out of my plight and bring to me after it something better.\n\nUmm Salama (RA) reported Allah's Messenger (ﷺ) as saying: If any Muslim who suffers some calamity says, what Allah has commanded him - (The dua is mentioned above) Allah will give him something better than it in exchange."},{"id":49,"title":"Namaza Başlamadan Önce Dua","ref":"Müslim: 601","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_49.json","ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا وَالْحَمْدُ لِلَّهِ كَثِيْرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيْلًا","latin":"Allahu ekber kebîrâ velhamdülillâhi kesîrâ ve Sübhânallâhi bükreten ve asîlâ","tr":"Allah en büyüktür, pek büyüktür. Hamd Allah'a bolca aittir. Allah'ı sabah ve akşam tüm eksikliklerden tenzih ederim.\n\nAllah'ın Resulü (ﷺ) şöyle buyurdu: 'Bu sözleri kim söyledi?' Halktan biri dedi ki: 'Ben söyledim, ey Allah'ın Resulü!' O (ﷺ) şöyle buyurdu: 'Bu söz beni hayrete düşürdü; zira cennetin kapıları onun için açıldı.' İbn Ömer (ra) şöyle dedi: Allah'ın Resulü'nün (ﷺ) bunu söylediğini işittiğimden beri bu kelimeleri bırakmadım.","en":"Allah is the Greatest, Most Great. Praise is to Allah, abundantly. Glory is to Allah, at the break of day and at its end.\n\nThe Messenger of Allah (ﷺ) said, \"Who uttered such and such a word?\" A person (who have recited these words) among the people said: It is I, O Messenger of Allah! He (ﷺ) said: it’s utterance surprised me, for the doors of heaven were opened for It. Ibn 'Umar (RA) said: I have not abandoned them (these words) since I heard the Messenger of Allah (ﷺ) saying this."},{"id":50,"title":"Namaza Başlarken Dua","ref":"Müslim: 600","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_50.json","ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","latin":"Elhamdülillâhi hamden kesîran tayyiben mübâraken fîh","tr":"Allah'a hamd olsun; çok, güzel ve bereketli bir hamd.\n\nAllah'ın Resulü (ﷺ) namazı bitirince şöyle dedi: İçinizden kim bu sözleri söyledi? Halk sustu. O (Peygamber ﷺ yeniden) şöyle dedi: İçinizden kim bu sözleri söyledi? Hiçbir yanlış söylemedi. Sonra bir adam şöyle dedi: Ben geldim, nefes almakta güçlük çektim ve bu sözleri söyledim. O şöyle yanıtladı: On iki meleğin birbirine baktığını gördüm; hangisinin onları (Allah'a) yükselteceği için rekabet ediyorlardı.","en":"Praise is to Allah, much, good and blessed praise.\n\nWhen the Messenger of Allah (ﷺ) finished the prayer he said: Who amongst you uttered these words? The people remained silent. He (the Prophet ﷺ again said) : Who amongst you uttered these words? He said nothing wrong. Then a man said: I came and had a difficulty in breathing, so I uttered them. He replied: I saw twelve angels facing one another as to who will take them up (to Allah)."},{"id":52,"title":"Rükudan Sonra Dua (Rabbenâ Leke'l-Hamd)","ref":"Buhârî: 799","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_52.json","ar":"رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيْرًا طَيِّبًا مُبَارَكًا فِيهِ","latin":"Rabbenâ ve leke'l-hamd, hamden kesîran tayyiben mübâreken fîh","tr":"Rabbimiz! Hamd Sanadır; çok, güzel ve bereketli bir hamd.\n\nPeygamber (ﷺ) namazı tamamlayınca şöyle sordu: 'Bu sözleri kim söyledi?' Adam şöyle yanıtladı: 'Ben.' Peygamber (ﷺ) şöyle buyurdu: 'Onu ilk yazacak olanı belirlemek için otuzdan fazla meleğin yarıştığını gördüm.'","en":"Our Lord, praise is Yours, abundant, good and blessed praise.\n\nWhen the Prophet (ﷺ) completed the prayer, he asked, \"Who has said these words?\" The man replied, \"I.\" The Prophet (ﷺ) said, \"I saw over thirty angels competing to write it first.\""},{"id":54,"title":"Rükudan Sonra Dua (Rabbenâ Leke'l-Hamd)","ref":"Buhârî: 796","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_54.json","ar":"اَللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ","latin":"Allâhümme Rabbenâ ve leke'l-hamd","tr":"Allah'ım, Rabbimiz! Hamd Sanadır.\n\nBirinizin sözü meleklerin sözüyle çakışırsa geçmiş tüm günahları bağışlanır.","en":"O Allah, our Lord and to You be the praise.\n\nIf the saying of any one of you coincides with that of the angels, all his past sins will be forgiven."},{"id":55,"title":"Selamdan Önce Dua","ref":"Sahîh (Elbânî). Nesâî: 1301","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_55.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","latin":"Allâhümme innî es'elüke yâ Allah! Bi-enneke'l-Vâhidü'l-Ahad üs-Samedüllezî lem yelid ve lem yûled, ve lem yekün lehû küfüven ehad, en tağfira lî zünûbî, inneke ente'l-Ğafûrü'r-Rahîm","tr":"Allah'ım! Senden şunu istiyorum, ey Allah! Doğurmayan, doğurulmamış ve kendisine hiçbir denk ve benzeri olmayan Tek ve Benzersiz, Samed olan Sen olduğun için günahlarımı bağışla; zira Sen çok bağışlayan ve çok merhametli olansın.\n\nAllah'ın Resulü (ﷺ) şöyle buyurdu: 'O bağışlandı' — bunu üç kez söyledi.","en":"O Allah, I ask of You, O Allah, as You are the One, the Only, the Self-Sufficient Master, Who begets not nor was He begotten, and there is None equal or comparable to Him, forgive me my sins, for You are the Oft-Forgiving, Most Merciful.\n\nThe Messenger of Allah (ﷺ) said: \"He has been forgiven,\" three times."},{"id":56,"title":"Selamdan Önce Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1495","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_56.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّوْمُ","latin":"Allâhümme innî es'elüke bi-enne leke'l-hamde, lâ ilâhe illâ ente'l-Mennânü Bedî'üs-semâvâti ve'l-ard, yâ Zâ'l-Celâli ve'l-İkrâm! Yâ Hayyü yâ Kayyûm","tr":"Allah'ım! Senden sana hamd olduğunu, senden başka ibadete layık hiçbir ilah olmadığını, lütuf ve ihsan sahibi olduğunu, gökleri ve yeri yoktan var eden olduğunu vesile kılarak istiyorum; ey Celal ve İkram sahibi! Ey her daim Diri olan! Ey her şeyi ayakta tutan!\n\nPeygamber (ﷺ) şöyle buyurdu: 'Ne ile dua ettiğini biliyor musunuz?' Onlar: 'Allah (cc) ve Resulü daha iyi bilir' dediler. O (ﷺ) şöyle buyurdu: 'Canımı elinde tutan Zat'a yemin ederim ki, Allah'ı en büyük ismiyle çağırdı; bu isimle çağrıldığında icabet eder, bu isimle istenildiğinde verir.'","en":"O Allah, I ask Thee by virtue of the fact that praise is due to Thee, there is no deity but Thou, Who showest favour and beneficence, the Originator of the Heavens and the earth, O Lord of Majesty and Splendour, O Living One, O Eternal One.\n\nThe Prophet (ﷺ) said: 'Do you know what he has supplicated with?' They said: \"Allah (SWT) and His Messenger (ﷺ) know best.\"He said: 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives.'"},{"id":57,"title":"Teşehhütten Sonra Dua (Selamdan Önce Dua)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1493","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_57.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ اَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","latin":"Allâhümme innî es'elüke bi-ennî eşhedü enneke Entallahu lâ ilâhe illâ Ente'l-Ahadu's-Samedüllezî lem yelid ve lem yûled ve lem yekün lehû küfüven Ehad","tr":"Allah'ım! Senden şunu istiyorum: Senden başka ibadete layık hiçbir ilah olmayan Sen Allah olduğuna, doğurmayan, doğurulmamış ve kendisine hiçbir denk ve benzeri olmayan Tek ve Samed olan Sen olduğuna şehâdet ettiğim için (senden istiyorum).\n\nPeygamber (ﷺ) şöyle buyurdu: 'Canımı elinde tutan Zat'a yemin ederim ki, Allah'ı en büyük ismiyle çağırdı; bu isimle çağrıldığında icabet eder, bu isimle istenildiğinde verir.'","en":"O Allah, I ask You, by the fact that I bear witness that You are Allah. There is none worthy of worship but You, the Only God, Independent of creation, who was not begotten and begets not, and none is equal to Him.\n\nThe Prophet (ﷺ) said: 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives.'"},{"id":58,"title":"Abdest Sonrası Dua","ref":"Müslim: 234","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_58.json","ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","latin":"Eşhedü en lâ ilâhe illallâhu vahdehû lâ şerîke leh, ve eşhedü enne Muhammeden abdühû ve Resûlüh","tr":"Şehâdet ederim ki Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, hiçbir ortağı yoktur. Şehâdet ederim ki Muhammed (ﷺ) O'nun kulu ve Resulüdür.\n\nCennetin sekiz kapısı ona açılır; dilediği kapıdan içeri girer.","en":"I bear witness that none has the right to be worshipped but Allah alone, Who has no partner; and I bear witness that Muhammad (ﷺ) is His slave and His Messenger.\n\nThe eight gates of Paradise will be opened for him; He will enter (Paradise) through whichever door he wishes."},{"id":59,"title":"Arefe Günü Duası","ref":"Hasen (Elbânî). Tirmizî: 3585","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_59.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيءٍ قَدِيرٌ","latin":"Lâ ilâhe illallâhu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü, ve hüve alâ külli şey'in Kadîr","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, hiçbir ortağı yoktur. Mülk O'nundur, hamd O'na aittir ve O her şeye kadirdir.","en":"None has the right to be worshiped except Allah, alone, without partner. To Him belongs sovereignty and all praise and He is over all things omnipotent."},{"id":68,"title":"Gece Uyanıldığında Dua (Lâ İlâhe İllallahu Vahdehû)","ref":"Buhârî: 1154","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_68.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ‏.‏ اَلْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Lâ ilâhe illallâhu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve hüve alâ külli şey'in Kadîr. Elhamdülillâhi ve sübhânallâhi ve lâ ilâhe illallâhu vallâhu ekber ve lâ havle ve lâ kuvvete illâ billâh","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur. O tektir ve hiçbir ortağı yoktur. Mülk O'nundur ve hamd yalnız O'na aittir. O her şeye kadirdir. Hamd yalnız Allah'a aittir. Tüm yücelik Allah içindir. Allah'tan başka ibadete layık hiçbir ilah yoktur. Allah en büyüktür. Güç ve kuvvet yalnız Allah'tandır.\n\nSonra şöyle derse: 'Allah'ım! Beni bağışla.' Veya (Allah'a) dua ederse, duası kabul edilir; abdest alıp namaz kılarsa namazı da kabul edilir.","en":"None has the right to be worshipped but Allah. He is the Only One and has no partners. For Him is the Kingdom and all the praises are due for Him. He is Omnipotent. All the praises are for Allah. All the glories are for Allah. And none has the right to be worshipped but Allah, And Allah is Great And there is neither Might nor Power Except with Allah.\n\nThen says: O Allah! Forgive me. Or invokes (Allah), he will be responded to and if he performs ablution (and prays), his prayer will be accepted."},{"id":72,"title":"Yunus'un Duası (Lâ İlâhe İllâ Ente Sübhâneke)","ref":"Sahîh (Elbânî). Tirmizî: 3505","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_72.json","ar":"لَا إِلَهَ إِلَّآ أَنتَ سُبْحٰنَكَ إِنِّى كُنْتُ مِنَ الظّٰلِمِينَ","latin":"Lâ ilâhe illâ Ente sübhâneke innî küntü mine'z-zâlimîn","tr":"Senden başka ibadete layık hiçbir ilah yoktur; Seni tüm eksikliklerden tenzih ederim. Şüphesiz ben zalimlerden oldum.\n\nBir müslüman bu şekilde (Allah'a) dua ettiğinde, Allah onun duasına icabet eder.","en":"There is none worthy of worship but You, glory is to You. Surely, I was among the wrongdoers.\n\nWhenever Muslim calls (Allah) in this way, Allah responds to his call."},{"id":73,"title":"Sıkıntı ve Musibet için Dua","ref":"Müslim: 918","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_73.json","ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ اَللَّهُمَّ أْجُرْنِيْ فِي مُصِيْبَتِيْ وَأَخْلِفْ لِي خَيْرًا مِّنْهَا","latin":"İnnâ lillâhi ve innâ ileyhi râciûn, Allâhümme'-cürnî fî musîbetî ve'hlif lî hayren minhâ","tr":"Şüphesiz biz Allah'a aidiz ve şüphesiz O'na döneceğiz. Allah'ım! Bu musibetimde bana ecir ver ve bunun yerine daha hayırlısını ver.\n\nAllah ona bunun yerine daha hayırlısını verir.","en":"We are from Allah and unto Him we return. O Allah take me out of my plight and bring to me after it something better.\n\nAllah will give him something better than it in exchange."},{"id":74,"title":"Allah'ın En Büyük İsmi için Dua (İsm-i Azam)","ref":"Sahîh (Elbânî). Nesâî: 1300","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_74.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","latin":"Allâhümme innî es'elüke bi-ennî eşhedü enneke Entallahu lâ ilâhe illâ Ente'l-Ahadü's-Samedüllezî lem yelid ve lem yûled ve lem yekün lehû küfüven Ehad","tr":"Allah'ım! Senden şunu istiyorum: Senden başka ibadete layık hiçbir ilah olmayan Sen Allah olduğuna, doğurmayan, doğurulmamış ve kendisine hiçbir denk ve benzeri olmayan Tek ve Samed olan Sen olduğuna şehâdet ettiğim için (senden istiyorum).\n\nBunun üzerine Peygamber (ﷺ) şöyle buyurdu: Allah'ı en büyük ismiyle çağırdı; bu isimle istenildiğinde verir, bu isimle çağrıldığında icabet eder.","en":"O Allah, I ask You, by the fact that I bear witness that You are Allah. There is none worthy of worship but You, the Only God, Independent of creation, Who was not begotten and begets not, and none is equal to Him.\n\nThen the Prophet (ﷺ) said, You have supplicated Allah using His Greatest Name, when asked with this name He gives, and when supplicated by this name he answers."},{"id":75,"title":"Teşehhütten Sonra Dua (Allâhümme innî es'elüke)","ref":"Sahîh (Elbânî). Nesâî: 1300","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_75.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّوْمُ","latin":"Allâhümme innî es'elüke bi-enne leke'l-hamde, lâ ilâhe illâ Ente'l-Mennânü Bedî'üs-semâvâti ve'l-ard, yâ Zâ'l-Celâli ve'l-İkrâm! Yâ Hayyü yâ Kayyûm","tr":"Allah'ım! Sana hamd olduğunu, senden başka ibadete layık hiçbir ilah olmadığını, lütuf ve ihsan sahibi olduğunu, gökleri ve yeri yoktan var eden olduğunu vesile kılarak senden istiyorum; ey Celal ve İkram sahibi! Ey her daim Diri olan! Ey her şeyi ayakta tutan!\n\nBunun üzerine Peygamber (ﷺ) şöyle buyurdu: 'Ne ile dua ettiğini biliyor musunuz?' Onlar: 'Allah (cc) ve Resulü daha iyi bilir' dediler. O şöyle buyurdu: 'Canımı elinde tutan Zat'a yemin ederim ki, Allah'ı en büyük ismiyle çağırdı; bu isimle çağrıldığında icabet eder, bu isimle istenildiğinde verir.'","en":"O Allah, I ask Thee by virtue of the fact that praise is due to Thee, there is no deity but Thou, Who showest favour and beneficence, the Originator of the Heavens and the earth, O Lord of Majesty and Splendour, O Living One, O Eternal One.\n\nThen the Prophet (ﷺ) said: 'Do you know what he has supplicated with?' They said: \"Allah (SWT) and His Messenger know best.\" He said: 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives."},{"id":79,"title":"Peygamber'in (ﷺ) Okuduğu Meşru Akşam Duası","ref":"Müslim: 2723","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_79.json","ar":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، رَبِّ أَسْأَلُكَ خَيْرَ مَا فِي هَذِهِ اللَّيْلَةِ وَخَيْرَ مَا بَعْدَهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِي هَذِهِ اللَّيْلَةِ وَشَرِّ مَا بَعْدَهَا، رَبِّ أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَسُوْءِ الْكِبَرِ، رَبِّ أَعُوْذُ بِكَ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ","latin":"Amsaynâ ve amsal-mülkü lillâhi velhamdü lillâhi, lâ ilâhe illallâhu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü ve Hüve alâ külli şey'in Kadîr. Rabbi es'elüke hayra mâ fî hâzihi'l-leyleti ve hayra mâ ba'dehâ ve eûzü bike min şerri mâ fî hâzihi'l-leyleti ve şerri mâ ba'dehâ, Rabbi eûzü bike mine'l-keseli, ve sûi'l-kiberi, Rabbi eûzü bike min azâbin fî'n-nâri ve azâbin fî'l-kabr","tr":"Akşama erdik, mülk de Allah'a ait olarak akşamladı; hamd yalnız Allah'a aittir. Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, hiçbir ortağı yoktur; mülk O'nundur, hamd O'na aittir ve O her şeye kadirdir. Rabbim! Bu gecenin hayırlısını ve sonrasının hayırlısını Senden istiyorum; bu gecenin şerrinden ve sonrasının şerrinden Sana sığınıyorum. Rabbim! Tembellikten ve kötü ihtiyarlıktan Sana sığınıyorum. Rabbim! Cehennem azabından ve kabir azabından Sana sığınıyorum.\n\nAbdullah b. Mesûd (ra) şöyle demiştir: Allah'ın Resulü (ﷺ) her sabah ve akşam yukarıdaki duayı okurdu. Sabah Asbahna... diye okur, akşam ise Asbahna yerine Amsaynâ der.","en":"We have reached the evening and at this very time unto Allah, belongs all sovereignty, and all praise is for Allah. None has the right to be worshipped except Allah, alone, without any partner, to Him belong all sovereignty and praise and He is over all things omnipotent. My Lord, I ask You for the good of this night and the good of what follows it and I take refuge in You from the evil of this night and the evil of what follows it. My Lord, I take refuge in You from laziness and senility. My Lord, I take refuge in You from torment in the Fire and punishment in the grave.\n\nAbdullah ibn Masood (RA) said, the Messenger of Allah (ﷺ) recited the above-mentioned dua in every morning and evening. In the morning he recites Asba’hna.…. and in the evening he recites Amsa-aia instead of Asba’hna."},{"id":81,"title":"Akşam Duaları (Meşru Dua)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5068","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_81.json","ar":"اَللَّهُمَّ بِكَ أَمْسَيْنَا، وَبِكَ أَصْبَحْنَا، وَبِكَ نَحْيَا، وَبِكَ نَمُوتُ، وَإِلَيْكَ الْمَصِيرُ","latin":"Allâhümme bike amsaynâ, ve bike asbahnâ, ve bike nahyâ, ve bike nemûtu ve ileyke'l-masîr","tr":"Allah'ım! Seninle akşama erdik, seninle sabaha erdik, seninle yaşarız ve seninle ölürüz; dönüş de Sanadır.","en":"O Allah, by You we enter the evening and by You we enter the morning, by You we live and and by You we die, and to You is our resurrection"},{"id":83,"title":"Hidayet ve Bereket için Akşam Duası","ref":"Ebû Dâvûd 4/322, No. 5084","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_83.json","ar":"أَمْسَيْنَا وَأَمْسَا الْمُلْكُ لِلَّهِ رَبِّ الْعَالَمِينَ، اللَّهُـمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذِهِ اللَّيْلَةِ :فَتْحَهَا، وَنَصْرَهَا، وَنُورَهَا، وَبَرَكَتَهَا، وَهُدَاهَا، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا فِيهَا وَشَرِّ مَا بَعْدَهَا","latin":"Amsaynâ ve amsal-mülkü lillâhi Rabbi'l-âlemîn, Allâhümme innî es'elüke hayra hâzihi'l-leyleti, Fethahâ ve nasrahâ ve nûrahâ, ve berakatehâ, ve hüdâhâ, ve eûzü bike min şerri mâ fîhâ ve şerri mâ ba'dehâ","tr":"Akşama erdik, bu anda mülk de âlemlerin Rabbi Allah'a ait olarak akşamladı. Allah'ım! Bu gecenin hayrını, fethini, yardımını, nurunu, bereketini ve hidayetini Senden istiyorum; bu gecenin şerrinden ve sonrasının şerrinden Sana sığınıyorum.","en":"We have reached the evening and at this very time all sovereignty belongs to Allah, Lord of the worlds. O Allah, I ask You for the good of this day, its triumphs and its victories, its light and its blessings and its guidance, and I take refuge in You from the evil of this day and the evil that follows it."},{"id":85,"title":"İman için Akşam Duası (Meşru Dua)","ref":"Sahîh (Elbânî). Sahîhu'l-Câmi: 4674","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_85.json","ar":"أَمْسَيْنَا عَلَى فِطْرَةِ الْإِسْلَامِ، وَعَلَى كَلِمَةِ الْإِخْلَاصِ، وَعَلَى دِينِ نَبِيِّنَا مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَى مِلَّةِ أَبِينَا إِبْرَاهِيمَ، حَنِيفًا مُسْلِمًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ","latin":"Amsaynâ alâ fıtrati'l-İslâmi ve alâ kelimeti'l-ihlâsi, ve alâ dîni Nebiyyinâ Muhammedin, ve alâ milleti ebînâ İbrâhîme, hanîfen Müslimen ve mâ kâne mine'l-müşrikîn","tr":"İslam fıtratı üzere, ihlâs kelimesi üzere, Peygamberimiz Muhammed'in dini üzere ve müşriklerden olmayan, hanîf ve müslüman olan atamız İbrahim'in milleti üzere akşama erdik.","en":"We rise in the evening upon the fitrah of Islaam, and the word of pure faith, and upon the religion of our Prophet Muhammad and the religion of our forefather Ibraaheem, who was a Muslim and of true faith and was not of those who associate others with Allah."},{"id":86,"title":"Günahlar için Sabah ve Akşam İstiğfar Duası","ref":"Buhârî: 6307, Müslim: 2702","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_86.json","ar":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","latin":"Estaġfirullâhe ve etûbü ileyh","tr":"Allah'tan bağışlanma dilerim ve O'na tövbe ederek dönerim.","en":"I seek Allah's forgiveness and I turn to Him in repentance."},{"id":87,"title":"Sübhânallâhi ve Bihamdihî Duası (Sabah Duası)","ref":"Müslim: 2726","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_87.json","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَى نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","latin":"Sübhânallâhi ve bihamdihî, adede halkıhî, ve rıdâ nefsihî, ve zinete arşihî ve midâde kelimâtih","tr":"Allah'ı tenzih ederim ve O'nu överim; yaratıklarının sayısı kadar, Zat'ının rızası kadar, Arş'ının ağırlığı kadar ve kelimelerinin mürekkebi kadar.\n\nCüveyriye şöyle rivayet etmiştir: Allah'ın Resulü (ﷺ) sabah ibadet yerinde sabah namazı kılarken onun yanından çıktı. Kuşluk vaktinde döndüğünde hâlâ orada oturuyordu. O (kutlu Peygamber) ona şöyle dedi: 'Seni bıraktığımdan beri hep burada mısın?' O: 'Evet' dedi. Bunun üzerine Allah'ın Resulü (ﷺ) şöyle buyurdu: 'Seni bıraktıktan sonra dört kelimeyi üç kez söyledim. Bunlar sabahtan beri söylediklerinle tartılsa, onlardan ağır gelirdi.'","en":"How perfect Allah is! I praise Him by the number of His creation and His pleasure, and by the weight of His throne, and the ink of His words.\n\nJuwairiya reported that Allah's Messenger (ﷺ) came out from (her apartment) in the morning as she was busy in observing her dawn prayer in her place of worship. He came back in the forenoon and she was still sitting there. He (the Holy Prophet) said to her: You have been in the same seat since I left you. She said: Yes. Thereupon Allah's Apostle (ﷺ) said: I recited four words (above mentioned words) three times after I left you and if these are to be weighed against what you have recited since morning these would outweigh them."},{"id":88,"title":"Sabah ve Akşam Duası (Salâvat-ı İbrâhimiyye)","ref":"et-Taberânî, Sahîhu't-Terğîb ve't-Terhîb 1/273","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_88.json","ar":"اَللَّھُمَّ صَلِّ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا صَلَّیْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ، اَللَّھُمَّ بَارِكْ عَلَی مُحَمَّدٍ وَّعَلَی آلِ مُحَمَّدٍ کَمَا بَارَکْتَ عَلَی اِبْرَاھِیْمَ وَعَلَی آلِ اِبْرَاھِیْمَ اِنَّكَ حَمِیْدٌ مَّجِیْدٌ","latin":"Allâhümme salli alâ Muhammedin ve alâ âli Muhammed, kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîm, inneke Hamîdün Mecîd. Allâhümme bârik alâ Muhammedin ve alâ âli Muhammed, kemâ bârekte alâ İbrâhîme ve alâ âli İbrâhîm, inneke Hamîdün Mecîd","tr":"Allah'ım! İbrahim'e (as) ve İbrahim'in ailesine salât ettiğin gibi Muhammed'e (ﷺ) ve Muhammed'in ailesine de salât et; şüphesiz Sen Hamîd ve Mecîd'sin. Allah'ım! İbrahim'e ve İbrahim'in ailesine bereket verdiğin gibi Muhammed'e ve Muhammed'in ailesine de bereket ver; şüphesiz Sen Hamîd ve Mecîd'sin.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Sabah 10 kez, akşam 10 kez salavat okuyana Kıyamet günü şefaatim ulaşır.'","en":"O Allah, bestow Your favor on Muhammad (ﷺ) and on the family of Muhammad (ﷺ) as You have bestowed Your favor on Ibrahim (A) and on the family of Ibrahim, You are Praiseworthy, Most Glorious. O Allah, bless Muhammad and the family of Muhammad as You have blessed Ibrahim and the family of Ibrahim, You are Praiseworthy, Most Glorious.\n\nThe Prophet saw said: \"Who recites blessings upon me 10 times in the morning and 10 times in the evening will obtain my intercession on the Day of Resurrection\"."},{"id":89,"title":"Koruma için Sabah ve Akşam Duası","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5088","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_89.json","ar":"بِسْمِ اللَّهِ الَّذِيْ لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","latin":"Bismillâhillezî lâ yedurru me'a-smihî şey'ün fi'l-ardı ve lâ fi's-semâi ve Hüve's-Semî'u'l-Alîm","tr":"Adıyla birlikte yerde ve gökte hiçbir şeyin zarar veremeyeceği Allah'ın adıyla; O, her şeyi hakkıyla işitendir, bilendir.\n\nOsman (ra) şöyle dedi: Allah'ın Resulü'nün (ﷺ) şöyle buyurduğunu işittim: 'Kim üç kez: «Adıyla birlikte yerde ve gökte hiçbir şeyin zarar veremeyeceği Allah'ın adıyla; O, her şeyi hakkıyla işitendir, bilendir» derse, sabaha kadar ona ani bir bela isabet etmez. Kim bunu sabah söylerse, akşama kadar ona ani bir bela isabet etmez.'","en":"In the name of Allah with whose name nothing is harmed on earth nor in the heavens and He is The All-Seeing, The All-Knowing.\n\nUthman (RA) say: I heard the Messenger of Allah (ﷺ) say: If anyone says three times: \"In the name of Allah, when Whose name is mentioned nothing on Earth or in Heaven can cause harm, and He is the Hearer, the Knower\" he will not suffer sudden affliction till the morning, and if anyone says this in the morning, he will not suffer sudden affliction till the evening."},{"id":90,"title":"Hasbiyallâhu Duası (Sabah ve Akşam Ezkarı)","ref":"Sahîh Mevkuf (Şuayb ve Arnaut). Ebû Dâvûd: 5081","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_90.json","ar":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَاّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيْمِ","latin":"Hasbiyallâhu lâ ilâhe illâ Hüve aleyhi tevekkeltü ve Hüve Rabbü'l-arşi'l-azîm","tr":"Allah bana yeter, O'ndan başka ibadete layık hiçbir ilah yoktur; O'na tevekkül ettim ve O, yüce Arş'ın Rabbidir.\n\nEbü'd-Derdâ (ra) şöyle dedi: Kim bu duayı sabah akşam yedi kez söylerse, doğru ya da yanlış (tekrarlasa da) Allah onu kederlendiren her şey için ona yetecektir.","en":"Allah is Sufficient for me, none has the right to be worshipped except Him, upon Him I rely and He is Lord of the exalted throne.\n\nAbu al-Darda’ (RA) said: if anyone says these dua seven times morning and evening, Allah will be sufficient for him against anything which grieves him, whether he is true or false in (repeating) them."},{"id":91,"title":"Yâ Hayyü Yâ Kayyûm Tam Duası (Sabah Akşam Ezkarı)","ref":"Hasen (Elbânî). Silsiletü's-Sahîha: 227","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_91.json","ar":"يَا حَيُّ يَا قَيُّوْمُ بِرَحْمَتِكَ أَسْتَغِيْثُ أَصْلِحْ لِي شَأْنِيْ كُلَّهُ وَلَا تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ","latin":"Yâ Hayyü yâ Kayyûmü birahmetike esteġîs, aslih lî şe'nî küllehû ve lâ tekilnî ilâ nefsî tarfete ayn","tr":"Ey her daim Diri olan, ey her şeyi ayakta tutan! Rahmetinle yardım istiyorum; bütün işlerimi yoluna koy ve beni bir göz kırpması kadar bile nefsime bırakma.\n\nEnes (ra) şöyle demiştir: Allah'ın Resulü (ﷺ) Fatıma'ya (ra) şunu tavsiye etti: «Sana sabah ve akşam bu duayı yapmanı tavsiye ederim.»","en":"O Ever Living, O Self-Subsisting and Supporter of all, by Your mercy I seek assistance, rectify for me all of my affairs and do not leave me to myself, even for the blink of an eye.\n\nAnas (RA) said, The Messenger of Allah (ﷺ) told Fatima (RA) that,\"I advice you that, you should supplicate this in the morning and evening\""},{"id":92,"title":"Güçlü İman için Sabah ve Akşam Duası","ref":"Sahîh li-Ġayrihî (Şuayb el-Arnaut). Tahrîcü'l-Müsned: 23112","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_92.json","ar":"رَضِيْتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِيْنًا وَبِمُحَمَّدٍ نَبِيًّا","latin":"Radîtü billâhi Rabben, ve bi'l-İslâmi dînen, ve bi-Muhammedin Nebiyyâ","tr":"Allah'ı Rabb, İslam'ı din, Muhammed'i (ﷺ) Peygamber olarak kabullendim ve razı oldum.","en":"I am pleased with Allah as a Lord, and Islaam as a religion and Muhammad (ﷺ) as a Prophet."},{"id":93,"title":"Bağışlanma için Sabah ve Akşam Duası","ref":"Sahîh Maktû (Elbânî). Ebû Dâvûd: 4886","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_93.json","ar":"اَللَّهُمَّ إِنِّي قَدْ تَصَدَّقْتُ بِعِرْضِي عَلَى عِبَادِكَ","latin":"Allâhümme innî kad tesaddaktu bi-ırdî alâ ibâdik","tr":"Allah'ım! Şerefimi kullarına sadaka olarak bağışladım.\n\nTâbiî Abdurrahman b. Aclan veya Sahâbî Enes (ra) şöyle demiştir: Allah'ın Resulü (ﷺ) buyurdu ki: Ebû Damdam gibi olamaz mısınız? Sahâbeler sordular: Ebû Damdam kimdir? O şöyle cevap verdi: Sizden önce yaşamış bir kişidir; her sabah bu cümleyi söylerdi. Bir başka rivayette ise: Beni kınayan kişiye şerefimi bağışladım, demiştir.","en":"O Allah, I gave my honour As Charity/Sadaka to thy servants.\n\nTabi’ee ‘Abdur Ra’hman ibn Ajlaan or Sa’habi Anas (RA) Said, the Messenger of Allah (ﷺ) said that, Can't you be like Abu Damdam? Sa’habas are asked that who is Abu Damdam? he replied, is a person who lived before you. he said this sentence in every morning. In another narration in, He said, I honour him who rebuke me."},{"id":95,"title":"En Güzel Bağışlanma Duası (Seyyidü'l-İstiğfar)","ref":"Buhârî: 6306","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_95.json","ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ (لَكَ) بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","latin":"Allâhümme Ente Rabbî lâ ilâhe illâ Ente, halaktenî ve ene abdüke, ve ene alâ ahdike ve va'dike mesteta'tü, eûzü bike min şerri mâ sana'tü, ebûü leke binimi'meke aleyye, ve ebûü (leke) bizenbî feğfirlî fe-innehû lâ yeğfiru'z-zünûbe illâ Ente","tr":"Allah'ım! Sen Rabbimsin; Senden başka ibadete layık hiçbir ilah yoktur. Beni Sen yarattın ve ben Senin kulunum. Gücüm yettiğince Sana verdiğim söze ve ahdime bağlıyım. Yaptığım kötülüklerin şerrinden Sana sığınıyorum. Bana olan nimetini kabul ediyorum ve günahımı itiraf ediyorum; beni bağışla; zira günahları Senden başkası bağışlayamaz.\n\nŞeddâd b. Evs şöyle rivayet etmiştir: Peygamber (ﷺ) şöyle buyurdu: 'Allah'tan bağışlanma istemenin en üstün şekli (yukarıdaki duadır).' Peygamber (ﷺ) şöyle ekledi: 'Kim bunu gündüz tam bir imanla okur ve o gün akşam olmadan ölürse Cennet ehlinden olur; kim bunu gece tam bir imanla okur ve sabah olmadan ölürse Cennet ehlinden olur.'","en":"O Allah, You are my Lord, none has the right to be worshipped except You, You created me and I am Your servant and I abide to Your covenant and promise as best I can, I take refuge in You from the evil of which I have committed. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for verily none can forgive sin except You.\n\nNarrated Shaddad bin Aus, The Prophet (ﷺ) said: \"The most superior way of asking for forgiveness from Allah is (The dua is mentioned above). The Prophet (ﷺ) added. \"If somebody recites it during the day with firm faith in it, and dies on the same day before the evening, he will be from the people of Paradise; and if somebody recites it at night with firm faith in it, and dies before the morning, he will be from the people of Paradise.\""},{"id":96,"title":"Âyetü'l-Kürsî - Taht Ayeti (Meşru Dua)","ref":"Buhârî: 2311","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_96.json","ar":"اللَّـهُ لَا إِلَـٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَيْءٍ مِّنْ عِلْمِهِ إِلَّا بِمَا شَاءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ ۖ وَلَا يَئُودُهُ حِفْظُهُمَا ۚ وَهُوَ الْعَلِيُّ الْعَظِيمُ ﴿٢٥٥﴾","latin":"Allâhu lâ ilâhe illâ Hüve'l-Hayyü'l-Kayyûm, lâ te'huzühû sinetün ve lâ nevm, lehû mâ fi's-semâvâti ve mâ fi'l-ard, men ze'llezî yeşfeu indehû illâ bi-iznihî, ya'lemü mâ beyne eydîhim ve mâ halfehüm, ve lâ yühîtûne bi-şey'in min ilmihî illâ bimâ şâe, vesi'a kürsiyyühü's-semâvâti ve'l-ard, ve lâ yeûdühû hıfzühümâ, ve Hüve'l-Aliyyü'l-Azîm","tr":"Allah! O'ndan başka ibadete layık hiçbir ilah yoktur; O, her daim Diri ve her şeyi ayakta tutandır. O'nu ne uyuklama ne de uyku tutar. Göklerde ne var, yerde ne varsa O'nundur. O'nun izni olmaksızın katında kim şefaat edebilir? O, kulların önünde ve arkasında olanları bilir. Onlar, O'nun ilminden, O'nun dilediği kadarından başka bir şeyi kavrayamazlar. O'nun kürsüsü gökleri ve yeri kaplamıştır. Bunları korumak O'na ağır gelmez. O, çok yücedir, çok büyüktür.\n\nÜbeyy b. Ka'b (ra) şöyle rivayet etmiştir: Kim Âyetü'l-Kürsî'yi sabah okursa akşama kadar cinlerden korunur; akşam okursa sabaha kadar cinlerden korunur. Not: Kim Fecir namazından sonra bir kez okursa hem sabah okumanın hem de Fecir namazından sonra okumanın iki faziletini de alır.","en":"Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never compass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great.\n\nUbay bin Ka’ab (RA) reported that, anyone recite ayatul kursi in the morning he will be protected from Jinn till the evening and if he recite in the evening he will be protected from Jinn till the morning. Note: If anyone recite it after Fajr prayer one time then he will get both the benefits of reciting it in the morning and benefits of reciting it after Fajr prayer."},{"id":99,"title":"Kin ve Nefretten Korunma Duası","ref":"Haşr Suresi 59:10","url":"https://quran.com/59/10","ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ ﴿١٠﴾","latin":"Rabbenâ'ğfirlena ve liihvânine'llezîne sebekunâ bi'l-îmâni ve lâ tec'al fî kulûbinâ ğillen lilleziyne âmenû rabbenâ inneke raûfun rahîm","tr":"Rabbimiz! Bizi ve bizden önce iman etmiş olan kardeşlerimizi bağışla. Kalplerimizde iman edenlere karşı hiçbir kin bırakma. Rabbimiz! Şüphesiz Sen çok şefkatlisin, çok merhametlisin.","en":"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."},{"id":100,"title":"Sabah ve Akşam Duası (Sağlık Duası)","ref":"Hasen (Elbânî). Ebû Dâvûd: 5090","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_100.json","ar":"اَللَّهُمَّ عَافِنِي فِي بَدَنِي اَللَّهُمَّ عَافِنِيْ فِي سَمْعِي اَللَّهُمَّ عَافِنِيْ فِي بَصَرِي لَا إِلَهَ إِلَّا أَنْتَ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümme âfinî fî bedenî, Allâhümme âfinî fî sem'î, Allâhümme âfinî fî basarî, lâ ilâhe illâ Ente. Allâhümme innî eûzü bike mine'l-küfri, ve'l-fakri, ve eûzü bike min azâbi'l-kabr, lâ ilâhe illâ Ente","tr":"Allah'ım! Bedenime sağlık ver. Allah'ım! İşitmeme sağlık ver. Allah'ım! Görme gücüme sağlık ver. Senden başka ibadete layık hiçbir ilah yoktur. Allah'ım! Küfürden ve fakirlikten Sana sığınıyorum; kabir azabından Sana sığınıyorum. Senden başka ibadete layık hiçbir ilah yoktur.\n\nAbdurrahman b. Ebî Bekre (ra) babasına şöyle dedi: Babacığım! Her sabah dua ettiğini duyuyorum. Sabah üç kez ve akşam üç kez tekrarlıyorsun. Bunun üzerine Ebû Bekre şöyle dedi: Allah'ın Resulü'nün (ﷺ) bu sözleri dua olarak kullandığını işittim; ben de O'nun sünnetine uymayı seviyorum.","en":"O Allah, grant my body health, O Allah, grant my hearing health, O Allah, grant my sight health. None has the right to be worshipped except You. O Allah, I take refuge with You from disbelief and poverty, and I take refuge with You from the punishment of the grave. None has the right to be worshipped except You.\n\nAbdur Rahman ibn Abu Bakr (RA) said that he told his father: O my father! I hear you supplicating every morning. You repeat them three times in the morning and three times in the evening. Then Abu Bakrah said: I heard the Messenger of Allah (ﷺ) using these words as a supplication and I like to follow his practice."},{"id":101,"title":"Kötülükten Korunma için Sabah Duası","ref":"Sahîh (Elbânî). Tirmizî: 3529","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_101.json","ar":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ، رَبَّ كُلِّ شَيْءٍ وَمَلِيكَهُ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ، أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِي، وَمِنْ شَرِّ الشَّيْطَانِ وَشِرْكِهِ ، وَأَنْ أَقْتَرِفَ عَلَى نَفْسِي سُوْءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","latin":"Allâhümme Âlime'l-ğaybi ve'ş-şehâdeti fâtıra's-semâvâti ve'l-ard, Rabbe külli şey'in ve melîkeh, eşhedü en lâ ilâhe illâ Ente, eûzü bike min şerri nefsî, ve min şerri'ş-şeytâni ve şirkihî, ve en aktarife alâ nefsî sûen, ev ecürrahu ilâ müslim","tr":"Allah'ım! Görüleni ve görülmeyeni bilen, gökleri ve yeri yoktan yaratan, her şeyin Rabbi ve hükümdarı! Senden başka ibadete layık hiçbir ilah olmadığına şehâdet ederim. Nefsimin şerrinden, şeytanın şerrinden ve şirkinden ve kendime kötülük yapmaktan ya da bir müslümana bunu yapmaktan Sana sığınıyorum.\n\nEbû Bekir es-Sıddîk (ra) şöyle dedi: «Ey Allah'ın Resulü! Bana sabah ve akşam ne söyleyeceğimi öğret.» O şöyle buyurdu: «Ey Ebû Bekir, şunu söyle (yukarıdaki dua)»","en":"O Allah, Knower of the unseen and the seen, Creator of the heavens and the Earth, Lord and Sovereign of all things, I bear witness that none has the right to be worshipped except You. I take refuge in You from the evil of my soul and from the evil and shirk of the devil, and from committing wrong against my soul or bringing such upon another Muslim.\n\nAbu Bakr As-Siddiq (RA) said: “O Messenger of Allah, teach me what to say at morning and afternoon.” He said: “O Abu Bakr, say (above dua)"},{"id":102,"title":"Af ve Afiyet için Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5074","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_102.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي دِينِيْ وَدُنْيَايَ وَأَهْلِيْ، وَمَالِيْ، اَللَّهُمَّ اسْتُرْ عَوْرَاتِيْ، وَآمِنْ رَوْعَاتِيْ، اَللَّهُمَّ احْفَظْنِي مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي وَعَنْ يَمِيْنِيْ وَعَنْ شِمَالِي وَمِنْ فَوْقِيْ وَأَعُوْذُ بِعَظَمَتِكَ أَنْ أُغْتَالَ مِنْ تَحْتِيْ","latin":"Allâhümme innî es'elüke'l-afve ve'l-âfiyete fi'd-dünyâ ve'l-âhirah, Allâhümme innî es'elüke'l-afve ve'l-âfiyete fî dînî ve dünyâye ve ehlî, ve mâlî, Allâhümme'stür avrâtî, ve âmin rav'âtî, Allâhümme'hfadnî min beyni yedeyyê, ve min halfî, ve an yemînî, ve an şimâlî, ve min fevkî, ve eûzü bi-azametike en uğtâle min tahtî","tr":"Allah'ım! Dünyada ve ahirette af ve afiyet istiyorum Senden. Allah'ım! Dinim, dünyam, ailem ve malım konusunda af ve afiyet istiyorum Senden. Allah'ım! Avretimi ört, korkularımı gider. Allah'ım! Önümden, arkamdan, sağımdan, solumdan ve üstümden beni koru; yerin dibine geçirilmekten azametinle Sana sığınıyorum.\n\nAbdullah b. Ömer (ra) şöyle dedi: Allah'ın Resulü (ﷺ) akşam ve sabah bu duaları okumayı hiç ihmal etmezdi.","en":"O Allah, I ask You for pardon and well-being in this life and the next. O Allah, I ask You for pardon and well-being in my religious and worldly affairs, and my family and my wealth. O Allah, veil my weaknesses and set at ease my dismay. O Allah, preserve me from the front and from behind and on my right and on my left and from above, and I take refuge with You lest I be swallowed up by the earth.\n\nAbdullah ibn Umar (RA) Said that, The Messenger of Allah (ﷺ) never forget to utter these supplications in the evening and in the morning."},{"id":104,"title":"Böceklerden Korunma Duası (Eûzü Bikelimâtillâhi't-Tâmmâti)","ref":"Müslim: 2708, 2709","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_104.json","ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","latin":"Eûzü bikelimâtillâhi't-tâmmâti min şerri mâ halak","tr":"Allah'ın yarattığı her şeyin şerrinden Allah'ın tam ve eksiksiz kelimelerine sığınırım.\n\nEbû Hüreyre (ra) şöyle rivayet etmiştir: Bir kişi Allah'ın Resulü'ne (ﷺ) gelerek şöyle dedi: «Ey Allah'ın Resulü! Gece bir akrep tarafından sokuldum.» Bunun üzerine O şöyle buyurdu: «Akşam şu sözleri söylemiş olsaydın (yukarıdaki dua), o sana zarar vermezdi.»","en":"I take refuge in Allah's perfect words from the evil He has created.\n\nAbu Huraira (RA) reported that a person came to Allah's Messenger (ﷺ) and said:\" Allah's Messenger (ﷺ), I was stung by a scorpion during the night. Thereupon he said: Had you recited these words in the evening. (The dua is mentioned above) that would not harm you"},{"id":108,"title":"Rızık ve İlim için Sabah Duası","ref":"Sahîh (Elbânî). İbn Mâce: 925","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_108.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا طَيِّبًا، وَعَمَلًا مُتَقَبَّلًا","latin":"Allâhümme innî es'elüke ilmen nâfian, ve rızkan tayyiben, ve amelen mütekabbelen","tr":"Allah'ım! Senden faydalı ilim, temiz rızık ve makbul amel istiyorum.","en":"O Allah, I ask You for knowledge which is beneficial and sustenance which is good, and deeds which are acceptable."},{"id":109,"title":"Allâhümme İnnî Duası (Akşam Ezkarı)","ref":"Hasen (İbn Baz). Ebû Dâvûd: 5069","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_109.json","ar":"اَللَّهُمَّ إِنِّي أَمْسَيْتُ أُشْهِدُكَ، وَأُشْهِدُ حَمَلَةَ عَرْشِكَ، وَمَلَائِكَتِكَ، وَجَمِيعَ خَلْقِكَ، أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلاَّ أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","latin":"Allâhümme innî amsaytü üşhidüke ve üşhidü hameletel arşike, ve melâiketeke ve cemîa halkıke, enneke Entallahu lâ ilâhe illâ Ente vahdeke lâ şerîke lek, ve enne Muhammeden abdüke ve Resûlük","tr":"Allah'ım! Akşama erdiğimde Seni, Arş'ını taşıyanları, meleklerini ve tüm yaratıklarını şahit tutuyorum ki: Sen Allah'sın; Senden başka ibadete layık hiçbir ilah yoktur; tek başınasın, hiçbir ortağın yoktur; Muhammed ise Senin kulun ve Resulündür.\n\nSabah veya akşam bu duayı dört kez söyleyen kişiyi Allah Cehennem ateşinden azat eder.","en":"O Allah, verily I have reached evening and call on You, the bearers of Your throne, Your angels, and all of Your creation to witness that You are Allah, none has the right to be worshipped except You, alone, without any partner and that Muhammad is Your Servant and Messenger.\n\nAllah will spare whoever says this four times in the morning or evening from the Hell-fire."},{"id":110,"title":"En Güzel Zikir ve Dua (Sübhânallâhi ve Bihamdihî)","ref":"Buhârî: 6682","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_110.json","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ وَسُبْحَانَ اللَّهِ الْعَظِيْمِ","latin":"Sübhânallâhi ve bihamdihî ve sübhânallâhi'l-azîm","tr":"Allah'a hamd ile tesbih ederim; her türlü noksanlıktan münezzehtir Allah, her türlü övgü O'na aittir ve O, azamet sahibi Allah'tır.","en":"Glory be to Allah and His is the praise, (and) Allah, the Greatest is free from imperfection\n\nThe Prophet (ﷺ) said, \"(There are) two words which are dear to the Beneficent (Allah) and very light (easy) for the tongue (to say), but very heavy in weight in the balance. They are: ''Subhan Allah wa-bi hamdihi'' and ''Subhan Allah Al-`Azim.\""},{"id":111,"title":"Bağışlanma ve Rızık için Güçlü Dua","ref":"Müslim: 2697","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_111.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِيْ وَاهْدِنِيْ وَعَافِنِيْ وَارْزُقْنِيْ","latin":"Allâhümmağfirlî verhamnî vehdini ve âfinî verzüknî","tr":"Allah'ım! Beni bağışla, bana merhamet et, beni doğru yola ilet, bana sağlık ver ve bana rızık ihsan et.\n\nEbû Mâlik, babasından şöyle rivayet etmiştir: Bir kimse İslam'a girdiğinde Allah'ın Resulü (ﷺ) ona önce namazı öğretir, ardından bu sözlerle dua etmesini emrederdi.","en":"O Allah forgive me, and have mercy on me and guide me and give me good health and provide rizq for me.\n\nAbu Malik reported on the authority of his father that when a person embraced Islam, Allah's Messenger (ﷺ) used to teach him how to observe prayer and then commanded him to supplicate in these words."},{"id":112,"title":"Çarşıya Girerken Okunacak Dua (Meşru Dua)","ref":"Hasen (Elbânî). Tirmizî: 3428","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_112.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، وَهُوَ حَيٌّ لَا يَمُوتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","latin":"Lâ ilâhe illallâhu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü, yuhyî ve yümît, ve Hüve hayyün lâ yemût, biyedihil-hayr, ve Hüve alâ külli şey'in Kadîr","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O Bir'dir, ortağı yoktur. Mülk O'nundur, hamd O'na aittir. O diriltir ve öldürür; O diridir ve ölmez. Hayır O'nun elindedir ve O her şeye kadirdir.\n\nÖmer b. Hattâb (ra) şöyle rivayet etmiştir: Allah'ın Resulü (ﷺ) buyurdu ki: «Çarşıya girip bu sözleri söyleyen kişi için Allah bir milyon iyilik yazar, bir milyon kötülüğünü siler, derecesini bir milyon yükseltir ve cennette ona bir köşk inşa eder.»","en":"None has the right to be worshiped but Allah alone, with no partner, to Him belongs all sovereignty and to Him is the praise, He gives life and gives death, and He is Ever-Living and does not die; in His Hand is all goodness and He is Able to do all things.\n\nUmar ibn al-Khattab (RA) said that the Messenger of Allah (ﷺ) said: “Whoever enters the marketplace and says these words, Allah shall record a million good deeds for him, wipe a million evil deeds away from him, raise a million ranks for him and build a palace in Jannah for him.”"},{"id":113,"title":"Korunma için Kehf Suresi'nin İlk 10 Ayeti","ref":"Müslim: 809","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_113.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ اَلْحَمْدُ لِلَّـهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَل لَّهُ عِوَجًا ۜ ﴿١﴾ قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا ﴿٢﴾ مَّاكِثِينَ فِيهِ أَبَدًا ﴿٣﴾ وَيُنذِرَ الَّذِينَ قَالُوا اتَّخَذَ اللَّـهُ وَلَدًا ﴿٤﴾ مَّا لَهُم بِهِ مِنْ عِلْمٍ وَلَا لِآبَائِهِمْ ۚ كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَاهِهِمْ ۚ إِن يَقُولُونَ إِلَّا كَذِبًا ﴿٥﴾ فَلَعَلَّكَ بَاخِعٌ نَّفْسَكَ عَلَىٰ آثَارِهِمْ إِن لَّمْ يُؤْمِنُوا بِهَـٰذَا الْحَدِيثِ أَسَفًا ﴿٦﴾ إِنَّا جَعَلْنَا مَا عَلَى الْأَرْضِ زِينَةً لَّهَا لِنَبْلُوَهُمْ أَيُّهُمْ أَحْسَنُ عَمَلًا ﴿٧﴾ وَإِنَّا لَجَاعِلُونَ مَا عَلَيْهَا صَعِيدًا جُرُزًا ﴿٨﴾ أَمْ حَسِبْتَ أَنَّ أَصْحَابَ الْكَهْفِ وَالرَّقِيمِ كَانُوا مِنْ آيَاتِنَا عَجَبًا ﴿٩﴾ إِذْ أَوَى الْفِتْيَةُ إِلَى الْكَهْفِ فَقَالُوا رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا ﴿١٠﴾","latin":"Bismillâhirrahmânirrahîm. Elhamdü lillâhillezî enzele alâ abdihil-kitâbe ve lem yec'al lehû ivecâ. Kayyimen liyünzire be'sen şedîdem-milledünhü ve yübeşşiral-mü'minînel-lezîne ya'melûnes-sâlihâti enne lehüm ecren hasenâ. Mâkisîne fîhi ebedâ. Ve yünzirel-lezîne kâlüttehazallâhü veledâ. Mâ lehüm bihî min ilmin ve lâ li-âbâihim; kebürat kelimeten tahrucu min efvâhihim; in yekûlûne illâ kezibâ. Fela'alleke bâhi'un-nefseke alâ âsârihim in lem yü'minû bihâzel-hadîsi esefâ. İnnâ ce'alnâ mâ alel-ardi zînetellehâ lineblevehüm eyyühüm ahsenü amelâ. Ve innâ lecâilûne mâ aleyhâ saîden curüzâ. Em hasibte enne ashâbel-kehfi ver-rakîmi kânû min âyâtinâ aceben. İz evel-fityetü ilel-kehfi fekâlû Rabbenâ âtinâ mil-ledünke rahmeten ve hayyi' lenâ min emrinâ reşedâ.","tr":"(1) Hamd, kulu üzerine Kitabı indiren ve onda hiçbir eğrilik bırakmayan Allah'a aittir. (2) Allah katından gelecek şiddetli azabı uyarmak ve iyi ameller işleyen müminlere güzel bir mükâfat olduğunu müjdelemek için (indirdi). (3) Onlar orada ebediyen kalacaklardır. (4) Ve «Allah çocuk edindi» diyenleri uyarmak için (indirdi). (5) Bunun hakkında ne onların ne de babalarının bilgisi vardır. Ağızlarından çıkan söz ne büyük! Onlar sadece yalan söylüyorlar. (6) Demek sen, bu söze inanmazlarsa arkalarından üzülerek kendini helak edeceksin! (7) Şüphesiz biz, yeryüzündeki her şeyi, onları hangisinin daha güzel iş yapacağını denemek için bir süs yaptık. (8) Biz gerçekten yeryüzündeki her şeyi kupkuru bir toprak yapacağız. (9) Yoksa sen Ashâbu'l-Kehf ve Rakîm'in ayetlerimiz arasında bir şey olmadığını mı sandın? (10) Hani gençler mağaraya sığınıp demişlerdi ki: «Rabbimiz! Bize katından bir rahmet ver, bize şu durumumuzda doğru yolu kolaylaştır.» (Kehf Suresi: 1-10)\n\nPeygamber (ﷺ) buyurdu ki: «Kehf Suresi'nin ilk on ayetini ezberleyen kimse Deccal'den korunur.»","en":"(1) [All] praise is [due] to Allah, who has sent down upon His Servant the Book and has not made therein any deviance. (2) [He has made it] straight, to warn of severe punishment from Him and to give good tidings to the believers who do righteous deeds that they will have a good reward (3) In which they will remain forever (4) And to warn those who say, \" Allah has taken a son.\" (5) They have no knowledge of it, nor had their fathers. Grave is the word that comes out of their mouths; they speak not except a lie. (6) Then perhaps you would kill yourself through grief over them, [O Muhammad], if they do not believe in this message, [and] out of sorrow. (7) Indeed, We have made that which is on the earth adornment for it that We may test them [as to] which of them is best in deed. (8) And indeed, We will make that which is upon it [into] a barren ground. (9) Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder? (10) [Mention] when the youths retreated to the cave and said, \"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance. (Sura Kahf: 1-10)\n\nThe Prophet (ﷺ) said, \"If anyone learns by heart the first ten verses of the Surah al-Kahf, he will be protected from the Dajjal.\""},{"id":114,"title":"Nazar ve Cinden Korunma Duası","ref":"Buhârî: 3371","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_114.json","ar":"أُعِيذُكُمَا [أَعُوْذُ] بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ","latin":"Üîzüküma (Kendisi için: Eûzü) bi kelimâtillâhit-tâmmeti min külli şeytânin ve hâmmetin ve min külli aynin lâmmetin","tr":"Sizi her şeytandan, her zararlı canlıdan ve her kötü gözden Allah'ın eksiksiz kelimelerine sığındırıyorum.\n\nPeygamber (ﷺ) Hasan ve Hüseyin için Allah'a sığınır ve şöyle derdi: «Dedeniz İbrahim, İsmail ve İshak için şu sözlerle Allah'a sığınırdı.»","en":"I commend you to the protection of Allah’s perfect words from every devil, vermin, and every evil eye.\n\nThe Prophet (ﷺ) used to seek Refuge with Allah for Al-Hasan and Al-Husain and say: \"Your forefather (i.e. Abraham) used to seek Refuge with Allah for Ishmael and Isaac by reciting.\""},{"id":116,"title":"Uyumadan Önce Dua (Ayete'l-Kürsî)","ref":"Buhârî, Fethü'l-Bârî 4/487, no. 2311","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_116.json","ar":"اَللَّهُ لَآ إِلٰهَ إِلَّا هُوَ الْحَىُّ الْقَيُّومُ ۚ لَا تَأْخُذُهُۥ سِنَةٌ وَلَا نَوْمٌ ۚ لَّهُۥ مَا فِى السَّمٰوٰتِ وَمَا فِى الْأَرْضِ ۗ مَنْ ذَا الَّذِى يَشْفَعُ عِنْدَهُۥٓ إِلَّا بِإِذْنِهِۦ ۚ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ ۖ وَلَا يُحِيطُونَ بِشَىْءٍ مِّنْ عِلْمِهِۦٓ إِلَّا بِمَا شَآءَ ۚ وَسِعَ كُرْسِيُّهُ السَّمٰوٰتِ وَالْأَرْضَ ۖ وَلَا يَـُٔودُهُۥ حِفْظُهُمَا ۚ وَهُوَ الْعَلِىُّ الْعَظِيمُ","latin":"Allâhü lâ ilâhe illâ Hüve'l-Hayyü'l-Kayyûm, lâ te'huzühü sinetün ve lâ nevm, lehû mâ fis-semâvâti ve mâ fil-ard, men zellezî yeşfe'u indehû illâ bi-iznihî, ya'lemü mâ beyne eydîhim ve mâ halfehüm, ve lâ yühîtûne bi-şey'im-min ilmihî illâ bimâ şâ', vesi'a kürsiyyühüs-semâvâti vel-ard, ve lâ yeûdühü hıfzuhumâ, ve Hüve'l-Aliyyü'l-Azîm","tr":"Allah! O'ndan başka ibadete layık hiçbir ilah yoktur. O, daima diri ve her şeyi ayakta tutandır. Ne uyuklama ne de uyku O'nu yakalayamaz. Göklerde ve yerde ne varsa hepsi O'nundur. O'nun izni olmadan O'nun katında kim şefaat edebilir? O, önlerindekini ve arkalarındakini bilir; O'nun ilminden hiçbir şeyi kavrayamazlar, ancak O'nun dilediği kadarını (kavrayabilirler). O'nun kürsüsü gökleri ve yeri kuşatmıştır. Onları koruyup gözetmek O'na ağır gelmez. O, Yücedir, Büyüktür. (Bakara Suresi 2:255)\n\nYatmak için uzandığında Ayete'l-Kürsî'yi okuyan kişinin yanında Allah'tan bir koruyucu kalır ve sabah olana kadar şeytan ona yaklaşamaz.","en":"Allah! There is none worthy of worship but He, the Ever Living, the One Who sustains and protects all that exists. Neither slumber nor sleep overtakes Him. To Him belongs whatever is in the heavens and whatever is on the earth. Who is he that can intercede with Him except with His Permission? He knows what happens to them in this world, and what will happen to them in the Hereafter. And they will never compass anything of His Knowledge except that which He wills. His Throne extends over the heavens and the earth, and He feels no fatigue in guarding and preserving them. And He is the Most High, the Most Great. (Sura Baqarah 2:255)\n\nWhoever reads Ayatul Kursi when he lies down to sleep will have a guardian from Allah remain with him and Satan will not be able to come near him until he rises in the morning."},{"id":117,"title":"Uyumadan Önce Dua (Bakara Suresi Son İki Ayet)","ref":"Buhârî, Fethü'l-Bârî 9/94, Müslim 1/554, no. 807","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_117.json","ar":"آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّـهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ اللَّـهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾","latin":"(285) Âmener-Resûlü bimâ ünzile ileyhi mir-Rabbihî vel-mü'minûn, küllün âmene billâhi ve melâiketihî ve kütübihî ve Rusülih, lâ nüferrikü beyne ehadin mir-Rusülih, ve kâlû semi'nâ ve eta'nâ ğufrâneke Rabbenâ ve ileyke'l-masîr. (286) Lâ yükellifulllâhü nefsen illâ vüs'ahâ, lehâ mâ kesebet ve aleyhâ mektesebat, Rabbenâ lâ tü'âhiznâ in-nesînâ ev ahta'nâ, Rabbenâ ve lâ tahmil aleynâ isran kemâ hameltehû alellezîne min kablinâ, Rabbenâ ve lâ tühammilenâ mâ lâ tâkate lenâ bih, va'fü annâ, vağfirlena verhamnâ, Ente Mevlânâ fensurnâ alel-kavmil-kâfirîn","tr":"(285) Peygamber, Rabbi tarafından kendisine indirilene iman etti, müminler de iman etti. Her biri; Allah'a, meleklerine, kitaplarına ve peygamberlerine iman etti. «O'nun peygamberleri arasında hiçbir ayrım yapmayız» dediler. «İşittik ve itaat ettik. Bağışlamanı dileriz Rabbimiz, dönüş yalnızca Sanadır» dediler. (286) Allah her şahsı yalnızca gücü yettiği kadarıyla yükümlü kılar. Kazandığı iyilik kendi yararına, işlediği kötülük de kendi zararınadır. «Rabbimiz! Unuttuğumuz ya da yanıldığımız şeyler sebebiyle bizi sorumlu tutma. Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yük yükleme. Rabbimiz! Güç yetiremeyeceğimiz şeyleri bize taşıtma. Bizi affet, bizi bağışla, bize acı. Sen bizim Mevlâmızsın. Kâfirler topluluğuna karşı bize yardım et.» (Bakara Suresi 2: 285-286)\n\nGece Bakara Suresi'nin son iki ayetini okuyan kişiye bu iki ayet yeter.","en":"(285) The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination. (286) Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people. (Sura Baqarah 2: 285-286)\n\nWhoever recites the last two Aayahs of Soorah al-Baqarah at night, those two Aayahs shall be sufficient for him."},{"id":118,"title":"Yatmadan Önce Dua (Kâfirûn Suresi)","ref":"Sahîh (Elbânî). Tirmizî: 3403","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_118.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ يَا أَيُّهَا الْكَافِرُونَ ﴿١﴾ لَا أَعْبُدُ مَا تَعْبُدُونَ ﴿٢﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٣﴾ وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ ﴿٤﴾ وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ ﴿٥﴾ لَكُمْ دِينُكُمْ وَلِيَ دِينِ ﴿٦﴾","latin":"Bismillâhirrahmânirrahîm (1) Kul yâ eyyühe'l-kâfirûn (2) Lâ a'büdü mâ ta'büdûn (3) Ve lâ entüm âbidûne mâ a'büd (4) Ve lâ ene âbidün mâ abedtüm (5) Ve lâ entüm âbidûne mâ a'büd (6) Leküm dînüküm ve liye dîn","tr":"(1) De ki: «Ey kâfirler! (2) Ben sizin taptıklarınıza tapmam. (3) Siz de benim taptığıma tapanlar değilsiniz. (4) Ben de sizin taptıklarınıza tapacak değilim. (5) Siz de benim taptığıma tapanlar değilsiniz. (6) Sizin dininiz size, benim dinim bana.» (Kâfirûn Suresi 109: 1-6)\n\nNevfel el-Eşca'î (ra) şöyle dedi: Allah'ın Resulü (ﷺ) bana şöyle buyurdu: «Kâfirûn Suresi'ni okuyarak uyu; bu seni şirkten kurtarır.»","en":"(1) Say, \"O disbelievers, (2) I do not worship what you worship. (3) Nor are you worshippers of what I worship. (4) Nor will I be a worshipper of what you worship. (5) Nor will you be worshippers of what I worship. (6) For you is your religion, and for me is my religion.\" (Sura kafirun 109: 1-6)\n\nNawfal Al-Ashzai (RA) said, the Messenger of Allah (ﷺ) told me, you will sleep after reciting Surah Kafirun, this will liberate you from shirk."},{"id":122,"title":"Uyku Duası","ref":"Buhârî: 6314","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_122.json","ar":"اَللَّهُمَّ بِاسْمِكَ أَمُوْتُ وَأَحْيَا","latin":"Allâhümme bismike emûtü ve ahyâ","tr":"Allah'ım! Senin adınla ölür ve yaşarım.","en":"O Allah, in Your Name I die and I live."},{"id":123,"title":"Uyumadan Önce Dua","ref":"Buhârî, Fethü'l-Bârî 11/113 no. 6324, Müslim 4/2083 no. 2711","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_123.json","ar":"بِاسْمِكَ اَللَّهُمَّ أَمُوْتُ وَأَحْيَا","latin":"Bismike Allâhümme emûtü ve ahyâ","tr":"Senin adınla ey Allah'ım, yaşar ve ölürüm.\n\nHuzeyfe (ra) şöyle dedi: «Allah'ın Resulü (ﷺ) uyumak istediğinde bu zikri okurdu.»","en":"In Your name O Allah, I live and die.\n\nHudhayfah (RA) said, \"If the Messenger of Allah (ﷺ) intended to sleep, he would recite this dhikr.”"},{"id":124,"title":"Uyumaya Giderken Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5058","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_124.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِى كَفَانِى وَآوَانِى وَأَطْعَمَنِى وَسَقَانِى وَالَّذِى مَنَّ عَلَىَّ فَأَفْضَلَ وَالَّذِى أَعْطَانِى فَأَجْزَلَ اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ، اَللَّهُمَّ رَبَّ كُلِّ شَىْءٍ وَمَلِيْكَهُ وَإِلَهَ كُلِّ شَىْءٍ أَعُوْذُ بِكَ مِنَ النَّارِ","latin":"Elhamdü lillâhillezî kefânî ve âvânî ve et'amenî ve sekânî vellezî menne aleyye fe-efdele vellezî a'tânî fe-eczelel hamdü lillâhi alâ külli hâl, Allâhümme rabbe külli şey'in ve melikeh ve ilâhe külli şey'in eûzü bike mine'n-nâr","tr":"Bana yeterliliği veren, beni barındıran, beni yediren ve içiren, üzerime lutfedip en güzel lütufta bulunan ve bana en bol ikramda bulunan Allah'a hamd olsun. Her halimde Allah'a hamd olsun. Allah'ım! Her şeyin Rabbi, her şeyin sahibi, her şeyin ilahı! Sana cehennemden sığınıyorum.","en":"Praise be to Allah Who has given me sufficiency, has guarded me, given me food and drink, been most gracious to me, and given to me most lavishly. Praise be to Allah in every circumstance. O Allah! Lord and King of everything, God of everything, I seek refuge in Thee from Hell."},{"id":125,"title":"Uyumak için Dua","ref":"Müslim: 2712","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_125.json","ar":"اَللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ","latin":"Allâhümme inneke halakte nefsî ve Ente teveffâhâ, leke memâtühâ ve mahyâhâ, in ahyeytehâ fahfazhâ, ve in emettehâ fağfirlehâ. Allâhümme innî es'elüke'l-âfiyeh","tr":"Allah'ım! Şüphesiz Sen nefsimi yarattın ve onu alacak olan da Sensin. Ölümü de hayatı da Sana aittir. Eğer onu yaşatırsan koru onu; eğer ölümünü dilersen onu bağışla. Allah'ım! Senden afiyet diliyorum.","en":"O Allah, verily You have created my soul and You shall take it's life, to You belong it's life and death. If You keep my soul alive then protect it, and if You take it's life then forgive it. O Allah, I ask You to grant me good health."},{"id":126,"title":"Uyumadan Önce Okunacak Dua","ref":"Müslim: 2713","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_126.json","ar":"اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","latin":"Allâhümme Entel-Evvelü felâ şey'e kableke, ve Entel-Âhiru felâ şey'e ba'deke, ve Entez-Zâhiru felâ şey'e fevkake, ve Entel-Bâtınü felâ şey'e dûneke, ikdi anned-deyne ve ağninâ mine'l-fakr","tr":"Allah'ım! Sen Evvel'sin, Senden önce hiçbir şey yoktur; Sen Âhir'sin, Senden sonra hiçbir şey yoktur; Sen Zâhir'sin, Senden üstün hiçbir şey yoktur; Sen Bâtın'sın, Senden daha yakın hiçbir şey yoktur. Borçlarımızı üzerimizden kaldır ve bizi fakirlikten koru.","en":"O Allah You are the First and nothing has come before you, and You are the Last, and nothing may come after You. You are the Most High, nothing is above You and You are the Most Near and nothing is nearer than You. Remove our debts from us and enrich us against poverty."},{"id":127,"title":"Uyumadan Önce Okunacak Dua","ref":"Müslim: 2713, Sahîh (Elbânî). Tirmizî: 3481","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_127.json","ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","latin":"Allâhümme Rabbes-semâvâtis-seb'i ve Rabbel-ard, ve Rabbel-Arşil-Azîm, Rabbenâ ve Rabbe külli şey'in, fâlikıl-habbi ven-nevâ, ve münzilat-Tevrâti vel-İncîl, vel-Furkân, eûzü bike min şerri külli şey'in Ente âhizün binâsiyetih. Allâhümme Entel-Evvelü felâ şey'e kableke, ve Entel-Âhiru felâ şey'e ba'deke, ve Entez-Zâhiru felâ şey'e fevkake, ve Entel-Bâtınü felâ şey'e dûneke, ikdi anned-deyne ve ağninâ mine'l-fakr","tr":"Allah'ım! Yedi göğün Rabbi, yerin Rabbi ve büyük Arş'ın Rabbi; Rabbimiz ve her şeyin Rabbi; tanecikleri ve çekirdekleri çatlatan; Tevrat'ı, İncil'i ve Furkan'ı indiren! Alnından tuttuğun her şeyin şerrinden Sana sığınıyorum. Allah'ım! Sen Evvel'sin, Senden önce hiçbir şey yoktur; Sen Âhir'sin, Senden sonra hiçbir şey yoktur; Sen Zâhir'sin, Senden üstün hiçbir şey yoktur; Sen Bâtın'sın, Senden daha yakın hiçbir şey yoktur. Borçlarımızı üzerimizden kaldır ve bizi fakirlikten koru.\n\nEbû Hüreyre (ra) şöyle rivayet etmiştir: Allah'ın Resulü (ﷺ) bize yatağa gittiğimizde bu sözleri söylememizi emrederdi. Başka bir rivayette ise Fâtıma (ra) ondan bir hizmetçi istediğinde bu duayı öğrettiği belirtilmektedir.","en":"O Allah, Lord of the seven heavens and the Lord of the Earth and Lord of the Magnificent Throne, our Lord and Lord of all things, Splitter of the seed and the date stone, Revealer of the Towraat, the Injeel and the Furqaan, I take refuge in You from the evil of all things You shall seize by the forelock. O Allah, You are The First so there is nothing before You and You are The Last so there is nothing after You. You are ath-Dhaahir so there is nothing above You and You are al-Baatin so there is nothing closer than You. Settle our debt for us and spare us from poverty.\n\nAbu Huraira (RA) reported that Allah's Messenger (ﷺ) used to command us that as we go to our bed, we should utter the words (as mentioned above). In another narration, he said that when Fatima (RA) asked him for a khadima, he then taught the dua."},{"id":128,"title":"Uyku Duası","ref":"Hasen (Elbânî). Tirmizî: 3528","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_128.json","ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ (التَّامَّاتِ) مِنْ غَضَبِهِ وَعِقَابِهِ وَ(مِنْ) شَرِّ عِبَادِهِ وَمِنْ هَمَزَاتِ الشَّيَاطِيْنِ وَأَنْ يَحْضُرُوْنِ","latin":"Eûzü bi-kelimâtillâhit-tâmmeti min ğadobihî ve ikâbihî, ve (min) şerri ibâdihî, ve min hemezâtiş-şeyâtîni ve en yahdurûn","tr":"Allah'ın eksiksiz kelimelerine, O'nun gazabından ve azabından, kullarının şerrinden, şeytanların vesveselerinden ve huzuruma gelmelerinden sığınıyorum.","en":"I seek refuge in the Perfect Words of Allah from His anger and His punishment, from the evil of His slaves and from the taunts of devils and from their presence."},{"id":129,"title":"Uyku Duası","ref":"Buhârî 11/126 no. 6320, Müslim 4/2084 no. 2714","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_129.json","ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، فَإِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا، بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ","latin":"Bismike Rabbî vada'tü cenbî, ve bike erfe'ühû, fe-in emsekkete nefsî ferhamhâ, ve in erseltehâ fahfazha, bimâ tahfazü bihî ibâdekessâlihîn","tr":"Rabbim! Senin adınla yanımı yere koydum ve Senin adınla kaldırıyorum. Eğer nefsimi alırsan ona merhamet et; eğer geri gönderirsen, onu salih kullarını koruduğun şekilde koru.\n\nEbû Hüreyre (ra) şöyle rivayet etmiştir: Peygamber (ﷺ) buyurdu ki: «Biriniz yatağa gittiğinde izarının iç yüzüyle yatağını silksin; zira yatakta arkasından ne geldiğini bilmez. Sonra şunu söylesin: (Yukarıdaki dua)»","en":"In Your name my Lord, I lie down and in Your name I rise, so if You should take my soul then have mercy upon it, and if You should return my soul then protect it in the manner You do so with Your righteous servants.\n\nNarrated by Abu Huraira (RA): The Prophet (ﷺ) said, When anyone of you go to bed, he should shake out his bed with the inside of his waist sheet, for he does not know what has come on to it after him, and then he should say: (The dua is mentioned above)"},{"id":130,"title":"Yatmadan Önce Dua","ref":"Sahîh (Elbânî). Tirmizî: 3398","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_130.json","ar":"اَللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ","latin":"Allâhümme kinî azâbeke yevme teb'asü ibâdek","tr":"Allah'ım! Kullarını dirilttiğin günde beni azabından koru.","en":"O Allah, protect me from Your punishment on the day Your servants are resurrected."},{"id":131,"title":"Uyku Duası","ref":"Hasen (Şuayb el-Arnaût). Müsned Ahmed: 6620","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_131.json","ar":"بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِيْ فَاغْفِرْ لِي ذَنْبِيْ","latin":"Bismike Rabbî vada'tü cenbî, fağfirlî cenbî","tr":"Rabbim! Senin adınla yanımı yere koydum; günahımı bağışla.\n\nAbdullah b. Amr (ra) Peygamber'in (ﷺ) yatağa uzanacağında bu duayı söylediğini rivayet etmiştir.","en":"O my Lord, I have slept in your name. You forgive my sins.\n\nAbdullah Ibn Amr (RA) said that the Prophet (ﷺ) used to say the above dua when he was lying in bed to sleep."},{"id":132,"title":"Uyku Duası","ref":"Müslim 4/2085 no. 2715","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_132.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ","latin":"Elhamdü lillâhillezî et'amenâ ve sekânâ, ve kefânâ, ve âvânâ, fekam mimmen lâ kâfiye lehû ve lâ mü'viye","tr":"Bizi yediren, içiren, bize yeten ve bizi barındıran Allah'a hamd olsun; ne kadar çok kimse vardır ki onlara yeten de yoktur barındıran da.\n\nEnes (ra) şöyle dedi: Allah'ın Resulü (ﷺ) yatağa uzandığında bu duayı söylerdi.","en":"All praise is for Allah, Who fed us and gave us drink, and Who is sufficient for us and has sheltered us, for how many have none to suffice them or shelter them.\n\nAnas (RA) said, Rasulullah (ﷺ) used to say this dua when he was lying in bed."},{"id":133,"title":"Uyumadan Önce Dualar","ref":"Sahîh (Elbânî). Tirmizî: 3392","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_133.json","ar":"اَللَّهُمَّ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ رَبَّ كُلِّ شَيْءٍ وَمَلِيْكَهُ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَمِنْ شَرِّ الشَّيْطَانِ وَ شِرْكِهِ وَأَنْ أَقْتَرِفَ عَلَى نَفْسِيْ سُوءًا، أَوْ أَجُرَّهُ إِلَى مُسْلِمٍ","latin":"Allâhümme Âlime'l-ğaybi ve'ş-şehâdeti fâtires-semâvâti vel-ard, Rabbe külli şey'in ve melîkeh, eşhedü en lâ ilâhe illâ Ente, eûzü bike min şerri nefsî, ve min şerriş-şeytâni ve şirkihî, ve en aktarife alâ nefsî sûen, ev ecürrahu ilâ Müslim","tr":"Allah'ım! Görüleni ve görülmeyeni bilen, gökleri ve yeri yaratan, her şeyin Rabbi ve hükümdarı! Senden başka ibadete layık hiçbir ilah olmadığına şahâdet ederim. Nefsimin şerrinden, şeytanın şerrinden ve şirkinden, kendime kötülük yapmaktan ya da bunu bir müslümana yapmaktan Sana sığınıyorum.\n\nPeygamber (ﷺ) bu duanın sabah, akşam ve yatmadan önce okunmasını öğretti.","en":"O Allah, Knower of the seen and the unseen, Creator of the heavens and the earth, Lord and Sovereign of all things I bear witness that none has the right to be worshipped except You. I take refuge in You from the evil of my soul and from the evil and shirk of the devil, and from committing wrong against my soul or bringing such upon another Muslim.\n\nThe Prophet (ﷺ) taught this dua to be recited in the morning, evening and after bed."},{"id":134,"title":"Uyku Öncesi Dualar","ref":"Sahîh (Arnaût). Ahmed: 15499","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_134.json","ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ مِنْ شَرِّ مَا خَلَقَ، وبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ","latin":"Eûzü bi-kelimâtillâhit-tâmmâtilleti lâ yücâvizühünne berrun ve lâ fâcirun, min şerri mâ haleka ve berâe ve zerâe, ve min şerri mâ yenzilü mines-semâi ve min şerri mâ ya'rucü fîhâ, ve min şerri mâ zerâe fil-ard, ve min şerri mâ yahrucu minhâ, ve min şerri fiteni'l-leyli ven-nehâr, ve min şerri külli târikin illâ târikaŋ yatrucu bi-hayrin yâ Rahmân","tr":"Hiçbir iyinin ve kötünün geçemeyeceği Allah'ın eksiksiz kelimelerine, yarattığı, var ettiği ve yaydığı şeylerin şerrinden, gökten inenin şerrinden, göğe çıkanın şerrinden, yeryüzünde yayılanın şerrinden, yerden çıkanın şerrinden, gece ve gündüzün fitnesinin şerrinden ve hayırla gelen hariç gece gelen her şeyin şerrinden sığınıyorum. Ey Rahman!\n\nAbdurrahman b. Hanbel (ra) şöyle dedi: «Bir gece çölde cin şeytanları Peygamber'e (ﷺ) ateşle saldırmaya yöneldi. Bunun üzerine Cibrîl (as) geldi ve bu duayı öğretti. Dua okunur okunmaz şeytanların ateşi söndü ve kaçtılar.»","en":"I seek refuge in the perfect words of Allah, which no virtuous person or sinner can overcome, from the evil of what He has created, created and spread, from the evil of that which descends from heaven, from the evil of that which ascends to heaven. From the evil of whatever is scattered in the earth, from the evil of whatever comes out of the earth, from the evil of the fitnah of night and day, and from the evil of all strangers, except the one who comes with goodness, O Most Merciful.\n\nAbdur Rahman Ibn Khanbash (RA) said, \"One night the devil jinn came forward to attack the Prophet (ﷺ) in the desert with fire. Then Jibriel (As) came and taught him this dua. As soon as the dua is recited, the fire of the devils is extinguished and they flee.”"},{"id":135,"title":"Yatmadan Önce Dualar","ref":"Sahîh (Elbânî). Sünen Ebû Dâvûd: 5054","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_135.json","ar":"بِسْمِ اللَّهِ وَضَعْتُ جَنْبِى اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَأَخْسِئْ شَيْطَانِيْ وَفُكَّ رِهَانِيْ وَاجْعَلْنِيْ فِي النَّدِىِّ الْأَعْلَى","latin":"Bismillâhi veda'tü cenbî, Allâhümme'ğfirlî zenbî ve ahsi' şeytânî ve fükke rihânî vec'alnî fi'n-nediyyil-a'lâ","tr":"Allah'ın adıyla yanımı yere koydum. Allah'ım! Günahımı bağışla, şeytanımı kov, beni yükümlülükten kurtar ve beni en yüce mecliste bulundur.\n\nEbu'l-Ezher el-Anmârî (ra) şöyle dedi: Peygamber (ﷺ) gece yatağına uzandığında bu sözleri söylerdi.","en":"In the name of Allah, I have laid down my side for Allah. O Allah! forgive my sin, drive away my devil, free me from my responsibility, and place me in the highest assembly.\n\nAbul Azhar Anmari (RA) said that the Prophet (ﷺ) used to say these words when he was lying in bed at night."},{"id":136,"title":"Yatmadan Önce Dua","ref":"Buhârî, Fethü'l-Bârî 11/113 no. 6313, Müslim 4/2081 no. 2710","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_136.json","ar":"اَللَّهُمَّ أَسْلَمْتُ نَفْسِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَوَجَّهْتُ وَجْهِيْ إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ","latin":"Allâhümme eslemtü nefsî ileyke, ve fevveztü emrî ileyke, ve vecceh-tü vechî ileyke, ve elce'tü zahrî ileyke, rağbeten ve rahbeten ileyke, lâ melcee ve lâ mencâ minke illâ ileyke, âmentü bi-kitâbikellegî enzelte ve bi-nebiyyikellegî erselte","tr":"Allah'ım! Nefsimi Sana teslim ettim, işimi Sana havale ettim, yüzümü Sana çevirdim ve ümit ve korku ile sırtımı Sana yasladım. Senden kaçacak sığınak ve kurtuluş yoktur; ancak Sena sığınmak vardır. İndirdiğin Kitabına ve gönderdiğin Nebine iman ettim.\n\nPeygamber (ﷺ) bu duayı öğrettiği kişiye şöyle buyurdu: «O gece ölürsen, fıtrat üzere yani İslam dini üzere ölmüş olursun.»","en":"O Allah, I submit my soul unto You, and I entrust my affair unto You, and I turn my face towards You, and I totally rely on You, in hope and fear of You. Verily there is no refuge nor safe haven from You except with You. I believe in Your Book which You have revealed and in Your Prophet whom You have sent.\n\nThe Prophet (ﷺ) said to the person to whom he taught this Dua: If you die that night, you die on Fitrat, the religion of Islam."},{"id":138,"title":"Gece Dönüş Yapıldığında Okunacak Dua","ref":"Hâkim'e göre Sahîh. İmam Zehebî 1/540; Nesâî, Amelü'l-Yevmi ve'l-Leyle No. 202, İbnü's-Sünnî No. 757. Ayrıca bkz. Sahîh Câmî 4:213","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_138.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ الْوَاحِدُ الْقَهَّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزِيزُ الْغَفَّارُ","latin":"Lâ ilâhe illAllâhü'l-Vâhidü'l-Kahhâr, Rabbus-semâvâti vel-ard, ve mâ beynehumel-Azîzü'l-Ğaffâr","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O, Tek'tir, Kahhar'dır, göklerin, yerin ve ikisi arasındakilerin Rabbi'dir, Azîz'dir, Gaffâr'dır.\n\nÂişe (ra) şöyle rivayet etmiştir: Allah'ın Resulü (ﷺ) gece uykuda döndüğünde şöyle derdi: (yukarıdaki dua)","en":"There is none worthy of worship but Allah, the One, the Victorious, Lord of the heavens and the earth and all that is between them, the All-Mighty, the All-Forgiving.\n\nAaishah (RA) narrated that the Messenger of Allah (ﷺ) used to say at night if he turned during sleep: (the dua is mentioned above)"},{"id":139,"title":"Uyanış Duası","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5060","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_139.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيْمِ، رَبِّ اغْفِرْ لِي","latin":"Lâ ilâhe illAllâhu vahdehû lâ şerîke leh, lehü'l-mülkü ve lehü'l-hamdü, ve Hüve alâ külli şey'in Kadîr. Sübhânallâhi, ve'l-hamdü lillâhi, ve lâ ilâhe illAllâhu, vAllâhu ekber, ve lâ havle ve lâ kuvvete illâ billâhi'l-Aliyyil-Azîm, Rabbığfirlî","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O tektir, ortağı yoktur; mülk O'nundur, hamd O'na aittir ve O her şeye kadirdir. Allah her türlü noksanlıktan münezzehtir; hamd Allah'a aittir; Allah'tan başka ibadete layık hiçbir ilah yoktur; Allah en büyüktür; güç ve kuvvet ancak yüce ve büyük olan Allah'a aittir. Rabbim! Beni bağışla.\n\nUbâde b. es-Sâmit (ra) şöyle rivayet etmiştir: Allah'ın Resulü (ﷺ) şöyle buyurdu: «Uyurken bir kimse ürperirse ve uyandığında bu duayı söyler ve namaz kılarsa namazı kabul edilir. Kalkar, abdest alır ve namaz kılarsa namazı makbul olur.»","en":"None has the right to be worshipped except Allah, alone, without any partner, to Him belong sovereignty and praise and He is over all things wholly capable. How perfect Allah is, and all praise is for Allah, and none has the right to be worshipped except Allah, Allah is the greatest and there is no power nor might except with Allah, The Most High, The Supreme, O my Lord forgive me.\n\n‘Ubadah bin al-Samit (RA) reported the Messenger of Allah (ﷺ) as saying, “If anyone is alarmed while asleep and he says when awakes and he prays, his prayer will be answered. If he gets up, performs ablution, and prays, his prayer will be accepted.”"},{"id":140,"title":"Uyanışta Okunacak Dua","ref":"Buhârî, bkz. el-Askalânî, Fethü'l-Bârî 8/237 no. 4569; Müslim 1/530 no. 256","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_140.json","ar":"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ ﴿١٩٠﴾ الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ﴿١٩١﴾ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ﴿١٩٢﴾ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ﴿١٩٣﴾ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ﴿١٩٤﴾ فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّن بَعْضٍ ۖ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّهِ ۗ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ ﴿١٩٥﴾ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ﴿١٩٦﴾ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ ۚ وَبِئْسَ الْمِهَادُ ﴿١٩٧﴾ لَٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ اللَّهِ ۗ وَمَا عِندَ اللَّهِ خَيْرٌ لِّلْأَبْرَارِ ﴿١٩٨﴾ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّهِ ثَمَنًا قَلِيلًا ۗ أُولَٰئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ اللَّهَ سَرِيعُ الْحِسَابِ ﴿١٩٩﴾ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ ﴿٢٠٠﴾","latin":"İnne fî halki's-semâvâti vel-ardi vahtilâfi'l-leyli ven-nehâri le-âyâtil-li-ülil-elbâb. Ellezîne yezkurûnAllâhe kıyâmen ve ku'ûden ve alâ cünûbihim ve yetefekkerûne fî halki's-semâvâti vel-ard; Rabbenâ mâ halakte hâzâ bâtılâ Sübhâneke fekınâ azâben-Nâr. Rabbenâ inneke men tudhill'n-Nâre fekad ahzeytehû ve mâ liz-zâlimîne min ensâr. Rabbenâ innenâ semi'nâ münâdiyen yünâdî lil-îmâni en âminû bi-Rabbikum fe-âmennâ; Rabbenâ fağfirlena zünûbenâ ve keffir annâ seyyiâtinâ ve teveffenâ meal-ebrâr. Rabbenâ ve âtinâ mâ vaadtenâ alâ rusülike ve lâ tuhzinâ Yevmel-Kıyâmeh; inneke lâ tuhliful-mîâd. Festecâbe lehüm Rabbühüm ennî lâ ûdî'u amele âmilin minkum min zekerin ev ünsâ; ba'dukum min ba'd; fellezîne hâcerû ve uhrıcû min diyârihim ve ûzû fî sebîlî ve kâtelû ve kutilû le-ükeffiranneannhüm seyyiâtihim ve le-üdhilennehüm cennâtin tecrî min tahtihel-enhâr; sevâben min indillâh; vAllâhü indehu hüsnüs-sevâb. Lâ yağurranneke tekallübüllezîne keferû fil-bilâd. Metâ'un kalîlün sümme me'vâhüm cehennemü ve bi'sel-mihâd. Lâkinillezînet-tekav Rabbehüm lehüm cennâtün tecrî min tahtihel-enhâru hâlidîne fîhâ nüzülen min indillâh; ve mâ indAllâhi hayrun lil-ebrâr. Ve inne min Ehlil-Kitâbi lemen yü'minü billâhi ve mâ ünzile ileykum ve mâ ünzile ileyhim hâşiîne lillâhi lâ yeşterûne bi-âyâtillâhi semenen kalîlâ; ülâike lehüm ecrühüm inde Rabbihim; innAllâhe serî'ul-hisâb. Yâ eyyühe'llezîne âmenûs-birû ve sâbirû ve râbitû vettekullâhe leallekum tüflihûn.","tr":"(190) Şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün birbirini takip edişinde aklıselim sahipleri için deliller vardır. (191) Onlar ayakta iken, otururken ve yanları üzerinde yatarken Allah'ı zikreder, göklerin ve yerin yaratılışını düşünürler. «Rabbimiz! Bunu boşuna yaratmadın. Seni tenzih ederiz; bizi cehennem azabından koru.» (192) «Rabbimiz! Şüphesiz Sen kimi ateşe sokarsan onu rezil etmiş olursun. Zalimlerin ise hiçbir yardımcısı yoktur.» (193) «Rabbimiz! Biz imanı çağıran bir davetçiyi duyduk: 'Rabbinize iman edin' dedi ve inandık. Rabbimiz! Günahlarımızı bağışla, kötülüklerimizi ört ve bizi iyilerle birlikte öldür.» (194) «Rabbimiz! Peygamberlerin aracılığıyla bize vaat ettiğini ver ve Kıyamet günü bizi rezil etme. Şüphesiz Sen vaadinden dönmezsin.» (195) Rableri onlara cevap verdi: «İçinizden erkek veya kadın, hiçbir çalışanın işini zayi etmeyeceğim; hepiniz birbirinizdensiniz. Hicret edenler, yurtlarından çıkarılanlar, yolumda eziyet görenler, savaşanlar ve öldürülenler — mutlaka kötülüklerini örteceğim ve onları altında nehirler akan cennetlere koyacağım; Allah katından bir mükâfat olarak. Güzel mükâfat Allah katındadır.» (196) Kâfirlerin ülkede dolaşıp durması seni aldatmasın. (197) Bu az bir geçimliktir; sonra sığınakları cehennemdir ve o ne kötü bir yerdir. (198) Fakat Rablerinden korkup sakınanlar için Allah katından konuk olarak altında nehirler akan cennetler vardır; orada ebediyen kalacaklardır. Allah katındaki iyiler için daha hayırlıdır. (199) Kitap Ehli'nden öyleleri de var ki Allah'a, size indirilene ve kendilerine indirilene, boyun eğerek Allah'a saygı duyarak inanırlar; Allah'ın ayetlerini az bir bedelle satmazlar. İşte onların Rableri katında mükâfatları vardır. Allah hesabı çabuk görendir. (200) Ey iman edenler! Sabredin, sabır yarışında birbirinizi geçin, Allah'a karşı gelmekten sakınıp savaşa hazır bekleyin ki kurtuluşa eresiniz. (Âl-i İmrân Suresi 3: 190-200)\n\nArdından Peygamber (ﷺ) kalktı ve iki rekât namaz kıldı; o namazda kıyamı, rükûu ve secdeyi uzattı. Namazı bitirdikten sonra uyudu....","en":"(190) Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding. (191) Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], \"Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire. (192) Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers. (193) Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous. (194) Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\" (195) And their Lord responded to them, \"Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward.\" (196) Be not deceived by the [uninhibited] movement of the disbelievers throughout the land. (197) [It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place. (198) But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah . And that which is with Allah is best for the righteous. (199) And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah . They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account. (200) O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful. (Sura Al-Imran 3: 190-200)\n\nThen the Prophet (ﷺ) stood up and prayed two rak'ats; In that prayer he prolongs Qiyam, Rukoo and Sujood. After ending the prayer he fell asleep ...."},{"id":141,"title":"Uyanıştan Sonra Dua","ref":"Buhârî, bkz. el-Askalânî, Fethü'l-Bârî 11/113 no. 6314; Müslim 4/2083 no. 2711","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_141.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُوْرُ","latin":"Elhamdü lillâhillezî ahyânâ ba'de mâ emâtenâ ve ileyhinnüşûr","tr":"Bizi öldürdükten sonra dirilten Allah'a hamd olsun; diriliş de O'nadır.","en":"All praise is for Allah who gave us life after having taken it from us and unto Him is the resurrection."},{"id":142,"title":"Fecir Namazı için Uyanış Duası","ref":"Tirmizî 5/473. Bkz. Elbânî'nin Sahîh Tirmizî 3/144","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_142.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِيْ فِي جَسَدِيْ، وَرَدَّ عَلَيَّ رُوحِيْ، وَأَذِنَ لِي بِذِكْرِهِ","latin":"Elhamdü lillâhillezî âfânî fî cesedî, ve radde aleyye rûhî, ve ezine lî bi-zikrih","tr":"Bedenimi sağlıklı kılan, ruhumu bana iade eden ve beni zikretmeme izin veren Allah'a hamd olsun.","en":"Praise is to Allah Who gave strength to my body and returned my soul to me and permitted me to remember Him."},{"id":144,"title":"Kötü Rüya için Dua","ref":"[1] Buhârî: 7044 [2] Müslim: 6041 [3] Sahîh (Elbânî). Tirmizî: 2280","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_144.json","ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ","latin":"Eûzü billâhi mineş-Şeytânirracîm","tr":"Kovulmuş şeytandan Allah'a sığınıyorum.\n\nUyku pozisyonunu değiştirmek gerekir. Bu rüyayı kimsenin önünde anlatmak yasaktır. Güzel rüya görmüş olsanız bile kimseye söylemek zorunda değilsiniz. Ancak yakın bir arkadaşın önünde veya bilge kişilerin önünde söylenebilir. Ebû Katâde (ra) şöyle rivayet etmiştir: Peygamber (ﷺ) şöyle buyurdu: Güzel rüya Allah'tandır. Kötü rüya ise şeytandandır. Dolayısıyla güzel rüya gören kişi onu sevdiği kişiye anlasın. Kötü rüya gören ise zararından ve şeytanın kötülüğünden Allah'a sığınsın, sola üç kez tükürsün. Rüyayı kimseye anlatmasın. Böyle yaparsa zarar görmez. [1] Cerîr (ra) şöyle dedi: Allah'ın Resulü (ﷺ) şöyle buyurdu: Biriniz hoşlanmadığı bir rüya gördüğünde soluna üç kez tükürsün. Üç kez şeytandan Allah'a sığınsın ve yan değiştirsin. [2] Ebû Hüreyre (ra) şöyle dedi: Allah'ın Resulü (ﷺ) şöyle buyurdu: Bir kimse kötü rüya görürse kalksın ve iki rekât namaz kılsın. [3]","en":"I seek refuge in Allah from Satan the outcast.\n\nOne need to change sides in their sleep. It is forbidden to tell this dream in front of anyone. Even if you have good dreams, you don't have to tell anyone. But it can be said in front of a close friend or in front of wise people. Narrated Abu Qatadah (RA): The Prophet (ﷺ) said: A good dream is from Allah. And bad dreams are from the devil. So whoever has a good dream, let him reveal it to the one he loves. And if anyone has a bad dream, let him seek refuge in Allah from its harm and from the evil of Satan, and spit three times to the left. Don't reveal the dream to anyone. Then it will not be able to harm him. [1] Jarir (RA) said, Rasulullah (ﷺ) said, when one of you has a dream that he dislikes, he should spit three times to his left. And he seeks refuge in Allah from Satan three times and changes sides. [2] Abu Hurairah (RA) said: The Messenger of Allah (ﷺ) said: If a person has a bad dream, he should get up and pray two rak'ahs. [3]"},{"id":146,"title":"Giyinirken Okunacak Dua","ref":"Hasen (Elbânî). Ebû Dâvûd: 4023","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_146.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي كَسَانِيْ هَذَا الثَّوْبَ وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّيْ وَلَا قُوَّةٍ","latin":"Elhamdü lillâhillezî kesânî hâzâ's-sevbe ve razakanîhi min ğayri havlin minnî ve lâ kuvveh","tr":"Beni bu elbise ile giydiren ve bana, hiçbir güç ve kuvvetim olmaksızın onu rızık olarak veren Allah'a hamd olsun.\n\nPeygamber (ﷺ) şöyle buyurdu: «Her kim elbise giyerken bunu söylerse geçmiş günahları bağışlanır.»","en":"All Praise is for Allah who has clothed me with this garment and provided it for me, with no power nor might from myself.\n\nThe Prophet (ﷺ) said, \"If anyone says this while wearing clothes, his previous sins will be forgiven.\""},{"id":147,"title":"Yeni Kıyafet Giyerken Okunacak Dua","ref":"Sahîh (Elbânî). Tirmizî: 1767","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_147.json","ar":"اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيْهِ أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ وَأَعُوْذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ","latin":"Allâhümme leke'l-hamdü Ente kesevtenîhi, es'elüke hayrehû ve hayra mâ suni'a leh, ve eûzü bike min şerrihî ve şerri mâ suni'a leh","tr":"Allah'ım! Hamd Sana aittir; beni bununla giydirdin. Onun hayrını ve yapılış amacının hayrını Senden istiyorum; onun şerrinden ve yapılış amacının şerrinden Sana sığınıyorum.","en":"O Allah, for You is all praise, You have clothed me with it, I ask You for the good of it and the good for which it was made, and I seek refuge with You from the evil of it and the evil for which it was made."},{"id":148,"title":"Yeni Kıyafet Giyen Biri için Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 4020","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_148.json","ar":"تُبْلَی وَيُخْلِفُ اللَّهُ تَعَالَی","latin":"Tubla' ve yuhliful-lâhu te'âlâ","tr":"Allah Teâlâ onu eskitsin ve yerine yenisini versin.\n\nSahabeler birisinin yeni kıyafet giydiğini gördüklerinde bu duayı yaparlardı.","en":"May you wear it out and Allah (Ta'aala) replace it [with another].\n\nThe Companions used to make this dua when they saw someone wearing new clothes."},{"id":149,"title":"Soyunmadan Önce Dua (Bismillâh)","ref":"Sahîh (Elbânî). Tirmizî: 606","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_149.json","ar":"بِسْمِ اللَّه","latin":"Bismillâh","tr":"Allah'ın adıyla.\n\nAllah'ın Resulü (ﷺ) şöyle buyurdu: «Biriniz soyunduğunda veya avret yerleri açıldığında cin gözleriyle insan avret yerleri arasındaki perde Bismillâh'tır.»","en":"In the name of Allah.\n\nThe Messenger of Allah (ﷺ) said: When one of you undresses or is uncovered, the veil between the human genitals and the eyes of the jinn is called 'Bismillah'."},{"id":150,"title":"Yeni Kıyafet Giyen Kadın için Dua","ref":"Buhârî: 5993","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_150.json","ar":"أَبْلِيْ وَأَخْلِقِيْ","latin":"Eblî ve ahlikî","tr":"Elbisenin eskiyinceye kadar yaşa.\n\nÜmm Hâlid (ra), Hâlid b. Saîd'in kızı şöyle dedi: «Allah'ın Resulü'ne (ﷺ) üzerinde siyah bir desen bulunan bir elbise getirildi. Sonra şöyle buyurdu: 'Bunu kime giydireceğiz?' Sahabeler sessiz kalınca Peygamber (ﷺ) buyurdu: 'Ümm Hâlid'i getirin.' Ben Peygamber'e (ﷺ) getirilince bizzat kendi eliyle elbiseyi bana giydirdi. Ardından iki kez şöyle buyurdu: (Yukarıdaki dua)» Bu, Ümm Hâlid'in çok küçük yaşta babasıyla Habeşistan'dan Medine'ye hicret ettiğinde olmuştu.»","en":"May you live so long that your dress gets worn out.\n\nUmm Khalid (RA), daughter of Khalid Ibn Sayed (RA), said, 'A garment was brought to the Messenger of Allah (ﷺ), with a black design on it. Then he said, \"Who can we wear this dress?\" When the Companions were silent, the Prophet (ﷺ) said, \"Bring Umm Khalid.\" Then when I was brought to the Prophet (ﷺ), he put the garment on me with his own hands. Then he said twice- (The dua is mentioned above) This is what happened when Umme Khalid emigrated from Ethiopia to Medina with her father, when she was very young."},{"id":151,"title":"Yeni Kıyafet Giyen Erkek için Dua","ref":"Buhârî: 5993","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_151.json","ar":"أَبْلَ وَأَخْلَقْ","latin":"Eble ve ahlık","tr":"Elbisenin eskiyinceye kadar yaşa.","en":"May you live so long that your dress gets worn out."},{"id":152,"title":"Yeni Kıyafet Giyene Okunacak Dua","ref":"Sahîh (Elbânî). İbn Mâce: 3558","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_152.json","ar":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا","latin":"İlbes cedîden, va'ış hamîden ve müt şehîden","tr":"Yenisini giy, övgüyle yaşa ve şehid olarak öl.\n\nİbn Ömer (ra) şöyle rivayet etmiştir: Peygamber (ﷺ) Ömer'in üzerinde beyaz bir elbise gördü ve şöyle dedi: «Bu elbisenin yeni mi, yoksa yıkanmış gibi mi görünüyor?» O şöyle dedi: «Yıkanmış.» Ardından Peygamber (ﷺ) şöyle buyurdu: (Yukarıdaki dua) Ömer (ra) şöyle dedi: «Ey Allah'ın Resulü! Aynı duayı sana da yapıyorum.»","en":"Wear anew, live commendably and die a shaheed.\n\nNarrated Ibn Umar (RA): The Prophet (ﷺ) saw a white dress on Umar and said, “Is this your dress new, or does it look like it was washed?” He said, “It is rather new.” Then the Prophet (ﷺ) said - (The dua is mentioned above) Umar (RA) said, “O Messenger of Allah! I am praying the same for you.”"},{"id":153,"title":"Yeni Kıyafet Giyene Söylenecek Dua","ref":"Sahîh (Elbânî). Sahîhü'l-Câmî: 1234","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_153.json","ar":"اِلْبَسْ جَدِيدًا وَعِشْ حَمِيدًا وَمُتْ شَهِيدًا وَيَرْزُقُكَ اللَّهُ قٌرَّةَ عَيْنٍ فِي الدُّنْيَا وَالْاَخِرَةِ","latin":"İlbes cedîden, va'ış hamîden ve müt şehîden ve en yerzukakallâhu kurrate aynin fid-dünyâ vel-âhirah","tr":"Yenisini giy, övgüyle yaşa ve şehid olarak öl; Allah sana dünyada ve ahirette gözünü aydınlatacak şeyler versin.","en":"Wear anew, live commendably and die a shaheed and may Allah give you those things in this duniya and in hereafter which will cool your eyes."},{"id":154,"title":"Evden Çıkarken Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5095","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_154.json","ar":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Bismillâhi, tevekkeltü alAllâhi, lâ havle ve lâ kuvvete illâ billâh","tr":"Allah'ın adıyla, Allah'a tevekkül ettim; güç ve kuvvet ancak Allah'a aittir.\n\nEnes b. Mâlik (ra) şöyle rivayet etmiştir: Peygamber (ﷺ) şöyle buyurdu: Bir kişi evinden çıkarken bu sözleri söylediğinde şu anda kendisine şöyle denilir: «Hidayete erdirildin, korunup kollandın ve muhafaza edildin.» Şeytanlar ondan uzaklaşır ve bir diğer şeytan şöyle der: «Hidayete erdirilmiş, korunmuş ve muhafaza edilmiş biriyle nasıl baş edebilirsin?»","en":"In the name of Allah, I place my trust in Allah and there is no might nor power except with Allah.\n\nNarrated Anas ibn Malik (RA): The Prophet (ﷺ) said: When a man goes out of his house and say these words, the following will be said to him at that time: \"You are guided, defended and protected.\" The devils will go far from him and another devil will say: How can you deal with a man who has been guided, defended and protected?"},{"id":155,"title":"Evden Çıkmadan Önce Okunacak Dua","ref":"Sahîh (Elbânî). Tirmizî: 3427","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_155.json","ar":"بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ اَللَّـهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نَزِلَّ أَوْ نَضِلَّ أَوْ نَظْلِمَ أَوْ نُظْلَمَ أَوْ نَجْهَلَ أَوْ يُجْهَلَ عَلَيْنَا","latin":"Bismillâhi, tevekkeltü alAllâhi. Allâhümme, innâ neûzü bike min en nezille ev nadılle, ev nazlime ev nuzlame, ev naćhele ev yuchelee aleynâ","tr":"Allah'ın adıyla, Allah'a tevekkül ettim. Allah'ım! İstemeden kayıp yaşamaktan veya sapıtmaktan, zulüm etmekten veya zulme uğramaktan, cahilce davranmaktan veya cahilce muameleye maruz kalmaktan Sana sığınırız.\n\nMü'min, gündüz veya gece dışarı çıktığında bu ezkarı kalbiyle okumalıdır.","en":"In the Name of Allah, I place my trust in Allah. O Allah! We seek refuge in You from slipping unintentionally or becoming misguided, or committing oppression or being oppressed, or acting ignorantly or being treated ignorantly.\n\nA mu'min should recite these adhkar by his/her heart whenever (Day/Night) he/she goes outside."},{"id":156,"title":"Evden Çıkarken Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 5094","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_156.json","ar":"اَللَّـهُمَّ إِنِّي أَعُوْذُ بِكَ أَنْ أَضِلَّ، أَوْ أُضَلَّ، أَوْ أَزِلَّ، أَوْ أُزَلَّ، أَوْ أَظْلِمَ، أَوْ أُظْلَمَ، أَوْ أَجْهَلَ، أَوْ يُجْهَلَ عَلَيَّ","latin":"Allâhümme innî eûzü bike min en adılle ev üdalle, ev ezille ev üzalle, ev azlime ev uzlame, ev echelee ev yuchelee aleyye","tr":"Allah'ım! Sapıtmaktan veya saptırılmaktan, istemeden günah işlemekten veya günaha sürüklenmekten, zulüm etmekten veya zulme uğramaktan, cahilce davranmaktan veya cahilce muameleye maruz kalmaktan Sana sığınırım.","en":"O Allah, I seek refuge with You lest I should stray or be led astray, or slip (i.e. to commit a sin unintentionally) or be tripped, or oppress or be oppressed, or behave foolishly or be treated foolishly."},{"id":157,"title":"Eve Girerken Okunacak Dua","ref":"Hasen (İbn Bâz). Ebû Dâvûd: 5096","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_157.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَوْلِجِ وَخَيْرَ الْمَخْرَجِ بِسْمِ اللَّهِ وَلَجْنَا وَبِسْمِ اللَّهِ خَرَجْنَا وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","latin":"Allâhümme innî es'elüke hayral-mevlici ve hayral-mahrace. Bismillâhi velecnâ, ve bismillâhi haracnâ, ve alAllâhi rabbinâ tevekkelna","tr":"Allah'ım! Girişte de çıkışta da senden hayır dilerim. Allah'ın adıyla girdik, Allah'ın adıyla çıktık ve Rabbimiz Allah'a tevekkül ettik.\n\nResûlullah (ﷺ) eve girerken Allah'ı anmayı emretti ve bunu yapanın yanına şeytanın giremeyeceğini bildirdi. Eve girerken yapılacak temel dua selamdır. Ebû Mâlik el-Eş'arî (ra) rivayet etmiştir ki, Resûlullah (ﷺ) şöyle buyurdu: Biriniz eve girdiğinde bu sözleri söylesin, ardından ailesine selam versin. Bu rivayetin ravileri güvenilir olmakla birlikte hadisin 'Mürsel' olma ihtimali bulunmaktadır.","en":"O Allah! I ask Thee for good both when entering and when going out; in the name of Allah we have entered, and in the name of Allah we have gone out, and in Allah our Lord do we trust.\n\nRasoolullah (ﷺ) commanded us to mention Allah upon entering home and informed that, who does that devil can’t enter into the house with him. Fundamental dua upon entering home is giving salaam. Abu Malik Ash’ari (RA) narrated that, Rasoolullah (ﷺ) said that, when anyone from you enter into the house, he should recite these words and then give salaam to his family. The narrators of this narration are all trustworthy but there is a probability that the hadith is ‘Mursaal’."},{"id":158,"title":"Eve Girmeden Önce Okunacak Dua","ref":"Hasen (İbn Hacer). Mişkât: 4/316","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_158.json","ar":"اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ","latin":"Es-selâmü aleyküm ve rahmetullâhi ve berekâtüh","tr":"Allah'ın selâmı, rahmeti ve bereketi üzerinize olsun.\n\nHerkese selam vermek sünnettir. Eş ve aile üyelerine selam vermek ise ayrıca sünnet olan bir davranıştır. Bu davranışın özel ödülleri vardır ve aşağıdaki hadis bu özelliğe sahip olanlara müjde vermektedir. Ebû Umâme (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) şöyle buyurdu: «Allah üç kişiye kefil olur ve onları korur. Yaşarsa tüm işleri Allah tarafından korunur, ölürse cennete girer. (Birincisi) Eve girmeden önce selam veren kişi, Allah'ın himayesine girer...»","en":"Peace be upon you, and the Mercy of Allah and His Blessings.\n\nTo give salaam upon all is sunnah. Giving salaam upon spouse and family members is additional sunnah. It is recommended and have special rewards and those who have this character, this below mentioned hadith give glad tidings. Abu umama (RA) said that, Rasoolullah (ﷺ) said, “Allah will give guarantee and protection for three kinds of people. If he live then all of his matter will be protected by Allah and if he die then he will enter into jannah. (First one is) He who give salaam before enter into the house, he will enter in the protection of Allah….”"},{"id":159,"title":"Eve Girerken Okunacak Dua","ref":"[1] Hasen (İbn Bâz). Ebû Dâvûd: 5096 [2] Müslim: 2018","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_159.json","ar":"بِسْمِ اللَّهِ وَلَجْنَا، وَبِسْمِ اللَّهِ خَرَجْنَا، وَعَلَى اللَّهِ رَبِّنَا تَوَكَّلْنَا","latin":"Bismillâhi velecnâ, ve bismillâhi haracnâ, ve alAllâhi rabbinâ tevekkelna","tr":"Allah'ın adıyla girdik, Allah'ın adıyla çıktık ve Rabbimiz Allah'a tevekkül ettik.\n\nArdından ev halkına selam verilir. [1] Bir kişi evine girdiğinde ve yemek yerken Allah'ın adını andığında, şeytan (kendi kendine) şöyle der: «Geceleyecek yeriniz yok, akşam yemeğiniz de.» [2]","en":"In the name of Allah we enter and in the name of Allah we leave, and upon our Lord we place our trust.\n\nThen give salaam to the people of the house. [1] When a person enters his house and mentions the name of Allah at the time of entering it and while eating the food, Satan says (addressing himself: You have no place to spend the night and no evening meal;[2]"},{"id":160,"title":"Tuvalete Girmeden Önce Okunacak Dua","ref":"Buhârî: 142","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_160.json","ar":"بِسْمِ اللَّهِ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْخُبُثِ وَالْخَبَائِثِ","latin":"Bismillâh, Allâhümme innî eûzü bike mine'l-hubüsi ve'l-habâis","tr":"Allah'ın adıyla. Allah'ım! Erkek ve dişi kötü ruhlardan Sana sığınırım.\n\nAlî (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) şöyle buyurdu: «Biriniz tenha bir yere ihtiyacını gidermek için gittiğinde, insanoğlunun avret yerini cinlerin gözünden koruyan şey 'Bismillâh' demektir.»","en":"In the Name of Allah. O Allah, I seek protection in You from the male and female unclean spirits.\n\nAli (RA) said, Rasoolullah (ﷺ) said: When one of you goes to a secluded place by the call of nature, the covering of the genitals of the children of Adam from the eyes of the jinn is to say \"Bismillah\"."},{"id":161,"title":"Tuvaletten Çıkarken Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 30","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_161.json","ar":"غُفْرَانَكَ","latin":"Ğufrâneke","tr":"Senden bağışlanma dilerim.\n\nÂişe (ra) şöyle demiştir: Resûlullah (ﷺ) tuvaletten çıktığında bu duayı okurdu.","en":"I ask You (Allah) for forgiveness.\n\nAyesha (RA) said that Rasoolullah (ﷺ) used to say this dua when he came out of the toilet."},{"id":163,"title":"Ezan Duyduktan Sonra Okunacak Dua (Ezan Duası)","ref":"Müslim: 386","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_163.json","ar":"أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ رَضِيتُ بِاللَّهِ رَبًّا وَبِمُحَمَّدٍ رَسُولًا وَبِالْإِسْلَامِ دِينًا","latin":"Eşhedü en lâ ilâhe illAllâhu vahdehû lâ şerîke leh, ve enne Muhammeden abdühû ve resûlühû, radîtü billâhi rabben ve bi-Muhammedin resûlen ve bi'l-islâmi dînen","tr":"Şehadet ederim ki Allah'tan başka hak ilah yoktur, O tektir, ortağı yoktur; Muhammed O'nun kulu ve resulüdür. Allah'ı Rab, Muhammed'i resul ve İslam'ı din olarak kabul ettim ve bunlardan razı oldum.\n\nSa'd b. Ebî Vakkâs (ra) şöyle demiştir: Resûlullah (ﷺ) şöyle buyurdu: «Müezzini duyan ve bu sözleri söyleyen kişinin tüm günahları bağışlanır.»","en":"I bear witness that none has the right to be worshipped except Allah, alone, without partner, and that Muhammad is His slave and Messenger (ﷺ). I am pleased with Allah as a Lord, and Muhammad as a Messenger and Islam as a religion.\n\nSa'd ibn Abi Waqqas (RA) said: The Messenger of Allah (ﷺ) said: \"Whoever hears Mu'adhzin and utters these words, all his sins will be forgiven.\""},{"id":164,"title":"Ezan Sonrası Dua (Salavât-ı Şerîfe)","ref":"Müslim: 384","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_164.json","ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، اَللَّهُمَّ بَارِكَ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ","latin":"Allâhümme salli alâ Muhammedin ve alâ âli Muhammed, kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîm, inneke Hamîdün Mecîd. Allâhümme bârik alâ Muhammedin ve alâ âli Muhammed, kemâ bârekte alâ İbrâhîme ve alâ âli İbrâhîm, inneke Hamîdün Mecîd","tr":"Allah'ım! İbrahim'e ve İbrahim'in ailesine rahmet ettiğin gibi Muhammed'e ve Muhammed'in ailesine de rahmet eyle; şüphesiz Sen Hamîd ve Mecîd'sin. Allah'ım! İbrahim'e ve İbrahim'in ailesine bereket verdiğin gibi Muhammed'e ve Muhammed'in ailesine de bereket ver; şüphesiz Sen Hamîd ve Mecîd'sin.\n\nAbdullah b. Amr b. el-Âs (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) şöyle buyurdu: «Müezzini duyduğunuzda onun söylediklerini tekrarlayın, sonra bana salavât getirin; zira bana salavât getiren kişiye Allah on kat bereket verir. Ardından Allah'tan benim için vesîleyi isteyin; vesîle, cennette Allah'ın kullarından yalnızca birine yakışan bir makamdır ve umarım o kişi ben olurum. Kim benim için vesîleyi isterse şefaatime hak kazanır.»","en":"O Allah, bestow Your favor on Muhammad (ﷺ) and on the family of Muhammad (ﷺ) as You have bestowed Your favor on Ibrahim (Ah) and on the family of Ibrahim (Ah), You are Praiseworthy, Most Glorious. O Allah, bless Muhammad (ﷺ) and the family of Muhammad (ﷺ) as You have blessed Ibrahim and the family of Ibrahim (Ah), You are Praiseworthy, Most Glorious.\n\nAbdullah bin Amr bin al-As (RA) reported Allah's Messenger (ﷺ) as saying: When you hear the Mu'adhdhin, repeat what he says, then invoke a blessing on me, for everyone who invokes a blessing on me will receive ten blessings from Allah; then beg from Allah al-Wasila for me, which is a rank in Paradise fitting for only one of Allah's servants, and I hope that I may be that one. If anyone who asks that I be given the Wasila, he will be assured of my intercession."},{"id":165,"title":"Ezan Sonrası Dua (Ezan Duası)","ref":"Buhârî: 614","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_165.json","ar":"اَللَّهُمَّ رَبَّ هَذِهِ الدَّعْوَةِ التَّامَّةِ، وَالصَّلَاةِ الْقَائِمَةِ، آتِ مُحَمَّدًا وَالْوَسِيْلَةَ وَالْفَضِيْلَةَ، وَابْعَثْهُ مَقَامًا مَحْمُوْدًا الَّذِيْ وَعَدْتَهُ","latin":"Allâhümme Rabbe hâzihi'd-da'veti't-tâmmeh, ves-salâti'l-kâimeh, âti Muhammeden el-vesîlete vel-fadîleh, veb'ashü makâmen mahmûdenil-lezî veadteh","tr":"Allah'ım! Bu eksiksiz davetin ve kılınacak namazın Rabbi! Muhammed'e (ﷺ) vesîleyi ve fazileti ver; ona vaat ettiğin makâm-ı mahmûdu nasip eyle.","en":"O Allah, Owner of this perfect call and Owner of this prayer to be performed, bestow upon Muhammad (ﷺ) al-waseelah and al-fadeelah and raise him upon a praised platform which You have promised him."},{"id":168,"title":"İmamlar ve Müezzinler için Dua (Bağışlanma Duası)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 517","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_168.json","ar":"اَللَّهُمَّ أَرْشِدِ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِيْنَ","latin":"Allâhümme arşidil eimmete vağfir lil-müezzinîn","tr":"Allah'ım! İmamlara hidayet ver, müezzinleri bağışla.","en":"O Allah, guide the imams and forgive the mu'adhdhins."},{"id":171,"title":"Abdest Sonrası Dua","ref":"Sahîh (Elbânî). Tirmizî: 55","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_171.json","ar":"اَللَّهُمَّ اجْعَلْنِيْ مِنَ التَّوَّابِيْنَ وَاجْعَلْنِي مِنَ الْمُتَطَهِّرِيْنَ","latin":"Allâhümmec'alnî mine't-tevvâbîne vec'alnî mine'l-mütetahhirîn","tr":"Allah'ım! Beni tevbe edenlerin arasına kat ve beni temizlenenlerin arasına kat.\n\nSahîh bir hadiste bu duanın önceki zikirden sonra okunması gerektiği bildirilmiştir. Bu iki duayı okuyan kişi için cennetin sekiz kapısı açılır; dilediği kapıdan girebilir.","en":"O Allah, make me among those who turn to You in repentance, and make me among those who are purified.\n\nIt has been narrated in Sahih Hadith that the dua should be recited after the previous dhikr. The eight gates of Paradise will be opened for the one who recites these two duas; He will enter (Paradise) through whichever door he wishes."},{"id":172,"title":"Abdest Sonrası Dua","ref":"Nesâî, Amelu'l-Yevm ve'l-Leyle, s. 173. Ayrıca bkz. Elbânî, İrvâü'l-Ğalîl 1/135 ve 2/94.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_172.json","ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ","latin":"Sübhâneke Allâhümme ve bihamdike, eşhedü en lâ ilâhe illâ Ente, estağfiruke ve etûbü ileyke","tr":"Allah'ım! Seni her türlü noksanlıktan tenzih eder, Seni överim. Senden başka hak ilah olmadığına şehadet ederim. Senden bağışlanma diler ve Sana tevbe ederim.\n\nEbû Saîd (ra) şöyle demiştir: Resûlullah (ﷺ) şöyle buyurdu: «Kim abdest aldıktan sonra bu duayı söylerse, o dua bir kâğıda yazılır ve mühürlenir (Arş'ın altında). Bu mühür kıyamete kadar kırılmaz.»","en":"Glory is to You, O Allah, and praise; I bear witness that there is none worthy of worship but You. I seek Your forgiveness and turn to You in repentance.\n\nAbu Sayed (RA) said, Rasulullah (ﷺ) said, if someone says this dua after ablution, it will be written in a letter and sealed (under the throne). That seal will not be broken before the Resurrection."},{"id":173,"title":"Camiye Giderken Okunacak Dua (Nûr Duası)","ref":"Buhârî: 6316","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_173.json","ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُوْرًا وَّفِي لِسَانِىْ نُوْرًا وَّاجْعَلْ فِي سَمْعِىْ نُوْرًا وَّاجْعَلْ فِي بَصَرِىْ نُوْرًا وَّاجْعَلْ مِنْ خَلْفِي نُوْرًا وَّمِنْ أَمَامِيْ نُوْرًا وَّاجْعَلْ مِنْ فَوْقِىْ نُوْرًا وَّمِنْ تَحْتِىْ نُوْرًا اَللَّهُمَّ أَعْطِنِىْ نُوْرًا","latin":"Allâhümmec'al fî kalbî nûren, ve fî lisânî nûren, vec'al fî sem'î nûren, vec'al fî basarî nûren, vec'al min halfî nûren, ve min emâmî nûren, vec'al min fevkî nûren, ve min tahtî nûren, Allâhümme a'tinî nûren","tr":"Allah'ım! Kalbime nûr ver, dilime nûr ver, kulağıma nûr ver, gözüme nûr ver, arkama nûr ver, önüme nûr ver, üstüme nûr ver, altıma nûr ver. Allah'ım! Bana nûr ihsan eyle.","en":"O Allah, place within my heart light, and upon my tongue light, and within my ears light, and within my eyes light, and place behind me light, and in front of me light, and above me light, and beneath me light. O Allah, bestow upon me light."},{"id":174,"title":"Camiye Giderken Okunacak Dua","ref":"Buhârî: 6316","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_174.json","ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي لِسَانِي نُورًا، وَفِي سَمْعِي نُورًا، وَفِي بَصَرِي نُورًا، وَمِنْ فَوْقِي نُورًا، وَمِنْ تَحْتِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ شِمَالِي نُورًا، وَمِنْ أَمَامِي نُورًا، وَمِنْ خَلْفِي نُورًا، وَاجْعَلْ فِي نَفْسِي نُورًا، وَأَعْظِمْ لِي نُورًا، وَعَظِّمْ لِي نُورًا، وَاجْعَلْ لِي نُورًا، وَاجْعَلْنِي نُورًا، اَللَّهُمَّ أَعْطِنِي نُورًا، وَاجْعَلْ فِي عَصَبِي نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِي نُورا، وَفِي شَعْرِي نُورًا، وَفِي بَشَرِي نُورًا","latin":"Allâhümmec'al fî kalbî nûren, ve fî lisânî nûren, ve fî sem'î nûren, ve fî basarî nûren, ve min fevkî nûren, ve min tahtî nûren, ve an yemînî nûren, ve an şimâlî nûren, ve min emâmî nûren, ve min halfî nûren, vec'al fî nefsî nûren, ve a'zim lî nûren, ve azzim lî nûren, vec'al lî nûren, vec'alnî nûren, Allâhümme a'tinî nûren, vec'al fî asabî nûren, ve fî lahmî nûren, ve fî demî nûren, ve fî şa'rî nûren, ve fî beşerî nûren","tr":"Allah'ım! Kalbime nûr ver, dilime nûr ver, kulağıma nûr ver, gözüme nûr ver, üstüme nûr ver, altıma nûr ver, sağıma nûr ver, soluma nûr ver, önüme nûr ver, arkama nûr ver. Canıma nûr ver. Benim için nûrumu büyüt ve artır. Bana nûr ihsan eyle ve beni nûr kıl. Allah'ım! Bana nûr ver; sinirlerime nûr ver, etine nûr ver, kanıma nûr ver, saçıma nûr ver ve derimin nûr ver.","en":"O Allah, place light in my heart, and on my tongue light, and in my ears light and in my sight light, and above me light, and below me light, and to my right light, and to my left light, and before me light and behind me light. Place in my soul light. Magnify for me light, and amplify for me light. Make for me light and make me a light. O Allah, grant me light, and place light in my nerves, and in my body light and in my blood light and in my hair light and in my skin light."},{"id":175,"title":"Camiye Girerken Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 465, Müslim: 713","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_175.json","ar":"بِسْمِ اللَّهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ، اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","latin":"Bismillâhi, ves-salâtü ves-selâmü alâ Resûlillâh. Allâhümmeftah lî ebvâbe rahmetik","tr":"Allah'ın adıyla. Allah'ın Resulü'ne (ﷺ) salât ve selâm olsun. Allah'ım! Bana rahmetinin kapılarını aç.","en":"In the Name of Allah, And blessings and peace be upon the Messenger of Allah (ﷺ). O Allah, open before me the doors of Your mercy."},{"id":176,"title":"Camiye Girerken Okunacak Dua (Allâhümme Salli Alâ Muhammed)","ref":"Hasen (Elbânî). İbnü's-Sünnî: 88, Müslim: 713","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_176.json","ar":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","latin":"Bismillâhi, Allâhümme salli alâ Muhammed, Allâhümmeftah lî ebvâbe rahmetik","tr":"Allah'ın adıyla. Allah'ım! Allah'ın Resulü'ne (ﷺ) salât ve selâm eyle. Allah'ım! Bana rahmetinin kapılarını aç.","en":"In the Name of Allah, Ya Allah please send blessings and peace upon the Messenger of Allah (ﷺ). O Allah, open before me the doors of Your mercy."},{"id":177,"title":"Camiye Girerken Okunacak Dua (Rabbığfirlî Zünûbî)","ref":"Sahîh (Elbânî). İbn Mâce: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_177.json","ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","latin":"Rabbığfirlî zünûbî veftah lî ebvâbe rahmetik","tr":"Rabbim! Günahlarımı bağışla ve bana rahmetinin kapılarını aç.","en":"O Allah, forgive me my sins and open to me the gates of Your mercy."},{"id":178,"title":"Camiye Girmeden Önce Okunacak Dua (Eûzü Billâh)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 465, 466","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_178.json","ar":"أَعُوْذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيْمِ مِنَ الشَّيْطَانِ الرَّجِيْمِ، بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ اَللَّهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ","latin":"Eûzü billâhi'l-azîm ve bi-vechihil-kerîm ve sultânihil-kadîm mine'ş-şeytânirracîm, bismillâhi, ves-salâtü ves-selâmü alâ Resûlillâh, Allâhümmeftah lî ebvâbe rahmetik","tr":"Kovulmuş şeytandan Yüce Allah'a, O'nun şerefli yüzüne ve ezelî saltanatına sığınırım. Allah'ın adıyla, Allah'ın Resulü'ne (ﷺ) salât ve selâm olsun. Allah'ım! Bana rahmetinin kapılarını aç.","en":"I take refuge with Allah, The Supreme and with His Noble Face, and His eternal authority from the accursed devil. In the name of Allah, and prayers and peace be upon the Messenger of Allah (ﷺ). O Allah, open the gates of Your mercy for me."},{"id":179,"title":"Camiden Çıkarken Okunacak Dua (Allâhümme İnnî Es'elüke)","ref":"Hasen (Elbânî). İbnü's-Sünnî: 88, Müslim: 713","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_179.json","ar":"بِسْمِ اللَّهِ اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ فَضْلِكَ","latin":"Bismillâhi Allâhümme salli alâ Muhammed, Allâhümme innî es'elüke min fadlik","tr":"Allah'ın adıyla (çıkıyorum). Allah'ım! Muhammed'e (ﷺ) salât ve selâm eyle. Allah'ım! Senden lütfunu isterim.","en":"In the name of Allah (I am going out).Oh Allah! Please send bessings and peace upon muhammad (ﷺ). Oh Allah! I want from your bounty."},{"id":180,"title":"Camiden Ayrılırken Okunacak Dua","ref":"Sahîh (Elbânî). İbn Mâce: 773","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_180.json","ar":"بِسْمِ اللَّهِ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُوْلِ اللَّهِ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ، اَللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","latin":"Bismillâhi ves-salâtü ves-selâmü alâ Resûlillâh, Allâhümme innî es'elüke min fadlik, Allâhümmesımnî mine'ş-şeytânirracîm","tr":"Allah'ın adıyla, Allah'ın Resulü'ne (ﷺ) salât ve selâm olsun. Allah'ım! Senden lütfunu isterim. Allah'ım! Beni kovulmuş şeytandan koru.","en":"In the Name of Allah, and peace and blessings be upon the Messenger of Allah (ﷺ). O Allah, I ask for Your favor, O Allah, protect me from Satan the outcast."},{"id":181,"title":"Camiden Çıkarken Okunacak Dua (Allâhümme Ecirnî)","ref":"Sahîh (İbn Hibbân). İbn Hibbân: 2047","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_181.json","ar":"اَللَّهُمَّ أَجِرْنِيْ مِنَ الشَّيْطَانِ الرَّجِيْمِ","latin":"Allâhümme ecirnî mine'ş-şeytânirracîm","tr":"Allah'ım! Beni kovulmuş şeytandan koru.","en":"O Allah, protect me from Satan the outcast."},{"id":182,"title":"Camiden Çıkarken Okunacak Dua","ref":"Sahîh (Elbânî). İbn Mâce: 773","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_182.json","ar":"اَللَّهُمَّ اعْصِمْنِى مِنَ الشَّيْطَانِ الرَّجِيْمِ","latin":"Allâhümmesımnî mine'ş-şeytânirracîm","tr":"Allah'ım! Beni kovulmuş şeytandan koru.","en":"O Allah, protect me from Satan the outcast."},{"id":183,"title":"Camiden Ayrılış Duası (Allâhümmağfirlî)","ref":"Sahîh (Elbânî). İbn Mâce: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_183.json","ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَافْتَحْ لِي أَبْوَابَ فَضْلِكَ","latin":"Allâhümmağfirlî zünûbî, veftah lî ebvâbe fadlik","tr":"Rabbim! Günahlarımı bağışla ve bana lütfunun kapılarını aç.","en":"O Lord pardon my sins, and open the gates of Your blessings for me."},{"id":184,"title":"Camide Kayıp Eşya İlan Eden Kişiye Söylenecek Dua","ref":"Sahîh (Elbânî). Tirmizî: 1321","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_184.json","ar":"لَا رَدَّهَا اللَّهُ عَلَيْكَ","latin":"Lâ raddehAllâhu aleyke","tr":"Allah onu sana geri vermesin.\n\nZira camiler bu amaç için inşa edilmemiştir.","en":"May Allah not return it to you.\n\nThis is because the mosques were not built for this purpose."},{"id":185,"title":"Camide Ticaret Yapan Kişiye Söylenecek Dua","ref":"Sahîh (Elbânî). Tirmizî: 1321","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_185.json","ar":"لَا أَرْبَحَ اللَّهُ تِجَارَتَكَ","latin":"Lâ erbahAllâhu ticâreteke","tr":"Allah ticaretine kâr vermesin.\n\nZira camiler bu amaç için inşa edilmemiştir.","en":"May Allah not profit your business.\n\nThis is because the mosques were not built for this purpose."},{"id":186,"title":"Namaz Duası (Namazın Başlangıcında)","ref":"Müslim: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_186.json","ar":"وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ، إِنَّ صَلَاتِي، وَنُسُكِي، وَمَحْيَايَ، وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ اَللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلَّا أَنْتَ لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ بِيَـدَيْكَ، وَالشَّـرُّ لَيْسَ إِلَيْـكَ، أَنَا بِكَ وَإِلَيْكَ، تَبارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتوبُ إِلَيْكَ","latin":"Veccehtu vechi lillezî fetaras-semâvâti vel-arda hanîfen ve mâ ene mine'l-müşrikîn, inne salâtî ve nüsükî ve mahyâye ve memâtî lillâhi rabbi'l-âlemîn, lâ şerîke leh, ve bi-zâlike ümirtü ve ene mine'l-müslimîn. Allâhümme ente'l-melikü lâ ilâhe illâ ente. Ente Rabbî ve ene abdüke, dhalemtü nefsî va'teraftü bi-zenbî fağfirlî zünûbî cemîan innehû lâ yağfiru'z-zünûbe illâ ente. Vahdinî li-ahsani'l-ahlâkı lâ yehdî li-ahsanihâ illâ ente, vasrif annî seyyieha lâ yasrifu annî seyyieha illâ ente, Labbeyk ve sa'deyk, vel-hayru küllühû bi-yedeyke, veş-şerru leyse ileyke, ene bike ve ileyke, tebârekteye ve teâleyte, estağfirüke ve etûbü ileyke","tr":"Yüzümü, gökleri ve yeri yaratan Allah'a tam bir teslimiyet içinde döndürdüm; ben müşriklerden değilim. Şüphesiz namazım, kurbanım, hayatım ve ölümüm, âlemlerin Rabbi Allah içindir; O'nun ortağı yoktur. Ben bununla emrolundum ve ben müslümanlardanım. Allah'ım! Sen Meliksin, Senden başka hak ilah yoktur. Sen Rabbimsin, ben Senin kulunum; kendime zulmettim ve günahımı itiraf ettim; tüm günahlarımı bağışla, zira Senden başka günahları bağışlayan yoktur. Beni en güzel ahlaka yönelt, zira Senden başka kimse en güzel ahlaka yöneltemez; kötü ahlakı benden uzaklaştır, zira Senden başka kimse onu benden uzaklaştıramaz. Buyur, emrine hazırım; tüm hayır Senin elindedir, şer Sana nisbet edilmez; Seninle ve Sana dönüyorum; mübarek ve yücesin, Senden bağışlanma diler ve Sana tevbe ederim.","en":"I have turned my face sincerely towards He who has brought forth the heavens and the Earth and I am not of those who associate (others with Allah). Indeed my prayer, my sacrifice, my life and my death are for Allah, Lord of the worlds, no partner has He, with this I am commanded and I am of the Muslims. O Allah, You are the Sovereign, none has the right to be worshipped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You. Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You."},{"id":187,"title":"Namazda Tekbirden Sonra Okunacak Dua","ref":"Buhârî: 744","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_187.json","ar":"اَللَّهُمَّ بَاعِدْ بَيْنِيْ وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اَللَّهُمَّ نَقِّنِيْ مِنَ الْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اَللَّهُمَّ اغْسِلْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ","latin":"Allâhümme bâid beynî ve beyne hatâyâye kemâ bâadte beynel-meşrıkı vel-mağrib, Allâhümme nekkınî mine'l-hatâyâ kemâ yünekkâ's-sevbü'l-ebyadu mine'd-denesi, Allâhümmağsil hatâyâye, bil-mâi ves-selci vel-bered","tr":"Allah'ım! Doğu ile batıyı birbirinden ne kadar uzak kıldıysan, beni de günahlarımdan o kadar uzak tut. Allah'ım! Beyaz elbise kirden nasıl temizlenirse, beni de hatalarımdan öyle temizle. Allah'ım! Hatalarımı su, kar ve doluyla yıkayıp temizle.\n\nEbû Hüreyre (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) tekbir ile Kur'ân tilavetinin başlangıcı arasında kısa bir sessizlik bırakırdı. Peygambere (ﷺ) 'Anam babam sana feda olsun! Tekbir ile tilavetin arasındaki o kısa sessizlikte ne söylüyorsunuz?' diye sordum. Peygamber (ﷺ) şöyle buyurdu: 'Şöyle derim: (Yukarıdaki dua okunur)'","en":"O Allah! separate me from my sins as You have separated the East from the West. O Allah, cleanse me of my transgressions as the white garment is cleansed of stains. O Allah! wash away my sins with ice and water and frost.\n\nNarrated by Abu Huraira (RA): Allah's Messenger (ﷺ) used to keep silent between the Takbir and the recitation of Qur'an and that interval of silence used to be a short one. I said to the Prophet (ﷺ) \"May my parents be sacrificed for you! What do you say in the pause between Takbir and recitation?\" The Prophet (ﷺ) said, \"I say, (The dua is Mentioned above)"},{"id":188,"title":"Teheccüd Namazına Başlarken Okunacak Dua","ref":"Müslim: 770","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_188.json","ar":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ وَإِسْرَافِيلَ فَاطِرَ السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ اِهْدِنِيْ لِمَا اخْتُلِفَ فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِيْ مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيْمٍ","latin":"Allâhümme Rabbe Cibrâîle ve Mîkâîle ve İsrâfîle, Fâtıras-semâvâti vel-ardi, Âlime'l-ğaybi veş-şehâdeti, ente tahkümü beyne ibâdike fîmâ kânû fîhi yahtelifûn. İhdinî limahtulife fîhi mine'l-hakkı bi-iznike, inneke tehdî men teşâü ilâ sırâtın müstakîm","tr":"Allah'ım! Cibrîl, Mîkâil ve İsrâfîl'in (büyük meleklerin) Rabbi, gökleri ve yeri yaratan, gizliyi ve aşikârı bilen! Sen, kulların arasında ayrılığa düştükleri konularda hüküm verensin. İzninle, ayrılığa düştükleri hakka beni yönelt; şüphesiz Sen, dilediğini doğru yola iletirsin.\n\nÂişe (ra) şöyle demiştir: Peygamber (ﷺ) gece (teheccüd) namazına başlarken bu duayı okurdu.","en":"O Allah, Lord of Jibra-eel, Meeka-eel and Israfeel (great angles), Creator of the heavens and the Earth, Knower of the seen and the unseen. You are the arbitrator between Your servants in that which they have disputed. Guide me to the truth by Your leave, in that which they have differed, for verily You guide whom You will to a straight path.\n\nAyesha said that the Prophet (ﷺ) used to recite this dua at the beginning of the night (tahajjud) prayer."},{"id":189,"title":"Teheccüd Namazı Duası (Başlangıçta)","ref":"Buhârî: 1120","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_189.json","ar":"اَللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ قَيِّمُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ وَلَكَ الْحَمْدُ، لَكَ مُلْكُ السَّمَوَاتِ وَالْأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ نُورُ السَّمَوَاتِ وَالْأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، وَلِقَاؤُكَ حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ ﷺ حَقٌّ، وَالسَّاعَةُ حَقٌّ، اَللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ (لَا إِلَهَ غَيْرُكَ)","latin":"Allâhümme lekel-hamd. Ente kayyimüs-semâvâti vel-ardi ve men fîhinne. Ve lekel-hamd, leke mülküs-semâvâti vel-ardi ve men fîhinne. Ve lekel-hamd, ente nûrus-semâvâti vel-ard. Ve lekel-hamd, entel-hakku ve va'dukel-hakku, ve likâüke hakkun, ve kavlüke hakkun, vel-cennetu hakkun ven-nâru hakkun ven-nebiyyûne hakkun. Ve Muhammedün (ﷺ) hakkun, ves-sâatü hakkun. Allâhümme leke eslemtü ve bike âmentü, ve aleyke tevekkeltu, ve ileyke enebtü ve bike hâsemtü, ve ileyke hâkemtü fağfirlî mâ kaddemtü ve mâ ahhertü ve mâ esrertü ve mâ a'lentü, entel-mukaddimü ve entel-muahhiru, lâ ilâhe illâ ente (bir rivayette lâ ilâhe illâ ente yerine lâ ilâhe ğayruke)","tr":"Allah'ım! Tüm hamd Sanadır. Sen göklerin, yerin ve içindekilerin kayyûmusun. Tüm hamd Sanadır; göklerin, yerin ve içindekilerin mülkü Senindir. Tüm hamd Sanadır; Sen göklerin ve yerin nûrusun. Tüm hamd Sanadır; Sen göklerin ve yerin Melikisisin. Tüm hamd Sanadır; Sen Hak'sın, vaadin Hak'tır, Sana kavuşmak Hak'tır, sözün Hak'tır, cennet Hak'tır, cehennem Hak'tır, nebîler Hak'tır. Hz. Muhammed (ﷺ) Hak'tır, kıyamet saati Hak'tır. Allah'ım! Sana teslim oldum, Sana iman ettim, Sana tevekkül ettim, Sana yöneldim, Seninle (düşmanlara karşı) mücadele ettim ve Seni hakem kıldım. Önceki ve sonraki, gizli ve aşikâr tüm günahlarımı bağışla. Sen öne geçirensin ve Sen geri bırakansın. Senden başka hak ilah yoktur (bir rivayette: Senden başka ilah yoktur).","en":"O Allah! All the praises are for you, You are the Holder of the Heavens and the Earth, And whatever is in them. All the praises are for You; You have the possession of the Heavens and the Earth And whatever is in them. All the praises are for You; You are the Light of the Heavens and the Earth And all the praises are for You; You are the King of the Heavens and the Earth; And all the praises are for You; You are the Truth and Your Promise is the truth, And to meet You is true, Your Word is the truth And Paradise is true And Hell is true And all the Prophets (Peace be upon them) are true; And Muhammad (ﷺ) is true, And the Day of Resurrection is true. O Allah ! I surrender (my will) to You; I believe in You and depend on You. And repent to You, And with Your help I argue (with my opponents, the non-believers) And I take You as a judge (to judge between us). Please forgive me my previous And future sins; And whatever I concealed or revealed And You are the One who make (some people) forward And (some) backward. There is none to be worshipped but you."},{"id":190,"title":"Teheccüd Sırasında Okunacak Dua (Başlangıçta)","ref":"Müslim: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_190.json","ar":"اَللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، أَنْتَ رَبِّي وَأَنَا عَبْدُكَ، ظَلَمْتُ نَفْسِي وَاعْتَرَفْتُ بِذَنْبِي فَاغْفِرْ لِي ذُنُوبِي جَمِيعًا إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، وَاهْدِنِي لِأَحْسَنِ الْأَخْلَاقِ لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَاصْرِفْ عَنِّي سَيِّئَهَا، لَا يَصْرِفُ عَنِّي سَيِّئَهَا إِلاَّ أَنْتَ.","latin":"Allâhümme entel-melikü lâ ilâhe illâ ente. Ente Rabbî ve ene abdüke, dhalemtü nefsî va'teraftü bi-zenbî fağfirlî zünûbî cemîan innehû lâ yağfiru'z-zünûbe illâ ente. Vahdinî li-ahsani'l-ahlâkı lâ yehdî li-ahsanihâ illâ ente, vasrif annî seyyiehâ lâ yasrifu annî seyyiehâ illâ ente","tr":"Allah'ım! Sen Meliksin, Senden başka hak ilah yoktur. Sen Rabbimsin, ben Senin kulunum; kendime zulmettim ve günahımı itiraf ettim; tüm günahlarımı bağışla, zira Senden başka günahları bağışlayan yoktur. Beni en güzel ahlaka yönelt, zira Senden başka kimse en güzel ahlaka yöneltemez; kötü ahlakı benden uzaklaştır, zira Senden başka kimse onu benden uzaklaştıramaz.","en":"O Allah, You are the Sovereign, none has the right to be worshipped except You. You are my Lord and I am Your servant, I have wronged my own soul and have acknowledged my sin, so forgive me all my sins for no one forgives sins except You. Guide me to the best of characters for none can guide to it other than You, and deliver me from the worst of characters for none can deliver me from it other than You."},{"id":191,"title":"Namazın Başlangıcında Okunan Dua (Tekbirden Sonra)","ref":"Müslim: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_191.json","ar":"لَبَّيْكَ وَسَعْدَيْكَ، وَالْخَيْرُ كُلُّهُ بِيَـدَيْكَ، وَالشَّـرُّ لَيْسَ إِلَيْـكَ، أَنَا بِكَ وَإِلَيْكَ، تَبَارَكْتَ وَتَعَالَيْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","latin":"Labbeyk ve sa'deyk, vel-hayru küllühû bi-yedeyke, veş-şerru leyse ileyke, ene bike ve ileyke, tebârekteye ve teâleyte, estağfirüke ve etûbü ileyke","tr":"Buyur, emrine hazırım; tüm hayır Senin elindedir, şer Sana nisbet edilmez; Seninle ve Sana dönüyorum; mübarek ve yücesin, Senden bağışlanma diler ve Sana tevbe ederim.","en":"Here I am, in answer to Your call, happy to serve you. All good is within Your hands and evil does not stem from You. I exist by your will and will return to you. Blessed and High are You, I seek Your forgiveness and repent unto You."},{"id":192,"title":"Namazın Başlangıcında Okunan Dua (Allâhu Ekber Kebîra)","ref":"Hasen li-ğayrihî (Şuayb el-Arnaût). Ebû Dâvûd: 764","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_192.json","ar":"اَللَّهُ أَكْبَرُ كَبِيرًا، اَللَّهُ أَكْبَرُ كَبِيرًا، اَللَّهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","latin":"Allâhu ekber kebîra, Allâhu ekber kebîra, Allâhu ekber kebîra, vel-hamdü lillâhi kesîra, vel-hamdü lillâhi kesîra, vel-hamdü lillâhi kesîra, ve sübhânAllâhi bükraten ve asîla","tr":"Allah her şeyden en büyük, pek büyüktür. Allah her şeyden en büyük, pek büyüktür. Allah her şeyden en büyük, pek büyüktür. Hamd Allah'a, bol bol. Hamd Allah'a, bol bol. Hamd Allah'a, bol bol. Allah sabah akşam her türlü noksanlıktan münezzehtir.","en":"Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Praise is to Allah, abundantly. Glory is to Allah, at the break of day and at its end."},{"id":195,"title":"Rükûda Okunacak Dua (Sübhâne Rabbiye'l-Azîm)","ref":"Sahîh (Elbânî). Tirmizî: 262","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_195.json","ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ","latin":"Sübhâne Rabbiye'l-Azîm","tr":"Yüce Rabbimi her türlü noksanlıktan tenzih ederim.\n\nBu dua kalbin duygu ve huşusuyla tekrarlanır. Bu tesbihi en az üç kez okumak Resûlullah'ın (ﷺ) sünnetidir ve O'nun emridir. Rivayetlerin büyük çoğunluğu 'Sübhâne Rabbiye'l-Azîm' şeklindedir; bazı hadislerde ise 'Sübhâne Rabbiye'l-Azîm ve Bihamdihî' şeklinde geçmektedir.","en":"Glory to my Lord the Exalted.\n\nThe dua will be repeated with the emotions of the mind. Reciting this Tasbeeh at least three times is the conduct and instruction of Rasulullah (ﷺ). Most of the narrations have \"Subhaana Rabbiyal-'Adheem\" and some of the hadiths have \"Subhaana Rabbiyal-'Adheem wa Bihamdihi\"."},{"id":196,"title":"Rükû Duası (Sübhâne Rabbiye'l-Azîm ve Bihamdihî)","ref":"Hasen Sened (Şuayb el-Arnaût). Ebû Dâvûd: 870","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_196.json","ar":"سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ","latin":"Sübhâne Rabbiye'l-Azîm ve bihamdihî","tr":"Yüce Rabbimi hamd ile tenzih ederim.","en":"Glory and praise be to my mighty Lord."},{"id":197,"title":"Rükûda Okunacak Dua (Sübbûhun Kuddûsun Rabbü'l-Melâiketi ve'r-Rûh)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 872","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_197.json","ar":"سُبُّوْحٌ قُدُّوْسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوْحِ","latin":"Sübbûhun, Kuddûsun, Rabbü'l-melâiketi ve'r-rûh","tr":"Seni her türlü noksanlıktan tenzih ederim; Sen en Kutsal'sın; meleklerin ve Rûh'un Rabbisin.\n\nÂişe (ra) şöyle demiştir: Resûlullah (ﷺ) bunu rükûda ve secdede okurdu.","en":"Glory (to You), Most Holy (are You), Lord of the angels and the Spirit.\n\nAyesha (RA) said that Rasulullah (ﷺ) used to recite it in rukoo and sujood."},{"id":198,"title":"Rükû Duası (Allâhümme Leke Reka'tü ve Bike Âmentü)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 760","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_198.json","ar":"اَللَّهُمَّ لَكَ رَكَعْتُ وَبِكَ آمَنْتُ وَلَكَ أَسْلَمْتُ خَشَعَ لَكَ سَمْعِيْ وَبَصَرِيْ وَمُخِّيْ وَعِظَامِيْ وَعَصَبِيْ","latin":"Allâhümme leke reka'tü, ve bike âmentü, ve leke eslemtü, haşea leke sem'î, ve basarî, ve muhhî, ve idhâmî, ve asabî","tr":"Allah'ım! Sana rükû ettim, Sana iman ettim, Sana teslim oldum. İşitme duyum, görme duyum, beyin ve kemiklerim, sinirlerim Senin önünde boyun eğdi.\n\nAlî (ra) şöyle demiştir: Resûlullah (ﷺ) rükûda bu sözleri söylerdi.","en":"O Allah, to You I bow (in prayer) and in You I believe and to You I have submitted. Before You my hearing is humbled, as is my sight, my mind, my bones, my nerves.\n\nAli (RA) said, Rasulullah (ﷺ) used to say these words in rukoo."},{"id":199,"title":"Rükûda Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 873","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_199.json","ar":"سُبْحَانَ ذِي الْجَبَرُوْتِ وَالْمَلَكُوْتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ","latin":"Sübhâne zil-ceberûti vel-melekûti vel-kibriyâi vel-azameh","tr":"Kudret, mülk, azamet ve yücelik sahibi olan Sen'i tenzih ederim.\n\nArdından secdeye gitti ve kıyamda Âl-i İmrân suresini okuduğu kadar secdede kaldı, sonra diğer sureleri peş peşe okudu.","en":"Glory is to You, Master of power, of dominion, of majesty and greatness.\n\nThen he prostrated and paused as long as he stood and recited Surat Aal Imran and then recited other surahs one after another."},{"id":200,"title":"Rükûda Okunacak Dua (Sübhâneke ve Bihamdike Estağfirüke)","ref":"Hasen (Elbânî). Silsiletü's-Sahîha: 3032","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_200.json","ar":"سُبْحَانَكَ وَبِحَمْدِكَ أَسْتَغْفِرُكَ وَأَتُوْبُ اِلَيْكَ","latin":"Sübhâneke ve bihamdike, estağfirüke ve etûbü ileyke","tr":"Allah'ım! Seni hamd ile tenzih ederim. Senden bağışlanma diler ve Sana tevbe ederim.","en":"Glory is to You O Allah, and praise. I ask you for forgiveness and I turn to you (from sinning)."},{"id":201,"title":"Rükûda Okunacak Dua (Bağışlanma Duası)","ref":"[1] Buhârî: 794 [2] Nasr Suresi 110:3","url":"https://quran.com/110/3","ar":"سُبْحَانَكَ اَللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اَللَّهُمَّ اغْفِرْ لِي","latin":"Sübhâneke Allâhümme Rabbenâ ve bihamdike Allâhümmağfirlî","tr":"Allah'ım! Rabbimiz, Seni hamd ile tenzih ederim. Allah'ım! Beni bağışla. [1]\n\nÂişe (ra) şöyle rivayet etmiştir: Kur'ân'ın emri doğrultusunda [2] Resûlullah (ﷺ) rükûda ve secdede bu duayı çokça okurdu.","en":"Glory is to You, O Allah, our Lord, and praise is Yours. O Allah, forgive me. [1]\n\nNarrated from Aisha (RA), she said that according to the instructions of the Qur'an, [2] the Messenger of Allah (ﷺ) used to say this dua more and more in bowing down and prostration - (The dua is mentioned above)"},{"id":202,"title":"Rükûdan Sonra Okunacak Dua (Semiallâhu Limen Hamideh)","ref":"Buhârî: 796","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_202.json","ar":"سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ","latin":"Semiallâhu limen hamideh","tr":"Allah, kendine hamd edeni işitir.","en":"Allah hears whoever praises Him."},{"id":203,"title":"Rükûdan Sonra Okunacak Dua (Allâhümme Rabbenâ Lekel-Hamd)","ref":"Müslim: 477","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_203.json","ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","latin":"Allâhümme Rabbenâ lekel-hamdü mil'es-semâvâti ve mil'el-ardı, ve mil'e mâ şi'te min şey'in ba'du, ehleth-senâi vel-mecdi, ahakku mâ kâlel-'abdü, ve küllünâ leke 'abdün. Allâhümme lâ mâni'a limâ a'tayte, ve lâ mu'tiye limâ mena'te, ve lâ yenfe'u zel-ceddi minkel-cedd","tr":"Allah'ım! Rabbimiz, göklerin tümünü, yerin tümünü ve bunların ardından dilediğin her şeyi dolduracak kadar Sana hamd olsun. Övgü ve yüceliğe layık olan Sen'sin; bir kulun söyleyebileceği en layık sözdür — ve hepimiz Senin kuluğuz. Allah'ım! Senin verdiğini engelleyecek kimse yoktur, engellediğini verecek kimse yoktur ve hiçbir servet sahibinin serveti Senin katında ona fayda sağlayamaz.","en":"O Allah, our Rabb (Lord), to You is praise in all the heavens and all the earth, and all that You Will (to create) afterwards, O You, Who are worthy of praise and glory, the most worthy of what a slave says - and we are all Your slaves: no one can withhold what You give, or give what You withhold, and riches cannot avail a wealthy person against You."},{"id":204,"title":"Rabbenâ Lekel-Hamd (Rükûdan Sonra Okunacak Dua)","ref":"Buhârî: 796","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_204.json","ar":"(اَللَّهُمَّ) رَبَّنَا لَكَ الْحَمْدُ","latin":"(1) Rabbenâ lekel-hamd (2) Allâhümme Rabbenâ lekel-hamd","tr":"[1] Rabbimiz, hamd Sanadır. [2] Allah'ım, Rabbimiz, hamd Sanadır.","en":"[1] Our Lord, to You be the praise. [2] O Allah, our Lord, to You be the praise."},{"id":205,"title":"Rabbenâ Vel-Hamd (Rükûdan Sonra Okunacak Dua)","ref":"Buhârî: 795","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_205.json","ar":"(اَللَّهُمَّ) رَبَّنَا وَلَكَ الْحَمْدُ","latin":"(1) Rabbenâ ve lekel-hamd (2) Allâhümme Rabbenâ ve lekel-hamd","tr":"[1] Rabbimiz ve hamd Sanadır. [2] Allah'ım, Rabbimiz ve hamd Sanadır.\n\nRükûdan sonra bir süre dik durulmalıdır. Bu herkes için vaciptir. Dik durmadan secdeye gidilirse namaz bozulur. Rükû halinde bu dört duadan biri okunmalıdır. Bu duaları dönüşümlü olarak okumak tavsiye edilir.","en":"[1] Our Lord and to You be the praise. [2] O Allah, our Lord and to You be the praise.\n\nAfter rukoo' one should stand straight for a while. It is obligatory upon all. If anyone goes to prostration before stand straight (for a while) then it will invalidate his salaah. In the state of rukoo' one should say one of these four duas. It is recommended to say these supplications alternatively."},{"id":207,"title":"Rükûdan Kalkarken Okunacak Dua","ref":"Müslim: 476","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_207.json","ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ","latin":"Allâhümme Rabbenâ lekel-hamdü miles-semâvâti ve miles-ardı ve millea mâ beynehumâ, ve millea mâ şi'te min şeyin ba'dü","tr":"Hamd Sana olsun, Allah'ım, Rabbimiz! Hamd Sanadır; gökleri doldurur, yeri doldurur, aralarındaki her şeyi tamamlar ve ardından dilediğin her şeyi tamamlar.\n\nİbn Ebî Evfâ (ra), İbn Abbâs (ra), Ali (ra) ve diğer Sahâbîler, Peygamber'in (ﷺ) rükûdan kalktığında bu sözleri söylediğini bildirmiştir.","en":"Praise be to You, O Allah, our Lord! Praise be to You, it fills the heavens, fills the earth, completes all that is in between them, and then it completes whatever You will.\n\nIbn Abi Aufa (R), Ibn Abbas (RA), Ali (RA) and other Companions said that the Prophet (ﷺ) used to say these words when he stand up from rukoo'."},{"id":208,"title":"Rükûdan Kalkarken Okunacak Dua 2","ref":"Müslim: 478","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_208.json","ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ وَمَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيءٍ بَعْدُ أَهْلَ الثَّنَاءِ وَالْمَجْدِ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","latin":"Allâhümme Rabbenâ lekel-hamd, miles-semâvâti ve miles-ardı ve mâ beynehumâ, ve millea mâ şi'te min şeyin ba'dü, ehleth-senâi vel-mecdi. Lâ mâni'a limâ a'tayte, ve lâ mu'tiye limâ mena'te, ve lâ yenfe'u zel-ceddi minkel-cedd","tr":"Allah'ım! Rabbimiz, gökleri, yeri ve aralarındaki her şeyi dolduracak kadar ve bunların dışında dilediğin her şeyi dolduracak kadar Sana hamd olsun. Her övgü ve yüceliğe layık olan Sensin. Senin verdiğini engelleyecek kimse yoktur, engellediğini verecek kimse yoktur ve büyük bir kimsenin büyüklüğü Senin katında ona fayda sağlayamaz.","en":"Allah! our Lord, to Thee be the praise that would fill the heavens and the earth and that which is between them, and that which will please Thee besides (them). Worthy art Thou of all praise and glory. No one can withhold what Thou givest, or give what Thou withholdest. And the greatness O! the great availeth not against Thee."},{"id":209,"title":"Allah'ı Öven Dua (Rükûdan Sonra Okunacak Dua)","ref":"Hasen (Elbânî). Nesâî: 931","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_209.json","ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ مُبَارَكًا عَلَيْهِ كَمَا يُحِبُّ رَبُّنَا وَيَرْضَى","latin":"Elhamdü lillâhi hamden kesîran tayyiben mübâreken fîhi mübâreken aleyhi kemâ yühibbü Rabbünâ ve yerdâ","tr":"Hamd olsun Allah'a; Rabbimizin sevdiği ve razı olduğu şekilde çok, güzel ve bereketli hamd.\n\nRifâa b. Râfi' (ra) şöyle demiştir: «Peygamber'in (ﷺ) arkasında namaz kılıyordum, hapşırdım ve (yukarıdaki duayı) söyledim. Namazı bitirdiğinde Resûlullah (ﷺ) 'Namazda kim konuştu?' dedi. Kimse bir şey söylemedi. Sonra ikinci kez 'Namazda kim konuştu?' dedi. Rifâa b. Râfi b. Afrâh (ra) 'Ben, ey Allah'ın Resûlü' dedi. 'Şöyle dedim: (yukarıdaki dua)' dedi. Peygamber (ﷺ) şöyle buyurdu: 'Canım elinde olan'a yemin olsun ki, otuzdan fazla melek onu hangisi önce yazacak diye yarıştı.'»","en":"Praise be to Allah, much good and blessed praise as our Lord loves and is pleased with\n\nRifa'ah bin Rafi' (RA) said that: \"I prayed behind the Prophet (ﷺ) and I sneezed and said: (the dua is mentioned above) When he finished praying, the Messenger of Allah (ﷺ) said: 'Who is the one who spoke during the prayer?' But no one said anything. Then he said it a second time: 'Who is the one who spoke during the prayer?' So Rifa'ah bin Rafi bin Afrah (RA) said: 'It was me, O Messenger of Allah.' He said: 'I said: (the dua is mentioned above)' The Prophet (ﷺ) said: 'By the One in Whose hand is my soul, thirty-odd angels hastened to see which of them would take it up.'"},{"id":213,"title":"Secdede Okunacak Dua (Sübhâne Rabbiye'l-A'lâ)","ref":"Müslim: 772","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_213.json","ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى","latin":"Sübhâne Rabbiye'l-A'lâ","tr":"En Yüce Rabbimi tenzih ederim.\n\nBu dua zihin ve kalp duygusuyla tekrar tekrar okunmalıdır. Bu tesbîhi en az üç kez okumak Resûlullah'ın (ﷺ) sünneti ve emridir. Rivayetlerin çoğu 'Sübhâne Rabbiye'l-A'lâ' ifadesini, bazı hadisler ise 'Sübhâne Rabbiye'l-A'lâ ve bihamdihî' ifadesini zikretmektedir. Rahmet ayetlerini okuduktan sonra durur ve Allah'tan isterdi; azap ayetlerini okuduktan sonra durur ve Allah'a sığınırdı.","en":"Glory is to my Lord, the Most High.\n\nThis dua should be repeat again and again with the emotion of the mind. Reciting this tasbeeh at least three times is the conduct and instruction of Rasulullah (ﷺ). Most of the narrations mention \"Subhaana Rabbiyal-A 'laa\" and some of the hadiths describe \"Subhana Rabbiyal-A 'laa wa bihamdihi\". After reciting every verse of mercy, he stopped and asked Allah for it, and after reciting every verse of punishment, he stopped and asked Allah for refuge from it."},{"id":214,"title":"Secde için Dua (Secde Duası)","ref":"Hasen Senedli (Şuayb el-Arnaût). Ebû Dâvûd: 870","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_214.json","ar":"سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ","latin":"Sübhâne Rabbiye'l-A'lâ ve bihamdihî","tr":"En Yüce Rabbimi hamd ile tenzih ederim.","en":"Glory and praise be to my most high Lord."},{"id":215,"title":"Secdede Okunacak Dua (Allâhümmağfirlî)","ref":"Müslim: 483","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_215.json","ar":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ كُلَّهُ دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَّتَهُ وَسِرَّهُ","latin":"Allâhümmağfirlî zenbî küllehû, diqqahû ve cillehû, ve evvelehû ve âhirehû ve alâniyetehû ve sirreh","tr":"Allah'ım! Tüm günahlarımı bağışla; küçük olanını ve büyük olanını, öncekini ve sonrakini, alenî olanını ve gizli olanını.","en":"O Allah, forgive me all my sins, great and small, the first and the last, those that are apparent and those that are hidden."},{"id":216,"title":"Secdede Okunacak Dua (Allâhümme İnnî Eûzü Biridâke)","ref":"Müslim: 486, Sahîh (Elbânî). Tirmizî: 3566","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_216.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوْذُ بِكَ مِنْكَ، لَا أُحْصِيْ ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","latin":"Allâhümme innî eûzü biridâke min sahatike, ve bimuâfâtike min ukûbetike ve eûzü bike minke, lâ uhsî senâen aleyke, ente kemâ esneyte alâ nefsike","tr":"Allah'ım! Gazabından rızana, cezandan affına sığınırım. Senden Sana sığınırım. Seni övmenin sonsuzluğunu sayamam. Sen, kendini övdüğün gibisin.","en":"O Allah, I seek protection in Your pleasure from Your anger, and I seek protection in Your forgiveness from Your punishment. I seek protection in You from You. I cannot count Your praises. You are as You have praised Yourself."},{"id":217,"title":"Secdede Okunacak Dua (Nûr Duası)","ref":"Buhârî: 6316, Müslim: 763","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_217.json","ar":"اَللَّهُمَّ اجْعَلْ فِي قَلْبِيْ نُورًا، وَفِي سَمْعِيْ نُورًا، وَفِي بَصَرِيْ نُورًا، وَعَنْ يَمِيْنِيْ نُورًا، وَعَنْ شِمَالِيْ نُورًا، وَأَمَامِيْ نُورًا، وَخَلْفِي نُورًا، وَفَوْقِيْ نُورًا، وَتَحْتِيْ نُورًا، وَاجْعَلْ لِي نُورًا (وَاجْعَلْنِيْ نُورًا)، وَاجْعَلْ فِي نَفْسِي نُورًا، (وَفِي عَصَبِيْ نُورًا، وَفِي لَحْمِي نُورًا، وَفِي دَمِيْ نُورًا، وَفِي شَعْرِيْ نُورًا، وَفِي بَشَرِيْ نُورًا)، اَللَّهُمَّ أَعْطِنِيْ نُورًا","latin":"Allâhümmec'al fî kalbî nûren, ve fî sem'î nûren, ve fî basarî nûren, ve an yemînî nûren, ve an şimâlî nûren, ve emâmî nûren, ve halfî nûren, ve fevkî nûren, ve tahtî nûren, vec'al lî nûren (vec'alnî nûren), vec'al fî nefsî nûren, (ve fî asabî nûren, ve fî lahmî nûren, ve fî demî nûren, ve fî şa'rî nûren, ve fî beşerî nûren), Allâhümme a'tinî nûren","tr":"Allah'ım! Kalbime nûr koy, kulaklarıma nûr, gözlerime nûr, sağıma nûr, soluma nûr, önüme nûr, arkama nûr, üstüme nûr, altıma nûr koy. Allah'ım! Bana nûr ver, beni nûr yap, ruhumda nûr kıl, sinirlerimde nûr, etimde nûr, kanımda nûr, saçlarımda nûr, derimde nûr kıl. Allah'ım! Bana nûr ihsan et.","en":"O Allah, place light in my heart, and in my ears light and in my sight light, and to my right light, and to my left light, and before me light and behind me light, and above me light, and below me light. O Allah, Make for me light, and make me a light, and place in my soul light, and place light in my nerves, and in my flesh light and in my blood light and in my hair light and in my skin light. O Allah, grant me light."},{"id":219,"title":"Secdede Okunacak Dua (Sübbûhun Kuddûsun Rabbü'l-Melâiketi ve'r-Rûh)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 872","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_219.json","ar":"سُبُّوحٌ، قُدُّوسٌ، رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","latin":"Sübbûhun, Kuddûsun, Rabbü'l-melâiketi ve'r-rûh","tr":"Her türlü noksanlıktan münezzehsin, her türlü kusurdan mukaddessin, meleklerin ve Rûh'un (Cebrâil'in) Rabbisin.","en":"Glory (to You), Most Holy (are You), Lord of the angels and the Spirit."},{"id":220,"title":"Secdede Okunacak Dua (Allâhümme Leke Secadtü ve Leke Eslemtü)","ref":"Sahîh (Elbânî). Nesâî: 1126","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_220.json","ar":"اَللَّهُمَّ لَكَ سَجَدْتُ وَلَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَصَوَّرَهُ، فَأَحْسَنَ صُوْرَتَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","latin":"Allâhümme leke secadtü ve leke eslemtü, ve bike âmentü, secede vechiye lillezî halakahû ve savverahû fe-ahsene sûretehû ve şakka sem'ahû ve basarahû, tebârekAllâhu ahsenü'l-hâlikîn","tr":"Allah'ım! Sana secde ettim, Sana teslim oldum ve Sana iman ettim. Yüzüm, onu yaratan, şekillendiren ve ona en güzel biçimi veren, işitme ve görme duyularını açan Allah'ın önünde secde etti. Yaratıcıların en hayırlısı olan Allah ne yücedir.","en":"O Allah, to You I prostrate myselfm, to You I have submitted, and in You I believe. My face is prostrated to the One Who created it, fashioned it, and gave it hearing and sight. Blessed is Allah, the Best of creators."},{"id":221,"title":"Secdede Okunacak Dua","ref":"Hasen (Elbânî). Ebû Dâvûd: 873","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_221.json","ar":"سُبْحَانَ ذِي الْجَبَرُوتِ، وَالْمَلَكُوتِ، وَالْكِبْرِيَاءِ، وَالْعَظَمَةِ","latin":"Sübhâne zil-ceberûti vel-melekûti vel-kibriyâi vel-azameh","tr":"Kudret, mülk, azamet ve yücelik sahibi olan Sen'i tenzih ederim.\n\nAvf b. Mâlik el-Eşcaî (ra) şöyle rivayet etmiştir: Resûlullah ile birlikte namaz kılmak için ayağa kalktım. Ayağa kalktı ve Bakara Suresini okudu. Rahmetten bahseden bir ayete gelince durdu ve dua etti; azaptan bahseden bir ayete gelince durdu ve Allah'a sığındı. Sonra rükûya gitti ve (Bakara Suresini okuduğu kadar) rükûda kaldı. Ardından secdeye gitti ve rükûda kaldığı kadar secdede kaldı. Secdede (yukarıdaki duayı) söyledi.","en":"Glory is to You, Master of power, of dominion, of majesty and greatness.\n\nNarrated by Awf ibn Malik al-Ashja'i (RA): I stood up to pray along with the Messenger of Allah (ﷺ); he got up and recited Surat al-Baqarah (Surah 2). When he came to a verse which spoke of mercy, he stopped and made supplication, and when he came to verse which spoke of punishment, he stopped and sought refuge in Allah, then he bowed and paused as long as he stood (reciting Surah al-Baqarah) Then he prostrated and paused as long as he bowed down. In prostration he said- (The dua is mentioned above)"},{"id":222,"title":"İki Secde Arasında Okunacak Dua","ref":"Sahîh (Elbânî). Ebû Dâvûd: 874","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_222.json","ar":"رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي","latin":"Rabbığfirlî, Rabbığfirlî","tr":"Ey Rabbim! Beni bağışla. Rabbim, beni bağışla.\n\nHuzeyfe (ra) şöyle demiştir: Peygamber (ﷺ) iki secde arasında otururken yukarıdaki duayı okurdu.","en":"O My Lord, forgive me. My Lord, forgive me.\n\nHuzaifa (RA) said that the Prophet (ﷺ) used to recite the above mentioned dua while sitting in the middle of two prostrations."},{"id":223,"title":"İki Secde Arasında Okunacak Dua (Allâhümmağfirlî Verhamnî Vehdînî Verzuknî)","ref":"Sahîh (Elbânî). Tirmizî: 284, Hasen (Elbânî). Ebû Dâvûd: 850","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_223.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَعَافِنِي وَاهْدِنِي وَارْزُقْنِي","latin":"Allâhümmağfirlî, verhamnî, ve âfinî, vehdînî, verzuknî","tr":"Allah'ım! Beni bağışla, bana merhamet et, bana sağlık ver, beni doğru yola ilet ve bana rızık ver.\n\nPeygamber (ﷺ) iki secde arasında otururken bu duayı okurdu.","en":"O Allah! Pardon me, have mercy on me, guide me, and grant me sustenance.\n\nThe Prophet (ﷺ) used to say this dua while sitting between two prostrations."},{"id":225,"title":"Kur'ân'daki Secde Ayeti için Dua","ref":"Hasen (Elbânî). Tirmizî: 579","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_225.json","ar":"اَللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا، وَضَعْ عَنِّي بِهَا وِزْرًا، وَاجْعَلْهَا لِي عِنْدَكَ ذُخْرًا، وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ","latin":"Allâhümmektüb lî bihâ indeke ecren, ve da' annî bihâ vizren, vec'alhâ lî indeke zuhrâ, ve tekabbelhâ minnee kemâ tekabbelteha min abdike Dâvûd","tr":"Allah'ım! Bunu benim için katında bir sevap olarak yaz, bu sayede benden bir günah kaldır, onu benim için katında bir hazine yap ve benden kabul et; tıpkı kulun Dâvûd'dan kabul ettiğin gibi.","en":"O Allah, write it as a reward for me, and release me from a sin for it, and make it a treasure for me in Paradise. Accept it from me as You accepted it from your servant Dawud."},{"id":226,"title":"Gece Tilavetinde Secde Duası","ref":"Hasen (Elbânî). Tirmizî: 580","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_226.json","ar":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ","latin":"Secede vechiye lillezî halakahû, ve şakka sem'ahû ve basarahû bi havlihî ve kuvvetih","tr":"Yüzüm, onu yaratan ve O'nun gücü ve kudreti ile ona işitme ve görme duyularını açan Allah'ın önünde secde etti.","en":"I have prostrated my face to the One Who created it, and gave it hearing and sight by His might and His power."},{"id":227,"title":"Secde Ayetlerini Okuduktan Sonra Okunacak Dua","ref":"Sahîh (Elbânî). Tirmizî: 3425, Mü'minûn Suresi 23:14","url":"https://quran.com/23/14","ar":"سَجَدَ وَجْهِيَ لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ، فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ","latin":"Secede vechiye lillezî halakahû, ve şakka sem'ahû ve basarahû bi havlihî ve kuvvetihî. FetebârekAllâhu ahsenü'l-hâlikîn","tr":"Yüzüm, onu yaratan ve O'nun gücü ve kudreti ile ona işitme ve görme duyularını açan Allah'ın önünde secde etti. Yaratıcıların en hayırlısı olan Allah ne yücedir.","en":"I have prostrated my face to the One Who created it, and gave it hearing and sight by His might and His power. So blessed is Allah, the best of creators."},{"id":228,"title":"Teşehhüd Duası (Ettahiyyâtü Lillâhi Ves-Salavâtü)","ref":"Buhârî: 7381","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_228.json","ar":"اَلتَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُوْلُهُ","latin":"Ettahiyyâtü lillâhi ves-salavâtü, vettayyibâtü, es-selâmü aleyke eyyühen-Nebiyyü ve rahmetullâhi ve berekâtühü, es-selâmü aleynâ ve alâ ibâdillâhis-sâlihîn. Eşhedü en lâ ilâhe illAllâhu ve eşhedü enne Muhammeden abdühû ve Resûlüh","tr":"Bütün tazimler Allah'a aittir, bütün salavât ve güzellikler de. Ey Nebi! Sana selam olsun, Allah'ın rahmeti ve bereketi üzerine olsun. Selam bize ve Allah'ın salih kullarına olsun. Şehadet ederim ki Allah'tan başka ilah yoktur ve şehadet ederim ki Muhammed O'nun kulu ve Resûlüdür.\n\nTeşehhüd, çeşitli sahâbîler tarafından (farklı lafızlarla) rivayet edilmiştir. İbn Mes'ûd (ra) şöyle dedi: Peygamber'in arkasında namaz kılıyor ve 'Es-Selâmü alAllâh — Allah'a selam olsun' diyorduk. Peygamber (ﷺ) şöyle buyurdu: 'Allah kendisi es-Selâm'dır (Allah'ın ismi), bu nedenle şöyle deyin: (Yukarıdaki dua)'","en":"All greetings of humility are for Allah, and all prayers and goodness. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous slaves of Allah. I bear witness that there is none worthy of worship but Allah, and I bear witness that Muhammad is His slave and His Messenger.\n\nTashahood was narrated by various companions (with different wordings). Ibn Mas'ud (RA) said, We used to pray behind the Prophet (ﷺ) and used to say: \"As-Salaamu 'Al-Allah. Peace be upon Allah. The Prophet (ﷺ) said, \"Allah himself is As-Salam (Name of Allah), so you should say: (The dua is mentioned above)"},{"id":229,"title":"Salavât-ı Şerîfe (Salavât-ı İbrâhimiyye)","ref":"Buhârî: 3370","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_229.json","ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ اَللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَّعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى إِبْرَاهِيْمَ وَعَلَى آلِ إِبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَّجِيْدٌ","latin":"Allâhümme salli alâ Muhammedin ve alâ âli Muhammedin, kemâ salleyte alâ İbrâhîme ve alâ âli İbrâhîme, inneke Hamîdün Mecîd. Allâhümme bârik alâ Muhammedin ve alâ âli Muhammedin, kemâ bârekte alâ İbrâhîme ve alâ âli İbrâhîme, inneke Hamîdün Mecîd","tr":"Allah'ım! İbrâhim'e ve İbrâhim ailesine rahmet ettiğin gibi Muhammed'e ve Muhammed ailesine rahmet et. Şüphesiz sen Hamîd ve Mecîd'sin. Allah'ım! İbrâhim'i ve İbrâhim ailesini mübarek kıldığın gibi Muhammed'i ve Muhammed ailesini mübarek kıl. Şüphesiz sen Hamîd ve Mecîd'sin.\n\nKa'b b. Ucre (ra) şöyle rivayet etmiştir: Resûlullah'a (ﷺ) şöyle sorduk: 'Ey Allah'ın Resûlü! Allah bize sizi namazda nasıl selamlayacağımızı öğretti; peki sizin üzerinize — ehl-i beytin üzerine — nasıl salavât getirelim?' O (ﷺ) şöyle buyurdu: 'Şöyle deyin: (Yukarıdaki dua)'","en":"O Allah, bestow Your favor on Muhammad (ﷺ) and on the family of Muhammad as You have bestowed Your favor on Ibrahim and on the family of Ibrahim, You are Praiseworthy, Most Glorious. O Allah, bless Muhammad (ﷺ) and the family of Muhammad as You have blessed Ibrahim and the family of Ibrahim, You are Praiseworthy, Most Glorious.\n\nNarrated by Ka`b bin Ujrah (RA): We asked Allah's Messenger (ﷺ) saying, 'O Allah's Messenger (ﷺ)! How should one (ask Allah to) send blessings on you, the members of the family, for Allah has taught us how to salute you (in the prayer)?' He (ﷺ) said, 'Say: (The dua is mentioned above)"},{"id":230,"title":"Teşehhüdden Sonra Okunacak Dua (Salavât-ı Şerîfe)","ref":"Buhârî: 3369","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_230.json","ar":"اَللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى آلِ إِبْرَاهِيْمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إبْرَاهِيْمَ إِنَّكَ حَمِيْدٌ مَجِيْدٌ","latin":"Allâhümme salli alâ Muhammedin ve ezvâcihî ve zürriyyetihî, kemâ salleyte alâ âli İbrâhîme. Ve bârik alâ Muhammedin ve ezvâcihî ve zürriyyetihî, kemâ bârekte alâ âli İbrâhîme. İnneke Hamîdün Mecîd","tr":"Allah'ım! İbrâhim ailesine rahmet ettiğin gibi Muhammed'e, eşlerine ve neslîne rahmet et. İbrâhim ailesini mübarek kıldığın gibi Muhammed'i, eşlerini ve neslîni mübarek kıl. Şüphesiz sen Hamîd ve Mecîd'sin.\n\nEbû Hümeyid (ra) el-Sâidî şöyle rivayet etmiştir: 'Ey Allah'ın Resûlü! Size nasıl salavât getirelim?' diye sordular. Peygamber (ﷺ) şöyle buyurdu: Şöyle deyin — (Yukarıdaki dua)","en":"O Allah, bestow Your favor on Muhammad (ﷺ) and upon his wives and progeny as You have bestowed Your favor upon the family of Ibrahim. And bless Muhammad (ﷺ) and his wives and progeny as You have blessed the family of Ibrahim, You are full of praise, Most Glorious.\n\nNarrated Abu Hamid (RA) Saidi: They asked, “O Messenger of Allah (ﷺ)! How can we recite Durood for you?” Then the Prophet (ﷺ) said, you say - (The dua is mentioned above)"},{"id":231,"title":"Duâ-i Me'sûr 1 (Allâhümme Ellif Beyne Kulûbinâ)","ref":"Daîf (Elbânî). Ebû Dâvûd: 969","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_231.json","ar":"اَللَّهُمَّ أَلِّفْ بَيْنَ قُلُوبِنَا وَأَصْلِحْ ذَاتَ بَيْنِنَا وَاهْدِنَا سُبُلَ السَّلَامِ وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّوْرِ وَجَنِّبْنَا الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْمُ وَاجْعَلْنَا شَاكِرِيْنَ لِنِعْمَتِكَ مُثْنِيْنَ بِهَا قَابِلِيْهَا وَأَتِمَّهَا عَلَيْنَا","latin":"Allâhümme ellif beyne kulûbinâ ve aslih zâte beyninâ vehdînâ sübüles-selâmi, ve neccînâ minez-zulümâti ilen-nûri, ve cennibnel-fevâhişe mâ zahera minhâ ve mâ betan, ve bârik lenâ fî esmâinâ ve ebsârinâ ve kulûbinâ ve ezvâcinâ ve zürriyyâtinâ ve tüb aleynâ inneke ente't-tevvâbü'r-rahîm vec'alnâ şâkirîne li-ni'metike müsninîne bihâ kâbileehâ ve etimme-hâ aleynâ","tr":"Allah'ım! Kalplerimizi birleştir, aramızdaki ilişkiyi düzelt, bizi selâmet yollarına ilet, bizi karanlıktan nûra çıkar, gizli ve açık çirkinliklerden bizi uzak tut, kulaklarımıza, gözlerimize, kalplerimize, eşlerimize ve çocuklarımıza bereket ver, bize tevbe nasip et; Sen tevveleri çok kabul eden, çok merhametlisin. Bizi nimetine şükreden, onu öven, kabul eden ve bize onu eksiksiz ihsan et.\n\nAbdullah b. Mes'ûd (ra) şöyle demiştir: Resûlullah (ﷺ) bize teşehhüdden sonra bu duayı okumayı öğretirdi.","en":"O Allah, join our hearts, mend our social relationship, guide us to the path of peace, bring us from darkness to light, save us from obscenities, outward or inward, and bless our ears, our eyes, our hearts, our wives, our children, and relent toward us; Thou art the Relenting, the Merciful. And make us grateful for Thy blessing and make us praise it while accepting it and give it to us in full.\n\nAbdullah ibn Mas'ud (RA) said: The Messenger of Allah (ﷺ) used to teach us this dua to recite after Tashahhud."},{"id":232,"title":"Duâ-i Me'sûr 2 (Cehennem Azabından Korunma Duası)","ref":"Müslim: 588","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_232.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ","latin":"Allâhümme innî eûzü bike min azâbi cehennem, ve min azâbil-kabr, ve min fitnetil-mahyâ vel-memât, ve min şerri fitnetil-mesîhid-deccâl","tr":"Allah'ım! Cehennem azabından, kabir azabından, hayat ve ölüm fitnesinden ve Mesîh Deccâl fitnesinin şerrinden Sana sığınırım.\n\nResûlullah (ﷺ) şöyle buyurmuştur: Biriniz teşehhüdü okuyunca dört şeyden Allah'a sığınmalıdır ve şöyle demelidir: (Yukarıdaki dua)","en":"O Allah! I seek refuge with Thee from the torment of the Hell, from the torment of the grave, from the trial of life and death and from the evil of the trial of Masih al-Dajjal.\n\nThe Messenger of Allah (ﷺ) said: When any one of you utters tashahhud (in prayer) he must seek refuge in Allah from four (trials) and should thus say : (The dua is mentioned above)"},{"id":233,"title":"Duâ-i Me'sûr 3 (Allâhümmağfirlî Mâ Kaddemtü)","ref":"Müslim: 771","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_233.json","ar":"اَللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümmağfirlî mâ kaddemtü, ve mâ ahhartü, ve mâ esrartü, ve mâ a'lentü, ve mâ esraftü, ve mâ ente a'lemü bihî minnee. Entel-Mukaddimü, ve Entel-Muahhiru lâ ilâhe illâ ente","tr":"Allah'ım! Önceden yaptıklarımı ve sonraya bıraktıklarımı, gizlediklerimi ve açığa vurduklarımı, sınır aştığım şeyleri ve benden daha iyi bildiğin şeyleri bağışla. Sen öne geçirensin ve geri bırakansın. Senden başka ilah yoktur.\n\nTeşehhüdden sonra Resûlullah (ﷺ) selam vermeden önce sonda bu duayı okurdu.","en":"O Allah, forgive me what I have sent before me and what I have left behind me, what I have concealed and what I have done openly, what I have done in excess, and what You are better aware of than I. You are the One Who sends forth and You are the One Who delays. There is none worthy of worship but You.\n\nAfter tashahood, The Messenger of Allah (ﷺ) supplicate this dua at the end, before saying salaam."},{"id":234,"title":"Duâ-i Me'sûr 4 (Allâhümme İnnî Zalemtü Nefsî)","ref":"Buhârî: 834","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_234.json","ar":"اَللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِيْ ظُلْمًا كَثِيْرًا وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ وَارْحَمْنِيْ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","latin":"Allâhümme innî zalemtü nefsî zulmen kesîren, ve lâ yağfiruż-żünûbe illâ ente, fağfirlî mağfireten min indike verhamnî inneke entel-Ğafûrur-Rahîm","tr":"Allah'ım! Kendime çok büyük zulüm ettim; günahları Senden başkası bağışlamaz. Beni katından bir bağışlamayla bağışla ve bana merhamet et. Şüphesiz Sen Ğafûr ve Rahîm'sin.","en":"O Allah, I have greatly wronged myself and no one forgives sins but You. So, grant me forgiveness and have mercy on me. Surely, you are Forgiving, Merciful."},{"id":235,"title":"Duâ-i Me'sûr 5 (Allâhümme Bi İlmikel-Ğayb)","ref":"Sahîh (Elbânî). Nesâî: 1305","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_235.json","ar":"اَللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِيْ مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي اَللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى وَأَسْأَلُكَ نَعِيْمًا لَا يَنْفَدُ وَأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ وَأَسْأَلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا فِتْنَةٍ مُضِلَّةٍ اَللَّهُمَّ زَيِّنَا بِزِيْنَةِ الْإِيْمَانِ وَاجْعَلْنَا هُدَاةً مُهْتَدِيْنَ","latin":"Allâhümme bi-ilmikel-ğaybi ve kudratike alel-halk, ahyinî mâ alimtel-hayâte hayran lî ve teveffenî izâ alimtel-vefâte hayran lî, Allâhümme ve es'eluke haşyeteke fil-ğaybi veş-şehâdeti, ve es'eluke kelimetal-hakkı fir-rıdâ vel-ğadabi, ve es'elükel-kasde fil-fakri vel-ğınâ, ve es'eluke naîmen lâ yenfedü, ve es'eluke kurrate aynin lâ tankati', ve es'elüker-rıdâ ba'del-kadâ, ve es'eluke bardel-ayşi ba'del-mevti, ve es'eluke lezzetenniazri ilâ vechike veş-şevka ilâ likâike fî ğayri darrâe mudırratin ve lâ fitnetin mudılleh, Allâhümme zeyyinnâ bizînetil-îmâni vec'alnâ hudâten muhtedîn","tr":"Allah'ım! Gaybı bilmen ve yaratılış üzerindeki kudretin hakkı için, hayatın benim için hayırlı olduğunu bildiğin müddetçe beni yaşat; ölümün benim için hayırlı olduğunu bildiğinde beni vefat ettir. Allah'ım! Gizlide ve açıkta Senden korkmanı, rıza ve öfke anlarında hakkı söylemeyi, zenginlikte ve yoksullukta tutumluluğu Senden istiyorum. Tükenmeyecek bir nimet, sona ermeyecek bir göz aydınlığı (sevinç) istiyorum. Hükmünden sonra rızayı ve ölümden sonra rahat bir yaşamı Senden istiyorum. Yüzüne bakmaktan duyulan lezzeti ve Sana kavuşmaktan duyulan özlemi; zarar veren bir belâ ve saptıran bir fitne olmaksızın Senden istiyorum. Allah'ım! Bizi iman güzelliği ile süsle ve bizi hidâyete ermiş önderler kıl.\n\nAtâ b. es-Sâib (ra) şöyle rivayet etmiştir: Ammâr b. Yâsir (ra) bize namaz kıldırdı ve namazı kısa tuttu. Bazı insanlar 'Namazı kısa tuttun' dediler. O da şöyle dedi: 'Bununla birlikte Resûlullah'tan (ﷺ) duyduğum duaları yine de okudum.' Bunu söylerken onlara yukarıdaki duayı öğretti.","en":"O Allah, by Your Knowledge of the unseen and by Your Power over creation, let me live if You know that life is good for me, and let me die if You know that death is good for me. O Allah, I ask You to grant me fear of You in private and in public. I ask you for the word of truth in times of contentment and anger. I ask You for moderation in wealth and in poverty. I ask you for blessings never ceasing and the coolness of my eye (i .e . pleasure) that never ends. I ask You for pleasure after Your Judgment and I ask You for a life of coolness after death. I ask You for the delight of gazing upon Your Face and the joy of meeting You without any harm and misleading trials befalling me. O Allah, dress us with the beauty of Faith, and make us guides who are upon (correct) guidance.\n\nIt was narrated from Ata bn As-Sa'ib (R) that: Ammar bin Yasir (RA) led us in prayer and he made it brief. Some of the people said to him: 'You made the prayer short.He said: 'Nevertheless I still recited supplications that I heard from the Messenger of Allah (ﷺ).' Saying this, he taught them the above dua."},{"id":236,"title":"Duâ-i Me'sûr 6 (Allâhümme İnnî Es'elüke Minel-Hayri)","ref":"Sahîh (Elbânî). İbn Mâce: 3846","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_236.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ، مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَعُوْذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ، وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا","latin":"Allâhümme innî es'elüke minel-hayri küllihî, âcilihî ve âcilihî, mâ alimtü minhü ve mâ lem a'lem. Ve eûzü bike mineş-şerri küllihî, âcilihî ve âcilihî, mâ alimtü minhü ve mâ lem a'lem. Allâhümme innî es'elüke min hayri mâ seeleke abdüke ve nebiyyüke, ve eûzü bike min şerri mâ âze bihî abdüke ve nebiyyüke. Allâhümme innî es'elükel-cennete ve mâ karrebe ileyha min kavlin ev amel, ve eûzü bike minen-nâri ve mâ karrebe ileyha min kavlin ev amel, ve es'elüke en tec'ale külle kadâin kadaytehû lî hayren","tr":"Allah'ım! Aceli ve geceli, bildiğim ve bilmediğim her türlü hayrı Senden istiyorum. Her türlü şerden, aceli ve geceli, bildiğimden ve bilmediğimden Sana sığınırım. Allah'ım! Kulun ve Nebîn'in Senden istediği hayırları Senden istiyorum; kulun ve Nebîn'in sığındığı şerlere karşı Sana sığınırım. Allah'ım! Cenneti ve söz veya amelle ona yaklaştıracak şeyleri Senden istiyorum; Cehennem'den ve söz veya amelle ona yaklaştıracak şeylerden Sana sığınırım. Hakkımda verdiğin her hükmü hayır kılmanı Senden istiyorum.","en":"O Allah, I ask You for all that is good, in this world and in the Hereafter, what I know and what I do not know. O Allah, I seek refuge with You from all evil, in this world and in the Hereafter, what I know and what I do not know. O Allah, I ask You for the good that Your slave and Prophet (ﷺ) has asked You for, and I seek refuge with You from the evil from which Your slave and Prophet (ﷺ) sought refuge. O Allah, I ask You for Paradise and for that which brings one closer to it, in word and deed, and I seek refuge in You from Hell and from that which brings one closer to it, in word and deed. And I ask You to make every decree that You decree concerning me good."},{"id":237,"title":"Kabir Azabından, Cehennem'den ve Deccâl'den Korunma Duası","ref":"Buhârî: 832","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_237.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْـيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ","latin":"Allâhümme innî eûzü bike min azâbil-kabr, ve eûzü bike min fitnetil-mesîhid-deccâl, ve eûzü bike min fitnetil-mahyâ vel-memât. Allâhümme innî eûzü bike minel-me'semi vel-mağram","tr":"Allah'ım! Kabir azabından Sana sığınırım, Mesîh Deccâl fitnesinden Sana sığınırım, hayat ve ölüm fitnesinden Sana sığınırım. Allah'ım! Günah ve borçtan Sana sığınırım.\n\nÂişe (ra) (Peygamber'in eşi) şöyle rivayet etmiştir: Resûlullah (ﷺ) namazında bu duayı okurdu. Ona 'Niçin bu kadar sık borçtan Allah'a sığınıyorsunuz?' diye sordu. Peygamber (ﷺ) şöyle buyurdu: 'Borçlu olan kişi konuştuğunda yalan söyler, söz verdiğinde ise vaadini bozar.'","en":"O Allah, I seek refuge in You from the punishment of the grave, and I seek refuge in You from the trial of the False Messiah, and I seek refuge in You from the trials of life and death. O Allah, I seek refuge in You from sin and from debt.\n\nNarrated by `Aisha (RA) (the wife of the Prophet) Allah's Messenger (ﷺ) used to say this dua in the prayer. She said to him, \"Why do you so frequently seek refuge with Allah from being in debt?\" The Prophet (ﷺ) replied, \"A person who in debt tells lies whenever he speaks, and breaks promises whenever he makes (them).\""},{"id":238,"title":"Namazın Sonunda Okunacak Dua (Allâhümme İnnî Eûzü Bike)","ref":"Müslim: 1/412","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_238.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيْحِ الدَّجَّالِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْمَأْثَمِ وَمِنَ الْمَغْرَمِ","latin":"Allâhümme innî eûzü bike min azâbi cehennem, ve eûzü bike min azâbil-kabr, ve eûzü bike min fitnetil-mesîhid-deccâl, ve eûzü bike min fitnetil-mahyâ vel-memât, Allâhümme innî eûzü bike minel-me'semi vel-mağram","tr":"Allah'ım! Cehennem azabından Sana sığınırım, kabir azabından Sana sığınırım, Mesîh Deccâl fitnesinden Sana sığınırım, hayat ve ölüm fitnesinden Sana sığınırım. Allah'ım! Günah ve borçtan Sana sığınırım.\n\nİbn Abbâs (ra) şöyle demiştir: Peygamber (ﷺ) onlara (Sahâbîlere) bu duayı Kur'ân surelerini öğrettiği gibi öğretirdi. Şöyle derdi: (Yukarıdaki dua)","en":"O Allah, I seek refuge with Thee from the torment of Hell, and I seek refuge with Thee from the torment of the grave, and I seek refuge with Thee from the trial of the Masih al-Dajjal (Antichrist) and I seek refuge with Thee from the trial of life and death. O Allah! I seek refuge with Thee from sin and debt.\n\nIbn ‘Abbas (RA) said that the Holy Prophet (ﷺ) used to teach them (the Companions) this Dua in the same way he used to teach them Surah of the Quran. He used to say: (The dua is mentioned above)"},{"id":239,"title":"Duâ-i Me'sûr 7 (Allâhümme Einnî Alâ Zikrike)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1522","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_239.json","ar":"اَللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ، وَشُكْرِكَ، وَحُسْنِ عِبَادَتِكَ","latin":"Allâhümme einnî alâ zikrike, ve şükrike, ve hüsni ibâdetik","tr":"Allah'ım! Seni zikretmem, Sana şükretmem ve Sana en güzel şekilde ibadet etmem konusunda bana yardım et.\n\nMuâz b. Cebel (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) elini tuttu ve şöyle dedi: 'Allah'a yemin olsun ki seni seviyorum, Muâz. Allah'a yemin olsun ki seni seviyorum. Sana bir vasiyette bulunacağım: Her farz namazdan sonra bu duayı okumayı hiç bırakma: (Yukarıdaki dua)'","en":"O Allah, help me to remember You, to give You thanks, and to perform Your worship in the best manner.\n\nMu'adh bin Jabal (RA) reported that the Messenger of Allah (ﷺ) caught his hand and said: By Allah, I love you, Mu'adh. By Allah, I love you. I give some instruction to you. Never leave to recite this supplication after every (prescribed) prayer: (The dua is mentioned above)"},{"id":240,"title":"Duâ-i Me'sûr 8 (Allâhümme İnnî Eûzü Bike Minel)","ref":"Buhârî: 6374","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_240.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبُخْلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوْذُ بِكَ مِنْ أَنْ نُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَعَذَابِ الْقَبْرِ","latin":"Allâhümme innî eûzü bike minel-buhli, ve eûzü bike minel-cubni, ve eûzü bike min en üraddé ilâ erzalil-ömür, ve eûzü bike min fitnetid-dünyâ ve azâbil-kabr","tr":"Allah'ım! Cimrilikten Sana sığınırım, korkaklıktan Sana sığınırım, aşağılık ihtiyarlığa döndürülmekten Sana sığınırım, dünya fitnesinden ve kabir azabından Sana sığınırım.\n\nSa'd b. Ebî Vakkâs (ra) şöyle rivayet etmiştir: Sa'd (ra) bu sözleri, bir öğretmenin çocuklara el yazısı öğrettiği gibi oğullarına öğretirdi. Ve namazın sonunda Resûlullah'ın (ﷺ) bu konularda (Allah'a) sığındığını söylerdi: (Yukarıdaki dua)","en":"O Allah! I seek refuge with You from cowardice, and miserliness, and seek refuge with You from reaching a degraded helpless old age, and seek refuge with You from the afflictions of the world and from the punishment in the grave.\n\nNarrated by Saad Ibn Abi Waqqas (RA): Saad (RA) used to teach these words to his sons in the same way that a teacher teaches handwriting to children. And he used to say that towards the end of the prayer, the Messenger of Allah (ﷺ) would seek refuge (in Allah) in these matters: (The dua is mentioned above)"},{"id":242,"title":"Duâ-i Me'sûr 9 (Allâhümme İnnî Es'elüke Yâ Allâhu Bi-Enneke)","ref":"Sahîh (Elbânî). Nesâî: 1301","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_242.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا أَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","latin":"Allâhümme innî es'elüke yâ Allâhu bi-ennekel-Vâhidul-Ehadüs-Samedüllezî, lem yelid ve lem yûled, ve lem yekun lehû küfüven ehad, en tağfirali zünûbî inneke Entel-Ğafûrur-Rahîm","tr":"Allah'ım! Senden istiyorum. Ey Allah! Sen Bir'sin, Tek'sin, hiçbir şeye muhtaç olmayan Samed'sin; doğurmamış ve doğurulmamışsın, hiçbir şey Sana denk değildir. Günahlarımı bağışla; şüphesiz Sen Ğafûr ve Rahîm'sin.\n\nDuayı işiten Resûlullah (ﷺ) üç kez şöyle buyurdu: 'O bağışlandı.'","en":"O Allah, I ask You. O Allah, You are the One, the Only, Self-Sufficient Master, Who was not begotten and begets not and none is equal to Him. Forgive me my sins, surely you are Forgiving, Merciful.\n\nAfter hearing his supplication, the Messenger of Allah (ﷺ) said three times, \"He has been forgiven.\""},{"id":243,"title":"Duâ-i Me'sûr 10","ref":"Sahîh (Elbânî). Nesâî: 1300","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_243.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلاَّ أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","latin":"Allâhümme innî es'elüke bi-enne lekel-hamde lâ ilâhe illâ ente el-Mennânü, bedîus-semâvâti vel-ardı yâ Zel-celâli vel-ikrâm, yâ Hayyü yâ Kayyûm, innî es'elük","tr":"Allah'ım! Senden istiyorum; zira tüm hamd Sanadır, Senden başka ilah yoktur, tek başınasın, ortaksızsın. Sen Mennân'sın, göklerin ve yerin Bedî'isin. Ey Celâl ve ikram sahibi! Ey Hayy! Ey Kayyûm! Senden istiyorum.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Ne ile dua ettiğini biliyor musunuz?' Sahâbîler şöyle cevap verdi: 'Allah ve Resûlü daha iyi bilir.' Peygamber (ﷺ) şöyle buyurdu: 'Canım elinde olan'a yemin olsun ki, Allah'ı en büyük ismiyle çağırdı; O bu isimle çağrıldığında icabet eder, bu isimle istenildiğinde verir.'»","en":"O Allah, I ask You as unto You is all praise, none has the right to be worshipped except You, alone, without partner. You are the Benefactor. Originator of the heavens and the Earth, O Possessor of majesty and honour, O Ever Living, O Self-Subsisting and Supporter of all. I am asking you\n\nThe Prophet (ﷺ) said: 'Do you know what he has supplicated with?' They said: \"Allah (SWT) and His Messenger know best.\" He (ﷺ) said: 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives.'\""},{"id":244,"title":"Duâ-i Me'sûr 11 (Allâhümme İnnî Es'elüke Bi-Enneke Entallâh Tam Dua)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1493","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_244.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي اَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ الَّذِيْ لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ","latin":"Allâhümme innî es'elüke bi-ennî eşhedü enneke EntAllâhü lâ ilâhe illâ Entel-Ehadus-Samedüllezî lem yelid ve lem yûled ve lem yekun lehû küfüven ehad","tr":"Allah'ım! Senden istiyorum; zira Sen Allah'sın diye şehadet ederim. Senden başka ilah yoktur, Bir'sin, yaratılıştan bağımsız Samed'sin; doğurmamış ve doğurulmamışsın, Sana denk olan hiçbir şey yoktur.\n\nBunun üzerine Peygamber (ﷺ) şöyle buyurdu: 'Canım elinde olan'a yemin olsun ki, Allah'ı en büyük ismiyle istedi; O bu isimle çağrıldığında icabet eder, bu isimle istenildiğinde verir.","en":"O Allah, I ask You, by the fact that I bear witness that You are Allah. There is none worthy of worship but You, the Only ilah, Independent of creation, Who was not begotten and begets not, and none is equal to Him.\n\nThen the Prophet (ﷺ) said, ‘By the One in Whose Hand is my soul, he has asked Allah by His Greatest Name, the one which if He is called upon by it, He responds, and when He is asked by it, He gives."},{"id":245,"title":"Duâ-i Me'sûr 12","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1493-1495","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_245.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ، الْمَنَّانُ، يَا بَدِيعَ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَأَعُوْذُ بِكَ مِنَ النَّارِ","latin":"Allâhümme innî es'elüke bi-enne lekel-hamde lâ ilâhe illâ Ente vahdeke lâ şerîke leke, el-Mennânü, yâ Bedîas-semâvâti vel-ardı yâ Zel-celâli vel-ikrâm, yâ Hayyü yâ Kayyûm innî es'elükel-cennete ve eûzü bike minen-nâr","tr":"Allah'ım! Senden istiyorum; zira tüm hamd Sanadır, Senden başka ilah yoktur, tek başınasın, ortaksızsın, Mennân'sın. Ey göklerin ve yerin Bedî'i! Ey Celâl ve ikram sahibi! Ey Hayy! Ey Kayyûm! Senden Cenneti istiyorum ve Ateş'ten Sana sığınırım.","en":"O Allah, I ask You, as You are the Owner of praise, there is none worthy of worship but You alone, You have no partner. You are the Giver of all good. O Creator of the heavens and the earth, Owner of majesty and honor. O Living and Everlasting One, I ask you for Paradise and I seek refuge in You from the fire."},{"id":246,"title":"Namazda Okunacak Dua (Allâhü Ekber Kebîrâ Velhamdü Lillâhi Kesîrâ)","ref":"Müslim: 601","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_246.json","ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا، وَالْحَمْدُ لِلَّهِ كَثِيرًا، وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا","latin":"Allâhü Ekber kebîrâ, velhamdü lillâhi kesîrâ, ve sübhânallâhi bükreten ve asîlâ","tr":"Allah büyüktür, pek büyük. Hamd Allah'a aittir, bol bol. Allah her türlü noksanlıktan münezzehtir, sabah akşam.\n\nResûlullah (ﷺ) şöyle buyurdu: 'Bu kelimeleri kim söyledi?' Cemaatten biri: 'Ben, ya Resûlallah!' dedi. Peygamber (ﷺ) şöyle buyurdu: 'Şaşırdım! Zira bu dua için göğün kapıları açıldı.' İbn Ömer (ra) şöyle dedi: 'Resûlullah'ın (ﷺ) bunu söylediğini duyduğumdan beri bu duayı hiç terk etmedim.'","en":"Allah is the Greatest, Most Great. Praise is to Allah, abundantly. Glory is to Allah, at the break of day and at its end.\n\nThe Messenger of Allah (ﷺ) said: Who uttered such and such a word? A person among the people (who have recited these words) said: Me! Ya Messenger of Allah!. He (ﷺ) said: it's utterance surprised me because for this dua, the doors of heaven were opened. Ibn 'Umar (RA) said: I have not abandoned them (to recite this dua) since I heard the Messenger of Allah (ﷺ) saying this."},{"id":247,"title":"Sabah Namazından Sonra Okunacak Dua (Allâhümme İnnî Es'elüke İlmen)","ref":"Sahîh (Elbânî). İbn Mâce: 925","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_247.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","latin":"Allâhümme innî es'elüke ilmen nâfia, ve rızkan tayyiben, ve amelen mütekabbela","tr":"Allah'ım! Senden faydalı ilim, helal rızık ve kabul edilmiş amel istiyorum.","en":"O Allah, I ask You for knowledge which is beneficial and sustenance which is good, and deeds which are acceptable."},{"id":248,"title":"Sabah ve Akşam Namazından Sonra Okunacak Dua 1","ref":"Hasen (Elbânî). Tirmizî: 3534","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_248.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","latin":"Lâ ilâhe illAllâhü vahdehû lâ şerîke leh, lehül-mülkü ve lehül-hamdü, yuhyî ve yümîtü, ve hüve alâ külli şey'in kadîr","tr":"Allah'tan başka hak ilah yoktur; O tektir, ortağı yoktur. Mülk O'na aittir, hamd O'na aittir; hayat verir ve öldürür, O her şeye gücü yetendir.","en":"None has the right to be worshipped except Allah, who is alone and does not have any partner. To Him belongs all sovereignty and praise, He gives life and causes death and He is omnipotent over all things."},{"id":249,"title":"Sabah ve Akşam Namazından Sonra Okunacak Dua 2 (Allâhümme Ecirni Minen-Nâr)","ref":"Hasen (İbn Hacer). el-Fütûhâtü'r-Rabbâniyye 3/69","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_249.json","ar":"اَللَّهُمَّ أَجِرْنِيْ مِنَ النَّارِ","latin":"Allâhümme ecirni minen-nâr","tr":"Allah'ım! Beni Cehennem'den koru.\n\nHâris b. Müslim (ra) şöyle demiştir: Resûlullah (ﷺ) bana şöyle buyurdu: 'Akşam namazını kıldığında 'Allah'ım! Beni Cehennem'den koru' diye yedi kez söyle; bunu söyleyip o gece ölürsen Allah seni Cehennem'den korur. Sabah namazını kıldığında da aynı şekilde söyle; o gün ölürsen Allah seni Cehennem'den korur.' Hadisçilerin büyük çoğunluğu bu hadisi kabul edilebilir görmüştür.","en":"O Allah, protect me from Hell.\n\nHarith ibn Muslim (RA) said: The Messenger of Allah (ﷺ) said to me: When you finish the maghrib prayer, say: 'O Allah, protect me from Hell\" seven times; for if you say that and die that night, Allah will protect you from jahannam; and when you finish the fajr prayer, say it in a similar way, for if you die that day, Allah will protect you from jahannam. Most of the muhaddithin have considered this hadith to be acceptable."},{"id":250,"title":"Namazdan Sonra Okunacak Dua (Estağfirullah)","ref":"Müslim: 591","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_250.json","ar":"أَسْتَغْفِرُ اللَّهَ","latin":"Estağfirullâh","tr":"Allah'tan bağışlanma dilerim.","en":"I ask Allah for forgiveness."},{"id":251,"title":"Namazdan Sonra Okunacak Dua (Allâhümme Entessalâm ve Minkessalâm Duası)","ref":"Müslim: 591","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_251.json","ar":"اَللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","latin":"Allâhümme Entessalâm ve minkessalâm, tebârekte yâ Zel-celâli vel-ikrâm","tr":"Allah'ım! Sen Selam'sın ve selam Senden gelir. Ey Celâl ve ikram sahibi! Sen ne yüce, ne mübareksın.","en":"O Allah, You are Peace and from You comes peace. Blessed are You, O Owner of majesty and honor."},{"id":252,"title":"Selamdan Sonra Okunacak Dua","ref":"Buhârî: 844","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_252.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِىَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","latin":"Lâ ilâhe illAllâhü vahdehû lâ şerîke leh, lehül-mülkü ve lehül-hamdü ve hüve alâ külli şey'in kadîr, Allâhümme lâ mânia limâ a'tayte, ve lâ mu'tiye limâ menate ve lâ yenfa'u zel-ceddi minkel-cedd","tr":"Allah'tan başka hak ilah yoktur; O tektir, ortağı yoktur. Mülk O'na aittir, hamd O'na aittir ve O her şeye gücü yetendir. Allah'ım! Senin vermeyi dilediğini engelleyecek kimse yoktur, Senin engellediğini verecek kimse yoktur; varlıklının varlığı Sene karşı ona fayda vermez.","en":"None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and and He is Able to do all things. O Allah, none can prevent what You have willed to bestow and none can bestow what You have willed to prevent, and no wealth or majesty can benefit anyone, as from You is all wealth and majesty."},{"id":253,"title":"Namazda Selamdan Sonra Okunacak Dua","ref":"Müslim: 594","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_253.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيْرٌ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ لَا إِلَهَ إِلَّا اللَّهُ وَلَا نَعْبُدُ إِلَّا إِيَّاهُ لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِيْنَ لَهُ الدِّيْنَ وَلَوْ كَرِهَ الْكَافِرُوْنَ","latin":"Lâ ilâhe illAllâhü vahdehû lâ şerîke leh, lehül-mülkü ve lehül-hamdü ve hüve alâ külli şey'in kadîr, lâ havle ve lâ kuvvete illâ billâh, lâ ilâhe illAllâhü, ve lâ na'büdü illâ iyyâh, lehün-ni'metü ve lehül-fadlü ve lehüs-senâül-hasen, lâ ilâhe illAllâhü muhlisîne lehüd-dîne ve lev kerihe'l-kâfirûn","tr":"Allah'tan başka hak ilah yoktur; O tektir, ortağı yoktur. Mülk O'na aittir, hamd O'na aittir ve O her şeye gücü yetendir. Güç ve kuvvet ancak Allah ile vardır. Allah'tan başka hak ilah yoktur ve yalnızca O'na ibadet ederiz. Tüm nimet O'na aittir, tüm fazl O'na aittir ve güzel sena O'na aittir. Allah'tan başka hak ilah yoktur; kâfirler hoş görmese de biz dini yalnızca O'na has kılarak ihlasla kulluk ederiz.\n\nAbdullah b. Zübeyr (ra) her selamdan sonra bu duayı okur ve şöyle derdi: Peygamber (ﷺ) her namazdan sonra bu duayı okurdu.","en":"None has the right to be worshipped except Allah, alone, without partner, to Him belongs all sovereignty and praise and and He is Able to do all things, there is no might nor power except with Allah. None has the right to be worshipped except Allah and we worship none except Him. For Him is all favor, grace, and glorious praise. None has the right to be worshipped except Allah and we are sincere in faith and devotion to Him although the disbelievers detest it.\n\nAbdullah ibn Zubayr (RA) himself used to recite this dua after every salaam and say: The Prophet (ﷺ) used to recite these dua after every prayer."},{"id":257,"title":"Namazdan Sonra Güçlü Zikir","ref":"Müslim 1/418, nr. 597","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_257.json","ar":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ","latin":"SübhânAllâhi, velhamdü lillâhi wAllâhü Ekber","tr":"Allah her türlü noksanlıktan münezzehtir, tüm hamd Allah'a aittir ve Allah en büyüktür.","en":"How perfect Allah is, all praise is for Allah, and Allah is the greatest."},{"id":258,"title":"Namazın Sonunda Okunacak Dua","ref":"Müslim: 709","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_258.json","ar":"رَبِّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ (تَجْمَعُ) عِبَادَكَ","latin":"Rabbi kınî azâbeke yevme teb'asü - [tecme'u] - ibâdek","tr":"Rabbim! Kullarını dirilttiğin - ya da bir araya getirdiğin - günde beni azabından koru.\n\nBerâ (ra) şöyle rivayet etmiştir: Resûlullah'ın (ﷺ) arkasında namaz kılarken yüzü bize dönmesi için O'nun sağ tarafında olmayı arzulardık. (Râvi dedi ki:) O'nun şöyle dediğini duydum: (dua yukarıda zikredilmiştir)","en":"O Allah, save me from Your punishment on the Day when You resurrect - or gather - Your slaves.\n\nBara' (RA) reported: When we prayed behind the Messenger of Allah (ﷺ) we cherished to be on his right side so that his face would turn towards us (at the end of the prayer), and he (the narrator) said: I heard him say: (the dua is mentioned above)"},{"id":259,"title":"Namazın Sonunda Okunacak Dua","ref":"Sahîh (Elbânî). Nesâî: 5465","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_259.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ","latin":"Allâhümme innî eûzü bike minel-küfri vel-fakri, ve azâbil-kabr","tr":"Allah'ım! Küfürden, fakirlikten ve kabir azabından Sana sığınırım.","en":"O Allah, I seek refuge with You from Kufr, poverty, and from the torment of the grave."},{"id":260,"title":"Namazdan Sonra Okunacak Dua (Allâhümme Einnî Alâ Zikrike ve Şükrike)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1522","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_260.json","ar":"اَللَّهُمَّ أَعِنِّى عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ","latin":"Allâhümme einnî alâ zikrike ve şükrike ve husni ibâdetik","tr":"Allah'ım! Seni zikretmeme, Sana şükretmeme ve Sana en güzel şekilde ibadet etmeme yardım et.\n\nMuâz b. Cebel (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) elinden tutarak şöyle buyurdu: 'Allah'a yemin olsun, seni seviyorum Muâz. Sana bir tavsiyede bulunuyorum. Her farz namazdan sonra bu duayı okumayı hiç bırakma.'","en":"O Allah, help me to remember You, to give You thanks, and to perform Your worship in the best manner.\n\nMu'adh bin Jabal (RA) reported that the Messenger of Allah (ﷺ) caught his hand and said: By Allah, I love you, Mu'adh. I give some instruction to you. Never leave to recite this supplication after every (prescribed) prayer."},{"id":261,"title":"Namazdan Sonra Okunacak Dua","ref":"[1] Müslim: 771 [2] Sahîh (Elbânî). Ebû Dâvûd: 1509","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_261.json","ar":"اَللَّهُمَّ غْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümmağfirlî mâ kaddemtü ve mâ ahhartü ve mâ esrartü ve mâ a'lentü ve mâ esraftü ve mâ Ente a'lemü bihî minnî. Entel-Mükaddimu ve Entel-Muahhiru lâ ilâhe illâ Ente","tr":"Allah'ım! Önceden yaptıklarımı ve sonradan yapacaklarımı, gizlice yaptıklarımı ve açıkça yaptıklarımı, aşırılığa kaçtıklarımı ve benden daha iyi bildiğin günahlarımı bağışla. Sen Mükaddimsin ve Muahhirsin. Senden başka hak ilah yoktur.\n\nResûlullah (ﷺ) bu duayı teşehhüdden sonra ve selamdan önce [1], başka bir rivayette ise namazı bitirdikten sonra okurdu [2]. Her iki rivayet de sahihtir. Belki O (ﷺ) bazen bu duayı selamdan önce, bazen de selamdan sonra okurdu.","en":"O Allah, forgive me what I have sent before me and what I have left behind me, what I have done in secret and what I have done in public, what I have done in excess, and those sins which You are better aware of than I. You are the One Who sends forth and You are the One Who delays. There is none worthy of worship but You.\n\nThe Messenger of Allah (ﷺ) after the tashahood but before the salaam [1] and in another narration, it says he used to say this dua after finishing the prayer [2]. Both narrations are authentic. Perhaps he (ﷺ) sometimes said this dua before salaam and sometimes after salaam."},{"id":262,"title":"Namazın Sonunda Okunacak Dua","ref":"Hasen (İbn Hacer). el-Fütûhâtü'r-Rabbâniyye 3/71","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_262.json","ar":"اَللَّهُمَّ أَصْلِحْ لِي دِيْنِيَ الَّذِي جَعَلْتَهُ عِصْمَةَ أَمْرِي، وَأَصْلِحْ لِي دُنْيَايَ الَّتِي جَعَلْتَ فِيهَا مَعَاشِيْ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِعَفْوِكَ مِنْ نِقْمَتِكَ، وَأَعُودُ بِكَ مِنْكَ، اَللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ","latin":"Allâhümme aslıh lî dîniyyellezî cealtehû ismetê emrî, ve aslıh lî dünyâyelleti cealtê fîhâ meâşî, Allâhümme innî eûzü biridâke min sahâtik, ve bi'afvike min nikmetik, ve eûzü bike mink, Allâhümme lâ mâniae limâ a'tayte ve lâ mu'tiye limâ menate ve lâ yenfa'u zel-ceddi minkel-cedd","tr":"Allah'ım! İşlerimin güvencesi kıldığın dinimi düzelt; geçimimi içinde kıldığın dünyamı düzelt. Allah'ım! Rızanı kıl gazabından sığınağım; affını kıl cezandan sığınağım ve Senden Sana sığınırım. Allah'ım! Senin vermeyi dilediğini engelleyecek kimse yoktur, Senin engellediğini verecek kimse yoktur; varlıklının varlığı Sana karşı ona fayda vermez.","en":"O Allah, set straight my religious commitment that You have made a protection for me, and set straight my worldly affairs which You have made a means of my livelihood. O Allah, I seek refuge in Your pleasure from Your wrath, and I seek refuge in Your forgiveness from Your punishment, and I seek refuge in You from You. O Allah, None can withhold what you have given and none can give what you have withheld, and no wealth or fortune can avail the man of wealth and fortune before You."},{"id":263,"title":"Namazdan Sonra Okunacak Dua","ref":"Sahîh (Elbânî). Dârimî: 2/217","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_263.json","ar":"اَللَّهُمَّ بِكَ أُحَاوِلُ وَبِكَ أُقَاتِلُ وَبِكَ أَصَاوِلُ","latin":"Allâhümme bike ehâvilü ve bike ukâtilü ve bike üsâvilü","tr":"Ya Allah! Senin yardımınla girişirim, Senin yardımınla savaşırım, Senin yardımınla cesaret gösteririm ve Senin yardımınla zafer kazanırım.","en":"Ya Allah! I try by your help, fight by your help, show courage by your help and be victorious by your help."},{"id":264,"title":"Namazdan Sonra Okunacak Dua (Allâhümmağfirlî Verhamnî ve Tüb Aleyye)","ref":"Sahîh (Elbânî). es-Silsiletü's-Sahîha: 556, Ahmed: 5564","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_264.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيْم (التَّوَّابُ الْغَفُورُ)","latin":"Allâhümmağfirlî ve tüb aleyye inneke Entet-Tevvâbür-Rahîm (diğer rivayette: Tevvâbül-Ğafûr)","tr":"Allah'ım! Beni bağışla ve tövbemi kabul et. Şüphesiz Sen Tevvâb ve Rahîm'sin.' (Diğer rivayette: Tevvâb ve Ğafûr'sun)\n\nEnsarlı bir sahabi (ra) şöyle demiştir: 'Resûlullah'ın (ﷺ) namazdan sonra bu duayı 100 kez okuduğunu duydum.' Bu hadisin ikinci rivayetinde şöyle denmektedir: 'Resûlullah (ﷺ) iki rek'at kuşluk namazı kılıyordu. Ardından bu duayı 100 kez okuyordu.' Her iki rivayet de sahihtir. En azından zikredenler, bu duayı kuşluk namazından sonra 100 kez okumaya özen göstermelidir.","en":"O Allah, forgive me and turn to me. You are the Ever-Turning, the Merciful' (in another narration: the Most Forgiving)\n\n\"An Ansari Companion (RA) said: \"I have heard the Messenger of Allah (ﷺ) say this dua 100 times after the prayer.\" The second narration of this hadith says: “Rasulullah (ﷺ) prays two rak'ats of Salatud-Duha. Then he recited this dua 100 times. Both descriptions are authentic. At least all the Dhaakirs should pay attention to recite this Dua 100 times after Salatud Duha."},{"id":265,"title":"Namazdan Sonra Okunacak Dua","ref":"Hasen (Elbânî). Sahîhü'l-Câmi: 1266","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_265.json","ar":"اَللَّهُمَّ اغْفِرْ لِي ذُنُوْبِي وَخَطَايَايَ كُلَّهَا اَللَّهُمَّ أَنْعِشْنِيْ وَاجْبُرْنِيْ وَاهْدِنيْ لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ فَإِنَّهُ لَا يَهْدِيْ لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ","latin":"Allâhümmağfirlî zünûbî ve hatâyâye küllehâ, Allâhümme en'işnî vecbürnî vehdini li sâlihil a'mâli vel ahlâkı fe-innehû lâ yehdî li sâlihihâ ve lâ yasrifü seyyiehâ illâ ente","tr":"Ya Allah! Tüm hatalarımı ve günahlarımı bağışla. Ya Allah! Bana ilham ver, beni itaatkâr kıl, hayırlı amellere ve güzel ahlaka yönlendir. Zira onun iyisine yalnızca Sen hidayet eder ve kötüsünden yalnızca Sen uzaklaştırırsın.\n\nEbû Ümâme (ra) ve Ebû Eyyûb (ra) şöyle demiştir: 'Peygamberinizin (ﷺ) yanına her farz ya da nafile namazda gittiğimde, namazın sonunda dönerken veya kalkarken bu iki şeyi söylediğini duydum.'","en":"Ya Allah! Forgive all of my mistakes and my sins. Ya Allah! Inspire me and make me obedient. Guide me to do the good deeds and to the good mannars. Because none can guide to it’s good and turn away from it except you.\n\nAbu Umama (RA) and Abu Ayyub (RA) said: \"Whenever I went to your Prophet (ﷺ) in any of the obligatory and supererogatory prayers, I heard him say these two things while turning or getting up at the end of the prayer.\""},{"id":266,"title":"Namazdan Sonra Okunacak Dua","ref":"Hasen (Elbânî). Sahîhü'l-Câmi: 1265","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_266.json","ar":"اَللَّهُمَّ اغْفِرْ لِي ذَنْبِيْ وَوَسِّعْ لِي فِي دَارِيْ وَبَارِكْ لِي فِي رِزْقِيْ","latin":"Allâhümmağfirlî zenbî ve vessia lî fî dârî ve bârik lî fî rızkî","tr":"Allah'ım! Günahımı bağışla, evimi genişlet ve rızkımı bereketli kıl.\n\nEbû Mûsâ (ra) şöyle demiştir: 'Resûlullah'a (ﷺ) abdest suyu getirdim. Ardından O abdest aldı, namaz kıldı ve bu duayı okudu.'","en":"O Allah, forgive me my sin, and expand for me my abode, and bless for me that which You have provided me.\n\nAbu Musa (RA) said, \"I brought the water of ablution to the Messenger of Allah (ﷺ). \"Then he performs ablution, prays and recites this dua."},{"id":267,"title":"Namazdan Sonra Zikir","ref":"Buhârî: 842","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_267.json","ar":"اَللَّهُ اَكْبَرُ","latin":"Allâhü Ekber","tr":"Allah en büyüktür.","en":"Allah is the greatest."},{"id":268,"title":"Namazdan Sonra Okunacak Dua","ref":"Müslim: 2726","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_268.json","ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ","latin":"SübhânAllâhi ve bihamdihî adede halkıhî ve ridâe nefsihî ve zinete arşihî ve midâde kelimâtih","tr":"Allah her türlü noksanlıktan münezzehtir ve O'na hamdolsun; yaratıklarının sayısınca, Zâtının rızasınca, Arşının ağırlığınca ve kelimelerinin mürekkebi kadar.","en":"Glory is to Allah and praise is to Him, by the multitude of His creation, by His Pleasure, by the weight of His Throne, and by the extent of His Words."},{"id":273,"title":"Teheccüd Namazına Başlarken Okunacak Dua (Sübhâneke Allâhümme)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 775","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_273.json","ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ وَتَبَارَكَ اسْمُكَ وَتَعَالَى جَدُّكَ وَلَا إِلَهَ غَيْرُكَ","latin":"Sübhâneke Allâhümme ve bihamdik, ve tebâreke'smük, ve teâlâ ceddük, ve lâ ilâhe ğayrük","tr":"Allah'ım! Seni tüm noksanlıklardan tenzih eder ve hamd ederim. İsmin ne mübarektir, şanın ne yücedir. Senden başka hak ilah yoktur.\n\nArdından şöyle dedi — üç kez —","en":"Glory is to You O Allah, and praise. Blessed is Your Name and Exalted is Your Majesty. There is none worthy of worship but You.\n\nThen he said this for three times -"},{"id":274,"title":"Vitir Namazından Sonra Okunacak Dua (Sübhânel-Melikilkuddûs)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1430; Nesâî: 1699, 1701","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_274.json","ar":"سُبْحَانَ الْمَلِكِ الْقُّدُّوْسِ","latin":"Sübhânel-Melikilkuddûs","tr":"Melik ve Kuddûs olan Allah her türlü noksanlıktan münezzehtir.","en":"Glory is to the King, the Holy."},{"id":275,"title":"Vitir Namazının Sonunda Okunacak Dua (Allâhümme İnnî Eûzü Biridâke)","ref":"Sahîh. Ebû Dâvûd: 1427","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_275.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُــوذُ بِكَ مِنْكَ، لَا أُحْصِيْ ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ","latin":"Allâhümme innî eûzü biridâke min sahâtike, ve bimuâfâtike min ukûbetike ve eûzü bike mink, lâ uhsî senâen aleyke Ente kemâ esneyte alâ nefsik","tr":"Allah'ım! Gazabından rızana sığınırım, cezandan affına sığınırım ve Senden Sana sığınırım. Seni hakkıyla övemem; Sen Zâtını övdüğün gibisin.\n\nAlî (ra) şöyle demiştir: Resûlullah (ﷺ) bu kelimeleri vitir namazının sonunda söylerdi. Vitir namazının sonu burada selamdan önce mi sonra mı olduğu açıkça belirtilmemiştir. Bu nedenle mümin bu duayı vitir namazının sonunda selamdan önce veya selamdan sonra okuyabilir.","en":"O Allah, I seek refuge with Your Pleasure from Your anger. I seek refuge in Your forgiveness from Your punishment. I seek refuge in You from You. I cannot count Your praises, You are as You have praised Yourself.\n\nAli (RA) said, Rasulullah (ﷺ) used to say the words at the end of Witr prayer. The end of Witr prayer here is not clearly stated before the salaam or after the salaam. Therefore, a believer can recite this dua at the end of Salatul Witr prayer before Salaam or after Salaam."},{"id":276,"title":"Vitir Namazından Sonra Okunacak Dua (Rabbül-Melâiketi ver-Rûh)","ref":"Sünen-i Dârekutnî 2/31, Mu'cemü'l-Evsât 8/108, Sünen-i Beyhakî 3/40","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_276.json","ar":"رَبُّ الْمَلَائِكَةِ وَالرُّوحِ","latin":"Rabbül-melâiketi ver-rûh","tr":"Meleklerin ve Ruh'un (Cebrâil'in) Rabbidir.","en":"Lord of the angels and the Spirit."},{"id":277,"title":"Vitir Namazında Okunacak Sureler (A'lâ Suresi, Kâfirûn Suresi ve İhlâs Suresi)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1423","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_277.json","ar":"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ﴿١﴾ الَّذِي خَلَقَ فَسَوَّىٰ ﴿٢﴾ وَالَّذِي قَدَّرَ فَهَدَىٰ ﴿٣﴾ وَالَّذِي أَخْرَجَ الْمَرْعَىٰ ﴿٤﴾ فَجَعَلَهُ غُثَاءً أَحْوَىٰ ﴿٥﴾ سَنُقْرِئُكَ فَلَا تَنسَىٰ ﴿٦﴾ إِلَّا مَا شَاءَ اللَّهُ ۚ إِنَّهُ يَعْلَمُ الْجَهْرَ وَمَا يَخْفَىٰ ﴿٧﴾ وَنُيَسِّرُكَ لِلْيُسْرَىٰ ﴿٨﴾ فَذَكِّرْ إِن نَّفَعَتِ الذِّكْرَىٰ ﴿٩﴾ سَيَذَّكَّرُ مَن يَخْشَىٰ ﴿١٠﴾ وَيَتَجَنَّبُهَا الْأَشْقَى ﴿١١﴾ الَّذِي يَصْلَى النَّارَ الْكُبْرَىٰ ﴿١٢﴾ ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحْيَىٰ ﴿١٣﴾ قَدْ أَفْلَحَ مَن تَزَكَّىٰ ﴿١٤﴾ وَذَكَرَ اسْمَ رَبِّهِ فَصَلَّىٰ ﴿١٥﴾ بَلْ تُؤْثِرُونَ الْحَيَاةَ الدُّنْيَا ﴿١٦﴾ وَالْآخِرَةُ خَيْرٌ وَأَبْقَىٰ ﴿١٧﴾ إِنَّ هَٰذَا لَفِي الصُّحُفِ الْأُولَىٰ ﴿١٨﴾ صُحُفِ إِبْرَاهِيمَ وَمُوسَىٰ ﴿١٩﴾","latin":"Bismillâhir-Rahmânir-Rahîm. (1) Kul HuvAllâhü Ehad. (2) Allâhüs-Samed. (3) Lem yelid ve lem yûled. (4) Ve lem yekun lehû küfüven ehad","tr":"(1) Yüce Rabbinin adını tesbih et. (2) O, yaratmış ve bir ölçüye göre biçimlendirmiştir. (3) O, takdir etmiş ve yol göstermiştir. (4) O, otlağı çıkarmıştır. (5) Sonra onu kararıp kurumuş bir yığına çevirmiştir. (6) Sana okutacağız; artık unutmayacaksın. (7) Ancak Allah'ın dilediği başka. Doğrusu O, açığı da gizliyi de bilir. (8) Seni kolaya hazırlayacağız. (9) Öğüt ver, çünkü öğüt fayda verir. (10) Allah'tan korkan öğüt alır. (11) Lakin azgın olan ondan kaçınır. (12) O, büyük ateşe girer. (13) Ne onda ölür ne de yaşar. (14) Temizlenen kişi kurtuluşa erer. (15) Rabbinin adını anar ve namaz kılar. (16) Hayır siz dünya hayatını tercih ediyorsunuz. (17) Hâlbuki ahiret daha hayırlı ve kalıcıdır. (18) Gerçekten bu, önceki kitaplarda da vardır. (19) İbrahim ve Mûsâ'nın kitaplarında. (A'lâ Suresi 87: 1-19)","en":"(1) Exalt the name of your Lord, the Most High, (2) Who created and proportioned (3) And Who destined and [then] guided (4) And who brings out the pasture (5) And [then] makes it black stubble. (6) We will make you recite, [O Muhammad], and you will not forget, (7) Except what Allah should will. Indeed, He knows what is declared and what is hidden. (8) And We will ease you toward ease. (9) So remind, if the reminder should benefit; (10) He who fears [ Allah ] will be reminded. (11) But the wretched one will avoid it - (12) [He] who will [enter and] burn in the greatest Fire, (13) Neither dying therein nor living. (14) He has certainly succeeded who purifies himself (15) And mentions the name of his Lord and prays. (16) But you prefer the worldly life, (17) While the Hereafter is better and more enduring. (18) Indeed, this is in the former scriptures, (19) The scriptures of Abraham and Moses. (Sura Al-A'la 87: 1-19)"},{"id":278,"title":"Vitir Namazı Duası (Kunut Duası)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1425","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_278.json","ar":"اَللَّهُمَّ اهْدِنِيْ فِيمَنْ هَدَيْتَ، وَعَافِنِيْ فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تَوَلَّيْتَ وَبَارِكْ لِي فِيمَا أَعْطَيْتَ وَقِنِيْ شَرَّ مَا قَضَيْتَ فَإِنَّكَ تَقْضِيْ وَلَا يُقْضَى عَلَيْكَ وَإِنَّهُ لَا يَذِلُّ مَنْ وَالَيْتَ، وَلَا يَعِزُّ مَنْ عَادَيْتَ تَبارَكْتَ رَبَّنَا وَتَعَالَيْتَ","latin":"Allâhümmehdinî fîmen hedayte, ve âfinî fîmen âfeyte, ve tevelleni fîmen tevelleyte, ve bârik lî fîmâ a'tayte, ve kınî şerre mâ kadayte, fe-inneke takdî ve lâ yukdâ aleyke, ve-innehû lâ yezillü men vâleyte, ve lâ ya'izzü men âdeyte, tebârekte Rabbenâ ve teâleyte","tr":"Allah'ım! Hidayet verdiklerinin arasında beni de hidayete erdir, afiyet verdiklerinin arasında bana da afiyet ver, gözetip koruduklarının arasında beni de gözetip koru, verdiğin şeyleri bereketli kıl, hükmettiğin şeylerin şerinden beni koru. Şüphesiz Sen hükmeder, Sana hükmedilemez. Dost tuttuğun kimse zillete düşmez, düşman tuttuğun kimse de izzete kavuşamaz. Ey Rabbimiz! Sen ne mübarek, ne yücesin.\n\nHasan b. Alî (ra) bu kunut hakkında şöyle demiştir: 'Resûlullah (ﷺ) vitir namazında kunut olarak söylemek üzere bu kelimeleri bana öğretti.'","en":"O Allah, guide me with those whom You have guided, and strengthen me with those whom You have given strength. Take me to Your care with those whom You have taken to Your care. Bless me in what You have given me. Protect me from the evil You have ordained. Surely, You command and are not commanded, and none whom You have committed to Your care shall be humiliated and none whom You have taken as an enemy shall taste glory. You are Blessed, Our Lord, and Exalted.\n\nHasan ibn Ali (RA) said about this Qunoot, \"The Messenger of Allah (ﷺ) taught me these words to say in the Witr prayer as the Witr Qunut.\""},{"id":279,"title":"Kunut Duası (Rabbi Einnî ve Lâ Tüin Aleyye)","ref":"Sahîh (Elbânî). Tirmizî: 3551","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_279.json","ar":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَيَّ وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَيَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِي (إِلَيَّ) وَانْصُرْنِيْ عَلَى مَنْ بَغَى عَلَيَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيْبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","latin":"Rabbi einnî ve lâ tüin aleyye, vensurnî ve lâ tensur aleyye, vemkür lî ve lâ temkür aleyye, vehdini ve yessirıl-hudâ lî (ileyye) vensurnî alâ men beğâ aleyye. Rabbic'alnî leke şekkâren leke zekkâren, leke rehhâben, leke mitvâen, leke muhbiten, ileyke evvâhen münîben. Rabbi tekabbel tevbetî, vağsil havbetî ve ecib da'vetî, ve sebbid hüccetî, ve seddid lisânî, vehdi kalbî, veslül sahîmete sadrî","tr":"Rabbim! Bana yardım et, aleyhime yardım etme; bana zafer ver, aleyhime zafer verme; benim için tedbir al, aleyhime tedbir alma; beni hidayete erdir ve hidayeti benim için kolaylaştır; aleyhime haksızlık edene karşı bana zafer ver. Rabbim! Beni Sana çok şükreden, Seni çok zikreden, Senden çok korkan, Sana çok itaat eden, Sana çok boyun büken, Sana çok dua edip yönelen bir kul kıl. Rabbim! Tövbemi kabul et, günahımı yıka, duamı kabul et, hüccetimi sağlam kıl, dilimi doğrult, kalbimi hidayete erdir ve göğsümdeki kini gider.","en":"My Lord, aid me and do not aid against me, and grant me victory and do not grant victory over me, plot for me and do not plot against me, guide me and facilitate guidance for me, grant me victory over those who transgress against me. My Lord, make me ever-grateful to You, ever-remembering of You, ever-fearful of You, ever-obedient to You, ever-humble to You, oft-turning and returning to You. My Lord, accept my repentance, wash my sin, answer my call, make firm my proof, make firm my tongue, guide my heart, and remove resentment from my heart (the treachery of my chest).\n\nIbn Abbas (RA) said, The Messenger of Allah (ﷺ) supplicated with this dua. One of the narrator of this hadith Abul Hasan Tanafisi (R) said, I asked Imaaam Waqi’ ibn Al-Jarrah (R) (196 H) (narrator of this hadith) that “Can I supplicate with this dua in Qunut of Witr prayer? He said, ”Yes”."},{"id":280,"title":"Kunut Duası (Allâhümme İnnâ Neste'înük)","ref":"Sahîh (Elbânî). İrvâü'l-Ğalîl: 2/170, Beyhakî: es-Sünenü'l-Kübrâ 2/211","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_280.json","ar":"اَللَّهُمَّ إِيَّاكَ نَعْبُدُ، وَلَكَ نُصَلِّي وَنَسْجُدُ، وَإِلَيْكَ نَسْعَى وَنَحْفِدُ، نَرْجُو رَحْمَتَكَ، وَنَخْشَى عَذَابَكَ، إِنَّ عَذَابَكَ بِالْكَافِرِينَ مُلْحَقٌ، اَللَّهُمَّ إِنَّا نَسْتَعِينُكَ، وَنَسْتَغْفِرُكَ، وَنُثْنِي عَلَيْكَ الْخَيْرَ، وَلَا نَكْفُرُكَ، وَنُؤْمِنُ بِكَ، وَنَخْضَعُ لَكَ، وَنَخْلَعُ مَنْ يَكْفُرُكَ","latin":"Allâhümme iyyâke na'büdü, ve leke nüsallî ve nescüdü, ve ileyke nes'â ve nahfidü, nercû rahmeteke, ve nahşâ azâbeke, inne azâbeke bilkâfirîne mülhak. Allâhümme innâ neste'înüke, ve nestagfiruke, ve nüsnî aleykel-hayr, ve lâ nekfüruke, ve nü'minü bike, ve nahdau leke, ve nahle'u men yekfürük","tr":"Allah'ım! Yalnızca Sana ibadet eder, Sana namaz kılar ve Sana secde ederiz. Sana koşar ve hizmetinde bulunuruz. Rahmetini umarız, azabından korkarız. Şüphesiz Senin azabın kâfirlere yetişir. Allah'ım! Senden yardım ister, Senden bağışlanma dileriz. Seni hayırla överiz. Seni inkâr etmeyiz, Sana iman ederiz, Sana boyun eğeriz ve Seni inkâr edeni reddederiz.","en":"O Allah, You alone do we worship and to You we pray and bow down prostrate. To You we hasten to worship and to serve. Our hope is for Your mercy and we fear Your punishment. Surely, Your punishment of the disbelievers is at hand. O Allah, we seek Your help and Your forgiveness, and we praise You beneficently. We do not deny You and we believe in You. We surrender to You and renounce whoever disbelieves in You."},{"id":281,"title":"Teheccüdden Önce Okunacak Dua (Âl-i İmrân Suresi'nin Son 10 Ayeti)","ref":"[1] Buhârî: 992 [2] Sahîh. Nesâî: 1626","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_281.json","ar":"إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِّأُولِي الْأَلْبَابِ ﴿١٩٠﴾ الَّذِينَ يَذْكُرُونَ اللَّـهَ قِيَامًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ﴿١٩١﴾ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ﴿١٩٢﴾ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ﴿١٩٣﴾ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ﴿١٩٤﴾فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لَا أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَىٰ ۖ بَعْضُكُم مِّن بَعْضٍ ۖ فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّـهِ ۗ وَاللَّـهُ عِندَهُ حُسْنُ الثَّوَابِ ﴿١٩٥﴾ لَا يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُوا فِي الْبِلَادِ ﴿١٩٦﴾ مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ ۚ وَبِئْسَ الْمِهَادُ ﴿١٩٧﴾ لَـٰكِنِ الَّذِينَ اتَّقَوْا رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا نُزُلًا مِّنْ عِندِ اللَّـهِ ۗ وَمَا عِندَ اللَّـهِ خَيْرٌ لِّلْأَبْرَارِ ﴿١٩٨﴾ وَإِنَّ مِنْ أَهْلِ الْكِتَابِ لَمَن يُؤْمِنُ بِاللَّـهِ وَمَا أُنزِلَ إِلَيْكُمْ وَمَا أُنزِلَ إِلَيْهِمْ خَاشِعِينَ لِلَّـهِ لَا يَشْتَرُونَ بِآيَاتِ اللَّـهِ ثَمَنًا قَلِيلًا ۗ أُولَـٰئِكَ لَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ ۗ إِنَّ اللَّـهَ سَرِيعُ الْحِسَابِ ﴿١٩٩﴾ يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّـهَ لَعَلَّكُمْ تُفْلِحُونَ ﴿٢٠٠﴾","latin":"İnne fî halkıs-semâvâti vel-ardı vahtilâfil-leyli ven-nehâri le-âyâtil-li-ülil-elbâb. Ellezeyne yezkürûnAllâhe kıyâmen ve ku'ûden ve alâ cünûbihim ve yetefekkerûne fî halkıs-semâvâti vel-ardı Rabbenâ mâ halakte hâzâ bâtılen Sübhâneke fekınâ azâben-nâr. Rabbenâ inneke men tüdhilın-nâre fekad ahzeytehû ve mâ lizzâlimîne min ensâr. Rabbenâ innenâ semi'nâ münâdiyen yünâdî lil-îmâni en âminû bi-Rabbikum feâmennâ; Rabbenâ fağfirlâ zünûbenâ ve keffir annâ seyyiâtinâ ve teveffenâ maal-ebrâr. Rabbenâ ve âtinâ mâ veadtenâ alâ rusülike ve lâ tuhzinâ yevmel-kıyâmeti inneke lâ tuhlifül-mî'âd...","tr":"(190) Şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün birbirinin ardınca gelip gitmesinde temiz akıl sahipleri için kesinlikle ibretler vardır. (191) Onlar ayaktayken, otururken ve yanları üzerine yatarken Allah'ı anar, göklerin ve yerin yaratılışını düşünür ve 'Rabbimiz! Bunu boşuna yaratmadın, Sen münezzehsin, bizi Cehennem azabından koru' derler. (192) Rabbimiz! Sen kimi Cehennem'e sokarsanız onu rezil etmişsindir. Zalimlerin de hiç yardımcısı yoktur. (193) Rabbimiz! Gerçekten biz 'Rabbinize iman edin' diye imana davet eden bir davetçiyi duyduk ve hemen iman ettik. Rabbimiz! Günahlarımızı bağışla, kötülüklerimizi ört ve canımızı iyilerle beraber al. (194) Rabbimiz! Resullerin aracılığıyla bize vadettiklerini bize ver, kıyamet gününde bizi rezil etme. Şüphesiz Sen vaadinden caymayacaksın. (195) Rableri de onlara icabet etti: 'Ben, erkek olsun kadın olsun, hiçbirinizin amelini boşa çıkarmayacağım. Hep birbirinizdensiniz. Hicret eden, yurtlarından çıkarılan, yolumda eziyete uğrayan, savaşan ve öldürülenlerin kötülüklerini mutlaka örteceğim ve onları Allah katından bir mükâfat olarak altından ırmaklar akan cennetlere koyacağım. Güzel mükâfat Allah katındadır.' (196) Kâfirlerin yeryüzünde rahatça dolaşmaları seni aldatmasın. (197) Bu kısa bir faydalanmadır. Sonra onların barınağı Cehennem'dir; ne kötü yataktır! (198) Fakat Rablerinden korkanlar için altından ırmaklar akan, içinde ebedî kalacakları cennetler vardır ki bu, Allah katından bir ikramdır. Allah katındakiler iyiler için en güzelidir. (199) Ehl-i Kitap'tan, Allah'a, size indirilene ve kendilerine indirilene, Allah'a boyun eğerek inanan, Allah'ın ayetlerini az bir bedelle değiştirmeyen kimseler de vardır. İşte bunların Rableri katında mükâfatları vardır. Şüphesiz Allah hesabı çabuk görendir. (200) Ey iman edenler! Sabredin, sabırda yarışın, savaşa hazır bulunun ve Allah'tan korkun ki kurtulasınız. (Âl-i İmrân Suresi 3:190-200)\n\nBaşka bir rivayette Peygamber (ﷺ) yatağından kalkarak gökyüzüne bakar ve Âl-i İmrân Suresi'nin son rükûsunun ilk beş ayetini okurdu. [2]","en":"(190) Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding. (191) Who remember Allah while standing or sitting or [lying] on their sides and give thought to the creation of the heavens and the earth, [saying], \"Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire. (192) Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers. (193) Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous. (194) Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\" (195) And their Lord responded to them, \"Never will I allow to be lost the work of [any] worker among you, whether male or female; you are of one another. So those who emigrated or were evicted from their homes or were harmed in My cause or fought or were killed - I will surely remove from them their misdeeds, and I will surely admit them to gardens beneath which rivers flow as reward from Allah, and Allah has with Him the best reward.\" (196) Be not deceived by the [uninhibited] movement of the disbelievers throughout the land. (197) [It is but] a small enjoyment; then their [final] refuge is Hell, and wretched is the resting place. (198) But those who feared their Lord will have gardens beneath which rivers flow, abiding eternally therein, as accommodation from Allah . And that which is with Allah is best for the righteous. (199) And indeed, among the People of the Scripture are those who believe in Allah and what was revealed to you and what was revealed to them, [being] humbly submissive to Allah . They do not exchange the verses of Allah for a small price. Those will have their reward with their Lord. Indeed, Allah is swift in account. (200) O you who have believed, persevere and endure and remain stationed and fear Allah that you may be successful. (Surah Al-Imran 3:190-200)\n\nIn another narration, The Prophet (ﷺ) used to get up from his bed and look at the sky and recite the first five verses of the last Ruku' of Surah Ali-Imran. [2]"},{"id":282,"title":"Teheccüd Namazı için Uyandığında Okunacak Zikir ve Dua","ref":"Hasen (Elbânî). Ebû Dâvûd: 766","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_282.json","ar":"اَللَّهُ أَكْبَرُ","latin":"Allâhü Ekber","tr":"Allah en büyüktür.","en":"Allah is the greatest."},{"id":283,"title":"İstikhare Duası","ref":"Buhârî 7/162, Nr. 1162, 7390","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_283.json","ar":"اَللَّهُمَّ إِنِّي أَسْتَخِيْرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوْبِ اَللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ (وَيُسَمِّي حَاجَتَهُ) خَيْرٌ لِي فِي دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ، فَاقْدُرْهُ لِي وَيَسِّرْهُ لِي ثُمَّ بَارِكْ لِي فِيهِ. [اَللَّهُمَّ] وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الْأَمْرَ شَرٌّ لِي فِي دِيْنِيْ وَمَعَاشِيْ وَعَاقِبَةِ أَمْرِيْ فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ ثُمَّ أَرْضِنِيْ بِهِ","latin":"Allâhümme innî estahîruke bi-ilmike, ve estakdiruke bi-kudretike, ve es'elüke min fadlikel-azîm fe-inneke takdiru ve lâ akdiru, ve ta'lemü ve lâ a'lemü, ve Ente allâmül-ğuyûb. Allâhümme in künte ta'lemü enne hâzel-emre hayrun lî fî dînî ve meâşî ve âkıbeti emrî, fakdürhü lî ve yessirhu lî sümme bârik lî fîh, (Allâhümme) ve in künte ta'lemü enne hâzel-emre şerrun lî fî dînî ve meâşî ve âkıbeti emrî fasrifhü annî vassrifnî anhü. Vakdür liyal-hayre haysü kâne sümme ardınî bih","tr":"Allah'ım! Senden ilminle hayır diliyor, kudretinle güç istiyorum ve büyük lütfunu talep ediyorum. Sen gücü yetensin, ben yetemem; Sen bilirsin, ben bilmem; Sen görünmezleri en iyi bilensin. Allah'ım! Bu işin benim için dinimde, geçimimde ve işimin akıbetinde hayırlı olduğunu biliyorsan onu bana nasip et, onu benim için kolaylaştır, sonra onda beni mübarek kıl. Allah'ım! Bu işin benim için dinimde, geçimimde ve işimin akıbetinde şerli olduğunu biliyorsan onu benden uzak tut ve beni ondan uzaklaştır. Nerede olursa olsun hayrı bana takdir et, sonra beni ondan razı kıl.\n\nCâbir b. Abdullâh (ra)'dan rivayet edildiğine göre şöyle demiştir: Peygamber (ﷺ) bize Kur'ân'dan bir sure öğretir gibi bütün işlerimizde istikhare namazı kılmayı öğretirdi. Şöyle buyururdu: 'Biriniz bir işe niyet ettiğinde farz dışında iki rek'at namaz kılsın, ardından şu duayı okusun: (yukarıdaki dua zikredilmiştir)'","en":"O Allah! I ask guidance from Your knowledge, And Power from Your Might and I ask for Your great blessings. You are capable and I am not. You know and I do not and You know the unseen. O Allah! If You know that this job is good for my religion and my subsistence and in my Hereafter. Then You ordain it for me and make it easy for me to get, And then bless me in it, and if You know that this job is harmful to me In my religion and subsistence and in the Hereafter. Then keep it away from me and let me be away from it. And ordain for me whatever is good for me, And make me satisfied with it.\n\nOn the authority of Jaabir Ibn 'Adbullaah (RA), he said: The Prophet (ﷺ) would instruct us to pray for guidance in all of our concerns, just as he would teach us a Soorah from the Quran. He would say: 'If any of you intends to undertake a matter then let him pray two supererogatory units [two rak'ah naafilah] of prayer and after which he should supplicate: (the above mentioned dua)"},{"id":284,"title":"Günahtan Sonra Tövbe Duası (2 Rek'at Namaz)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 1521","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_284.json","ar":"وَالَّذِينَ إِذَا فَعَلُوا فَاحِشَةً أَوْ ظَلَمُوا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلَىٰ مَا فَعَلُوا وَهُمْ يَعْلَمُونَ ﴿١٣٥﴾ أُولَٰئِكَ جَزَاؤُهُم مَّغْفِرَةٌ مِّن رَّبِّهِمْ وَجَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا ۚ وَنِعْمَ أَجْرُ الْعَامِلِينَ ﴿١٣٦﴾","latin":"Vellezeyne izâ fealû fâhışeten ev zalemû enfüsehüm zekeruAllâhe festağferû li-zünûbihim ve men yağfiruz-zünûbe illAllâhü ve lem yüsirrû alâ mâ feâlû ve hüm ya'lemûn. Ülâike cezâühüm mağfiretün mir-Rabbihim ve cennâtün tecrî min tahtihel-enhâru hâlidîne fîhâ ve ni'me ecrul-âmilîn.","tr":"(135) Onlar ki bir kötülük yaptıkları ya da kendilerine zulmettikleri zaman Allah'ı hatırlar, günahlarından dolayı hemen tövbe ederler. Günahları Allah'tan başka kim affedebilir ki? Bir de onlar, bilerek işledikleri günahta ısrar etmezler. (136) İşte onların mükâfatı Rableri katından bir bağışlanma ve altından ırmaklar akan Cennetlerdir; orada ebedî kalacaklardır. Amel edenlerin mükâfatı ne güzeldir! (Âl-i İmrân Suresi 3:135-136)","en":"(135) And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah ? - and [who] do not persist in what they have done while they know. (136) Those - their reward is forgiveness from their Lord and gardens beneath which rivers flow [in Paradise], wherein they will abide eternally; and excellent is the reward of the [righteous] workers. (Sura Ali Imran 3:135-136)"},{"id":285,"title":"Vefat Eden için Dua","ref":"Müslim: 920","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_285.json","ar":"اَللَّهُمَّ اغْفِرْ لَهُ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِيْنَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِيْنَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ","latin":"Allâhümmağfirlehû (kişinin ismi), verfa' derecetehû fil-mehdiyyîn, vahlüfhü fî akıbihî fil-ğâbirîn, vağfirlânâ ve lehû yâ Rabbel-âlemîn, vefseh lehû fî kabrihî, ve nevvir lehû fîh","tr":"Allah'ım! Onu (kişinin ismi) bağışla, hidayete erenlerin arasında derecesini yükselt ve geride kalan torunları arasında ona halef ihsan et. Ey âlemlerin Rabbi! Hem bize hem de ona bağışlanma ihsan et ve kabrini genişlet ve onu kabrinde nura garkyle.\n\nResûlullah (ﷺ) Ebû Seleme (ra)'nin (vefat ettiğinde) yanına geldi. Gözleri açık kalmıştı. Peygamber (ﷺ) gözlerini kapattı ve şöyle buyurdu: 'Can çıkınca göz de onu takip eder.' Aile fertlerinden bazıları ağladı ve feryat etti. Bunun üzerine şöyle buyurdu: 'Kendiniz için yalnızca hayır dua edin; zira melekler söylediklerinize 'Âmin' der.' Ardından şöyle dedi (dua yukarıda zikredilmiştir)","en":"O Allah, forgive him (person's name), raise his degree among those who are rightly guided, grant him a successor in his descendants who remain. Forgive us and him, O Lord of the Universe, and make his grave spacious, and grant him light in it.\n\nThe Messenger of Allah (ﷺ) came to Abu Salama (RA) (as he died). His eyes were fixedly open. Rasoolullah (ﷺ) closed them, and then said: When the soul is taken away the sight follows it. Some of the people of his family wept and wailed. So he said: Do not supplicate for yourselves anything but good, for angels say \"Amen\" to what you say. He then said- (The dua is mentioned above)"},{"id":287,"title":"Cenazeyi Kabre Koyarken Okunacak Dua","ref":"Sahîh. Ebû Dâvûd: 3213","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_287.json","ar":"بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُوْلِ اللَّهِ (ﷺ)","latin":"Bismillâhi ve alâ sünneti Resûlillâh","tr":"Allah'ın adıyla ve Resûlullah'ın (ﷺ) Sünneti'ne uygun olarak.","en":"With the Name of Allah and according to the Sunnah of the Messenger of Allah (ﷺ)."},{"id":288,"title":"Cenazeyi Kabre Koyarken Okunacak Dua","ref":"Sahîh. İbn Mâce: 1550","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_288.json","ar":"بِسْمِ اللَّهِ وَعَلَى مِلَّةِ رَسُوْلِ اللَّهِ","latin":"Bismillâhi ve alâ milleti Resûlillâh","tr":"Allah'ın adıyla ve Resûlullah'ın (ﷺ) milleti üzere.\n\nCenazeyi kabirde sağ yanı üzerine koymak sünnettir. Cenazeyi sırt üstü yatırıp elleri göğsünde kavuşturmaya dair bir delil yoktur. Toprak atarken Bismillâh dışında okunacak bir dua yoktur.","en":"With the Name of Allah and according to the millat of the Messenger of Allah (ﷺ).\n\nSunnah is to place the dead in the grave on his right side. There is no evidence to place the dead on his back and hands on the chest. When giving soil, there is no Dua to recite except Bismillah."},{"id":289,"title":"Cenazeyi Kabre Koyarken Okunacak Dua","ref":"Sahîh. İbn Mâce: 1270","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_289.json","ar":"بِسْمِ اللَّهِ وَفِي سَبِيلِ اللَّهِ وَعَلَى مِلَّةِ رَسُولِ اللَّهِ","latin":"Bismillâhi ve fî sebîlillâhi ve alâ milleti Resûlillâh (ﷺ)","tr":"Allah'ın adıyla, Allah yolunda ve Resûlullah'ın (ﷺ) milleti üzere.","en":"With the Name of Allah, in the path of Allah and according to the millat of the Messenger of Allah (ﷺ)"},{"id":290,"title":"Kabir Ziyaretinde Okunacak Dua (Esselâmü Aleyküm Yâ Ehled-Diyâr)","ref":"Müslim: 975","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_290.json","ar":"اَلسَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ إِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ","latin":"Esselâmü aleyküm ehled-diyâri minel-mü'minîne vel-müslimîn, ve innâ inşâAllâhü biküm lâhikûn, es'elüllâhe lenâ ve lekümül-âfiyeh","tr":"Mü'minlerden ve müslümanlardan olan kabir sakinlerine selam olsun. İnşâallah biz de size katılacağız. Allah'tan hem kendimiz hem de sizin için afiyet dilerim.\n\nBüreyde b. el-Husayb el-Eslemî (ra) şöyle rivayet etmiştir: Resûlullah (ﷺ) herkese mezarlığa gittiğinde bu duayı okumayı öğretirdi.","en":"Peace be upon you, the inhabitants of the grave, among the believers, and Muslims, and if Allah will then we shall join you. I pray to Allah peace for us and for you.\n\nBuraida ibnul husaib aslami (RA) narrated that the Messenger of Allah (ﷺ) used to teach them to recite this dua when anyone went to the graveyard."},{"id":291,"title":"Mezarlığa Girerken Okunacak Dua (Meşru Dua)","ref":"Sahîh. Mişkâtü'l-Mesâbîh: 1767","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_291.json","ar":"اَلسَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِيْنَ وَالْمُسْلِمِيْنَ وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِيْنَ مِنَّا وَالْمُسْتَأْخِرِيْنَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ","latin":"Esselâmü alâ ehlid-diyâri minel-mü'minîne vel-müslimîn, ve yerhümullâhül-müstakdimîne minnel-müstahrîn, ve innâ inşâAllâhü biküm lâ-lâhikûn","tr":"Bu yerde yatan mü'min ve müslümanlara selam olsun. Allah aramızdan daha önce gidenlerle sonradan gelenlere rahmet etsin. İnşâallah biz de size katılacağız.\n\nÂişe (ra) Resûlullah'a (ﷺ) mezarlık ziyaretinde ne söyleceğini sordu; O da ona şunu söylemesini buyurdu (Dua yukarıda zikredilmiştir).","en":"Peace be upon the inhabitants of this place among the believers and Muslims. May Allah have mercy upon those who have gone on ahead of us and those who come later on, and we will join you, if Allah wills.\n\nA’isha (RA) asked Allah’s messenger (ﷺ) what she should say, i.e. when visiting graves, and he told her to say (The Dua is mentioned above)."},{"id":292,"title":"Kabir Ziyaretinde Okunacak Dua (Mezarlık Duası)","ref":"Müslim: 249","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_292.json","ar":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُوْنَ","latin":"Esselâmü aleyküm dâre kavmin mü'minîn, ve innâ inşâAllâhü biküm lâhikûn","tr":"Ey mü'minler topluluğunun yurdu, size selam olsun. İnşâallah biz de size katılacağız.\n\nEbû Hüreyre (ra) şöyle dedi: 'Resûlullah (ﷺ) mezarlığa gitti ve bu sözleri söyledi.'","en":"Peace be upon you, O you who believe. We will meet you, if Allah willing.\n\nAbu Hurairah said, \"The Messenger of Allah (ﷺ) went to the graveyard and said these words.\""},{"id":293,"title":"Müslüman Kabirlerini Ziyaret Ederken Okunacak Dua (Mezarlık Duası)","ref":"Müslim: 974","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_293.json","ar":"اَلسَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِيْنَ وَأَتَاكُمْ مَا تُوعَدُونَ غَدًا مُؤَجَّلُونَ وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ اَللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ","latin":"Esselâmü aleyküm dâre kavmin mü'minîn, ve etâküm mâ tûadûn ğaden müaccelun, ve innâ inşâAllâhü biküm lâhikûn. Allâhümmağfir li-ehli Bakîil-ğarkad","tr":"Ey mü'min kabir sakinlerinin yurdu, size selam olsun! Size vadedilen, yarın size ulaşacak ve ertelenmiş olarak bekliyorsunuz. İnşâallah biz de size katılacağız. Allah'ım! Bakîü'l-Ğarkad mezarlığı sakinlerini bağışla.\n\nÂişe (ra) şöyle dedi: 'Resûlullah (ﷺ) bende kaldığında gecenin son vaktinde Bakî mezarlığına gider ve bu sözleri söylerdi.'","en":"Peace be upon you, O you who believers inhabitants of the grave! The promise that was given to you has come to you, and you are waiting for the day to come. And we will meet you by the will of Allah. O Allah, forgive the inhabitants of the Baqi graveyard.\n\nAyesha (RA) said, \"When Rasoolullah (ﷺ) stayed in my house, he used to go to the Baqi' graveyard at the last hour of night and say these words."},{"id":294,"title":"Cenaze Namazında Ölü için Okunacak Dua (Meşru Dua)","ref":"Sahîh (Elbânî). Ebû Dâvûd: 3201","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_294.json","ar":"اَللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا وَصَغِيرِنَا وَكَبِيرِنَا وَذَكَرِنَا وَأُنْثَانَا وَشَاهِدِنَا وَغَائِبِنَا اَللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِيمَانِ وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الْإِسْلَامِ اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تُضِلَّنَا بَعْدَهُ","latin":"Allâhümmağfir li-hayyinâ ve meyyitinâ, ve sağîrinâ ve kebîrinâ, ve zekerinâ ve ünsânâ, ve şâhidinâ ve ğâ'ibinâ. Allâhümme men ahyeytehû minnâ feahyihî alel-îmân, ve men teveffeytehu minnâ feteveffehu alel-İslâm, Allâhümme lâ tahrimnâ ecrehû ve lâ tudillenâ ba'deh","tr":"Allah'ım! Yaşayanlarımızı ve ölülerimizi, küçüklerimizi ve büyüklerimizi, erkeklerimizi ve kadınlarımızı, hazır bulunanlarımızı ve bulunmayanlarımızı bağışla. Allah'ım! İçimizden yaşattıklarını İman üzere yaşat; içimizden vefat ettirdiklerini İslam üzere vefat ettir. Allah'ım! Onun ecrinden bizi mahrum bırakma ve onun ardından bizi sapıtma.","en":"O Allah, forgive those of us who are living and those of us who are dead, those of us who are present and those of us who are absent, our young and our old, our male and our female. O Allah, to whomsoever of us You givest life grant him life as a believer, and whomsoever of us You takest in death take him in death as a follower of Islam. O Allah, do not withhold from us the reward (of faith) and do not lead us astray after his death."},{"id":295,"title":"Vefat Eden Erkek için Okunacak Dua (Cenaze Duası)","ref":"Müslim: 963","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_295.json","ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ وَأَكْرِمْ نُزُلَهُ وَوَسِّعْ مُدْخَلَهُ وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ وَأَدْخِلْهُ الْجَنَّةَ وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ [وَعَذَابِ النَّارِ]","latin":"Allâhümmağfir lehû verhemhû, ve âfihî va'fü anhü, ve ekrim nüzülehû, ve vessia müdhàlehû, vağsilhü bilmâi veş-şelci vel-beradi, ve nekıhhî minel-hatâyâ kemâ nekayteş-şevbel-ebyade mined-denesi, ve ebdilhü dâren hayran min dârihî, ve ehlen hayran min ehlihî, ve zevcan hayran min zevcihî, ve edhılhül-cennete, ve eızhü min azâbil-kabri (ve azâbin-nâr)","tr":"Allah'ım! Onu bağışla, ona rahmet et, ona afiyet ver ve onu affet. Ona ikramda bulun, girişini genişlet, onu su, kar ve dolu ile yıka. Onu hatalarından temizle, tıpkı beyaz elbisenin kirden temizlendiği gibi. Ona yurdundan daha iyi bir yurt, ailesinden daha iyi bir aile ve eşinden daha iyi bir eş ver. Onu Cennet'e koy ve onu kabir azabından [ve Cehennem azabından] koru.\n\nAvf b. Mâlik (ra) şöyle dedi: 'Resûlullah (ﷺ) cenaze namazını kıldığında bu duayı ondan ezberledim. Bu duayı duyunca o cenaze ben olsaydım diye düşündüm!' (Dua yukarıda zikredilmiştir)","en":"O Allah, forgive him and have mercy on him and give him strength and pardon him. Be generous to him and cause his entrance to be wide and wash him with water and snow and hail. Cleanse him of his transgressions as white cloth is cleansed of stains. Give him an abode better than his home, and a family better than his family and a spouse better than his spouse. Take him into Paradise and protect him from the punishment of the grave [and from the punishment of Hell-fire].\n\nAwf ibn Malik (RA) said, When the Messenger of Allah (ﷺ) performed the funeral prayer, I memorized this dua from him. Hearing this dua, I wished that the dead body would be me! (The dua is Mentioned above)"},{"id":296,"title":"Cenaze Namazında Okunacak Dua (Erkek için)","ref":"Sahîh Mevkûf (Elbânî). el-Muvatta: 539","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_296.json","ar":"اَللَّهُمَّ (إِنَّهُ) عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُوْلُكَ وَأَنْتَ أَعْلَمُ بِهِ اَللَّهُمَّ إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ وَإِنْ كَانَ مُسِيْئًا فَتَجَاوَزْ عَنْ سَيِّئَاتِهِ اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهُ وَلَا تَفْتِنَّا بَعْدَهُ","latin":"Allâhümme (innehû) abdüke vebnu abdike vebnu emetike, kâne yeşhedü en lâ ilâhe illâ ente, ve enne Muhammeden abdüke ve rasûlük, ve ente a'lemü bih. Allâhümme in kâne muhsinen fezid fî ihsânihî, ve in kâne müsîen fetecâvez an seyyiâtih. Allâhümme lâ tahrimnâ ecrehû ve lâ teftinnâ ba'deh","tr":"Allah'ım! Bu kişi senin kulun, erkek kulunun oğlu, kadın kulunun oğludur. Senden başka gerçek ilah olmadığına ve Hz. Muhammed'in (ﷺ) senin kulun ve elçin olduğuna şahitlik ederdi. Sen onu daha iyi bilirsin. Allah'ım! Eğer iyilik yapan biriyse iyiliğini artır; eğer günah işlediyse günahlarını bağışla. Allah'ım! Bizi onun ecrinden mahrum bırakma ve onun ardından bizi fitneye düşürme.","en":"O Allah, this man is Your servant, the son of Your male servant, the son of female servant. He testified that there is no true ilaah but you and that Muhammad (ﷺ) is your servant and your messenger. And you are more aware of it. O Allah, if he is a doer of good, then increase his goodness. And if he has sinned, then forgive him. O Allah, do not deprive us of His reward and do not tempt us after that."},{"id":297,"title":"Cenaze Namazında Okunacak Dua (Allâhümme Abdüke Vebnü Emetike)","ref":"Sahîh (Elbânî). el-Hâkim: 1/359","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_297.json","ar":"اَللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ اِحْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِنًا فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزْ عَنْهُ","latin":"Allâhümme abdüke vebnu emetike ihtâce ilâ rahmetike, ve ente ğaniyyün an azâbihî, in kâne muhsinen fezid fî hasenâtihî, ve in kâne müsîen fetecâvez anh","tr":"Allah'ım! Bu kişi senin erkek ve kadın kullarından birinin oğludur; senin rahmetine muhtaçtır. Sen ise onun azabına muhtaç değilsin. Eğer iyilik sahibi biriyse iyiliklerini artır; eğer günahkâr biriyse onu affet.","en":"O Allah, he is the son of One of Your male & female slave, he is in need of Your mercy, and You are not in need of his torment. If he was pious, then increase his rewards and if he was a sinner then pardon him."},{"id":298,"title":"Cenaze Namazında Vefat Eden için Okunacak Dua (Cenaze Duası)","ref":"Sahîh. Ebû Dâvûd: 3202","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_298.json","ar":"اَللَّهُمَّ إِنَّ (فُلَانَ بْنَ فُلَانٍ) فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ اَللَّهُمَّ فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","latin":"Allâhümme inne (fulânebne fulân) fî zimmetike ve habli civârike, fekıhî min fitnetil-kabri ve azâbin-nâri, ve ente ehlül-vefâi vel-hakk. Allâhümme fağfirlehû verhemhû inneke entel-Ğafûrür-Rahîm","tr":"Allah'ım! Şüphesiz [kişinin adı] senin himayende ve güvencenin ipindedir. Onu kabir fitnesinden ve ateş azabından koru. Sen vaadi yerine getiren ve hak olan zatsın. Allah'ım! Onu bağışla ve ona rahmet et. Şüphesiz sen çok bağışlayan, çok merhamet edenssin.","en":"O Allah, surely [name the person] is under Your protection, and in the rope of Your security, so save him from the trial of the grave and from the punishment of the Fire. You fulfill promises and grant rights, so forgive him and have mercy on him. Surely You are Most Forgiving, Most Merciful."},{"id":299,"title":"Cenaze Namazında Okunacak Dua (Kadın için)","ref":"Müslim: 963","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_299.json","ar":"اَللَّهُمَّ اغْفِرْ لَهَا وَارْحَمْهَا وَعَافِهَا وَاعْفُ عَنْهَا وَأَكْرِمْ نُزُلَهَا وَوَسِّعْ مُدْخَلَهَا وَاغْسِلْهَا بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهَا مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ وَأَبْدِلْهَا دَارًا خَيْرًا مِنْ دَارِهَا وَأَهْلًا خَيْرًا مِنْ أَهْلِهَا وَزَوْجًا خَيْرًا مِنْ زَوْجِهَا وَأَدْخِلْهَا الْجَنَّةَ وَأَعِذْهَا مِنْ عَذَابِ الْقَبْرِ [عَذَابِ النَّارِ]","latin":"Allâhümmağfir lehâ verhemhâ, ve âfihâ va'fü anhâ, ve ekrim nüzülehâ, ve vessia müdhàlehâ, vağsilhâ bilmâi veş-şelci vel-beradi, ve nekıhhâ minel-hatâyâ kemâ nekayteş-şevbel-ebyade mined-denesi, ve ebdilhâ dâren hayran min dârihâ, ve ehlen hayran min ehlihâ, ve zevcan hayran min zevcihâ, ve edhılhâl-cennete, ve eızhâ min azâbil-kabri [veya azâbin-nâr]","tr":"Allah'ım! Onu bağışla, ona rahmet et, ona afiyet ver ve onu affet. Ona ikramda bulun, girişini genişlet, onu su, kar ve dolu ile yıka. Onu hatalarından temizle, tıpkı beyaz elbisenin kirden temizlendiği gibi. Ona yurdundan daha iyi bir yurt, ailesinden daha iyi bir aile ve eşinden daha iyi bir eş ver. Onu Cennet'e koy ve onu kabir azabından [ve Cehennem azabından] koru.","en":"O Allah, forgive her and have mercy on her and give her strength and pardon her. Be generous to her and cause her entrance to be wide and wash her with water and snow and hail. Cleanse her of his transgressions as white cloth is cleansed of stains. Give her an abode better than her home, and a family better than her family and a spouse better than his spouse. Take her into Paradise and protect her from the punishment of the grave [and from the punishment of Hell-fire]."},{"id":300,"title":"Cenaze Namazında Okunacak Dua (Allâhümme İnnehâ Emetüke)","ref":"Sahîh Mevkûf (Elbânî). el-Muvatta: 539","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_300.json","ar":"اَللَّهُمَّ (إِنَّهَا) أَمَتُكَ وَبِنْتُ عَبْدِكَ وَبِنْتُ أَمَتِكَ كَانَتْ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُوْلُكَ وَأَنْتَ أَعْلَمُ بِهِ اَللَّهُمَّ إِنْ كَانَتْ مُحْسِنَةً فَزِدْ فِي إِحْسَانِهَا وَإِنْ كَانَتْ مُسِيْئَةً فَتَجَاوَزْ عَنْ سَيِّئَاتِهَا اَللَّهُمَّ لَا تَحْرِمْنَا أَجْرَهَا وَلَا تَفْتِنَّا بَعْدَهَا","latin":"Allâhümme (innehâ) emetüke vebnetü abdike vebnetü emetike, kânet teşhedü en lâ ilâhe illâ ente, ve enne Muhammeden abdüke ve rasûlük, ve ente a'lemü bih. Allâhümme in kânet muhsîneten fezid fî ihsânihâ, ve in kânet müsîeten fetecâvez an seyyiâtihâ. Allâhümme lâ tahrimnâ ecrehâ ve lâ teftinnâ ba'dehâ","tr":"Allah'ım! Bu kadın senin kulun, erkek kulunun kızı, kadın kulunun kızıdır. Senden başka gerçek ilah olmadığına ve Hz. Muhammed'in (ﷺ) senin kulun ve elçin olduğuna şahitlik ederdi. Sen onu daha iyi bilirsin. Allah'ım! Eğer iyilik yapan biriyse iyiliğini artır; eğer günah işlediyse günahlarını bağışla. Allah'ım! Bizi onun ecrinden mahrum bırakma ve onun ardından bizi fitneye düşürme.","en":"O Allah, this woman is Your servant, the daughter of Your male servant, the daughter of female servant. She testified that there is no true ilaah but you and that Muhammad (ﷺ) is your servant and your messenger. And you are more aware of it. O Allah, if she is a doer of good, then increase her goodness. And if she has sinned, then forgive her. O Allah, do not deprive us of her reward and do not tempt us after that."},{"id":301,"title":"Vefat Eden Kadın için Okunacak Dua (Cenaze Duası)","ref":"Sahîh (Elbânî). el-Hâkim: 1/359","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_301.json","ar":"اَللَّهُمَّ أَمَتُكَ وَبِنْتُ أَمَتِكَ اِحْتَاجَتْ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهَا، إِنْ كَانَتْ مُحْسِنَةً فَزِدْ فِي حَسَنَاتِهَا، وَإِنْ كَانَتْ مُسِيئَةً فَتَجَاوَزْ عَنْهَا","latin":"Allâhümme emetüke vebnetü emetike, ihtâcet ilâ rahmetike, ve ente ğaniyyün an azâbihâ, in kânet muhsîneten fezid fî hasenâtihâ, ve in kânet müsîeten fetecâvez anhâ","tr":"Allah'ım! Bu kadın senin erkek ve kadın kullarından birinin kızıdır; senin rahmetine muhtaçtır. Sen ise onun azabına muhtaç değilsin. Eğer iyilik sahibi biriyse iyiliklerini artır; eğer günahkâr biriyse onu affet.","en":"O Allah, she is the daughter of One of Your male & female slave, she is in need of Your mercy, and You are not in need of her torment. If she was pious then increase her rewards and if she was a sinner then pardon her."},{"id":302,"title":"Vefat Eden Kadın için Okunacak Dua (Cenaze Namazı)","ref":"Sahîh. Ebû Dâvûd: 3202","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_302.json","ar":"اَللَّهُمَّ إِنَّ (فُلَانَةَ بِنْتُ فُلَانٍ) فِي ذِمَّتِكَ وَحَبْلِ جِوَارِكَ فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ وَعَذَابِ النَّارِ وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، اَللَّهُمَّ فَاغْفِرْ لَهَا وَارْحَمْهَا إِنَّكَ أَنْتَ الْغَفُوْرُ الرَّحِيْمُ","latin":"Allâhümme inne (fulânete binte fulân) fî zimmetike, ve habli civârike, fekıhâ min fitnetil-kabri ve azâbin-nâri, ve ente ehlül-vefâi vel-hakk. Allâhümme fağfir lehâ verhemhâ inneke entel-Ğafûrür-Rahîm","tr":"Allah'ım! Şüphesiz [kişinin adı] senin himayende ve güvencenin ipindedir. Onu kabir fitnesinden ve ateş azabından koru. Sen vaadi yerine getiren ve hak olan zatsın. Allah'ım! Onu bağışla ve ona rahmet et. Şüphesiz sen çok bağışlayan, çok merhamet edenssin.","en":"O Allah, surely [name the person] is under Your protection, and in the rope of Your security, so save her from the trial of the grave and from the punishment of the Fire. You fulfill promises and grant rights, so forgive her and have mercy on her. Surely You are Most Forgiving, Most Merciful."},{"id":303,"title":"Bağışlanma için Cenaze Duası (Meşru Dua)","ref":"Hasen (İbn Hacer). er-Rabbâniyye 4/176","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_303.json","ar":"اَللَّهُمَّ أَنْتَ رَبُّهَا، وَأَنْتَ خَلَقْتَهَا، وَأَنْتَ هَدَيْتَهَا لِلْإِسْلَامِ، وَأَنْتَ قَبَضْتَ رُوْحَهَا، وَأَنْتَ أَعْلَمُ بِسِرِّهَا وَعَلَانِيَتِهَا، جِئْنَا شُفَعَاءَ فَاغْفِرْ لَهَا","latin":"Allâhümme ente rabbühâ, ve ente halaktehâ, ve ente hedeyteha lil-İslâm, ve ente kabadta rûhahâ, ve ente a'lemü bisırrihâ ve alâniyetihâ, ci'nâ şüfeâe fağfir lehâ","tr":"Allah'ım! Sen onun Rabbisin, onu sen yarattın, onu İslam'a hidayet ettin, ruhunu sen aldın ve onun gizlisini aşikârını sen daha iyi bilirsin. Ona şefaatçi olarak geldik; onu bağışla.","en":"O Allah, You are his Lord, You have created him, You have shown him the way to Islam, You have accepted his soul, You know all his open and secrets. We have come to intercede for him, so forgive him."},{"id":304,"title":"Vefat Eden Çocuk için Okunacak Dua (Meşru Dua)","ref":"Bkz. el-Muğnî, İbn Kudâme 3/416; Ayrıca bkz. ed-Dürûsü'l-Mühimme li-Âmmeti'l-Ümme, Şeyh Abdülaziz b. Abdullah b. Bâz (rahimehullâh), s. 15","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_304.json","ar":"اَللَّهُمَّ اجْعَلْهُ فَرَطًا وَذُخْرًا لِوَالِدَيْهِ، وَشَفِيعًا مُجَابًا، اَللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجُورَهُمَا، وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، اَللَّهُمَّ اغْفِرْ لِأَسْلَافِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ","latin":"Allâhümmec'alhü feratan ve zuhrân li-vâlideyhi, ve şefîan mücâbâ. Allâhümme sekkal bihî mevâzînehumâ ve a'zim bihî ücûrehumâ, ve elhıkhü bisâlihil-mü'minîn, vec'alhü fî kefâleti İbrâhîm, ve kıhî birahmetike azâbel-cahîm, ve ebdilhü dâren hayran min dârihî, ve ehlen hayran min ehlihî. Allâhümmağfir li-eslâfinâ ve efrâtinâ ve men sebekanâ bil-îmân","tr":"Allah'ım! Onu anne-babası için bir öncü, bir hazine ve kabul edilmiş bir şefaatçi kıl. Allah'ım! Onu onların terazilerini ağırlaştıracak bir vesile yap, ecrini büyüt. Onu sâlih mü'minlere kavuştur. Onu İbrahim'in (as) himayesine koy. Rahmetinle onu Cehennem azabından koru. Ona yurdundan daha güzel bir yurt ve ailesinden daha güzel bir aile ver. Allah'ım! Bizden önce gidenlerimizi, küçük yaşta vefat eden çocuklarımızı ve İmanla bizden önce geçenleri bağışla.","en":"O Allah, make him a precursor, a forerunner and a treasure for his parents and an answered intercessor. O Allah, make him weigh heavily in their scales (of good) and magnify their reward. Make him join the righteous of the believers. Place him in the care of Ibrahim (As). Save him by Your mercy from the torment of Hell. Give him a home better than his home and a family better than his family. O Allah, forgive those who have gone (i.e. passed away) before us, our lost children (by death), and those who have preceded us in Faith."},{"id":305,"title":"Cenaze Namazında Okunacak Dua","ref":"Sahîh (Şuayb el-Arnaût). el-Muvatta: 540","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_305.json","ar":"اَللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ الْقَبْرِ","latin":"Allâhümme eızhü min azâbil-kabr","tr":"Allah'ım! Onu kabir azabından koru.\n\nSaîd b. Müseyyeb (r)'den rivayet edilmiştir. Şöyle dedi: 'Hiç günah işlememiş bir çocuğun cenaze namazını Ebû Hüreyre (ra)'nin arkasında kıldım.' Orada Ebû Hüreyre (ra)'nin şöyle söylediğini duydum: (Dua yukarıda zikredilmiştir)","en":"O Allah, protect him from the torment of the grave.\n\nNarrated by Sa’eed Ibn Musayyib (R) He said, \"I perform janaza of a child behind Abu Hurairah (RA) who has never committed any sin.\" There I heard Abu Huraira (RA) say: (The dua is Mentioned above)"},{"id":306,"title":"Vefat Eden Çocuk için Okunacak Dua (Cenaze Duası)","ref":"Mevkûf Hasen (Elbânî). Ahkâmü'l-Cenâiz, s. 160","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_306.json","ar":"اَللَّهُمَّ اجْعَلْهُ لَنَا سَلَفًا وَّفَرَطًا وَّأَجْرًا","latin":"Allâhümmec'alhü lenâ selefan ve feratan ve ecran","tr":"Allah'ım! Onu bizim için bir öncü, bir hazine ve ecre vesile kıl.","en":"O Allah, make him for us a precursor, a forerunner and a cause of reward."},{"id":307,"title":"Vefat Eden için Bağışlanma Duası (Cenaze Duası)","ref":"Sahîh. Ebû Dâvûd: 3221","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_307.json","ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَثَبِّتْهُ","latin":"Allâhümmağfirlehû ve sebbithü","tr":"Allah'ım! Onu bağışla ve onu sabit kıl. (Kabir sorgusu sırasında)\n\nOsmân b. Affân (ra)'dan rivayet edilmiştir: Peygamber (ﷺ) bir ölüyü defnetmekten işini bitirdiğinde onun yanında (yani kabrinin başında) durur ve şöyle buyururdu: 'Kardeşiniz için bağışlanma dileyin ve onun için sebat isteyin; zira o şimdi sorguya çekilecek.'","en":"O Allah, forgive him, strengthen him (During question of grave)\n\nNarrated Uthman ibn Affan (RA) : Whenever the Prophet (ﷺ) became free from burying the dead, he used to stay at him (i.e. his grave) and say: Seek forgiveness for your brother, and beg steadfastness for him, for he will be questioned now."},{"id":308,"title":"Ölüm ve Sabır Duası (Meşru Dua)","ref":"Buhârî: 7377","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_308.json","ar":"إِنَّ لِلَّهِ مَا أَخَذَ وَلَهُ مَا أَعْطَى وَكُلٌّ عِنْدَهُ بِأَجَلٍ مُسَمًّى","latin":"İnnâ lillâhi mâ ehaze, ve lehü mâ a'tâ, ve küllün indehü bi-ecelin müsemmâ","tr":"Allah'ın aldığı şey ona aittir, verdiği de ona aittir; her şeyin onun katında belirlenmiş bir eceli vardır.\n\nÜsâme b. Zeyd (ra)'dan rivayet edilmiştir: Peygamber (ﷺ) ile birlikteydik; bu sırada ansızın kızlarından birinin, ölmek üzere olan oğlunu görmeye gelmesini isteyen habercisi geldi. Peygamber (ﷺ) haberciye şöyle buyurdu: (Dua yukarıda zikredilmiştir). Ona sabretmesini ve Allah'ın mükâfatını ummasını söyleyin.","en":"Whatever Allah takes is His, and whatever He gives is His, and everything with Him has a limited fixed term (in this world).\n\nNarrated by Usama bin Zaid (RA): We were with the Prophet (ﷺ) when suddenly there came to him a messenger from one of his daughters who was asking him to come and see her son who was dying. The Prophet (ﷺ) said (to the messenger), (The dua is Mentioned above). So order her to be patient and hope for Allah's reward."},{"id":309,"title":"Vefat için Taziye Duası (Meşru Dua)","ref":"el-Ezkâr li'n-Nevevî, s. 126","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_309.json","ar":"أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ","latin":"A'dhamAllâhü ecrek, ve ahsene azâeke ve ğafera li-meyyitik","tr":"Allah ecrini artırsın, sana (yas tutmada) sabır tevfiki ihsan etsin ve vefat edeninizi bağışlasın.","en":"May Allah increase your reward, grant you the tawfiq of patience (in mourning), and forgive the dead person."},{"id":310,"title":"Kadir Gecesi Duası (Allâhümme İnneke Afüvvün Kerîm Duası)","ref":"Sahîh (Elbânî). Tirmizî: 3513","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_310.json","ar":"اَللَّهُمَّ إِنَّكَ عَفُوٌّ (كَرِيْمٌ) تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي","latin":"Allâhümme inneke Afüvvün [Kerîm], tühibbül-afve fa'fü annî","tr":"Allah'ım! Şüphesiz sen çok affedicisin [çok cömertsin], affetmeyi seversin; beni affet.\n\nÂişe (ra) şöyle dedi: 'Ey Allah'ın Resûlü! Kadir Gecesi'nde dua etmeli miyim?' Bunun üzerine ona bu duayı öğretti. Bu dua Kadir Gecesi'ndeki namazın secdesinde, selamdan önce, selamdan sonra, diğer tüm gün ve gecelerdeki namazlarda ve normal zamanlarda da okunabilir.","en":"O Allah, indeed You are Pardoning [Generous], You love pardon, so pardon me.\n\nAyesha (RA) said, \"O Messenger of Allah (ﷺ), should I make du'a on Lailatul Qadr?\" Then he (ﷺ) taught me this du'a. This du'aa 'can be recited in the prostration of Salat on Laylat al-Qadr, before Salam, after salaam and on all other days and nights in all Salats and at normal times."},{"id":312,"title":"Hilal Görme Duası","ref":"Sahîh. Tirmizî: 3451","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_312.json","ar":"اَللَّهُمَّ أَهْلِلْهُ عَلَيْنَا بِالْيُمْنِ وَالْإِيْمَانِ وَالسَّلَامَةِ وَالْإِسْلَامِ رَبِّيْ وَرَبُّكَ اللَّهُ","latin":"Allâhümme ehlilhü aleynâ bil-yümni vel-îmân, ves-selâmeti vel-İslâm, rabbî ve rabbükAllâh","tr":"Allah'ım! Onu üzerimize bereket, İman, güvenlik ve İslam ile getir. Rabbim ve senin Rabbin Allah'tır.\n\nResûlullah (ﷺ) yeni ay gördüğünde bu duayı okurdu. Ramazan ve tüm ayların hilalini gördükten sonra bu duayı okumak Sünnettir.","en":"O Allah, bring it over us with blessing and faith, and security and Islam. My Lord and your Lord is Allah.\n\nRasulullah (ﷺ) used to say this dua when he saw the new moon. It is masnun to recite this dua after seeing the new moon of Ramadan and all the months."},{"id":313,"title":"İftar Duası","ref":"[1] Hasen (Elbânî). Ebû Dâvûd: 2357 [2] Zayıf (Elbânî). Ebû Dâvûd: 2358","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_313.json","ar":"ذَهَبَ الظَّمَاءُ وَابْتَلَّتِ الْعُرُوْقُ وَثَبَتَ الْأَجْرُ إِنْ شَاءَ اللَّهُ","latin":"Zehebedh-dhama'ü vebtelleti'l-urûku, ve sebetel-ecru inşâAllâh","tr":"Susuzluk gitti, damarlar ıslandı ve ecir inşâallah sabit oldu.\n\nNot: Yaygın olarak okunan 'Allâhümme leke sumtü ve alâ rızkike eftartü' hadisi zayıftır (da'îf).","en":"The thirst is gone, the veins are moistened and the reward is confirmed, if Allah wills.\n\nNote that, the widely practiced hadith 'Allahumma laka samtu wa 'ala rizqika aftartu' but, the hadith is da'if (weak). [2]"},{"id":314,"title":"İftar Duası","ref":"Hasen (Hâfız İbn Hacer). Tahrîcü'l-Ezkâr, Şerhu'l-Ezkâr: 4/342","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_314.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِرَحْمَتِكَ الَّتِي وَسِعَتْ كُلَّ شَيْءٍ أَنْ تَغْفِرَ لِي","latin":"Allâhümme innî es'elüke birahmetikel-letî vesia't külle şey'in en tağfiralî","tr":"Allah'ım! Her şeyi kuşatan rahmetinle beni bağışlamanı senden istiyorum.\n\nAbdullah b. Amr (ra) iftarda bu duayı okurdu.","en":"O Allah, I ask You by Your mercy, which encompasses all things, that You forgive me.\n\nAbdullah bin Amr (RA) used to say this dua during Iftar."},{"id":315,"title":"Oruçluyken Hakaret Edilince Okunacak Dua","ref":"Buhârî: 1894","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_315.json","ar":"إِنِّي صَائِمٌ، إِنِّي صَائِمٌ","latin":"İnnî sâimün, innî sâimün","tr":"Ben oruçluyum, ben oruçluyum.\n\nEbû Hüreyre (ra)'den rivayet edilmiştir: Resûlullah (ﷺ) şöyle buyurdu: 'Oruç bir kalkandır; öyleyse sizden biri oruç tuttuğunda zina etmesin ve cahilce davranmasın. Biri onunla kavga eder ya da ona hakaret ederse şöyle desin: (Dua yukarıda zikredilmiştir)'","en":"I am fasting. I am fasting.\n\nNarrated Abu Huraira (RA): The Messenger of Allah (ﷺ) said: Fasting is a shield; So if any one of you observes fasting, let him not commit adultery or foolishness; If someone fights him or insults him, let him say - (The dua is mentioned above)"},{"id":316,"title":"Birinin Evinde İftar Açarken Okunacak Dua","ref":"Sahîh. Ebû Dâvûd: 3854","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_316.json","ar":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","latin":"Eftera indekümüs-sâimûn, ve ekele taâmekümül-ebrâr, ve sallet aleyküm'ül-melâike","tr":"Yanınızda oruçlular orucunu açtı, iyiler yemeğinizi yedi ve melekler size dua etti.","en":"With you, those who are fasting have broken their fast, you have fed those who are righteous, and the angels recite their prayers upon you."},{"id":318,"title":"Yolculuk için Güçlü Dua (Meşru Dua)","ref":"Sahîh (Elbânî). Tirmizî: 3446","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_318.json","ar":"اَلْحَمْدُ لِلَّهِ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِيْنَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُوْنَ، اَلْحَمْدُ لِلَّهِ، اَلْحَمْدُ لِلَّهِ، اَلْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اَللّهُ أَكْبَرُ، (لَا إِلٰهَ إِلَّا أَنْتَ) سُبْحَانَكَ، إِنِّي ظَلَمْتُ نَفْسِيْ فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوْبَ إِلاَّ أَنْتَ","latin":"Elhamdülillâh. SübhânAllâhillezî sahhara lenâ hâzâ ve mâ künnâ lehû mukrinîn. Ve innâ ilâ Rabbinâ lemünkalibûn. Elhamdülillâh, elhamdülillâh, elhamdülillâh, Allâhü Ekber, Allâhü Ekber, Allâhü Ekber, (lâ ilâhe illâ ente) sübhâneke innî zalemtü nefsî fağfirlî, feinnehû lâ yağfirüz-zünûbe illâ ente","tr":"Hamd Allah'a mahsustur. Çabamızla hiçbir zaman sahip olamayacağımız bunu bize sağlayan O'na yücelik olsun. Şüphesiz biz Rabbimize dönücüleriz. Hamd Allah'a mahsustur, Hamd Allah'a mahsustur, Hamd Allah'a mahsustur. Allah en büyüktür, Allah en büyüktür, Allah en büyüktür. Yücesin sen, Allah'ım! Kendime zulmettim; beni bağışla; zira günahları yalnızca sen bağışlarsın.","en":"Praise is to Allah. Glory is to Him Who has provided this for us though we could never have had it by our efforts. Surely, unto our Lord we are returning. Praise is to Allah. Praise is to Allah. Praise is to Allah. Allah is the Most Great. Allah is the Most Great. Allah is the Most Great. Glory is to You. O Allah, I have wronged my own soul. Forgive me, for surely none forgives sins but You."},{"id":319,"title":"Yolculuk ve Koruma Duası (Seyahat Duası)","ref":"Müslim: 1342","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_319.json","ar":"اَللَّهُ أَكْبَرُ، اَللَّهُ أَكْبَرُ، اَللَّهُ أَكْبَرُ، سُبْحَانَ الَّذِيْ سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِيْنَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُوْنَ اَللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى، اَللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا وَاطْوِ عَنَّا بُعْدَهُ، اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيْفَةُ فِي الْأَهْلِ، اَللَّهُمَّ إِنِّيْ أَعُوْذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوْءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ","latin":"Allâhü Ekber, Allâhü Ekber, Allâhü Ekber. Sübhânellezî sahhara lenâ hâzâ ve mâ künnâ lehû mukrinîn. Ve innâ ilâ Rabbinâ lemünkalibûn. Allâhümme innâ nes'elüke fî seferinâ hâzel birre vet-takvâ, ve minel-ameli mâ terdâ, Allâhümme havvin aleynâ seferanâ hâzâ vatvi annâ bu'dehû, Allâhümme entes-sâhibü fis-seferi, vel-halîfetü fil-ehli, Allâhümme innî eûzü bike min ve'sâis-seferi, ve ke'âbetil-manzari, ve sûil-münkalebi fil-mâli vel-ehli","tr":"Allah en büyüktür (3 kez). Çabamızla hiçbir zaman sahip olamayacağımız bunu bize sağlayan O'na yücelik olsun. Şüphesiz biz Rabbimize dönücüleriz. Allâhım! Bu yolculuğumuzda senden iyilik ve takva ile seni razı edecek ameller istiyoruz. Allâhım! Bu yolculuğumuzu bize kolaylaştır ve uzaklığını azalt. Allâhım! Sen yolda yoldaşımızsın ve ailelerimizi emanet ettiğimiz Zat'sın. Allâhım! Bu yolculuğun zorluklarından, gözlere çarpan kötü manzaralardan ve dönüşte mal ile ailede musibete uğramaktan sana sığınırım.\n\nPeygamber (ﷺ) yolculuktan döndüğünde de bu duayı okur ve şunu eklerdi:","en":"Allah is the Most Great (3 times). Glory is to Him Who has provided this for us though we could never have had it by our efforts. Surely, unto our Lord we are returning. O Allah, we ask You on this our journey for goodness and piety, and for works that are pleasing to You. O Allah, lighten this journey for us and make its distance easy for us. O Allah, You are our Companion on the road and the One in Whose care we leave our family. O Allah, I seek refuge in You from this journey's hardships, and from the wicked sights in store and from finding our family and property in misfortune upon returning.\n\nAnd when the Prophet (ﷺ) returned from his journey, he would recite it and add to it:"},{"id":320,"title":"Yolcuya Peygamberî Vedâ Duası","ref":"Sahîh (Elbânî). İbn Mâce: 2825","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_320.json","ar":"أَسْتَوْدِعُكَ اللَّهَ الَّذِيْ لَا تَضِيْعُ وَدَائِعُهُ","latin":"Estevdi'ukallâhellezî lâ tedîu vedâiauh","tr":"Seni, hiçbir emanetini zayi etmeyen Allah'a emanet ediyorum.\n\nAllah'ın Resûlü (ﷺ) beni uğurladı ve şöyle dedi: (Yukarıdaki dua zikredilmiştir). Yolcu bu duayı uğurlayana söylemelidir. Ancak hem yolcu hem de uğurlayan bu duayı birbirleri için okuyabilir.","en":"I leave you in the care of Allah, as nothing is lost that is in His care.\n\nThe Messenger of Allah (ﷺ) gave me a send-off and said: (The dua is mentioned above). So, musaafir should say this dua to the farewell giver.But Musaafir and farewell giver both can supplicate this dua for each other."},{"id":321,"title":"Güvenli Seyahat İçin Güçlü Yolculuk Duası","ref":"Sahîh (Elbânî). Tirmizî: 3443","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_321.json","ar":"أَسْتَوْدِعُ اللَّهَ دِيْنَكَ وَأَمَانَتَكَ وَخَوَاتِيْمَ عَمَلِكَ","latin":"Estevdi'ullâhe dîneke, ve emâneteke, ve havâtîme amelike","tr":"Dînini, emanetini ve amellerinin sonunu Allah'a bırakıyorum.\n\nAbdullah ibn Ömer (r.a.) şöyle dedi: Allah'ın Resûlü (ﷺ) veda ederken elini tutup musafaha yaptı ve yukarıdaki duayı söyledi. Başka bir rivayette Abdullah ibn Yezîd el-Hatmî (r.a.) şöyle dedi: Allah'ın Resûlü (ﷺ) şu sözlerle veda ederdi. Ancak bu durumda tekil (ke) yerine çoğul (küm) kullandı: 'Estevdi'ullâhe dîneküm ve emânetiküm ve havâtîme a'mâliküm' — Dîninizi, emanetlerinizi ve amellerinizin sonunu Allah'a bırakıyorum.","en":"I leave your religion in the care of Allah, as well as your safety, and the last of your deeds.\n\nAbdullah ibn Umar (RA) said, The Messenger of Allah (ﷺ) said: when he bid farewell, he grab his hand and did musafaha and said the above mentioned dua.In another narration, Abdullah Ibn Yazid Khatmi (RA) said, The Messenger of Allah (ﷺ) bid farewell by saying these words. But in this case, he used plural (kum) instead of singular (ka): “Astad’iullaha diinaakum wa amaanatakum wa khawatima a’maalikum” I leave your religion in the care of Allah, as well as your safety, and the last of your deeds."},{"id":322,"title":"Güvenli Seyahat ve Bereket İçin Peygamberî Dua","ref":"Hasen (Elbânî). Tirmizî: 3444","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_322.json","ar":"زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ لَكَ ذَنْبَكَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ","latin":"Zevvedekallâhüt-takvâ, ve ğafere zenbeke, ve yessere lekel-hayre haysü mâ künte","tr":"Allah sana takva azığı versin, günahlarını bağışlasın ve nerede olursan ol hayırı sana kolaylaştırsın.\n\nEnes ibn Mâlik (r.a.) şöyle dedi: Bir adam Allah'ın Resûlü'ne (ﷺ) gelip 'Yolculuğa çıkmaya karar verdim, bana yol azığı ver' dedi. Bunun üzerine Peygamber (ﷺ) bu sözleri söyleyerek onun için dua etti.","en":"May Allah give you piety as your provision, forgive your sins, and make goodness easy for you wherever you are.\n\nAnas ibn Malik (RA) said, \"A man came to the Messenger of Allah (ﷺ) and said, 'I have decided to travel. Give me a Travel allowance.' Then he said these words and prayed for him."},{"id":324,"title":"Yeni Şehirde Güvenlik İçin İslamî Dua (Meşnu Dua)","ref":"Hasen li-Gayrihî (Elbânî). Sahîh İbn Huzeyme: 2565","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_324.json","ar":"اَللَّهُمَّ رَّبَّ السَّمَاوَاتِ السَّبْعِ وَمَا أَظْلَلْنَ، وَرَبَّ الْأَرَضِيْنَ السَّبْعِ ومَا أَقْلَلْنَ، ورَبَّ الشَّيَاطِيْنِ ومَا أَضْلَلْنَ، ورَبَّ الرِّيَاحِ وَمَا ذَرَيْنَ، أَسْأَلُكَ خَيْرَ هَذِهِ الْقَرْيَةِ وَخَيْرَ أَهْلِهَا، (وَخَيْرَ مَا فِيهَا) وَنَعُوذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا وشَرِّ مَا فِيهَا","latin":"Allâhümme Rabbes-semâvâtis-seb'i ve mâ ezlalne, ve Rabbel-aradînes-seb'i ve mâ akalne, ve Rabbeş-şeyâtîni ve mâ edlalne, ve Raber-riyâhi ve mâ zerayne. Es'elüke hayra hâzihil-karyeti ve hayra ehlihâ, ve hayra mâ fîhâ, ve neûzü bike min şerrihâ, ve şerri ehlihâ, ve şerri mâ fîhâ","tr":"Allâhım! Yedi göğün ve gölgelerindeki her şeyin Rabbi, yedi yerin ve taşıdığı her şeyin Rabbi, şeytanların ve saptırdıklarının Rabbi, rüzgârların ve savurduklarının Rabbi! Senden bu beldedeki hayrı, halkındaki hayrı ve içindeki hayrı istiyorum. Onun şerrinden, halkının şerrinden ve içindeki şerden sana sığınıyorum.\n\nSüheyb (r.a.) şöyle dedi: Peygamber (ﷺ) bir beldeyi görmeden önce bu sözleri söylerdi.","en":"O Allah, Lord of the seven heavens and all they overshadow, Lord of the seven worlds and all they uphold, Lord of the devils and all they lead astray, Lord of the winds and all they scatter. I ask You for the goodness of this town and for the goodness of its people, and for the goodness it contains. I seek refuge in You from its evil, from the evil of its people and from the evil it contains.\n\nSuhaib (RA) said that the Prophet (ﷺ) used to say these words whenever he saw a town before entering it."},{"id":325,"title":"Çarşıya Girerken Okunacak İslamî Dua (Meşnu Dua)","ref":"Sahîh (Elbânî). Tirmizî: 3449","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_325.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِهَا وَخَيْرِ أَهْلِهَا وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَشَرِّ أَهْلِهَا","latin":"Allâhümme innî es'elüke min hayrihâ ve hayri ehlihâ, ve eûzü bike min şerrihâ ve şerri ehlihâ","tr":"Allâhım! Bu yerin hayrını ve halkının hayrını senden istiyorum. Bu yerin şerrinden ve halkının şerrinden sana sığınıyorum.\n\nAbdullah ibn Mes'ûd'dan (r.a.) rivayet edilmiştir ki o, çarşının girişinde durur, bu duayı okur ve ardından çarşıya girerdi.","en":"Ya Allah! I ask you for the blessing of this place and the goodness of it’s inhabitant’s. And I take refuge in you from harm of this place and harm of it’s inhabitant’s.\n\nIt is narrated on the authority of 'Abdullah ibn Mas'ud (RA) that he stood at the entrance of the market, recited the du'a and entered the market."},{"id":329,"title":"Yolculukta Sabah Olunca Yolcu Duası","ref":"Müslim: 2718","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_329.json","ar":"سَمِعَ سَامِعٌ بِحَمْدِ اللَّهِ، وَحُسْنِ بَلَائِهِ عَلَيْنَا، رَبَّنَا صَاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذًا بِاللَّهِ مِنَ النَّارِ","latin":"Semi'a sâmi'un bi hamdillâhi ve hüsni belâihî aleynâ. Rabbenâ sâhibnâ, ve efdhil aleynâ âizen billâhi minen-nâr.","tr":"Dinleyen bir kulak, bize verdiği nimetler için Allah'a hamd ettiğimizi duymuştur. Rabbimiz! Bize yoldaş ol ve üzerimize lütfunu ihsan et. Cehennem'den Allah'a sığınırım.","en":"He Who listens has heard that we praise Allah for the good things He gives us. Our Lord, be with us and bestow Your favor upon us. I seek the protection of Allah from the Fire."},{"id":331,"title":"Allah'ın İsimleriyle Yolculuk Duası (Meşnu Dua)","ref":"Hûd Suresi: 41","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_331.json","ar":"بِسْمِ اللَّهِ مَجْرَاهَا وَمُرْسٰىهَآ ۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ","latin":"Bismillâhi mecrâhâ ve mürsâhâ inne Rabbî le ğafûrur-rahîm","tr":"Onun yürüyüşü de durması da Allah'ın adıyladır. Şüphesiz Rabbim çok bağışlayan, çok merhamet edendir.\n\nNot: Bu dua bir hayvana veya herhangi bir taşıta binerken okunacak bir dua değildir. Ancak ülkemizde pek çok aracın önüne bu dua yazılmakta ve şoför yolculuğa başlarken bu duayı okumaktadır; bu doğru değildir.","en":"In the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful.\n\nNote that, this Dua cannot be said while mounting an animal or any means of transport. However, in our country, this dua is written in front of many vehicles and the supervisor says this dua when starting the journey, which is wrong."},{"id":334,"title":"Koruma İçin İslamî Seyahat Duası","ref":"Hasen Sahîh (Elbânî). Ebû Dâvud: 2598","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_334.json","ar":"اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ اَللَّهُمَّ اطْوِ لَنَا الْأَرْضَ وَهَوِّنْ عَلَيْنَا السَّفَرَ","latin":"Allâhümme entes-sâhibü fis-seferi vel-halîfetü fil-ehli, Allâhümme innî eûzü bike min ve'sâis-seferi, ve ke'âbetil-münkalebi ve sûil-manzari fil-ehli vel-mâli, Allâhümmakti lennel-arda ve havvin aleynâs-sefere","tr":"Allâhım! Sen yolculukta yoldaşımız ve aileyi koruyansın. Allâhım! Yolculuğun sıkıntısından, dönüşte zarar bulmaktan ve aileme ile malıma dair gördüğüm kötü şeylerden sana sığınırım. Allâhım! Yolu bize yakın kıl ve yolculuğu bize kolaylaştır.","en":"O Allah, You are the Companion in the journey, and the One Who looks after the family; O Allah, I seek refuge in Thee from the difficulty of travelling, finding harm when I return, and unhappiness in what I see coming to my family and property. O Allah, make the length of his journey short for us, and the journey easy for us."},{"id":335,"title":"Güvenlik İçin İslamî Seyahat Duası (Meşnu Dua)","ref":"Sahîh (Elbânî). Tirmizî: 3447","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_335.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ فِي سَفَرِيْ هَذَا مِنَ الْبِرِّ وَالتَّقْوَى وَمِنَ الْعَمَلِ مَا تَرْضَى، اَللَّهُمَّ هَوِّنْ عَلَيْنَا الْمَسِيرَ وَاطْوِ عَنَّا بُعْدَ الْأَرْضِ اَللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الْأَهْلِ اَللَّهُمَّ اصْحَبْنَا فِي سَفَرِنَا وَاخْلُفْنَا فِي أَهْلِنَا","latin":"Allâhümme innî es'elüke fî seferî hâzâ minel-birri vet-takvâ, ve minel-ameli mâ terdâ. Allâhümme havvin aleynâl-mesîre, vatvi annâ bu'adel-ard. Allâhümme entes-sâhibü fis-seferi vel-halîfetü fil-ehli. Allâhümme ashıbnâ fî seferinâ vahlüfnâ fî ehlinâ","tr":"Allâhım! Bu yolculuğumda senden iyilik, takva ve seni razı edecek ameller istiyorum. Allâhım! Yolu bize kolaylaştır ve yerin uzaklığını bize yakın kıl. Allâhım! Sen yolculukta yoldaşımız ve aileyi koruyansın. Allâhım! Yolculuğumuzda bize yoldaş ol ve ailelerimizin koruyucusu ol.","en":"O Allah, I ask You in this journey of mine from the righteousness and piety and actions that which you are pleased with. O Allah, ease for us the path, and make near for us the distance of the land. O Allah, You are the companion in the journey, and the caretaker for the family. O Allah, accompany us in our journey, and take care of our families"},{"id":336,"title":"Hac Telbiyesi (Lebbeyke Allâhümme Lebbeyke Duası)","ref":"Buhârî: 1549, Müslim 2/841, No. 1184","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_336.json","ar":"لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ","latin":"Lebbeyk Allâhümme lebbeyk, lebbeyke lâ şerîke leke lebbeyk, innel-hamde ven-ni'mete leke vel-mülk, lâ şerîke lek.","tr":"Buyur Allâhım, buyur! Buyur, senin hiçbir ortağın yoktur, buyur! Şüphesiz hamd sana mahsustur, nimet de senin, mülk de senin. Senin hiçbir ortağın yoktur.\n\nİbn Ömer (r.a.) şöyle dedi: Allah'ın Resûlü'nün (ﷺ) saçları birbirine geçmişken bu telbiyeyi okuduğunu işittim. (Dua yukarıda zikredilmiştir.) Bunlardan fazla bir şey söylemedi.","en":"I am here at Your service, O Allah, I am here at Your service. I am here at Your service, You have no partener, I am here at Your service. Surely the praise, and blessings are Yours, and the dominion. You have no partener.\n\nNarrated Ibn 'Umar: I heard the Messenger of Allah (ﷺ), reciting this talbiyyah with his hair tied together. (The Dua is motioned above) He did not utter more words than this."},{"id":338,"title":"Yemânî Rüknü ile Hacer-ül Esved Arasındaki Dua","ref":"Hasen hadis. Ebû Dâvud: 1892","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_338.json","ar":"رَبَّنَا اٰتِنَا فِي الدُّنْيَا حَسَنَةً وَّفِي الْاٰخِرَةِ حَسَنَةً وَّقِنَا عَذَابَ النَّارِ","latin":"Rabbenâ âtinâ fid-dünyâ haseneten ve fil-âhirati haseneten ve kınâ azâben-nâr","tr":"Rabbimiz! Bize dünyada da güzellik ver, ahirette de güzellik ver ve bizi Cehennem azabından koru.\n\nAbdullah ibn Sâib (r.a.) şöyle dedi: Allah'ın Resûlü'nün (ﷺ) iki rükün arasında bu duayı okuduğunu işittim. (Dua yukarıda zikredilmiştir)","en":"Our Lord, grant us the good things in this world and the good things in the next life and save us from the punishment of the Fire.\n\nNarrated Abdullah Ibn Sa'ib (RA): I heard the Messenger of Allah (ﷺ) recite this prayer in the middle of two rukans. (The dua is Mentioned above)"},{"id":345,"title":"Safâ Merve Duası","ref":"[1] Bakara Suresi: 158 [2] Müslim 2/888, No. 1218; Ayet, Bakara Suresi'nin 158. ayetidir.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_345.json","ar":"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ","latin":"İnnes-Safâ vel-Mervete min şeâirillâh","tr":"Şüphesiz Safâ ile Merve, Allah'ın şiarlarındandır. [1]\n\nArdından şöyle derdi: Allah'ın başladığıyla ben de başlıyorum. Böylece Safâ'dan başlar ve Kâbe'yi görebileceği yere kadar çıkar, Kâbe'ye yönelir ve şöyle derdi:","en":"Indeed, as-Safa and al-Marwah are among the symbols of Allah. [1]\n\nAnd then say: I begin by that which Allah began. so he started with as-Safaa and climbed it until he could see the Ka'bah, he then faced it and said:"},{"id":347,"title":"Hayvan Kesme Duası (Bismillâh Allâhü Ekber)","ref":"Buhârî: 5565","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_347.json","ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ","latin":"Bismillâhi vAllâhü Ekber","tr":"Allah'ın adıyla, Allah en büyüktür!","en":"With the Name of Allah, Allah is the Most Great!"},{"id":348,"title":"Kurban Kesmeden Önce Okunan Dua (Kurban Duası)","ref":"Ahmed 4/400, No. 19586; Ebû Dâvud, 4/308, No. 5040","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_348.json","ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اَللَّهُمَّ مِنْكَ وَلَكَ] اَللَّهُمَّ تَقَبَّلْ مِنِّي","latin":"Bismillâhi vAllâhü Ekber [Allâhümme minke ve leke] Allâhümme tekabbel minnî","tr":"Allah'ın adıyla, Allah en büyüktür! [Allâhım! Senden geldi ve sana sunuluyor.] Allâhım! Benden kabul et.","en":"With the Name of Allah, Allah is the Most Great! [O Allah, from You and to You.] O Allah, accept it from me."},{"id":349,"title":"Kesim Anında Okunan Dua (Kurban Duası)","ref":"Müslim: 1967","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_349.json","ar":"بِسْمِ اللَّهِ اَللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ وَآلِ مُحَمَّدٍ وَمِنْ أُمَّةِ مُحَمَّدٍ","latin":"Bismillâhi, Allâhümme tekabbel min Muhammedin ve âli Muhammedin, ve min ümmeti Muhammedin","tr":"Allah'ın adıyla. Allâhım! Bunu Muhammed'den, Muhammed'in ailesinden ve Muhammed'in ümmetinden kabul et.\n\nArdından kurbanı kesti.","en":"In the name of Allah, O Allah, accept it from Muhammad, Muhammad's family and from Muhammad's Ummah (followers)\n\nThen he sacrificed it."},{"id":350,"title":"Hayvan Kurban Etme Duası","ref":"Sahîh. Ebû Dâvud: 2810","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_350.json","ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي","latin":"Bismillâhi vAllâhü Ekber hâzâ annî ve ammen lem yüdahhi min ümmetî","tr":"Allah'ın adıyla, Allah en büyüktür. Bu benden ve ümmetimden kurban kesemeyenler adınadır.","en":"In the name of Allah, Allah is Most Great. This is from me and from those who did not sacrifice from my community."},{"id":354,"title":"Şeytandan Korunmak İçin Güçlü Dua","ref":"Mü'minûn Suresi 23:97-98","url":"https://quran.com/23/97","ar":"رَبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ، وَأَعُوْذُ بِكَ رَبِّ أَن يَّحْضُرُونِ","latin":"Rabbi eûzü bike min hemezâtiş-şeyâtîn, Ve eûzü bike Rabbi en yahdurûn","tr":"Rabbim! Şeytanların vesveselerinden sana sığınırım. Ve Rabbim! Onların yanımda bulunmalarından da sana sığınırım.","en":"My Lord, I seek refuge in You from the incitements of the devils, And my Lord, I seek refuge from they be present with me."},{"id":355,"title":"Şeytandan Korunma Duası","ref":"Sahîh. Ebû Dâvud: 775","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_355.json","ar":"أَعُوْذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ مِنْ هَمْزِهِ وَنَفْخِهِ وَنَفْثِهِ","latin":"Eûzü billâhis-semîil-alîmi mineş-şeytânir-racîm min hemzihî ve nefhihî ve nefisihî","tr":"Her şeyi işiten ve her şeyi bilen Allah'a sığınırım; kovulmuş şeytandan, onun çıldırtmasından veya kötü vesvesesinden (hemz), kibir ve kibrinden (nefh) ve büyüsünden (nefs) korunmak için.","en":"I seek refuge in Allah, the All-Hearing and the All-Knowing from the accursed devil, from his madness or evil suggestion (Hamz), from his puffing up (Nafkh), and from his witchcraft (Nafth)."},{"id":357,"title":"Mescidde Şeytandan Korunma Duası","ref":"Sahîh. Ebû Dâvud: 466","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_357.json","ar":"أَعُوْذُ بِاللَّهِ الْعَظِيمِ وَبِوَجْهِهِ الْكَرِيمِ وَسُلْطَانِهِ الْقَدِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ","latin":"Eûzü billâhil-azîm, ve bi vechihi'l-kerîm, ve sultânihil-kadîm mineş-şeytânir-racîm","tr":"Yüce Allah'a, O'nun yüce yüzüne ve ezeli saltanatına sığınırım; kovulmuş şeytandan korunmak için.\n\nUkbe (r.a.) şöyle dedi: 'Kim bu duayı okursa, şeytan şöyle der: Bu adam tüm gün boyunca benden (kötülük ve tuzaktan) korundu.'","en":"I seek refuge in Allah, the Magnificent, and in His noble face, and in his eternal domain, from the accursed Devil.\n\nUqbah (RA) said, ‘When someone recites this du’a, the devil says, ‘This man escaped from me (evil and intrigue) for the whole day."},{"id":358,"title":"Mescide Girerken Okunan Dua (Meşnu Dua)","ref":"Sahîh. İbn Mâce: 773","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_358.json","ar":"اَللَّهُمَّ اعْصِمْنِي مِنَ الشَّيْطَانِ الرَّجِيمِ","latin":"Allâhümma'sımnî mineş-şeytânir-racîm","tr":"Allâhım! Beni kovulmuş şeytandan koru.","en":"O Allah, protect me from Satan the outcast."},{"id":361,"title":"Yeni Doğan Bebek İçin İslamî Dua","ref":"Sahîh (Elbânî). Ebû Dâvud: 441","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_361.json","ar":"بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ وَشَكَرْتَ الْوَاهِبَ وَبَلَغَ أَشُدَّهُ وَرُزِقْتَ بِرَّهُ","latin":"Bârekallâhü leke fil-mevhûbi lek, ve şekerte'l-vâhibe, ve belağa eşüddehu, ve ruzıkte birrehu.","tr":"Allah sana bağışladığı bu nimette bereket versin, bağışlayana (Allah'a) şükretmen nasip olsun, çocuk güçlü çağına ulaşsın ve onun iyiliğinden nasip alabilesin.","en":"May Allah bless you with His gift to you, and may you (the new parent) give thanks (to Allah - the giver), may the child reach the maturity of years, and may you be granted its righteousness."},{"id":362,"title":"Yeni Doğan Bebeğin Babası İçin Dua","ref":"İmam Nevevî, el-Ezkâr, s. 256/349'da bunu zikretmiştir.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_362.json","ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَزَاكَ اللَّهُ خَيْرًا وَرَزَقَكَ اللَّهُ مِثْلَهُ وَأَجْزَلَ اللَّهُ ثَوَابَكَ","latin":"Bârekallâhü leke ve bâreke aleyke, ve cezâkAllâhü hayran, ve rezekakAllâhü mislehû, ve eczelAllâhü sevâbeke","tr":"Allah sana bereket versin ve üzerine bereket yağdırsın. Allah sana hayırla mükâfat etsin ve sana bir o kadarını daha nasip etsin ve seni bol bol mükâfatlandırsın.","en":"May Allah bless you, and shower His blessings upon you, and may Allah reward you well and bestow upon you its like and reward you abundantly."},{"id":365,"title":"Sıkıntı Anında Dua (Kadder Allah Duası)","ref":"Müslim: 2664","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_365.json","ar":"قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ","latin":"Kadderallâhü ve mâ şâe feale","tr":"Allah takdir etti; O dilediğini yapar.\n\nEbû Hüreyre (r.a.) Allah'ın Resûlü'nün (ﷺ) şöyle buyurduğunu rivayet etti: Güçlü mümin, zayıf müminden daha hayırlı ve Allah katında daha sevilir; her birinde hayır vardır. Ancak sana fayda verecek şeye (ahirette) düşkün ol, Allah'tan yardım iste, acze düşme; başına bir şey geldiğinde: Şunu yapsaydım, böyle olmazdı, deme; ama şöyle de: (Yukarıda zikredilen dua). Çünkü senin 'şöyle yapsaydım'ın şeytana kapı açar.","en":"Allah has decreed and what He wills, He does.\n\nAbu Huraira (RA) reported Allah's Messenger (ﷺ) as saying: A strong believer is better and is more lovable to Allah than a weak believer, and there is good in everyone, (but) cherish that which gives you benefit (in the Hereafter) and seek help from Allah and do not lose heart, and if anything (in the form of trouble) comes to you, don't say: If I had not done that, it would not have happened so and so, but say: (The dua is Mentioned above) your \"if\" opens the (gate) for the Satan."},{"id":366,"title":"Stres ve Kaygı İçin Dua","ref":"Sahîh (İbn Hacer el-Askalânî). İbn Hibbân: 974","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_366.json","ar":"اَللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","latin":"Allâhümme lâ sehle illâ mâ ce'altehû sehlâ ve ente tec'alül-hazne izâ şi'te sehlâ","tr":"Allâhım! Senin kolaylaştırdığın şeyler dışında kolaylık yoktur. Dilersen zorluğu kolaylaştırırsın.","en":"O Allah, there is no ease other than what You make easy. If you want you can make difficult matter easy."},{"id":368,"title":"Horoz Öttüğünde veya Eşek Anırdığında Okunacak Dua (Eûzübillâhi Mineşşeytânirracîm)","ref":"[1] Buhârî: 3303 [2] Sahîh. Ebû Dâvud: 5103","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_368.json","ar":"أَعُوْذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيـمِ","latin":"Eûzü billâhi mineşşeytânirracîm","tr":"Kovulmuş şeytandan Allah'a sığınırım.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Horozun öttüğünü duyduğunuzda Allah'tan lütuf isteyin; zira (öttükleri, bir melek gördükleri anlamına gelir). Eşeğin anırdığını duyduğunuzda ise şeytandan Allah'a sığının; zira (anırmaları, şeytan gördükleri anlamına gelir). [1] Bir başka rivayette: Horozun öttüğünü duyduğunuzda Allah'ın lütfundan isteyin; zira bir melek görmüştür. Eşeğin anırdığını duyduğunuzda ise şeytandan Allah'a sığının; zira o şeytanı görmüştür.' [2]","en":"I seek refuge in Allah from Satan the outcast.\n\nThe Prophet (ﷺ) said, \"When you hear the crowing of rooster, ask for Allah's Blessings for (their crowing indicates that) they have seen an angel. And when you hear the braying of donkeys, seek Refuge with Allah from Satan for (their braying indicates) that they have seen a Satan. [1] In another narration when you hear the rooster crowing, ask Allah for some of His grace, for they have seen as angel; but when you hear donkey braying, seek refuge in Allah from the devil, for it has seen the devil. [2]"},{"id":370,"title":"İman Şüphelerinde Dua (Âmentü Billâhi Duası)","ref":"Müslim: 134","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_370.json","ar":"آمَنْتُ بِاللَّهِ وَرُسُلِهِ","latin":"Âmentü billâhi ve rusülih","tr":"Allah'a ve Resûllerine inandım.\n\nEbû Hüreyre'den (r.a.) rivayet edildi: Allah'ın Resûlü (ﷺ) şöyle buyurdu: 'İnsanlar birbirlerine soru sormaya devam edecekler; ta ki şu soruya gelinecek: Allah her şeyi yarattı, peki Allah'ı kim yarattı? Kendisini böyle bir durumla karşı karşıya bulan kimse şöyle desin: (Yukarıda zikredilen dua.)'","en":"I believe in Allah and His Messenger.\n\nIt is narrated on the authority of Abu Huraira (RA) that the Messenger of Allah (ﷺ) said: Men will continue to question one another till this is propounded: Allah created all things but who created Allah? He who found himself confronted with such a situation should say: (The dua is Mentioned above)"},{"id":371,"title":"Şeytanın Vesvesesine Karşı Güçlü Dua","ref":"Hasen. Ebû Dâvud: 4722","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_371.json","ar":"اَللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ","latin":"Allâhü Ehad. Allâhüs-Samed. Lem yelid ve lem yûled. Ve lem yekün lehû küfüven ehad","tr":"O Allah'tır, Bir'dir. Allah Samed'dir (her şey O'na muhtaçtır, O hiçbir şeye muhtaç değildir). Doğurmamış ve doğurulmamıştır. Hiçbir şey O'na denk ve benzer değildir.\n\nEbû Hüreyre (r.a.) Allah'ın Resûlü'nün (ﷺ) şöyle buyurduğunu rivayet etti: 'İnsanlar birbirlerine soru sormaya devam edecekler; ta ki şu söylenecek: Allah her şeyi yarattı, peki Allah'ı kim yarattı? Kim bununla karşılaşırsa şöyle desin: (Yukarıda zikredilen dua.)' Sonra sol tarafına üç kez tükürerek şeytandan Allah'a sığındı.","en":"He is Allah, [who is] One, Allah, the Eternal Refuge. He neither begets nor is born, Nor is there to Him any equivalent.\n\nAbu Hurairah (RA) reported that Messenger of Allah (ﷺ) said: People will continue to ask one another(questions) till this is pronounced: Allah created all things, but who created Allah ? Whoever comes across anything of that, he should say: (The dua is mentioned above) Then he spit three times on his left side, seeking refuge with Allah from Satan."},{"id":372,"title":"İmanı Güçlendirmek İçin Güçlü Dua","ref":"Hasen. Ebû Dâvud: 5110","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_372.json","ar":"هُوَ الْأوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ","latin":"Hüvel-Evvelü vel-Âhiru vez-Zâhiru vel-Bâtınü, ve Hüve bi külli şey'in Alîm","tr":"O, her şeyden önce var olan ve sonra da kalacak olandır; O açıktır ve gizlidir; O her şeyi hakkıyla bilendir. (Hadîd Sûresi 57:3)\n\nEbû Zümeyl (r.a.) şöyle dedi: İbn Abbâs'a (r.a.) sordum; kalbimde zor bir soru var. 'Nedir?' diye sordu. 'Allah'a yemin ederim ki, söyleyemiyorum' dedim. Bana 'Şüpheyle mi ilgili?' diye sordu ve güldü. Sonra şöyle dedi: Allah Teâlâ şu âyeti indirinceye kadar kimse bundan kurtulamaz: '(94) Sana indirdiğimizden şüphe ediyorsan, senden önce kitap okuyanlara sor. Yemin olsun ki, sana Rabbinden hak gelmiştir; artık şüphecilerden olma. (95) Allah'ın âyetlerini yalanlayanlardan da olma; aksi takdirde hüsrana uğrayanlardan olursun.' (Yûnus Sûresi 10:94-95)","en":"He is the First and the Last, the Most High and the Most Near. And He is the Knower of all things. (Sura Al-Hadid 57:3)\n\nAbu Zumayl (RA) said: I asked Ibn Abbas (RA), I have a difficult question in my mind. He asked: What is it? I replied: I swear by Allah, I cannot speak about it. He asked me: Is it something doubtful? and he laughed. He then said: No one could escape that, until Allah, the exalted, revealed: (94) So if you are in doubt, [O Muhammad], about that which We have revealed to you, then ask those who have been reading the Scripture before you. The truth has certainly come to you from your Lord, so never be among the doubters. (95) And never be of those who deny the signs of Allah and [thus] be among the losers. (Sura Yunus 10:94-95)"},{"id":373,"title":"Cehennem ve Deccâl'den Korunma Duası","ref":"Sahîh Müslim: 2867","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_373.json","ar":"نَعُوذُ بِاللَّهِ مِنْ عَذَابِ النَّارِ نَعُوذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ نَعُوذُ بِاللَّهِ مِنَ الْفِتَنِ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ الدَّجَّالِ","latin":"Neûzü billâhi min azâbin nâr. Neûzü billâhi min azâbil kabr. Neûzü billâhi minel fiteni mâ zahera minhâ ve mâ batan. Neûzü billâhi min fitnetid deccâl","tr":"Cehennem azabından Allah'a sığınırız. Kabir azabından Allah'a sığınırız. Görünen ve görünmeyen fitnelerden Allah'a sığınırız. Deccâl fitnesinden Allah'a sığınırız.","en":"We seek refuge with Allah from the torment of Hell, Seek refuge with Allah from the torment of the grave. We seek refuge with Allah from turmoil and its visible and invisible aspects. We seek refuge with Allah from the turmoil of the Dajjal."},{"id":379,"title":"Bağışlanma İçin Meşnu Dua (Rabbigfirlî ve Tüb Aleyye)","ref":"Sahîh. Ebû Dâvud: 1516","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_379.json","ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ (الْغَفُوْرُ)","latin":"Rabbigfirlî ve tüb aleyye inneke ente't-Tevvâbür-Rahîm [Bir rivayette er-Rahîm yerine el-Gaffûr geçmektedir]","tr":"Rabbim, beni bağışla ve tövbemi kabul et; şüphesiz Sen tövbeleri çokça kabul eden, çok merhametli olansın. [Bir rivayette 'tövbeleri çokça kabul eden' yerine 'çok bağışlayan' geçmektedir.]","en":"Lord, forgive me and repent for me, for you are The Most Merciful The Acceptor of Repentance. In another narration there is \"The Forgiver\" instead of \"The Acceptor of Repentance\""},{"id":380,"title":"Bağışlanma Duası (Estağfirullâhel Azîm)","ref":"[1] Sahîh (Elbânî). Ebû Dâvud: 1517 [2] Sahîh (Elbânî). Tirmizî: 3579 [3] Müslim: 482 [4] Müslim: 2702","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_380.json","ar":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ الَّذِيْ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ","latin":"Estağfirullâhel azîmellezî lâ ilâhe illâ hüvel hayyül kayyûmü ve etûbu ileyh","tr":"Kendisinden başka ibadete layık hiçbir ilah bulunmayan, Diri ve Kayyûm olan Yüce Allah'tan bağışlanma diler ve O'na tövbe ederim.\n\nAllah, savaş sırasında kaçmış olsa bile onu bağışlar.' [1] O (ﷺ) şöyle buyurdu: 'Rabbin kuluna en yakın olduğu an gecenin ortasıdır; o saatte Allah'ı zikredenlerden olabilirseniz öyle yapın.' [2] O (ﷺ) şöyle de buyurdu: 'Kulun Rabbine en yakın olduğu an secde hâlidir; bu nedenle orada çokça dua edin.' [3] O (ﷺ) şöyle de buyurdu: 'Şüphesiz kalbim bazen gaflete düşer; ben ise günde yüz kez Allah'tan bağışlanma dilerim.' [4]","en":"I seek the forgiveness of Allah the Mighty, Whom there is none worthy of worship except Him, the Living, the Eternal, and I repent to Him.\n\nAllah would forgive him even if he was one who fled during the advance of an army.\" [1] He (ﷺ) said: \"The nearest the Lord comes to His servant is in the middle of the night, so if you are able to be of those who remember Allah at that time, then be so.\" [2] He (ﷺ) also said: \"The nearest a servant is to his Lord is when he is prostrating, so supplicate much therein.\" [3] He (ﷺ) also said: \"Verily my heart becomes preoccupied, and verily I seek Allah\"s forgiveness a hundred times a day.\" [4]"},{"id":381,"title":"Bağışlanma Duası (Lâ İlâhe İllallâhül Halîmül Kerîm)","ref":"Sahîh isnâd (Ahmed Şâkir). Müsned Ahmed 2/39","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_381.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ الْحَلِيمُ الْكَرِيمُ، لَا إِلَهَ إِلَّا اللَّهُ الْعَلِيُّ الْعَظِيمُ، سُبْحَانَ اللَّهِ رَبِّ السَّمَوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْعَظِيمِ، اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","latin":"Lâ ilâhe illallâhül halîmül kerîm, lâ ilâhe illallâhül aliyyül azîm, sübhânallâhi rabbis semâvâtis seb'i ve rabbil arşil azîm, elhamdü lillâhi rabbil âlemîn","tr":"Allah'tan başka ilah yoktur; O Halîm'dir, Kerîm'dir. Allah'tan başka ilah yoktur; O Alî'dir, Azîm'dir. Yedi göğün Rabbi ve Azîm Arş'ın Rabbi olan Allah'ı tenzih ederim. Hamd, âlemlerin Rabbi Allah'a aittir.\n\nAlî ibn Ebî Tâlib'den (r.a.) rivayet edildi: Sana şu cümleleri öğreteyim mi; bunları söylersen zaten bağışlanmış olsan bile bağışlanırsın. (Sonra yukarıdaki cümleleri söyledi.)","en":"There is no true God but Allah the Most Patient, the Most Honorable. There is no true God but Allah the Most Exalted, the Most High. I am proclaiming the holiness of the Lord of the seven heavens and the Lord of the glorious throne. All praise is due to Allah, the Lord of the worlds.\n\n‘Narrated from Ali bin Abi Talib (RA), will I not teach you some sentences which if you say you will be forgiven even though you are forgiven (He then told the above sentences)"},{"id":382,"title":"Seyyidül İstiğfar Bağışlanma Duası","ref":"Buhârî: 6306","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_382.json","ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ، خَلَقْتَنِيْ وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ، أَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ، وَأَبُوءُ بِذَنْبِيْ فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","latin":"Allâhümme ente rabbî lâ ilâhe illâ ente, halaktenî ve ene abdüke, ve ene alâ ahdike ve va'dike mesteta'tü, eûzü bike min şerri mâ sana'tü, ebûü leke bini'metike aleyye, ve ebûü bizenbî, fagfirlî fe innehû lâ yagfirüzünûbe illâ ente","tr":"Allâhım! Sen benim Rabbimsin, Senden başka ibadete layık ilah yoktur. Beni Sen yarattın ve ben Senin kulunum. Gücüm yettiğince ahdine ve vaadine bağlıyım. İşlediğim kötülüklerin şerrinden Sana sığınırım. Bana olan nimetlerini kabul eder, günahımı da itiraf ederim. Beni bağışla; zira günahları yalnızca Sen bağışlarsın.","en":"O Allah, You are my Lord, none has the right to be worshipped except You, You created me and I am Your servant and I abide to Your covenant and promise as best I can, I take refuge in You from the evil of which I have committed. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for verily none can forgive sin except You."},{"id":383,"title":"Bağışlanma Duası (Nûh Sûresi)","ref":"Nûh Sûresi 71:10","url":"https://quran.com/71/10","ar":"اِسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا","latin":"İstagfirû Rabbeküm innehû kâne Gaffârâ.","tr":"Rabbinizden bağışlanma dileyin; şüphesiz O çok bağışlayandır.","en":"Ask forgiveness from your Lord; for He is Oft-Forgiving;"},{"id":384,"title":"Tövbe Duası (Nûr Sûresi)","ref":"Nûr Sûresi 24:31","url":"https://quran.com/24/31","ar":"وَتُوبُوٓا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ","latin":"Ve tûbû ilallâhi cemî'an eyyühel mü'minûne leallekum tüflihûn.","tr":"Ey müminler! Hepiniz Allah'a tövbe edin; umulur ki kurtuluşa erersiniz.","en":"And turn to Allah in repentance, all of you, O believers, that you might succeed."},{"id":385,"title":"Tövbe Duası (Tahrîm Sûresi)","ref":"Tahrîm Sûresi 66:8","url":"https://quran.com/66/8","ar":"يٰٓأَيُّهَا الَّذِينَ ءَامَنُوا تُوبُوٓا إِلَى اللَّهِ تَوْبَةً نَّصُوحًا","latin":"Yâ eyyühellezîne âmenû tûbû ilallâhi tevbeten nasûhâ.","tr":"Ey iman edenler! Allah'a samimi bir tövbe ile tövbe edin.","en":"O you who have believed, repent to Allah with sincere repentance."},{"id":386,"title":"Bağışlanma Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3:135","url":"https://quran.com/3/135","ar":"وَالَّذِينَ إِذَا فَعَلُوا فٰحِشَةً أَوْ ظَلَمُوٓا أَنفُسَهُمْ ذَكَرُوا اللَّهَ فَاسْتَغْفَرُوا لِذُنُوبِهِمْ وَمَن يَغْفِرُ الذُّنُوبَ إِلَّا اللَّهُ وَلَمْ يُصِرُّوا عَلٰى مَا فَعَلُوا وَهُمْ يَعْلَمُونَ","latin":"Vellezîne izâ fealu fâhişeten ev zalemû enfüsehüm zekerullâhe festagarferû lizünûbihim ve men yagfirüz-zünûbe illallâhü ve lem yüsirrû alâ mâ feâlû ve hüm ya'lemûn.","tr":"Onlar ki, bir kötülük işlediklerinde ya da kendilerine zulmettiklerinde Allah'ı anarlar ve günahlarının bağışlanmasını dilerler. Günahları Allah'tan başka kim bağışlayabilir ki? Ve bile bile yaptıkları günahta ısrar etmezler.","en":"And those who, when they commit an immorality or wrong themselves [by transgression], remember Allah and seek forgiveness for their sins - and who can forgive sins except Allah? - and [who] do not persist in what they have done while they know."},{"id":390,"title":"Nikâh Hutbesi (Hutbetü'l-Hâce)","ref":"[1] Âl-i İmrân Sûresi 3:102 [2] Nisâ Sûresi 4:1 [3] Ahzâb Sûresi 33:70-71. Sahîh (Elbânî). Tirmizî: 1105","url":"https://quran.com/3/102","ar":"إِنَّ الْحَمْدَ لِلَّهِ نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ أَشْهَدُ أَنْ لَّا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُّسْلِمُونَ يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً ۚ وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ ۚ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًۭا سَدِيدًا يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَمَنْ يُطِعِ اللَّهَ وَرَسُولَهُ فَقَدْ فَازَ فَوْزًا عَظِيمًا","latin":"İnnel-hamde lillâh nahmudühu ve nestâînühu ve nestağfiruh, ve neûzü billâhi min şürûri enfüsinâ ve min seyyiâti a'mâlinâ, men yehdihillâhu fe lâ mudille leh, ve men yudlil fe lâ hâdiye leh, eşhedü en lâ ilâhe illallâhu, ve eşhedü enne Muhammeden abduhû ve resûlüh. Yâ eyyühellezîne âmenüt-takullâhe hakka tükâtihî velâ temûtünne illâ ve entüm müslimûn. Yâ eyyühen-nâsüt-takû Rabbeküm ellezî halakakum min nefsin vâhidetin, ve halaka minhâ zevcehâ, ve besse minhumâ ricâlen kesîren ve nisâen, vet-takullâhellelzî tesâelûne bihî vel erhâm, innallâhe kâne aleyküm rakîbâ. Yâ eyyühellezîne âmenüt-takullâhe ve kûlû kavlen sedîden, yuslih leküm a'mâleküm ve yagfir leküm zünûbeküm, ve men yutîillâhe ve resûlehû fe kad fâze fevzen azîmâ.","tr":"Şüphesiz hamd Allah'a aittir; O'na hamd eder, O'ndan yardım diler, O'ndan bağışlanma isteriz. Nefislerimizin şerrinden ve amellerimizin kötülüğünden Allah'a sığınırız. Allah kimi hidayete erdirirse onu saptıracak yoktur; kimi de saptırırsa onu doğru yola iletecek yoktur. Allah'tan başka ibadete layık ilah olmadığına şahitlik ederim; Muhammed'in O'nun kulu ve Resûlü olduğuna şahitlik ederim. (Sonra şu âyetleri okur:) 'Ey iman edenler! Allah'tan, O'na yaraşır şekilde korkun; yalnızca Müslümanlar olarak ölün.' [1] 'Ey insanlar! Sizi tek bir nefisten yaratan, ondan eşini var eden ve ikisinden pek çok erkek ve kadın türeten Rabbinizden korkun. Adını kullanarak birbirinizden dilekte bulunduğunuz Allah'tan ve akrabalık bağlarını kesmekten sakının. Şüphesiz Allah üzerinizde gözetleyicidir.' [2] 'Ey iman edenler! Allah'tan korkun ve doğruyu konuşun. Ki Allah işlerinizi düzeltsin ve günahlarınızı bağışlasın. Kim Allah'a ve Resûlü'ne itaat ederse gerçekten büyük bir kurtuluşa ermiştir.' [3] Sonra ihtiyacından söz ederdi. [4]","en":"Indeed all Praise is for Allah, we praise Him, we seek His help and we ask His forgiveness. We seek refuge with Allah from the evil of our own souls and from the evil of our actions. Whoever Allah guides will never be led astray,and whomever Allah leads astray, no one can guide. I bear witness that there is no deity worthy of worship except Allah, and I bear witness that Muhammad is His slave and Messenger. (then reads the following verses) O you who believe! Fear Allah as He should be feared, and die not except as Muslims; [1] O Mankind! Fear your Lord, Who created you from a single person, and from him created his wife, and from them he created many men and women, and fear Allah through Whom you demand your mutual (rights). Surely, Allah is Ever Watchful over you; [2] O you who believe! Fear Allah, and speak (always) the truth He will direct you to do righteous good deeds and will forgive you your sins. And whosoever obeys Allah and His Messenger has indeed achieved a great success. [3]\n\nThen he would talk about his needs. [4]"},{"id":391,"title":"Sâlih Aile İçin Dua (Evlilik Duası)","ref":"Furkân Sûresi 25:74","url":"https://quran.com/25/74","ar":"رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ إِمَامًا","latin":"Rabbenâ heb lenâ min ezvâcinâ ve zürriyyâtinâ kurrate a'yünin vec'alnâ lil-müttekîne imâmâ.","tr":"Rabbimiz! Bize eşlerimizden ve soyumuzdan göz aydınlığı bağışla ve bizi müttakilere önder kıl.","en":"Our Lord, grant us from among our wives and offspring comfort to our eyes and make us an example for the righteous."},{"id":392,"title":"Yeni Evli Çift İçin Dua (Evlilik Duası)","ref":"Sahîh (Elbânî). Ebû Dâvud: 2130","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_392.json","ar":"بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ","latin":"Bârekallâhü leke, ve bâreke aleyke, ve ceme'a beyneküma fî hayr","tr":"Allah sana bereket versin, sana bereket yağdırsın ve ikinizi hayırda bir araya getirsin.\n\nEbû Hüreyre (r.a.) şöyle dedi: 'Allah'ın Resûlü (ﷺ) yeni evlileri tebrik ederken bunu söylerdi.'","en":"May Allah bless you, and shower His blessings upon you, and join you together in goodness.\n\nAbu Hurairah (RA) said, \"The Messenger of Allah (ﷺ) used to say this to congratulate the newlyweds.\""},{"id":393,"title":"Eşi Kabul Ederken Okunacak Dua","ref":"Hasen. Ebû Dâvud: 2160","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_393.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ وَأَعُوْذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ","latin":"Allâhümme innî es'elüke hayrehâ ve hayra mâ cebeltehâ aleyhi ve eûzü bike min şerrihâ ve min şerri mâ cebeltehâ aleyh","tr":"Allâhım! Onun iyiliğini ve onu üzerine yarattığın iyiliği Senden isterim; onun şerrinden ve onu üzerine yarattığın şerden Sana sığınırım.","en":"O Allah, I ask You for the goodness of her and the goodness upon which You have created her, and I seek refuge in You from the evil of her and from the evil upon which You have created her."},{"id":394,"title":"İlk Gerdek Gecesi Duası","ref":"Sahîh (Elbânî). Âdâbü'z-Zifâf: 24","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_394.json","ar":"اَللَّهُمَّ بَارِكْ لِي فِي أَهْلِي، وَبَارِكْ لِأَهْلِي فِيَّ اَللَّهُمَّ ارْزُقْهُمْ مِنِّي، وَارْزُقْنِي مِنْهُمْ، اَللَّهُمَّ اجْمَعْ بَيْنَنَا مَا جَمَعْتَ فِي خَيْرٍ، وفَرِّقْ بَيْنَنَا إِذَا فَرَّقْتَ فِي خَيْرٍ","latin":"Allâhümme bârik lî fî ehlî, ve bârik lî ehlî fiyye. Allâhümm-erzükhüm minnî, verzüknî minhüm. Allâhümmec-mâ' beynenâ mâ ceme'te fî hayr. ve ferrık beynenâ izâ ferrakte fî hayr","tr":"Yâ Allah! Ailem konusunda bana bereket ver ve benim yüzümden aileme bereket ver. Yâ Allah! Benden onlara rızık ver, onlardan da bana rızık ver. Yâ Allah! Aramızdaki hayırları birleştirdiğin gibi bizi de hayırda birleştir; ayrılık vermek istersen onu da hayırla ver.","en":"Ya Allah! Give barakah for me in my family and give barakah to me for my family. Ya Allah! give provision to them from me and give provision to me from them. Ya Allah! collect all the good in between us which you collected and if you separate any good from us then separate it with good."},{"id":395,"title":"Cinsel Birliktelik Öncesinde Okunacak Dua","ref":"Buhârî: 141","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_395.json","ar":"بِاسْمِ اللَّهِ اَللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا","latin":"Bismillâh. Allâhümme cennibneşşeytân, ve cennibişşeytâne mâ rezaktenâ","tr":"Allah'ın adıyla. Allâhım! Bizi şeytandan uzaklaştır ve bize rızık olarak verdiğini de şeytandan uzaklaştır.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Kim birliktelik öncesinde bunu söylerse, onlara bir çocuk verildiğinde şeytan o çocuğa zarar veremez.'","en":"With the Name of Allah. O Allah, keep the I Devil away from us and keep the Devil away from that which You provide for us.\n\nThe Prophet (ﷺ) said, “If anyone says this before sexual intercourse is consummated, the Shaytaan will not harm him if a child is born to them."},{"id":396,"title":"Yeni Ebeveynleri Tebrik Etmek İçin Dua","ref":"Bu söz Hasan el-Basrî'ye (rahimehullah) atfedilmektedir. Bkz. İbn Kayyim, Tuhfetü'l-Mevdûd, s. 20.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_396.json","ar":"بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوْبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ.","latin":"Bârekallâhü leke fil-mevhûbi leke, ve şekerte'l-vâhibe, ve belağa eşüddehû, ve rüzıkte birreh","tr":"Allah sana verdiği bu armağanda seni mübarek kılsın; bağışlayana şükretmeni nasip etsin; çocuk olgunluk çağına ulaşsın ve onun iyiliğini sana rızık eylesin.","en":"May Allah bless you with His gift to you, and may you (the new parent) give thanks, may the child reach the maturity of years, and may you be granted its righteousness."},{"id":397,"title":"İslamda Tebrike Cevap (Bârekallâhü Leke ve Cezâkallâhü Hayran)","ref":"Nevevî, el-Ezkâr, s. 349. Ayrıca bkz. Sâlim el-Hilâlî, Sahîhu'l-Ezkâr fî'n-Nevevî, 2/713. Daha fazla bilgi için bkz. ez-Zikr ve'd-Duâ ve'l-İlâc bi'r-Rukye, 1/416.","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_397.json","ar":"بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْرًا، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ","latin":"Bârekallâhü leke ve bâreke aleyke, ve cezâkAllâhü hayran, ve rezakakAllâhü mislehû, ve eczelAllâhü sevâbeke","tr":"Allah sana bereket versin ve üzerine bereket yağdırsın; Allah seni hayırla mükâfatlandırsın, sana bir benzerini nasip etsin ve seni bol bol ödüllendirsin.\n\nYukarıdaki tebrik ve cevap sahabelerden nakledilmiştir.","en":"May Allah bless you, and shower His blessings upon you, and may Allah reward you well and bestow upon you its like and reward you abundantly.\n\nThe above congratulations and answer are narrated from some of the Companions."},{"id":398,"title":"Kur'ânî Bağışlanma Duası","ref":"Bakara Sûresi 2:127-128","url":"https://quran.com/2/127","ar":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ ﴿١٢٧﴾ رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ ﴿١٢٨﴾","latin":"Rabbenâ tekabbel minnâ inneke Entes-Semîul-Alîm. Rabbenâ vec'alnâ müslimeyni leke ve min zürriyyetinâ ümmeten müslimelenleke ve erinâ menâsikenâ ve tüb aleynâ inneke Ente't-Tevvâbür-Rahîm.","tr":"(127) Rabbimiz! Bizden kabul et. Şüphesiz Sen işitensin, bilensin. (128) Rabbimiz! Bizi sana teslim olan müslümanlar kıl; soyumuzdan da sana boyun eğen bir ümmet çıkar; bize ibadet yerlerimizi göster ve tövbemizi kabul et. Şüphesiz Sen tövbeleri çok kabul eden, çok merhametlisin.","en":"(127) Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing.(128) Our Lord, and make us Muslims [in submission] to You and from our descendants a Muslim nation [in submission] to You. And show us our rites and accept our repentance. Indeed, You are the Accepting of repentance, the Merciful."},{"id":399,"title":"Çocuk Sahibi Olmak İçin Dua","ref":"Âl-i İmrân Sûresi 3:38","url":"https://quran.com/3/38","ar":"رَبِّ هَبْ لِي مِن لَّدُنكَ ذُرِّيَّةً طَيِّبَةً ۖ إِنَّكَ سَمِيعُ الدُّعَاءِ","latin":"Rabbi heb lî mil-ledünke zürriyyeten tayyibeh inneke Semîud-duâ.","tr":"Rabbim! Katından bana sâlih bir nesil bağışla. Şüphesiz Sen duayı hakkıyla işitensin.","en":"My Lord, grant me from Yourself a good offspring. Indeed, You are the Hearer of supplication."},{"id":400,"title":"Günahların Bağışlanması İçin Dua","ref":"İbrâhim Sûresi 14:40-41","url":"https://quran.com/14/40","ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ ﴿٤٠﴾ رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ ﴿٤١﴾","latin":"Rabbic'alnî mükîmes-Salâti ve min zürriyyetî Rabbenâ ve tekabbel düâ. Rabbengfir lî ve livâlideyye ve lil-mü'minîne yevme yekûmül-hisâb.","tr":"Rabbim! Beni ve soyumdan gelecekleri namazı dosdoğru kılanlardan eyle. Rabbimiz! Duamı kabul et. (40) Rabbimiz! Hesabın kurulacağı günde beni, annemi-babamı ve müminleri bağışla. (41)","en":"My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication.(40) Our Lord, forgive me and my parents and the believers the Day the account is established.(41)"},{"id":401,"title":"Anne Baba İçin Dua","ref":"İsrâ Sûresi 17:24","url":"https://quran.com/17/24","ar":"رَّبِّ ارْحَمْهُمَا كَمَا رَبَّيَانِي صَغِيرًا","latin":"Rabbir-hamhümâ kemâ rabbeyânî sağîrâ.","tr":"Rabbim! Onlar beni küçükken nasıl yetiştirdilerse, Sen de onlara öylece merhamet et.","en":"My Lord, have mercy upon them as they brought me up [when I was] small."},{"id":402,"title":"Rahmet ve Hayırlı Sonuç İçin Dua","ref":"Kehf Sûresi 18:10","url":"https://quran.com/18/10","ar":"رَبَّنَا آتِنَا مِن لَّدُنكَ رَحْمَةً وَهَيِّئْ لَنَا مِنْ أَمْرِنَا رَشَدًا","latin":"Rabbenâ âtinâ mil-ledünke rahmeten ve heyyi' lenâ min emrinâ rasedâ.","tr":"Rabbimiz! Katından bize rahmet bağışla ve işimizde bize doğru olanı hazırla.","en":"Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance."},{"id":404,"title":"Şükür ve Sâlih Amel İçin Dua","ref":"Neml Sûresi 27:19","url":"https://quran.com/27/19","ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ","latin":"Rabbi evzi'nî en eşküre ni'metekelletî en'amte aleyye ve alâ vâlideyye ve en a'mele sâlihan terdâhü ve edhılnî birahmetike fî ibâdikeşşâlihîn.","tr":"Rabbim! Bana ve anne-babama verdiğin nimete şükretmemi, razı olacağın sâlih ameller işlememi bana nasip et. Rahmetinle beni sâlih kulların arasına kat.","en":"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants."},{"id":405,"title":"Kur'ân'da Çocuk İçin Dua","ref":"Saffât Sûresi 37:100","url":"https://quran.com/37/100","ar":"رَبِّ هَبْ لِي مِنَ الصَّالِحِينَ","latin":"Rabbi heb lî mines-sâlihîn.","tr":"Rabbim! Bana sâlihlerden [bir çocuk] bağışla.","en":"My Lord, grant me [a child] from among the righteous."},{"id":406,"title":"Anne Baba, Güzel Amel ve Sâlih Aile İçin Dua","ref":"Ahkâf Sûresi 46:15","url":"https://quran.com/46/15","ar":"رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي ۖ إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ","latin":"Rabbi evzi'nî en eşküre ni'metekelletî en'amte aleyye ve alâ vâlideyye ve en a'mele sâlihan terdâhü ve aslıh lî fî zürriyyetî innî tübtü ileyke ve innî minel-müslimîn.","tr":"Rabbim! Bana ve anne-babama verdiğin nimete şükretmemi, razı olacağın sâlih ameller işlememi bana nasip et ve soyumu benim için ıslah et. Ben sana tövbe ettim ve gerçekten müslümanlardanım.","en":"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to work righteousness of which You will approve and make righteous for me my offspring. Indeed, I have repented to You, and indeed, I am of the Muslims."},{"id":407,"title":"Aileyi Şirkten Koruma Duası","ref":"İbrâhim Sûresi 14:35","url":"https://quran.com/14/35","ar":"رَبِّ اجْعَلْ هَـٰذَا الْبَلَدَ آمِنًا وَاجْنُبْنِي وَبَنِيَّ أَن نَّعْبُدَ الْأَصْنَامَ","latin":"Rabbic'el hâzel-belede âminen vecnübnî ve beniyye en na'budelesnem.","tr":"Rabbim! Bu şehri [Mekke'yi] güvenli kıl; beni ve oğullarımı puta tapmaktan uzak tut.","en":"My Lord, make this city [Makkah] secure and keep me and my sons away from worshipping idols."},{"id":408,"title":"Çocuk Sahibi Olamayan Kişinin Duası","ref":"Meryem Sûresi 19:5","url":"https://quran.com/19/5","ar":"وَإِنِّي خِفْتُ الْمَوَالِيَ مِن وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِن لَّدُنكَ وَلِيًّا ﴿٥﴾","latin":"Ve innî hiftül-mevâliye min verâî ve kânetim-raetî âkiran feheb lî mil-ledünke veliyyâ.","tr":"Gerçekten ben, ardımdan gelecek akrabalarımdan endişelendim; karım da kısır. Katından bana bir varis bağışla.","en":"And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir"},{"id":409,"title":"Cennet ve Bağışlanma İçin Dua","ref":"Gâfir Sûresi 40:7-9","url":"https://quran.com/40/7","ar":"رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ ﴿٧﴾ رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ﴿٨﴾ وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ﴿٩﴾","latin":"Rabbenâ vesi'te külle şey'ir-rahmeten ve ilmen fagfir lilleziyne tâbû vettebe'û sebîleke ve kıhim azâbel-Cahîm. Rabbenâ ve edhılhüm cennâti adninil-letî ve adtehüm ve men saleha min âbâihim ve ezvâcihim ve zürriyyâtihim; inneke Entel-Azîzül-Hakîm. Ve kıhimüs-seyyiât; ve men tekıs-seyyiâti yevme'izin fekad rahimteh; ve zâlike hüvel fevzül-azîm.","tr":"Rabbimiz! Sen her şeyi rahmet ve ilimle kuşatmışsın; tövbe eden ve senin yoluna uyanları bağışla ve onları Cehennem azabından koru. (7) Rabbimiz! Onları ve atalarından, eşlerinden ve soylarından sâlih olanları, onlara vaat ettiğin Adn cennetlerine koy. Şüphesiz Sen Azîz'sin, Hakîm'sin. (8) Onları kötülüklerden de koru. O gün kimi kötülüklerden korursan ona merhamet etmiş olursun; işte büyük kurtuluş odur. (9)","en":"Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire.(7) Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise.(8) And protect them from the evil consequences [of their deeds]. And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment.\" (9)"},{"id":410,"title":"Anne Babanın Bağışlanması İçin Dua","ref":"Nûh Sûresi 71:28","url":"https://quran.com/71/28","ar":"رَّبِّ اغْفِرْ لِي وَلِوَالِدَيَّ وَلِمَن دَخَلَ بَيْتِيَ مُؤْمِنًا وَلِلْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَلَا تَزِدِ الظَّالِمِينَ إِلَّا تَبَارًا","latin":"Rabbigfirlî ve livâlideyye ve limen dehale beytiye mü'minen ve lil-mü'minîne vel-mü'minât; ve lâ tezidiz-zâlimîne illâ tebârâ.","tr":"Rabbim! Beni, anne-babamı, evime mümin olarak gireni ve erkek-kadın tüm müminleri bağışla. Zalimleri ise yalnızca helake uğrat.","en":"My Lord, forgive me and my parents and whoever enters my house a believer and the believing men and believing women. And do not increase the wrongdoers except in destruction.\""},{"id":411,"title":"İbadeti ve Rızkı Artırmak İçin Dua","ref":"İbrâhim Sûresi 14:37","url":"https://quran.com/14/37","ar":"رَبَّنَا لِيُقِيمُوا الصَّلاةَ فَاجْعَلْ أَفْئِدَةً مِنَ النَّاسِ تَهْوِي إِلَيْهِمْ وَارْزُقْهُمْ مِنَ الثَّمَرَاتِ لَعَلَّهُمْ يَشْكُرُونَ","latin":"Rabbenâ li yükîmüs-Salâte fec'al ef'ideten minen-nâsi tehvî ileyhim verzükhüm mines-semerâti le'allehüm yeşkürûn.","tr":"Rabbimiz! Ben soyumdan bir kısmını senin Mukaddes Evi'nin yakınında, ekilmez bir vadiye yerleştirdim. Rabbimiz! Namazı dosdoğru kılsınlar diye (böyle yaptım). Öyleyse insanların kalplerini onlara yönelt ve meyvelerden onlara rızık ver; umulur ki şükrederler.","en":"Our Lord, I have settled some of my descendants in an uncultivated valley near Your sacred House, our Lord, that they may establish prayer. So make hearts among the people incline toward them and provide for them from the fruits that they might be grateful."},{"id":412,"title":"Borçtan Kurtulmak İçin Güçlü Dua","ref":"Hasen. Tirmizî: 3563","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_412.json","ar":"اَللَّهُمَّ اكْفِنِيْ بِحَلَالِكَ عَنْ حَرَامِكَ وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","latin":"Allâhümmekfinî bihâlâlike an harâmike ve ağninî bifadlike ammen sivâk","tr":"Allâhım! Haramın yerine helal olanla beni yetindir ve Senden başkasına muhtaç olmaktan beni koru.\n\nAlî (r.a.) şöyle nakletti: Yanıma bir mükateb geldi ve dedi ki: 'Kitabet bedelini ödeyemiyorum, bana yardım et.' Ben de dedim ki: 'Sana Allah'ın Resûlü'nün (ﷺ) bana öğrettiği kelimeleri öğreteyim mi? Sir dağı kadar borçlu olsaydın Allah onu senin için ödeyecekti.' Sonra şöyle buyurdu: (Yukarıda zikredilen dua.)","en":"O Allah, suffice me with what You have allowed instead of what You have forbidden, and make me independent of all others besides You.\n\nAli (RA) narrated: That a Mukatib came to him and said: “Indeed I am not capable of my Kitabah so aid me.” He said: “Should I not teach you words that the Messenger of Allah (ﷺ) taught me? If you had a debt upon you similar to the mountain of Sir, Allah would fulfill it for you. He said: (The dua is mentioned above)"},{"id":413,"title":"Stres, Kaygı ve Borç İçin Dua","ref":"Buhârî: 2893","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_413.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَالْعَجْزِ وَالْكَسَلِ وَالْبُخْلِ وَالْجُبْنِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","latin":"Allâhümme innî eûzü bike minel-hammi vel-hazen, vel'aczi vel-kesel, vel-buhli vel-cübn, ve dale'id-deyni ve galebetirrücâl","tr":"Allâhım! Keder ve üzüntüden, âcizlikten ve tembellikten, cimrilikten ve korkaklıktan, borç yükünden ve insanların baskısından Sana sığınırım.","en":"O Allah, I seek refuge in You from grief and sadness, from weakness and from laziness, from miserliness and from cowardice, from being overcome by debt and from being overpowered by men (i.e. other people)."},{"id":414,"title":"Borçtan Kurtulmak İçin Dua (Meşnu Dua)","ref":"Hasen (Elbânî). Sahîhü't-Terğîb: 1821","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_414.json","ar":"اَللَّهُمَّ مٰلِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَنْ تَشَاءُ وَتَنْزِعُ الْمُلْكَ مِمَّنْ تَشَاءُ وَتُعِزُّ مَنْ تَشَاءُ وَتُذِلُّ مَنْ تَشَاءُ بِيَدِكَ الْخَيْرُ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ رَحْمَانُ الدُّنْيَا وَالْآخِرَةِ وَرَحِيْمَهُمَا تُعْطِيْهِمَا مَنْ تَشَاءُ وَتَمْنَعُ مِنْهُمَا مَنْ تَشَاءُ ارْحَمْنِيْ رَحْمَةً تُغْنِيْنِيْ بِهَا عَنْ رَحْمَةِ مَنْ سِوَاكَ","latin":"Allâhümme mâlikel-mülki tü'til-mülke men teşâü, ve tenziul-mülke mimmen teşâü, ve tüizzu men teşâü ve tüzillü men teşâü, bi yedikel-hayrü inneke alâ külli şey'in kadîr, rahmâneddunyâ vel-âhirati ve rahîmehumâ, tü'tîhimâ men teşâü, ve temneühümâ men teşâü erhamnî rahmeten tuğnînî bihâ an rahmeti men sivâk","tr":"Allâhım! Mülkün sahibi! Mülkü dilediğine verirsin, dilediğinden alırsın; dilediğini yüceltir, dilediğini alçaltırsın. Hayır Senin elindedir. Şüphesiz Sen her şeye kadirsin. Dünyanın ve âhiretin Rahman'ı ve Rahîm'i! Dilediğine verirsin, dilediğinden alırsın. Bana öyle bir rahmet eyle ki onunla Senden başkasının rahmetine muhtaç kalmayayım.\n\nAllah'ın Resûlü (ﷺ) Muâz'a (r.a.) şöyle buyurdu: 'Bu duayı okursan bir dağ kadar borçlu olsan bile Allah senin borcunu öder.'","en":"O Allah, Master (and owner) of the Dominion (or Kingdom), You give the dominion to whom You will, and You take the dominion from whom You will, and You exalt whom You will, and You humiliate whom You will. In Your Hand is all goodness. Verily, You are Able to do all things. The Beneficent and the Merciful of this world and the hereafter, You bestow them on whomever You will and withhold them from whomever You will. Have mercy on me, (such) Mercy that would not make me in need of the mercy of others (than you).\n\nThe Messenger of Allah (ﷺ) said to Mu'adh (RA), 'If you pray this Dua, Allah will repay you even if you have a mountain of debt."},{"id":416,"title":"Günahlar, Borç ve Tembellik İçin Korunma Duası","ref":"Sahîh. Tirmizî: 3495","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_416.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ الْقَبْرِ، وَعَذَابِ الْقَبْرِ، وَشَرِّ فِتْنَةِ الْغِنَى، وَشَرِّ فِتْنَةِ الْفَقْرِ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، اَللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ. اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَالْهَرَمِ وَالْمَأْثَمِ وَالْمَغْرَمِ","latin":"Allâhümme innî eûzü bike min fitnatin-nâr, ve azâbin-nâr, ve fitnetil-kabr, ve azâbil-kabr, ve şerri fitnetil-ğınâ, ve şerri fitnetil-fakr, Allâhümme innî eûzü bike min fitnetil-mesîhid-deccâl. Allâhümmagsilhâtâyâye bi-mâis-selci vel-bered, ve nakkı kalbî minel-hatâyâ kemâ nekkaytet-sevbel-ebyade mined-denes, ve bâid beynî ve beyne hatâyâye kemâ bâatte beynel-meşrıkı vel-mağrib, Allâhümme innî eûzü bike minel-keseli vel-haremi vel-me'semi vel-mağrem","tr":"Allâhım! Cehennem fitnesinden, Cehennem azabından, kabir fitnesinden, kabir azabından, zenginlik fitnesinin şerrinden, fakirlik fitnesinin şerrinden ve Deccâl Mesîh'in fitnesinin şerrinden Sana sığınırım. Allâhım! Hatalarımı kar ve dolu suyu ile yıka; kalbimi hatalardan temizle, tıpkı beyaz elbiseyi kirden temizlediğin gibi; benimle hatalarım arasını, doğu ile batıyı uzaklaştırdığın gibi uzaklaştır. Allâhım! Tembellikten, bunaklıktan, günah ve borçtan Sana sığınırım.","en":"O Allah, indeed, I seek refuge in You from the trial of the Fire, and the punishment of the Fire, and the punishment of the grave, and the trial of the grave, and from the evil of the trial of the grave, and from the evil of the trials of wealth, and from the evils of the trials of poverty, and from the evil of the trial of the false Masih. O Allah, wash my sins with water of ice and hail, and cleanse my heart of sins, as You cleansed a white garment of filth, and distance me and my sins as You distanced between the east and the west. O Allah, indeed, I seek refuge in You from laziness, senility, sin and debt."},{"id":417,"title":"Borçtan Kurtulmak ve Zenginlik İçin Güçlü Dua","ref":"Müslim: 2713, Sahîh. Tirmizî: 3481","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_417.json","ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ، وَالْفُرْقَانِ، أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","latin":"Allâhümme Rabbes-semâvâtis-seb'i, ve Rabbel-Ardi, ve Rabbel-Arşil-Azîm, Rabbenâ ve Rabbe külli şey'in, fâlıkal-habbi ven-nevâ, ve münzilet-Tevrâti vel-İncîli, vel-Furkân, eûzü bike min şerri külli şey'in ente âhizun binâsıyetih. Allâhümme Entel-Evvelü fe leyse kableke şey'un, ve Entel-Âhiru fe leyse ba'deke şey'un, ve Entez-Zâhiru fe leyse fevkake şey'un, ve Entel-Bâtınu fe leyse dûneke şey'un, ikdi anned-deyne ve ağninâ minel-fakr","tr":"Allâhım! Yedi göğün Rabbi, yerin Rabbi, Azîm Arş'ın Rabbi; Rabbimiz ve her şeyin Rabbi; tohumu ve çekirdeği yaratan; Tevrat'ı, İncil'i ve Furkân'ı indiren! Alnından tuttuğun her şeyin şerrinden Sana sığınırım. Allâhım! Sen Evvel'sin, Senden önce hiçbir şey yoktur; Sen Âhir'sin, Senden sonra hiçbir şey yoktur; Sen Zâhir'sin, Senden üstün hiçbir şey yoktur; Sen Bâtın'sın, Senden daha yakın hiçbir şey yoktur. Borcumuzu bizden öde ve bizi fakirlikten kurtar.","en":"O Allah, Lord of the seven heavens and the exalted throne, our Lord and Lord of all things, Splitter of the seed and the date stone, Revealer of the Towraat, the Injeel and the Furqaan, I take refuge in You from the evil of all things You shall seize by the forelock. O Allah, You are The First so there is nothing before You and You are The Last so there is nothing after You. You are ath-Thaahir so there is nothing above You and You are al-Baatin so there is nothing closer than You. Settle our debt for us and spare us from poverty."},{"id":418,"title":"Borçtan Kurtulma ve Düşmanlara Karşı Dua","ref":"Sahîh. Nesâî: 5475","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_418.json","ar":"اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَغَلَبَةِ الْعَدُوِّ وَشَمَاتَةِ الْأَعْدَاءِ","latin":"Allâhümme innî eûzü bike min galebed-deyn, ve galebetil-adüvv, ve şemâtetel-a'dâ","tr":"Allâhım! Borç yüküne ezilmekten, düşman baskısına yenilmekten ve düşmanların benim felaketime sevinmesinden Sana sığınırım.","en":"O Allah, I seek refuge with You from being overwhelmed with debt, from being overpowered by the enemy and from the enemy rejoicing over my misfortunes."},{"id":419,"title":"Borç Geri Ödemesi İçin Dua (Meşnu Dua)","ref":"Sahîh. Nesâî: 4683","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_419.json","ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ، إِنَّمَا جَزَاءُ السَّلَفِ الْحَمْدُ وَالْأَدَاءُ","latin":"Bârekallâhü leke fî ehlike ve mâlike, innemâ cezâüs-selefil-hamdü vel-edâ'","tr":"Allah, ailende ve malında sana bereket versin. Şüphesiz borcun karşılığı övgü ve geri ödemedir.","en":"May Allah bless you in your family and your wealth, surely the reward for a loan is praise and returning (what was borrowed)."},{"id":420,"title":"Kaygı ve Depresyon İçin Dua","ref":"[1] Buhârî: 6346 [2] Sahîh İbn Hibbân 3/147, Müsned Ahmed 194","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_420.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ، الْعَظِيْمُ الْحَلِيْمُ لَا إِلَهَ إِلَّا اللَّهُ، رَبُّ الْعَرْشِ الْعَظِيْمِ لَا إِلَهَ إِلَّا اللَّهُ، رَبُّ السَّمَاوَاتِ، وَرَبُّ الْأَرْضِ، وَرَبُّ الْعَرْشِ الْكَرِيْمِ","latin":"Lâ ilâhe illAllâhül-Azîmül-Halîm, lâ ilâhe illAllâhü Rabbül-Arşil-Azîm, lâ ilâhe illAllâhü Rabbüs-semâvâti ve Rabbül-ardi ve Rabbül-Arşil-Kerîm","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; O, Azîm'dir, Halîm'dir. Allah'tan başka ibadete layık hiçbir ilah yoktur; O, yüce Arş'ın Rabbidir. Allah'tan başka ibadete layık hiçbir ilah yoktur; O, göklerin Rabbi, yerin Rabbi ve şerefli Arş'ın Rabbidir.\n\nPeygamber (ﷺ) sıkıntı anında şöyle dua ederdi (yukarıdaki dua). [1] Ali (r.a.) şöyle dedi: Allah'ın Resûlü (ﷺ) bana sıkıntı ve keder halinde yukarıda zikredilen duayı öğretti. [2]","en":"There is none worthy of worship but Allah the Mighty, the Forbearing. There is none worthy of worship but Allah, Lord of the Magnificent Throne. There is none worthy of worship but Allah, Lord of the heavens and Lord of the earth, and Lord of the Noble Throne.\n\nThe Prophet (ﷺ) used to invoke Allah at the time of distress, saying, (the dua is mentioned above). [1] Ali (RA) said, The Messenger of Allah taught me this above mentioned dua in the state of anxiety and distress. [2]"},{"id":421,"title":"Stres, Kaygı ve Depresyon İçin Dua","ref":"Ebû Dâvud: 1525","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_421.json","ar":"اَللَّهُ اَللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","latin":"Allâhü Allâhü Rabbî, lâ üşrikü bihî şey'â.","tr":"Allah, Allah benim Rabbimdir. O'na hiçbir şeyi ortak koşmam.\n\nEsmâ binti Umeys'ten (r.anhâ) rivayet edildi: Allah'ın Resûlü (ﷺ) bana şöyle dedi: Sıkıntı anında söyleyeceğin sözleri sana öğreteyim mi? Bunlar: (Yukarıda zikredilen dua.)","en":"Allah, Allah is my Lord. I do not associate anything with Him.\n\nNarrated Asma' daughter of Umays (RA): The Messenger of Allah (ﷺ) said to me: May I not teach you phrases which you utter in distress? These are: (The dua is mentioned avobe)"},{"id":422,"title":"Sıkıntı İçin Dua","ref":"Sahîh (Elbânî). Silsile-i Sahîha: 1/337","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_422.json","ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ، وَابْنُ عَبْدِكَ، وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُــــلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيعَ قَلْبِي، وَنُورَ صَدْرِي، وَجَلَاءَ حُزْنِي، وَذَهَابَ هَمِّي","latin":"Allâhümme innî abdüke, vebnü abdike, vebnü emetike, nâsıyetî biyedike, mâdın fiyye hükmüke, adlün fiyye kadâüke, es'elüke bikülli ismin hüve leke, semmeyte bihî nefseke, ev enzeltehu fî kitâbike, ev allemtehu ehaden min halkike, ev ista'serte bihî fî ilmil-ğaybi indeke, en tec'alel-Kur'âne rabîa kalbî, ve nûra sadrî, ve celâe huznî, ve zehâbe hemmî","tr":"Allâhım! Ben Senin kulun, erkek kulunun oğlu ve cariyenin oğluyum. Alnım Senin elindedir (benim üzerimde tasarruf hakkın vardır). Hakkımdaki hükmün geçerlidir, hakkımdaki kazân adaletlidir. Seni, Kendine verdiğin, Kitabında indirdiğin, yarattıklarından birine öğrettiğin veya Sende bulunan gayb ilminde Sana sakladığın her isminle şu şeyi istiyorum: Kur'ân'ı kalbimin baharı, göğsümün nuru, hüznümün gidericisi ve sıkıntımın gidericisi kıl.\n\nAllah şüphesiz onun sıkıntısını ve kederini giderir ve yerini sevinçle doldurur. 'Ya Resûlullah, bunu öğrenmeli miyiz?' diye soruldu. Peygamber (ﷺ) şöyle buyurdu: 'Elbette! Bunu duyan herkes ezberlemeli.'","en":"O Allah, I am Your slave and the son of Your male slave and the son of your female slave. My forehead is in Your Hand (i.e. you have control over me). Your Judgment upon me is assured and Your Decree concerning me is just. I ask You by every Name that You have named Yourself with, revealed in Your Book, taught any one of Your creation or kept unto Yourself in the knowledge of the unseen that is with You, to make the Qur'an the spring of my heart, and the light of my chest, the banisher of my sadness and the reliever of my distress.\n\nAllah will surely remove his worries and troubles and replace them with joy. ”It was asked, O Messenger of Allah! Shall we not learn it? ' The Prophet (ﷺ) said, “Of course! Anyone who hears this should memorize it.”"},{"id":424,"title":"Kaygı ve Depresyon Duası","ref":"[1] Hasen. Ebû Dâvud: 5090 [2] Buhârî: 2893","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_424.json","ar":"اَللَّهُمَّ رَحْمَتَكَ أَرْجُو، فَلَا تَكِلْنِي إِلَى نَفْسِي طَرْفَةَ عَيْنٍ، وَأَصْلِحْ لِي شَأْنِي كُلَّهُ، لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümme rahmeteke ercû felâ tekilnî ilâ nefsî tarfete ayn, ve aslih lî şe'nî küllehû, lâ ilâhe illâ ente","tr":"Allâhım! Senin rahmetini umuyorum. Beni bir göz kırpımı kadar (bir an bile) kendi başıma bırakma. Tüm işlerimi benim için düzelt. Senden başka ibadete layık hiçbir ilah yoktur.\n\nPeygamber (ﷺ) bu duayı çokça okurdu.","en":"O Allah, I hope for Your mercy. Do not leave me to myself even for the blinking of an eye (i.e. a moment). Correct all of my affairs for me. There is none worthy of worship but You.\n\nProphet (ﷺ) used to say this supplication increasingly."},{"id":426,"title":"Başkasının Sıkıntısını Görünce Okunacak Dua","ref":"Sahîh. Tirmizî: 3432","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_426.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِي مِمَّا ابْتَلَاكَ بِهِ، وَفَضَّلَنِي عَلَى كَثِيرٍ مِمَّنْ خَلَقَ تَفْضِيلًا","latin":"Elhamdülillâhillezî âfânî mimmebtelâke bihî ve faddalenî alâ kesîrin mimmen halaka tafdîlâ","tr":"Seni içine düşürdüğü şeyden beni koruyan ve yarattıklarının büyük çoğunluğuna karşı beni üstün kılan Allah'a hamdolsun.\n\nO tehlike ona dokunmaz.","en":"Praise is to Allah Who has spared me what He has afflicted you with, and preferred me greatly above much of what He has created.\n\nThat danger will not touch him."},{"id":427,"title":"Depresyonda Okunacak Dua (Yâ Hayyü Yâ Kayyûm Birahmetike Estağîs)","ref":"Hasen (Elbânî). Tirmizî: 3524","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_427.json","ar":"يَا حَيُّ يَا قَيُّوْمُ، بِرَحْمَتِكَ أَسْتَغِيْثُ","latin":"Yâ hayyü yâ kayyûmü birahmetike estağîs","tr":"Ey Diri olan, ey her şeyi ayakta tutan! Senin rahmetinle yardım diliyorum.\n\nPeygamber (ﷺ) bir şey onu üzdüğünde (yukarıdaki duayı) söylerdi.","en":"O Ever Living, O Self-Subsisting and Supporter of all, by Your mercy I seek assistance.\n\nWhenever a matter would distress him, the Prophet (ﷺ) would say (above dua)"},{"id":429,"title":"Güçlük Anında Okunacak Dua (Meşnu Dua)","ref":"Sahîh (Elbânî). İbn Hibbân: 974","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_429.json","ar":"اَللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا","latin":"Allâhümme lâ sehle illâ mâ cealtehû sehlâ, ve ente tec'alül-hazne izâ şi'te sehlâ","tr":"Allâhım! Senin kolaylaştırdığın şey hariç kolay olan yoktur. Dilediğinde üzüntüyü de kolaylaştırsın.","en":"O Allah, there is no ease other than what You make easy. If You want You ease sorrow."},{"id":430,"title":"Düşmanlardan Korunmak İçin Güçlü Dua","ref":"Sahîh. Ebû Dâvud: 1537","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_430.json","ar":"اَللَّهُمَّ إِنَّا نَجْعَلُكَ فِي نُحُورِهِمْ وَنَعُوذُ بِكَ مِنْ شُرُورِهِمْ","latin":"Allâhümme innâ nec'alüke fî nühûrihim ve neûzü bike min şürûrihim","tr":"Allâhım! Seni onlara karşı kalkan yapıyoruz ve onların kötülüklerinden Sana sığınıyoruz.","en":"O Allah, we ask You to restrain them by their necks and we seek refuge in You from their evil."},{"id":431,"title":"Zalimlere Karşı Korunma Duası","ref":"Sahîh (Elbânî). Sahîhü't-Terğîb: 2237, Edebü'l-Müfred: 707","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_431.json","ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ السَّبْعِ وَرَبَّ الْعَرْشِ الْعَظِيْمِ كُنْ لِي جَارًا مِنْ فُلَانِ بْنِ فُلَانٍ، وَأَحْزَابِهِ مِنْ خَلَائِقِكَ (وَمِنْ شَرِّ خَلْقِكَ كُلِّهِمْ جَمِيْعًا) أَنْ يَفْرُطَ عَلَيَّ أَحَدٌ مِنْهُمْ أَوْ يَطْغَى عَزَّ جَارُكَ وَجَلَّ ثَنَاؤُكَ وَلَا إِلٰهَ إِلَّا أَنْتَ","latin":"Allâhümme Rabbes-semâvâtis-seb'i, ve Rabbel-Arşil-Azîm, kun lî câren min [buraya kişinin adı söylenir], ve ahzâbihî min halâikike, (ve min şerri halkike küllihim cemîan) en yefruta aleyye ehadün minhüm ev yetğâ, azze cârüke, ve celle senâüke, ve lâ ilâhe illâ ente","tr":"Allâhım! Yedi göğün Rabbi, yüce Arş'ın Rabbi! Beni [kişinin adı] ve yaratıkların arasındaki yardımcılarına karşı destekle; onlardan hiçbirinin bana haksızlık etmesine veya azmasına izin verme. Senin korumanın şanı yücedir, senin övgün büyüktür. Senden başka ibadete layık hiçbir ilah yoktur.\n\nAbdullah ibn Mes'ûd'dan (r.a.) ve Abdullah ibn Abbâs'tan (r.a.) rivayet edildi, dediler ki: Kim herhangi bir yöneticinin, idarecinin veya güçlü bir kişinin zararından korkarsa bu duayı okumalıdır.","en":"O Allah, Lord of the seven heavens, Lord of the Magnificent Throne, be for me a support against [such and such a person] and his helpers from among your creatures, lest any of them abuse me or do me wrong. Mighty is Your patronage and glorious are Your praises. There is none worthy of worship but You.\n\nNarrated from Abdullah Ibn Masood (RA) and Abdullah Ibn Abbas (RA), they said: If anyone fears harm from any ruler, administrator or powerful person, he should recite this dua."},{"id":432,"title":"Zararlı İnsanlardan Güvenlik İçin Dua","ref":"Müslim 4/2300, 3005","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_432.json","ar":"اَللَّهُمَّ اكْفِنِيْهِمْ بِمَا شِئْتَ","latin":"Allâhümmekfinîhim bimâ şi'te","tr":"Allâhım! Dilediğin şekilde beni onlara karşı yeterli kıl (yani koru).","en":"O Allah, suffice (i.e. protect) me against them however You wish."},{"id":434,"title":"Beladan Korunma Duası","ref":"Sahîh. Tirmizî: 3431, 3432","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_434.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي عَافَانِيْ مِمَّا ابْتَلَاكَ بِهِ وَفَضَّلَنِيْ عَلَى كَثِيْرٍ مِمَّنْ خَلَقَ تَفْضِيْلًا","latin":"Elhamdülillâhillezî âfânî mimmebtelâke bihî, ve faddalenî alâ kesîrin mimmen halaka tafdîlâ","tr":"Seni içine düşürdüğü şeyden beni koruyan ve yarattıklarının büyük çoğunluğuna karşı beni üstün kılan Allah'a hamdolsun.\n\nÖmer'den (r.a.) rivayet edildi: Allah'ın Resûlü (ﷺ) şöyle buyurdu: 'Kim belaya uğramış birini görüp (yukarıdaki duayı) söylerse, yaşadığı sürece o beladan korunur.' Hüseyin'in (r.a.) torunu Muhammed el-Bâkır dedi ki: Dua, musibete uğrayan kişinin duymayacağı şekilde sessizce söylenmelidir.","en":"Praise be to Allah who had saved me from what He had afflicted you with, and for honouring me over many of his creations.\n\nUmar (RA) narrated that: The Messenger of Allah (ﷺ) said: “Whoever sees a person afflicted and say: (The dua is mentioned above) then he shall be saved from that affliction for as long as he lives.” Grandson of Husain (RA), Muhammad al-Bakir said, dua should be uttered silently without hearing the afflicted person."},{"id":436,"title":"Peygamber'in Savaşta Duası (Yâ Hayyü Yâ Kayyûm)","ref":"Hasen (Heysemî). Taberânî: 4817","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_436.json","ar":"يَا حَيُّ، يَا قَيُّوْمُ","latin":"Yâ Hayyü yâ Kayyûm","tr":"Ey Diri olan, ey Ebedî olan.\n\nAlî (r.a.) şöyle dedi: 'Bedir Savaşı günü bir süre savaştıktan sonra Allah'ın Resûlü'nün (ﷺ) ne yaptığını görmek için yanına koştum. Onu secde hâlinde yalnızca şu kelimeleri söylerken gördüm: 'Yâ Hayyü Yâ Kayyûm (Ey Diri olan, ey Ebedî olan)' ve bunun üzerine hiçbir şey ilave etmiyordu. Sonra tekrar savaşa gittim. Bir süre sonra tekrar yanına döndüm. Yine onu secde hâlinde yalnızca aynı kelimeleri söylerken gördüm. Sonra tekrar savaşa gittim. Bir süre sonra tekrar yanına döndüm; yine onu secde hâlinde yalnızca aynı kelimeleri söylerken gördüm. Ardından Allah ona (ﷺ) zafer ihsan etti. Bu hadiste zikir ile nasıl dua edileceğini görebiliriz. Bu tür dua en güzel sonucu getirir.'","en":"O Ever Living One, O Eternal One.\n\nAli (RA) said: ”In the day of Badr war, after fighting for some while I was rushing to come to the Messenger of Allah (ﷺ) to see what he was doing. I saw him in a state of prostration and only saying these words : ya ‘hayyu ya qayyum (O Ever Living One, O Eternal One) and didn’t increase over that. Then again I went to the war. After some time I returned to him. Again I saw him in a state of prostration and only saying those same words.Then again I went to the war. After some time I returned to him and saw him in a state of prostration and only saying those same words. Then Allah granted him (ﷺ) victory. We can see in this hadith how to make dua by dhikr. This type of dua brings best result."},{"id":438,"title":"Stres ve Aşırı Düşünce İçin Dua","ref":"Sahîh. İbn Mâce: 3882","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_438.json","ar":"اَللَّهُ رَبِّي لَا أُشْرِكُ بِهِ شَيْئًا","latin":"Allâhü Rabbî lâ üşrikü bihî şey'â","tr":"Allah benim Rabbimdir. O'na hiçbir şeyi ortak koşmam.\n\nÂişe (r.anhâ) şöyle dedi: 'Allah'ın Resûlü (ﷺ) ailesini bir araya toplar ve şöyle derdi: İçinizden biri sıkıntıya veya tehlikeye düşerse bunu söylesin.'","en":"Allah is my Lord. I do not associate anything with Him.\n\nAyesha (RA) said, \"The Messenger of Allah (ﷺ), used to gather all his family together and say: If any of you are ever in trouble or in danger, say this.\""},{"id":439,"title":"Kaygıyı Yenme Duası (Meşnu Dua)","ref":"Hasen Garîb. Ebû Dâvud: 2632","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_439.json","ar":"اَللَّهُمَّ أَنْتَ عَضُدِي، وَأَنْتَ نَصِيرِي، بِكَ أَحُولُ وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ","latin":"Allâhümme ente adudî ve ente nasîrî, bike ehûlü ve bike esûlü ve bike ukâtilü","tr":"Allâhım! Sen benim gücümsün ve Sen benim yardımcımsın. Senin için harekete geçiyor, Senin için ilerliyorum ve Senin için savaşıyorum.","en":"O Allah, You are my strength and You are my support. For Your sake I go forth and for Your sake I advance and for Your sake I fight."},{"id":440,"title":"Peygamber'in Tehlikede Duası (HasbünAllâh)","ref":"Buhârî: 4563","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_440.json","ar":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ","latin":"HasbünAllâhü ve ni'mel-vekîl","tr":"Allah bana yeterlidir ve O ne güzel vekildir.\n\nBu dua, İbrâhîm (a.s.) tarafından ateşe atıldığında okundu. Hz. Muhammed (ﷺ) de insanlar ona 'İnsanlar size karşı birleşti!' dediklerinde bu duayı okudu.","en":"Allah is sufficient for me, and how fine a trustee (He is).\n\nThis dua was recited by Ibrahim (As) when he was thrown into the fire. And Muhammad (ﷺ) recited this prayer when the people said to him, \"The people are united against you!\""},{"id":441,"title":"Zalimlere Karşı Korunma Duası","ref":"Sahîh. Edebü'l-Müfred: 708","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_441.json","ar":"اَللَّهُ أَكْبَرُ، اَللَّهُ أَعَزُّ مِنْ خَلْقِهِ جَمِيعًا، اَللَّهُ أَعَزُّ مِمَّا أَخَافُ وَأَحْذَرُ، أَعُوْذُ بِاللَّهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ الْمُمْسِكِ السَّمَوَاتِ السَّبْعِ أَنْ يَقَعْنَ عَلَى الْأَرْضِ إِلَّا بِإِذْنِهِ، مِنْ شَرِّ عَبْدِكَ فُلَانٍ، وَجُنُودِهِ وَأَتْبَاعِهِ وَأَشْيَاعِهِ، مِنَ الْجِنِّ وَالْإِنْسِ، اَللَّهُمَّ كُنْ لِي جَارًا مِنْ شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلَا إِلَهَ غَيْرُكَ","latin":"Allâhü Ekber, Allâhü eazzü min halkihî cemîan, Allâhü eazzü mimmâ ehâfü ve ahzeru, eûzü billâhillezî lâ ilâhe illâ hüvel-mümsikis-semâvâtis-seb'i en yekaane alel-ardı illâ biiznihî, min şerri abdike (kişinin adı söylenir), ve cünûdihî ve etbâihî ve eşyâihî, minel-cinni vel-ins. Allâhümme kun lî câren min şerrihim, celle senâüke ve azze cârüke, ve tebârekesmüke, ve lâ ilâhe ğayrük","tr":"Allâh en büyüktür, tüm yaratıklarından daha güçlüdür. Allah korktuğum ve çekindiğim her şeyden daha güçlüdür. Hiçbir ilah olmayan; emriyle yedi göğü yere düşmekten alıkoyan Allah'a sığınırım. Kulunun (kişinin adı söylenir) ve onun yardımcılarının, takipçilerinin ve destekçilerinin cinler ve insanlar arasındaki kötülüğünden (Sana sığınırım). Allâhım! Onların kötülüğüne karşı benim dayanağım ol. Senin övgün yüce, Senin korumanın şanı yüce. Senin ismin mübarektir. Senden başka gerçek bir ilah yoktur.\n\nİbn Abbâs'tan (r.a.) rivayet edildi: 'Size korku veren ve size saldıracağından korktuğunuz etkili bir kişiyle karşılaştığınızda üç kez şunu söyleyin: (Yukarıdaki dua.)'","en":"Allah is the Most Great, Mightier than all His creation. He is Mightier than what I fear and dread. I seek refuge in Allah, Who there is none worthy of worship but Him. He is the One Who holds the Seven heavens from falling upon the earth except by His command. (I seek refuge in You Allah) from the evil of Your slave (say the person's name), and his helpers, his followers and his supporters from among the jinn and mankind. O Allah, be my support against their evil. Glorious are Your praises and mighty is Your patronage. Blessed is Your Name, there is no true God but You.\n\nNarrated Ibn 'Abbas (RA) : When you meet an influential person who is causing terror and you fear that he will attack you, you will say three times: (The dua is mentioned above)"},{"id":442,"title":"Düşmanlara Karşı Zafer Duası","ref":"Buhârî: 2818, 2833, 2933","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_442.json","ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اِهْزِمِ الْأَحْزَابَ، اَللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ","latin":"Allâhümme münzelel-kitâbi, serîal-hisâbi, ihzimil-ahzâb. Allâhümmahzimhüm ve zelzilhüm","tr":"Allâhım! Kitabı indiren, hesabı çabuk gören! Toplulukları (kâfirlerin gruplarını) boz. Allâhım! Onları boz ve sars.","en":"Allah, Revealer of the Book, Swift to account, defeat the groups (of disbelievers). O Allah, defeat them and shake them."},{"id":443,"title":"Sağlık ve Korunma Duası","ref":"Sahîh. Buhârî, Edebü'l-Müfred 1/226","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_443.json","ar":"اَللَّهُمَّ مَتِّعْنِي بِسَمْعِي وَبَصَرِي وَاجْعَلْهُمَا الْوَارِثَ مِنِّي، وَانْصُرْنِي عَلَى مَنْ ظَلَمَنِي وَخُذْ مِنْهُ بِثَأْرِي","latin":"Allâhümme mettini bisem'î ve basarî vec'alhümâl-vârise minnee, vensurnî alâ men zalemeni ve huz minhü bisâ'rî","tr":"Allâhım! Kulağımdan ve gözümden yararlandır; onları öldüğüm güne kadar sağlıklı ve güçlü tut. Bana zulmedenlere karşı bana yardım et ve benden intikam al.","en":"O Allah, grant me enjoyment of my hearing and sight, and keep them healthy and sound until the day I die, and aid me against those who oppress me, and avenge me from them."},{"id":444,"title":"Zalimlere Karşı Korunma İçin Kur'ânî Dua","ref":"A'râf Sûresi 7:47","url":"https://quran.com/7/47","ar":"رَبَّنَا لَا تَجْعَلْنَا مَعَ الْقَوْمِ الظَّالِمِينَ","latin":"Rabbenâ lâ tec'alnâ meal-kavmiz-zâlimîn.","tr":"Rabbimiz! Bizi zalimler topluluğuyla birlikte eyleme.","en":"Our Lord, do not place us with the wrongdoing people."},{"id":445,"title":"Borç Kurtulma İçin İslami Dua","ref":"Hasen Garîb. Tirmizî: 3563","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_445.json","ar":"اَللَّهُمَّ اكْفِنِي بِحَلَالِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكَ عَمَّنْ سِوَاكَ","latin":"Allâhümmekfinî bihâlâlike an harâmike, ve ağninî bifadlike ammen sivâk","tr":"Allâhım! Haramın yerine helal olanla beni yetindir ve lütfunla beni Senden başkasına muhtaç olmaktan koru.","en":"O Allah, make what is lawful enough for me, as opposed to what is unlawful, and spare me by Your grace of the need for others."},{"id":447,"title":"Peygamber'in Kötü Göze ve Zarara Karşı Duası","ref":"Buhârî: 3371","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_447.json","ar":"أُعِيْذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَّهَامَّةٍ وَّمِنْ كُلِّ عَيْنٍ لَامَّةٍ","latin":"Üîzüküma bikelimâtillâhit-tâmmeti min külli şeytânin ve hâmmeh, ve min külli aynin lâmmeh","tr":"Sizi her şeytandan, her zehirli hayvandan ve her kötü, zararlı, kıskanç gözden Allah'ın eksiksiz kelimelerine sığındırırım.","en":"I seek protection for you in the Perfect Words of Allah from every devil and every beast, and from every envious blameworthy eye."},{"id":448,"title":"Zor Anlarda Meşnu Dua","ref":"Sahîh. Tirmizî: 3505","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_448.json","ar":"لَا إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّى كُنْتُ مِنَ الظَّالِمِيْنَ","latin":"Lâ ilâhe illâ ente sübhâneke innî küntü minez-zâlimîn","tr":"Senden başka ibadete layık hiçbir ilah yoktur (ey Allah). Sen her türlü noksanlıktan münezzehsin. Şüphesiz ben zalimlerden oldum.","en":"None has the right to be worshipped but You (O Allah), Glorified (and Exalted) are You. Truly, I have been of the wrong-doers."},{"id":449,"title":"Sıkıntı İçin Dua (Meşnu Dua)","ref":"Buhârî: 3346","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_449.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ","latin":"Lâ ilâhe illallâh","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur.\n\n'Yaklaşan bir tehlikeden dolayı Araplara yazıklar olsun. Ye'cüc ve Me'cüc'ün duvarından başparmağı ile işaret parmağıyla bir halka yaparak şu kadar açıldı.' Zeyneb binti Cahş (r.anhâ) dedi ki: 'Ya Resûlallah! İçimizde salih kişiler olduğu hâlde helak mı olacağız?' Şöyle buyurdu: 'Evet, kötülük çoğaldığında.'","en":"None has the right to be worshipped but Allah.\n\nWoe unto the Arabs from a danger that has come near. An opening has been made in the wall of Gog and Magog like this,\" making a circle with his thumb and index finger. Zainab bint Jahsh (RA) said, \"O Allah's Messenger (ﷺ)! Shall we be destroyed even though there are pious persons among us?\" He said, \"Yes, when the evil person will increase.\""},{"id":450,"title":"Peygamber'in Birine Hakaret Ettikten Sonra Duası (Meşnu Dua)","ref":"Buhârî: 6361","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_450.json","ar":"اَللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ","latin":"Allâhümme feeyyyümâ mü'minin sebbebtühû fec'al zâlike lehû kurbeten ileyke yevmel-kıyâmeh","tr":"Allâhım! Müminlerden birine hakaret etmişsem, bunu kıyamet gününde onun Sana yakınlık vesilesi kıl.","en":"O Allah, whomever of the believers I have abused, make it a means of gaining nearness to you on the Day of Resurrection."},{"id":451,"title":"Müslüman Kardeşi Övmenin Adabı","ref":"Buhârî: 2662","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_451.json","ar":"أَحْسِبُ فُلَانًا وَاللَّهُ حَسِيبُهُ وَلَا أُزَكِّي عَلَى اللَّهِ أَحَدًا أَحْسِبُهُ كَذَا وَكَذَا","latin":"Ahsibü fülânen vAllâhü hasîbüh, ve lâ üzekkî alAllâhi ehaden ahsibühû kezâ ve kezâ","tr":"Şahsen onun hakkında böyle düşünüyorum; gerçeği tam olarak Allah bilir. Allah'ın huzurunda hiçbir kimsenin iyiliğini onaylamam; ama onun şöyle şöyle biri olduğunu zannediyorum.\n\nBu, söz konusu kişide belirli bir niteliğin bulunduğuna dair bilgiye sahip olduğunuzdan emin olmanız gerektiğinde söylenmelidir.","en":"I think that he is so and so, and Allah knows exactly the truth, and I do not confirm anybody's good conduct before Allah, but I think him so and so.\n\nIt is to be said when you must ensure you have knowledge that the certain characteristic is present in that person."},{"id":452,"title":"Allah'ı Övme Duası","ref":"Sahîh. Edebü'l-Müfred: 589","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_452.json","ar":"اَللَّهُمَّ لَا تُؤَاخِذْنِي بِمَا يَقُولُونَ، وَاغْفِرْ لِي مَا لَا يَعْلَمُونَ، وَاجْعَلْنِي خَيْرًا مِمَّا يَظُّنُّونَ","latin":"Allâhümme lâ tüâhidnî bimâ yekûlûn, vagfirlî mâ lâ ya'lemûn vec'alnî hayran mimmâ yezunnûn","tr":"Allâhım! Söyledikleri için beni hesaba çekme; bilmedikleri şeyler için beni bağışla ve beni onların zannettiğinden daha iyi kıl.","en":"O Allah, do not call me to account for what they say and forgive me for what they have no knowledge of and make me better than they imagine."},{"id":453,"title":"Allah'tan Bağışlanma İsteme Duası","ref":"[1] Riyâzüssâlihîn: 1843 [2] Müslim: 2346","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_453.json","ar":"غَفَرَ اللَّهُ لَكَ","latin":"Gaferallâhü lek","tr":"Allah seni bağışlasın.\n\nBuna karşılık Allah'ın Resûlü (ﷺ) şöyle dedi:","en":"May Allah forgive you.\n\nIn response, The Messenger of Allah (ﷺ) said:"},{"id":454,"title":"Cezâkallâhü Hayran Demenin Gücü","ref":"Sahîh. Tirmizî: 2035","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_454.json","ar":"جَزَاكَ اللَّهُ خَيْرًا","latin":"CezâkAllâhü hayran","tr":"Allah seni hayırla mükâfatlandırsın.\n\nElinden gelen en fazla övgüyü yapmış olur.","en":"May Allah reward you with good.\n\nThen he has done the most that he can of praise."},{"id":457,"title":"Allah için Sevginin Duası","ref":"Hasen (Elbânî). Ebû Dâvud: 5125","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_457.json","ar":"أُحِبُّكَ فِي اللَّهِ","latin":"Ühibbüke fillâh","tr":"Seni Allah için seviyorum.\n\nO da şöyle karşılık verir:","en":"I love you for the sake of Allah.\n\nHe will respond by saying:"},{"id":458,"title":"Mal ve Aile İçin Dua (Meşnu Dua)","ref":"Buhârî: 3780, 5167","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_458.json","ar":"بَارَكَ اللَّهُ لَكَ فِي أَهْلِكَ وَمَالِكَ","latin":"Bârekallâhü leke fî ehlike ve mâlike","tr":"Allah ailenizde ve malınızda size bereket versin.\n\nAbdurrahman (r.a.) sonra şöyle dedi: 'Pazarın nerede?' Ona Kaynukâ pazarını gösterdiler. (Oraya gitti ve) kuru yoğurt ve tereyağı kârıyla döndü. Pazara gitmeye devam etti; ta ki bir gün üzerinde sarı koku izleriyle geldi. Peygamber (ﷺ) 'Bu (koku) nedir?' diye sordu. O da 'Evlendim' diye cevap verdi. Peygamber (ﷺ) 'Mehrini ne kadar verdin?' diye sordu. O da 'Bir hurma çekirdeği ağırlığında altın verdim' diye cevap verdi. Peygamber (ﷺ) şöyle buyurdu: 'Bir koyunla da olsa düğün ziyafeti ver.'","en":"May Allah bless you in your family and your property.\n\n`Abdur-Rahman (RA) then said, \"Where is your market?\" So they showed him the Qainuqa' market. (He went there and) returned with a profit in the form of dried yogurt and butter. He continued going (to the market) till one day he came, bearing the traces of yellow scent. The Prophet (ﷺ) asked, \"What is this (scent)?\" He replied, \"I got married.\" The Prophet (ﷺ) asked, \"How much Mahr did you give her?\" He replied, \"I gave her a datestone of gold or a gold piece equal to the weight of a date-stone.\" The Prophet (ﷺ) said, \"Arrange a marriage banquet even with a sheep."},{"id":460,"title":"Biri Bârekallâhü Fîküm Dediğinde Okunacak Dua","ref":"İbn Sünnî (Sayfa 138, Hadis No. 278). Ayrıca bkz. İbnü'l-Kayyım'ın el-Vâbilü's-Sayyib adlı eseri Sayfa 304. Tahkik: Beşîr Muhammed Uyûn","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_460.json","ar":"بَارَكَ اللَّهُ فِيكُمْ","latin":"Bârekallâhü fîküm","tr":"Allah hepinize bereket versin.\n\nÂişe (r.anhâ) sonra şöyle dedi:","en":"May Allah bless you all.\n\nAaishah (RA) then said:"},{"id":461,"title":"İyi Şans ve Tevekkül Duası","ref":"Sahîh (Elbânî). Silsile-i Sahîha: 1065, Müsned Ahmed: 7045","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_461.json","ar":"اَللَّهُمَّ لَا طَيْرَ إِلَّا طَيْرُكَ وَلَا خَيْرَ إِلَّا خَيْرُكَ وَلَا إِلَهَ غَيْرُكَ","latin":"Allâhümme lâ tayre illâ tayrüke, ve lâ hayre illâ hayrüke, ve lâ ilâhe ğayrük","tr":"Allâhım! Senin (gösterdiğin) işaretten başka işaret yoktur; Senin hayırından başka hayır yoktur ve Senden başka ibadete layık hiçbir ilah yoktur.","en":"O Allah there is no portent other than Your portent, no goodness other than Your goodness, and none worthy of worship other than You."},{"id":469,"title":"Aksırma Duası (Her Hal İçin Elhamdülillâh)","ref":"Sahîh. Tirmizî: 2741","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_469.json","ar":"اَلْحَمْدُ لِلَّهِ (عَلَى كُلِّ حَالٍ)","latin":"Elhamdülillâhi ('alâ külli hâl)","tr":"Her hâlükârda hamd Allah'a mahsustur.","en":"Praise is to Allah in all circumstances."},{"id":470,"title":"Aksırana Karşılık Verme Duası (Yerhamükallâh)","ref":"Buhârî: 1240, 6224","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_470.json","ar":"يَرْحَمُكَ اللَّهُ","latin":"Yerhamükallâh","tr":"Allah sana merhamet etsin.","en":"May Allah have mercy upon you."},{"id":471,"title":"Aksırma Karşılığına Cevap Duası (Yahdîküümullâh)","ref":"Sahîh. Tirmizî: 2741","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_471.json","ar":"يَهْدِيْكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ","latin":"Yahdîküümullâhü ve yuslihu bâlekum","tr":"Allah sizi hidayete erdirsin ve işlerinizi düzeltsin.\n\nHadislerde, aksırma duasına selam almak gibi karşılık verilmesi konusunda özel talimatlar verilmiştir. Bu sünnetler toplumumuzda maalesef ihmal edilmektedir.","en":"May Allah guide you and set your affairs in order.\n\nSpecial instructions have been given in the hadith to answer the sneeze dua like answering the salutation. These Sunnahs are neglected in our society."},{"id":472,"title":"Aksırma Meşnu Duası (Yerhamüna ve İyyâküm)","ref":"Edebü'l-Müfred: 941","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_472.json","ar":"يَرْحَمُنَا اللَّهُ وَإِيَّاكُمْ، وَيَغْفِرُ لَنَا وَلَكُمْ","latin":"Yerhamenallâhü ve iyyâküm ve yağfiru lenâ ve lekum","tr":"Allah bize ve size merhamet etsin, bizi ve sizi bağışlasın.","en":"May Allah shower his mercy upon you and us and forgive you and us."},{"id":474,"title":"Bağışlanma İçin Güçlü İstiğfar Duası","ref":"Sahîh. Tirmizî: 3434","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_474.json","ar":"رَبِّ اغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الْغَفُورُ","latin":"Rabbığfir lî ve tüb 'aleyye inneke ente't-Tevvâbül-Ğafûr","tr":"Rabbim! Beni bağışla ve tövbemi kabul et; şüphesiz Sen Tevvâb'sın (tövbeleri kabul edersin), Ğafûr'sun (çok bağışlayansın).\n\nİbn Ömer (r.a.) şöyle dedi: Allah'ın Resûlü'nün (ﷺ) herhangi bir oturumda kalkmadan önce yüz kez şunu söylediği sayılırdı: (yukarıdaki dua).","en":"My Lord, forgive me and accept my repentance, You are the Ever-Relenting, the All-Forgiving.\n\nIbn 'Umar (RA) said: It would be counted that at any one sitting, the Messenger of Allah (ﷺ) before getting up would say one hundred times:(The dua is mentioned above)"},{"id":476,"title":"Her Durumda Elhamdülillâh Demek","ref":"Hasen. İbn Mâce: 3803","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_476.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ","latin":"Elhamdülillâhillezî bini'metihî tetimmüs-sâlihât","tr":"Nimetleriyle tüm iyiliklerin tamamlandığı Allah'a hamd olsun.","en":"Praise is to Allah Who by His blessings all good things are perfected."},{"id":477,"title":"Her Durumda Okunacak Dua (Elhamdülillâh Alâ Külli Hâl)","ref":"Hasen. İbn Mâce: 3803","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_477.json","ar":"اَلْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ","latin":"Elhamdülillâhi alâ külli hâl","tr":"Her hâlükârda Allah'a hamd olsun.","en":"Praise is to Allah in all circumstances."},{"id":479,"title":"Övüldüğünde Okunacak Dua (Meşnu Dua)","ref":"Sahîh. Edebü'l-Müfred: 761, Parantez içi kısım (Şuabü'l-İman 4/288)","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_479.json","ar":"اَللَّهُمَّ لَا تُؤَاخِذْنِيْ بِمَا يَقُوْلُوْنَ وَاغْفِرْ لِي مَا لَا يَعْلَمُوْنَ (وَاجْعَلْنِيْ خَيْرًا مِمَّا يَظُنُّوْنَ)","latin":"Allâhümme lâ tüâhidnî bimâ yekûlûn, vağfir lî mâ lâ ya'lemûn [vec'alnî hayran mimmâ yezünnûn]","tr":"Allâhım! Onların söyledikleri için beni sorumlu tutma ve onların bilmedikleri şeyleri bana bağışla [ve beni onların zannettiğinden daha iyi kıl].\n\nSahâbîlerin âdeti şuydu: Biri onlara sâlih veya iyi dese rahatsızlık duyarlardı. Biri onları övdüğünde şöyle dua ederlerdi: (yukarıdaki dua).","en":"Oh Allah, do not call me to account for what they say and forgive me for what they have no knowledge of [and make me better than they imagine].\n\nIt was the custom of the Companions that they would feel discomfort if anyone called them righteous or praised them. If someone praise them, they would say- (The dua is mentioned above)"},{"id":481,"title":"Gayrimüslimlerin Selamına Karşılık Vermek","ref":"Buhârî: 6258","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_481.json","ar":"وَعَلَيْكُمْ","latin":"Ve aleyküm","tr":"Ve sizin üzerinize de.","en":"And upon you"},{"id":484,"title":"Lâ İlâhe İllAllâh'ın Güçlü Zikri","ref":"Sahîh. Tirmizî: 3430","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_484.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَا إِلَهَ إِلَّا اللَّهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، لَا إِلَهَ إِلَّا اللَّهُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Lâ ilâhe illAllâhü vAllâhü Ekber, lâ ilâhe illAllâhü vahdeh, lâ ilâhe illAllâhü vahdehû lâ şerîke leh, lâ ilâhe illAllâhü lehül-mülkü ve lehül-hamdü, lâ ilâhe illAllâhü ve lâ havle ve lâ kuvvete illâ billâh","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; Allah en büyüktür. Allah'tan başka ibadete layık hiçbir ilah yoktur, O tektir. Allah'tan başka ibadete layık hiçbir ilah yoktur, O tektir, ortağı yoktur. Allah'tan başka ibadete layık hiçbir ilah yoktur; mülk O'nundur, hamd O'nundur. Allah'tan başka ibadete layık hiçbir ilah yoktur; güç ve kuvvet yalnızca Allah'a aittir.\n\nEbû Saîd el-Hudrî (r.a.) ve Ebû Hüreyre (r.a.) şöyle dedi: Allah'ın Resûlü (ﷺ) buyurdu: Bir kul bu sözleri söylediğinde Allah ona karşılık verir. Kim hasta hâlindeyken bu sözleri söyler ve bu hâlde ölürse ateş ona dokunmaz.","en":"There is none worthy of worship but Allah, Allah is the Most Great. None has the right to be worshipped but Allah alone. None has the right to be worshipped but Allah alone, Who has no partner. There is none worthy of worship but Allah, His is the dominion and His is the praise. There is none worthy of worship but Allah, there is no power and no might but by Allah.\n\nAbu Saeed Khudri (RA) and Abu Hurairah (RA) said that the Messenger of Allah (ﷺ) said that when a servant says these words, Allah responds to him and if someone says these words while he is ill and then dies, the fire will not touch him."},{"id":488,"title":"Allah için Sevgi Duası (Meşnu Dua)","ref":"Hasen. Ebû Dâvud: 5125","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_488.json","ar":"أَحَبَّكَ الَّذِي أَحْبَبْتَنِي لَهُ","latin":"Ahabbakellezî ahbebtenî leh","tr":"Seni benim için seven Allah, seni de sevsin.","en":"May He for Whose sake you love me, love you."},{"id":491,"title":"Kur'ân Tilavetinde Secde Duası","ref":"Hasen. Tirmizî: 3424","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_491.json","ar":"اَللَّهُمَّ اكْتُبْ لِي بِهَا عِنْدَكَ أَجْرًا وَضَعْ عَنِّيْ بِهَا وِزْرًا وَاجعَلْهَا لِي عِنْدَكَ ذُخْرًا وَتَقَبَّلْهَا مِنِّي كَمَا تَقَبَّلْتَهَا مِنْ عَبْدِكَ دَاوُدَ","latin":"Allâhümmektüb lî bihâ indeke ecran, vad'a annî bihâ vizran, vec'alhâ lî indeke zühra, ve tekabbelhâ minnee kemâ tekabbeltehâ min abdike Dâvûd","tr":"Allâhım! Bunu katında benim için bir sevap olarak yaz, benden bir günahı bu sayede sil, bunu katında benim için bir hazine kıl ve onu kulun Dâvûd'dan kabul ettiğin gibi benden de kabul et.\n\nİbn Abbâs (r.a.) şöyle dedi: 'Allah'ın Resûlü (ﷺ) secde âyetlerini okudu ve bu duayı yaptı.' (Yukarıdaki dua).","en":"O Allah, write it as a reward for me, and release me from a burden for it, and make it a treasure for me in Paradise. Accept it from me as You accepted it from your servant Dawud.\n\nIbn 'Abbas (RA) said, \"The Messenger of Allah (ﷺ), recited the verses of prostration and recited this du'a.\" (The dua is mentioned above)"},{"id":495,"title":"Toplantı Kefareti Duası (Keffaratü'l-Meclis)","ref":"Sahîh. Tirmizî: 3433","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_495.json","ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ أَسْتَغْفِرُكَ وَأَتُوْبُ إِلَيْكَ","latin":"Sübhânekellâhümme ve bihamdike, eşhedü en lâ ilâhe illâ ente, estağfiruke ve etûbü ileyke","tr":"Allah'ım! Seni her türlü eksiklikten tenzih eder ve Sana hamd ederim. Senden başka ibadete layık hiçbir ilah olmadığına şehadet ederim. Senden bağışlanma diler ve Sana tövbe ederim.\n\nAbdullah ibn Amr ibn el-Âs (r.a.), Ebû Berze el-Eslemî (r.a.) ve Ebû Hüreyre (r.a.) gibi sahâbîlerden farklı sahîh isnâtlarla rivayet edildi: Peygamber (ﷺ) toplantıdan ayrılmadan önce bu sözleri söylerdi. Şöyle buyurdu: 'Kim kalkarken bu sözleri söylerse meclis için kefaret olur. Allah ﷻ bu sayede o mecliste geçen câiz olmayan sözleri ve günahları bağışlar.'","en":"Glory is to You, O Allah, and praise is to You. I bear witness that there is none worthy of worship but You. I seek Your forgiveness and repent to You.\n\nIt is narrated in different authentic chains by the Companions like Abdullah Ibn Amr Ibn Al-As (RA), Abu Barzah Aslami (RA), Abu Hurairah (RA) that the Prophet (ﷺ) used to say these words before leaving the meeting at the end of the meeting. He said, \"If anyone says these words while getting up from a meeting, it will be an expiation for the meeting. Because of this, Allah Almighty will forgive the unlawful speech and sins of that meeting."},{"id":496,"title":"Meclisi Bitirirken Okunacak Dua","ref":"Hasen. Tirmizî: 3502","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_496.json","ar":"اَللَّهُمَّ اقْسِمْ لَنَا مِنْ خَشْيَتِكَ مَا يَحُولُ بَيْنَنَا وَبَيْنَ مَعَاصِيْكَ وَمِنْ طَاعَتِكَ مَا تُبَلِّغُنَا بِهِ جَنَّتَكَ وَمِنَ الْيَقِيْنِ مَا تُهَوِّنُ بِهِ عَلَيْنَا مُصِيْبَاتِ الدُّنْيَا وَمَتِّعْنَا بِأَسْمَاعِنَا وَأَبْصَارِنَا وَقُوَّتِنَا مَا أَحْيَيْتَنَا وَاجْعَلْهُ الْوَارِثَ مِنَّا وَاجْعَلْ ثَأْرَنَا عَلَى مَنْ ظَلَمَنَا وَانْصُرْنَا عَلَى مَنْ عَادَانَا وَلَا تَجْعَلْ مُصِيْبَتَنَا فِي دِيْنِنَا وَلَا تَجْعَلِ الدُّنْيَا أَكْبَرَ هَمِّنَا وَلَا مَبْلَغَ عِلْمِنَا وَلَا تُسَلِّطْ عَلَيْنَا مَنْ لَا يَرْحَمُنَا","latin":"Allâhümmaksim lenâ min haşyetike mâ yehûlü beynenâ ve beyne ma'âsîke, ve min tâatike mâ tübellığunâ bihî cenneteke, ve minel-yakîni mâ tühevvinü bihî aleynâ musîbeted-dünyâ, ve metti'nâ bi-esmâ'inâ ve absârinâ ve kuvvetinâ mâ ahyeytenâ, vec'alhül-vârisi minnâ, vec'al se'renâ alâ men zalemena, vensurnâ alâ men âdânâ, ve lâ tec'al musîbetenâ fî dîninâ, ve lâ tec'alid-dünyâ ekbere hâmminâ ve lâ mebleğa ilminâ, ve lâ tüsallit aleynâ men lâ yerhamenâ","tr":"Allâhım! Bize, bizimle günahlar arasına giren böyle bir korku nasip et; cennetine ulaştıracak böyle bir itaat ver; dünyanın musibetlerini bize kolaylaştıracak böyle bir yakîn ihsan et. Allâhım! Bizi sağ bıraktığın müddetçe kulaklarımızdan, gözlerimizden ve gücümüzden yararlandır; bunları bizden sonraki nesle miras bırak. Zulmedenlere karşı öcümüzü al, bize düşman olanlara karşı bize yardım et. Musibetimizi dinimizde kılma, dünyayı en büyük kaygımız ve bilgimizin son sınırı yapma; bize merhamet etmeyenleri üzerimize musallat etme.\n\nAbdullah ibn Ömer (r.a.) şöyle dedi: Peygamber (ﷺ) meclisten çok nadir kalkar, kalkmadan önce ashabına bu duayı yapmadan gitmezdi. Bu hadis Hasen'dir. [Tirmizî (49. Kitabü'd-Da'avât, 80. Bâb) 5/492-493] Başka bir rivayette tâbiî Nâfi şöyle dedi: Abdullah ibn Ömer (r.a.) bir mecliste oturan insanlar için bu sözleri söylemeden o meclisten kalkmıyordu. [Nesâî, Es-Sünenü'l-Kübrâ 6/106; İbn el-Esîr, Câmiu'l-Usûl 4/279] Şunu belirtmek gerekir ki bu duada ne Peygamber (ﷺ) ne de ashâbı ellerini kaldırmıştır. Sahâbenin Peygamber'in sünnetini aktarmada son derece dikkatli olduğu görülmektedir. Ellerin kaldırılmasının caiz olup olmadığını da belirttiklerinden, bu konuda sünnetin el kaldırmamak olduğu anlaşılmaktadır.","en":"O Allah, give us such fear that will serve as a barrier between us and acts of disobedience; and give us such obedience that will take us to Your Paradise; and such certainty as will make easy for us to bear in the calamities of this world. O Allah! let us enjoy our hearing, our sight and our strength as long as You keep us alive and keep our senses healthy and sound until the day We die, and make our revenge restricted to those who oppressed us, and support us against those who are hostile to us, and give us not trial in our religion; and let not worldly affairs be our principal concern, or the ultimate limit of our knowledge, and let not those dominate us who do not show mercy to us.\n\nAbdullah bin Umar (RA) said, The Prophet (ﷺ) used to say this dua before leaving the Majlis and seldom left the Majlis without praying for his companions. This hadith is Hasan. [Tirmidhi (49-Kitabud Dawaat, 80-Baab) 5/ 492-493] In another narration, Tabi'i Nafi said, “Abdullah ibn Umar (RA) would not have stood from a meeting without saying these words for the people sitting in the meeting. [Nasai, As-Sunanul Kubra 6/106; Ibn al-Athir, Jamiul Usul 4/279] It is to be noted that the Prophet (ﷺ), the Companions of his Majlis, Abdullah Ibn Umar (RA) or the people of his Majlis did not raise their hands in supplication. We have seen that the Companions were very interested and diligent in narrating the Sunnah of the Prophet (ﷺ). They have described if raising hands during supplication is permissible in this particular case. That is why it is proved that the sunnah is not to be raised. Besides, we have seen that raising the hand during dua is a manners of dua. The Prophet (ﷺ) sometimes supplicated alone and sometimes with the Companions. In the light of this hadith, it is understood that at the end of the meeting, the speaker will say the words of the supplication and the people present will say Amin. If everyone sometimes raises their hands and supplicates, there is no chance of it being considered illegal or bidat. However, depending on the hadith of general virtue, it is bid'ah to consider it necessary to raise one's hand in the case of such duas or to consider it unlawful not to raise one's hand. Since the matter is open, in the light of hadith, the matter must be kept open."},{"id":499,"title":"Yemek Öncesi Dua (Bismillâhi Evvelehû ve Âhirehû)","ref":"Sahîh. Ebû Dâvud: 3767","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_499.json","ar":"بِسْمِ اللَّهِ أَوَّلَهُ وَآخِرَهُ","latin":"Bismillâhi evvelehû ve âhirehû","tr":"Başında da sonunda da Allah'ın adıyla.","en":"In the name of Allah, in the beginning and in the end."},{"id":500,"title":"Yemek Öncesi Dua (Bismillâhi fî Evvelîhi ve Âhirîhi)","ref":"Sahîh. Tirmizî: 1858","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_500.json","ar":"بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ","latin":"Bismillâhi fî evvelîhi ve âhirîhi","tr":"Başında da sonunda da Allah'ın adıyla.","en":"In the name of Allah, in the beginning and in the end."},{"id":503,"title":"Yemek Sonrası Dua","ref":"Hasen. İbn Mâce: 3285","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_503.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِيْ هَذَا وَرَزَقَنِيْهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ","latin":"Elhamdülillâhillezî et'amenî hâzâ ve rezakanîhi min ğayri havlin minnî ve lâ kuvveh","tr":"Bana bu yiyeceği yediren ve onu bana herhangi bir güç ve kuvvetim olmaksızın rızık olarak veren Allah'a hamd olsun.\n\nPeygamber (ﷺ) şöyle buyurdu: 'Bir kimse yemek yiyip bu sözleri söylerse geçmiş günahları bağışlanır.'","en":"Praise is to Allah Who has given me this food and sustained me with it though I was unable to doit and powerless.\n\nThe Prophet (ﷺ) said, \"If a person eats food and says these words, his previous sins will be forgiven.\""},{"id":504,"title":"Süt İçtikten Sonra Okunacak Dua","ref":"Hasen. İbn Mâce: 3322","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_504.json","ar":"اَللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ","latin":"Allâhümme bârik lenâ fîhi ve zidnâ minh","tr":"Allâhım! Bunu bize bereketli kıl ve bize bundan daha fazlasını ver.","en":"O Allah, bless us in it and give us more of it."},{"id":505,"title":"Yemek Sonrası Dua (Sofrayı Kaldırırken)","ref":"Buhârî: 5458, Sahîh. Tirmizî: 3456","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_505.json","ar":"اَلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ، وَلَا مُسْتَغْنًى عَنْهُ رَبَّنَا","latin":"Elhamdülillâhi hamden kesîran tayyiben mübâreken fîhi, ğayre [mekfiyyin ve lâ] müveddain ve lâ müsteğnen anh Rabbenâ","tr":"Allah'a bol, güzel ve bereketli hamd olsun; [karşılık ödenemez ve] vazgeçilemez, Rabbimiz ondan müstağni kalamaz.","en":"All praise is to Allah, praise in abundance, good and blessed. It cannot [be compensated for, nor can it] be left, nor can it be done without, our Lord."},{"id":506,"title":"Yemek Sonrası Dualar","ref":"Sahîh. Ebû Dâvud: 3851","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_506.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ وَسَقَى وَسَوَّغَهُ وَجَعَلَ لَهُ مَخْرَجًا","latin":"Elhamdülillâhillezî et'ame ve sekâ ve sevvağahû ve ce'ale lehû mahrecâ","tr":"Yediren, içiren, onu kolayca yuttutan ve onun için bir çıkış yolu yaratan Allah'a hamd olsun.","en":"Praise be to Allah Who has given food and drink and made it easy to swallow, and provided an exit for it."},{"id":507,"title":"Misafirin Ev Sahibi İçin Duası","ref":"Müslim: 2055","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_507.json","ar":"اَللَّهُمَّ أَطْعِمْ مَنْ أَطْعَمَنِيْ وَاسْقِ مَنْ سَقَانِيْ (وَأَسْقِ مَنْ أَسْقَانِي)","latin":"Allâhümme et'im men et'amenî vaskı men sekânî (başka bir rivayette: ve eskî men eskanî)","tr":"Allâhım! Beni doyuranı doyur ve bana içiren içir.","en":"O Allah, feed the one who has fed me and drink to the one who has given me drink."},{"id":508,"title":"Misafir Olarak Yemek Yerken Ev Sahibine Dua","ref":"Sahîh. Ebû Dâvud: 3854","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_508.json","ar":"أَفْطَرَ عِنْدَكُمُ الصَّائِمُوْنَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ","latin":"Eftare indekümus-sâimûn, ve ekele taâmekümül-ebrâr, ve sallet aleykümel-melâikeh","tr":"Yanınızda oruçlular iftar etti, iyiler yemeğinizi yedi ve melekler size dua etti.\n\nBiri Resûlullah'ın (ﷺ) orucunu açar veya oruçlu olmadığı hâlde ona yemek ikram ederse, bu duayı ona söylerdi: (yukarıdaki dua).","en":"With you, those who are fasting have broken their fast, those who are righteous shall fed by you, and the angels recite their prayers upon you.\n\nIf someone breaks the fast of Rasulullah (ﷺ) or feeds any food other than fasting, he would say du'a for him by saying this - (The dua is mentioned above)"},{"id":509,"title":"Sizi Yediren İçin Dua","ref":"Müslim: 2042","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_509.json","ar":"اَللَّهُمَّ بَارِكْ لَهُمْ فِي مَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ","latin":"Allâhümme bârik lehüm fîmâ rezakteküm, vağfir lehüm verhemhüm","tr":"Allâhım! Onlara verdiğin rızıklarını bereketli kıl, onları bağışla ve onlara merhamet et.\n\nAbdullah ibn Bişr şöyle dedi: 'Allah'ın Resûlü (ﷺ) babamın evine geldi.' Yemek ikram ettiler. Yemekten yedi. Babam onun için dua etmesini istedi. Bunun üzerine şu sözleri söyledi: (yukarıdaki dua).","en":"O Allah, bless them in what You have provided for them, and forgive them and have mercy on them.\n\nAbdullah ibn Bishar said, \"The Messenger of Allah (ﷺ) came to my father's house.\" He offered some food. He took some food from it. My father wants to pray for him. Then he said these words- (The dua is mentioned above)"},{"id":515,"title":"Horoz Öttüğünde Peygamber'in Duası","ref":"Buhârî: 3303","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_515.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ","latin":"Allâhümme innî es'elüke min fadlik","tr":"Allâhım! Senden lütfunu istiyorum.","en":"O Allah, I ask You from Your favor."},{"id":517,"title":"Rüzgar ve Fırtına İçin Dua","ref":"Müslim: 899","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_517.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ وَأَعُوْذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ","latin":"Allâhümme innî es'elüke hayrehâ, ve hayra mâ fîhâ, ve hayra mâ ürsilet bih, ve eûzü bike min şerrihâ, ve şerri mâ fîhâ, ve şerri mâ ürsilet bih","tr":"Allâhım! Onun hayırlısını, içindeki hayırlısını ve beraberinde gönderilenin hayırlısını senden isterim. Onun şerrinden, içindeki şerden ve beraberinde gönderilenin şerrinden sana sığınırım.","en":"O Allah, I ask You for the good of it, for the good of what it contains, and for the good of what is sent with it. I seek refuge in You from the evil of it, from the evil of what it contains, and from the evil that is sent with it."},{"id":519,"title":"Bulutların Şerrinden Korunma Duası","ref":"Sahîh. Ebû Dâvud: 5099","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_519.json","ar":"اَللَّهُمَّ إِنِّي اَعُوذُبِكَ مِنْ شَرِّهَا","latin":"Allâhümme innî eûzü bike min şerrihâ","tr":"Allâhım! Onun şerrinden sana sığınırım.\n\nÂişe'den (r.a.) rivayet edildi, şöyle dedi: 'Göğün ufkunda yoğun bulutların toplandığını görürse Allah'ın Resûlü (ﷺ) namazda olsa bile her işi bırakırdı! Ardından şunu söylerdi: (yukarıdaki dua)'","en":"O Allah! I seek refuge in Thee from its evil.\n\nNarrated Aisha (RA), she said, ‘If he saw clouds condensing on one of the horizons of the sky, the Messenger of Allah (ﷺ) would stop all work, even during Salat! Then he would say back to that- (The dua is mentaioned above)"},{"id":520,"title":"Yağmur Duası","ref":"Buhârî: 1032","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_520.json","ar":"اَللَّهُمَّ صَيِّبًا نَافِعًا","latin":"Allâhümme sayyiben nâfia","tr":"Allâhım! (Bereketli ve) faydalı bir yağmur gönder.","en":"O Allah, (bring) beneficial rain clouds."},{"id":522,"title":"Gök Gürültüsü ve Şimşek İçin Dua","ref":"Sahîh. Edebü'l-Müfred: 560","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_522.json","ar":"سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلَائِكَةُ مِنْ خِيْفَتِهِ","latin":"Sübhânellezî yüsebbihu'r-ra'dü bihamdihî vel-melâiketü min hîfetih","tr":"Gök gürültüsünü ve melekleri O'nun korkusundan O'nu tesbih ettiren Allah'ı tenzih ederim.","en":"Glory is to Him Whom thunder and angels glorify due to fear of Him."},{"id":523,"title":"Gök Gürültülü Fırtına İçin Dua","ref":"Sahîhu'l-İsnâd (Ahmed Şâkir). Müsned Ahmed: 8/98","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_523.json","ar":"اَللَّهُمَّ لَا تَقْتُلْنَا بِغَضَبِكَ وَلَا تُهْلِكْنَا بِعَذَابِكَ وَعَافِنَا قَبْلَ ذَلِكَ","latin":"Allâhümme lâ taktülnâ bi-ğadabike ve lâ tühliknâ bi-azâbike ve âfinâ kable zâlik","tr":"Allâhım! Bizi öfkenle öldürme, azabınla helak etme ve bundan önce bizi affet.","en":"O Allah, do not kill us with Your wrath, and do not destroy us with Your punishment, and pardon us before that."},{"id":524,"title":"Uğursuzluk Düşüncesine Karşı Dua","ref":"Sahîh (Elbânî). Silsile-i Sahîha: 1065, Müsned Ahmed: 7045","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_524.json","ar":"اَللَّهُمَّ لَا طَيْرَ إِلاَّ طَيْرُكَ، وَلَا خَيْرَ إِلَّا خَيْرُكَ، وَلَا إِلَهَ غَيْرُكَ","latin":"Allâhümme lâ tayre illâ tayrüke, ve lâ hayre illâ hayrüke, ve lâ ilâhe ğayrük","tr":"Allâhım! Senin (takdir ettiğin) işaretten başka işaret yoktur; Senin hayırdan başka hayır yoktur ve Senden başka ibadete layık hiçbir ilah yoktur.\n\nİbn Ömer (r.a.) şöyle dedi: Allah'ın Resûlü (ﷺ) buyurdu. Ashâb: 'Ey Allah'ın Resûlü! Böyle bir düşüncenin kefareti nedir?' dediler. O şöyle buyurdu: 'Şunu söylesin.' (yukarıdaki dua).","en":"O Allah, there is no omen but there is reliance on You, there is no good except Your good and none has the right to be worshipped except You.\n\nIbn 'Umar (RA) said: The Messenger of Allah (ﷺ) said: The Companions said, O Messenger of Allah, what is the expiation for such a thought? He said he should say (the above words)."},{"id":525,"title":"Şiddetli Yağmur İçin Dua","ref":"Buhârî: 1019","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_525.json","ar":"اَللَّهُمَّ عَلَى ظُهُوْرِ الْجِبَالِ وَالْآكَامِ وَبُطُوْنِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ","latin":"Allâhümme alâ zühûril-cibâli vel-âkâmi ve butûnil-evdiyeti ve menâbitişşecer","tr":"Allâhım! (Yağmuru) dağların tepelerine, platoların üzerine, vadilerin içine ve ağaçların yetiştiği yerlere (yağdır).\n\nEnes ibn Mâlik'ten (r.a.) rivayet edildi: Allah'ın Resûlü'nün (ﷺ) yanına bir adam gelip şöyle dedi: 'Ey Allah'ın Resûlü! Hayvanlarımız telef oldu, yollar kesildi. Allah'a dua et!' Peygamber (ﷺ) dua etti ve bir Cuma'dan diğerine kadar yağmur yağdı. Sonra bir adam Peygamber'e (ﷺ) gelip şöyle dedi: 'Ey Allah'ın Resûlü! Evlerimiz yıkıldı, yollarımız kesildi, hayvanlarımız telef oldu.' Bunun üzerine Allah'ın Resûlü (ﷺ) şöyle dedi: (yukarıdaki dua). Ardından bulutlar Medine'nin üzerinden elbise soyunur gibi çekildi.","en":"O Allah! (Let it rain) on the summit of the mountain, plateau, where a variety of plants grow in the Valley.\n\nNarrated by Anas Ibn Malik (RA): A man came to the Messenger of Allah (ﷺ) and said, “O Messenger of Allah! Our animals have been destroyed and the roads have been cut off. Pray to Allah (for rain)!” The Prophet (ﷺ) prayed to Allah. As a result, it rained on us from one Jumu'ah to another Jumu'ah. Then a man came to the Prophet (ﷺ) and said, “O Messenger of Allah! Our homes have been destroyed, our roads have been cut off, and our cattle have been destroyed.” Then the Messenger of Allah (ﷺ) said: (The dua is mentioned above) Then the clouds move away from Medina in the same way that clothes are removed from the body."},{"id":526,"title":"Salâtü'l-İstiskâ (Yağmur Namazı Duası)","ref":"Sahîh (Elbânî). Ebû Dâvud: 1169","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_526.json","ar":"اَللَّهُمَّ اسْقِنَا غَيْثًا مُغِيْثًا مَرِيْئًا مَرِيْعًا نَافِعًا غَيْرَ ضَارٍّ عَاجِلًا غَيْرَ آجِلٍ","latin":"Allâhümme eskınâ ğaysen muğîsen merian merian, nâfian ğayre dârrin, âcilen ğayre âcilin","tr":"Allâhım! Bize bol, sağanak, bereketli, faydalı ve zararsız, gecikmeksizin hemen bir yağmur ver.\n\nKısa süre sonra gökyüzü kapandı.","en":"O Allah, shower upon us abundant rain, beneficial not harmful, swiftly and not delayed.\n\nSoon the sky became overcast."},{"id":527,"title":"Salâtü'l-İstiskâ Duası (Yağmur İsteği)","ref":"Buhârî: 1014","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_527.json","ar":"اَللَّهُمَّ أَغِثْنَا، اَللَّهُمَّ أَغِثْنَا، اَللَّهُمَّ أَغِثْنَا","latin":"Allâhümme ağisnâ. Allâhümme ağisnâ. Allâhümme ağisnâ","tr":"Allâhım! Bize yağmur ver. Allâhım! Bize yağmur ver. Allâhım! Bize yağmur ver.\n\nEnes'ten rivayet edildi: Bir adam Cuma günü mescide girdi. Allah'ın Resûlü (ﷺ) o sırada ayakta hutbe veriyordu. Adam şöyle dedi: 'Ey Allah'ın Resûlü! Mallarımız helak oldu, yollar kesildi; Allah'a dua et de bize yağmur ver.' Bunu duyan Allah'ın Resûlü (ﷺ) ellerini kaldırdı ve şunu söyledi: (yukarıdaki dua)","en":"O Allah, give us rain. O Allah, give us rain. O Allah, give us rain.\n\nNarrated Anas: A man enters the mosque on Friday. The Messenger of Allah (ﷺ) was then standing and giving a sermon (speech). The man said, “O Messenger of Allah! (Our) wealth has been destroyed, roads have been cut off; Pray to Allah to give us rain. ”Hearing this, the Messenger of Allah (ﷺ) raised his hands and said:(The dua is mentioned above)"},{"id":528,"title":"Yağmur Duası (Salâtü'l-İstiskâ)","ref":"Hasen (Elbânî). Ebû Dâvud: 1176","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_528.json","ar":"اَللَّهُمَّ اسْقِ عِبَادَكَ، وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِي بَلَدَكَ الْمَيِّتَ","latin":"Allâhümmeske ibâdeke ve behâimeke venşür rahmeteke ve ahyi beledakel-meyyite","tr":"Allâhım! Kullarını ve hayvanlarını sula, rahmetini yay ve ölü toprağına hayat ver.","en":"O Allah, give water to Your slaves, and Your livestock, and spread Your mercy, and revive Your dead land."},{"id":529,"title":"Yağmurun Durması İçin Dua","ref":"Hasen (Elbânî). Ebû Dâvud: 1/218","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_529.json","ar":"اَللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اَللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ، وَبُطُونِ الْأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ","latin":"Allâhümme havâleynâ ve lâ aleynâ. Allâhümme alel-âkâmi vedh-dhirâbi, ve butûnil-evdiyeti, ve menâbitişşecer","tr":"Allâhım! Etrafımıza yağdır, üzerimize değil. Allâhım! Platoların üzerine, dağ yamaçlarına, vadilerin içine ve ağaçların yetiştiği yerlere (yağdır).","en":"O Allah, let it pass us and not fall upon us, but upon the hills and mountains, and the center of the valleys, and upon the forested lands."},{"id":530,"title":"Yağmur İçin Şükür Duası","ref":"Buhârî: 846","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_530.json","ar":"مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ","latin":"Mutırnâ bifadlillâhi ve rahmetih","tr":"Allah'ın lütfu ve rahmeti sayesinde yağmur yağdı.\n\nZeyd ibn Hâlid el-Cühenî'den (r.a.) rivayet edildi: Peygamber (ﷺ), Hudeybiye'de yağmurlu bir gecenin ardından bize sabah namazı kıldırdı. Namazı bitirince cemaate döndü ve şöyle buyurdu: 'Rabbinizin ne dediğini biliyor musunuz?' Cemaat: 'Allah ve Resûlü daha iyi bilir' dedi. Şöyle buyurdu: 'Allah şöyle dedi: Bu sabah kullarımdan kimi mü'min kaldı, kimi kâfir oldu. (Yukarıdaki duayı) söyleyen bana inanmış ve yıldızları inkâr etmiş oldu. Belirli bir yıldız yüzünden yağmur yağdı diyen ise beni inkâr edip o yıldıza inandı.'","en":"It has rained by the bounty of Allah and His mercy.\n\nNarrated Zaid bin Khalid Al-Juhani (RA): The Prophet (ﷺ) led us in the Fajr prayer at Hudaibiya after a rainy night. On completion of the prayer, he faced the people and said, \"Do you know what your Lord has said (revealed)?\" The people replied, \"Allah and His Apostle know better.\" He said, \"Allah has said, 'In this morning some of my slaves remained as true believers and some became non-believers; whoever said that (The dua is mentioned above) had belief in Me and he disbelieves in the stars, and whoever said that it rained because of a particular star had no belief in Me but believes in that star.'"},{"id":531,"title":"Şifa Duası (Fâtiha Sûresi)","ref":"Buhârî: 5741","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_531.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ ﴿١﴾ الْحَمْدُ لِلَّـهِ رَبِّ الْعَالَمِينَ ﴿٢﴾ الرَّحْمَـٰنِ الرَّحِيمِ ﴿٣﴾ مَالِكِ يَوْمِ الدِّينِ ﴿٤﴾ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ﴿٥﴾ اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿٦﴾ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ ﴿٧﴾","latin":"(1) Bismillâhirrahmânirrahîm. (2) Elhamdülillâhi Rabbil-âlemîn. (3) Errahmânirrahîm. (4) Mâliki yevmiddîn. (5) İyyâke na'büdü ve iyyâke nesta'în. (6) İhdinessırâtel-müstakîm. (7) Sırâtallezîne en'amte aleyhim ğayril-mağdûbi aleyhim ve leddâllîn","tr":"(1) Rahmân ve Rahîm olan Allah'ın adıyla. (2) Hamd, âlemlerin Rabbi Allah'a mahsustur. (3) O, Rahmân'dır, Rahîm'dir. (4) Din gününün sahibidir. (5) Yalnız Sana ibadet ederiz ve yalnız Senden yardım dileriz. (6) Bizi doğru yola ilet. (7) Kendilerine nimet verdiklerinin yoluna; gazaba uğramışların ve sapkınların yoluna değil. (Fâtiha Sûresi: 1-7)\n\nEl-Esved'den (r.a.) rivayet edildi: Âişe'ye zehirli sokmaya (yılan veya akrep sokması) karşı rukye uygulamasını sordum. O şöyle dedi: 'Peygamber (ﷺ) zehirli sokmaya karşı rukye tedavisine izin verdi.'","en":"(1) In the name of Allah, the Entirely Merciful, the Especially Merciful. (2) [All] praise is [due] to Allah, Lord of the worlds - (3) The Entirely Merciful, the Especially Merciful, (4) Sovereign of the Day of Recompense. (5) It is You we worship and You we ask for help. (6) Guide us to the straight path - (7) The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray. (Sura Fatiha: 1-7)\n\nNarrated Al-Aswad (RA): I asked `Aisha about treating poisonous stings (a snake-bite or a scorpion sting) with a Ruqya. She said, \"The Prophet (ﷺ) allowed the treatment of poisonous sting with Ruqya.\""},{"id":532,"title":"Nazar İçin Dua (Meşnu Dua)","ref":"Sahîh (Elbânî). İbn Mâce: 3508, 3509","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_532.json","ar":"بَارَكَ اللَّهُ لَكَ","latin":"Bârekallâhü lek","tr":"Allah seni mübarek kılsın.\n\nZira nazar gerçektir.","en":"Allah give blessings to you.\n\nBecause, for the evil eye is real."},{"id":534,"title":"Hastalık İçin Peygamber'in Duası","ref":"Buhârî: 5743","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_534.json","ar":"اَللَّهُمَّ رَبَّ النَّاسِ أَذْهِبِ الْبَأْسَ اِشْفِ وَأَنْتَ الشَّافِي لَا شِفَاءَ إِلاَّ شِفَاؤُكَ شِفَاءً لَا يُغَادِرُ سَقَمًا","latin":"Allâhümme Rabben-nâs, ezhibil-be's, işfi ve entеş-Şâfî, lâ şifâe illâ şifâüke, şifâen lâ yüğâdiru sekamâ","tr":"Allâhım, insanların Rabbi! Hastalığı gider, şifa ver; şüphesiz Sen Şâfî'sin. Senin şifandan başka şifa yoktur; geride hiçbir hastalık bırakmayan bir şifa ver.\n\nÂişe'den (r.a.) rivayet edildi: Peygamber (ﷺ) bazı eşlerini tedavi ederken sağ elini hastalıklı bölgeden geçirir ve şunu söylerdi: (yukarıdaki dua)","en":"O Allah, the Lord of the people! Remove the trouble and heal the patient, for You are the Healer. No healing is of any avail but Yours; healing that will leave behind no ailment.\n\nNarrated `Aisha (RA): The Prophet (ﷺ) used to treat some of his wives by passing his right hand over the place of ailment and used to say: (The dua is mentioned above)"},{"id":535,"title":"Ağrı Giderme İçin Güçlü Dua","ref":"Buhârî: 5745, Müslim: 2194","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_535.json","ar":"باِسْمِ اللَّهِ تُرْبَةُ أَرْضِنَا بِرِيْقَةِ بَعْضِنَا يُشْفَى (بِهِ) سَقِيْمُنَا بِإِذْنِ رَبِّنَا","latin":"Bismillâhi, türbetü ardınâ, birikati ba'dınâ, yüşfâ (bihî) sekîmünâ, bi'izni Rabbinâ","tr":"Allah'ın adıyla. Toprağımızın tozu ve bazımızın tükürüğüyle Rabbimizin izniyle hastamız şifa bulur.\n\nÂişe (r.a.) şöyle dedi: Bedenin herhangi bir yerinde bir hastalık, ağrı veya yara olduğunda Resûlullah (ﷺ) şehâdet parmağını yere koyar kaldırır ve bu duayı okurdu. Başka bir rivayette, ağzının tükürüğünden biraz parmağına sürüp parmağını yere koyar, sonra ağrıyan yere dokundurur ve bu duayı söylerdi.","en":"In the Name of Allah The earth of our land and the saliva of some of us cure our patient.\n\nAyesha (RA) said that if there was any illness, pain or wound on any part of the body, Rasulullah (ﷺ) would place his (Shahadat) finger on the ground and lift it and recite this Dua. In another narration, he would put a little saliva of his mouth on his finger and put his finger on the ground and then put it in the place of pain and say this dua."},{"id":537,"title":"Şifa İçin Güçlü Dua (İhlâs, Felak, Nâs Sûreleri)","ref":"Buhârî: 5735","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_537.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ هُوَ اللَّـهُ أَحَدٌ ﴿١﴾ اللَّـهُ الصَّمَدُ ﴿٢﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿٣﴾ وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ ﴿","latin":"Bismillâhirrahmânirrahîm. (1) Kul HuvAllâhü Ahad. (2) Allâhüs-Samed. (3) Lem yelid ve lem yûled. (4) Ve lem yekün lehû küfüven ehad","tr":"Rahman ve Rahîm olan Allah'ın adıyla. (1) De ki: 'O, Allah'tır, bir tektir. (2) Allah Samed'dir (her şey O'na muhtaçtır, O hiçbir şeye muhtaç değildir). (3) O doğurmamış ve doğurulmamıştır. (4) Hiçbir şey O'na denk ve benzer değildir.' (İhlâs Sûresi: 1-4)","en":"In the name of Allah, the Entirely Merciful, the Especially Merciful. (1) Say, \"He is Allah, [who is] One, (2) Allah, the Eternal Refuge. (3) He neither begets nor is born, (4) Nor is there to Him any equivalent.\" (Sura Ikhlas: 1-4)"},{"id":540,"title":"Sağlık ve Şifa Duası","ref":"Buhârî: 5675","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_540.json","ar":"أَذْهِبِ الْبَأْسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا","latin":"Ezhibibil-be'se Rabben-nâs, veşfi ente'ş-Şâfî, lâ şifâe illâ şifâüke, şifâen lâ yüğâdiru sekamâ","tr":"Ey insanların Rabbi! Hastalığı gider ve şifa ver; zira şifa veren yalnız Sensin. Senin şifanın dışında şifa yoktur; hiçbir hastalık bırakmayan bir şifadır bu.\n\nAllah'ın Resûlü (ﷺ) bir hastayı ziyaret ettiğinde ya da bir hasta ona getirildiğinde şu duayı okurdu: (Dua yukarıda zikredilmiştir)","en":"Take away the disease, O the Lord of the people! Cure him as You are the One Who cures. There is no cure but Yours, a cure that leaves no disease.\n\nWhenever Allah's Messenger (ﷺ) paid a visit to a patient, or a patient was brought to him, he used to invoke Allah, saying (The dua is mentioned above)"},{"id":541,"title":"Hasta İçin Dua (Meşnu Dua)","ref":"Buhârî: 3616","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_541.json","ar":"لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ","latin":"Lâ be'se tahûrun inşâAllâh","tr":"Üzülme, inşallah (sana) bir kefaret olur.\n\nPeygamber (ﷺ) hasta ziyaretine gittiğinde bu duayı okurdu.","en":"Do not worry, it will be a purification (for you), Allah willing.\n\nThe Prophet (ﷺ) used to say this dua when he went to see a sick person."},{"id":542,"title":"Hasta İçin İslami Dua","ref":"Sahîh. Tirmizî: 2083","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_542.json","ar":"أَسْأَلُ اللَّهَ الْعَظِيْمَ رَبَّ الْعَرْشِ الْعَظِيْمِ أَنْ يَشْفِيَكَ","latin":"Es'elüllâhel-Azîme Rabbel-Arşil-Azîmi en yeşfiyeke","tr":"Yüce Arş'ın Rabbi olan Azîm Allah'tan seni iyileştirmesini istiyorum.\n\nİbn Abbâs'tan (r.a.) rivayetle Peygamber (ﷺ) şöyle buyurdu: 'Hiçbir Müslüman hasta ziyaretine gider — ölüm anı hariç — ve yedi kez şu duayı okursa: (Dua yukarıda zikredilmiştir), mutlaka o kimse şifa bulur.'","en":"I ask Almighty Allah, Lord of the Magnificent Throne, to make you well.\n\nIbn 'Abbas (RA) narrated that the Prophet (ﷺ) said: \"There is no Muslim worshiper who visits one who is ill - other than at the time of death - and he says seven times: (The dua is mentioned above) except when he will be cured.\" (The dua is mentioned above)"},{"id":543,"title":"Bağışlanma ve Cennet İçin Dua","ref":"Sahîh (Elbânî). Sahîhu'l-Câmi: 1267","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_543.json","ar":"اَللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى","latin":"Allâhümmağfir lî verhamnî ve elhıknî bir-rafîkıl-a'lâ","tr":"Allâhım! Beni bağışla, bana merhamet et ve beni en yüce dostlara (cennette) kavuştur.","en":"O Allah, forgive me and have mercy upon me and join me with the highest companions (in Paradise)."},{"id":544,"title":"Ölüm Yaklaştığında Okunacak Dua (Meşnu Dualar)","ref":"Sahîh (Elbânî). Tirmizî: 3430","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_544.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ","latin":"Lâ ilâhe illAllâhü vAllâhü Ekber","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur ve Allah en büyüktür.\n\nRabbi onun sözünü tasdik eder ve şöyle der: 'Benden başka ibadete layık ilah yoktur ve Ben en Büyüğüm.'","en":"None has the right to be worshipped except Allah and Allah is the greatest.\n\nHis Lord affirms his statement and says: ‘There is none worthy of worship except Me, and I am the Greatest,’"},{"id":547,"title":"Peygamber Muhammed'in (ﷺ) Can Çekişme Duası","ref":"Buhârî: 4449","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_547.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ","latin":"Lâ ilâhe illAllâhü inne lilmevti sekerât","tr":"Allah'tan başka ibadete layık hiçbir ilah yoktur; şüphesiz ölümün can çekişmeleri vardır.","en":"There is none worthy of worship but Allah, surely death has agonies."},{"id":549,"title":"Zor Zamanlarda Sabır Duası","ref":"Müslim: 918","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_549.json","ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اَللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا","latin":"İnnâ lillâhi ve innâ ileyhi râciûn, Allâhümme'curnî fî musîbetî, vahlüf lî hayran minhâ","tr":"Biz Allah'a aidiz ve O'na döneceğiz; ey Allah'ım, bu musibetimde bana ecir ver ve bunu benden daha hayırlısıyla değiştir.\n\nAllah ona kesinlikle daha hayırlısını verir. Ebû Seleme'nin vefatından sonra ben bu duayı Allah Resûlü'nün (ﷺ) tavsiyesi doğrultusunda okudum; Allah da bana ondan daha hayırlısını, yani Allah Resûlü'nü (ﷺ) verdi.","en":"We belong to Allah and to Him shall we return; O Allah, reward me for my affliction and give me something better than it in exchange for it.\n\nAllah will surely give him something better than that. After the death of Abu Salamah, I recite this du'a according to the instructions of the Messenger of Allah (ﷺ), then Allah has given me better than him, that is, to the Messenger of Allah (ﷺ)."},{"id":550,"title":"Hasta ve Vefat Eden Kişi İçin Dua (Mesnun Dua)","ref":"Müslim: 919","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_550.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَلَهُ وَأَعْقِبْنِي مِنْهُ عُقْبٰى حَسَنَةً","latin":"Allâhümmaghfir lî velehû, ve a'kıbnî minhü ukbâ haseneh","tr":"Ey Allah'ım, beni ve onu bağışla; bana onun yerine daha hayırlısını ver.\n\nÜmmü Seleme (RA) rivayet etti: Allah'ın Resûlü (ﷺ) şöyle buyurdu: 'Hasta veya vefat etmiş birine gittiğinizde hayır dua edin; zira melekler söylediğiniz her şeye 'Âmîn' derler.' Ümmü Seleme ekledi: Ebû Seleme vefat edince Allah'ın Resûlü'ne (ﷺ) gittim ve: 'Ey Allah'ın Resûlü, Ebû Seleme vefat etti' dedim. O bana bu duayı okumamı emretti. Ben de okuyunca Allah bana onun yerine Muhammed'i (ﷺ) verdi; o benim için Ebû Seleme'den daha hayırlıydı.","en":"O Allah, forgive me and him, and compensate me with someone better than him.\n\nUmm Salama (RA) reported Allah's Messenger (ﷺ) as saying: Whenever you visit the sick or the dead, supplicate for good because angels say\" Amen\" to whatever you say. She added: When Abu Salama died, I went to the Messenger of Allah (ﷺ) and said: Messenger of Allah, Abu Salama has died. He told me to recite:(The dua is mentioned above) So I said (this), and Allah gave me in exchange Muhammad (ﷺ), who is better for me than him (Abu Salama)."},{"id":551,"title":"Vefat Eden İçin Mağfiret Duası (Mesnun Dua)","ref":"Müslim: 920","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_551.json","ar":"اَللَّهُمَّ اغْفِرْ لَهُ وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِيْنَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِيْنَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ","latin":"Allâhümmaghfir lehû [kişinin adını zikredin] verfa' deracetehû fil-mehdiyyîn, vahlüfhü fî akıbihî fil-ğâbirîn, vaghfir lenâ ve lehû yâ Rabbel-âlemîn, vefsah lehû fî kabrihî ve nevvir lehû fîh","tr":"Ey Allah'ım, [falan kişiyi] bağışla; onun derecesini hidayete erenlerin arasında yükselt, geride bıraktıkları içinde ona hayırlı bir halef ol, ey âlemlerin Rabbi bizi ve onu bağışla, kabrini genişlet ve onu kabrinde aydınlat.\n\nAllah'ın Resûlü (ﷺ), Ebû Seleme (vefat ederken) yanına geldi. Gözlerinin açık kaldığını gördü; onları kapattı, ardından şöyle buyurdu: (Dua yukarıda zikredilmiştir)","en":"O Allah, forgive – [so-and-so] - and raise his rank among the rightly guided, and be a successor to whom he has left behind, and forgive us and him O Lord of the worlds. Make spacious his grave and illuminate it for him.\n\nThe Messenger of Allah (ﷺ) came to Abu Salama (as he died). His eyes were fixedly open. He closed them, and then said: (The dua is mentioned above)"},{"id":552,"title":"Vefat Eden Kadın İçin Mağfiret Duası","ref":"Müslim: 920","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_552.json","ar":"اَللَّهُمَّ اغْفِرْ لَهَا وَارْفَعْ دَرَجَتَهَا فِي الْمَهْدِيِّيْنَ، وَاخْلُفْهَآ فِي عَقِبِهَا فِي الْغَابِرِيْنَ، وَاغْفِرْ لَنَا وَلَهَا يَا رَبَّ الْعَالَمِيْنَ، وَافْسَحْ لَهَا فِي قَبْرِهَا، وَنَوِّرْ لَهَا فِيهِ","latin":"Allâhümmaghfir lehâ [kişinin adını zikredin] verfa' deracetehâ fil-mehdiyyîn, vahlüfhâ fî akıbihâ fil-ğâbirîn, vaghfir lenâ ve lehâ yâ Rabbel-âlemîn, vefsah lehâ fî kabrihâ ve nevvir lehâ fîh","tr":"Ey Allah'ım, [falan kadını] bağışla; onun derecesini hidayete erenlerin arasında yükselt, geride bıraktıkları içinde ona hayırlı bir halef ol, ey âlemlerin Rabbi bizi ve onu bağışla, kabrini genişlet ve onu kabrinde aydınlat.","en":"O Allah, forgive – [so-and-so] - and raise her rank among the rightly guided, and be a successor to whom she has left behind, and forgive us and her O Lord of the worlds. Make spacious her grave and illuminate it for her."},{"id":553,"title":"Nazar ve Korunma Duası","ref":"Buhârî: 3371","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_553.json","ar":"أَعُوْذُ بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَّامَّةٍ","latin":"Eûzü bi kelimâtillâhit-tâmmeti min külli şeytânin ve hâmmeh, ve min külli aynin lâmmeh","tr":"Her şeytandan, her zehirli hayvandan ve her kötü gözden Allah'ın eksiksiz kelamına sığınırım.\n\nPeygamber (ﷺ), Hasan ve Hüseyin için Allah'a sığınır ve şöyle buyururdu: 'Dedeniz İbrahim (AS), İsmail ve İshak için şu sözlerle Allah'a sığınırdı: (dua yukarıda zikredilmiştir)' İnanan tüm anne ve babalar bu sözleri sabah ve akşam okuyarak çocuklarına üflemeli ve dua etmelidir. Bunun yanında herkes sabah ve akşam kendi korunması için de bu duayı okumalıdır.","en":"I commend you to the protection of Allah’s perfect words from every devil, vermin, and every evil eye.\n\nThe Prophet (ﷺ) used to seek Refuge with Allah for Al-Hasan and Al-Husain and say: \"Your forefather (i.e. Abraham) used to seek Refuge with Allah for Ishmael and Isaac by reciting the following: (the dua is mentioned above) All believing fathers and mothers should recite these verses in the morning and in the evening, blow their children and make dua. Besides, everyone should recite the dua in the morning and evening for their own protection."},{"id":554,"title":"Kötülük ve Hasetten Korunma Duası","ref":"[1] Felak Sûresi: 1-5 [2] Nâs Sûresi: 1-6 [3] Sahîh (Elbânî). İbn Mâce: 3511","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_554.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أَعُوْذُ بِرَبِّ الْفَلَقِ ﴿١﴾ مِن شَرِّ مَا خَلَقَ ﴿٢﴾ وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ ﴿٣﴾ وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ ﴿٤﴾ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ ﴿٥﴾","latin":"Bismillâhir-Rahmânir-Rahîm. (1) Kul eûzü bi Rabbil-felak. (2) Min şerri mâ halak. (3) Ve min şerri ğâsikin izâ vakab. (4) Ve min şerrin-neffâsâti fil-ukad. (5) Ve min şerri hâsidin izâ hased","tr":"(1) De ki: Sabahın Rabbine sığınırım. (2) Yarattığı şeylerin şerrinden. (3) Bastırdığında karanlığın şerrinden. (4) Düğümlere üfleyenlerin şerrinden. (5) Haset ettiğinde haset edenin şerrinden. (Felak Sûresi: 1-5)","en":"(1) Say, \"I seek refuge in the Lord of daybreak (2) From the evil of that which He created (3) And from the evil of darkness when it settles (4) And from the evil of the blowers in knots (5) And from the evil of an envier when he envies.\" (Sura Falaq: 1-5)"},{"id":555,"title":"Korunma ve Şifa İçin Rukye Duası","ref":"Müslim: 2186","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_555.json","ar":"بِسْمِ اللَّهِ أَرْقِيْكَ مِنْ كُلِّ شَيْءٍ يُؤْذِيْكَ، مِنْ شَرِّ كُلِّ نَفْسٍ أَوْ عَيْنٍ حَاسِدٍ، اَللَّهُ يَشْفِيكْ، بِسْمِ اللَّهِ أَرْقِيْكَ","latin":"Bismillâhi erkîk, min külli şey'in yü'zîk, min şerri külli nefsin ev aynin hâsidin. Allâhü yeşfîk, bismillâhi erkîk","tr":"Allah'ın adıyla sana rukye yapıyorum; sana zarar veren her şeyden, her nefsin veya hasetçi gözün şerrinden. Allah seni iyileştirsin. Allah'ın adıyla sana rukye yapıyorum.\n\nEbû Saîd el-Hudrî (RA) şöyle dedi: Cebrail (AS), Allah'ın Resûlü'ne (ﷺ) geldi; o sırada ateşi vardı. Cebrail (AS): 'Ey Muhammed, hasta mısın?' dedi. O da: 'Evet' dedi. Bunun üzerine Cebrail (AS) yukarıdaki sözleri söyledi.","en":"In the Name of Allah I perform Ruqyah for you, from everything that is harming you, from the evil of every soul or envious eye, may Allah heal you. In the Name of Allah I perform Ruqyah for you.\n\nAbu Sayed Khudri (RA) said, Gabriel (As) came to the Messenger of Allah (ﷺ) (he was feverish at that time). Gabriel (As) said, Muhammad, are you sick? He said: Yes. Then he said the above words."},{"id":556,"title":"Kötü Gözden Ağrı Giderme Duası","ref":"Ceyyid/İyi senet (Hüseyin Selîm Esed). Müsned Ebî Ya'lâ el-Mevsılî: 8195","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_556.json","ar":"اَللَّهُمَّ أَذْهِبْ حَرَّهَا وَبَرْدَهَا، وَوَصَبَهَا","latin":"Allâhümme ezhibharre hâ ve berdehâ ve vasebehâ","tr":"Ey Allah'ım! Onun [kötü göz] hararetini, soğuğunu ve acısını gider.","en":"O Allah ! Remove its [evil eye] heat and cold and its pain."},{"id":560,"title":"Sâlihler İçin Hidayet Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 1-5","url":"https://quran.com/2/1","ar":"الم ﴿١﴾ ذَٰلِكَ الْكِتَابُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ ﴿٢﴾ الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ﴿٣﴾ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ ﴿٤﴾ أُولَـٰئِكَ عَلَىٰ هُدًى مِّن رَّبِّهِمْ ۖ وَأُولَـٰئِكَ هُمُ الْمُفْلِحُونَ ﴿٥﴾","latin":"Elif-Lâm-Mîm. Zâlikel-kitâbü lâ raybe fîh; hüdel-lil-müttekîn. Ellezîne yü'minûne bil-ğaybi ve yükîmûnes-salâte ve mimmâ razaknâhüm yünfikûn. Vellezîne yü'minûne bimâ ünzile ileyke ve mâ ünzile min kablik ve bil-âhirati hüm yûkınûn. Ülâike alâ hüden min Rabbihim ve ülâike hümül-müflihûn.","tr":"(1) Elif. Lâm. Mîm. (2) Bu, kendisinde şüphe olmayan kitaptır; takvâ sahipleri için yol göstericidir. (3) Onlar gayba inanırlar, namazı dosdoğru kılarlar ve kendilerine rızık olarak verdiklerimizden infak ederler. (4) Ve onlar sana indirilene ve senden önce indirilene iman ederler; ahirete de kesin bir inanç beslerler. (5) İşte bunlar Rablerinden gelen bir hidayet üzerindedirler ve kurtuluşa erenler de bunlardır.","en":"(1) Alif, Lam, Meem. (2) This is the Book about which there is no doubt, a guidance for those conscious of Allah - (3) Who believe in the unseen, establish prayer, and spend out of what We have provided for them, (4) And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith]. (5) Those are upon [right] guidance from their Lord, and it is those who are the successful.`"},{"id":561,"title":"Büyü ve Kötülükten Korunma Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 102","url":"https://quran.com/2/102","ar":"وَاتَّبَعُوا مَا تَتْلُو الشَّيَاطِينُ عَلَىٰ مُلْكِ سُلَيْمَانَ ۖ وَمَا كَفَرَ سُلَيْمَانُ وَلَـٰكِنَّ الشَّيَاطِينَ كَفَرُوا يُعَلِّمُونَ النَّاسَ السِّحْرَ وَمَا أُنزِلَ عَلَى الْمَلَكَيْنِ بِبَابِلَ هَارُوتَ وَمَارُوتَ ۚ وَمَا يُعَلِّمَانِ مِنْ أَحَدٍ حَتَّىٰ يَقُولَا إِنَّمَا نَحْنُ فِتْنَةٌ فَلَا تَكْفُرْ ۖ فَيَتَعَلَّمُونَ مِنْهُمَا مَا يُفَرِّقُونَ بِهِ بَيْنَ الْمَرْءِ وَزَوْجِهِ ۚ وَمَا هُم بِضَارِّينَ بِهِ مِنْ أَحَدٍ إِلَّا بِإِذْنِ اللَّـهِ ۚ وَيَتَعَلَّمُونَ مَا يَضُرُّهُمْ وَلَا يَنفَعُهُمْ ۚ وَلَقَدْ عَلِمُوا لَمَنِ اشْتَرَاهُ مَا لَهُ فِي الْآخِرَةِ مِنْ خَلَاقٍ ۚ وَلَبِئْسَ مَا شَرَوْا بِهِ أَنفُسَهُمْ ۚ لَوْ كَانُوا يَعْلَمُونَ ﴿١٠٢﴾","latin":"Vetteba'û mâ tetlûş-şeyâtîn'ü alâ mülki Süleymân; ve mâ kefere Süleymânü ve lâkinneş-şeyâtîne keferû yü'allimûnen-nâses-sihra ve mâ ünzile alel-melekeyni bi-Bâbile Hârûte ve Mârût; ve mâ yü'allimâni min ehadin hattâ yekûlâ innemâ nahnü fitnetün felâ tekfür. Feyeteallemûne minhümâ mâ yüferrıkûne bihî beynel-mer'i ve zevcih; ve mâ hüm bi-dârrîne bihî min ehadin illâ bi-iznillâh; ve yeteallemûne mâ yadurruhüm ve lâ yenfeuhüm; ve lekad alimû le-meniştarâhü mâ lehû fil-âhirati min halâk; ve lebi'se mâ şerav bihî enfüsehüm; lev kânû ya'lemûn.","tr":"(102) Ve onlar Süleyman'ın mülkü hakkında şeytanların okuduklarına uydular. Süleyman küfre girmedi; lakin şeytanlar küfre girdi, insanlara sihri ve Bâbil'de Hârût ile Mârût adlı iki meleğe indirileni öğrettiler. Hâlbuki o ikisi hiç kimseye, 'Biz ancak bir sınavız, sakın küfre girme' demedikçe bir şey öğretmiyordu. Fakat onlar, o ikisinden erkekle karısının arasını açacak şeyler öğreniyorlardı. Allah'ın izni olmadan bununla hiç kimseye zarar veremezlerdi. Onlar ise kendilerine zarar verecek, fayda sağlamayacak şeyler öğreniyorlardı. Andolsun, onu satın alanın âhirette hiçbir payı olmadığını biliyorlardı. Karşılığında kendilerini sattıkları şey ne kadar kötü! Keşke bilselerdi.","en":"(102) And they followed [instead] what the devils had recited during the reign of Solomon. It was not Solomon who disbelieved, but the devils disbelieved, teaching people magic and that which was revealed to the two angels at Babylon, Harut and Marut. But the two angels do not teach anyone unless they say, \"We are a trial, so do not disbelieve [by practicing magic].\" And [yet] they learn from them that by which they cause separation between a man and his wife. But they do not harm anyone through it except by permission of Allah . And the people learn what harms them and does not benefit them. But the Children of Israel certainly knew that whoever purchased the magic would not have in the Hereafter any share. And wretched is that for which they sold themselves, if they only knew."},{"id":562,"title":"İslam'da Allah'ın Birliği (Bakara Sûresi)","ref":"Bakara Sûresi 2: 163-164","url":"https://quran.com/2/163","ar":"وَإِلَـٰهُكُمْ إِلَـٰهٌ وَاحِدٌ ۖ لَّا إِلَـٰهَ إِلَّا هُوَ الرَّحْمَـٰنُ الرَّحِيمُ ﴿١٦٣﴾ إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ وَمَا أَنزَلَ اللَّـهُ مِنَ السَّمَاءِ مِن مَّاءٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا وَبَثَّ فِيهَا مِن كُلِّ دَابَّةٍ وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ ﴿١٦٤﴾","latin":"Ve ilâhüküm ilâhün Vâhid; lâ ilâhe illâ Hüver-Rahmânür-Rahîm. İnne fî halkas-semâvâti vel-ardı vahtilâfil-leyli ven-nehâri vel-fülkiLletî tecrî fil-bahri bimâ yenfaun-nâse ve mâ enzelallâhü mines-semâi min mâin fe-ahyâ bihil-arda ba'de mevtihâ ve besse fîhâ min külli dâbbeh ve tasrîfir-riyâhi ves-sahâbil-müsehharin beynes-semâi vel-ardı le-âyâtil-li-kavmiy-ya'kılûn.","tr":"(163) Sizin ilahınız tek bir ilahtır. O'ndan başka hiçbir ilah yoktur; O, Rahmân'dır, Rahîm'dir. (164) Şüphesiz göklerin ve yerin yaratılışında, gece ile gündüzün birbirini izlemesinde, insanlara faydalı şeyler taşıyarak denizde akıp giden gemilerde, Allah'ın gökten indirip de ölü hâldeki toprağı canlandırdığı suda, yeryüzünde her çeşit canlıyı yaymasında, rüzgârları yönlendirmesinde ve gök ile yer arasındaki emre amade bulutlarda aklını kullanan bir topluluk için gerçekten ayetler (deliller) vardır.","en":"(163) And your god is one God. There is no deity [worthy of worship] except Him, the Entirely Merciful, the Especially Merciful. (164) Indeed, in the creation of the heavens and earth, and the alternation of the night and the day, and the [great] ships which sail through the sea with that which benefits people, and what Allah has sent down from the heavens of rain, giving life thereby to the earth after its lifelessness and dispersing therein every [kind of] moving creature, and [His] directing of the winds and the clouds controlled between the heaven and the earth are signs for a people who use reason."},{"id":564,"title":"Güç ve Mağfiret İçin Kur'anî Dua (Bakara Sûresi)","ref":"Bakara Sûresi 2: 284-286","url":"https://quran.com/2/284","ar":"لِّلَّـهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللَّـهُ ۖ فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ ۗ وَاللَّـهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ ﴿٢٨٤﴾ آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّـهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ﴿٢٨٥﴾ لَا يُكَلِّفُ اللَّـهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ﴿٢٨٦﴾","latin":"Lillâhi mâ fis-semâvâti ve mâ fil-ard; ve in tübdû mâ fî enfüsiküm ev tuhfûhü yühâsibküm bihillâh; feyağfiru li-men yeşâü ve yüazzibü men yeşâ'; vallâhü alâ külli şey'in Kadîr. Âmener-Rasûlü bimâ ünzile ileyhi min Rabbihî vel-mü'minûn; küllün âmene billâhi ve melâiketihî ve Kütübihî ve Rusülihî lâ nüferriku beyne ehadin min Rusülih; ve kâlû semı'nâ ve ata'nâ ğufrâneke Rabbenâ ve ileykel-masîr. Lâ yükellifullâhü nefsen illâ vüs'ahâ; lehâ mâ kesebet ve aleyhâ mektesebet; Rabbenâ lâ tüâhıznâ in nesînâ ev ahta'nâ; Rabbenâ ve lâ tahmil aleynâ ısran kemâ hameltehu alellezîne min kablinâ; Rabbenâ ve lâ tühammilnâ mâ lâ tâkate lenâ bih; va'fü annâ vaghfir lenâ verhamnâ; Ente Mevlânâ fensurnâ alel-kavmil-kâfirîn.","tr":"(284) Göklerde ve yerdekilerin hepsi Allah'ındır. İçinizdekini açığa vursanız da gizleseniz de Allah onunla sizi hesaba çeker. Sonra dilediğini affeder, dilediğini azaplandırır. Allah'ın her şeye gücü yeter. (285) Peygamber, Rabbi'nden kendisine indirilene iman etti; müminler de iman etti. Hepsi Allah'a, meleklerine, kitaplarına ve peygamberlerine iman etti. 'O'nun peygamberleri arasında hiçbir ayırım yapmayız' dediler. Ve şöyle dediler: 'İşittik ve itaat ettik. Ey Rabbimiz, bağışlamanı isteriz. Dönüş sanadır.' (286) Allah, hiçbir kimseyi gücünün yettiğinden fazlasıyla yükümlü kılmaz. Herkesin kazandığı iyilik kendi lehine, işlediği kötülük kendi aleyhinedir. 'Ey Rabbimiz, unutur ya da yanılırsak bizi sorumlu tutma! Ey Rabbimiz, bizden öncekilere yüklediğin gibi bize de ağır yük yükleme. Ey Rabbimiz, takat getiremeyeceğimiz şeyleri de bize taşıtma! Bizi affet, bizi bağışla, bize merhamet et. Sen bizim Mevlâmızsın. Kâfirler topluluğuna karşı bize yardım et.'","en":"(284) To Allah belongs whatever is in the heavens and whatever is in the earth. Whether you show what is within yourselves or conceal it, Allah will bring you to account for it. Then He will forgive whom He wills and punish whom He wills, and Allah is over all things competent. (285) The Messenger has believed in what was revealed to him from his Lord, and [so have] the believers. All of them have believed in Allah and His angels and His books and His messengers, [saying], \"We make no distinction between any of His messengers.\" And they say, \"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination.\" (286) Allah does not charge a soul except [with that within] its capacity. It will have [the consequence of] what [good] it has gained, and it will bear [the consequence of] what [evil] it has earned. \"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.\""},{"id":565,"title":"İlim ve İman Dilemek İçin Dua","ref":"Âl-i İmrân Sûresi 3: 18-19","url":"https://quran.com/3/18","ar":"شَهِدَ اللَّـهُ أَنَّهُ لَا إِلَـٰهَ إِلَّا هُوَ وَالْمَلَائِكَةُ وَأُولُو الْعِلْمِ قَائِمًا بِالْقِسْطِ ۚ لَا إِلَـٰهَ إِلَّا هُوَ الْعَزِيزُ الْحَكِيمُ ﴿١٨﴾ إِنَّ الدِّينَ عِندَ اللَّـهِ الْإِسْلَامُ ۗ وَمَا اخْتَلَفَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ الْعِلْمُ بَغْيًا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِآيَاتِ اللَّـهِ فَإِنَّ اللَّـهَ سَرِيعُ الْحِسَابِ ﴿١٩﴾","latin":"Şehidallâhü ennehû lâ ilâhe illâ Hüve vel-melâiketü ve ülül-ilmi kâimen bil-kıst; lâ ilâhe illâ Hüvel-Azîzül-Hakîm. İnned-dîne indallâhil-İslâm; ve mahtelefellezîne ûtül-kitâbe illâ min ba'di mâ câehümül-ilmü bağyen beynehüm; ve men yekfür bi-âyâtillâhi fe-innallâhe serîul-hisâb.","tr":"(18) Allah, kendisinden başka ilah olmadığına şahitlik etti; melekler ve ilim sahipleri de adaletle bunun şahidi oldu. O'ndan başka ilah yoktur; O, Azîz'dir, Hakîm'dir. (19) Şüphesiz Allah katında tek din İslam'dır. Kitap verilenlerin ayrılığa düşmeleri ise, kendilerine ilim geldikten sonra aralarındaki kıskançlık yüzünden oldu. Allah'ın ayetlerini inkâr eden kimse bilsin ki, Allah hesabı çok hızlı görendir.","en":"(18) Allah witnesses that there is no deity except Him, and [so do] the angels and those of knowledge - [that He is] maintaining [creation] in justice. There is no deity except Him, the Exalted in Might, the Wise. (19) Indeed, the religion in the sight of Allah is Islam. And those who were given the Scripture did not differ except after knowledge had come to them - out of jealous animosity between themselves. And whoever disbelieves in the verses of Allah, then indeed, Allah is swift in [taking] account."},{"id":566,"title":"Kara Büyüden Korunma Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 54-56","url":"https://quran.com/7/54","ar":"إِنَّ رَبَّكُمُ اللَّـهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ ۗ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ ۗ تَبَارَكَ اللَّـهُ رَبُّ الْعَالَمِينَ ﴿٥٤﴾ ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً ۚ إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ ﴿٥٥﴾ وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا ۚ إِنَّ رَحْمَتَ اللَّـهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ ﴿٥٦﴾","latin":"İnne Rabbakümüllâhüllezî halakas-semâvâti vel-arda fî sitteti eyyâmin sümmestevâ alel-arş; yüğşîl-leylen-nehâre yatlübühû hasîsen veş-şemse vel-kamere ven-nücûme müsehhârâtim-bi-emrih; elâ lehül-halku vel-emr; tebârekallâhü Rabbül-âlemîn. Üd'û Rabbeküm taderruân ve hufyeten; innehû lâ yühibbül-mütedeîn. Ve lâ tüfsidû fil-ardı ba'de ıslâhihâ ved'ûhü havfen ve tameân; inne rahmetallâhi karîbün minel-muhsinîn.","tr":"(54) Şüphesiz Rabbiniz, gökleri ve yeri altı günde yaratan, ardından arşa kurulan, geceyi gündüze bürüyen -gece durmaksızın gündüzü takip eder- güneşi, ayı ve yıldızları buyruğuna boyun eğdiren Allah'tır. İyi bilin ki, yaratmak da buyurmak da O'na aittir. Âlemlerin Rabbi Allah ne yücedir! (55) Rabbinize yalvara yalvara ve gizlice dua edin; doğrusu O, sınırı aşanları sevmez. (56) Barış ve düzenin kurulmasından sonra yeryüzünde bozgunculuk çıkarmayın. O'na korku ve umut içinde dua edin. Şüphesiz Allah'ın rahmeti iyilik yapanlara yakındır.","en":"(54) Indeed, your Lord is Allah, who created the heavens and earth in six days and then established Himself above the Throne. He covers the night with the day, [another night] chasing it rapidly; and [He created] the sun, the moon, and the stars, subjected by His command. Unquestionably, His is the creation and the command; blessed is Allah, Lord of the worlds. (55) Call upon your Lord in humility and privately; indeed, He does not like transgressors. (56) And cause not corruption upon the earth after its reformation. And invoke Him in fear and aspiration. Indeed, the mercy of Allah is near to the doers of good."},{"id":567,"title":"Cinlerden Korunma Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 117-122","url":"https://quran.com/7/117","ar":"وَأَوْحَيْنَا إِلَىٰ مُوسَىٰ أَنْ أَلْقِ عَصَاكَ ۖ فَإِذَا هِيَ تَلْقَفُ مَا يَأْفِكُونَ ﴿١١٧﴾ فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ ﴿١١٨﴾ فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ ﴿١١٩﴾ وَأُلْقِيَ السَّحَرَةُ سَاجِدِينَ ﴿١٢٠﴾ قَالُوا آمَنَّا بِرَبِّ الْعَالَمِينَ ﴿١٢١﴾ رَبِّ مُوسَىٰ وَهَارُونَ ﴿١٢٢﴾","latin":"Ve evhaynâ ilâ Mûsâ en elkı asâke fe-izâ hiye telkafü mâ ye'fikûn. Fevaka'al-hakkü ve batale mâ kânû ya'melûn. Feğulibû hünâlike venkalabû sâğirîn. Ve ülkiyeş-seharetü sâcidîn. Kâlû âmennâ bi-Rabbil-âlemîn. Rabbi Mûsâ ve Hârûn.","tr":"(117) Musa'ya: 'Asanı bırak' diye vahyettik; o da hemen onların uydurduklarını yutup yok etmeye başladı. (118) Böylece gerçek ortaya çıktı ve onların yaptıkları batıl oldu. (119) Firavun ve adamları orada yenildi ve küçük düştü. (120) Büyücüler hemen secdeye kapandılar. (121) 'Âlemlerin Rabbine iman ettik' dediler. (122) 'Musa'nın ve Harun'un Rabbine.'","en":"(117) And We inspired to Moses, \"Throw your staff,\" and at once it devoured what they were falsifying. (118) So the truth was established, and abolished was what they were doing. (119) And Pharaoh and his people were overcome right there and became debased. (120) And the magicians fell down in prostration [to Allah ]. (121) They said, \"We have believed in the Lord of the worlds, (122) The Lord of Moses and Aaron.\""},{"id":568,"title":"Büyüye Karşı Korunma Duası (Yûnus Sûresi)","ref":"Yûnus Sûresi 10: 81-82","url":"https://quran.com/10/81","ar":"فَلَمَّا أَلْقَوْا قَالَ مُوسَىٰ مَا جِئْتُم بِهِ السِّحْرُ ۖ إِنَّ اللَّـهَ سَيُبْطِلُهُ ۖ إِنَّ اللَّـهَ لَا يُصْلِحُ عَمَلَ الْمُفْسِدِينَ ﴿٨١﴾ وَيُحِقُّ اللَّـهُ الْحَقَّ بِكَلِمَاتِهِ وَلَوْ كَرِهَ الْمُجْرِمُونَ ﴿٨٢﴾","latin":"Felemmâ elkav kâle Mûsâ mâ ci'tüm bihis-sihr; innallâhe se-yübtılüh; innallâhe lâ yuslihü amelel-müfsidîn. Ve yühıkkullâhül-hakka bi-kelimâtihî ve lev kerihal-mücrimûn.","tr":"(81) Onlar büyülerini attıklarında Musa: 'Getirdiğiniz ancak bir büyüdür; Allah onu mutlaka geçersiz kılacaktır. Zira Allah bozguncuların işini düzeltmez' dedi. (82) 'Allah, suçlular istemese de hakkı kelimeleriyle gerçekleştirir.'","en":"(81) And when they had thrown, Moses said, \"What you have brought is [only] magic. Indeed, Allah will expose its worthlessness. Indeed, Allah does not amend the work of corrupters. (82) And Allah will establish the truth by His words, even if the criminals dislike it.\""},{"id":569,"title":"Kara Büyü ve Kötülükten Korunma Duası","ref":"Tâhâ Sûresi 20: 69","url":"https://quran.com/20/69","ar":"وَأَلْقِ مَا فِي يَمِينِكَ تَلْقَفْ مَا صَنَعُوا ۖ إِنَّمَا صَنَعُوا كَيْدُ سَاحِرٍ ۖ وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَىٰ ﴿٦٩﴾","latin":"Ve elkı mâ fî yemînik telkaf mâ saneû; innemâ saneû keydü sâhir; ve lâ yüflihus-sâhiru haysu etâ.","tr":"(69) 'Sağ elindekini bırak; onların yaptıklarını yutup yok etsin. Onların yaptıkları yalnızca bir büyücü hilesidir. Büyücü ise nereye giderse gitsin başarıya ulaşamaz.'","en":"(69) And throw what is in your right hand; it will swallow up what they have crafted. What they have crafted is but the trick of a magician, and the magician will not succeed wherever he is.\""},{"id":570,"title":"Mü'minûn Sûresi'nden Mağfiret Duası","ref":"Mü'minûn Sûresi 23: 115-118","url":"https://quran.com/23/115","ar":"أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَاكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ﴿١١٥﴾ فَتَعَالَى اللَّـهُ الْمَلِكُ الْحَقُّ ۖ لَا إِلَـٰهَ إِلَّا هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ ﴿١١٦﴾ وَمَن يَدْعُ مَعَ اللَّـهِ إِلَـٰهًا آخَرَ لَا بُرْهَانَ لَهُ بِهِ فَإِنَّمَا حِسَابُهُ عِندَ رَبِّهِ ۚ إِنَّهُ لَا يُفْلِحُ الْكَافِرُونَ ﴿١١٧﴾ وَقُل رَّبِّ اغْفِرْ وَارْحَمْ وَأَنتَ خَيْرُ الرَّاحِمِينَ ﴿١١٨﴾","latin":"Efehesibtüm ennemâ halaknaküm abesen ve enneküm ileynâ lâ türceûn. Feteâlellâhül-Melikül-Hakk; lâ ilâhe illâ Hüve Rabbül-Arşil-Kerîm. Ve men yed'u meallâhi ilâhen âhare lâ bürhâne lehû bih; fe-innemâ hisâbühû inde Rabbih; innehû lâ yüflihül-kâfirûn. Ve kul Rabbığfir verham ve Ente hayrür-râhimîn.","tr":"(115) 'Sizi boş yere yarattığımızı ve bize döndürülmeyeceğinizi mi sandınız?' (116) O hâlde gerçek Melik olan Allah çok yücedir. O'ndan başka ilah yoktur. O, şerefli Arş'ın Rabbidir. (117) Kim Allah ile birlikte delili olmayan başka bir ilaha yalvarırsa, onun hesabı ancak Rabbine aittir. Gerçekten kâfirler kurtuluşa eremez. (118) De ki: 'Rabbim, bağışla ve merhamet et; Sen merhametlilerin en hayırlısısın.'","en":"(115) Then did you think that We created you uselessly and that to Us you would not be returned?\" (116) So exalted is Allah, the Sovereign, the Truth; there is no deity except Him, Lord of the Noble Throne. (117) And whoever invokes besides Allah another deity for which he has no proof - then his account is only with his Lord. Indeed, the disbelievers will not succeed. (118) And, [O Muhammad], say, \"My Lord, forgive and have mercy, and You are the best of the merciful.\""},{"id":571,"title":"Cinlerden Korunmak İçin Güçlü Dua (Saffât Sûresi)","ref":"Saffât Sûresi 37: 1-10","url":"https://quran.com/37/1","ar":"وَالصَّافَّاتِ صَفًّا ﴿١﴾ فَالزَّاجِرَاتِ زَجْرًا ﴿٢﴾ فَالتَّالِيَاتِ ذِكْرًا ﴿٣﴾ إِنَّ إِلَـٰهَكُمْ لَوَاحِدٌ ﴿٤﴾ رَّبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا وَرَبُّ الْمَشَارِقِ ﴿٥﴾ إِنَّا زَيَّنَّا السَّمَاءَ الدُّنْيَا بِزِينَةٍ الْكَوَاكِبِ ﴿٦﴾ وَحِفْظًا مِّن كُلِّ شَيْطَانٍ مَّارِدٍ ﴿٧﴾ لَّا يَسَّمَّعُونَ إِلَى الْمَلَإِ الْأَعْلَىٰ وَيُقْذَفُونَ مِن كُلِّ جَانِبٍ ﴿٨﴾ دُحُورًا ۖ وَلَهُمْ عَذَابٌ وَاصِبٌ ﴿٩﴾ إِلَّا مَنْ خَطِفَ الْخَطْفَةَ فَأَتْبَعَهُ شِهَابٌ ثَاقِبٌ ﴿١٠﴾","latin":"Ves-sâffâti saffâ. Fez-zâcirâti zecrâ. Fet-tâliyâti zihrâ. İnne ilâheküm le-Vâhid. Rabbus-semâvâti vel-ardı ve mâ beynehumâ ve Rabbül-meşârik. İnnâ zeyyennâs-semâed-dünyâ bi-zînetil-kevâkib. Ve hıfzam-min külli şeytânin mârid. Lâ yessemmea'ûne ilel-meleil-a'lâ ve yükzefûne min külli cânib. Duhûren ve lehüm azâbün vâsib. İllâ men hatıfel-hatfete fe-etbea'hû şihâbün sâkıb.","tr":"(1) Saf saf dizilenlere andolsun, (2) Haykırarak sevk edenlere, (3) Zikri okuyanlara andolsun ki, (4) Şüphesiz ilahınız birdir, (5) O, göklerin, yerin ve ikisi arasındakilerin Rabbi; doğuların da Rabbidir. (6) Gerçekten Biz, en yakın göğü yıldız süsüyle süsledik, (7) Hem de her inatçı şeytana karşı korudu onu. (8) Onlar artık yüce topluluğu (melekleri) dinleyemezler ve her yönden taşa tutulurlar. (9) Kovulmuş olarak; onlar için sürekli bir azap vardır. (10) Ancak bir söz kapan olursa, delici bir alev onu kovalar.","en":"(1) By those [angels] lined up in rows (2) And those who drive [the clouds] (3) And those who recite the message, (4) Indeed, your God is One, (5) Lord of the heavens and the earth and that between them and Lord of the sunrises. (6) Indeed, We have adorned the nearest heaven with an adornment of stars (7) And as protection against every rebellious devil (8) [So] they may not listen to the exalted assembly [of angels] and are pelted from every side, (9) Repelled; and for them is a constant punishment, (10) Except one who snatches [some words] by theft, but they are pursued by a burning flame, piercing [in brightness]."},{"id":572,"title":"Hidayet ve Mağfiret Duası (Ahkaf Sûresi)","ref":"Ahkâf Sûresi 46: 29-32","url":"https://quran.com/46/29","ar":"وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِّنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنصِتُوا ۖ فَلَمَّا قُضِيَ وَلَّوْا إِلَىٰ قَوْمِهِم مُّنذِرِينَ ﴿٢٩﴾ قَالُوا يَا قَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنزِلَ مِن بَعْدِ مُوسَىٰ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَىٰ طَرِيقٍ مُّسْتَقِيمٍ ﴿٣٠﴾ يَا قَوْمَنَا أَجِيبُوا دَاعِيَ اللَّـهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُم مِّن ذُنُوبِكُمْ وَيُجِرْكُم مِّنْ عَذَابٍ أَلِيمٍ ﴿٣١﴾ وَمَن لَّا يُجِبْ دَاعِيَ اللَّـهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِن دُونِهِ أَوْلِيَاءُ ۚ أُولَـٰئِكَ فِي ضَلَالٍ مُّبِينٍ ﴿٣٢﴾","latin":"Ve iz sarafnâ ileyke neferan minel-cinni yestemiûnel-Kur'âne felemmâ hadarûhü kâlû ensitû felemmâ kudiye vellevü ilâ kavmihim münzirîn. Kâlû yâ kavmenâ innâ semi'nâ kitâben ünzile min ba'di Mûsâ müsaddıkallen-limâ beyne yedeyhi yehdî ilel-hakkı ve ilâ tarîkın müstakîm. Yâ kavmenâ ecîbû dâiyallâhi ve âminû bihî yağfir leküm min zünûbiküm ve yücirküm min azâbin elîm. Ve mel-lâ yücib dâiyallâhi fe-leyse bi-mu'cizin fil-ardı ve leyse lehû min dûnihî evliyâ'; ülâike fî dalâlim-mübîn.","tr":"(29) Hani cinlerden bir grubu, Kur'an'ı dinlemek için sana yönlendirmiştik. Onu dinlemek üzere huzuruna geldiklerinde birbirlerine: 'Susun, dinleyin' dediler. Kur'an okuyup bitirince uyarıcılar olarak kavimlerine döndüler. (30) Dediler ki: 'Ey kavmimiz! Biz, Musa'dan sonra indirilmiş, önceki kitapları doğrulayan ve hakka ve doğru yola ileten bir kitap dinledik. (31) Ey kavmimiz! Allah'ın davetçisine uyun ve ona iman edin ki, Allah günahlarınızı bağışlasın ve sizi elem verici azaptan korusun. (32) Allah'ın davetçisine uymayan, yeryüzünde Allah'ı aciz bırakamaz; Allah'tan başka da dostları olmaz. İşte bunlar apaçık bir sapıklık içindedirler.'","en":"(29) And [mention, O Muhammad], when We directed to you a few of the jinn, listening to the Qur'an. And when they attended it, they said, \"Listen quietly.\" And when it was concluded, they went back to their people as warners. (30) They said, \"O our people, indeed we have heard a [recited] Book revealed after Moses confirming what was before it which guides to the truth and to a straight path. (31) O our people, respond to the Messenger of Allah and believe in him; Allah will forgive for you your sins and protect you from a painful punishment. (32) But he who does not respond to the Caller of Allah will not cause failure [to Him] upon earth, and he will not have besides Him any protectors. Those are in manifest error.\""},{"id":573,"title":"Kötülükten Korunma Duası (Rahmân Sûresi)","ref":"Rahmân Sûresi 55: 33-36","url":"https://quran.com/55/33","ar":"يَا مَعْشَرَ الْجِنِّ وَالْإِنسِ إِنِ اسْتَطَعْتُمْ أَن تَنفُذُوا مِنْ أَقْطَارِ السَّمَاوَاتِ وَالْأَرْضِ فَانفُذُوا ۚ لَا تَنفُذُونَ إِلَّا بِسُلْطَانٍ ﴿٣٣﴾ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٤﴾ يُرْسَلُ عَلَيْكُمَا شُوَاظٌ مِّن نَّارٍ وَنُحَاسٌ فَلَا تَنتَصِرَانِ ﴿٣٥﴾ فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ ﴿٣٦﴾","latin":"Yâ ma'şerel-cinni vel-insi inisteta'tüm en tenfüzû min aktâris-semâvâti vel-ardı fenfüzû; lâ tenfüzûne illâ bi-sultân. Fe-bi-eyyi âlâi Rabbiküma tükezzibân. Yürselü aleyküma şüvâzun min nârin ve nühâsun fe-lâ tentasırân. Fe-bi-eyyi âlâi Rabbiküma tükezzibân.","tr":"(33) Ey cinler ve insanlar topluluğu! Göklerin ve yerin sınırlarını aşmaya gücünüz yetiyorsa, haydi aşın. Allah'ın bir gücü olmadıkça aşamazsınız. (34) O hâlde Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz? (35) Üzerinize kor ateşten alev ve duman salınır; o zaman artık kendinizi koruyamazsınız. (36) O hâlde Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?","en":"(33) O company of jinn and mankind, if you are able to pass beyond the regions of the heavens and the earth, then pass. You will not pass except by authority [from Allah ]. (34) So which of the favors of your Lord would you deny? (35) There will be sent upon you a flame of fire and smoke, and you will not defend yourselves. (36) So which of the favors of your Lord would you deny?"},{"id":574,"title":"Allah'ın İsimleriyle Güç ve Kurtuluş Duası","ref":"Haşr Sûresi 59: 21-24","url":"https://quran.com/59/21","ar":"لَوْ أَنزَلْنَا هَـٰذَا الْقُرْآنَ عَلَىٰ جَبَلٍ لَّرَأَيْتَهُ خَاشِعًا مُّتَصَدِّعًا مِّنْ خَشْيَةِ اللَّـهِ ۚ وَتِلْكَ الْأَمْثَالُ نَضْرِبُهَا لِلنَّاسِ لَعَلَّهُمْ يَتَفَكَّرُونَ ﴿٢١﴾ هُوَ اللَّـهُ الَّذِي لَا إِلَـٰهَ إِلَّا هُوَ ۖ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ ۖ هُوَ الرَّحْمَـٰنُ الرَّحِيمُ ﴿٢٢﴾ هُوَ اللَّـهُ الَّذِي لَا إِلَـٰهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلَامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ ۚ سُبْحَانَ اللَّـهِ عَمَّا يُشْرِكُونَ ﴿٢٣﴾ هُوَ اللَّـهُ الْخَالِقُ الْبَارِئُ الْمُصَوِّرُ ۖ لَهُ الْأَسْمَاءُ الْحُسْنَىٰ ۚ يُسَبِّحُ لَهُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ ﴿٢٤﴾","latin":"Lev enzelna hâzel-Kur'âne alâ cebelin lere-eytehu hâşian müteşaddia min haşyetillâh; ve tilkel-emsâlü nadribühâ lin-nâsi lealehüm yetefekkerûn. Hüvallâhüllezî lâ ilâhe illâ Hüve Âlimül-ğaybi veş-şehâdeti Hüver-Rahmânür-Rahîm. Hüvallâhüllezî lâ ilâhe illâ Hüvel-Melikül-Kuddûsüs-Selâmül-Mü'minül-Müheyminül-Azîzül-Cebbârül-Mütekebbir; Sübhânallâhi ammâ yüşrikûn. Hüvallâhül-Hâlıkul-Bâriül-Musavviru lehül-esmâül-hüsnâ; yüsebbihu lehû mâ fis-semâvâti vel-ard; ve Hüvel-Azîzül-Hakîm.","tr":"(21) Eğer biz bu Kur'an'ı bir dağa indirseydik, Allah'ın korkusundan onun ezilip parçalandığını görürdün. Bu örnekleri insanlar için veriyoruz ki düşünsünler. (22) O, görmediğinizi ve gördüğünüzü bilen Allah'tır; O'ndan başka ilah yoktur. Rahmân'dır, Rahîm'dir. (23) O, kendisinden başka ilah olmayan Allah'tır. Melik'tir, Kuddûs'tur, Selâm'dır, Mü'min'dir, Müheymin'dir, Azîz'dir, Cebbâr'dır, Mütekebbir'dir. Allah, ortak koştuklarından münezzehtir. (24) O, Hâlik'tir, Bâri'dir, Musavvir'dir. En güzel isimler O'nundur. Göklerde ve yerde olanların hepsi O'nu tesbih eder. O, Azîz'dir, Hakîm'dir.","en":"(21) If We had sent down this Qur'an upon a mountain, you would have seen it humbled and coming apart from fear of Allah . And these examples We present to the people that perhaps they will give thought. (22) He is Allah, other than whom there is no deity, Knower of the unseen and the witnessed. He is the Entirely Merciful, the Especially Merciful. (23) He is Allah, other than whom there is no deity, the Sovereign, the Pure, the Perfection, the Bestower of Faith, the Overseer, the Exalted in Might, the Compeller, the Superior. Exalted is Allah above whatever they associate with Him. (24) He is Allah, the Creator, the Inventor, the Fashioner; to Him belong the best names. Whatever is in the heavens and earth is exalting Him. And He is the Exalted in Might, the Wise."},{"id":575,"title":"Cinlerden Korunma Duası (Cin Sûresi)","ref":"Cin Sûresi 72: 1-9","url":"https://quran.com/72/1","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا ﴿١﴾ يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ ۖ وَلَن نُّشْرِكَ بِرَبِّنَا أَحَدًا ﴿٢﴾ وَأَنَّهُ تَعَالَىٰ جَدُّ رَبِّنَا مَا اتَّخَذَ صَاحِبَةً وَلَا وَلَدًا ﴿٣﴾ وَأَنَّهُ كَانَ يَقُولُ سَفِيهُنَا عَلَى اللَّـهِ شَطَطًا ﴿٤﴾ وَأَنَّا ظَنَنَّا أَن لَّن تَقُولَ الْإِنسُ وَالْجِنُّ عَلَى اللَّـهِ كَذِبًا ﴿٥﴾ وَأَنَّهُ كَانَ رِجَالٌ مِّنَ الْإِنسِ يَعُوذُونَ بِرِجَالٍ مِّنَ الْجِنِّ فَزَادُوهُمْ رَهَقًا ﴿٦﴾ وَأَنَّهُمْ ظَنُّوا كَمَا ظَنَنتُمْ أَن لَّن يَبْعَثَ اللَّـهُ أَحَدًا ﴿٧﴾ وَأَنَّا لَمَسْنَا السَّمَاءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَسًا شَدِيدًا وَشُهُبًا ﴿٨﴾ وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ ۖ فَمَن يَسْتَمِعِ الْآنَ يَجِدْ لَهُ شِهَابًا رَّصَدًا ﴿٩﴾","latin":"Bismillâhir-Rahmânir-Rahîm. Kul ûhiye ileyye ennehüsteme'a neferun minel-cinni fe-kâlû innâ semi'nâ Kur'ânen aceben. Yehdî iler-rüşdi fe-âmennâ bihî ve len nüşrike bi-Rabbinâ ehadâ. Ve ennehû teâlâ ceddü Rabbinâ mettehaze sâhibeten ve lâ veledâ. Ve ennehû kâne yekûlü sefîhünâ alellâhi şatatâ. Ve ennâ zanennâ en len tekûlel-insü vel-cinnü alellâhi kezibâ. Ve ennehû kâne ricâlun minel-insi ye'ûzûne bi-ricâlin minel-cinni fe-zâdûhüm rahaká. Ve ennehüm zannû kemâ zanentüm en len yeb'asallâhü ehadâ. Ve ennâ lemeesnâs-semâe fevecednâhâ müli'et haresen şedîden ve şühübâ. Ve ennâ künnâ nak'udü minhâ mekâide lis-sem'i fe-men yestemi'il-âne yecid lehû şihâber rasadâ.","tr":"(1) De ki: 'Cinlerden bir grubun Kur'an'ı dinlediği bana vahyedildi ve onlar şöyle dediler: Gerçekten biz, harika bir Kur'an dinledik. (2) O, doğru yola iletiyor; ona iman ettik. Rabbimize hiçbir zaman ortak koşmayacağız. (3) Ve Rabbimizin şanı yücedir; O, ne bir eş ne de bir çocuk edinmiştir. (4) İçimizdeki akılsız, Allah hakkında aşırı yanlış sözler söylüyordu. (5) Biz de insanların ve cinlerin Allah hakkında asla yalan söylemeyeceğini zannetmiştik. (6) Ama insanlar arasından bazı kimseler, cinlerden bazı kimselere sığınıyordu; bu da onların sapkınlıklarını artırdı. (7) Onlar da sizin zannettiğiniz gibi, Allah'ın hiçbir zaman kimseyi peygamber olarak göndermeyeceğini sandılar. (8) Biz göğe ulaşmaya çalıştık; fakat onu güçlü muhafızlar ve alevlerle dolu bulduk. (9) Biz orada dinlemek için oturuyor idik; ama şimdi kim dinlemek isterse, kendisini bekleyen bir alev bulur.'","en":"(1) Say, [O Muhammad], \"It has been revealed to me that a group of the jinn listened and said, 'Indeed, we have heard an amazing Qur'an. (2) It guides to the right course, and we have believed in it. And we will never associate with our Lord anyone. (3) And [it teaches] that exalted is the nobleness of our Lord; He has not taken a wife or a son (4) And that our foolish one has been saying about Allah an excessive transgression. (5) And we had thought that mankind and the jinn would never speak about Allah a lie. (6) And there were men from mankind who sought refuge in men from the jinn, so they [only] increased them in burden. (7) And they had thought, as you thought, that Allah would never send anyone [as a messenger]. (8) And we have sought [to reach] the heaven but found it filled with powerful guards and burning flames. (9) And we used to sit therein in positions for hearing, but whoever listens now will find a burning flame lying in wait for him."},{"id":578,"title":"Kötü Vesveseden Korunma Duası (Nâs Sûresi)","ref":"Nâs Sûresi 114","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_578.json","ar":"بِسْمِ اللَّـهِ الرَّحْمَـٰنِ الرَّحِيمِ قُلْ أَعُوْذُ بِرَبِّ النَّاسِ ﴿١﴾ مَلِكِ النَّاسِ ﴿٢﴾ إِلَـٰهِ النَّاسِ ﴿٣﴾ مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ ﴿٤﴾ الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ ﴿٥﴾ مِنَ الْجِنَّةِ وَالنَّاسِ ﴿٦﴾","latin":"Bismillâhir-Rahmânir-Rahîm. Kul eûzü bi-Rabbin-nâs. Melikin-nâs. İlâhin-nâs. Min şerril-vesvâsil-hannâs. Ellezî yüvesvisü fî sudûrin-nâs. Minel-cinneti ven-nâs.","tr":"(1) De ki: İnsanların Rabbine sığınırım. (2) İnsanların hükümdarına. (3) İnsanların ilahına. (4) Sinsi vesvesecinin şerrinden. (5) İnsanların göğüslerine vesvese veren. (6) Cinlerden ve insanlardan olan.","en":"(1) Say, \"I seek refuge in the Lord of mankind, (2) The Sovereign of mankind. (3) The God of mankind, (4) From the evil of the retreating whisperer - (5) Who whispers [evil] into the breasts of mankind - (6) From among the jinn and mankind.\""},{"id":579,"title":"Sapıklıktan Korunma Duası (Nisâ Sûresi)","ref":"Nisâ Sûresi 4: 167-173","url":"https://quran.com/4/167","ar":"إِنَّ الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّـهِ قَدْ ضَلُّوا ضَلَالًا بَعِيدًا ﴿١٦٧﴾ إِنَّ الَّذِينَ كَفَرُوا وَظَلَمُوا لَمْ يَكُنِ اللَّـهُ لِيَغْفِرَ لَهُمْ وَلَا لِيَهْدِيَهُمْ طَرِيقًا ﴿١٦٨﴾ إِلَّا طَرِيقَ جَهَنَّمَ خَالِدِينَ فِيهَا أَبَدًا ۚ وَكَانَ ذَٰلِكَ عَلَى اللَّـهِ يَسِيرًا ﴿١٦٩﴾ يَا أَيُّهَا النَّاسُ قَدْ جَاءَكُمُ الرَّسُولُ بِالْحَقِّ مِن رَّبِّكُمْ فَآمِنُوا خَيْرًا لَّكُمْ ۚ وَإِن تَكْفُرُوا فَإِنَّ لِلَّـهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۚ وَكَانَ اللَّـهُ عَلِيمًا حَكِيمًا ﴿١٧٠﴾ يَا أَهْلَ الْكِتَابِ لَا تَغْلُوا فِي دِينِكُمْ وَلَا تَقُولُوا عَلَى اللَّـهِ إِلَّا الْحَقَّ ۚ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللَّـهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَآمِنُوا بِاللَّـهِ وَرُسُلِهِ ۖ وَلَا تَقُولُوا ثَلَاثَةٌ ۚ انتَهُوا خَيْرًا لَّكُمْ ۚ إِنَّمَا اللَّـهُ إِلَـٰهٌ وَاحِدٌ ۖ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ ۘ لَّهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ وَكَفَىٰ بِاللَّـهِ وَكِيلًا ﴿١٧١﴾ لَّن يَسْتَنكِفَ الْمَسِيحُ أَن يَكُونَ عَبْدًا لِّلَّـهِ وَلَا الْمَلَائِكَةُ الْمُقَرَّبُونَ ۚ وَمَن يَسْتَنكِفْ عَنْ عِبَادَتِهِ وَيَسْتَكْبِرْ فَسَيَحْشُرُهُمْ إِلَيْهِ جَمِيعًا ﴿١٧٢﴾ فَأَمَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ فَيُوَفِّيهِمْ أُجُورَهُمْ وَيَزِيدُهُم مِّن فَضْلِهِ ۖ وَأَمَّا الَّذِينَ اسْتَنكَفُوا وَاسْتَكْبَرُوا فَيُعَذِّبُهُمْ عَذَابًا أَلِيمًا وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّـهِ وَلِيًّا وَلَا نَصِيرًا ﴿١٧٣﴾","latin":"İnnellezîne keferû ve saddû an sebîlillâhi kad dallû dalâlen be'îdâ. İnnellezîne keferû ve zalemû lem yekunillâhü li-yağfire lehüm ve lâ li-yehdiyehüm tarîkâ. İllâ tarîka cehenneme hâlidîne fîhâ ebedâ; ve kâne zâlike alallâhi yesîrâ. Yâ eyyühen-nâsü kad câekümer-Rasûlü bil-hakkı mir-Rabbiküm fe-âminû hayran leküm; ve in tekfürû fe-inna lillâhi mâ fis-semâvâti vel-ard; ve kânallâhü Alîmen Hakîmâ. Yâ ehlel-kitâbi lâ tağlû fî dîniküm ve lâ tekûlû alallâhi illel-hakk; innemel-Mesîhu Îsebnu Meryeme Rasûlullâhi ve kelimetühû elkaahâ ilâ Meryeme ve rûhun minh; fe-âminû billâhi ve Rusülihî ve lâ tekûlû selâsehten; intehû hayran leküm; innemallâhü İlâhün Vâhid; Sübhânehu en yekûne lehû veled; lehû mâ fis-semâvâti ve mâ fil-ard; ve kefâ billâhi Vekîlâ. Len yestenkifel-Mesîhu en yekûne abdellillâhi ve lel-melâiketül-mukarrebûn; ve men yestenkif an ibâdetihî ve yestekbir fe-seyahşüruhüm ileyhi cemîâ. Fe-emmelezîne âmenû ve amilûs-sâlihâti fe-yüveffiyhim ücûrehüm ve yezîdühüm min fadlih; ve emmelezînestenkefû vestekberû fe-yüazzibühüm azâben elîmâ ve lâ yecidûne lehüm min dûnillâhi veliyyen ve lâ nasîrâ.","tr":"(167) Şüphesiz inkâr edip Allah yolundan alıkoyanlar gerçekten derin bir sapkınlığa düştüler. (168) Şüphesiz inkâr edip zulmedenler var ya, Allah onları ne bağışlayacak ne de bir yola iletecektir. (169) Ancak ebedi olarak içinde kalacakları cehennem yoluna. Bu, Allah'a kolaydır. (170) Ey insanlar! Resûl, size Rabbinizden gerçeği getirdi; iman edin, bu sizin için hayırlıdır. Eğer inkâr ederseniz, bilin ki göklerde ve yerde olanların hepsi Allah'ındır. Allah her şeyi bilendir, hüküm ve hikmet sahibidir. (171) Ey Ehl-i Kitap! Dininizde sınırı aşmayın ve Allah hakkında gerçekten başkasını söylemeyin. Meryem oğlu Îsâ Mesîh, ancak Allah'ın elçisi ve Meryem'e iletilmiş O'nun kelimesi ve O'ndan bir ruhtur. Allah'a ve elçilerine iman edin. 'Üçtür' demeyin; bundan vazgeçin, bu sizin için daha hayırlıdır. Allah ancak tek bir ilahtır. O'nun çocuğu olmasından münezzehtir. Göklerde ve yerde olanların hepsi O'nundur. Vekil olarak Allah yeter. (172) Mesîh, Allah'ın kulu olmaktan asla çekinmez; yakın melekler de. Kim O'na ibadetten çekinseydi ya da kibirlenirse, Allah onların hepsini huzuruna toplayacaktır. (173) İman edip iyi işler yapanlara Allah, ücretlerini tam verecek ve lütfundan fazlasını da katacaktır. Çekinen ve kibirlenenlere ise acıklı bir azap verecek; Allah dışında kendileri için ne bir dost ne de bir yardımcı bulabileceklerdir.","en":"(167) Indeed, those who disbelieve and avert [people] from the way of Allah have certainly gone far astray. (168) Indeed, those who disbelieve and commit wrong [or injustice] - never will Allah forgive them, nor will He guide them to a path. (169) Except the path of Hell; they will abide therein forever. And that, for Allah, is [always] easy. (170) O Mankind, the Messenger has come to you with the truth from your Lord, so believe; it is better for you. But if you disbelieve - then indeed, to Allah belongs whatever is in the heavens and earth. And ever is Allah Knowing and Wise. (171) O People of the Scripture, do not commit excess in your religion or say about Allah except the truth. The Messiah, Jesus, the son of Mary, was but a messenger of Allah and His word which He directed to Mary and a soul [created at a command] from Him. So believe in Allah and His messengers. And do not say, \"Three\"; desist - it is better for you. Indeed, Allah is but one God. Exalted is He above having a son. To Him belongs whatever is in the heavens and whatever is on the earth. And sufficient is Allah as Disposer of affairs. (172) Never would the Messiah disdain to be a servant of Allah, nor would the angels near [to Him]. And whoever disdains His worship and is arrogant - He will gather them to Himself all together. (173) And as for those who believed and did righteous deeds, He will give them in full their rewards and grant them extra from His bounty. But as for those who disdained and were arrogant, He will punish them with a painful punishment, and they will not find for themselves besides Allah any protector or helper."},{"id":580,"title":"İnatçı Cinlerden Korunma Duası","ref":"Mâide Sûresi 5: 33-34","url":"https://quran.com/5/33","ar":"إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّـهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الْأَرْضِ فَسَادًا أَن يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُم مِّنْ خِلَافٍ أَوْ يُنفَوْا مِنَ الْأَرْضِ ۚ ذَٰلِكَ لَهُمْ خِزْيٌ فِي الدُّنْيَا ۖ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ ﴿٣٣﴾ إِلَّا الَّذِينَ تَابُوا مِن قَبْلِ أَن تَقْدِرُوا عَلَيْهِمْ ۖ فَاعْلَمُوا أَنَّ اللَّـهَ غَفُورٌ رَّحِيمٌ ﴿٣٤﴾","latin":"İnnemâ cezâüllezîne yühâribûnallâhe ve Resûlehû ve yes'avne fil-ardı fesâden en yukattelû ev yüsallebû ev tükatta'a eydîhim ve ercülühüm min hilâfin ev yünfev minel-ard; zâlike lehüm hızyün fid-dünyâ ve lehüm fil-âhireti azâbün azîm. İllellezîne tâbû min kabli en takdirû aleyhim fa'lemû ennallâhe Ğafûrür-Rahîm.","tr":"(33) Allah'a ve Resûlü'ne karşı savaşanların ve yeryüzünde bozgunculuk çıkarmak için çabalayanların cezası; öldürülmeleri, asılmaları ya da el ve ayaklarının çaprazlama kesilmesi yahut yerlerinden sürgün edilmektir. Bu, dünyada onlar için bir rezilliktir; âhirette de onlar için büyük bir azap vardır. (34) Ancak onlara güç yetirmeden önce tövbe edenler bunun dışındadır. Bilin ki Allah çok bağışlayandır, çok merhamet edendir.","en":"(33) Indeed, the penalty for those who wage war against Allah and His Messenger and strive upon earth [to cause] corruption is none but that they be killed or crucified or that their hands and feet be cut off from opposite sides or that they be exiled from the land. That is for them a disgrace in this world; and for them in the Hereafter is a great punishment, (34) Except for those who return [repenting] before you apprehend them. And know that Allah is Forgiving and Merciful."},{"id":581,"title":"Kötü Cinlerden Güvenlik Duası (Enfâl Sûresi)","ref":"Enfâl Sûresi 8: 12","url":"https://quran.com/8/12","ar":"إِذْ يُوحِي رَبُّكَ إِلَى الْمَلَائِكَةِ أَنِّي مَعَكُمْ فَثَبِّتُوا الَّذِينَ آمَنُوا ۚ سَأُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ فَاضْرِبُوا فَوْقَ الْأَعْنَاقِ وَاضْرِبُوا مِنْهُمْ كُلَّ بَنَانٍ ﴿١٢﴾","latin":"İz yûhî Rabbüke ilel-melâiketi ennî meaküm fe-sebbitûllezîne âmenû; se-ülkî fî kulûbillezîne keferûr-ru'be fadribû fevkal-a'nâki vadribû minhüm külle benân.","tr":"(12) Hani Rabbin meleklere şunu vahyediyordu: 'Ben sizinle beraberim; iman edenleri sağlamlaştırın. Ben inkâr edenlerin kalplerine korku salacağım; hemen boyunlarının üstüne vurun ve onların her parmağına vurun.'","en":"(12) [Remember] when your Lord inspired to the angels, \"I am with you, so strengthen those who have believed. I will cast terror into the hearts of those who disbelieved, so strike [them] upon the necks and strike from them every fingertip.\""},{"id":582,"title":"İnatçı Cinlerden Korunma Sûresi (Hicr Sûresi)","ref":"Hicr Sûresi 15: 16-18","url":"https://quran.com/15/16","ar":"وَلَقَدْ جَعَلْنَا فِي السَّمَاءِ بُرُوجًا وَزَيَّنَّاهَا لِلنَّاظِرِينَ ﴿١٦﴾ وَحَفِظْنَاهَا مِن كُلِّ شَيْطَانٍ رَّجِيمٍ ﴿١٧﴾ إِلَّا مَنِ اسْتَرَقَ السَّمْعَ فَأَتْبَعَهُ شِهَابٌ مُّبِينٌ ﴿١٨﴾","latin":"Ve lekad cealnâ fis-semâi bürûcen ve zeyyennâhâ lin-nâzirîn. Ve hafıznâhâ min külli şeytânir-racîm. İllâ menis-terakâs-sem'a fe-etbeahü şihâbün mübîn.","tr":"(16) Gerçekten Biz, gökte burçlar yarattık ve onu seyredenler için süsledik. (17) Onu kovulmuş her şeytandan koruduk. (18) Ancak kulak hırsızlığı yapanlar olur; onu da parlak bir alev takip eder.","en":"(16) And We have placed within the heaven great stars and have beautified it for the observers. (17) And We have protected it from every devil expelled [from the mercy of Allah ] (18) Except one who steals a hearing and is pursued by a clear burning flame."},{"id":583,"title":"İnatçı Cinleri Gidermek İçin Kur'anî Dua (İsrâ Sûresi)","ref":"İsrâ Sûresi 17: 110-111","url":"https://quran.com/17/110","ar":"قُلِ ادْعُوا اللَّـهَ أَوِ ادْعُوا الرَّحْمَـٰنَ ۖ أَيًّا مَّا تَدْعُوا فَلَهُ الْأَسْمَاءُ الْحُسْنَىٰ ۚ وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا ﴿١١٠﴾ وَقُلِ الْحَمْدُ لِلَّـهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ ۖ وَكَبِّرْهُ تَكْبِيرًا ﴿١١١﴾","latin":"Kulid'ullâhe evid'ur-Rahmâne eyyemâ ted'û fe-lehül-esmâül-hüsnâ; ve lâ techerbi-salâtike ve lâ tuhâfit bihâ vebteği beyne zâlike sebîlâ. Ve kulil-Hamdü lillâhillezî lem yettehiz veleden ve lem yekün lehû şerîkün fil-mülki ve lem yekün lehû veliyyün minez-zülli ve kebbirhü tekbîrâ.","tr":"(110) De ki: 'Allah deyin ya da Rahmân deyin; hangisini çağırırsanız çağırın, en güzel isimler O'nundur.' Namazını ne çok yüksek sesle ne de çok kısık sesle kıl; bu ikisi arasında orta bir yol tut. (111) Ve de ki: 'Övgü, çocuk edinmemiş, hükümranlıkta ortağı bulunmayan ve zillet nedeniyle bir veliye muhtaç olmayan Allah'a mahsustur; O'nu büyüklüğüne yakışır bir şekilde yücelt.'","en":"(110) Say, \"Call upon Allah or call upon the Most Merciful. Whichever [name] you call - to Him belong the best names.\" And do not recite [too] loudly in your prayer or [too] quietly but seek between that an [intermediate] way. (111) And say, \"Praise to Allah, who has not taken a son and has had no partner in [His] dominion and has no [need of a] protector out of weakness; and glorify Him with [great] glorification.\""},{"id":584,"title":"İnatçı Cinlerden Korunma Duası (Enbiyâ Sûresi)","ref":"Enbiyâ Sûresi 21: 70","url":"https://quran.com/21/70","ar":"وَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَخْسَرِينَ ﴿٧٠﴾","latin":"Ve erâdû bihî keyden fe-cealnâhümül-ahserîn.","tr":"(70) Ona bir tuzak kurmak istediler; ama Biz onları en büyük kaybedenler yaptık.","en":"(70) And they intended for him harm, but We made them the greatest losers."},{"id":585,"title":"Cinler İçin Cehennem Azabından Korunma Duası","ref":"Hac Sûresi 22: 19-22","url":"https://quran.com/22/19","ar":"هَـٰذَانِ خَصْمَانِ اخْتَصَمُوا فِي رَبِّهِمْ ۖ فَالَّذِينَ كَفَرُوا قُطِّعَتْ لَهُمْ ثِيَابٌ مِّن نَّارٍ يُصَبُّ مِن فَوْقِ رُءُوسِهِمُ الْحَمِيمُ ﴿١٩﴾ يُصْهَرُ بِهِ مَا فِي بُطُونِهِمْ وَالْجُلُودُ ﴿٢٠﴾ وَلَهُم مَّقَامِعُ مِنْ حَدِيدٍ ﴿٢١﴾ كُلَّمَا أَرَادُوا أَن يَخْرُجُوا مِنْهَا مِنْ غَمٍّ أُعِيدُوا فِيهَا وَذُوقُوا عَذَابَ الْحَرِيقِ ﴿٢٢﴾","latin":"Hâzâni hasmânıhtasemû fî Rabbihim felleziyne keferû kutti'at lehüm siyâbün min nârin yusabbü min fevki ru'ûsihimül-hamîm. Yüşharü bihî mâ fî butûnihim vel-cülûd. Ve lehüm mekâmiü min hadîd. Küllemâ erâdû en yahrecû minhâ min ğammin uîdû fîhâ ve zûkû azâbel-harîk.","tr":"(19) Bunlar, Rableri hakkında tartışan iki hasımdır. İnkâr edenlere ateşten giysiler biçilecek, başlarının üstünden kaynar su dökülecektir. (20) Bu kaynar suyla karınlarındakiler ve derileri eritilecektir. (21) Onlar için demir topuzlar vardır. (22) Üzüntüden cehennemden her çıkmak istediklerinde, oraya geri döndürülürler ve 'Yakıcı azabı tadın!' denir.","en":"(19) These are two adversaries who have disputed over their Lord. But those who disbelieved will have cut out for them garments of fire. Poured upon their heads will be scalding water (20) By which is melted that within their bellies and [their] skins. (21) And for [striking] them are maces of iron. (22) Every time they want to get out of Hellfire from anguish, they will be returned to it, and [it will be said], \"Taste the punishment of the Burning Fire!\""},{"id":586,"title":"Cinlerden Korunma Sûresi (Nûr Sûresi)","ref":"Nûr Sûresi 24: 39","url":"https://quran.com/24/39","ar":"وَالَّذِينَ كَفَرُوا أَعْمَالُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَاءً حَتَّىٰ إِذَا جَاءَهُ لَمْ يَجِدْهُ شَيْئًا وَوَجَدَ اللَّـهَ عِندَهُ فَوَفَّاهُ حِسَابَهُ ۗ وَاللَّـهُ سَرِيعُ الْحِسَابِ ﴿٣٩﴾","latin":"Vellezîne keferû a'mâlühüm ke-serâbin bi-kîatin yahsebühüz-zam'ânü mâen hattâ izâ câehü lem yecidhu şey'en ve vecedallâhe indehû fe-veffâhü hisâbeh; vallâhü serîul-hisâb.","tr":"(39) İnkâr edenlerin amelleri ise düzlükteki seraba benzer; susayan onu su zanneder; ama ona varınca hiçbir şey bulamaz; ama Allah'ı huzurunda bulur ve O da onun hesabını tamamen görür. Allah hesabı çok hızlı görendir.","en":"(39) But those who disbelieved - their deeds are like a mirage in a lowland which a thirsty one thinks is water until, when he comes to it, he finds it is nothing but finds Allah before Him, and He will pay him in full his due; and Allah is swift in account."},{"id":587,"title":"İyi Amellerin Allah Tarafından Kabul Edilmesi İçin Dua","ref":"Furkân Sûresi 25: 23","url":"https://quran.com/25/23","ar":"وَقَدِمْنَا إِلَىٰ مَا عَمِلُوا مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَاءً مَّنثُورًا ﴿٢٣﴾","latin":"Ve kadımnâ ilâ mâ amilû min amelin fe-cealnâhü hebâen mensûrâ.","tr":"(23) Onların yaptıkları amellere yöneldik ve onları saçılmış toz zerreleri hâline getirdik.","en":"(23) And We will regard what they have done of deeds and make them as dust dispersed."},{"id":588,"title":"Düşmandan Korunma Duası (Saffât Sûresi)","ref":"Saffât Sûresi 37: 98","url":"https://quran.com/37/98","ar":"فَأَرَادُوا بِهِ كَيْدًا فَجَعَلْنَاهُمُ الْأَسْفَلِينَ ﴿٩٨﴾","latin":"Fe-erâdû bihî keyden fe-cealnâhümül-esfelîn.","tr":"(98) Ona karşı bir tuzak kurmak istediler; ama Biz onları en aşağı olanlar yaptık.","en":"(98) And they intended for him a plan, but We made them the most debased."},{"id":589,"title":"Allah'ın Planına Güvenmek İçin Dua (Mü'min Sûresi)","ref":"Mü'min Sûresi 40: 78","url":"https://quran.com/40/78","ar":"وَلَقَدْ أَرْسَلْنَا رُسُلًا مِّن قَبْلِكَ مِنْهُم مَّن قَصَصْنَا عَلَيْكَ وَمِنْهُم مَّن لَّمْ نَقْصُصْ عَلَيْكَ ۗ وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّـهِ ۚ فَإِذَا جَاءَ أَمْرُ اللَّـهِ قُضِيَ بِالْحَقِّ وَخَسِرَ هُنَالِكَ الْمُبْطِلُونَ ﴿٧٨﴾","latin":"Ve lekad erselne rusülen min kablik minhüm men kasasnâ aleyke ve minhüm mel-lem naksus aleyk; ve mâ kâne li-rasûlin en ye'tiye bi-âyetin illâ bi-iznillâh; fe-izâ câe emrullâhi kudiye bil-hakkı ve hasire hünâlikel-mübtilûn.","tr":"(78) Andolsun, senden önce de peygamberler gönderdik. Onların kiminin kıssasını sana anlattık, kiminin kıssasını anlatmadık. Hiçbir peygamberin Allah'ın izni olmadan bir ayet getirmesi mümkün değildir. Allah'ın emri gelince hak ile hükmolunur ve batılcılar orada kayba uğrar.","en":"(78) And We have already sent messengers before you. Among them are those [whose stories] We have related to you, and among them are those [whose stories] We have not related to you. And it was not for any messenger to bring a sign [or verse] except by permission of Allah . So when the command of Allah comes, it will be concluded in truth, and the falsifiers will thereupon lose [all]."},{"id":590,"title":"Kur'an'dan Hidayet ve Şifa Duası (Fussilet Sûresi)","ref":"Fussilet Sûresi 41: 44","url":"https://quran.com/41/44","ar":"وَلَوْ جَعَلْنَاهُ قُرْآنًا أَعْجَمِيًّا لَّقَالُوا لَوْلَا فُصِّلَتْ آيَاتُهُ ۖ أَأَعْجَمِيٌّ وَعَرَبِيٌّ ۗ قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ ۖ وَالَّذِينَ لَا يُؤْمِنُونَ فِي آذَانِهِمْ وَقْرٌ وَهُوَ عَلَيْهِمْ عَمًى ۚ أُولَـٰئِكَ يُنَادَوْنَ مِن مَّكَانٍ بَعِيدٍ ﴿٤٤﴾","latin":"Ve lev cealnâhü Kur'ânen a'cemiyyen le-kâlû levlâ fussilet âyâtühû ea'cemiyyün ve arabiyyün; kul hüve lillezîne âmenû hüden ve şifâ'; vellezîne lâ yü'minûne fî âzânihim vakrun ve hüve aleyhim amâ; ülâike yünâdevne min mekânin baîd.","tr":"(44) Eğer onu Arapça olmayan bir Kur'an yapsaydık, onlar mutlaka: 'Ayetleri genişçe açıklanmış olsaydı ya! Ne o, Arapça olmayan, ne bu, Arap?' derlerdi. De ki: 'O, iman edenler için bir hidayet ve şifadır.' İnananmayanlara gelince, kulaklarında ağırlık vardır ve Kur'an onlara karşı kördür. Onlar sanki uzak bir yerden sesleniliyormuş gibi çağrılırlar.","en":"(44) And if We had made it a non-Arabic Qur'an, they would have said, \"Why are its verses not explained in detail [in our language]? Is it a foreign [recitation] and an Arab [messenger]?\" Say, \"It is, for those who believe, a guidance and cure.\" And those who do not believe - in their ears is deafness, and it is upon them blindness. Those are being called from a distant place."},{"id":591,"title":"Cehennemden ve Günahlardan Korunma Duası (Duhân Sûresi)","ref":"Duhân Sûresi 44: 43-50","url":"https://quran.com/44/43","ar":"إِنَّ شَجَرَتَ الزَّقُّومِ ﴿٤٣﴾ طَعَامُ الْأَثِيمِ ﴿٤٤﴾ كَالْمُهْلِ يَغْلِي فِي الْبُطُونِ ﴿٤٥﴾ كَغَلْيِ الْحَمِيمِ ﴿٤٦﴾ خُذُوهُ فَاعْتِلُوهُ إِلَىٰ سَوَاءِ الْجَحِيمِ ﴿٤٧﴾ ثُمَّ صُبُّوا فَوْقَ رَأْسِهِ مِنْ عَذَابِ الْحَمِيمِ ﴿٤٨﴾ ذُقْ إِنَّكَ أَنتَ الْعَزِيزُ الْكَرِيمُ ﴿٤٩﴾ إِنَّ هَـٰذَا مَا كُنتُم بِهِ تَمْتَرُونَ ﴿٥٠﴾","latin":"İnne şeceretez-zekkûm. Taâmül-esîm. Kel-mühli yağlî fil-butûn. Ke-ğaylihamîm. Huzûhü fa'tilûhü ilâ sevâil-cahîm. Sümme subbû fevka re'sihî min azâbil-hamîm. Zuk inneke entel-azîzül-kerîm. İnne hâzâ mâ küntüm bihî temterûn.","tr":"(43) Şüphesiz zekkum ağacı, (44) Günahkârın yemeğidir. (45) O, karınlarda erimiş maden gibi kaynar, (46) Kaynar su gibi fokurdar. (47) 'Tutun onu, cehennemin tam ortasına sürükleyin, (48) Sonra başının üstünden kaynar su azabı dökün' denir. (49) 'Tat bakalım! Sen aziz ve şerefli olan kimseydin ya! (50) İşte bu, hakkında şüphe ettiğiniz şeydir.'","en":"(43) Indeed, the tree of zaqqum (44) Is food for the sinful. (45) Like murky oil, it boils within bellies (46) Like the boiling of scalding water. (47) [It will be commanded], \"Seize him and drag him into the midst of the Hellfire, (48) Then pour over his head from the torment of scalding water.\" (49) [It will be said], \"Taste! Indeed, you are the honored, the noble! (50) Indeed, this is what you used to dispute.\""},{"id":592,"title":"Günah ve Kibire Karşı Hidayet Duası (Câsiye Sûresi)","ref":"Câsiye Sûresi 45: 7-8","url":"https://quran.com/45/7","ar":"وَيْلٌ لِّكُلِّ أَفَّاكٍ أَثِيمٍ ﴿٧﴾ يَسْمَعُ آيَاتِ اللَّـهِ تُتْلَىٰ عَلَيْهِ ثُمَّ يُصِرُّ مُسْتَكْبِرًا كَأَن لَّمْ يَسْمَعْهَا ۖ فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ ﴿٨﴾","latin":"Veylün li-külli effâkin esîm. Yesmeû âyâtillâhi tütlâ aleyhi sümme yüsırrü müstekbiren ke-en lem yesmehâ fe-beşşirhü bi-azâbin elîm.","tr":"(7) Büyük yalancı, günahkâr olan herkese yazıklar olsun. (8) Allah'ın ayetlerini okurken işitir; sonra sanki hiç işitmemiş gibi kibirle ısrar eder. İşte onu acıklı bir azapla müjdele.","en":"(7) Woe to every sinful liar (8) Who hears the verses of Allah recited to him, then persists arrogantly as if he had not heard them. So give him tidings of a painful punishment."},{"id":593,"title":"Aile Koruması ve Mağfiret Duası (Tegâbün Sûresi)","ref":"Tegâbün Sûresi 64: 14-16","url":"https://quran.com/64/14","ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ مِنْ أَزْوَاجِكُمْ وَأَوْلَادِكُمْ عَدُوًّا لَّكُمْ فَاحْذَرُوهُمْ ۚ وَإِن تَعْفُوا وَتَصْفَحُوا وَتَغْفِرُوا فَإِنَّ اللَّـهَ غَفُورٌ رَّحِيمٌ ﴿١٤﴾ إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ ۚ وَاللَّـهُ عِندَهُ أَجْرٌ عَظِيمٌ ﴿١٥﴾ فَاتَّقُوا اللَّـهَ مَا اسْتَطَعْتُمْ وَاسْمَعُوا وَأَطِيعُوا وَأَنفِقُوا خَيْرًا لِّأَنفُسِكُمْ ۗ وَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَـٰئِكَ هُمُ الْمُفْلِحُونَ ﴿١٦﴾","latin":"Yâ eyyühellezîne âmenû inne min ezvâciküm ve evlâdiküm adüvven leküm fahzerûhüm; ve in ta'fû ve tasfahû ve tağfirû fe-innallâhe Ğafûrür-Rahîm. İnnemâ emvâlüküm ve evlâdüküm fitneh; vallâhü indehû ecrun azîm. Fettekullâhe mesteta'tüm vasme'û ve etîû ve enfıkû hayren li-enfüsiküm; ve men yûka şühha nefsihî fe-ülâike hümül-müflihûn.","tr":"(14) Ey iman edenler! Eşlerinizden ve çocuklarınızdan size düşman olanlar vardır; onlardan sakının. Ama affeder, hoş görür ve bağışlarsanız, bilin ki Allah çok bağışlayandır, çok merhamet edendir. (15) Mallarınız ve çocuklarınız ancak bir fitnedir (sınavdır). Allah katında ise büyük bir mükâfat vardır. (16) Gücünüz yettiğince Allah'tan korkun; dinleyin, itaat edin ve kendiniz için hayırlı olanı harcayın. Kim nefsinin cimriliğinden korunursa, işte onlar kurtuluşa erenlerin ta kendileridir.","en":"(14) O you who have believed, indeed, among your wives and your children are enemies to you, so beware of them. But if you pardon and overlook and forgive - then indeed, Allah is Forgiving and Merciful. (15) Your wealth and your children are but a trial, and Allah has with Him a great reward. (16) So fear Allah as much as you are able and listen and obey and spend [in the way of Allah ]; it is better for your selves. And whoever is protected from the stinginess of his soul - it is those who will be the successful."},{"id":594,"title":"Zalim İnsanlardan Kurtuluş Duası (Nisâ Sûresi)","ref":"Nisâ Sûresi 4: 75","url":"https://quran.com/4/75","ar":"رَبَّنَا أَخْرِجْنَا مِنْ هَـٰذِهِ الْقَرْيَةِ الظَّالِمِ أَهْلُهَا وَاجْعَل لَّنَا مِن لَّدُنكَ وَلِيًّا وَاجْعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","latin":"Rabbenâ ahricnâ min hâzihil-karyetiz-zâlimi ehlühâ vec'al lenâ min ledünke veliyyâ vec'al lenâ min ledünke nasîrâ.","tr":"Rabbimiz, bizi halkı zalim olan bu şehirden çıkar; katından bize bir dost ver; katından bize bir yardımcı ver!","en":"Our Lord, take us out of this city of oppressive people and appoint for us from Yourself a protector and appoint for us from Yourself a helper?\""},{"id":595,"title":"Zor Zamanlarda Hidayet Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 89","url":"https://quran.com/7/89","ar":"عَلَى اللَّهِ تَوَكَّلْنَا ۚ رَبَّنَا افْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِالْحَقِّ وَأَنتَ خَيْرُ الْفَاتِحِينَ","latin":"Alallâhi tevekkelna; Rabbeneftah beynenâ ve beyne kavminâ bil-hakkı ve Ente Hayrul-Fâtihîn.","tr":"Allah'a tevekkül ettik. Rabbimiz, bizimle kavmimiz arasında hak ile hükmet; Sen hükmedenlerin en hayırlısısın.","en":"Our Lord, decide between us and our people in truth, and You are the best of those who give decision."},{"id":596,"title":"Zalimlerin Elinden Mazlumun Duası (Yûnus Sûresi)","ref":"Yûnus Sûresi 10: 85-86","url":"https://quran.com/10/85","ar":"عَلَى اللَّهِ تَوَكَّلْنَا رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ ﴿٨٥﴾ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ ﴿٨٦﴾","latin":"Alallâhi tevekkelna Rabbenâ lâ tec'alnâ fitneten lil-kavmiz-zâlimîn. Ve neccınâ bi-rahmetike minel-kavmil-kâfirîn.","tr":"(85) Allah'a tevekkül ettik. Rabbimiz, bizi zalim kavme fitne (sınav) yapma. (86) Bizi rahmetinle kâfir kavimden kurtar.","en":"(85) Upon Allah do we rely. Our Lord, make us not [objects of] trial for the wrongdoing people (86) And save us by Your mercy from the disbelieving people."},{"id":597,"title":"Bozgunculuk Yapan İnsanlardan Korunma Duası (Ankebût Sûresi)","ref":"Ankebût Sûresi 29: 30","url":"https://quran.com/29/30","ar":"رَبِّ انصُرْنِي عَلَى الْقَوْمِ الْمُفْسِدِينَ","latin":"Rabbinsurnî alel-kavmil-müfsidîn.","tr":"Rabbim, bozgunculuk çıkaran kavme karşı bana yardım et.","en":"My Lord, support me against the corrupting people."},{"id":599,"title":"Zalimlerden Güvenlik Duası (Kasas Sûresi)","ref":"Kasas Sûresi 28: 21","url":"https://quran.com/28/21","ar":"رَبِّ نَجِّنِي مِنَ الْقَوْمِ الظَّالِمِينَ","latin":"Rabbi neccınî minel-kavmiz-zâlimîn.","tr":"Rabbim, beni zalimler topluluğundan kurtar.","en":"My Lord, save me from the wrongdoing people."},{"id":600,"title":"Ayartmadan Korunma Duası (Yûsuf Sûresi)","ref":"Yûsuf Sûresi 12: 33","url":"https://quran.com/12/33","ar":"رَبِّ ٱلسِّجْنُ أَحَبُّ إِلَىَّ مِمَّا يَدْعُونَنِىٓ إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّى كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ ٱلْجَٰهِلِينَ","latin":"Rabbis-sicnü ehabbu ileyye mimmâ yed'ûnenî ileyh; ve illâ tasrif annî keydehünne asbu ileyhinne ve ekün minel-câhilîn.","tr":"Rabbim, zindan bana onların beni çağırdığı şeyden daha sevgilidir. Onların tuzaklarını benden çevirmezsen, onlara yönelebilir ve cahillerden olabilirim.","en":"My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."},{"id":601,"title":"Ağrı ve Sıkıntıdan Kurtuluş Duası (Enbiyâ Sûresi)","ref":"Enbiyâ Sûresi 21: 83","url":"https://quran.com/21/83","ar":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ","latin":"Ennî messeniyed-durru ve Ente Erhamür-Râhimîn.","tr":"Gerçekten bana sıkıntı dokundu; Sen merhametlilerin en merhametlisisin.","en":"Indeed, adversity has touched me, and you are the Most Merciful of the merciful."},{"id":602,"title":"Ailenin Zararlı Eylemlerden Korunma Duası","ref":"Şuarâ Sûresi 26: 169","url":"https://quran.com/26/169","ar":"رَبِّ نَجِّنِي وَأَهْلِي مِمَّا يَعْمَلُونَ","latin":"Rabbi neccınî ve ehlî mimmâ ya'melûn.","tr":"Rabbim, beni ve ailemi onların yaptıklarının sonucundan kurtar.","en":"My Lord, save me and my family from [the consequence of] what they do."},{"id":603,"title":"Sıkıntı Zamanlarında Yardım Duası (Kamer Sûresi)","ref":"Kamer Sûresi 54: 10","url":"https://quran.com/54/10","ar":"أَنِّي مَغْلُوبٌ فَانتَصِرْ","latin":"Ennî mağlûbun fantasır.","tr":"Gerçekten ben mağlup oldum; yardım et.","en":"Indeed, I am overpowered, so help."},{"id":604,"title":"Mağfiret Duası (Kasas Sûresi)","ref":"Kasas Sûresi 28: 16","url":"https://quran.com/28/16","ar":"رَبِّ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي","latin":"Rabbi innî zalemtü nefsî fağfir lî.","tr":"Rabbim, gerçekten ben kendime zulmettim; beni bağışla.","en":"My Lord, indeed I have wronged myself, so forgive me"},{"id":606,"title":"Sâd Sûresi'nden Mağfiret Duası","ref":"Sâd Sûresi 38: 35","url":"https://quran.com/38/35","ar":"رَبِّ ٱغْفِرْ لِى","latin":"Rabbığfir lî.","tr":"Rabbim, beni bağışla.","en":"My Lord, forgive me"},{"id":607,"title":"Müslüman Aile ve Hidayet Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 128","url":"https://quran.com/2/128","ar":"رَبَّنَا وَاجْعَلْنَا مُسْلِمَيْنِ لَكَ وَمِن ذُرِّيَّتِنَا أُمَّةً مُّسْلِمَةً لَّكَ وَأَرِنَا مَنَاسِكَنَا وَتُبْ عَلَيْنَا ۖ إِنَّكَ أَنتَ التَّوَّابُ الرَّحِيمُ","latin":"Rabbenâ vec'alnâ müslimeyni leke ve min zürriyyetinâ ümmeten müslimeten leke ve erinâ menâsikena ve tüb aleynâ inneke Ente't-Tevvâbür-Rahîm.","tr":"Rabbimiz! Bizi Sana boyun eğen Müslümanlar kıl ve soyumuzdan da Sana boyun eğen bir ümmet yetiştir; ibadet yerlerimizi bize göster ve tövbemizi kabul et; şüphesiz Sen tövbeleri çok kabul edensin, çok merhamet edensin.","en":"Our Lord! Make of us Muslims, bowing to Thy (Will), and of our progeny a people Muslim, bowing to Thy (will); and show us our place for the celebration of (due) rites; and turn unto us (in Mercy); for Thou art the Oft-Returning, Most Merciful"},{"id":608,"title":"Bağışlanma ve Rahmet Dilemek İçin Dua (Mü'minûn Sûresi)","ref":"Mü'minûn Sûresi 23: 109","url":"https://quran.com/23/109","ar":"رَبَّنَا آمَنَّا فَاغْفِرْ لَنَا وَارْحَمْنَا وَأَنتَ خَيْرُ الرَّاحِمِينَ","latin":"Rabbenâ âmennâ fağfir lenâ verhamnâ ve Ente Hayrür-Râhimîn.","tr":"Rabbimiz, iman ettik; bizi bağışla ve bize merhamet et; Sen merhametlilerin en hayırlısısın.","en":"Our Lord, we have believed, so forgive us and have mercy upon us, and You are the best of the merciful.'"},{"id":610,"title":"Kardeşler İçin Mağfiret Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 151","url":"https://quran.com/7/151","ar":"رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنَا فِي رَحْمَتِكَ ۖ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","latin":"Rabbığfir lî ve li-ehî ve edhılnâ fî rahmetike ve Ente Erhamür-Râhimîn.","tr":"Rabbim, beni ve kardeşimi bağışla; bizi rahmetine al; Sen merhametlilerin en merhametlisisin.","en":"My Lord, forgive me and my brother and admit us into Your mercy, for You are the most merciful of the merciful."},{"id":611,"title":"İtaat ve Mağfiret Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 285","url":"https://quran.com/2/285","ar":"سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ","latin":"Semia'nâ ve eta'nâ ğufrâneke Rabbenâ ve ileykel-masîr.","tr":"İşittik ve itaat ettik. Ey Rabbimiz, bağışlamanı isteriz; dönüş sanadır.","en":"We hear and we obey. [We seek] Your forgiveness, our Lord, and to You is the [final] destination."},{"id":612,"title":"Mağfiret ve Ateşten Korunma Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 16","url":"https://quran.com/3/16","ar":"رَبَّنَا إِنَّنَا آمَنَّا فَاغْفِرْ لَنَا ذُنُوبَنَا وَقِنَا عَذَابَ النَّارِ","latin":"Rabbenâ innenâ âmennâ fağfir lenâ zunûbenâ ve kınâ azâben-nâr.","tr":"Rabbimiz, biz iman ettik; günahlarımızı bağışla ve bizi ateşin azabından koru.","en":"Our Lord, indeed we have believed, so forgive us our sins and protect us from the punishment of the Fire"},{"id":613,"title":"Zor Zamanlarda Mağfiret ve Güç Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 147","url":"https://quran.com/3/147","ar":"رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","latin":"Rabbenağfir lenâ zunûbenâ ve isrâfenâ fî emrinâ ve sebbit akdâmenâ vensurnâ alel-kavmil-kâfirîn.","tr":"Rabbimiz, günahlarımızı ve işlerimizdeki aşırılıklarımızı bağışla; ayaklarımızı sağlamlaştır ve kâfirler topluluğuna karşı bize zafer ver.","en":"Our Lord, forgive us our sins and the excess [committed] in our affairs and plant firmly our feet and give us victory over the disbelieving people."},{"id":614,"title":"Mağfiret ve Rahmet Dileme Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 23","url":"https://quran.com/7/23","ar":"رَبَّنَا ظَلَمْنَا أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ الْخَاسِرِينَ","latin":"Rabbenâ zalemna enfüsenâ ve illam tağfir lenâ ve terhamnâ lenekûnenne minel-hâsirîn.","tr":"Rabbimiz, biz kendimize zulmettik. Eğer bizi bağışlamaz ve bize merhamet etmezsen, kesinlikle hüsrana uğrayanlardan oluruz.","en":"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers."},{"id":615,"title":"İlim ve Mağfiret Duası (Hûd Sûresi)","ref":"Hûd Sûresi 11: 47","url":"https://quran.com/11/47","ar":"رَبِّ إِنِّي أَعُوْذُ بِكَ أَنْ أَسْأَلَكَ مَا لَيْسَ لِي بِهِ عِلْمٌ ۖ وَإِلَّا تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِينَ","latin":"Rabbi innî eûzü bike en es'eleke mâ leyse lî bihî ilm; ve illâ tağfir lî ve terhamnî ekün minel-hâsirîn.","tr":"Rabbim, hakkında bilgim olmayan şeyi Senden istemekten Sana sığınırım. Eğer beni bağışlamaz ve bana merhamet etmezsen, hüsrana uğrayanlardan olurum.","en":"My Lord, I seek refuge in You from asking that of which I have no knowledge. And unless You forgive me and have mercy upon me, I will be among the losers."},{"id":616,"title":"Mağfiret ve Müminler Arasında Birlik Duası","ref":"Haşr Sûresi 59: 10","url":"https://quran.com/59/10","ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ","latin":"Rabbenağfir lenâ ve li-ihvâninalleżîne sebekûnâ bil-îmâni ve lâ tec'al fî kulûbinâ ğıllen lilleżîne âmenû Rabbenâ inneke Ra'ûfür-Rahîm.","tr":"Rabbimiz, bizi ve imanda bizden önce geçmiş olan kardeşlerimizi bağışla; kalbimizde iman edenlere karşı hiçbir kin bırakma. Rabbimiz, şüphesiz Sen çok şefkatlisin, çok merhametlisin.","en":"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."},{"id":618,"title":"Rahmet, Mağfiret ve Cennet Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 191-194","url":"https://quran.com/3/191","ar":"رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ﴿١٩١﴾ رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ﴿١٩٢﴾ رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا ۚ رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ﴿١٩٣﴾ رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ﴿١٩٤﴾","latin":"Rabbenâ mâ halakte hâzâ bâtılan Sübhâneke fekınâ azâben-nâr. Rabbenâ inneke men tüdhilin-nâre fekad ahzeytehû ve mâ liz-zâlimîne min ensâr. Rabbenâ innenâ semi'nâ münâdiyen yünâdî lil-îmâni en âminû bi-Rabbiküm fe-âmennâ; Rabbenâ fağfir lenâ zunûbenâ ve keffir annâ seyyiâtinâ ve teveffenâ meal-ebrâr. Rabbenâ ve âtinâ mâ veadtenâ alâ rusülike ve lâ tühnizne yevmel-kıyâmeh; inneke lâ tühlifül-mî'âd.","tr":"(191) Rabbimiz, Sen bunu boşuna yaratmadın. Seni tenzih ederiz; bizi ateşin azabından koru. (192) Rabbimiz, şüphesiz Sen kimi ateşe sokarsan onu rezil etmiş olursun; zalimlerin hiçbir yardımcısı yoktur. (193) Rabbimiz, biz imanı çağıran bir davetçinin 'Rabbinize iman edin' diye çağırdığını işittik ve iman ettik. Rabbimiz, günahlarımızı bağışla, kötülüklerimizi ört ve bizi iyilerle birlikte vefat ettir. (194) Rabbimiz, elçilerin aracılığıyla bize vadettiğini bize ver; kıyamet gününde bizi rezil etme. Şüphesiz Sen vaadinden dönmezsin.","en":"(191) Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire (192) Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers. (193) Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed. Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous. (194) Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\""},{"id":619,"title":"Doğruluk ve Cennet Duası (Şuarâ Sûresi)","ref":"Şuarâ Sûresi 26: 83-85","url":"https://quran.com/26/83","ar":"رَبِّ هَبْ لِي حُكْمًا وَأَلْحِقْنِي بِالصَّالِحِينَ ﴿٨٣﴾ وَاجْعَل لِّي لِسَانَ صِدْقٍ فِي الْآخِرِينَ ﴿٨٤﴾ وَاجْعَلْنِي مِن وَرَثَةِ جَنَّةِ النَّعِيمِ ﴿٨٥﴾","latin":"Rabbi heb lî hükmen ve elhıknî bis-sâlihîn. Vec'al lî lisâne sıdkın fil-âhirîn. Vec'alnî min vereseti cennetin-na'îm.","tr":"(83) Rabbim, bana hikmet ver ve beni salihlerle birleştir. (84) Sonraki nesiller arasında bana dürüstlükle anılan bir dil (güzel bir nam) nasip et. (85) Beni Naîm cennetinin mirasçılarından kıl.","en":"(83) \"My Lord, grant me authority and join me with the righteous. (84) And grant me a reputation of honor among later generations.(85) And place me among the inheritors of the Garden of Pleasure."},{"id":620,"title":"Rezil Olmaktan Korunma Duası (Şuarâ Sûresi)","ref":"Şuarâ Sûresi 26: 87-89","url":"https://quran.com/26/87","ar":"وَلَا تُخْزِنِي يَوْمَ يُبْعَثُونَ ﴿٨٧﴾ يَوْمَ لَا يَنفَعُ مَالٌ وَلَا بَنُونَ ﴿٨٨﴾ إِلَّا مَنْ أَتَى اللَّـهَ بِقَلْبٍ سَلِيمٍ ﴿٨٩﴾","latin":"Ve lâ tühnizni yevme yüb'asûn. Yevme lâ yenfe'u mâlün ve lâ benûn. İllâ men etallâhe bikalbın selîm.","tr":"(87) Diriltildikleri gün beni rezil etme. (88) O gün ki ne mal fayda verir ne de evlatlar. (89) Ancak Allah'a kalb-i selim (temiz bir kalp) ile gelenler (kurtulur).","en":"(87) And do not disgrace me on the Day they are [all] resurrected (88) The Day when there will not benefit [anyone] wealth or children (89) But only one who comes to Allah with a sound heart."},{"id":621,"title":"Allah'tan Yardım ve Mağfiret Dileme Duası (Mümtehine Sûresi)","ref":"Mümtehine Sûresi 60: 4-5","url":"https://quran.com/60/4","ar":"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ ﴿٤﴾ رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ﴿٥﴾","latin":"Rabbenâ aleyke tevekkelnâ ve ileyke enebnâ ve ileykelmesîr. Rabbenâ lâ tec'alnâ fitneten lilleżîne keferû vağfir lenâ Rabbenâ inneke Entel-azîzül-hakîm.","tr":"(4) Rabbimiz, Sana dayandık, Sana yöneldik ve dönüş Sanadır. (5) Rabbimiz, bizi kâfirler için bir fitne (azap aracı) kılma; bizi bağışla Rabbimiz. Şüphesiz Sen Azîz'sin, Hakîm'sin.","en":"(4) Our Lord, upon You we have relied, and to You we have returned, and to You is the destination. (5) Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."},{"id":622,"title":"Nûr ve Mağfiret Duası (Tahrîm Sûresi)","ref":"Tahrîm Sûresi 66: 8","url":"https://quran.com/66/8","ar":"رَبَّنَا أَتْمِمْ لَنَا نُورَنَا وَاغْفِرْ لَنَا ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","latin":"Rabbenâ etmim lenâ nûrenâ vağfir lenâ inneke alâ külli şey'in kadîr.","tr":"Rabbimiz, bizim için nurumuzu tamamla ve bizi bağışla. Şüphesiz Sen her şeye kadirsin.","en":"Our Lord, perfect for us our light and forgive us. Indeed, You are over all things competent."},{"id":623,"title":"Nesil Duası (Enbiyâ Sûresi)","ref":"Enbiyâ Sûresi 21: 89","url":"https://quran.com/21/89","ar":"رَبِّ لَا تَذَرْنِي فَرْدًا وَأَنتَ خَيْرُ الْوَارِثِينَ","latin":"Rabbi lâ tezernî ferden ve Ente Hayrul-vârisîn.","tr":"Rabbim, beni tek başıma (vârissiz) bırakma; Sen vârislerin en hayırlısısın.","en":"My Lord, do not leave me alone [with no heir], while you are the best of inheritors."},{"id":626,"title":"Zorluklardan Kurtuluş Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 286","url":"https://quran.com/2/286","ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","latin":"Rabbenâ lâ tüâhiznâ in nesînâ ev ahta'nâ; Rabbenâ ve lâ tahmil aleynâ ısran kemâ hameltehu alellezîne min kablinâ; Rabbenâ ve lâ tühammilnâ mâ lâ tâkate lenâ bih; va'fü annâ vağfir lenâ verhamnâ; Ente Mevlânâ fensurnâ alel-kavmil-kâfirîn.","tr":"Rabbimiz, unutur ya da yanılırsak bizi sorumlu tutma. Rabbimiz, bizden öncekilere yüklediğin gibi bize de ağır yük yükleme. Rabbimiz, güç yetiremeyeceğimiz şeyleri bize taşıtma. Bizi affet, bizi bağışla, bize merhamet et. Sen bizim Mevlâmızsın; kâfirler topluluğuna karşı bize yardım et.","en":"Our Lord, do not impose blame upon us if we have forgotten or erred. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."},{"id":628,"title":"İman ve Kur'ân'da Şahitlik Duası","ref":"Mâide Sûresi 5: 83","url":"https://quran.com/5/83","ar":"رَبَّنَا آمَنَّا فَاكْتُبْنَا مَعَ الشَّاهِدِينَ","latin":"Rabbenâ âmennâ faktübnâ meaş-şâhidîn.","tr":"Rabbimiz, iman ettik; bizi şahitler arasına yaz.","en":"Our Lord, we have believed, so register us among the witnesses."},{"id":630,"title":"Zor Zamanlarda Sabır Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 126","url":"https://quran.com/7/126","ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ","latin":"Rabbenâ efrığ aleynâ sabren ve teveffenâ müslimîn.","tr":"Rabbimiz, üzerimize sabır yağdır ve bizi Müslümanlar olarak (Sana teslim olmuş hâlde) vefat ettir.","en":"Our Lord, pour upon us patience and let us die as Muslims [in submission to You]."},{"id":631,"title":"Hidayet ve Mağfiret Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 155-156","url":"https://quran.com/7/155","ar":"رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّايَ ۖ أَتُهْلِكُنَا بِمَا فَعَلَ السُّفَهَاءُ مِنَّا ۖ إِنْ هِيَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَاءُ وَتَهْدِي مَن تَشَاءُ ۖ أَنتَ وَلِيُّنَا فَاغْفِرْ لَنَا وَارْحَمْنَا ۖ وَأَنتَ خَيْرُ الْغَافِرِينَ ﴿١٥٥﴾ وَاكْتُبْ لَنَا فِي هَـٰذِهِ الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ إِنَّا هُدْنَا إِلَيْكَ ۚ ﴿١٥٦﴾","latin":"Rabbi lev şi'te ehlekteküm min kablu ve iyyây; etühlikunâ bimâ fe'ales-süfehâü minnâ; in hiye illâ fitnetüke tüdillu bihâ men teşâü ve tahdî men teşâü; Ente veliyyünâ fağfir lenâ verhamnâ ve Ente Hayrul-ğâfirîn. Vektüb lenâ fî hâzihid-dünyâ haseneten ve fil-âhireti innâ hüdnâ ileyk.","tr":"(155) Rabbim, dileseydin onları ve beni daha önce helâk ederdin. İçimizdeki akılsızların yaptıkları yüzünden bizi helâk mi edeceksin? Bu, ancak Senin fitnendir (sınavındır); onunla dilediğini saptırır, dilediğini hidayete erdirirsin. Sen bizim Velîmizsin; bizi bağışla, bize merhamet et; Sen bağışlayanların en hayırlısısın. (156) Bu dünyada ve âhirette bize iyilik yaz; çünkü biz Sana yöneldik.","en":"(155) My Lord, if You had willed, You could have destroyed them before and me [as well]. Would You destroy us for what the foolish among us have done? This is not but Your trial by which You send astray whom You will and guide whom You will. You are our Protector, so forgive us and have mercy upon us; and You are the best of forgivers. (156) And decree for us in this world [that which is] good and [also] in the Hereafter; indeed, we have turned back to You."},{"id":632,"title":"Zor Zamanlarda Güç Duası (Meryem Sûresi)","ref":"Meryem Sûresi 19: 4","url":"https://quran.com/19/4","ar":"رَبِّ إِنِّى وَهَنَ الْعَظْمُ مِنِّى وَاشْتَعَلَ الرَّأْسُ شَيْبًا وَلَمْ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيًّا","latin":"Rabbi innî vehenel-azmu minnî veşte'aler-re'sü şeybâ ve lem ekün bi-düâike Rabbi şakiyyâ.","tr":"Rabbim, şüphesiz kemiklerim zayıfladı, başım ak saçla doldu; Rabbim, Sana dua etmekle hiçbir zaman mutsuz olmadım.","en":"My Lord, indeed my bones have weakened, and my head has filled with white, and never have I been in my supplication to You, my Lord, unhappy."},{"id":633,"title":"Tevbe ve Koruma Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi 40: 7","url":"https://quran.com/40/7","ar":"رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَّحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ","latin":"Rabbenâ vesi'te külle şey'in rahmeten ve ilmen fağfir lilleżîne tâbû vettebe'û sebîleke ve kıhim azâbel-cahîm.","tr":"Rabbimiz, her şeyi rahmet ve ilimle kuşattın; tevbe edenleri ve Senin yoluna uyanları bağışla, onları cehennem azabından koru.","en":"Our Lord, You have encompassed all things in mercy and knowledge, so forgive those who have repented and followed Your way and protect them from the punishment of Hellfire."},{"id":634,"title":"Zalimlere Yardım Etmeme Duası (Kasas Sûresi)","ref":"Kasas Sûresi 28: 17","url":"https://quran.com/28/17","ar":"رَبِّ بِمَا أَنْعَمْتَ عَلَيَّ فَلَنْ أَكُونَ ظَهِيرًا لِّلْمُجْرِمِينَ","latin":"Rabbi bimâ en'amte aleyye felen ekûne zahîral-lil-mücrımîn.","tr":"Rabbim, bana lütfettiğin nimet hakkı için asla günahkârlara arka çıkmam.","en":"My Lord, for the favor You bestowed upon me, I will never be an assistant to the criminals."},{"id":638,"title":"Saygınlık ve Şeref Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 26","url":"https://quran.com/3/26","ar":"اللَّـهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ ۖ بِيَدِكَ الْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ","latin":"Allâhümme Mâlikel-mülki tü'til-mülke men teşâü ve tenziul-mülke mimmen teşâü ve tüizzü men teşâü ve tüzillü men teşâü biyadikel-hayr; inneke alâ külli şey'in kadîr.","tr":"Allâh'ım, mülkün sahibi! Dilediğine mülk verirsin, dilediğinden mülkü çekip alırsın; dilediğini yüceltir, dilediğini alçaltırsın. Her iyilik Senin elindedir. Şüphesiz Sen her şeye kadirsin.","en":"O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is [all] good. Indeed, You are over all things competent."},{"id":639,"title":"Gerçek Müminler ve Şahitler Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 53","url":"https://quran.com/3/53","ar":"رَبَّنَا آمَنَّا بِمَا أَنزَلْتَ وَاتَّبَعْنَا الرَّسُولَ فَاكْتُبْنَا مَعَ الشَّاهِدِينَ","latin":"Rabbenâ âmennâ bimâ enzelte vetteba'ner-Rasûle faktübnâ meaş-şâhidîn.","tr":"Rabbimiz, indirdiğine iman ettik ve Resûl'e uyduk; bizi şahitler arasına yaz.","en":"Our Lord, we have believed in what You revealed and have followed the messenger, so register us among the witnesses [to truth]."},{"id":641,"title":"Başarı ve Doğruluk Duası (İsrâ Sûresi)","ref":"İsrâ Sûresi 17: 80","url":"https://quran.com/17/80","ar":"رَّبِّ أَدْخِلْنِي مُدْخَلَ صِدْقٍ وَأَخْرِجْنِي مُخْرَجَ صِدْقٍ وَاجْعَل لِّي مِن لَّدُنكَ سُلْطَانًا نَّصِيرًا","latin":"Rabbi edhılnî müdhale sıdkın ve ahricnî muhrace sıdkın vec'al lî min ledünke sultânen nasîrâ.","tr":"Rabbim, beni (girdiğim her yere) doğrulukla girdir, (çıktığım her yerden) doğrulukla çıkar; katından bana yardımcı bir güç ver.","en":"My Lord, cause me to enter a sound entrance and to exit a sound exit and grant me from Yourself a supporting authority."},{"id":642,"title":"Özgüven ve Konuşma Duası (Tâhâ Sûresi)","ref":"Tâhâ Sûresi 20: 25-28","url":"https://quran.com/20/25","ar":"رَبِّ اشْرَحْ لِي صَدْرِي ﴿٢٥﴾ وَيَسِّرْ لِي أَمْرِي ﴿٢٦﴾ وَاحْلُلْ عُقْدَةً مِّن لِّسَانِي ﴿٢٧﴾ يَفْقَهُوا قَوْلِي ﴿٢٨﴾","latin":"Rabbişrah lî sadrî. Ve yessir lî emrî. Vahlül ukdeten min lisânî. Yefkahû kavlî.","tr":"(25) Rabbim, göğsümü aç (genişlet). (26) İşimi bana kolaylaştır. (27) Dilimden düğümü çöz. (28) Ki sözümü anlasınlar.","en":"(25) My Lord, expand for me my breast [with assurance] (26) And ease for me my task (27) And untie the knot from my tongue (28) That they may understand my speech."},{"id":644,"title":"Biri Hakaret Ettiğinde Kur'ânî Dua (Enbiyâ Sûresi)","ref":"Enbiyâ Sûresi 21: 112","url":"https://quran.com/21/112","ar":"رَبِّ احْكُم بِالْحَقِّ ۗ وَرَبُّنَا الرَّحْمَـٰنُ الْمُسْتَعَانُ عَلَىٰ مَا تَصِفُونَ","latin":"Rabbih-küm bil-hak; ve Rabbuner-Rahmânül-müstea'nü alâ mâ tasifûn.","tr":"Rabbim, aramızda hak ile hükmet. Rabbimiz, söylediklerinize karşı yardım istenen Rahman'dır.","en":"My Lord, judge [between us] in truth. And our Lord is the Most Merciful, the one whose help is sought against that which you describe."},{"id":645,"title":"Şeytandan Korunma İçin Güçlü Kur'ânî Dua (Mü'minûn Sûresi)","ref":"Mü'minûn Sûresi 23: 97-98","url":"https://quran.com/23/97","ar":"رَّبِّ أَعُوْذُ بِكَ مِنْ هَمَزَاتِ الشَّيَاطِينِ ﴿٩٧﴾ وَأَعُوْذُ بِكَ رَبِّ أَن يَحْضُرُونِ ﴿٩٨﴾","latin":"Rabbi eûzü bike min hemezâtiş-şeyâtîn. Ve eûzü bike Rabbi en yahdhurûn.","tr":"(97) Rabbim, şeytanların vesveselerinden Sana sığınırım. (98) Rabbim, onların yanımda bulunmasından da Sana sığınırım.","en":"(97)My Lord, I seek refuge in You from the incitements of the devils, (98) And I seek refuge in You, my Lord, lest they be present with me."},{"id":646,"title":"Cehennem Azabından Korunma Duası (Furkân Sûresi)","ref":"Furkân Sûresi 25: 65-66","url":"https://quran.com/25/65","ar":"رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا ﴿٦٥﴾ إِنَّهَا سَاءَتْ مُسْتَقَرًّا وَمُقَامًا ﴿٦٦﴾","latin":"Rabbenasrif annâ azâbe cehenneme inne azâbehâ kâne ğarâmâ. İnnehâ sâet müstekaren ve mükâmâ.","tr":"(65) Rabbimiz, cehennem azabını bizden uzaklaştır; şüphesiz onun azabı süregelen bir belâdır. (66) O, gerçekten ne kötü bir konak ve ne kötü bir ikametgâhtır.","en":"(65)Our Lord, avert from us the punishment of Hell. Indeed, its punishment is ever adhering (66) Indeed, it is evil as a settlement and residence."},{"id":648,"title":"İyi Amellerin Kabulü İçin Dua (Bakara Sûresi)","ref":"Bakara Sûresi 2: 127","url":"https://quran.com/2/127","ar":"رَبَّنَا تَقَبَّلْ مِنَّا ۖ إِنَّكَ أَنتَ السَّمِيعُ الْعَلِيمُ","latin":"Rabbenâ tekabbel minnâ inneke Entes-Semî'ul-alîm.","tr":"Rabbimiz, bunu bizden kabul et. Şüphesiz Sen Semi'sin, Alîm'sin.","en":"Our Lord, accept [this] from us. Indeed You are the Hearing, the Knowing."},{"id":649,"title":"Namaz Kılmak İçin Güçlü Dua (İbrâhîm Sûresi)","ref":"İbrâhîm Sûresi 14: 40","url":"https://quran.com/14/40","ar":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِن ذُرِّيَّتِي ۚ رَبَّنَا وَتَقَبَّلْ دُعَاءِ","latin":"Rabbic'alnî mükîmes-salâti ve min zürriyyetî Rabbenâ ve tekabbel düâ.","tr":"Rabbim, beni ve neslimden olanları namazı gereği gibi kılanlardan eyle. Rabbimiz, duamı kabul et.","en":"My Lord, make me an establisher of prayer, and [many] from my descendants. Our Lord, and accept my supplication."},{"id":650,"title":"Salih Evlat Duası (Sâffât Sûresi)","ref":"Sâffât Sûresi 37: 100","url":"https://quran.com/37/100","ar":"رَبِّ هَبْ لِى مِنَ الصّٰلِحِينَ","latin":"Rabbi heb lî mines-sâlihîn.","tr":"Rabbim, bana salihlerden (bir evlat) bağışla.","en":"My Lord, grant me [a child] from among the righteous."},{"id":654,"title":"Allah'tan Hidayet Dileme Duası (Kasas Sûresi)","ref":"Kasas Sûresi 28: 22","url":"https://quran.com/28/22","ar":"عَسَىٰ رَبِّي أَن يَهْدِيَنِي سَوَاءَ السَّبِيلِ","latin":"Asâ Rabbî en yehdiyenî sevâes-sebîl.","tr":"Umarım Rabbim beni doğru yola iletir.","en":"Perhaps my Lord will guide me to the sound way."},{"id":655,"title":"Cahillerden Olmaktan Korunma Duası (Bakara Sûresi)","ref":"Bakara Sûresi 2: 67","url":"https://quran.com/2/67","ar":"أَعُوْذُ بِاللَّهِ أَنْ أَكُونَ مِنَ الْجَاهِلِينَ","latin":"Eûzü billâhi en ekûne minel-câhilîn.","tr":"Cahillerden olmaktan Allah'a sığınırım.","en":"I seek refuge in Allah from being among the ignorant."},{"id":656,"title":"Korunma ve Bereket İçin İslâmî Dua (Bakara Sûresi)","ref":"Bakara Sûresi 2: 126","url":"https://quran.com/2/126","ar":"رَبِّ ٱجْعَلْ هَٰذَا بَلَدًا ءَامِنًا وَٱرْزُقْ أَهْلَهُۥ مِنَ ٱلثَّمَرَٰتِ مَنْ ءَامَنَ مِنْهُم بِٱللَّهِ وَٱلْيَوْمِ ٱلْءَاخِرِ ۖ","latin":"Rabbic'al hâzâ beladen âminen verzük ehlehu mines-semerâti men âmene minhüm billâhi vel-yevmil-âhir.","tr":"Rabbim, bunu güvenli bir şehir kıl; halkından Allah'a ve ahiret gününe inananları meyvelerle rızıklandır.","en":"My Lord, make this a secure city and provide its people with fruits - whoever of them believes in Allah and the Last Day."},{"id":657,"title":"Sabır İçin Güçlü Dua (Bakara Sûresi)","ref":"Bakara Sûresi 2: 250","url":"https://quran.com/2/250","ar":"رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا وَثَبِّتْ أَقْدَامَنَا وَانصُرْنَا عَلَى القَوْمِ الكَافِرِينَ","latin":"Rabbenâ efrığ aleynâ sabren ve sebbit akdâmenâ vensurnâ alel-kavmil-kâfirîn.","tr":"Rabbimiz, üzerimize sabır yağdır, ayaklarımızı sağlamlaştır ve kâfirler topluluğuna karşı bize yardım et.","en":"Our Lord! Bestow on us endurance, make our foothold sure, and give us help against the disbelieving folk"},{"id":658,"title":"İsyankâr İnsanlardan Korunma Duası (Mâide Sûresi)","ref":"Mâide Sûresi 5: 25","url":"https://quran.com/5/25","ar":"فَافْرُقْ بَيْنَنَا وَبَيْنَ الْقَوْمِ الْفَاسِقِينَ","latin":"Fefruk beynenâ ve beynel-kavmil-fâsikîn.","tr":"Bizimle fasık kavim arasını ayır.","en":"Part us from the defiantly disobedient people."},{"id":659,"title":"Rızık İçin Güçlü Dua (Mâide Sûresi)","ref":"Mâide Sûresi 5: 114","url":"https://quran.com/5/114","ar":"وَارْزُقْنَا وَأَنتَ خَيْرُ الرَّازِقِينَ","latin":"Verzuknâ ve Ente Haytur-râzikîn.","tr":"Bizi rızıklandır; Sen rızık verenlerin en hayırlısısın.","en":"And provide for us, and You are the best of providers."},{"id":660,"title":"Salih Evlat Duası (A'râf Sûresi)","ref":"A'râf Sûresi 7: 189","url":"https://quran.com/7/189","ar":"لَئِنْ آتَيْتَنَا صَالِحًا لَّنَكُونَنَّ مِنَ الشَّاكِرِينَ","latin":"Le'in âteytená sâlihan lenekûnenne mineş-şâkirîn.","tr":"Eğer bize salih (bir evlat) verirsen, şüphesiz şükredenlerden oluruz.","en":"If You should give us a good [child], we will surely be among the grateful."},{"id":661,"title":"Güvenlik ve Şükran Duası (Yûnus Sûresi)","ref":"Yûnus Sûresi 10: 22","url":"https://quran.com/10/22","ar":"لَئِنْ أَنجَيْتَنَا مِنْ هَٰذِهِ لَنَكُونَنَّ مِنَ الشَّاكِرِينَ","latin":"Le'in enceytenâ min hâzihi lenekûnenne mineş-şâkirîn.","tr":"Eğer bizi bundan kurtarırsan, şüphesiz şükredenlerden oluruz.","en":"If You should save us from this, we will surely be among the thankful."},{"id":662,"title":"Yolculuk Duası (Hûd Sûresi)","ref":"Hûd Sûresi 11: 41","url":"https://quran.com/11/41","ar":"بِسْمِ ٱللَّهِ مَجْر۪ىٰهَا وَمُرْسَىٰهَآۚ إِنَّ رَبِّى لَغَفُورٌ رَّحِيمٌ","latin":"Bismillâhi mecrîhâ ve mürsâhâ; inne Rabbî le-Ğafûrür-Rahîm.","tr":"Allah'ın adıyla (geminin) seyri de, demirlemesi de. Şüphesiz Rabbim çok bağışlayandır, çok merhametlidir.","en":"In the name of Allah is its course and its anchorage. Indeed, my Lord is Forgiving and Merciful."},{"id":663,"title":"Zor Zamanlarda Güç ve Hidayet Duası (Yûsuf Sûresi)","ref":"Yûsuf Sûresi 12: 23","url":"https://quran.com/12/23","ar":"مَعَاذَ اللَّهِ ۖ إِنَّهُ رَبِّي أَحْسَنَ مَثْوَايَ ۖ إِنَّهُ لَا يُفْلِحُ الظَّالِمُونَ","latin":"Me'âzallâhi innehu Rabbî ahsene mesveye; innehu lâ yüflihuz-zâlimûn.","tr":"Allah'a sığınırım! O benim efendimdir; bana iyi bir yer edinmemi sağladı. Şüphesiz zalimler kurtuluşa eremez.","en":"[I seek] the refuge of Allah. Indeed, he is my master, who has made good my residence. Indeed, wrongdoers will not succeed."},{"id":664,"title":"Hz. Yûsuf'un Korunma ve Huzur Duası (Yûsuf Sûresi)","ref":"Yûsuf Sûresi 12: 101","url":"https://quran.com/12/101","ar":"فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ ۖ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","latin":"Fâtıres-semâvâti vel-ardı Ente Veliyyî fid-dünyâ vel-âhirah; teveffenî müslimen ve elhıknî bis-sâlihîn.","tr":"Göklerin ve yerin yaratıcısı! Sen benim dünyada da âhirette de Velîmsin. Beni Müslüman olarak vefat ettir ve beni salihlerle birleştir.","en":"My Lord, You have given me [something] of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous."},{"id":665,"title":"Meryem Sûresi'nden Vâris Duası","ref":"Meryem Sûresi 19: 5","url":"https://quran.com/19/5","ar":"وَإِنِّي خِفْتُ الْمَوَالِيَ مِن وَرَائِي وَكَانَتِ امْرَأَتِي عَاقِرًا فَهَبْ لِي مِن لَّدُنكَ وَلِيًّا","latin":"Ve innî hiftül-mevâliye min verâî ve kânetimraetî âkıran feheb lî min ledünke veliyyâ.","tr":"Ben ardımdan bırakacağım akrabalarımdan endişelendim; zira karım kısırdır. Katından bana bir vâris bağışla.","en":"And indeed, I fear the successors after me, and my wife has been barren, so give me from Yourself an heir"},{"id":667,"title":"Allah'tan Yardım Dileme Duası (Mü'minûn Sûresi)","ref":"Mü'minûn Sûresi 23: 26","url":"https://quran.com/23/26","ar":"رَبِّ انصُرْنِي","latin":"Rabbinsurnî.","tr":"Rabbim, bana yardım et.","en":"My Lord, support me"},{"id":668,"title":"Konaklama Duası (Mü'minûn Sûresi)","ref":"Mü'minûn Sûresi 23: 29","url":"https://quran.com/23/29","ar":"رَّبِّ أَنزِلْنِي مُنزَلًا مُّبَارَكًا وَأَنتَ خَيْرُ الْمُنزِلِينَ","latin":"Rabbi enzilnî münzelen mübâreken ve Ente Hayrul-münzilîn.","tr":"Rabbim, beni bereketli bir yere indir; Sen konuklayanların en hayırlısısın.","en":"My Lord, let me land at a blessed landing place, and You are the best to accommodate [us]."},{"id":669,"title":"Dindar Müslüman Olmak İçin Dua (Mü'minûn Sûresi)","ref":"Mü'minûn Sûresi 23: 94","url":"https://quran.com/23/94","ar":"رَبِّ فَلَا تَجْعَلْنِي فِي الْقَوْمِ الظَّالِمِينَ","latin":"Rabbi felâ tec'alnî fil-kavmiz-zâlimîn.","tr":"Rabbim, beni zalimler topluluğunun içine koyma.","en":"My Lord, then do not place me among the wrongdoing people.\""},{"id":670,"title":"Allah'tan Yardım ve Güvenlik Duası (Şuarâ Sûresi)","ref":"Şuarâ Sûresi 26: 118","url":"https://quran.com/26/118","ar":"فَافْتَحْ بَيْنِي وَبَيْنَهُمْ فَتْحًا وَنَجِّنِي وَمَن مَّعِيَ مِنَ الْمُؤْمِنِينَ","latin":"Feftah beynî ve beynehüm fethan ve neccınî ve men meiye minel-mü'minîn.","tr":"Benimle onlar arasında kesin bir hükümle hükmet; beni ve beraberimdeki müminleri kurtar.","en":"Then judge between me and them with decisive judgement and save me and those with me of the believers."},{"id":671,"title":"Aileyle Birlikte Cennete Giriş İçin Rabbenâ Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi 40: 8","url":"https://quran.com/40/8","ar":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ","latin":"Rabbenâ ve edhılhüm cennâti adninilletî veadtehüm ve men salaha min âbâihim ve ezvâcihim ve zürriyyâtihim; inneke Entel-azîzül-hakîm.","tr":"Rabbimiz, onları ve atalarından, eşlerinden, nesillerinden salih olanları, onlara vadettiğin Adn cennetlerine kat. Şüphesiz Sen Azîz'sin, Hakîm'sin.","en":"Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise."},{"id":672,"title":"Mağfiret ve Cehennemden Korunma Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi 40: 9","url":"https://quran.com/40/9","ar":"وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ","latin":"Ve kıhimüs-seyyiât; ve men tekıs-seyyiâti yevme'izin fekad rahimteh; ve zâlike hüvel-fevzül-azîm.","tr":"Onları kötülüklerden koru; o gün kötülüklerden koruduğun kimseye şüphesiz rahmet etmiş olursun. İşte bu büyük kurtuluşun ta kendisidir.","en":"And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."},{"id":673,"title":"Kibirlilere Karşı Korunma Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi 40: 27","url":"https://quran.com/40/27","ar":"إِنِّي عُذْتُ بِرَبِّي وَرَبِّكُم مِّن كُلِّ مُتَكَبِّرٍ لَّا يُؤْمِنُ بِيَوْمِ الْحِسَابِ","latin":"İnnî uztü bi-Rabbî ve Rabbiküm min külli mütekebbiril-lâ yü'minü bi-yevmil-hisâb.","tr":"Şüphesiz ben, hesap gününe inanmayan her kibirliden Rabbime ve Rabbinize sığındım.","en":"Indeed, I have sought refuge in my Lord and your Lord from every arrogant one who does not believe in the Day of Account."},{"id":674,"title":"Allah'a Tevekkül Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi 40: 44","url":"https://quran.com/40/44","ar":"وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ ۚ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ","latin":"Ve üfevvidu emrî ilallâh; innallâhe basîrum-bil-ibâd.","tr":"İşimi Allah'a havale ediyorum. Şüphesiz Allah kullarını görmektedir.","en":"I entrust my affair to Allah. Indeed, Allah is Seeing of [His] servants."},{"id":675,"title":"Cennette Ev İçin Dua (Tahrîm Sûresi)","ref":"Tahrîm Sûresi 66: 11","url":"https://quran.com/66/11","ar":"رَبِّ ابْنِ لِي عِندَكَ بَيْتًا فِي الْجَنَّةِ","latin":"Rabbibni lî indeke beyten fil-cenneh.","tr":"Rabbim, katında cennet'te bana bir ev yap; beni Firavun'dan ve onun işlerinden kurtar, beni zalimler topluluğundan kurtar.","en":"My Lord, build for me near You a house in Paradise and save me from Pharaoh and his deeds and save me from the wrongdoing people."},{"id":676,"title":"Kâfirlere Karşı Dua (Nûh Sûresi)","ref":"Nûh Sûresi 71: 26","url":"https://quran.com/71/26","ar":"رَّبِّ لَا تَذَرْ عَلَى الْأَرْضِ مِنَ الْكَافِرِينَ دَيَّارًا","latin":"Rabbi lâ tezar alel-ardı minel-kâfirîne deyyârâ.","tr":"Rabbim, yeryüzünde kâfirlerden hiçbir sakin bırakma.","en":"My Lord, do not leave upon the earth from among the disbelievers an inhabitant."},{"id":677,"title":"Kaygı ve Stres Giderme Duası","ref":"[1] Ahmed 1/391, Elbânî Sahîha'da sahih olarak derecelendirmiştir 1/337 [2] Sahîh İbn Hibbân 3/253","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_677.json","ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ، نَاصِيَتِي بِيَدِكَ، مَاضٍ فِيَّ حُكْمُكَ، عَدْلٌ فِيَّ قَضَاؤُكَ، أَسْأَلُكَ بِكُلِّ اسْمٍ هُوَ لَكَ، سَمَّيْتَ بِهِ نَفْسَكَ، أَوْ أَنْزَلْتَهُ فِي كِتَبِكَ، أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ، أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ، أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِي، وَنُوْرَ بَصَرِيْ (وَنُورَ صَدْرِي)، وَجَلَاءَ حُزْنِيْ، وَذَهَابَ هَمِّيْ","latin":"Allâhümme innî abdüke, vebnü abdike, vebnü emetike, nâsıyetî bi-yedike, mâdın fiyye hükmüke, adlün fiyye kadâüke, es'elüke bi-külli ismin hüve leke, semmeyte bihi nefseke, ev enzeltehü fî kitâbike, ev allemtehü ehaden min halkıke, ev isteserte bihi fî ilmil-ğaybi indeke, en tec'alel-kur'âne rebîa kalbî, ve nûra basarî (başka bir rivayette 'basarî' yerine 'sadrî'), ve celâe huznî, ve zehâbe hemmî.","tr":"Allâh'ım, ben Senin kulunum, Senin erkek kulunun oğluyum, Senin kadın kulunun oğluyum. Alnım Senin elindedir (yani Sen benim üzerimde hâkimsin). Benim hakkımdaki hükmün geçerlidir, benim hakkımdaki kaderindir adil olan. Kendine isim olarak verdiğin, Kitabında indirdiğin, yarattıklarından birine öğrettiğin ya da katındaki gayb ilminde Senin için sakladığın her bir ismin hürmetine Senden istiyorum: Kur'ân'ı kalbimin baharı, gözümün (bir rivayette 'göğsümün') nuru, üzüntümün gidericisi ve sıkıntımın gidereni kıl. [1]\n\nAbdullah ibn Mes'ûd (r.a.) şöyle dedi: Allah Resûlü (s.a.v.) buyurdu: 'Kime sıkıntı ve üzüntü isabet eder de bu duayı okursa, Allah onun sıkıntısını ve üzüntüsünü giderir, yerlerine ferahlık verir.' Ashab, 'Bunları öğrenmeli miyiz?' diye sordu. O, 'Elbette! Bunları işiten herkes öğrenmelidir' buyurdu.' Bu hadisin senedi makbuldür. [2] Not: Kadınlar bu duayı şu şekilde okumalıdır: 'Allâhümme innî emetüke, ve bintü abdike ve bintü emetike…' Yani: 'Allâh'ım, ben Senin cariyenim, Senin erkek kulunun kızıyım ve Senin kadın kulunun kızıyım….' Birçok hadiste Allah'ın en büyük ismiyle dua etmek teşvik edilmiştir. Bazı rivayetlerde Allah'tan bu isimle dileyenin duasının kabul edileceği belirtilmektedir.","en":"O Allah, I am Your slave and the son of Your male slave and the son of your female slave. My forehead is in Your Hand (i.e. you have control over me). Your Judgment upon me is assured and Your Decree concerning me is just. I ask You by every Name that You have named Yourself with, revealed in Your Book, taught any one of Your creation or kept unto Yourself in the knowledge of the unseen that is with You, to make the Qur'an the spring of my heart, and the light of my chest, the banisher of my sadness and the reliever of my distress. [1]\n\nAbdullah ibn Mas’ud (RA) said, The Messenger of Allah (ﷺ) said, “If anyone afflicted with anxiety, inquietude state and he says the above mentioned dua, then Allah will remove his distress and anxiety and altered it with happiness. Companions then said, ”So, we have to learn these words! He said,“Obviously! Whomsoever listens to these words, should memorize them.” This hadith's chain of narration is acceptable. [2] N.B. Women should say this dua like this: “Allaahumma inni amatuka, wa bintu ‘abdika wa bintu amatika….” Meaning: “Oh Allah! I am your slave girl, a daughter of your slave and a daughter of your slave girl….” In many hadiths, it is encouraged to make dua by the greatest name of Allah. In many narrations, it is said that if anyone ask Allah by this name then Allah will accept his dua."},{"id":678,"title":"İsm-i Âzam ile Dua (Allah'ın En Büyük İsimleri)","ref":"Sahih. Tirmizî: 3475","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_678.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنِّي أَشْهَدُ أَنَّكَ أَنْتَ اَللَّهُ لَا إِلَهَ إِلَّا أَنْتَ الْأَحَدُ الصَّمَدُ اَلَّذِي لَمْ يَلِدْ وَلَمْ يُوْلَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","latin":"Allâhümme innî es'elüke bi-ennî eşhedü enneke Entallâhü lâ ilâhe illâ Entel-Ahadüs-Samedüllezî lem yelid ve lem yûled ve lem yekün lehû küfüven ehad.","tr":"Allâh'ım, şüphesiz Senden şunu istiyorum: Senin Allah olduğuna, Senden başka ilâh olmadığına şahitlik ederim. Sen Ehadisin, Samedsin; doğurmadın ve doğurulmadın, hiçbir şey Sana denk değildir.\n\n'Büreyde (r.a.) şöyle dedi: Peygamber (s.a.v.) bir adamın bu duayla dua ettiğini duydu. Bunun üzerine şöyle buyurdu: Canım Kudret elinde bulunan Allah'a yemin olsun ki o adam Allah'tan İsm-i Âzam'ıyla diledi; o isimle dua edildiğinde Allah icabet eder, o isimle istenildiğinde Allah verir.'","en":"O Allah, I ask You, by the fact that I bear witness that You are Allah. There is none worthy of worship but You, the Only God, Independent of creation, Who was not begotten and begets not , and none is equal to Him.\n\n\"Buraidah (RA) said, “The Prophet (ﷺ) heard a man supplicating with this dua, So he said: ‘By the One in Whose Hand is my soul, he has asked Allah by His Greatest Name, the one which if He is called upon by it, He responds, and when He is asked by it, He gives.\""},{"id":679,"title":"Allah'ın En Büyük İsimleri Duası (İsm-i Âzam)","ref":"Sahih (Elbânî). Nesâî: 1300","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_679.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيعُ السَّمَاوَاتِ وَالْأَرْضِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، يَا حَيُّ يَا قَيُّومُ، إِنِّي أَسْأَلُكَ","latin":"Allâhümme innî es'elüke bi-enne lekel-hamd, lâ ilâhe illâ entel-mennânü bedi'us-semâvâti vel-ard, yâ zel-celâli vel-ikrâm! Yâ hayyu yâ kayyûm innî es'elük.","tr":"Allâh'ım, şüphesiz Senden şunu istiyorum: Tüm hamd Sana aittir, Senden başka ilâh yoktur; Sen Mennân'sın, göklerin ve yerin yaratıcısısın. Ey Celâl ve İkram sahibi! Ey Hayy! Ey Kayyûm! Senden istiyorum.\n\nAllah Resûlü'nün (s.a.v.) yanında oturuyordum; bir adam namaz kılıyordu. Rükû yapıp, secde yapıp ve teşehhüdü okuyunca dua etti; duasında bu sözleri söyledi. Peygamber (s.a.v.) şöyle buyurdu: 'Ne ile dua ettiğini biliyor musunuz?' Onlar: 'Allah ve Resûlü daha iyi bilir' dediler. Bunun üzerine şöyle buyurdu: 'Canım elinde bulunan Allah'a yemin olsun ki o adam Allah'ı İsm-i Âzam'ıyla çağırdı; o isimle çağrıldığında Allah icabet eder, o isimle istenildiğinde verir.'","en":"O Allah, indeed I ask You since all praise is due to You, there is none worthy of worship but You, the Bestower, the Creator of the heavens and earth, O Possessor of majesty and honor, O Ever-living, O-Eternal. I am asking to you.\n\nI was sitting with the Messenger of Allah (ﷺ) and a man was praying. When he bowed, prostrated and recited the tashahhud, he supplicated, and in his supplication he said: (the above mentioned dua). The Prophet (ﷺ) said, 'Do you know what he has supplicated with?' They said, \"Allah (SWT) and His Messenger know best.\" He said, 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives.'"},{"id":681,"title":"Allah'ın En Büyük İsimleri Duası (Er-Rahmân)","ref":"Ebû Dâvûd: 1496","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_681.json","ar":"وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ","latin":"Ve ilâhüküm ilâhün vâhidün lâ ilâhe illâ hüver-rahmânür-rahîm.","tr":"Sizin ilâhınız bir tek ilâhtır; O'ndan başka ilâh yoktur. O, Rahman'dır, Rahim'dir.","en":"And your Allah is One Allah: There is no god but He, Most Gracious, Most Merciful."},{"id":682,"title":"Allah'ın En Büyük İsimleri Duası (Âyetü'l-Kürsî)","ref":"Ebû Dâvûd: 1496","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_682.json","ar":"الم. اَللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ","latin":"Elif Lâm Mîm. Allâhü lâ ilâhe illâ Hüvel-Hayyül-kayyûm.","tr":"Elif, Lâm, Mîm. Allah; O'ndan başka ilâh yoktur. Hayy'dır, Kayyûm'dur.\n\nYezîd kızı Esmâ (r.a.) rivayet etmiştir: Peygamber (s.a.v.) şöyle buyurdu: 'Allah'ın İsm-i Âzam'ı şu iki ayette geçmektedir: Ve ilâhüküm ilâhün vâhidün... (Bakara: 163) ve Âl-i İmrân sûresinin başı: Elif Lâm Mîm. Allah, O'ndan başka ilâh yoktur; Hayy'dır, Kayyûm'dur.'","en":"Alif, Lam, Meem. Allah - there is no deity except Him, the Ever-Living, the Sustainer of existence.\n\nAsma daughter of Yazid (RA) reported, the Prophet (ﷺ) said: \"Allah's Greatest Names is in these two verses: \"And your Ilaah (God) is One Ilaah (God), none has the right to be worshipped but He, the Ever-Merciful, the Mercy-Giving' (Surah al-Baqarah: 163)and the beginning of Surah Al 'Imran, \"Alif Laam Mim. Allah, there is no deity but He, the Living, the Eternal.\""},{"id":683,"title":"Allah'ın En Büyük İsimleri Duası (Tâhâ Sûresi)","ref":"Sahih (Elbânî). Sahîhu'l-Câmi: 1025","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_683.json","ar":"وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ","latin":"Ve anetil-vücûhü lil-hayyil-kayyûm.","tr":"Yüzler, Hayy ve Kayyûm olan (Allah) önünde eğilip boyun bükmüştür.","en":"(All) faces shall be humbled before (Him) - the Living, the Self-Subsisting."},{"id":686,"title":"Zor Zamanlarda Hz. Yûnus'un (a.s.) Güçlü Duası","ref":"Enbiyâ Sûresi 21: 87","url":"https://quran.com/21/87","ar":"لَا إِلَـٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ","latin":"Lâ ilâhe illâ Ente Sübhâneke innî küntü minez-zâlimîn.","tr":"Senden başka ilâh yoktur. Seni tenzih ederim. Şüphesiz ben zalimlerden oldum.","en":"There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers."},{"id":689,"title":"Hidayet Duası (Mesnûn Dua)","ref":"Yûsuf Sûresi 12: 64","url":"https://quran.com/12/64","ar":"فَاللَّـهُ خَيْرٌ حَافِظًا ۖ وَهُوَ أَرْحَمُ الرَّاحِمِينَ","latin":"Fellâhü hayrun hâfızâ; ve Hüve Erhamür-râhimîn.","tr":"Allah koruyucuların en hayırlısıdır; O merhametlilerin en merhametlisidir.","en":"But Allah is the best guardian, and He is the most merciful of the merciful."},{"id":690,"title":"Sabır Duası (Yûsuf Sûresi)","ref":"Yûsuf Sûresi 12: 83","url":"https://quran.com/12/83","ar":"فَصَبْرٌ جَمِيلٌ ۖ عَسَى اللَّـهُ أَن يَأْتِيَنِي بِهِمْ جَمِيعًا ۚ إِنَّهُ هُوَ الْعَلِيمُ الْحَكِيمُ","latin":"Fesubrun cemîl; asallâhü en ye'tiyenî bihim cemî'â; innehu Hüvel-alîmül-hakîm.","tr":"Güzel sabır yaraşır (bana). Umarım Allah hepsini bana geri getirir. Şüphesiz O, Alîm'dir, Hakîm'dir.","en":"So patience is most fitting. Perhaps Allah will bring them to me all together. Indeed it is He who is the Knowing, the Wise.\""},{"id":691,"title":"Hz. Yûsuf'un Korunma Duası","ref":"Yûsuf Sûresi 12: 33","url":"https://quran.com/12/33","ar":"رَبِّ السِّجْنُ أَحَبُّ إِلَيَّ مِمَّا يَدْعُونَنِي إِلَيْهِ ۖ وَإِلَّا تَصْرِفْ عَنِّي كَيْدَهُنَّ أَصْبُ إِلَيْهِنَّ وَأَكُن مِّنَ الْجَاهِلِينَ","latin":"Rabbis-sicnü ehabbu ileyye mimmâ yed'ûnenî ileyh; ve illâ tasrif annî keydehünne asbu ileyhinne ve ekün minel-câhilîn.","tr":"Rabbim, hapishane bana onların beni çağırdığı şeyden daha sevgilidir. Eğer onların tuzaklarını benden savmazsan, onlara meyleder ve cahillerden olurum.","en":"My Lord, prison is more to my liking than that to which they invite me. And if You do not avert from me their plan, I might incline toward them and [thus] be of the ignorant."},{"id":695,"title":"Dünya ve Âhirette İyilik İçin Dua (Rabbenâ Duası)","ref":"Müslim: 2690","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_695.json","ar":"اَللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","latin":"Allâhümme âtinâ fid-dünyâ haseneten, ve fil-âhirati haseneten, ve kınâ azâben-nâr.","tr":"Allâh'ım, bize dünyada iyilik ver, âhirette de iyilik ver ve bizi ateşin azabından koru.\n\nEnes (r.a.) ne zaman dua etse mutlaka bu duayı okurdu; başka bir dua okuyacağı zaman da bu duayı o duanın içine katardı.","en":"O Allah! Give us in this world that, which is good and in the Hereafter that, which is good and save us from the torment of the Fire.\n\nWhenever Anas (RA) had to supplicate he made this very supplication, and whenever he (intended) to make another supplication he (inserted) this very supplication in that."},{"id":696,"title":"Deccal ve Zorluklardan Korunma Duası","ref":"Buhârî: 6377","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_696.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ فِتْنَةِ النَّارِ وَعَذَابِ النَّارِ، وَفِتْنَةِ الْقَبْرِ وَعَذَابِ الْقَبْرِ، وَشَرِّ فِتْنَةِ الْغِنَى، وَشَرِّ فِتْنَةِ الْفَقْرِ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، اَللَّهُمَّ اغْسِلْ قَلْبِي بِمَاءِ الثَّلْجِ وَالْبَرَدِ، وَنَقِّ قَلْبِي مِنَ الْخَطَايَا، كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَبَاعِدْ بَيْنِي وَبَيْنَ خَطَايَاىَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ وَالْمَأْثَمِ وَالْمَغْرَمِ","latin":"Allâhümme innî eûzü bike min fitnetin-nâr, ve azâbin-nâr, ve fitnetil-kabr ve azâbil-kabr, ve şerri fitnetil-ğınâ, ve şerri fitnetil-fekr, Allâhümme innî eûzü bike min şerri fitnetil-mesîhid-deccâl. Allâhümmağsil kalbî bi-mâiś-śelci vel-bered, ve nakki kalbî minel-hatâyâ kemâ nakaytaś-śevbel-ebyada mined-denes. Ve bâid beynî ve beyne hatâyâye kemâ bâadte beynel-meşrikı vel-mağrib. Allâhümme innî eûzü bike minel-keseli vel-me'śemi vel-mağram.","tr":"Allâh'ım, cehennem fitnesinden, cehennem azabından, kabir fitnesinden, kabir azabından, zenginlik fitnesinin şerrinden ve fakirlik fitnesinin şerrinden Sana sığınırım. Allâh'ım, Mesîh Deccal'ın fitnesinin şerrinden Sana sığınırım. Allâh'ım, kalbimi kar ve dolu suyu ile yıka; kalbimi günahlardan, beyaz elbisenin kirden temizlendiği gibi temizle. Benimle günahlarımın arasını, doğu ile batıyı birbirinden uzaklaştırdığın gibi uzaklaştır. Allâh'ım, tembellikten, günahtan ve borçtan Sana sığınırım.","en":"O Allah! I seek refuge with You from the affliction of the Fire, the punishment of the Fire, the affliction of the grave, the punishment of the grave, and the evil of the affliction of poverty. O Allah! I seek refuge with You from the evil of the affliction of Al-Masih Ad- Dajjal, O Allah! Cleanse my heart with the water of snow and hail, and cleanse my heart from all sins as a white garment is cleansed from filth, and let there be a far away distance between me and my sins as You made the East and West far away from each other. O Allah! I seek refuge with You from laziness, senility, sins, and from being in debt."},{"id":697,"title":"Kabir Azabından Korunma Duası","ref":"Buhârî: 6367, Müslim: 2706","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_697.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْهَرَمِ، وَالْبُخْلِ وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ","latin":"Allâhümme innî eûzü bike minel-aczi, vel-keseli, vel-cübni, vel-haremi, vel-buhli, ve eûzü bike min azâbil-kabr, ve min fitnetil-mahyâ vel-memât.","tr":"Allâh'ım, acizlikten, tembellikten, korkaklıktan, ihtiyarlıktan, cimrilikten Sana sığınırım; kabir azabından, hayat ve ölüm fitnesinden Sana sığınırım.","en":"O Allah, I seek refuge in Thee from incapacity, from indolence, from cowardice, from senility, from miserliness, and I seek refuge in Thee from the torment of the grave and from trial of the life and death."},{"id":699,"title":"Tembellik ve Zayıflıktan Korunma Duası","ref":"Müslim: 2722","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_699.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ، اَللَّهُمَّ آتِ نَفْسِيْ تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا","latin":"Allâhümme innî eûzü bike minel-aczi vel-keseli, vel-cübni vel-buhli, vel-haremi ve azâbil-kabr, Allâhümme âti nefsî takvâhâ ve zekkihâ ente hayru men zekkâhâ ente veliyyühâ ve mevlâhâ, Allâhümme innî eûzü bike min ilmin lâ yenfeu, ve min kalbin lâ yahşeu, ve min nefsin lâ teşbau, ve min da'vetin lâ yüstecâbu lehâ.","tr":"Allâh'ım, acizlikten, tembellikten, korkaklıktan, cimrilikten, ihtiyarlıktan ve kabir azabından Sana sığınırım. Allâh'ım, nefsime takvâsını ver ve onu temizle; onu en iyi temizleyecek olan Sensin; onun velisi ve efendisi Sensin. Allâh'ım, fayda vermeyen ilimden, Allah'a saygı duymayan kalpten, doymayan nefisten ve kabul edilmeyen duadan Sana sığınırım.","en":"O Allah, I seek refuge with You from weakness, and laziness, cowardice and miserliness, old and infirm age, and the torment of the grave. O Allah, give my soul piety and purify it, for indeed You are the best of those who can purify it, You are it's Guardian and Master. O Allah, I seek refuge with You from knowledge that does not benefit, from a heart that does not get humbled [to Allah], from a soul which is never satisfied and from a supplication which does not get answered."},{"id":700,"title":"Allah'ın Gazabından Korunma Duası","ref":"Müslim: 2739","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_700.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ، وَجَمِيعِ سَخَطِكَ","latin":"Allâhümme innî eûzü bike min zevâli ni'metike, ve tahavvüli âfiyetike, ve fücâeti nikmetike, ve cemî'i sahatık.","tr":"Allâh'ım, nimetinin geri alınmasından, sağlığının değişmesinden, ansızın gelecek azabından ve her türlü gazabından Sana sığınırım.","en":"O Allah, I seek refuge in Thee from the withdrawal of Thine blessing and the change of Thine protection (from me) and from the sudden wrath of Thine, and from every displeasure of Thine."},{"id":701,"title":"Kötülükten Korunma İçin İslâmî Dua (Mesnûn Dua)","ref":"Müslim: 2716","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_701.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ","latin":"Allâhümme, innî eûzü bike min şerri mâ amiltü, ve min şerri mâ lem a'mel.","tr":"Allâh'ım, yaptığımın şerrinden ve yapmadığımın şerrinden Sana sığınırım.","en":"I seek refuge in Thee from the evil of what I did and from the evil of what I did not."},{"id":703,"title":"Hidayet ve Zenginlik Duası (Mesnûn Dua)","ref":"Müslim: 2721","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_703.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى، وَالتُّقَى، وَالْعَفَافَ، وَالْغِنَى","latin":"Allâhümme, innî es'elukel-hüdâ vet-tükâ vel-afâfe vel-ğınâ.","tr":"Allâh'ım, Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.","en":"O Allah. I beg of Thee the right guidance, safeguard against evils, chastity and freedom from want."},{"id":704,"title":"Allah'tan Hidayet ve Güç Dileme Duası","ref":"Müslim: 2725","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_704.json","ar":"اَللَّهُمَّ اهْدِنِيْ وَسَدِّدْنِي","latin":"Allâhümmehdinî ve seddidnî.","tr":"Allâh'ım, bana hidayet et ve beni doğru yolda sağlamlaştır.","en":"O Allah, guide me and make me steadfast."},{"id":706,"title":"Peygamberin Servet ve Nesil İçin Duası","ref":"Buhârî: 6344","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_706.json","ar":"اَللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ وَبَارِكْ لَهُ فِيمَا أَعْطَيْتَهُ","latin":"Allâhümme eksir mâlehû ve veledehû ve bârik lehu fîmâ a'taytehû.","tr":"Allâh'ım, onun malını ve çocuklarını çoğalt; verdiğin şeylerde ona bereket ver.\n\nEnes (r.a.) anlatıyor: Annem şöyle dedi: 'Ey Allah'ın Resûlü! Kulun (Enes) için Allah'a dua edin.' Bunun üzerine o (s.a.v.) şöyle dua etti: (dua yukarıda belirtilmiştir.)","en":"O Allah! Increase his wealth and children, and bestow Your Blessing on whatever You give him.\n\nNarrated by Anas (RA): My mother said, \"O Allah's Messenger (ﷺ)! Please invoke Allah on behalf of your servant.\" He (ﷺ) said: (the dua is mentioned above)"},{"id":707,"title":"Stres ve Üzüntü Giderme Duası","ref":"Buhârî: 6346","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_707.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ الْعَظِيْمُ الْحَلِيمُ، لَا إِلَهَ إِلَّا اللَّهُ رَبُّ الْعَرْشِ الْعَظِيمِ لَا إِلَهَ إِلَّا اللَّهُ رَبُّ السَّمَاوَاتِ وَرَبُّ الْأَرْضِ وَرَبُّ الْعَرْشِ الْكَرِيمِ","latin":"Lâ ilâhe illallâhül azîmül halîm. Lâ ilâhe illallâhü Rabbül arşil azîm. Lâ ilâhe illallâhü Rabbus-semâvâti ve Rabbül ardi, ve Rabbül arşil-kerîm.","tr":"Azîm ve Halîm olan Allah'tan başka ilâh yoktur. Yüce Arş'ın Rabbi olan Allah'tan başka ilâh yoktur. Göklerin Rabbi, yerin Rabbi ve Kerîm Arş'ın Rabbi olan Allah'tan başka ilâh yoktur.","en":"There is none worthy of worship but Allah the Mighty, the Forbearing. There is none worthy of worship but Allah, Lord of the Magnificent Throne. There is none worthy of worship but Allah, Lord of the heavens and Lord of the earth, and Lord of the Noble Throne."},{"id":708,"title":"Sağlıklı Vücut, İşitme ve Görme İçin Dua","ref":"Hasen. Ebû Dâvûd: 5090","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_708.json","ar":"اَللَّهُمَّ عَافِنِيْ فِي بَدَنِي اَللَّهُمَّ عَافِنِيْ فِي سَمْعِيْ اَللَّهُمَّ عَافِنِيْ فِي بَصَرِيْ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümme âfinî fî bedenî, Allâhümme âfinî fî sem'î, Allâhümme âfinî fî basarî, lâ ilâhe illâ Ente.","tr":"Allâh'ım, bedenimi sağlıklı kıl! Allâh'ım, işitmemi sağlıklı kıl! Allâh'ım, görüşümü sağlıklı kıl! Senden başka hak ilâh yoktur.","en":"O Allah! Keep my body healthy! O Allah! Keep my hearing healthy! O Allah! Keep my eyesight healthy! There is no true god but you."},{"id":709,"title":"Kabir Azabından Korunma Duası","ref":"Hasen. Ebû Dâvûd: 5090","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_709.json","ar":"اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ اَللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Allâhümme innî eûzü bike minel-küfri, vel-fekr, Allâhümme innî eûzü bike min azâbil-kabr, lâ ilâhe illâ Ente.","tr":"Allâh'ım, küfürden ve fakirlikten Sana sığınırım. Allâh'ım, kabir azabından Sana sığınırım. Senden başka hak ilâh yoktur.\n\nEbû Bekre şöyle dedi: Allah Resûlü'nün (s.a.v.) bu sözleri dua olarak kullandığını duydum; onun sünnetine uymayı seviyorum.","en":"O Allah, I seek refuge in You from disbelief and poverty. O Allah! I seek refuge in You from the punishment of the grave. There is none worthy of worship but You.\n\nHe said: I heard the Messenger of Allah (ﷺ) using these words as a supplication and I like to follow his sunnah."},{"id":710,"title":"Zor Zamanlar ve Rahatlama Duası","ref":"Hasen. Ebû Dâvûd: 5090","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_710.json","ar":"اَللَّهُمَّ رَحْمَتَكَ أَرْجُو فَلَا تَكِلْنِيْ إِلَى نَفْسِيْ طَرْفَةَ عَيْنٍ وَأَصْلِحْ لِي شَأْنِيْ كُلَّهُ لَا إِلَهَ إِلاَّ أَنْتَ","latin":"Allâhümme rahmeteke ercû felâ tekilnî ilâ nefsî tarfete ayn, ve aslih lî şe'nî küllehü, lâ ilâhe illâ Ente.","tr":"Allâh'ım, rahmetine umut bağlıyorum. Beni bir göz kırpımı (an) bile kendi başıma bırakma. Tüm işlerimi benim için düzelt. Senden başka hak ilâh yoktur.","en":"O Allah, I hope for Your mercy. Do not leave me to myself even for the blinking of an eye (i.e. a moment). Correct all of my affairs for me. There is none worthy of worship but You."},{"id":712,"title":"Stres Giderme ve Zorluklar İçin Dua","ref":"Sahih (Elbânî). Silsiletü's-Sahîha: 199","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_712.json","ar":"اَللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ أَسْأَلُكَ بِكُلِّ اِسْمٍ هُوَ لَكَ سَمَّيْتَ بِهِ نَفْسَكَ أَوْ عَلَّمْتَهُ أَحَدًا مِنْ خَلْقِكَ أَوْ أَنْزَلْتَهُ فِي كِتَابِكَ أَوِ اسْتَأْثَرْتَ بِهِ فِي عِلْمِ الْغَيْبِ عِنْدَكَ أَنْ تَجْعَلَ الْقُرْآنَ رَبِيْعَ قَلْبِي وَنُورَ صَدْرِي وَجَلَاءَ حُزْنِيْ وَذَهَابَ هَمِّيْ","latin":"Allâhümme innî abdüke, vebnü abdike, vebnü emetike, nâsıyetî bi-yedike, mâdın fiyye hükmüke, adlün fiyye kadâüke, es'elüke bi-külli ismin hüve leke, semmeyte bihi nefseke, ev allemtehü ehaden min halkıke, ev enzeltehü fî kitâbike, ev isteserte bihi fî ilmil-ğaybi indeke, en tec'alel-kur'âne rebîa kalbî, ve nûra sadrî, ve celâe huznî, ve zehâbe hemmî.","tr":"Allâh'ım, ben Senin kulunum, Senin erkek kulunun oğluyum, Senin kadın kulunun oğluyum. Alnım Senin elindedir. Benim hakkımdaki hükmün geçerlidir, benim hakkımdaki kaderindir adil olan. Kendine isim olarak verdiğin, yarattıklarından birine öğrettiğin, Kitabında indirdiğin ya da katındaki gayb ilminde Senin için sakladığın her bir ismin hürmetine Senden istiyorum: Kur'ân'ı kalbimin baharı, göğsümün nuru, üzüntümün gidericisi ve sıkıntımın gidereni kıl.\n\nAllah onun kaygı ve sıkıntılarını mutlaka giderir, yerlerine sevinç verir. 'Ey Allah'ın Resûlü, bunu öğrenelim mi?' diye soruldu. Peygamber (s.a.v.) şöyle buyurdu: 'Elbette! Bunu işiten herkes ezberlesin.'","en":"O Allah, I am Your slave and the son of Your male slave and the son of your female slave. My forehead is in Your Hand (i.e. you have control over me). Your Judgment upon me is assured and Your Decree concerning me is just. I ask You by every Name that You have named Yourself with, Taught any one of Your creation or revealed in Your Book or kept unto Yourself in the knowledge of the unseen that is with You, to make the Qur'an the spring of my heart, and the light of my chest, the banisher of my sadness and the reliever of my distress.\n\nAllah will surely remove his worries and troubles and replace them with joy. It was asked, O Messenger of Allah (ﷺ)! Shall we not learn it? ' The Prophet (ﷺ) said, “Of course! Anyone who hears this should memorize it."},{"id":716,"title":"Yardım ve Hidayet İçin Güçlü Dua","ref":"Sahih (Süyûtî). Câmiu's-Sağîr: 1450","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_716.json","ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُورِ كُلِّهَا وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْاَخِرَةِ","latin":"Allâhümme ahsin âkıbetinâ fil-umûri küllihe, ve ecirnâ min hızyi'd-dünyâ ve azâbil-âhirah.","tr":"Allâh'ım, tüm işlerimizde sonumuzu iyi eyle; bizi dünya rezilliğinden ve âhiret azabından koru.","en":"O Allah! grant us a good outcome on all of our affairs and save us from the disgrace of this world and the punishment of the Hereafter."},{"id":717,"title":"Dünya ve Âhirette Güvenlik İçin Peygamberin Duası","ref":"Sahih. Tirmizî: 3551","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_717.json","ar":"رَبِّ أَعِنِّيْ وَلَا تُعِنْ عَلَىَّ وَانْصُرْنِيْ وَلَا تَنْصُرْ عَلَىَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَىَّ وَاهْدِنِيْ وَيَسِّرِ الْهُدَى لِي وَانْصُرْنِيْ عَلَى مَنْ بَغَى عَلَىَّ رَبِّ اجْعَلْنِيْ لَكَ شَكَّارًا لَكَ ذَكَّارًا لَكَ رَهَّابًا لَكَ مِطْوَاعًا لَكَ مُخْبِتًا إِلَيْكَ أَوَّاهًا مُنِيبًا رَبِّ تَقَبَّلْ تَوْبَتِيْ وَاغْسِلْ حَوْبَتِيْ وَأَجِبْ دَعْوَتِيْ وَثَبِّتْ حُجَّتِيْ وَسَدِّدْ لِسَانِيْ وَاهْدِ قَلْبِيْ وَاسْلُلْ سَخِيْمَةَ صَدْرِيْ","latin":"Rabbi! E'innî ve lâ tü'in aleyye, vensurnî ve lâ tensur aleyye, vemkür lî ve lâ temkür aleyye, vahdinî ve yessıril-hüdâ lî, vensurnî alâ men bağâ aleyye. Rabbic'alnî leke şekkâren, leke zakkâren, leke rahhâben, leke mitvâen, leke muhbiten, ileyke evvâhen münîbâ. Rabbi! Tekabbel tevbetî, vağsil havbetî ve ecib da'vetî, ve sebbit hüccetî, ve seddid lisânî, vahdi kalbî, vaslül sahîmete sadrî.","tr":"Rabbim, bana yardım et ve aleyhime yardım etme; bana zafer ver ve üzerime zafer verme; benim için hile yap ve aleyhime hile yapma; bana hidayet et ve hidayeti benim için kolaylaştır; bana zulmedenlere karşı bana zafer ver. Rabbim, beni Sana çok şükreden, Seni çok zikreden, Senden çok korkan, Sana itaatkâr, Sana alçakgönüllü, Sana çok yönelen ve dönen birisi kıl. Rabbim, tevbemi kabul et, günahımı sil, duamı kabul et, delilimi sağlamlaştır, dilimi doğrult, kalbime hidayet ver, göğsümdeki kini söküp at.","en":"My Lord, aid me and do not aid against me, and grant me victory and do not grant victory over me, plot for me and do not plot against me, guide me and facilitate guidance for me, grant me victory over those who transgress against me. My Lord, make me ever-grateful to You, ever-remembering of You, ever-fearful of You, ever-obedient to You, ever-humble to You, oft-turning and returning to You. My Lord, accept my repentance, wash my sin, answer my call, make firm my proof, make firm my tongue, guide my heart, and remove the treachery of my chest."},{"id":718,"title":"Bereket, Güvenlik ve Cennet İçin Dua","ref":"Hasen (Şevkânî). Tuhfetü'z-Zâkirîn: 489","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_718.json","ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ وَنَعُوذُ بِكَ مِنْ شَرِّ مَا اسْتَعَاذَ بِكَ مِنْهُ نَبِيُّكَ مُحَمَّدٌ وَأَنْتَ الْمُسْتَعَانُ وَعَلَيْكَ الْبَلَاغُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Allâhümme innâ nes'elüke min hayri mâ seeleke minhü nebiyyüke Muhammedün, ve neûzü bike min şerri mesté'âze bike minhü nebiyyüke Muhammedün, ve entel-müste'ânü ve aleykel-belâğ, ve lâ havle ve lâ kuvvete illâ billâh.","tr":"Allâh'ım, Peygamberin Hz. Muhammed'in Senden istediği iyilikleri Senden istiyoruz; Peygamberin Hz. Muhammed'in Senden sığındığı kötülüklerden Sana sığınıyoruz. Yardım istenilen Sensin, tebliğ etmek de Sana düşer; güç ve kuvvet yalnızca Allah'tandır.\n\nEbû Umâme (r.a.) şöyle rivayet etti: 'Allah Resûlü (s.a.v.) pek çok dua okudu ve biz bunları ezberliyemedik. Dedik ki: Ey Allah'ın Resûlü, pek çok dua okudunuz ve biz bunları ezberliyemedik. Buyurdu: Bunların hepsini kapsayan bir şeye sizi yönlendireyim mi? (Dua yukarıda belirtilmiştir.)'","en":"O Allah, we ask You from the good of what Your Prophet Muhammad (ﷺ) asked You for, and we seek refuge in You from the evil of that which Your Prophet Muhammad (ﷺ) sought refuge in You from, and You are the one from Whom aid is sought, and it is for You to fulfill, and there is no might or power except by Allah.\n\nAbu Umamah (RA) narrated: “The Messenger of Allah (ﷺ) supplicated with many supplications of which we did not preserve a thing. We said: ‘O Messenger of Allah (ﷺ), you supplicated with many supplications of which we did not preserve a thing.’ He (ﷺ) said: ‘Should I not direct you to what will include all of that? That you say: (The dua is mentioned above)"},{"id":719,"title":"Kötülükten Korunmak İçin Peygamberin Duası","ref":"Sahih. İbn Mâce: 3846","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_719.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنَ الْخَيْرِ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ وَأَعُوْذُ بِكَ مِنَ الشَّرِّ كُلِّهِ عَاجِلِهِ وَآجِلِهِ مَا عَلِمْتُ مِنْهُ وَمَا لَمْ أَعْلَمْ اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ خَيْرِ مَا سَأَلَكَ عَبْدُكَ وَنَبِيُّكَ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا عَاذَ بِهِ عَبْدُكَ وَنَبِيُّكَ اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْجَنَّةَ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَعُوْذُ بِكَ مِنَ النَّارِ وَمَا قَرَّبَ إِلَيْهَا مِنْ قَوْلٍ أَوْ عَمَلٍ وَأَسْأَلُكَ أَنْ تَجْعَلَ كُلَّ قَضَاءٍ قَضَيْتَهُ لِي خَيْرًا","latin":"Allâhümme innî es'elüke minel-hayri küllihî âcilihî ve âcilihî, mâ alimtü minhü ve mâ lem a'lem, ve eûzü bike mineş-şerri küllihî âcilihî ve âcilihî, mâ alimtü minhü ve mâ lem a'lem, Allâhümme innî es'elüke min hayri mâ se'eleke abdüke ve nebiyyüke, ve eûzü bike min şerri mâ âze bihî abdüke ve nebiyyüke, Allâhümme innî es'elükel-cennete ve mâ karrebe ileyhe min kavlin ev amel, ve eûzü bike minen-nâr, ve mâ karrebe ileyhe min kavlin ev amel. Ve es'elüke en tec'ale külle kadâin kadaytehu lî hayrâ.","tr":"Allâh'ım, bildiğim ve bilmediğim, acil ve ertelenmiş tüm iyilikleri Senden istiyorum; bildiğim ve bilmediğim, acil ve ertelenmiş tüm kötülüklerden Sana sığınıyorum. Allâh'ım, kulun ve Peygamberin'in Senden istediği iyilikleri istiyorum; kulun ve Peygamberin'in Senden sığındığı kötülüklerden Sana sığınıyorum. Allâh'ım, Senden cenneti ve onu yakınlaştıran söz ve amelleri istiyorum; cehennemden ve onu yakınlaştıran söz ve amellerden Sana sığınıyorum. Hakkımda hükmettiğin her kaderi hayırlı kılmanı istiyorum.","en":"O Allah! I ask You for all goodness, now and later on, that which I know and that which I do not know, and I seek refuge with You from all evil, now and later on, that which I know and that which I do not know. O Allah! I ask You the good that which your slave and Prophet (ﷺ) asked You for, and I seek refuge with You from the evil that from which your slave and Prophet (ﷺ) sought refuge. O Allah! I ask you for Paradise and what brings one closer to it of words or deeds, and I seek refuge from you from Hell and what brings one closer to it of words or deeds, and I ask you to make every destiny that You have prescribed for me good."},{"id":720,"title":"Kötü Düşünce ve Eylemlerden Korunma Duası","ref":"Sahih. Tirmizî: 3492","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_720.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ سَمْعِيْ وَمِنْ شَرِّ بَصَرِيْ وَمِنْ شَرِّ لِسَانِيْ وَمِنْ شَرِّ قَلْبِيْ وَمِنْ شَرِّ مَنِيِّيْ","latin":"Allâhümme innî eûzü bike min şerri sem'î, ve min şerri basarî, ve min şerri lisânî, ve min şerri kalbî, ve min şerri meniyyî.","tr":"Allâh'ım, işitmem in şerrinden, görmem in şerrinden, dilimin şerrinden, kalbimin şerrinden ve nefsimin şerrinden Sana sığınırım.\n\nŞekel bin Humeyd (r.a.) şöyle dedi: 'Peygamber'e (s.a.v.) geldim ve dedim ki: Ey Allah'ın Resûlü, bana bir sığınma duası öğret.' Bunun üzerine elimi tuttu ve şöyle dedi: 'De ki: (dua yukarıda belirtilmiştir.)'","en":"O Allah, I seek refuge in You from hearing evil, from seeing evil, from speaking evil, from the evils of my heart and the evils of my carnal desires.\n\nShakal bin Humaid (RA) said: \"I came to the Prophe t(ﷺ) and said: 'O Messenger of Allah (ﷺ), teach me a way of seeking refuge so that I may seek refuge by it.\" He (ﷺ) said: \"So he took my hand and said: 'Say: (the dua is mentioned above)"},{"id":721,"title":"Hastalık ve İlletten Korunma Duası","ref":"Sahih. Ebû Dâvûd: 1554","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_721.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبَرَصِ وَالْجُنُوْنِ وَالْجُذَامِ وَمِنْ سَيِّئِ الْأَسْقَامِ","latin":"Allâhümme innî eûzü bike minel-berasi vel-cünûni vel-cüzâmi, ve min seyyiil-eskâm.","tr":"Allâh'ım, alaca hastalığından, delilikten, cüzzamdan ve kötü hastalıklardan Sana sığınırım.","en":"O Allah, I seek refuge in Thee from leprosy, madness, elephantiasis, and evil diseases."},{"id":722,"title":"Kötü Amel ve Hastalıklardan Korunma Duası","ref":"Sahih. Mişkât: 2405","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_722.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ مُنْكَرَاتِ الْأَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ وَالْأَدْوَاءِ","latin":"Allâhümme innî eûzü bike min münkerâtil-ahlâkı vel-a'mâli vel-ehvâi vel-edvâi.","tr":"Allâh'ım, kötü ahlâktan, kötü amellerden, kötü hevâlardan ve hastalıklardan Sana sığınırım.","en":"O Allah, I seek refuge in you from evil morals, deeds, passions and diseases."},{"id":724,"title":"Allah'ın Sevgisi ve Salih Ameller İçin Dua","ref":"[1] Yani bunları yaparsanız günahlar silinir [2] Sahih. Tirmizî: 3235","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_724.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ فِعْلَ الْخَيْرَاتِ وَتَرْكَ الْمُنْكَرَاتِ وَحُبَّ الْمَسَاكِيْنِ وَأَنْ تَغْفِرَ لِي وَتَرْحَمَنِي وَإِذَا أَرَدْتَ فِتْنَةَ قَوْمٍ فَتَوَفَّنِيْ غَيْرَ مَفْتُوْنٍ وَأَسْأَلُكَ حُبَّكَ وَحُبَّ مَنْ يُحِبُّكَ وَحُبَّ عَمَلٍ يُقَرِّبُ إِلَى حُبِّكَ","latin":"Allâhümme innî es'elüke fi'lel-hayrâti, ve terkel-münkerâti, ve hubbeL-mesâkîni, ve en tağfira lî ve terhamenî ve izâ erâdte fitnete kavmin fe-teveffenî ğayra meftûn, ve es'elüke hubbeke ve hubbe men yühibbüke, ve hubbe amelin yükarribu ilâ hubbik.","tr":"Allâh'ım, iyi amelleri yapmayı, kötü amellerden uzak durmayı, fakirleri sevmeyi, beni bağışlamanı ve bana merhamet etmeni istiyorum. Bir kavmi imtihan etmeyi istersen, beni fitneye düşmeden vefat ettir. Senin sevgini, Seni sevenlerin sevgisini ve beni Senin sevgine yaklaştıracak amellerin sevgisini istiyorum.\n\nMuâz bin Cebel (r.a.) şöyle rivayet etti: 'Bir sabah Allah Resûlü (s.a.v.) sabah namazı için yanımıza gelmekte gecikti; güneş doğmak üzereydi. Sonra hızla çıktı, namaz için hazırlandı. Allah Resûlü (s.a.v.) namazı hızlıca kıldırdı. Selam verince yüksek sesle şöyle buyurdu: Olduğunuz yerde kalın. Sonra dönerek bize yaklaştı ve şöyle dedi: Bu sabah yanınıza gelemememin sebebini size anlatayım: Gece kalktım, abdest alıp gücüm yettiği kadar namaz kıldım; namazımda uyukladım ve derin uykuya daldım. Sonra Rabbimi en güzel surette gördüm. Dedi ki: Ey Muhammed! Dedim: Rabbim, emrine amadeyim! Dedi: Yüce topluluk (melekler) ne ile meşgul? Dedim: Bilmiyorum Rabbim. Bunu üç kez söyledi. Buyurdu: Avucunu omuzlarımın arasına koydu ve parmaklarının serinliğini göğsümde hissettim. Sonra her şey bana açıldı. Dedi ki: Ey Muhammed! Yüce topluluk ne ile meşgul? Dedim: Kefaret amelleriyle. Dedi: Onlar neler? Dedim: Cemaate yürümek, namazdan sonra mescitlerde oturmak, zorluklara rağmen abdesti tam almak. Dedi: Peki ya başka? Dedim: Yemek yedirmek, yumuşak konuşmak ve insanlar uyurken gece namazı kılmak. Dedi: Dile. Dedim: (Yukarıdaki dua). Allah Resûlü (s.a.v.) şöyle buyurdu: Gerçektir; onu öğrenin ve ezberleyin.' [1] Günahlar silinir [2] Sahih. Tirmizî: 3235]","en":"O Allah, I ask You to inspire me to do good deeds, and to abstain from bad deeds, and to love those who are poor, and to forgive me and have mercy on me, and if You wish a trial for Your servants, then make me die before falling into it. And I ask You to make me love You and to love those who love You, and to love the actions that get me closer to Your love.\n\nNarrated by Mu'adh bin Jabal (RA): \"One morning, the Messenger of Allah (ﷺ) was prevented from coming to us for Fajr Salat, until we were just about to look for the eye of the sun (meaning sunrise). Then he came out quickly, had the Salat prepared for. The Messenger of Allah (ﷺ) performed the Salat, and he performed his Salat in a relatively quick manner. When he said the Salam, he called aloud with his voice saying to us: 'Stay in your rows as you are.' Then he turned coming near to us, then he said: 'I am going to narrate to you what kept me from you this morning: I got up during the night, I performed Wudu and prayed as much as I was able to, and I dozed off during my Salat, and fell deep asleep. Then I saw my Lord, Blessed and Most High, in the best of appearances. He said: 'O Muhammad!' I said: 'My Lord here I am my Lord!' He said: 'What is it that the most exalted group busy themselves with?' I said: 'I do not know Lord.' And He said it three times.\" He said: \"So I saw Him place His Palm between my shoulders, and I sensed the coolness of His Fingertips between my breast. Then everything was disclosed for me, and I became aware. So He said: 'O Muhammad!' I said: 'Here I am my Lord!' He said: 'What is it that the most exalted group busy themselves with?' I said: 'In the acts that atone.' He said: 'And what are they?' I said: 'The footsteps to the congregation, the gatherings in the Masajid after the Salat, Isbagh Al-Wudu during difficulties.' [1] He said: 'Then what else?' I said: 'Feeding others, being lenient in speech, and Salat during the night while the people are sleeping.' He said: 'Ask.' I said: (The dua mentioned above) The Messenger of Allah (ﷺ) said: \"Indeed it is true, so study it and learn it.\" [2]"},{"id":725,"title":"Düşman ve Kıskançlıktan Korunma Duası","ref":"Hasen (Elbânî). Silsiletü's-Sahîha: 1540","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_725.json","ar":"اَللَّهُمَّ احْفَظْنِيْ بِالْإِسْلَامِ قَائِمًا، وَاحْفَظْنِيْ بِالْإِسْلَامِ قَاعِدًا، وَاحْفَظْنِيْ بِالْإِسْلَامِ رَاقِدًا، وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَاسِدًا اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ، وَأَعُوْذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ","latin":"Allâhümmehfaznî bil-islâmi kâimen, vehfaznî bil-islâmi kâiden, vehfaznî bil-islâmi râkiden, ve lâ tüşmit bî adüvven ve lâ hâsiden, Allâhümme innî es'elüke min külli hayrin hezâinühü bi-yedik, ve eûzü bike min külli şerrin hezâinühü biyadik.","tr":"Allâh'ım, ayaktayken beni İslâm ile koru; otururken beni İslâm ile koru; yatarken beni İslâm ile koru; düşmanımı veya kıskanımı bana sevindirilme. Allâh'ım, hazineleri Senin elinde olan her iyiliği Senden istiyorum; hazineleri Senin elinde olan her kötülükten Sana sığınıyorum.","en":"O Allah! Protect me with Islam when standing, and protect me with Islam when sitting down, and protect me with Islam when reclining, and do not make an enemy or envier gloat over me. O Allah, I ask you for every good whose treasuries are in Your Hand, and I seek refuge with you from every evil whose treasuries are in Your Hand."},{"id":727,"title":"Teşehhüd Sonrası Selam Öncesi Dua","ref":"Buhârî: 6370","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_727.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْبُخْلِ وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ وَأَعُوْذُ بِكَ مِنْ أَنْ أُرَدَّ إِلَى أَرْذَلِ الْعُمُرِ وَأَعُوْذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا وَأَعُوْذُ بِكَ مِنْ عَذَابِ الْقَبْرِ","latin":"Allâhümme innî eûzü bike minel-buhli, ve eûzü bike minel-cübni, ve eûzü bike min en üradde ilâ erzalil-ümüri, ve eûzü bike min fitnetid-dünyâ ve eûzü bike min azâbil-kabr.","tr":"Allâh'ım, cimrilikten Sana sığınırım; korkaklıktan Sana sığınırım; en kötü yaşlılığa döndürülmekten Sana sığınırım; dünyanın fitnesinden Sana sığınırım ve kabir azabından Sana sığınırım.\n\nSa'd bin Ebî Vakkâs (r.a.) bu cümleleri çocuklarına, bir öğretmenin yazıyı çocuklara öğrettiği gibi öğretirdi ve şöyle derdi: Allah Resûlü (s.a.v.) namazın sonunda tüm bu şeylerden sığınmayı talep ederdi. (Yukarıdaki dua belirtilmiştir.)","en":"O Allah, I seek Your protection from miserliness, I seek Your protection from cowardice, and I seek Your protection from being returned to feeble old age. I seek Your protection from the trials of this world and I seek Your protection from the torment of the grave.\n\nSaad ibn Abi Waqqas (RA) used to teach these sentences to his sons in the same way that a teacher teaches handwriting to children. And he used to say that the Messenger of Allah (ﷺ) used to seek refuge (in Allah) in all these matters towards the end of the prayer - (The dua is mentioned above)"},{"id":728,"title":"Geçmiş ve Gelecek Günahların Mağfireti İçin Dua","ref":"Müslim: 2719","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_728.json","ar":"اَللَّهُمَّ اغْفِرْ لِي خَطِيْئَتِيْ وَجَهْلِيْ وَإِسْرَافِي فِي أَمْرِيْ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي اَللَّهُمَّ اغْفِرْ لِي جِدِّيْ وَهَزَلِيْ وَخَطَئِيْ وَعَمْدِيْ وَكُلُّ ذَلِكَ عِنْدِيْ اَللَّهُمَ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي أَنْتَ الْمُقَدِّمُ وَأَنْتَ الْمُؤَخِّرُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ","latin":"Allâhümmağfir lî hatîetî, ve cehlî, ve isrâfî fî emrî, ve mâ Ente a'lemü bihî minnî. Allâhümmağfir lî ciddî ve hezlî, ve hatâî ve amdî, ve küllü zâlike indî. Allâhümmağfir lî mâ kaddamtü ve mâ ahhartü, ve mâ asrartü, ve mâ a'lentü, ve mâ Ente a'lemü bihî minnî. Entel-Mükaddemü, ve Entel-Mü'ahhiru; ve Ente alâ külli şeyin kadîr.","tr":"Allâh'ım, hatalarımı, bilgisizliğimi ve işlerimdeki aşırılığımı bağışla; Senin bunları benden daha iyi bildiğini de (bağışla). Allâh'ım, ciddi ve şakada, hata ve kasıtta yaptıklarımı bağışla; bunların hepsi bendedir. Allâh'ım, geçmişte ve gelecekte, gizlide ve açıkta yaptıklarımı bağışla; Senin bunları benden daha iyi bildiğini de (bağışla). Sen Mükaddim'sin ve Mü'ahhir'sin; her şeye gücün yeter.","en":"O Allah, forgive me my faults, my ignorance, my immoderation in my concerns. And Thou art better aware (of my affairs) than myself. O Allah, grant me forgiveness (of the faults which I committed) seriously or otherwise (and which I committed inadvertently and de- liberately. All these (failings) are in me. O Allah, grant me forgiveness from the fault which I did in haste or deferred, which I committed in privacy or in public and Thou art better aware of (them) than myself. Thou art the First and the Last and over all things Thou art Omnipotent."},{"id":730,"title":"Uyumadan Önce Korunma Duası","ref":"Müslim: 2717","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_730.json","ar":"اَللَّهُمَّ لَكَ أَسْلَمْتُ وَبِكَ آمَنْتُ وَعَلَيْكَ تَوَكَّلْتُ وَإِلَيْكَ أَنَبْتُ وَبِكَ خَاصَمْتُ اَللَّهُمَّ إِنِّي أَعُوْذُ بِعِزَّتِكَ لَا إِلَهَ إِلَّا أَنْتَ أَنْ تُضِلَّنِيْ أَنْتَ الْحَيُّ الَّذِيْ لَا يَمُوْتُ وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ","latin":"Allâhümme leke eslemtü, ve bike âmentü, ve aleyke tevekkeltu, ve ileyke enebtü, ve bike hâsemtü, Allâhümme innî eûzü bi-izzatike, lâ ilâhe illâ ente en tudıllenî, entel-hayyulleżî lâ yemûtu, vel-cinnü vel-insü yemûtûn.","tr":"Allâh'ım, Sana teslim oldum; Sana iman ettim; Sana dayandım; Sana yöneldim; [yardımınla] tartıştım [savundum ve mücadele ettim]. Senden başka ilâh olmayan Senin izzetine sığınırım; beni saptırma. Sen ölmeyen Hayy'sın; cinler ve insanlar ölür.","en":"O Allah, to You I did submit, and in You I did believe, and on You I did rely, and to You I did return, and with Your [help] I did dispute [defend and fight]. I seek refuge in Your Might, there is no deity [worthy of worship] but You, [that You] let me not go astray. You are the Ever living who does not perish, while the jinn and mankind perish."},{"id":731,"title":"Cennet ve Cehennemden Kurtuluş Duası","ref":"Hasen (Arnaut). el-Ezkâr 1/340","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_731.json","ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مُوْجِبَاتِ رَحْمَتِكَ وَعَزَائِمَ مَغْفِرَتِكَ وَالسَّلَامَةَ مِنْ كُلِّ إِثْمٍ وَالْغَنِيْمَةَ مِنْ كُلِّ بِرٍّ وَالْفَوْزَ بِالْجَنَّةِ وَالنَّجَاةَ بِعَوْنِكَ مِنَ النَّارِ","latin":"Allâhümme innâ nes'elüke mûcibâti rahmetike, ve azâime mağfiretike, ves-selâmete min külli ismin, vel-ğanîmete min külli birrin, vel-fevze bil-cenneti, ven-necâte bi-avnike minen-nâr.","tr":"Allâh'ım, rahmetini gerektiren şeyleri, mağfiretini kesinleştirecek sebepleri, her günahtan kurtuluşu, her iyilikten nasip almayı, cenneti kazanmayı ve yardımınla ateşten kurtuluşu Senden istiyorum.","en":"O Allah! I beg You for that which incites Your Mercy and the means of Your forgiveness, safety from every sin, the benefit from every good deed, success in attaining Jannah and deliverance from Fire."},{"id":732,"title":"Yaşlılıkta Rızık Duası","ref":"Sahih (Süyûtî). Câmiu's-Sağîr: 1485","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_732.json","ar":"اَللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَيَّ عِنْدَ كِبَرِ سِنِّيْ وَانْقِطَاعِ عُمُرِيْ","latin":"Allâhümmec'al evse'a rızkıke aleyye inde kiberi sinnî venkıtâi ümürî.","tr":"Allâh'ım, yaşlılığımda ve ömrümün son günlerinde rızkımı en geniş şekilde ver.","en":"O Allah, make my sustenance the most plentiful in my old age and during the last days of my life."},{"id":734,"title":"Allah'tan Lütuf ve Merhamet Dileme Duası","ref":"Sahih (Elbânî). Silsiletü's-Sahîha: 1543","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_734.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ فَإِنَّهُ لَا يَمْلِكُهَا إِلَّا أَنْتَ","latin":"Allâhümme innî es'elüke min fadlike ve rahmetike fe innehu lâ yemlikühe illâ ente.","tr":"Allâh'ım, Senin lütfunu ve merhametini istiyorum; çünkü bunlara yalnızca Sen sahipsin.\n\nArdından hediye olarak kızartılmış bir keçi getirildi. Bunun üzerine Peygamberimiz (s.a.v.) şöyle buyurdu: 'Bu Allah'ın bir lütfudur. Şimdi rahmetini bekliyoruz.'","en":"O Allah, I beseech you for your favour and your mercy, for indeed none possesses that except you.\n\nThen a fried goat was presented to Him as a gift. After that Prophet (ﷺ) said, “This is a favor from Allah. Now we are waiting for his mercy.”"},{"id":735,"title":"Kaza ve Musibet Koruma Duası","ref":"Sahih. Ebû Dâvûd: 1552","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_735.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْهَدْمِ وَأَعُوْذُ بِكَ مِنَ التَّرَدِّيْ وَأَعُوْذُ بِكَ مِنَ الْغَرَقِ وَالْحَرَقِ وَالْهَرَمِ وَأَعُوْذُ بِكَ أَنْ يَتَخَبَّطَنِيَ الشَّيْطَانُ عِنْدَ الْمَوْتِ وَأَعُوْذُ بِكَ أَنْ أَمُوْتَ فِي سَبِيْلِكَ مُدْبِرًا وَأَعُوْذُ بِكَ أَنْ أَمُوْتَ لَدِيْغًا","latin":"Allâhümme innî eûzü bike minel-hedmi, ve eûzü bike minet-teraddî, ve eûzü bike minel-ğarakı, vel-haraki vel-haremi, ve eûzü bike en yetehabbeteniyeş-şeytânü indel-mevti, ve eûzü bike en emûte fî sebîlike müdbiren, ve eûzü bike min en emûte ledîğâ.","tr":"Allâh'ım, enkaz altında kalmaktan Sana sığınırım; yüksekten düşmekten Sana sığınırım; boğulmaktan, yangından ve ihtiyarlıktan Sana sığınırım. Ölüm anında şeytanın beni kandırmasından Sana sığınırım; Senin yolunda savaşırken geri dönerek ölmekten Sana sığınırım; zehirli bir yaratığın ısırmasından ölmekten Sana sığınırım.","en":"O Allah I seek refuge in You from [a death caused by] demolition, and I seek refuge in You from [a death caused by] tumbling from a hight, and I seek refuge in You from drowning, [a death caused by] burning [due to fire], old and infirm age. And I seek refuge in You from the deception of the devil at the moments of death, and I seek refuge in You from dying while fleeing [the battlefield] during a battle [fought] in Your sake, and I seek refuge in You from dying from a [venomous] sting."},{"id":736,"title":"Açlık ve İhanetten Korunma Duası","ref":"Hasen. Ebû Dâvûd: 1547","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_736.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْجُوْعِ فَإِنَّهُ بِئْسَ الضَّجِيْعُ وَأَعُوْذُ بِكَ مِنَ الْخِيَانَةِ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ","latin":"Allâhümme innî eûzü bike minel-cû'i, fe-innehü bi'sed-decî'u, ve eûzü bike minel-hıyâneti, fe-innehâ bi'setil-bitâneh.","tr":"Allâh'ım, açlıktan Sana sığınırım; zira o ne kötü bir yataktaşıdır. İhanetten Sana sığınırım; zira o ne kötü bir sırdaştır.","en":"O Allah, I seek refuge with You from hunger, for it is the worst bedfellow. And I seek refuge in You from treachery, for it is the worst of associates."},{"id":737,"title":"Fakirlik ve Zilletten Korunma Duası","ref":"Sahih. Ebû Dâvûd: 1544","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_737.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْفَقْرِ، وَالْقِلَّةِ، وَالذِّلَّةِ، وَأَعُوْذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ","latin":"Allâhümme innî eûzü bike minel-fakri, vel-killeti, vez-zilleti, ve eûzü bike min en azlime ev üzleme.","tr":"Allâh'ım, yoksulluktan, kıtlıktan ve zilletten Sana sığınırım; zulmetmekten ve zulme uğramaktan Sana sığınırım.","en":"O Allah, I seek refuge in You from absolute poverty, paucity, humiliation, and I seek refuge in You from oppressing or being oppressed."},{"id":738,"title":"Kötü Komşudan Korunma Duası","ref":"Hasen (Elbânî). Sahîhu'l-Câmi: 1290","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_738.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ جَارِ السُّوْءِ فِي دَارِ الْمُقَامَةِ فَإِنَّ جَارَ الْبَادِيَةِ يَتَحَوَّلُ","latin":"Allâhümme innî eûzü bike min câris-sû'i fî dâril-mukâmeh, fe-inne cârel-bâdiyeti yetehavvel.","tr":"Allâh'ım, ikamet ettiğim yerde kötü bir komşudan Sana sığınırım; zira göçebe komşu göç edip gider.","en":"O Allah! Indeed I take refuge in You from a bad neighbour leads astray (is a bad influence)."},{"id":739,"title":"Faydalı İlim İçin Dua","ref":"Sahih. Nesâî: 5470","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_739.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَقَلْبٍ لَا يَخْشَعُ وَدُعَاءٍ لَا يُسْمَعُ وَنَفْسٍ لَا تَشْبَعُ اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ","latin":"Allâhümme innî eûzü bike min ilmin lâ yenfa'u, ve kalbin lâ yahşa'u, ve duâin lâ yüsme'u, ve nefsin lâ teşba'u. Allâhümme innî eûzü bike min hâülâil-erba'.","tr":"Allâh'ım, fayda vermeyen ilimden, huşu duymayan kalpten, kabul olmayan duadan ve doymayan nefisten Sana sığınırım. Allâh'ım, bu dört şeyden Sana sığınırım.","en":"O Allah, I seek refuge with You from knowledge that is of no benefit, a heart that is not humble, a supplication that is not heard and a soul that is not satisfied. O Allah, I seek refuge with You from these four."},{"id":740,"title":"Kötü Komşudan Korunma Duası","ref":"Hasen (Elbânî). Sahîhu'l-Câmi: 1299","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_740.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ يَوْمِ السُّوْءِ وَمِنْ لَيْلَةِ السُّوْءِ وَمِنْ سَاعَةِ السُّوْءِ وَمِنْ صَاحِبِ السُّوْءِ وَمِنْ جَارِ السُوْءِ فِي دَارِ الْمُقَامَةِ","latin":"Allâhümme innî eûzü bike min yevmis-sû'i, ve min leyletis-sû'i, ve min sâ'atis-sû'i, ve min sâhibis-sû'i, ve min câris-sû'i fî dâril-mukâmeh.","tr":"Allâh'ım, kötü günden, kötü geceden, kötü vakitten, kötü arkadaştan ve ikamet ettiğim yerde kötü komşudan Sana sığınırım.","en":"O Allah, indeed I seek refuge in You from a bad day and a bad night and a bad time and a bad partner and from having a bad neighbor near my place of residence."},{"id":742,"title":"Din İlmini Artırma Duası","ref":"Buhârî: 143","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_742.json","ar":"اَللَّهُمَّ فَقِّهْهُ فِي الدِّيْنِ","latin":"Allâhümme fakkıh-hü fid-dîn.","tr":"Allâh'ım, onu dinde derin anlayış sahibi kıl.","en":"O Allah! Make him a learned scholar in religion (Islam)."},{"id":743,"title":"Şirkten Korunmak İçin Güçlü Dua (Mesnûn Dua)","ref":"Hasen Ligayrihi (Elbânî). Sahîhu't-Terğîb: 36","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_743.json","ar":"اَللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ أَنْ نُشْرِكَ بِكَ شَيْئًا نَعْلَمُهُ وَنَسْتَغْفِرُكَ لِمَا لَا نَعْلَمُهُ","latin":"Allâhümme innâ neûzü bike min en nüşrike bike şey'en na'lemüh, ve nestağfiruke limâ lâ na'lemüh.","tr":"Allâh'ım, bilerek Sana herhangi bir şeyi ortak koşmaktan Sana sığınırız. Bilmeyerek [Sana ortak koşmuş olmaktan da] senden bağışlanma dileriz.","en":"O Allah, We seek refuge in You from ascribing any partner to you knowingly. We also seek your forgiveness from unknowingly [ascribing partners to you]."},{"id":744,"title":"Öğrenim ve Akademik Başarı İçin Dua","ref":"Sahih. Silsiletü's-Sahîha: 3151, Tirmizî: 3599","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_744.json","ar":"اَللَّهُمَّ انْفَعْنِيْ بِمَا عَلَّمْتَنِيْ وَعَلِّمْنِيْ مَا يَنْفَعُنِيْ وَارْزُقْنِيْ عِلْمًا تَنْفَعُنِيْ بِهِ","latin":"Allâhümmen fa'nî bimâ allemtenî ve allimnî mâ yenfa'unî verzuknî ilmen tenfa'unî bih.","tr":"Allâh'ım, bana öğrettiklerinle beni faydalandır, bana fayda verecek ilmi öğret ve beni bu ilimle rızıklandır.","en":"O Allah! Grant me benefit in what you have taught me, and teach me useful knowledge and provide me with knowledge that will benefit me."},{"id":746,"title":"Allah'ın En Büyük İsmiyle Bağışlanma Duası","ref":"Sahih. Nesâî: 1301","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_746.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اَللَّهُ بِأَنَّكَ الْوَاحِدُ الْأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَّهُ كُفُوًا أَحَدٌ أَنْ تَغْفِرَ لِي ذُنُوْبِيْ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ","latin":"Allâhümme innî es'elüke yâ Allah! Bi-enneke'l-Vâhidül-Ehadüs-Samedüllezî lem yelid ve lem yûled, ve lem yekün lehû küfüven ehad, en tağfire lî zünûbî, inneke Entel-Ğafûrür-Rahîm.","tr":"Allâh'ım, Senden şunu istiyorum, ey Allah! Sen Bir'sin, Tek'sin, Samed'sin; doğurmamış ve doğurulmamışsın; Sana hiçbir denk de yoktur. Günahlarımı bağışlamanı istiyorum; zira Sen çok bağışlayan, çok merhamet edensin.\n\nDuasını duyan Allah Resûlü (s.a.v.) üç kez 'Bağışlandı' buyurdu.","en":"O Allah, I ask of You, O Allah, as You are the One, the Only, the Self-Sufficient Master, Who begets not nor was He begotten, and there is None equal or comparable to Him, forgive me my sins, for You are the Oft-Forgiving, Most Merciful.\n\nListening to his prayers, The Messenger of Allah (ﷺ) said: \"He has been forgiven,\" three times."},{"id":747,"title":"Duanın Kabulü İçin Allah'ın En Büyük İsmiyle Dua","ref":"Sahih. Nesâî: 1300","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_747.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدُ لَا إِلَهَ إِلَّا أَنْتَ الْمَنَّانُ بَدِيْعُ السَّمَوَاتِ وَالْأَرْضِ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ يَا حَيُّ يَا قَيُّومُ إِنِّي أَسْأَلُكَ","latin":"Allâhümme innî es'elüke bi-enne lekel-hamd, lâ ilâhe illâ entel-mennânü bedî'us-semâvâti vel-ard, yâ zel-celâli vel-ikrâm! Yâ hayyu yâ kayyûm! İnnî es'elük.","tr":"Allâh'ım, hamd Sana mahsus olduğu için Senden istiyorum; Senden başka ilah yoktur; Sen Mennân'sın, gökleri ve yeri yoktan var edensin; ey Celâl ve İkrâm sahibi! Ey Diri olan, ey her şeyi ayakta tutan! Senden istiyorum.\n\nEnes b. Mâlik (r.a.) şunu anlattı: 'Allah Resûlü'nün (s.a.v.) yanında oturuyordum; bir adam ayakta namaz kılıyordu. Rüku edip secde ettikten ve teşehhüt okuduktan sonra dua etti; duasında şöyle dedi: (Yukarıdaki dua zikredildi.) Bunun üzerine Peygamberimiz (s.a.v.): 'Ne ile dua ettiğini biliyor musunuz?' diye sordu. Onlar: 'Allah ve Resûlü daha iyi bilir' dediler. O (s.a.v.) şöyle buyurdu: 'Canımı elinde tutan'a yemin olsun, o Allah'a en büyük ismiyle dua etti; ki o isimle çağrıldığında icabet eder, o isimle istenildiğinde verir.'","en":"O Allah, indeed I ask You since all praise is due to You, there is none worthy of worship but You, the Bestower, the Creator of the heavens and earth, O Possessor of majesty and honor, O Ever-living, O-Eternal, I am asking to You.\n\nIt was narrated that Anas bin Malik (RA) said: \"I was sitting with the Messenger of Allah (ﷺ) and a man was standing and praying. When he bowed, prostrated and recited the tashahhud, he supplicated, and in his supplication he said: (The dua is mentioned above) Then the Prophet (ﷺ) said: 'Do you know what he has supplicated with?' They said: \"Allah (SWT) and His Messenger know best. He (ﷺ) said: 'By the One in Whose Hand is my soul, he called upon Allah by His greatest Name, which, if He is called by it, He responds, and if He is asked by it, He gives.'"},{"id":750,"title":"Hidayet ve Ebedî Mutluluk Duası (Mesnun Dua)","ref":"Sahih. Nesâî: 1305","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_750.json","ar":"اَللَّهُمَّ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِيْ، وَتَوَفَّنِيْ إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي، اَللَّهُمَّ وَأَسْأَلُكَ خَشْيَتَكَ فِي الْغَيْبِ وَالشَّهَادَةِ وَأَسْأَلُكَ كَلِمَةَ الْحَقِّ فِي الرِّضَا وَالْغَضَبِ، وَأَسْأَلُكَ الْقَصْدَ فِي الْفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لَا يَنْفَدُ، وأَسْأَلُكَ قُرَّةَ عَيْنٍ لَا تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأْلُكَ لَذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ، فِي غَيْرِ ضَرَّاءَ مُضِرَّةٍ، وَلَا فِتْنَةٍ مُضِلَّةٍ، اَللَّهُمَّ زَيِّنَّا بِزِينَةِ الْإِيمَانِ، وَاجْعَلْنَا هُدَاةً مُهْتَدِينَ","latin":"Allâhümme bi 'ilmikel-ğaybi ve kudretike 'alel-halkı ahyinî mâ 'alimtel-hayâte hayren lî, ve teveffenî idhâ 'alimtel-vefâte hayren lî. Allâhümme ve es'elüke haşyeteke fîl-ğaybi veş-şehâdeti ve es'elüke kelimetal-hakki fîr-rıdâ vel-ğadabi, ve es'elükel-kasde fîl-fakri vel-ğınâ, ve es'elüke ni'men lâ yenfedü ve es'elüke kurrate 'aynin lâ tankati'u ve es'elüker-rıdâ ba'del-kadâi, ve es'elüke bardel-'ayşi ba'del-mevti, ve es'elüke ledhdhetennazari ilâ vechike veş-şevka ilâ likâike fî ğayri darrâe mudırratin ve lâ fitneten mudılleti, Allâhümme zeyyinnâ bizînetil-îmâni vec'alnâ hüdâten mühtedin","tr":"Ey Allah'ım! Gaybi bilgin ve yaratılış üzerindeki kudretin hakkı için, yaşamayı benim için hayırlı gördükçe beni yaşat; ölümü benim için hayırlı gördüğünde canımı al. Ey Allah'ım! Senden, gizlide ve açıkta Seni korkmamı dilerim. Rıza halinde de öfke halinde de doğru söz söylemememi dilerim. Senden zenginlikte de fakirlikte de ölçülü olmamı dilerim. Senden tükenmeyen bir nimet ve kesilmeyen göz aydınlığı dilerim. Kazandan sonra hoşnutluk, ölümün ardından kolay bir yaşam dilerim. Senden yüzüne bakmanın lezzetini ve zarar veren bir musibete ya da saptıran bir fitneye uğramaksızın Sana kavuşmanın özlemini dilerim. Ey Allah'ım! Bizi iman süsüyle süsle ve bizi hidayet eden, hidayete eren kimselerden kıl.\n\n'Atâ ibn es-Sâib (rahimehullah) babasından rivayet etmiştir: «Ammâr ibn Yâsir (radıyallahu anh) bize namaz kıldırdı ve namazı kısa tuttu. Bazı insanlar ona: 'Namazı kısa tuttun' dediler. O da: 'Yine de Allah Resûlü'nden (sallallahu aleyhi ve sellem) işittiğim duaları okudum' dedi. Kalktığında bir adam onu takip ederek o duayı sordu, sonra gelip insanlara anlattı: (Yukarıda geçen dua)»","en":"O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive so long as You know that living is good for me and cause me to die when You know that death is better for me. O Allah, cause me to fear You in secret and in public. I ask You to make me true in speech in times of pleasure and of anger. I ask You to make me moderate in times of wealth and poverty. And I ask You for everlasting delight and joy that will never cease. I ask You to make me pleased with that which You have decreed and for an easy life after death. I ask You for the sweetness of looking upon Your face and a longing to meet You in a manner that does not entail a calamity that will bring about harm or a trial that will cause deviation. O Allah, beautify us with the adornment of faith and make us among those who guide and are rightly guided.\n\n‘Ata bin As-Sa'ib (R) narrated that his father said: \"Ammar bin Yasir (RA) led us in prayer and he made it brief. Some of the people said to him: 'You made the prayer sort (or brief).' He said: 'Nevertheless I still recited supplications that I heard from the Messenger of Allah (ﷺ).' When he got up and left, a man followed him and asked him about that supplication, then he came and told the people: (The dua is mentioned above)"},{"id":751,"title":"Allah'ın Sevgisi ve Faydalı Arkadaşlar İçin Dua","ref":"Hasen (İbn Hacer). Tahrîcü Mişkât: 3/31","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_751.json","ar":"اَللَّهُمَّ ارْزُقْنِيْ حُبَّكَ وَحُبَّ مَنْ يَنْفَعُنِيْ حُبُّهُ عِنْدَكَ اَللَّهُمَّ مَا رَزَقْتَنِيْ مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُحِبُّ اَللَّهُمَّ وَمَا زَوَيْتَ عَنِّيْ مِمَّا أُحِبُّ فَاجْعَلْهُ لِي فَرَاغًا فِيمَا تُحِبُّ","latin":"Allâhümmer-zuknî hubbeke ve hubbe men yenfe'unî hubbühû 'indeke. Allâhümme mâ razaktenî mimmâ uhibbu fec'alhü kuvveten lî fîmâ tuhibbu. Allâhümme ve mâ zeveynte 'annî mimmâ uhibbu fec'alhü ferâğen lî fîmâ tuhibbu","tr":"Ey Allah'ım! Bana Senin sevgini ve katında sevgisi bana fayda verecek kimselerin sevgisini nasip et. Ey Allah'ım! Sevdiğim şeylerden bana rızık olarak verdiklerini, sevdiğin şeyler için güç kaynağı kıl. Ey Allah'ım! Sevdiğim şeylerden benden uzaklaştırdıklarını ise sevdiğin şeyler için boş vakit kıl.","en":"O Allah grant me Your love and the love of those whose love will benefit me with You. O Allah, whatever you have provided me of that which I love, then make it strength for me for that which You love. O Allah, and what you have kept from me of that which I love, then make it for me a period of rest in that which You love."},{"id":752,"title":"Bağışlanma ve Temizlenme Duası","ref":"Sahih. Nesâî: 402","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_752.json","ar":"اَللَّهُمَّ طَهِّرْنِيْ مِنَ الذُّنُوبِ وَالْخَطَايَا اَللَّهُمَّ نَقِّنِيْ مِنْهَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الدَّنَسِ، اَللَّهُمَّ طَهِّرْنِيْ بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ","latin":"Allâhümme tahhirnî mined-dünûbi vel-hatâyâ. Allâhümme nakkınî minhâ kemâ yunaккas-sevbül-ebyadu mined-denesi. Allâhümme tahhirnî bis-selci vel-beredi vel-mâil-bâridi","tr":"Ey Allah'ım! Beni günahlardan ve hatalardan temizle. Ey Allah'ım! Beni onlardan, beyaz elbisenin kirden temizlendiği gibi temizle. Ey Allah'ım! Beni kar, dolu ve soğuk su ile temizle.","en":"O Allah, purify me of sin and error, O Allah cleanse me of it as a white garment is cleansed of dirt, O Allah purify me with snow and hail and cold water."},{"id":753,"title":"Kabir Azabından Korunma Duası","ref":"Sahih. Ebû Dâvûd: 1376","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_753.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَسُوْءِ الْعُمُرِ، وَفِتْنَةِ الصَّدْرِ، وَعَذَابِ الْقَبْرِ","latin":"Allâhümme innî e'ûzü bike minel-cübni vel-buhli ve sûil-'ümüri ve fitnetis-sadri ve 'azâbil-kabr","tr":"Ey Allah'ım! Sana korkudan, cimrilikten, düşkünlük çağına ulaşmaktan, göğsün fitnesinden ve kabir azabından sığınırım.","en":"O Allah, I seek refuge with You from cowardice, miserliness, reaching the age of second childhood, the trials of the heart and the torment of the grave."},{"id":754,"title":"Cehennem Ateşinden ve Kabir Azabından Korunma Duası","ref":"Sahih. Nesâî: 5519","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_754.json","ar":"اَللَّهُمَّ رَبَّ جِبْرَائِيْلَ وَمِيْكَائِيْلَ ورَبَّ إِسْرَافِيلَ أَعُوذُ بِكَ مِنْ حَرِّ النَّارِ وَمِنْ عَذَابِ الْقَبْرِ","latin":"Allâhümme Rabbe Cibrâîle ve Mîkâîle ve Rabbe İsrâfîle, e'ûzü bike min harrin-nâri ve min 'azâbil-kabr","tr":"Ey Allah'ım! Cebrail, Mikail ve İsrafil'in Rabbi! Cehennem ateşinin hararetinden ve kabir azabından Sana sığınırım.","en":"O Allah, Lord of Gabriel and Michael, and lord of Israfel, I seek refuge in You from the heat of the hell fire, and from the torment of the grave."},{"id":755,"title":"Doğru Kararlar İçin Allah'ın Yardımını Dileme Duası","ref":"Sahih (el-Vâdi'î). Sahîhü'l-Müsned: 322","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_755.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ وَأَسْأَلُكَ أَنْ تَعْزِمَ لِي عَلَى رُشْدِ أَمْرِيْ","latin":"Allâhümme innî e'ûzü bike min şerri nefsî ve es'elüke en ta'zime lî 'alâ rüşdi emrî","tr":"Ey Allah'ım! Nefsimin şerrinden Sana sığınırım ve işlerimin doğrusunu yapmakta bana kararlılık vermeni Senden dilerim.","en":"Ya Allah! I seek refuge in You from harm of myself and I ask you for guidence and steadfastness to do right things"},{"id":756,"title":"Tüm Günahlar ve Hatalar İçin Bağışlanma Duası","ref":"Sahih (İbnü'l-Kayyim). el-Vâbilü's-Sayyib: s. 199","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_756.json","ar":"اَللَّهُمَّ اغْفِرْ لِي مَا أَسْرَرْتُ وَمَا أَعْلَنْتُ وَمَا أَخْطَأْتُ وَمَا تَعَمَّدْتُ وَمَا عَلِمْتُ وَمَا جَهِلْتُ","latin":"Allâhümmagfir lî mâ esrartu ve mâ e'lentu ve mâ ahta'tü ve mâ te'ammedtü ve mâ 'alimtü ve mâ cehiltü","tr":"Ey Allah'ım! Gizlide ve açıkta işlediğim, hataen yaptığım, kasıtlı olarak yaptığım, bilerek yaptığım ve bilmeyerek yaptığım günahlarımı bağışla.","en":"O Allah, grant me forgiveness from the fault which I committed in privacy or in public, which I mistakenly did, which I did deliberately, which I did knowingly and which I did unknowingly."},{"id":758,"title":"Borçtan Kurtulma ve Mali Sorunlar İçin Güçlü Dua","ref":"Müslim: 2713","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_758.json","ar":"اَللَّهُمَّ رَبَّ السَّمَوَاتِ وَرَبَّ الْأَرْضِ، وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيْلِ وَالْفُرْقَانِ، أَعُوْذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ، اَللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اِقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","latin":"Allâhümme Rabbes-semâvâti ve Rabbel-ardı ve Rabbel-'Arşil-'Azîm, Rabbenâ ve Rabbe külli şey'in, fâlikal-habbi ven-nevâ, ve münzilet-Tevrâti vel-İncîli vel-Furkân, e'ûzü bike min şerri külli şey'in Ente âhizün binâsiyetihî. Allâhümme Entel-Evvelü fe-leyse kableke şey'ün, ve Entel-Âhiru fe-leyse ba'deke şey'ün, ve Entez-Zâhiru fe-leyse fevkake şey'ün, ve Entel-Bâtınü fe-leyse dûneke şey'ün, ikdi 'anneD-deyne ve eğninâ minel-fakr","tr":"Ey Allah'ım! Göklerin Rabbi, yerin Rabbi ve yüce Arş'ın Rabbi, Rabbimiz ve her şeyin Rabbi, tohumu ve çekirdeği yaran, Tevrat'ı, İncil'i ve Furkan'ı (Kur'ân-ı Kerîm) indiren! Perçemini tuttuğun (üzerinde tam hâkimiyetin olan) her şeyin şerrinden Sana sığınırım. Ey Allah'ım! Sen Evvel'sin, Senden önce hiçbir şey yoktur; Sen Âhir'sin, Senden sonra hiçbir şey yoktur; Sen Zâhir'sin, Senden üstte hiçbir şey yoktur; Sen Bâtın'sın, Senden ötede hiçbir şey yoktur. Bizden borç yükünü kaldır ve bizi fakirlikten kurtar.","en":"O Allah. the Lord of the Heavens and the Lord of the Earth and Lord of the Magnificent Throne, our Lord, and the Lord of evervthing, the Splitter of the grain of corn and the datestone (or fruit kernal), the Revealer of Torah and Injil and Criterion (the Holy Qur'an), I seek refuge in Thee from the evil of every- thing Thou art to sieze by the forelock (Thou hast perfect control over it). O Allah, Thou art the First, there is naught before Thee, and Thou art the Last and there is naught after Thee, and Thou art Evident and there is nothing above Thee, and Thou art Innermost and there is nothing beyond Thee. Remove the burden of debt from us and relieve us from want."},{"id":759,"title":"Hidayet ve Aile Bereketi İçin Dua","ref":"Sahih. Sahih Edebü'l-Müfred: 630","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_759.json","ar":"رَبَّنَا أَصْلِحْ بَيْنَنَا، وَاهْدِنَا سَبِيلَ الْإِسْلَامِ، وَنَجِّنَا مِنَ الظُّلُمَاتِ إِلَى النُّورِ، وَاصْرِفْ عَنَّا الْفَوَاحِشَ مَا ظَهْرَ مِنْهَا وَمَا بَطَنَ، وَبَارِكْ لَنَا فِي أَسْمَاعِنَا وَأَبْصَارِنَا وَقُلُوبِنَا وَأَزْوَاجِنَا وَذُرِّيَّاتِنَا، وَتُبْ عَلَيْنَا إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ، وَاجْعَلْنَا شَاكِرِينَ لِنِعْمَتِكَ، مُثْنِينَ بِهَا، قَائِلِينَ بِهَا، وَأَتْمِمْهَا عَلَيْنَا","latin":"Rabbenâ aslih beynenâ vehdine sebîlel-İslâm, ve neccîne minez-zulümâti ilen-nûr, vasrif 'annel-fevâhişe mâ zahera minhâ ve mâ betana ve bârik lenâ fî esmâ'inâ ve ebsârinâ ve kulûbinâ ve ezvâcinâ ve zürriyyâtinâ ve tub 'aleynâ inneke Entet-Tevvâbür-Rahîm, vec'alnâ şâkirîne li-ni'metike müsniîne bihâ kâilîne bihâ ve etmimhâ 'aleynâ","tr":"Rabbimiz! Aramızı düzelt ve bizi İslâm yoluna hidayet et. Bizi karanlıklardan (kurtarıp) nura çıkar. Açık ve gizli olan fuhşiyatı bizden uzaklaştır. Kulaklarımızda, gözlerimizde, kalplerimizde, eşlerimizde ve çocuklarımızda bize bereket ver. Bize tevbe ile dön, zira Sen tevbeleri çok kabul edensin, çok merhametlisin. Bizi nimetine şükredenlerden, onu övenlerden ve ilan edenlerden kıl. Ve onu bizim üzerimizde tamamla.\n\nAbdullah ibn Mes'ûd (radıyallahu anh)'dan rivayet edilmiştir: Namaz kılarken oturuşlarda ne söyleyeceğimizi bilmiyorduk. Allah'ın Resûlü (sallallahu aleyhi ve sellem) (Allah tarafından) öğretildi. Sonra aynı şekilde rivayeti aktardı. Ardından şöyle dedi: Bize ayrıca başka kelimeleri de öğretirdi; fakat onları tahiyyatı öğrettiği gibi öğretmezdi: (Yukarıda geçen dua)","en":"Our Lord, make peace between us and guide us on the path of Islam. Save us from the darkness (and bring us) to the light. Remove acts of deviance from us, both open and hidden. Bless us in our ears, our eyes, our hearts, our wives and our children. Turn to us. You are the Ever-Turning, Most Merciful. Make us thankful for Your blessing and make us among those who give praise for it and proclaim it. Perfect it for us.\n\nNarrated Abdullah ibn Mas'ud (RA): We did not know what we should say when we sat during prayer. The Messenger of Allah (ﷺ) was taught (by Allah). He then narrated the tradition to the same effect. Then He said: He used to teach us also some other words, but he did not teach them as he taught us the tashahhud: (The dua is mentioned above)"},{"id":760,"title":"Cennet ve Hayat Bereketleri İçin Güçlü Dua","ref":"Sahih (Heysemî). Mecma'ü'z-Zevâid: 10/108","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_760.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ الْمَسْأَلَةِ، وَخَيْرَ الدُّعَاءِ، وَخَيْرَ النَّجَاحِ، وَخَيْرَ الْعَمَلِ، وَخَيْرَ الثَّوَابِ، وَخَيْرَ الْحَيَاةِ، وَخَيْرَ الْمَمَاتِ، وَثَبِّتْنِيْ، وَثَقِّل مَوَازِينِيْ، وَحَقِّقْ إِيْمَانِيْ، وَارْفَعْ دَرَجَاتِيْ، وَتَقَبَّلْ صَلَاتِيْ، وَاغْفِرْ خَطِيْئَتِيْ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ فَوَاتِحَ الْخَيْرِ، وَخَوَاتِمَهُ، وَجَوَامِعَهُ، وَأَوَّلَهُ، وَآخِرَهُ وَظَاهِرَهُ، وَبَاطِنَهُ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ مَا آتِيْ، وَخَيْرَ مَا أَفْعَلُ، وَخَيْرَ مَا أَعْمَلُ، وَخَيْرَ مَا بَطَنَ، وَخَيْرَ مَا ظَهَرَ، وَالدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ، اَللَّهُمَّ إنِّي أَسْأَلُكَ أَنْ تَرْفَعَ ذِكْرِيْ، وَتَضَعَ وِزْرِيْ، وَتُصْلِحَ أَمْرِيْ، وَتُطَهِّرَ قَلْبِيْ، وَتُحَصِّنَ فَرْجِيْ، وَتُنَوِّرَ قَلْبِيْ، وَتَغْفِرَ لِي ذَنْۢبِيْ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ آمِينْ، اَللَّهُمَّ إنِّي أَسْأَلُكَ أَنْ تُبَارِكَ لِي فِي نَفْسِيْ، وَفِي سَمْعِيْ، وَفِي بَصَرِيْ، وَفِي رُوحِيْ، وَفِي خَلْقِيْ، وَفِي خُلُقِيْ، وَفِي أَهْلِيْ، وَفِي مَحْيَايَ، وَفِي مَمَاتِيْ، وَفِي عَمَلِيْ، فَتَقَبَّلْ حَسَنَاتِيْ، وَأَسْأَلُكَ الدَّرَجَاتِ الْعُلَى مِنَ الْجَنَّةِ، آمِينْ","latin":"Allâhümme innî es'elüke hayrel-mes'eleti ve hayred-du'âi ve hayren-necâhi ve hayrel-'ameli ve hayres-sevâbi ve hayrel-hayâti ve hayrel-memâti ve sebbitnî ve sekkal-mevâzînî ve hakkik îmânî verfa' derecâtî ve tekabbel salâtî vagfir hatî'atî ve es'elüked-derecâtil-'ulyâ minel-cenneti. Allâhümme innî es'elüke fevâtihel-hayri ve havâtimehû ve cevâmi'ahû ve evvelehû ve âhirehû ve zâhirehû ve bâtınehû ved-derecâtil-'ulyâ minel-cenneti âmîn. Allâhümme innî es'elüke hayra mâ âtî ve hayra mâ ef'alü ve hayra mâ a'melü ve hayra mâ betane ve hayra mâ zahara ved-derecâtil-'ulyâ minel-cenneti âmîn. Allâhümme innî es'elüke en terfe'a zikrî ve teda'a vizrî ve tusliha emrî ve tutahhira kalbî ve tuhassine fercî ve tünevvira kalbî ve tagfira lî zenbî ve es'elüked-derecâtil-'ulyâ minel-cenneti âmîn. Allâhümme innî es'elüke en tübârika lî fî nefsî ve fî sem'î ve fî basarî ve fî rûhî ve fî halkî ve fî hulukî ve fî ehlî ve fî mahyâye ve fî memâtî ve fî amelî fe-tekabbel hasanâtî ve es'elüked-derecâtil-'ulyâ minel-cenneti âmîn","tr":"Ey Allah'ım! Senden en hayırlı istemeyi, en hayırlı duayı, en hayırlı başarıyı, en hayırlı ameli, en hayırlı sevabı, en hayırlı yaşamı ve en hayırlı ölümü isterim. Beni sabitleştir, mizanımı ağır kıl, imanımı tahkik et, derecelerimi yükselt, namazımı kabul et ve günahımı bağışla. Senden Cennet'in en yüce derecelerini isterim. Âmin. Ey Allah'ım! Senden hayrın başlangıçlarını, sonlarını, tamamını, evvelini, ahirini, zahirini ve batınını ve Cennet'in en yüce derecelerini isterim. Âmin. Ey Allah'ım! Senden bana gelecek olanın hayrını, yapacaklarımın hayrını, amellerimin hayrını, gizlediğimin hayrını ve açıkladığımın hayrını ve Cennet'in en yüce derecelerini isterim. Âmin. Ey Allah'ım! Senden zikrimi yüceltmeni, yükümü hafifletmeni, işlerimi düzeltmeni, kalbimi temizlemeni, iffetimi korumanı, kalbimi nurlandırmanı ve günahımı bağışlamanı isterim. Ve Cennet'in en yüce derecelerini isterim. Âmin. Ey Allah'ım! Senden nefsimde, kulağımda, gözümde, ruhimde, bedenimde, ahlakımda, ailемde, hayatımda, ölümümde ve amelimde bana bereket vermeni ve iyiliklerimi kabul etmeni isterim. Senden Cennet'in en yüce derecelerini isterim. Âmin.","en":"O Allah I ask of You the best request, the best supplication, the best success, the best work, the best reward, the best life, and the best death. And make me firm, let my balance (of good) be heavy, fulfill my belief, elevate my position, accept my prayer, and forgive my sin. And I ask of You the highest degrees in Paradise. Ameen. O Allah I ask of You the beginnings of good, and the endings of good, all its aspects, its first, and its last, its apparent (side) and its unapparent (side), and the highest degrees in Paradise. Ameen. O Allah I ask of You the good that comes to me, and the good of what I do, and the good of my work and the good of what I conceal, and the good of what I reveal and the highest degrees in Paradise. Ameen. O Allah I ask You to raise high my reputation, relieve me of my burden, set right my affairs, purify my heart, guard my chastity, illuminate my heart, and forgive my sin. And I ask of You the highest degrees in Paradise. Ameen. O Allah I ask You to bless me in my hearing, in my sight, in my soul, in my body, in my manners, in my family, in my life, in my death, and in my work and to accept my good deeds. And I ask of You the highest degrees in Paradise. Ameen."},{"id":761,"title":"Rızık ve Hayatta Kanaat İçin Dua","ref":"Hasen (İbn Hacer). Fütûhâtü'r-Rabbâniyye: 4/383","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_761.json","ar":"اَللَّهُمَّ قَنِّعْنِيْ بِمَا رَزَقْتَنِيْ وَبَارِكْ لِي فِيهِ وَأَخْلِفْ عَلَيَّ كُلَّ غَائِبَةٍ لِي بِخَيْرٍ","latin":"Allâhümme kanniğnî bimâ razaktenî ve bârik lî fîhi ve ahlif 'aleyye külle ğâibeten lî bihayr","tr":"Ey Allah'ım! Beni, bana verdiğin rızka kanaat ettir ve onu benim için mübarek kıl. Sahip olmadığım her şeyi benim için hayırla tamamla.","en":"O Allah, make me content with the provision You have given me and bless me in it and appoint good for me in every thing which I do not have."},{"id":762,"title":"Kolay Hesap İçin Dua (Mesnun Dua)","ref":"Buhârî: 6537","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_762.json","ar":"اَللَّهُمَّ حَاسِبْنِيْ حِسَابًا يَسِيْرًا","latin":"Allâhümme hâsibnî hisâben yesîrâ","tr":"Ey Allah'ım! Beni kolay bir hesapla hesaba çek.\n\nÂişe (radıyallahu anhâ)'dan rivayet edilmiştir: Allah'ın Resûlü (sallallahu aleyhi ve sellem) şöyle buyurdu: «Kıyamet günü hesaba çekilen herkes mahvolur.» Ben: «Ey Allah'ın Resûlü! Allah, 'Kitabı sağından verilene gelince, o kolay bir hesapla hesaba çekilecektir' (84:7-8) buyurmuyor mu?» dedim. Allah'ın Resûlü (sallallahu aleyhi ve sellem): «O (ayet) sadece hesapların sunulması anlamındadır; hesabı kıyamet günü sorgulanacak herkes ise mutlaka azaba uğrar» buyurdu.","en":"O Allah! Grant me an easy reckoning.\n\nNarrated by ‘Aisha (RA): Allah's Messenger (ﷺ), said, \"None will be called to account on the Day of Resurrection, but will be ruined.\" I said \"O Allah's Messenger (ﷺ)! Hasn't Allah said: 'Then as for him who will be given his record in his right hand, he surely will receive an easy reckoning? (84:7-8) Allah's Messenger (ﷺ) said, \"That (Verse) means only the presentation of the accounts, but anybody whose account (record) is questioned on the Day of Resurrection, will surely be punished.\""},{"id":764,"title":"Cennet ve Güçlü İman İçin Mesnun Dua","ref":"Hasen (Elbânî). Silsiletü's-Sahîha: 5/379","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_764.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ إِيْمَانًا لَا يَرْتَدُّ، وَنَعِيْمًا لَا يَنْفَدُ، وَمُرَافَقَةَ نَبِيِّنَا مُحَمَّدٍ (ﷺ) فِي أَعْلَى جَنَّةِ الْخُلْدِ","latin":"Allâhümme innî es'elüke îmânen lâ yerteddü ve na'îmen lâ yenfedü ve mürâfakate Nebiyyinâ (sallallahu aleyhi ve sellem) fî a'lâ cennetil-huld","tr":"Ey Allah'ım! Senden geri dönmeyen bir iman, tükenmez bir nimet ve sonsuz Cennet'in en yüce makamlarında Peygamberimiz (sallallahu aleyhi ve sellem) ile beraberliği istiyorum.\n\nAbdullah ibn Mes'ûd (radıyallahu anh) şöyle rivayet etmiştir: «Mescitte namaz kılıyordum. Bu sırada Allah'ın Resûlü (sallallahu aleyhi ve sellem) mescide girdi. Yanında Ebû Bekir (radıyallahu anh) ve Ömer (radıyallahu anh) vardı. Nisâ sûresini okudum. Okumayı bitirince Allah'a hamd ettim, Peygamber'e (sallallahu aleyhi ve sellem) salât okudum, sonra kendim için dua ettim. Allah'ın Resûlü (sallallahu aleyhi ve sellem): 'İste! İstediğin verilecektir' buyurdu. Ardından: 'Kur'ân'ı saf hâliyle okumak isteyen, onu İbn Ümmü Abd'in (Abdullah ibn Mes'ûd'un) okuduğu gibi okusun' buyurdu. Evime döndüm. Bir süre sonra Ebû Bekir (radıyallahu anh) geldi ve: 'Duanda istediklerini hatırlıyor musun?' dedi. 'Evet' dedim. Onlar şunlardı: (Yukarıda geçen dua). Ardından Ömer (radıyallahu anh) bu Allah'ın kuluna müjde vermek için geldi. Varınca Ebû Bekir'in (radıyallahu anh) yanımdan ayrıldığını gördü. Bunun üzerine: 'Bunu yaptıysa, o her zaman beni geçmiştir' dedi.»","en":"O Allah, I ask you for such Imaan that does not waver and tranquility that does not diminish and the companionship of our Prophet (ﷺ) in high stations of everlasting Jannah.\n\nAbdullah Ibn Mas’ud (RA) narrated, he said, “I was praying at the mosque. In the meantime, The Messenger of Allah (ﷺ) entered into the mosque. Abu Bakr (RA) and ‘Umar (RA) were with Him. I recited surah An-Nisah. After completing the recitation, I praised Allah and sent salah upon prophet (ﷺ) then I make dua for myself. Then The Messenger of Allah (ﷺ) said, “Ask! You will be given (what you want).” Then He (ﷺ) said, “Whoever wants to recite the Qur'an in it’s pure form, then he should recite it as Ibn Umm ‘Abd (Abdullah Ibn Mas’ud). Then I came back to my home. Sometimes later Abu Bakr (RA) came to me and said, “Did you remember the things you are wanting in your supplication?” I replied, “Yes. Those are: (The dua is mentioned above)” Then ‘Umar (RA) came to this slave of Allah to give the glad tidings. After reaching, he saw Abu Bakr (RA) was leaving from me. Then he [‘Umar (RA)] said, “If you did this, then you are always outdid me.”"},{"id":765,"title":"Hidayet ve Nefsin Şerrinden Korunma Duası","ref":"Hasen (İbn Hacer). Tahrîcü Mişkât: 3/24","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_765.json","ar":"اَللَّهُمَّ أَلْهِمْنِيْ رُشْدِيْ وَأَعِذْنِيْ مِنْ شَرِّ نَفْسِيْ","latin":"Allâhümme elhimnî rüşdî ve e'iznî min şerri nefsî","tr":"Ey Allah'ım! Bana doğruyu ilham et ve beni nefsimin şerrinden koru.\n\nİmrân ibn Husayn (radıyallahu anh) şöyle rivayet etmiştir: «Peygamber (sallallahu aleyhi ve sellem) babama şöyle buyurdu: 'Ey Husayn! Kaç ilaha ibadet ediyorsun?' Babam: 'Yedi. Altısı yerde, biri göklerin üzerinde' dedi. Peygamber (sallallahu aleyhi ve sellem): 'Peki korku ve ümidinde hangisine yöneliyorsun?' buyurdu. Babam: 'Göklerin üzerinde olana' dedi. Peygamber (sallallahu aleyhi ve sellem): 'Ey Husayn! İslâm'ı kabul etseydin, sana fayda verecek iki cümle öğretirdim' buyurdu.» İmrân dedi ki: «Husayn İslâm'ı kabul ettiğinde: 'Ey Allah'ın Resûlü! Bana vaat ettiğin iki cümleyi öğret' dedi. Bunun üzerine Peygamber (sallallahu aleyhi ve sellem): 'De ki: (Yukarıda geçen dua)' buyurdu.»","en":"O Allah, inspire me with my guidance, and protect me from harm of myself.\n\nImran bin Husain (RA) narrated: “The Prophet (ﷺ) said to my father: ‘O Husain, how many deities do you worship?’ He said: ‘Seven. Six in the earth, and one above the heavens.’ He (ﷺ) said: ‘So which of them do you take for your ardent requests and fears?’ He said: ‘The one above the heavens.’ He (ﷺ) said: ‘O Husain, if you would but accept Islam, I would teach you two phrases that would benefit you.’ He said: “So when Husain accepted Islam, he said: ‘O Messenger of Allah, teach me the two phrases you promised me.’ So, he (ﷺ) said: “Say: (The dua is mentioned above)"},{"id":767,"title":"Kıyâmü'l-Leyl'de Hidayet ve Sağlık İçin Dua","ref":"Hasen Sahih. Nesâî: 1617","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_767.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَاهْدِنِيْ وَارْزُقْنِيْ وَعَافِنِيْ‏ أَعُوْذُ بِاللَّهِ مِنْ ضِيْقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ","latin":"Allâhümmağfir lî vehdini verzuknî ve 'âfinî. E'ûzü billâhi min dîkıl-mekâmi yevmel-kıyâmeh","tr":"Ey Allah'ım! Beni bağışla, bana hidayet et, bana rızık ver ve bana afiyet ver. Kıyamet günü makamın darlığından Allah'a sığınırım.\n\nÂsım ibn Humeyd (rahimehullah) şöyle dedi: «Âişe (radıyallahu anhâ)'ya Peygamber'in (sallallahu aleyhi ve sellem) gece namazına nasıl başladığını sordum. Dedi ki: 'Benden önce kimsenin sormadığı bir şeyi sordun. Allah'ın Resûlü (sallallahu aleyhi ve sellem) on kez tekbir (Allahu Ekber), on kez tahmid (Elhamdülillah), on kez tesbih (Sübhanallah), on kez tehlil (Lâ ilâhe illallah) ve on kez istiğfar (Estağfirullah) okur, ardından şöyle derdi: (Yukarıda geçen dua)»","en":"O Allah, forgive me, guide me, grant me provision and good health. I seek refuge with Allah from the difficulty of standing on the Day of Resurrection.\n\nAsim bin Humaid (R) said: \"I asked 'Aishah (RA) how the Prophet (ﷺ)- start his Qiyam Al-Lail? She said: 'You have asked me something which no one before you has asked. The Messenger of Allah (ﷺ) used to say the takbir (Allahu Akbar) ten times, the tahmid (Alhamdu lillah) ten times, the tasbih (Subhanallah) ten times, the tahlil (La ilaha illallah) ten times, and the istigfaar (Astigfirullah) ten times, then he would say: (The dua is mentioned above)"},{"id":768,"title":"İşitme ve Görme Duyularının Korunması İçin Dua","ref":"Sahih. Edebü'l-Müfred: 650","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_768.json","ar":"اَللَّهُمَّ مَتِّعْنِيْ بِسَمْعِيْ وَبَصَرِيْ وَاجْعَلْهُمَا الْوَارِثَ مِنِّيْ وَانْصُرْنِيْ عَلَى عَدُوِّيْ وَأَرِنِيْ مِنْهُ ثَأْرِيْ","latin":"Allâhümme metti'nî bi-sem'î ve basarî vec'alhumel-vârise minnî, vensurnî 'alâ 'adüvvî ve erinî minhu bi-sa'rî","tr":"Ey Allah'ım! Bana kulağımı ve gözümü nimetlendir; bunları benden (hayatımın) mirasçıları kıl. Beni düşmanıma karşı yardımla destekle ve ondan öcümü almamı sağla.","en":"O Allah, let me enjoy my sight and hearing and make them remain sound until I die. Turn away my enemy and grant me revenge on him."},{"id":769,"title":"Bereketli Bir Hayat ve Ölüm İçin İslami Dua","ref":"Sahih (Süyûtî). Câmi'us-Sağîr: 1505","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_769.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ عِيْشَةً نَقِيَّةً وَمِيْتَةً سَوِيَّةً وَمَرَدًّا غَيْرَ مُخْزٍ وَلَا فَضِحٍ","latin":"Allâhümme innî es'elüke 'îşeten nakıyyeten ve mîteten seviyyeten ve mereddân ğayra muhzin ve lâ fâdih","tr":"Ey Allah'ım! Senden temiz bir yaşam, kolay bir ölüm ve utandırmayan, rezil etmeyen bir geri dönüş istiyorum!","en":"O Allah! I ask You for a pure living, an easy death and a return that is not shameful or disgracefull!"},{"id":770,"title":"Sıkıntı ve Düşmanları Yenmek İçin Dua","ref":"Sahih. Edebü'l-Müfred: 699","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_770.json","ar":"اَللَّهُمَّ لَكَ الْحَمْدُ كُلُّهُ، اَللَّهُمَّ لَا قَابِضَ لِمَا بَسَطْتَ، وَلَا مُقَرِّبَ لِمَا بَاعَدْتَ، وَلَا مُبَاعِدَ لِمَا قَرَّبْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا مَانِعَ لِمَا أَعْطَيْتَ. اَللَّهُمَّ ابْسُطْ عَلَيْنَا مِنْ بَرَكَاتِكَ وَرَحْمَتِكَ وَفَضْلِكَ وَرِزْقِكَ، اَللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ الْمُقِيمَ الَّذِي لَا يَحُولُ وَلَا يَزُولُ. اَللَّهُمَّ إِنِّي أَسْأَلُكَ النَّعِيمَ يَوْمَ الْعَيْلَةِ، وَالْأَمْنَ يَوْمَ الْحَرْبِ، اَللَّهُمَّ عَائِذًا بِكَ مِنْ سُوءِ مَا أَعْطَيْتَنَا، وَشَرِّ مَا مَنَعْتَ مِنَّا. اَللَّهُمَّ حَبِّبْ إِلَيْنَا الْإِيمَانَ وَزَيِّنْهُ فِي قُلُوبِنَا، وَكَرِّهْ إِلَيْنَا الْكُفْرَ وَالْفُسُوقَ وَالْعِصْيَانَ، وَاجْعَلْنَا مِنَ الرَّاشِدِينَ. اَللَّهُمَّ تَوَفَّنَا مُسْلِمِينَ، وَأَحْيِنَا مُسْلِمِينَ، وَأَلْحِقْنَا بِالصَّالِحِينَ، غَيْرَ خَزَايَا وَلَا مَفْتُونِينَ. اَللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِكَ، وَيُكَذِّبُونَ رُسُلَكَ، وَاجْعَلْ عَلَيْهِمْ رِجْزَكَ وَعَذَابَكَ. اَللَّهُمَّ قَاتِلِ الْكَفَرَةَ الَّذِينَ أُوتُوا الْكِتَابَ، إِلَهَ الْحَقِّ","latin":"Allâhümme lekel-hamdü küllühû, Allâhümme lâ kâbida limâ besatta ve lâ mukarribe limâ bâ'adtte ve lâ mübâide limâ karrabte ve lâ mu'tiye limâ mene'te ve lâ mâni'a limâ a'tayte. Allâhümmebsut 'aleynâ min berekâtike ve rahmetike ve fadlike ve rızkike. Allâhümme innî es'elüken-na'îmel-mukîmellezî lâ yahûlü ve lâ yezûl. Allâhümme innî es'elüken-na'îme yevmel-'âileti vel-emne yevmel-harbi. Allâhümme 'âizün bike min sûi mâ a'teytinâ ve şerri mâ mene'te minnâ. Allâhümme habbib ileynel-îmâne ve zeyyinhü fî kulûbinâ ve kerrih ileynel-küfra vel-fûsûka vel-'isyâne vec'alnâ miner-râşidîn. Allâhümme teveffenâ müslimîne ve ahyinâ müslimîne ve elhıknâ bis-sâlihîne ğayra hâzâyâ ve lâ meftûnîn. Allâhümme kâtilil-küfferaellezîne yesüddûne 'an sebîlike ve yükezzibûne rusüleke vec'al 'aleyhim ricze'Ve 'azâbeke. Allâhümme kâtilil-küfferaellezîne ûtül-kitâbe, ilâhel-hakk","tr":"Ey Allah'ım! Bütün hamdler Sanadır. Ey Allah'ım! Senin genişlettiğini daraltacak yoktur; uzaklaştırdığını yaklaştıracak yoktur; yaklaştırdığını uzaklaştıracak yoktur; vermediğini verecek yoktur; verdiğini engelleyecek yoktur. Ey Allah'ım! Bize bereketinden, rahmetinden, lütfundan ve rızkından genişlet! Ey Allah'ım! Senden değişmeyen ve zeval bulmayan kalıcı nimeti istiyorum. Ey Allah'ım! Senden tam yoksulluğun gününde nimet ve korkunun gününde güvenlik istiyorum. Ey Allah'ım! Bize verdiklerinin kötülüğünden ve vermeyip bizden esirgeyenlerin şerrinden Sana sığınırım. Ey Allah'ım! Bize imanı sevdir ve onu kalplerinde güzelleştir. Bize küfrü, fıskı ve isyanı çirkin göster. Bizi doğru yolda olanlardan kıl. Ey Allah'ım! Bizi Müslüman olarak vefat ettir, Müslüman olarak yaşat ve bizi rezil olmaksızın ve fitneye düşmeksizin salih kullarına katıver. Ey Allah'ım! Senin yolunu tıkayan ve resullerini yalanlayan kâfirleri helak et. Onların üzerine riczini ve azabını indir. Ey Allah'ım! Kitap verilmiş kâfirlerle savaş, ey Hakkın İlahı!\n\nRifâa ez-Zürakî (radıyallahu anh) şöyle dedi: «Uhud savaşında müşrikler geri çekildiğinde Allah'ın Resûlü (sallallahu aleyhi ve sellem) şöyle buyurdu: 'Yüce Rabbime hamd edebilmem için saf tutun.' Onlar arkasında saf tuttular. Sonra şöyle dedi: (Yukarıda geçen dua)»","en":"O Allah, all praise is due to You. O Allah, none can contract what You expand nor bring near what you put far away. None can put far away what You bring near. None can give what You withhold nor withhold what You give. O Allah, expand to us some of Your blessings, mercy and favour and give us provision! O Allah, I ask You for the abiding blessing which is neither changed nor removed. O Allah, I ask You for blessing on the Day of Utter Poverty and security on the Day of Fear. O Allah, I seek refuge with You from the evil of what You give us. O Allah, make us love belief and adorn our hearts with it. Make us hate disbelief, deviance and rebellion. Place us among the rightly-guided. O Allah, make us die Muslims and make us live as Muslims and join us to the rightly, acting, who are neither disappointed nor afflicted. O Allah, fight the unbelievers who bar your path and who deny Your Messengers. Place You abasement and punishment over them. O Allah, fight the unbelievers who were given the Book, O Lord of Truth!\n\nRifa'a az-Zurqi (R) said, \"In the Battle of Uhud when the idolaters retreated, the Messenger of Allah (ﷺ) said, 'Form straight ranks so that I can praise my Almighty Lord.' They formed in ranks behind him. He said: (The dua is mentioned above)"},{"id":771,"title":"Bağışlanma, Sağlık ve Rızık İçin İslami Dua","ref":"Sahih. İbn Mâce: 3845","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_771.json","ar":"اَللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِيْ وَعَافِنِيْ وَارْزُقْنِيْ","latin":"Allâhümmağfir lî verhamnî ve 'âfinî verzuknî","tr":"Ey Allah'ım! Beni bağışla, bana merhamet et, bana afiyet ver ve bana rızık ver.\n\nPerşembe'ye kadar dört parmağını başparmak hariç kaldırarak şöyle dedi: «Bunlar senin din ve dünya işlerini bir araya getirir.»","en":"O Allah, forgive me, have mercy on me, keep me safe and sound and grant me provision.\n\nAnd he held up his four fingers apart from the thumb and said: \"These will combine your religious and worldly affairs.\""},{"id":772,"title":"Bereket, Şeref ve Kanaat İçin Dua","ref":"Hasen (Begavî). Şerhü's-Sünne: 3/154","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_772.json","ar":"اَللَّهُمَّ زِدْنَا وَلَا تَنْقُصْنَا وَأَكْرِمْنَا وَلَا تُهِنَّا وَأَعْطِنَا وَلَا تَحْرِمْنَا وَآثِرْنَا وَلَا تُؤْثِرْ عَلَيْنَا وَأَرْضِنَا وَارْضَ عَنَّا","latin":"Allâhümme zidnâ ve lâ tenkusnâ ve ekrimnâ ve lâ tühinnâ ve a'tinâ ve lâ tahrimnâ ve âsirnâ ve lâ tü'sir 'aleynâ ve ardınâ verda 'annâ","tr":"Ey Allah'ım! Bize (nimet ve sevap olarak) artır, eksiltme; bizi şereflendir, alçaltma; bize (lütuf ve ihsanından) ver, mahrum bırakma; bizi kayır, aleyhimize olma; bizi razı et ve bizden razı ol.\n\nSonra Peygamber (sallallahu aleyhi ve sellem) şöyle buyurdu: «Allah bana on ayet indirdi; bu ayetleri hayata geçiren cennete girer.» Ardından o ayetleri okudu:","en":"O Allah! Increase us [in Your Blessings and rewards] and do not decrease us, Honour us and do not humiliate us, give us [from Your Gifts] and do not deprive us, be in Favour of us and not against us, and make us satisfied and be satisfied with us.\n\nThen Prophet (ﷺ) said, “Allah sent down such ten ayahs upon me, whomsoever implicate these ayahs he will enter paradise.” Then he recited those ayahs:"},{"id":773,"title":"Güzel Ahlak ve Kişisel Gelişim İçin Dua","ref":"Sahih (Elbânî). Ahmed: 24392","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_773.json","ar":"اَللَّهُمَّ أَحْسَنْتَ خَلْقِيْ فَأَحْسِنْ خُلُقِيْ","latin":"Allâhümme ahsente halkî fe ahsin hulukî","tr":"Ey Allah'ım! Yaratılışımı güzel yarattın, ahlakımı da güzelleştir.","en":"O Allah, you have perfected my creation, so too perfect my character."},{"id":774,"title":"Güç ve Doğru Hidayet İçin İslami Dua","ref":"Buhârî: 4356","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_774.json","ar":"اَللَّهُمَّ ثَبِّتْهُ وَاجْعَلْهُ هَادِيًا مَهْدِيًّا","latin":"Allâhümme sebbithu vec'alhü hâdiyen mehdiyyâ","tr":"Ey Allah'ım! Onu sağlam kıl ve onu hidayet eden, hidayete ermiş biri yap.\n\nKays (rahimehullah)'tan rivayet edilmiştir: Cerîr (radıyallahu anh) bana şöyle dedi: «Peygamber (sallallahu aleyhi ve sellem) bana şöyle buyurdu: 'Zü'l-Halasa'yı benden def edemez misin?' O, Yemenli Ka'be olarak anılan Haşem kabilesine ait Yemen'deki bir evdi. Ahmes kabilesinden yüz elli atlıyla yola çıktım. Ben atların üzerinde sağlam oturamıyordum. Bunun üzerine Peygamber (sallallahu aleyhi ve sellem) göğsüme vurdu; parmaklarının izini göğsümde gördüm. Ardından şöyle dedi: (Yukarıda geçen dua)»","en":"O Allah! Make him firm and make him a guiding and a rightly guided man.\n\nNarrated by Qais (R): Jarir (RA) said to me, The Prophet (ﷺ) said to me, \"Won't you relieve me from Dhu-l-Khalasa?\" And that was a house (in Yemem belonging to the tribe of) Khatham called Al-Ka`ba Al Yamaniya. I proceeded with one-hundred and-fifty cavalry from Ahmas (tribe) who were horse riders. I used not to sit firm on horses, so the Prophet (ﷺ) stroke me over my chest till I saw the mark of his fingers over my chest, and then he said: (The dua is mentioned above)"},{"id":776,"title":"Öfke Giderme ve Fitneden Korunma Duası","ref":"Hasen (Heysemî). Mecma'ü'z-Zevâid: 10/27","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_776.json","ar":"اَللَّهُمَّ رَبَّ مُحَمَّدٍ النَّبِيِّ اِغْفِرْ لِي ذَنْبِيْ وَأَذْهِبْ غَيْظَ قَلْبِيْ وَأَجِرْنِيْ مِنْ مُضِلاَّتِ الْفِتَنِ مَا أَحْيَيْتَنَا","latin":"Allâhümme Rabbe Muhammedin Nebiyyî ığfir lî zenbî ve ezhib ğayza kalbî ve ecirnî min mudıllâtil-fiteni mâ ahyeytenâ","tr":"Ey Allah'ım! Peygamber Muhammed'in (sallallahu aleyhi ve sellem) Rabbi! Günahımı bağışla, kalbimden öfkeyi gider ve bizi hayatta bıraktığın müddetçe bizi saptırıcı fitnelerden koru.","en":"Ya Allah, Rabb of prophet Muhammad (ﷺ)! Forgive my sins. Remove anger from my heart and give me protection from confusing trial untill you give us death."},{"id":777,"title":"Sebat ve Hidayet İçin Dua","ref":"Sahih Li Ğayrihî. Tahrîcü Mişkât: 915","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_777.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ وَالْعَزِيْمَةَ عَلَى الرُّشْدِ وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ وَأَسْأَلُكَ قَلْبًا سَلِيْمًا وَلِسَانًا صَادِقًا وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ","latin":"Allâhümme innî es'elükes-sebâte fil-emri vel-'azîmete 'aler-rüşdi ve es'elüke şükra ni'metike ve hüsne 'ibâdetike ve es'elüke kalben selîmen ve lisânen sâdıkan ve es'elüke min hayri mâ ta'lemü ve e'ûzü bike min şerri mâ ta'lemü ve estağfirüke limâ ta'lemü","tr":"Ey Allah'ım! Senden işlerimde sebat ve doğru yola kararlılık istiyorum. Senden nimetine şükretmemi ve Sana güzel ibadet etmemi istiyorum. Senden sağlam bir kalp ve doğru bir dil istiyorum. Bildiğin hayırların en iyisini istiyorum; bildiğin şerlerin en kötüsünden Sana sığınıyorum ve bildiğin şeyler için Senden bağışlanma diliyorum.","en":"O Allah, I ask You for steadfastness in all my affairs and determination in following the right path, I ask You to make me thankful for Your blessings and to make me worship You properly. I ask You for a sound heart and a truthful tongue. I ask You for the best of what You know and I seek refuge in You from the worst of what You know and I seek Your forgiveness for what You know."},{"id":778,"title":"Bağışlanma ve Afiyet İçin Dua","ref":"Sahih. İbn Mâce: 3871","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_778.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيةَ فِي الدُّنْيَا وَالْآخِرَةَ","latin":"Allâhümme innî es'elükel-'afve vel-'âfiyete fid-dünyâ vel-âhireh","tr":"Ey Allah'ım! Senden dünyada ve ahirette af ve afiyet istiyorum.","en":"O Allah, I ask You for forgiveness and well-being in this world and in the Hereafter."},{"id":779,"title":"En Üstün Bağışlanma Duası (Seyyidü'l-İstiğfar)","ref":"Buhârî: 6306","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_779.json","ar":"اَللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُؤُ لَكَ بِنِعْمَتِكَ عَلَىَّ وَأَبُؤُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","latin":"Allâhümme Ente Rabbî lâ ilâhe illâ Ente, halaktenî ve ene 'abdüke ve ene 'alâ 'ahdike ve va'dike mesteta'tü, e'ûzü bike min şerri mâ sana'tü, ebû'ü leke bi-ni'metike 'aleyye, ve ebû'ü bi-zenbî fağfir lî fe-innehû lâ yağfirüz-zünûbe illâ Ente","tr":"Ey Allah'ım! Sen benim Rabbimsin; Senden başka ibadet edilmeye layık yoktur. Beni yarattın ve ben Senin kulunum. Gücümün yettiği kadar ahdine ve vaadine bağlı kalmaya çalışıyorum. İşlediğim kötülüğün şerrinden Sana sığınırım. Üzerimdeki nimetini itiraf ediyor ve günahımı itiraf ediyorum; beni bağışla, zira Senden başka günahları bağışlayan yoktur.","en":"O Allah, You are my Lord, none has the right to be worshipped except You, You created me and I am Your servant and I abide to Your covenant and promise as best I can, I take refuge in You from the evil of which I have committed. I acknowledge Your favour upon me and I acknowledge my sin, so forgive me, for verily none can forgive sin except You."},{"id":781,"title":"Hakaret Ettiğin Kişi İçin Dua (Buhârî)","ref":"Buhârî: 6361","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_781.json","ar":"اَللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ، فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ","latin":"Allâhümme fe-eyyümâ mü'minin sebbebtühû fec'al zâlike lehû kurbeten ileyke yevmel-kıyâmeh","tr":"Ey Allah'ım! Hakaret ettiğim hangi mümin varsa, bunu kıyamet günü onun için Sana yakınlaştırıcı bir vesile kıl.","en":"O Allah, whomever of the believers I have abused, give him the reward of a sacrificial slaughter for it on the Day of Resurrection."},{"id":783,"title":"Stres ve Kaygıya Yardımcı Olan Dua","ref":"Buhârî: 2893","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_783.json","ar":"اَللَّهُمَّ اِنِّي أَعُوْذُ بِكَ مِنَ الْهَمِّ وَالْحُزْنِ وَالْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ","latin":"Allâhümme innî e'ûzü bike minel-hemmi vel-hüzni vel-'aczi vel-keseli vel-cübni vel-buhli ve dalai'd-deyni ve ğalebetir-ricâl","tr":"Ey Allah'ım! Sana üzüntüden ve kederden, acizlikten ve tembellikten, korkaklıktan ve cimrilikten, ağır borç yükünden ve insanların baskısından sığınırım.","en":"O Allah! I seek refuge with You from worry and grief, from incapacity and laziness, from cowardice and miserliness, from being heavily in debt and from being overpowered by (other) men."},{"id":784,"title":"Allah'tan Yardım İsteme Duası (Enfâl Sûresi)","ref":"Enfâl Sûresi 8: 9-10","url":"https://quran.com/8/9","ar":"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ ﴿٩﴾ وَمَا جَعَلَهُ اللَّـهُ إِلَّا بُشْرَىٰ وَلِتَطْمَئِنَّ بِهِ قُلُوبُكُمْ ۚ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّـهِ ۚ إِنَّ اللَّـهَ عَزِيزٌ حَكِيمٌ ﴿١٠﴾","latin":"İz testağîsûne Rabbekum festecâbe lekum ennî mümiddükum bi-elfim-minel-melâiketi murdifîn. Ve mâ ce'alehullâhü illâ büşrâ ve li-tatmaínne bihî kulûbükum; ve men-nasru illâ min 'indillâh; innallâhe 'Azîzün Hakîm.","tr":"(9) Hani Rabbinizden yardım istiyordunuz; O da «Şüphesiz ben sizi birbiri ardınca gelen bin melekle destekleyeceğim» diye isteğinize karşılık verdi. (10) Allah bunu yalnızca müjde olsun ve kalpleriniz bununla yatışsın diye yaptı. Zafer, ancak Allah katındandır. Şüphesiz Allah mutlak güç ve hikmet sahibidir.","en":"(9) [Remember] when you asked help of your Lord, and He answered you, \"Indeed, I will reinforce you with a thousand from the angels, following one another.\" (10) And Allah made it not but good tidings and so that your hearts would be assured thereby. And victory is not but from Allah. Indeed, Allah is Exalted in Might and Wise."},{"id":785,"title":"Bedir Savaşı Hakkında Kur'ân Ayetleri (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi 3: 123-126","url":"https://quran.com/3/123","ar":"وَلَقَدْ نَصَرَكُمُ اللَّـهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ ۖ فَاتَّقُوا اللَّـهَ لَعَلَّكُمْ تَشْكُرُونَ ﴿١٢٣﴾ إِذْ تَقُولُ لِلْمُؤْمِنِينَ أَلَن يَكْفِيَكُمْ أَن يُمِدَّكُمْ رَبُّكُم بِثَلَاثَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُنزَلِينَ ﴿١٢٤﴾ بَلَىٰ ۚ إِن تَصْبِرُوا وَتَتَّقُوا وَيَأْتُوكُم مِّن فَوْرِهِمْ هَـٰذَا يُمْدِدْكُمْ رَبُّكُم بِخَمْسَةِ آلَافٍ مِّنَ الْمَلَائِكَةِ مُسَوِّمِينَ ﴿١٢٥﴾ وَمَا جَعَلَهُ اللَّـهُ إِلَّا بُشْرَىٰ لَكُمْ وَلِتَطْمَئِنَّ قُلُوبُكُم بِهِ ۗ وَمَا النَّصْرُ إِلَّا مِنْ عِندِ اللَّـهِ الْعَزِيزِ الْحَكِيمِ ﴿١٢٦﴾","latin":"Ve lekad nasarakumullâhü bi-Bedrin ve entüm ezilletün; fettekullahe la'alleküm teşkürûn. İz tekûlü lil-mü'minîne elen yekfiyekum en yümiddekum Rabbükum bi-selâseti âlâfin minel-melâiketi münzelîn. Belâ; in tasbiru ve tettekû ve ye'tûküm min fevrihim hâzâ yumdidküm Rabbükum bi-hamse âlâfin minel-melâiketi müsevvimîn. Ve mâ ce'alehullâhü illâ büşrâ lekum ve li-tatmaínne kulûbükum bih; ve men-nasru illâ min 'indillâhil-'Azîzil-Hakîm.","tr":"(123) Andolsun, siz güçsüz iken Allah, Bedir'de de size yardım etmişti. O hâlde Allah'a karşı gelmekten sakının ki şükredebilesiniz. (124) Hani sen mü'minlere, «Rabbinizin, indirilmiş üç bin melekle sizi takviye etmesi size yetmez mi?» diyordun. (125) Evet, eğer sabreder, Allah'a karşı gelmekten sakınırsanız ve onlar da hemen bu anda üzerinize gelseler, Rabbiniz sizi nişanlı beş bin melekle destekler. (126) Allah bunu, yalnızca size müjde olsun ve kalpleriniz bununla yatışsın diye yaptı. Zafer ancak mutlak güç ve hikmet sahibi Allah katındandır.","en":"(123) And already had Allah given you victory at [the battle of] Badr while you were few in number. Then fear Allah; perhaps you will be grateful. (124) [Remember] when you said to the believers, \"Is it not sufficient for you that your Lord should reinforce you with three thousand angels sent down? (125) Yes, if you remain patient and conscious of Allah and the enemy come upon you [attacking] in rage, your Lord will reinforce you with five thousand angels having marks [of distinction] (126) And Allah made it not except as [a sign of] good tidings for you and to reassure your hearts thereby. And victory is not except from Allah, the Exalted in Might, the Wise -"},{"id":786,"title":"Allah'a Tevekkülü Artırmak İçin Dua","ref":"Âl-i İmrân Sûresi 3: 173-174","url":"https://quran.com/3/173","ar":"اَلَّذِينَ قَالَ لَهُمُ النَّاسُ إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّـهُ وَنِعْمَ الْوَكِيلُ ﴿١٧٣﴾ فَانقَلَبُوا بِنِعْمَةٍ مِّنَ اللَّـهِ وَفَضْلٍ لَّمْ يَمْسَسْهُمْ سُوءٌ وَاتَّبَعُوا رِضْوَانَ اللَّـهِ ۗ وَاللَّـهُ ذُو فَضْلٍ عَظِيمٍ ﴿١٧٤﴾","latin":"Ellezîne kâle lehümün-nâsü innen-nâse kad ceme'û lekum fahşevhüm fe-zâdehüm îmânen ve kâlû hasbünallâhü ve ni'mel-Vekîl. Fenkalebû bi-ni'metin minallâhi ve fadlin lem yemsehhüm sûün vettebe'û rıdvânallâh; vallâhü zû fadlin 'azîm.","tr":"(173) O kimseler ki, münafıklar kendilerine «İnsanlar size karşı büyük bir ordu topladılar; artık onlardan korkun» dediklerinde bu, onların imanlarını artırdı ve «Allah bize yeter, O ne güzel vekildir» dediler. (174) Bunun üzerine onlar, kendilerine hiçbir kötülük dokunmaksızın Allah'tan bir nimet ve lütufla geri döndüler. Allah'ın rızasını da gözetmiş oldular. Allah büyük lütuf sahibidir.","en":"(173) Those to whom hypocrites said, \"Indeed, the people have gathered against you, so fear them.\" But it [merely] increased them in faith, and they said, \"Sufficient for us is Allah, and [He is] the best Disposer of affairs.\" (174) So they returned with favor from Allah and bounty, no harm having touched them. And they pursued the pleasure of Allah, and Allah is the possessor of great bounty."},{"id":787,"title":"Rızık ve Servet İçin Dua","ref":"Buhârî: 6344","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_787.json","ar":"اَللَّهُمَّ أَكْثِرْ مَالَهُ وَوَلَدَهُ، وَأَطِلْ حَيَاتَهُ، وَاغْفِرْ لَهُ","latin":"Allâhümme eksir mâlehû ve veledehû ve etil hayâtehû vağfir leh","tr":"Ey Allah'ım! Onun malını ve çocuklarını çoğalt, ömrünü uzat ve onu bağışla.\n\nEnes (radıyallahu anh) şöyle dedi: «Peygamber (sallallahu aleyhi ve sellem) ev halkına gelirdi. Bir gün yanımıza geldi ve bize dua etti. Ümmü Süleym (radıyallahu anhâ): 'Küçük hizmetçin için de dua etmez misiniz?' dedi. Bunun üzerine şöyle dua etti: (Yukarıda geçen dua)»","en":"O Allah! Increase his wealth and children, and bestow Your Blessing on whatever You give him.\" a time of distress.\n\nAnas (RA) said, \"The Prophet (ﷺ), used to come to us, the people of his house. One day he came to us and made supplication for us. Umm Sulaym (RA) said, 'Won't you make supplication for your little servant?' He said, (the dua is mentioned above)"},{"id":789,"title":"Peygamber'in Ebû Hüreyre'nin Annesi İçin Duası","ref":"Müslim: 2491","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_789.json","ar":"اَللَّهُمَّ اهْدِ أُمَّ أَبِي هُرَيْرَةَ","latin":"Allâhümmahdi ümme Ebî Hüreyre","tr":"Ey Allah'ım! Ebû Hüreyre'nin annesini doğru yola hidayet et.\n\nPeygamber (sallallahu aleyhi ve sellem) Ebû Hüreyre'nin (radıyallahu anh) annesi için dua etti ve annesi hemen İslâm'ı kabul etti. Ebû Hüreyre (radıyallahu anh) şöyle dedi: «Annem müşrik bir kadındı. Ona İslâm'ı tebliğ ederdim. Bir gün yine tebliğ ettim. Tebliğ ederken Allah'ın Resûlü (sallallahu aleyhi ve sellem) hakkında hoşuma gitmeyen bir şey söyledi. Bunun üzerine ağlayarak Allah'ın Resûlü'ne (sallallahu aleyhi ve sellem) gittim ve: 'Ey Allah'ın Resûlü! Anneme İslâm'ı tebliğ ediyordum fakat kabul etmiyordu. Bugün tebliğ ettim, Siz hakkında çirkin bir şey söyledi. Ona dua edin, Allah ona hidayet etsin' dedim. Bunun üzerine Allah'ın Resûlü (sallallahu aleyhi ve sellem) şöyle dua etti: (Yukarıda geçen dua)»","en":"O Allah, guide mother of Abu Huraira on the right path.\n\nProphet (ﷺ) made dua for mother of Abu Hurairah (RA). Then his mother accepted Islam Immediately. Abu Hurairah (RA) said, “My mother was a polytheist woman. I gave dawah to her to accept Islam. One day I gave dawah to her. While I was giving dawah to her, she said something ill about The Messenger of Allah (ﷺ), which displeased me.Then I went to The Messenger of Allah (ﷺ) crying. I said to him, “Oh The Messenger of Allah (ﷺ)! I was giving dawah to my mother, but she didn’t accept it. Today, I give dawah to her. As a result, she said something ill about. Please make dua for her that Allah give guidance to her. Then the Messenger of Allah (ﷺ) said: (the dua is mentioned above)"},{"id":790,"title":"Mü'minler Tarafından Sevilmek İçin Dua","ref":"Müslim: 2491","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_790.json","ar":"اَللَّهُمَّ حَبِّبْ عُبَيْدَكَ هَذَا وَأُمَّهُ إِلَى عِبَادِكَ الْمُؤْمِنِينَ وَحَبِّبْ إِلَيْهِمُ الْمُؤْمِنِيْنَ","latin":"Allâhümme habbib 'ubeydeke hâzâ ve ümmehû ilâ 'ibâdikel-mü'minîn, ve habbib ileyhimül-mü'minîn","tr":"Ey Allah'ım! Bu kulun —Ebû Hüreyre— ve annesinin sevgisini mü'min kullarının kalplerine yerleştir; mü'min kulların sevgisini de onların kalbine yerleştir.\n\nEbû Hüreyre (radıyallahu anh) şöyle dedi: «Allah'ın Resûlü'nün (sallallahu aleyhi ve sellem) duasından çok memnun olarak ayrıldım. Kapıya yaklaşınca kapı içeriden kapalıydı. Annem ayak seslerimi duyunca: 'Ebû Hüreyre, bekle' dedi. Ardından su sesini duydum; gusül aldı, elbisesini giydi, hızlıca başını örttü ve kapıyı açtı. Sonra: 'Ebû Hüreyre! Allah'tan başka ilah olmadığına ve Muhammed'in O'nun kulu ve resûlü olduğuna şahitlik ederim' dedi. Bunun üzerine sevinç gözyaşları dökerek Allah'ın Resûlü'ne (sallallahu aleyhi ve sellem) döndüm ve: 'Ey Allah'ın Resûlü! Müjde, Allah duanıza icabet etti ve Ebû Hüreyre'nin annesini doğru yola iletti' dedim. Peygamber Allah'a hamd ve sena etti, güzel sözler söyledi. Ben de: 'Ey Allah'ın Resûlü! Allah'a dua edin, benim ve annеmin sevgisini mü'min kullara, onların sevgisini de bize yerleştirsin.' Bunun üzerine Allah'ın Resûlü şöyle dua etti: (Yukarıda geçen dua). Ebû Hüreyre şöyle dedi: 'Bu dua o kadar iyi kabul edildi ki, beni duyan ya da gören hiçbir mü'min beni sevmekten geri kalmadı.'»","en":"O Allah, let there be love of these servants of yours, i.e. Abu Huraira and his mother, in the hearts of the believing servants and let their hearts be filled with the love of the believing servants.\n\nI came out quite pleased with the supplication of Allah's Apostle (ﷺ) and when I came near the door it was closed from within. My mother heard the noise of my footsteps and she said: Abu Huraira, just wait. And I heard the noise of falling of water. She took a bath and put on the cloth and quickly covered her head with a head-dress and opened the door and then said: Abu Huraira, I bear witness to the fact that there is no god but Allah and Muhammad is His bondsman and His Messenger (ﷺ). He (Abu Huraira) said: I went back to Allah's Messenger (ﷺ) and (this time) I was shedding the tears of joy. I said: Allah's Messenger, be happy, for Allah has responded to your supplication and He has set on the right path the mother of Abu Huraira. He (the Holy Prophet) praised Allah, and extolled Him and uttered good words. I said: O Allah's Messenger (ﷺ), supplicate to Allah so that He may instill love of mine and that of my mother too in the believing servants and let our hearts be filled with their love, whereupon Allah's Messenger (ﷺ) said: O Allah, let there be love of these servants of yours, i.e. Abu Huraira and his mother, in the hearts of the believing servants and let their hearts be filled with the love of the believing servants. (Abu Huraira said: This prayer) was so well granted by Allah that no believer was ever born who heard of me and who saw me but did not love me."},{"id":792,"title":"Ticaret Başarısı İçin Mesnun Dua","ref":"Beyhakî: 6/112, Ahmed: 1750","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_792.json","ar":"اَللَّهُمَّ بَارِكْ لَهُ فِي صَفْقَةِ يَمِيْنِهِ","latin":"Allâhümme bârik lehû fî safkati yemînihî","tr":"Ey Allah'ım! Onun sağ eli ile yaptığı ticarette bereket ver.\n\nO Küfe'de yaşardı; eve dönmeden önce kırk bin kâr ederdi.","en":"Oh Allah! Put barakah on his trade.\n\nHe lived in Kufa; And before returning home, he used to make a profit of forty thousand."},{"id":793,"title":"Zâlimlere Karşı Korunma Duası","ref":"Müslim: 1794","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_793.json","ar":"اَللَّهُمَّ عَلَيْكَ بِقُرَيْشٍ","latin":"Allâhümme 'aleyke bi-Kureyş","tr":"Ey Allah'ım! Kureyş'in işini Sen gör.\n\nPeygamber (sallallahu aleyhi ve sellem) Allah'ın bazı düşmanları hakkında beddua etti ve Allah duasına icabet etti. Bu olaylardan biri şöyledir: Mekke'de müşrikler Peygamber'e (sallallahu aleyhi ve sellem) çok eziyet verdiler. Bir gün Allah'ın Resûlü (sallallahu aleyhi ve sellem) Kâbe yanında namaz kılarken Ebû Cehil, kötü arkadaşlarından birini kışkırtarak dişi bir devenin yavrusunu Muhammed secdeye gittiğinde omuzları arasına koymasını emretti. Bu alçak işi Ukbe ibn Ebî Muayt gerçekleştirdi. Peygamber (sallallahu aleyhi ve sellem) namazını bitirince yüksek sesle onlara beddua etti ve üç kez şöyle dedi: (Yukarıda geçen dua)","en":"O Allah, it is for Thee to deal with the Quraish.\n\nProphet (ﷺ) invoked Allah's imprecations upon some enemy of Allah, and Allah responded his dua. One of the incidence was, in Makkah , polytheists gave much pain to Prophet (ﷺ). One day, while the Messenger of Allah (ﷺ) was saying his prayer near the Ka'ba, Abu Jahl commanded some of his evil companions to place foetus of the she-camel between the shoulders of Muhammad when he goes down in prostration (a posture in prayer). This heinous crime was commited by ‘Uqbaa ibn Abi Muait.When the Prophet (ﷺ) had finished his prayer, he invoked Allah's imprecations upon them in a loud voice. Then he said thrice: (the dua is mentioned above)"},{"id":794,"title":"Düşmanlara Karşı Korunma Duası","ref":"Müslim: 1794","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_794.json","ar":"اَللَّهُمَّ عَلَيْكَ بِأَبِي جَهْلِ بْنِ هِشَامٍ وَعُتْبَةَ بْنِ رَبِيْعَةَ وَشَيْبَةَ بْنِ رَبِيْعَةَ وَالْوَلِيْدِ بْنِ عُقْبَةَ وَأُمَيَّةَ بْنِ خَلَفٍ وَعُقْبَةَ بْنِ أَبِيْ مُعَيْطٍ","latin":"Allâhümme 'aleyke bi-Ebî Cehlin ibni Hişâm, ve 'Utbete ibni Rebîa, ve Şeybete ibni Rebîa, vel-Velîdi ibni Ukbe, ve Ümeyye ibni Halef, ve 'Ukbete ibni Ebî Muayt","tr":"Ey Allah'ım! Ebû Cehil ibn Hişâm, Utbe ibn Rebîa, Şeybe ibn Rebîa, Velid ibn Ukbe, Ümeyye ibn Halef ve Ukbe ibn Ebî Muayt'ın işini Sen gör.\n\nİbn Mes'ûd (radıyallahu anh) şöyle dedi: «Muhammed'i (sallallahu aleyhi ve sellem) hak ile gönderene yemin olsun, isimlerini söylediklerinin hepsini Bedir günü yerde can çekişir hâlde gördüm. Cesetleri savaş alanının yakınındaki bir çukura atıldı.» Bir başka rivayette: «Allah'a yemin olsun, onları Bedir savaş alanında can çekişirken gördüm. Çok sıcak bir gündü ve yüzleri değişmişti (bozulma belirtileri gösteriyordu).»","en":"O Allah, it is for Thee to deal with Abu Jahl bin Hisham, 'Utba bin Rabi'a, Shaiba bin Rabi'a. Walid bin Uqba, Umayya bin Khalaf, Uqba bin Abu Mu'ait.\n\nIbn Mas’ud (RA) said,”By One Who sent Muhammad (ﷺ) with truth, I saw (all) those he had named lying slain on the Day of Badr. Their dead bodies were dragged to be thrown into a pit near the battlefield”. In another narration, “I swear by Allah that I saw them lying slain in the battlefield of Badr. It being a hot day, their complexion had changed (showing signs of decay).”"},{"id":795,"title":"Zarardan Korunma Duası","ref":"Buhârî: 3911","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_795.json","ar":"اَللَّهُمَّ اصْرَعْهُ","latin":"Allâhümme sra'hü","tr":"Ey Allah'ım! Onu yere yıkıver.\n\nEnes ibn Mâlik (radıyallahu anh)'dan rivayet edilmiştir: Allah'ın Resûlü (sallallahu aleyhi ve sellem), aynı devenin üzerinde Ebû Bekir'in (radıyallahu anh) arkasında binmiş olarak Medine'ye geldi. Ebû Bekir yaşlı bir adamdı ve insanlar tarafından tanınıyordu; Allah'ın Resûlü ise genç ve tanınmayan biriydi. Bir adam Ebû Bekir'le karşılaştığında: «Ey Ebû Bekir! Önünde kim var?» diye sorardı. Ebû Bekir: «Bu adam bana yolu gösteriyor» derdi. Adam bundan kastedilen yolun düz yol olduğunu zannederdi; oysa Ebû Bekir fazilet ve iyilik yolunu kastediyordu. Sonra Ebû Bekir arkasına bakınca bir atlının onları takip ettiğini gördü. «Ey Allah'ın Resûlü! Bir atlı bizi takip ediyor» dedi. Peygamber (sallallahu aleyhi ve sellem) arkasına bakıp şöyle dua etti: (Yukarıda geçen dua)","en":"O Allah! Cause him to fall down.\n\nNarrated by Anas bin Malik (RA): Allah's Messenger (ﷺ) arrived at Medina with Abu Bakr (RA), riding behind him on the same camel. Abu Bakr (RA) was an elderly man known to the people, while Allah's Messenger (ﷺ) was a youth that was unknown. Thus, if a man met Abu Bakr (RA), he would say, \"O Abu Bakr! Who is this man in front of you?\" Abu Bakr (RA) would say, \"This man shows me the Way,\" One would think that Abu Bakr (RA) meant the road, while in fact, Abu Bakr (RA) meant the way of virtue and good. Then Abu Bakr (RA) looked behind and saw a horse-rider pursuing them. He said, \"O Allah's Messenger (ﷺ)! This is a horse-rider pursuing us.\" The Prophet (ﷺ) looked behind and said - (The dua is mentioned above)"},{"id":796,"title":"Peygamber'in Bedir Savaşı'ndaki Duası (Mesnun Dua)","ref":"Müslim: 1763","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_796.json","ar":"اَللَّهُمَّ أَنْجِزْ لِي مَا وَعَدْتَنِي اَللَّهُمَّ آتِ مَا وَعَدْتَنِي اَللَّهُمَّ إِنْ تُهْلِكْ هَذِهِ الْعِصَابَةَ مِنْ أَهْلِ الْإِسْلَامِ لَا تُعْبَدُ فِي الْأَرْضِ","latin":"Allâhümme enci lî mâ ve 'adtenî, Allâhümme âti mâ ve 'adtenî, Allâhümme in tühlik hâzihil-'işâbete min ehlil-İslâmi lâ tu'bed fil-ardi","tr":"Ey Allah'ım! Bana vaat ettiğini yerine getir. Ey Allah'ım! Bana vaat ettiklerini getir. Ey Allah'ım! Eğer İslâm ehlinden bu küçük topluluğu helak edersen, yeryüzünde Sana ibadet edilmez.\n\nÖmer ibn el-Hattâb (radıyallahu anh)'tan rivayet edilmiştir: «Bedir savaşının günü Allah'ın Resûlü (sallallahu aleyhi ve sellem) kâfirlere baktı; onlar bin kişiydi; kendisinin ashâbı ise üç yüz on dokuz kişiydi. Peygamber (sallallahu aleyhi ve sellem) Kıble'ye döndü, ellerini uzattı ve Rabbine şöyle dua etmeye başladı: (Yukarıda geçen dua)»","en":"O Allah! Fulfill what You promised for me. [O Allah! Bring about what You promised for me] O Allah! If you destroy this band of adherents to Islam, you will not be worshiped upon the earth.\n\nIt has been narrated on the authority of `Umar bin al-Khattab (RA) who said: When it was the day on which the Battle of Badr was fought, the Messenger of Allah (ﷺ) cast a glance at the infidels, and they were one thousand while his own Companions were three hundred and nineteen. The Prophet (ﷺ) turned (his face) towards the Qibla. Then he stretched his hands and began his supplication to his Lord: (The dua mentioned above)"},{"id":797,"title":"Allah'ın Yardımı İçin Dua (Mesnun Dua)","ref":"Müslim: 1763","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_797.json","ar":"إِذْ تَسْتَغِيثُونَ رَبَّكُمْ فَاسْتَجَابَ لَكُمْ أَنِّي مُمِدُّكُم بِأَلْفٍ مِّنَ الْمَلَائِكَةِ مُرْدِفِينَ","latin":"İz testağîsûne Rabbekum festecâbe lekum ennî mümiddükum bi-elfim-minel-melâiketi murdifîn.","tr":"Hani Rabbinizden yardım istiyordunuz; O da «Şüphesiz ben sizi birbiri ardınca gelen bin melekle destekleyeceğim» diye isteğinize karşılık verdi. (Enfâl Sûresi 8:9)\n\nO (Rasûlullah sallallahu aleyhi ve sellem) ellerini uzatmış, Kıble'ye yönelmiş hâlde Rabbi'ne dua etmeye devam etti; öyle ki rida'sı omuzlarından kaydı. Bunun üzerine Ebû Bekir (radıyallahu anh) geldi, ridasını aldı, omuzlarına koydu ve arkasından onu kucaklayarak şöyle dedi: «Ey Allah'ın Peygamberi! Rabbine yaptığın bu dua yeter; O, sana vaat ettiğini yerine getirecektir.» Bunun üzerine Allah Teâlâ şu ayeti indirdi: (Yukarıdaki ayet) Böylece Allah meleklerle yardım etti.","en":"[Remember] when you asked help of your Lord, and He answered you, \"Indeed, I will reinforce you with a thousand from the angels, following one another.\" (Sura Anfal 8:9)\n\nHe (Rasulullah ﷺ) continued his supplication to his Lord, stretching his hands, facing the Qibla, until his mantle slipped down from his shoulders. So Abu Bakr (RA) came to him, picked up his mantle and put it on his shoulders. Then he embraced him from behind and said: O Prophet of Allah (ﷺ), this prayer of yours to your Lord will suffice you, and He will fulfill for you what He has promised you. So Allah, the Glorious and Exalted, revealed (the Qur'anic verse): (The ayaat is mentioned above) So Allah helped him with angels."},{"id":799,"title":"Korkudan Kurtulma İçin Dua (Mesnun Dua)","ref":"[1] Bakara Sûresi 2: 214 [2] Zâdü'l-Me'âd: 3/274","url":"https://quran.com/2/214","ar":"يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ إِذْ جَاءَتْكُمْ جُنُودٌ فَأَرْسَلْنَا عَلَيْهِمْ رِيحًا وَجُنُودًا لَّمْ تَرَوْهَا ۚ وَكَانَ اللَّهُ بِمَا تَعْمَلُونَ بَصِيرًا ﴿٩﴾ إِذْ جَاءُوكُم مِّن فَوْقِكُمْ وَمِنْ أَسْفَلَ مِنكُمْ وَإِذْ زَاغَتِ الْأَبْصَارُ وَبَلَغَتِ الْقُلُوبُ الْحَنَاجِرَ وَتَظُنُّونَ بِاللَّهِ الظُّنُونَا ﴿١٠﴾ هُنَالِكَ ابْتُلِيَ الْمُؤْمِنُونَ وَزُلْزِلُوا زِلْزَالًا شَدِيدًا ﴿١١﴾","latin":"Em hasibtüm en tedhulül-cennete ve lemmâ ye'tikum-mesellüllezîne halev min kablikum messethumül-be'sâü ved-darrâü ve zülzilû hattâ yekûler-Resûlü vellezîne âmenû me'ahû metâ nasrullâh; elâ inne nasrallâhi karîb.","tr":"Yoksa siz, daha önce gelip geçenlerin başına gelenler sizin de başınıza gelmeden cennete gireceğinizi mi sandınız? Onlara öyle yoksulluk ve sıkıntı dokunmuş, öyle sarsılmışlardı ki, peygamber ve beraberindeki inananlar «Allah'ın yardımı ne zaman gelecek?» diyecek olmuşlardı. İyi bilin ki Allah'ın yardımı yakındır.","en":"(9) O you who have believed, remember the favor of Allah upon you when armies came to [attack] you and We sent upon them a wind and armies [of angels] you did not see. And ever is Allah, of what you do, Seeing. (10) [Remember] when they came at you from above you and from below you, and when eyes shifted [in fear], and hearts reached the throats and you assumed about Allah [various] assumptions. (11) There the believers were tested and shaken with a severe shaking."},{"id":800,"title":"Peygamber'in Hendek Savaşı'ndaki Duası","ref":"Müslim: 1742","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_800.json","ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ سَرِيعَ الْحِسَابِ اِهْزِمِ الْأَحْزَابَ اَللَّهُمَّ اهْزِمْهُمْ وَزَلْزِلْهُمْ","latin":"Allâhümme münzelel-kitâbi serîal-hisâbi ihzimil-ahzâb. Allâhümmahzimhüm ve zelzilhüm.","tr":"Ey Allah'ım! Kitabı indiren, hesabı çabuk gören! Grupları boz. Ey Allah'ım! Onları boz ve sarsıver.\n\nHendek savaşında Allah'ın Resûlü'ne (sallallahu aleyhi ve sellem) karşı savaşanlar beş gruptu: Mekke müşrikleri, Arap kabilelerinin müşrikleri, Medine dışından gelen Yahudiler, Benî Kureyzâ ve münafıklar. Hendek karşısında on bin kâfir vardı; Peygamber (sallallahu aleyhi ve sellem) ile birlikte ise üç bin Müslüman. Kâfirler Peygamber'i bir ay kuşattı. Aralarında muharebe olmadı; yalnızca Ali ibn Ebî Tâlib (radıyallahu anh) ile Amr ibn Veddi el-Âmirî arasında bir çarpışma yaşandı ve Ali (radıyallahu anh) onu öldürdü. Bu, hicretten sonraki dördüncü yıldı. O savaşta Allah'ın Resûlü (sallallahu aleyhi ve sellem) onlar hakkında şöyle dua etti: (Yukarıda geçen dua)","en":"O Allah, Revealer of the Book, swift in (taking) account, put the tribes to rout. O Lord, defeat them and shake them.\n\nIn the battle of Ahzaab, those who fought with The Messenger of Allah (ﷺ), they were five kinds: Polytheists of Makkah, Polytheists of various tribes of Arab, Jews who came from outside the madina, Banu Quraiza and the hypocrites. There were ten thousands disbelievers in the front of trench and with the Prophet (ﷺ), there were three thousands Muslims. The disbelievers surrounded Prophet (ﷺ) for 1 month. There was no fighting between them, but there was an incident where a fighting took place Ali ibn Abi Taalib (RA) with Amar ibn Udd Amiri. Ali (RA) killed him. This was the fourth year after Hijrah. In that battle The Messenger of Allah (ﷺ) invoked Allah against them - (The dua is mentioned above)"},{"id":801,"title":"Huneyn Savaşı'nda Güçlü Dua","ref":"Müslim: 1777","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_801.json","ar":"شَاهَتِ الْوُجُوْهُ","latin":"Şâhatil-vücûh","tr":"Bu yüzler çirkin olsun!\n\nBu hadis Seleme ibnu'l-Ekva' (radıyallahu anh)'tan rivayet edilmiştir: «Allah'ın Resûlü'nün (sallallahu aleyhi ve sellem) yanında Huneyn'de savaştık. Düşmanla karşılaştığımızda Allah'ın Resûlü (sallallahu aleyhi ve sellem) katırından indi, yerden bir avuç toprak aldı, düşmanın yüzlerine fırlattı ve şöyle dedi: (Yukarıda geçen dua). Düşmandan hiç kimse yoktu ki o avuç toprağın tozundan gözleri dolmasın. Böylece arkalarını dönüp kaçtılar; Allah (azze ve celle) onları bozguna uğrattı ve Allah'ın Resûlü (sallallahu aleyhi ve sellem) ganimetlerini Müslümanlara dağıttı.»","en":"May these faces be deformed!\n\nThis hadith has been narrated on the authority of Salama ibnul akwa (RA) who said: We fought by the side of the Messenger of Allah (ﷺ) at Hunain. When we encountered the enemy, the Messenger of Allah (ﷺ) got down from his mule. picked up a handful of dust from the ground, threw it into their (enemy) faces and said: (the dua is mentioned above) There was no one among the enemy whose eyes were not filled with the dust from this handful. So, they turned back fleeing. and Allah the Exalted and Glorious defeated them, and the Messenger of Allah (ﷺ) distributed their booty among the Muslims."},{"id":802,"title":"Sıkıntılar İçin Mesnun Dua","ref":"Buhârî: 6347","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_802.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ جَهْدِ الْبَلَاءِ وَدَرَكِ الشَّقَاءِ وَسُوْءِ الْقَضَاءِ وَشَمَاتَةِ الْأَعْدَاءِ","latin":"Allâhümme innî e'ûzü bike min cehdi'l-belâi ve deraki'ş-şakâi ve sûi'l-kadâi ve şemâteti'l-a'dâ","tr":"Ey Allah'ım! Bela'nın şiddetinden, perişanlığa uğramaktan, kötü kadere duçar olmaktan ve düşmanların benim musibetime sevinmesinden Sana sığınırım.","en":"O Allah, I seek refuge with Allah from the difficult moment of a calamity and from being overtaken by destruction and from being destined to an evil end, and from the malicious joy of enemies."},{"id":803,"title":"Zarardan Korunma İçin Mesnun Dua","ref":"Müslim: 2722","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_803.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَعَذَابِ الْقَبْرِ، اَللَّهُمَّ آتِ نَفْسِيْ تَقْوَاهَا وَزَكِّهَا أَنْتَ خَيْرُ مَنْ زَكَّاهَا أَنْتَ وَلِيُّهَا وَمَوْلَاهَا، اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ وَمِنْ دَعْوَةٍ لَا يُسْتَجَابُ لَهَا.","latin":"Allâhümme innî e'ûzü bike minel-'aczi vel-keseli vel-cübni vel-buhli vel-haremi ve 'azâbil-kabr. Allâhümme âti nefsî tekvâhâ ve zekkihâ ente hayrü men zekkâhâ ente veliyyühâ ve mevlâhâ. Allâhümme innî e'ûzü bike min 'ilmin lâ yenfe'u ve min kalbin lâ yahşa'u ve min nefsin lâ teşbe'u ve min da'vetin lâ yüstecâbu lehâ","tr":"Ey Allah'ım! Acizlikten, tembellikten, korkaklıktan, cimrilikten, ihtiyarlık düşkünlüğünden ve kabir azabından Sana sığınırım. Ey Allah'ım! Nefsime takvasını ver ve onu temizle; zira onu temizleyenlerin en hayırlısı Sensin. Sen onun Velîsi ve Mevlâsısın. Ey Allah'ım! Fayda vermeyen ilimden, huşu duymayan kalpten, doymak bilmeyen nefisten ve kabul edilmeyen duadan Sana sığınırım.","en":"O Allah, I seek refuge with You from weakness, and laziness, cowardice and miserliness, old and infirm age, and the torment of the grave. O Allah, give my soul piety and purify it, for indeed You are the best of those who can purify it, You are it's Guardian and Master. O Allah, I seek refuge with You from knowledge that does not benefit, from a heart that does not get humbled [to Allah], from a soul which is never satisfied and from a supplication which does not get answered."},{"id":804,"title":"Ani Azaptan Korunma İçin Mesnun Dua","ref":"Müslim: 2739","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_804.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنْ زَوَالِ نِعْمَتِكَ، وَتَحَوُّلِ عَافِيَتِكَ، وَفُجَاءَةِ نِقْمَتِكَ وَجَمِيْعِ سَخَطِكَ","latin":"Allâhümme innî e'ûzü bike min zevâli ni'metike ve tehavvüli 'âfiyetike ve fücâeti nikmetike ve cemî'i sahatıke","tr":"Ey Allah'ım! Nimetinin geri alınmasından, afiyetinin değişmesinden, azabının ansızın gelmesinden ve her türlü gazabından Sana sığınırım.","en":"O Allah, I seek refuge in Thee from the withdrawal of your blessing and the change of your protection (from me) and from the sudden your wrath, and from your every displeasure."},{"id":805,"title":"Allah'ın Sevgisi İçin Mesnun Dua","ref":"Hasen (İbn Hacer). Tahrîcü'l-Mesâbîh: 3/31","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_805.json","ar":"اَللَّهُمَّ ارْزُقْنِي حُبَّكَ وَحُبَّ مَنْ يَنْفَعُنِي حُبُّهُ عِنْدَكَ اَللَّهُمَّ مَا رَزَقْتَنِي مِمَّا أُحِبُّ فَاجْعَلْهُ قُوَّةً لِي فِيمَا تُّحِبُّ، اَللَّهُمَّ وَمَا زَوَيْتَ عَنِّي مِمَّا أُحِبُّ فَاجْعَلْهُ لِي فَرَاغًا فِيمَا تُحِبُّ","latin":"Allâhümmer zuknî hubbeke ve hubbe men yenfe'unî hubbühû 'indeke. Allâhümme mâ razaktenî mimmâ uhibbu fec'alhü kuvveten lî fîmâ tuhibbu. Allâhümme ve mâ zeveynte 'annî mimmâ uhibbu fec'alhü lî ferâğen fîmâ tuhibbu","tr":"Ey Allah'ım! Bana Senin sevgini ve katında sevgisi bana fayda verecek kimselerin sevgisini nasip et. Ey Allah'ım! Sevdiğim şeylerden bana rızık olarak verdiklerini, sevdiğin şeylere ulaşmak için güç kaynağı kıl. Ey Allah'ım! Sevdiğim şeylerden benden uzaklaştırdıklarını ise sevdiğin şeylere ulaşmak için boş vakit kıl.","en":"O Allah grant me Your love and the love of those whose love will benefit me. O Allah, whatever you have provided me of that which I love, make it strength for me for achieving that which You love. O Allah, and what you have kept from me of that which I love, then make it for me a period of rest for achieving that which You love."},{"id":807,"title":"Hidayet İçin Mesnun Dua","ref":"Müslim: 2721","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_807.json","ar":"اَللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","latin":"Allâhümme innî es'elükel-hüdâ vet-tukâ vel-'afâfe vel-ğınâ","tr":"Ey Allah'ım! Şüphesiz Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.","en":"O Allah, indeed, I ask You for guidance, piety, chastity, and sufficiency."},{"id":809,"title":"Cehennem Ateşinden Korunma İçin Mesnun Dua","ref":"Sahih (Ahmed Şâkir). Umdetü't-Tefsîr: 1/162","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_809.json","ar":"اَللَّهُمَّ أَحْسِنْ عَاقِبَتَنَا فِي الْأُمُوْرِ كُلِّهَا، وَأَجِرْنَا مِنْ خِزْيِ الدُّنْيَا وَعَذَابِ الْآخِرَةِ","latin":"Allâhümme ahsin 'âkıbetenâ fil-ümûri küllihâ ve ecirnâ min hızzid-dünyâ ve 'azâbil-âhireh","tr":"Ey Allah'ım! Tüm işlerimizde sonucumuzu güzel kıl, bizi dünyanın rezilliğinden ve ahiretin azabından koru.","en":"O Allah! grant us a good outcome on all of our affairs and save us from the disgrace of this world and the punishment of the Hereafter."},{"id":811,"title":"Hastalıktan Korunma İçin Mesnun Dua","ref":"Hasen (Elbânî). Silsiletü's-Sahîha: 1540","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_811.json","ar":"اَللَّهُمَّ حْفَظْنِي بِالْإِسْلَامِ قَائِمًا وَاحْفَظْنِي بِالْإِسْلَامِ قَاعِدًا وَحْفَظْنِي بِالْإِسْلَامِ رَاقِدًا وَلَا تُشْمِتْ بِي عَدُوًّا وَلَا حَسِدًا، اَللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ كُلِّ خَيْرٍ خَزَائِنُهُ بِيَدِكَ وَأَعُوْذُ بِكَ مِنْ كُلِّ شَرٍّ خَزَائِنُهُ بِيَدِكَ","latin":"Allâhüm-mahfaznî bil-İslâmi kâimen, vah-faznî bil-İslâmi kâ'iden, vah-faznî bil-İslâmi râkıden, ve lâ tüşmit bî 'adüvven ve lâ hâsiden. Allâhümme innî es'elüke min külli hayrin hazâinühû bi-yedike ve e'ûzü bike min külli şerrin hazâinühû bi-yedike","tr":"Ey Allah'ım! Ayaktayken beni İslâm ile koru, otururken beni İslâm ile koru, yatarken beni İslâm ile koru; düşmanımı ve hased edeni benim yüzümden sevindirme. Ey Allah'ım! Hazineleri Senin elinde bulunan her türlü hayrı Senden istiyorum; hazineleri Senin elinde bulunan her türlü şerden de Sana sığınıyorum.","en":"O Allah! Protect me with Islam when standing, and protect me with Islam when sitting down, and protect me with Islam when reclining, and do not make an enemy or envier rejoice at me. O Allah! I ask you for every good whose stores are in Your Hand, and I seek refuge with you from every evil whose stores are in Your Hand."},{"id":812,"title":"Rızık ve Uzun Ömür İçin Mesnun Dua","ref":"Hasen (Heysemî). Mecma'ü'z-Zevâid: 10/185","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_812.json","ar":"اَللَّهُمَّ اجْعَلْ أَوْسَعَ رِزْقِكَ عَلَىَّ عِنْدَ كِبَرِ سِنِّي وَانْقِطَاعِ عُمُرِي","latin":"Allâhümmec'al evsa'a rızkike 'aleyye 'inde kiberi sinnî venkıtâ'i 'ümürî","tr":"Ey Allah'ım! Rızkını benim üzerime ihtiyarlığımda ve ömrümün son döneminde en geniş biçimde yay.","en":"O Allah! Expand for me Your provision till my old age and till the end of my life."},{"id":813,"title":"Hastalık ve Zorluktan Korunma İçin Mesnun Dua","ref":"Sahih (Elbânî). Sahîhü'l-Câmi': 1285","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_813.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَالْجُبْنِ وَالْبُخْلِ وَالْهَرَمِ وَالْقَسْوَةِ وَالْغَفْلَةِ وَالْعَيْلَةِ وَالذِّلَّةِ وَالْمَسْكَنَةِ وَأَعُوْذُ بِكَ مِنَ الْفَقْرِ وَالْكُفْرِ وَالْفُسُوْقِ وَالشِّقَّاقِ وَالنِّفَقِ وَالسُّمْعَةِ والرِّيَاءِ وَأَعُوْذُ بِكَ مِنَ الصَّمَمِ وَالْبَكَمِ وَالْجُنُوْنِ وَالْجُذَامِ وَالْبَرَصِ وَسَيِّءِ الْأَسْقَامِ","latin":"Allâhümme innî e'ûzü bike minel-'aczi vel-keseli vel-cübni vel-buhli vel-haremi vel-kasvetî vel-ğafletî vel-'ayleti vez-zülleti vel-meskeneti ve e'ûzü bike minel-fakri vel-küfri vel-füsûki veş-şikâki ven-nifâki ves-süm'ati ver-riyâi ve e'ûzü bike mines-samemi vel-bekemi vel-cünûni vel-cüzâmi vel-berasi ve seyyiil-eskâm","tr":"Ey Allah'ım! Acizlikten, tembellikten, korkaklıktan, cimrilikten, ihtiyarlık düşkünlüğünden, kalp katılığından, gafletden, yoksulluktan, aşağılıktan ve sefaletten Sana sığınırım. Sana mutlak yoksulluktan, küfürden, fıskdan, ayrılıkçılıktan, nifaktan, şöhret peşinden ve riyadan sığınırım. Sana sağırlıktan, dilsizlikten, delilikten, cüzamdan, alacadan (abraştan) ve her türlü kötü hastalıktan sığınırım.","en":"O Allah, I seek refuge in You from Inability; lethargy; Cowardice, Miserliness, Senility, Hard heartedness, Heedlessness, Deprivation; Humiliation, misery; And I seek refuge in You from absolute poverty, Disbelief, Rebellion; Dissension, Hypocrisy, Seeking fame, And showing off, And I seek refuge in You from deafness, Being mute, Insanity; Leprosy, Leukederma, And from any worst kind of illness."},{"id":815,"title":"Faydalı İlim İçin Mesnun Dua","ref":"Sahih. Tirmizî: 3599","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_815.json","ar":"اَللَّهُمَّ انْفَعْنِي بِمَا عَلَّمْتَنِي وَعَلِّمْنِي مَا يَنْفَعُنِي وَزِدْنِي عِلْمًا","latin":"Allâhümmen-fe'nî bi-mâ 'allemtenî ve 'allim-nî mâ yenfe'unî ve zidnî 'ilmâ","tr":"Ey Allah'ım! Bana öğrettiklerinle beni faydalandır, bana faydalı olanı öğret ve ilmimi artır.","en":"Oh Allah, benefit me with what You have taught me and teach me what benefits me, and increase me in knowledge."},{"id":818,"title":"Şirkten Korunma Duası","ref":"Sahih. Edebü'l-Müfred: 716","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_818.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ أَنْ أُشْرِكَ بِكَ وَأَنَا أَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا لَا أَعْلَمُ","latin":"Allâhümme innî e'ûzü bike en üşrike bike ve ene e'lemü ve estağfirüke limâ lâ e'lemü","tr":"Ey Allah'ım! Bilerek Sana ortak koşmaktan Sana sığınırım; bilmeden yaptıklarım için de Senden bağışlanma dilerim.","en":"O Allah, I seek refuge in You lest I associate anything with You knowingly, and I seek Your forgiveness for what I know not."},{"id":826,"title":"Yeni Meyve Görünce Okunan Dua","ref":"Müslim: 1373","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_826.json","ar":"اَللَّهُمَّ بَارِكْ لَنَا فِي ثَمَرِنَا، وَبَارِكْ لَنَا فِي مَدِينَتِنَا، وَبَارِكْ لَنَا فِي صَاعِنَا، وَبَارِكْ لَنَا فِي مُدِّنَا","latin":"Allâhümme bârik lenâ fî semerâtinâ ve bârik lenâ fî medînetinâ ve bârik lenâ fî sâ'inâ ve bârik lenâ fî müddinâ","tr":"Ey Allah'ım! Meyvelerimizde bize bereket ver, şehrimizde bize bereket ver, sa'ımızda bize bereket ver ve müddümüzde bize bereket ver.","en":"O Allah, bless us in our dates and bless us in our town, bless us in our Sa' and in our Mudd."},{"id":827,"title":"Kötü Ahlaktan Korunma Duası","ref":"Sahih. Tirmizî: 3591","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_827.json","ar":"اَللَّهُمَّ اِنِّي اَعُوذُ بِكَ مِنْ مُنْكَرَاتِ الْاَخْلَاقِ وَالْأَعْمَالِ وَالْأَهْوَاءِ","latin":"Allâhümme innî e'ûzü bike min münkerâtil-ahlâkı vel-a'mâli vel-ehvâ","tr":"Ey Allah'ım! Kötü ahlaktan, kötü amellerden ve kötü hevâlardan Sana sığınırım.","en":"O Allah, I seek refuge in You from evil character, evil actions, and evil desires."},{"id":828,"title":"Göz, Kulak, Dil ve Kalbi Korumak İçin Dua","ref":"Sahih. Ebû Dâvûd: 1551","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_828.json","ar":"اَللَّهُمَّ اِنِّي اَعُوذُ بِكَ مِنْ شَرِّ سَمْعِيْ وَمِنْ شَرِّ بَصَرِيْ وَمِنْ شَرِّ لِسَانِيْ وَمِنْ شَرِّ قَلْبِيْ مِنْ شَرِّ مَنِيِّيْ","latin":"Allâhümme innî e'ûzü bike min şerri sem'î ve min şerri basarî ve min şerri lisânî ve min şerri kalbî ve min şerri meniyyî","tr":"Ey Allah'ım! İşitmemimin şerrinden, görmemimin şerrinden, dilimin şerrinden, kalbimin şerrinden ve menimin şerrinden (cinsel ihtirasın şerrinden) Sana sığınırım.","en":"O Allah, indeed I seek refuge in You from the evil of my hearing and the evil of my sight, and the evil of my tongue and the evil of my heart, and the evil of my semen."},{"id":831,"title":"Aynaya Bakınca Okunan Dua","ref":"Sahih (Elbânî). Müsned-i Ahmed: 5099","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_831.json","ar":"اَللَّهُمَّ حَسَّنْتَ خَلْقِي فَأَحْسِنْ خُلُقِي","latin":"Allâhümme hassente halkî fe ahsin hulukî","tr":"Ey Allah'ım! Dış görünüşümü güzel yarattığın gibi, ahlakımı da güzelleştir.","en":"O Allah, just as You have made my external features beautiful, make my character beautiful as well."},{"id":838,"title":"Sıkıntı Anında Okunacak Dua (Yâ Hayyu yâ Kayyûm Duası)","ref":"Hasen. Tirmizî: 3524","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_838.json","ar":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ","latin":"Yâ Hayyu yâ Kayyûmu bi-rahmetike estağîs","tr":"Ey Dâimâ Diri olan, ey her şeyi ayakta tutan! Rahmetinle senden yardım dilerim.","en":"O Ever Living, O Self-Subsisting and Supporter of all, by Your Mercy I seek help."},{"id":839,"title":"Peygamber'in Gün Boyu Allah'ı Övdüğü Duası","ref":"Sahih (Albânî). Sahîhü'l-Câmî: 2615","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_839.json","ar":"اَلْحَمْدُ لِلَّهِ عَدَدَ مَا خَلَقَ، وَالْحَمْدُ لِلَّهِ مِلْءَ مَا خَلَقَ، وَالْحَمْدُ لِلَّهِ عَدَدَ مَا فِي الْأَرْضِ وَالسَّمَاءِ، وَالْحَمْدُ لِلَّهِ مِلْءَ مَا فِي الْأَرْضِ وَالسَّمَاءِ، وَالْحَمْدُ لِلَّهِ عَدَدَ مَا أَحْصَى كِتَابُهُ، وَالْحَمْدُ لِلَّهِ عَدَدَ كُلِّ شَيْءٍ، وَالْحَمْدُ لِلَّهِ مِلْءَ كُلِّ شَيْءٍ سُبْحَانَ لِلَّهِ عَدَدَ مَا خَلَقَ، وَسُبْحَانَ لِلَّهِ مِلْءَ مَا خَلَقَ، وَسُبْحَانَ لِلَّهِ عَدَدَ مَا فِي الْأَرْضِ وَالسَّمَاءِ، وَسُبْحَانَ لِلَّهِ مِلْءَ مَا فِي الْأَرْضِ وَالسَّمَاءِ، وَسُبْحَانَ لِلَّهِ عَدَدَ مَا أَحْصَى كِتَابُهُ، وَسُبْحَانَ لِلَّهِ عَدَدَ كُلِّ شَيْءٍ، وَسُبْحَانَ لِلَّهِ مِلْءَ كُلِّ شَيْءٍ","latin":"Elhamdülillâhi adede mâ haleka, velhamdülillâhi mil'e mâ haleka, velhamdülillâhi adede mâ fil-ardi ves-semâi, velhamdülillâhi mil'e mâ fil-ardi ves-semâi, velhamdülillâhi adede mâ ahsâ kitâbuhû, velhamdülillâhi adede külli şey'in, velhamdülillâhi mil'e külli şey'in. Sübhânallâhi adede mâ haleka, ve sübhânallâhi mil'e mâ haleka, ve sübhânallâhi adede mâ fil-ardi ves-semâi, ve sübhânallâhi mil'e mâ fil-ardi ves-semâi, ve sübhânallâhi adede mâ ahsâ kitâbuhû, ve sübhânallâhi adede külli şey'in, ve sübhânallâhi mil'e külli şey'in.","tr":"Allah'a hamdolsun, yarattıklarının sayısınca; Allah'a hamdolsun, yarattıklarını dolduracak kadar; Allah'a hamdolsun, yer ve göklerdeki her şeyin sayısınca; Allah'a hamdolsun, yer ve göklerdeki her şeyi dolduracak kadar; Allah'a hamdolsun, Kitab'ının saydığı kadar; Allah'a hamdolsun, her şeyin sayısınca; Allah'a hamdolsun, her şeyi dolduracak kadar. Allah'ı her türlü eksiklikten tenzih ederim, yarattıklarının sayısınca; Allah'ı tenzih ederim, yarattıklarını dolduracak kadar; Allah'ı tenzih ederim, yer ve göklerdeki her şeyin sayısınca; Allah'ı tenzih ederim, yer ve göklerdeki her şeyi dolduracak kadar; Allah'ı tenzih ederim, Kitab'ının saydığı kadar; Allah'ı tenzih ederim, her şeyin sayısınca; Allah'ı tenzih ederim, her şeyi dolduracak kadar.\n\nPeygamber (sallallahu aleyhi ve sellem) Ebû Umâme el-Bâhilî (radıyallahu anh)'a şöyle buyurdu: «Sana gündüz ve gece boyunca yapılan nafile zikirden daha hayırlı bir dua/zikir öğreteyim mi? Bu duayı/zikri kendin öğren ve senden sonra geleceklere de öğret.»","en":"Praise be to Allah equal to His creation, praise be to Allah for the fullness of His creation, praise be to Allah equal to what is in the heavens and earth, praise be to Allah equal to what His Book has counted, praise be to Allah full of what His Book has counted, praise be to Allah equal to the quantity of all things and the praise of Allah are full of all things. I am glorifying Allah equal to His creation, I am glorifying Allah for the fullness of His creation, I am glorifying Allah equal to what is in the heavens and earth, I am glorifying Allah equal to what His Book has counted, pI am glorifying Allah full of what His Book has counted, I am glorifying Allah equal to the quantity of all things and I am glorifying Allah full of all things.\n\nThe Prophet (peace and blessings of Allaah be upon him) said to Abu Umama Bahili (may Allaah be pleased with him), “Shall I not teach you a du'aa/dhikr that is better than all day and night (naafil) dhikr? Learn this du'aa/dhikr yourself, and teach it to those who will come after you.\""},{"id":841,"title":"Gelecekte Bir Şey Yapmak İçin Söylenecek Söz (İnşâallah)","ref":"Kehf Sûresi: 23-24","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_841.json","ar":"إِنْ شَاءَ اللَّهُ","latin":"İnşâallah","tr":"Allah dilerse.\n\n«Hiçbir şey için 'Ben bunu yarın mutlaka yapacağım' deme; ancak 'Allah dilerse (İnşâallah)' ekle. Unuttuğun zaman Rabbini an ve 'Umarım Rabbim beni doğruya daha yakın olana yönlendirir' de.»","en":"If Allah wills.\n\nAnd never say of anything, \"Indeed, I will do that tomorrow,\" Except [when adding], \"If Allah wills.\" And remember your Lord when you forget [it] and say, \"Perhaps my Lord will guide me to what is nearer than this to right conduct.\""},{"id":845,"title":"Kötü Haber Duyduğunda veya Bir Şeyi Kaybettiğinde Okunacak Dua (İnnâ Lillâhi)","ref":"Müslim: 2126","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_845.json","ar":"إِنَّا لِلَّهِ","latin":"İnnâ lillâhi","tr":"Biz Allah'tan geldik (Allah'ın kullarıyız).","en":"We are from Allah."},{"id":846,"title":"Güzel Bir Şey Gördüğünde Söylenecek Söz (Mâşâallah)","ref":"Müslim: 3508","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_846.json","ar":"مَا شَاءَ ٱللَّهُ","latin":"Mâ şâallah","tr":"Allah'ın dilediği oldu.","en":"That which Allah wanted."},{"id":852,"title":"Kötü Bir Şey Duyduğunda Söylenecek Söz (Neûzübillah)","ref":"Buhârî: 6362","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_852.json","ar":"نَعُوذُ بِاللَّهِ","latin":"Neûzübillâh","tr":"Allah'a sığınırım.","en":"I seek refuge with Allah."},{"id":853,"title":"Ölüm Haberinde Okunacak Dua (İnnâ Lillâhi ve İnnâ İleyhi Râciûn)","ref":"Bakara Sûresi: 2/156","url":"https://quran.com/2/156","ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ","latin":"İnnâ lillâhi ve innâ ileyhi râciûn","tr":"Biz Allah'tan geldik ve O'na döneceğiz.","en":"We are from Allah and unto Him we return."},{"id":854,"title":"Namazdan Sonra Âmin Duası","ref":"Sahih Li Ğayrihî (Albânî). Tergîb ve't-Terhîb: 2/66","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_854.json","ar":"آمِينْ","latin":"Âmîn","tr":"(Ey Allah'ım!) Duamızı kabul et.","en":"(Oh Allah) accept our invocation."},{"id":857,"title":"Şüpheye Düşüldüğünde Söylenecek Söz (Vallahu A'lem)","ref":"Buhârî: 5570","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_857.json","ar":"وَاللَّهُ أَعْلَمُ‏","latin":"Vallahu a'lem","tr":"Allah daha iyi bilir.","en":"Allah knows better."},{"id":862,"title":"Bağışlanma ve Şükran İçin Sabah Duası","ref":"Müslim: 822","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_862.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ أَقَالَنَا يَوْمَنَا هٰذَا وَلَمْ يُهْلِكْنَا بِذُنُوْبِنَا","latin":"Elhamdü lillâhillezî ekâlenâ yevmenâ hâzâ ve lem yühliknâ bi-zünûbinâ","tr":"Bize bu günü gösteren ve geçmiş günahlarımız sebebiyle bizi helak etmeyen Allah'a hamd ü senâlar olsun.","en":"All praise (and innumerable thanks) to Allah, Who has shown us this day, and did not destroy us for our (past) sins."},{"id":863,"title":"Fitneden Korunma Duası","ref":"Buhârî: 6593","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_863.json","ar":"اَللَّهُمَّ اِنَّا نَعُوْذُ بِكَ اَنْ نَرْجِعَ عَلٰى أَعْقَابِنَا أَوْ نُفْتَنَ عَنْ دِيْنِنَا.","latin":"Allâhümme innâ neûzü bike en narci'a alâ a'kâbinâ ev nüftene an dîninâ","tr":"Ey Allah'ım! Geriye dönmekten (dinden çıkmaktan) ve dinimiz hakkında fitneye düşmekten Sana sığınırız.","en":"O Allah, we seek refuge with You from turning on our heels, or being put to trial in our religion."},{"id":864,"title":"Dünya ve Ahirette Güvenlik İçin Dua (Mesnun Dua)","ref":"Sahih. Tirmizî: 3514","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_864.json","ar":"أَسْأَلُ اللَّهَ الْعَافِيَةَ فِيْ الدُّنْيَا وَالْآخِرَةِ","latin":"Es'elullâhe'l-âfiyete fid-dünyâ vel-âhira","tr":"Dünya ve ahirette Allah'tan afiyet dilerim.","en":"I seek security from Allah in this World and Hereafter."},{"id":865,"title":"Korunma ve Hidayet Duası","ref":"Sahih (Albânî). Sahîhü'l-Mevârid: 2059","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_865.json","ar":"اَللَّهُمَّ إِنِّي أَسْتَهْدِيكَ لِأَرْشَدِ أَمْرِي، وَأَعُوْذُ بِكَ مِنْ شَرِّ نَفْسِيْ","latin":"Allâhümme innî estehdikel-erşede emrî ve eûzü bike min şerri nefsî","tr":"Ey Allah'ım! Tüm işlerimde senden en doğruya hidayet dilerim ve nefsimin şerrinden sana sığınırım.","en":"O Allah, I seek guidance from You in all matters, and I seek refuge in You from my own evil."},{"id":866,"title":"Azalan Aydan Korunma Duası","ref":"Sahih (Albânî). Sahîhü'l-Câmî: 6918","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_866.json","ar":"أَعُوْذُ بِاللَّهِ مِنْ شَرِّ هٰذَا الغَاسِقِ","latin":"Eûzü billâhi min şerri hâzel-ğâsık","tr":"Bu kaybolan ayın şerrinden Allah'a sığınırım.","en":"I seek refuge in Allah from the misfortune of this disappearing moon."},{"id":867,"title":"Bağışlanma ve Nefsi Koruma İçin Güçlü Dua","ref":"Sahih (Şuayb el-Arnaût). Müsned Ahmed: 19992","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_867.json","ar":"اَللَّهُمَّ قِنِيْ شَرَّ نَفْسِيْ، وَاعْزِمْ لِيْ عَلٰى أَرْشَدِ أَمْرِيْ اَللَّهُمَّ اغْفِرْ لِيْ مَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَخْطَأْتُ وَمَا عَمَدْتُّ، وَمَا جَهِلْتُ.","latin":"Allâhümme kınî şerra nefsî vec'a' lî alâ erşedi emrî, Allâhümmağfir lî mâ esrartu ve mâ a'lentu ve mâ ahta'tü ve mâ emadtü ve mâ cahiltü","tr":"Ey Allah'ım! Beni nefsimin şerrinden koru ve bana tüm işlerimde en doğruya azim ver. Ey Allah'ım! Gizli yaptıklarımı ve açık yaptıklarımı, isteyerek yaptıklarımı ve istemeyerek yaptıklarımı, bilgisizlikle yaptıklarımı bağışla.","en":"O Allah, keep me safe from the evil of my soul. Give me a strong will to do good in all things. O Allah, forgive me all that I have done openly and secretly, that which I have done willingly and unwillingly, and that which I have done in ignorance."},{"id":868,"title":"Teşehhüd Duası (Ettahiyyâtü'l-Mübârekâtü's-Salevâtü't-Tayyibât)","ref":"Müslim: 403","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_868.json","ar":"اَلتَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ اَلسَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لَّا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ","latin":"Ettahiyyâtü'l-mübârekâtü's-salevâtü't-tayyibâtü lillâh, esselâmü aleyke eyyühen-Nebiyyü ve rahmetullâhi ve berekâtühü, esselâmü aleynâ ve alâ ibâdillâhis-sâlihîn. Eşhedü en lâ ilâhe illAllâhü ve eşhedü enne Muhammeden Resûlüllâh.","tr":"Bütün mübarek tebrikler, dualar ve güzel şeyler Allah'a aittir. Sana selâm olsun, ey Peygamber, Allah'ın rahmeti ve bereketi de. Bize ve Allah'ın sâlih kullarına da selâm olsun. Allah'tan başka ilâh olmadığına şahadet ederim ve Muhammed'in (sallallahu aleyhi ve sellem) Allah'ın Resûlü olduğuna şahadet ederim.","en":"All the blessed compliments and all the holy prayers are only for Allah. Peace be on you, O Prophet, and Allah’s mercy and blessings (are on you). And peace be on us and on the good (pious) worshipers of Allah.I bear witness that there is no true God except Allah. I further testify that Muhammad (peace be upon him) is the Messenger of Allah."},{"id":869,"title":"Teşehhüd Duası (Ettahiyyâtü Lillâhi Ezkiyâtü Lillâhi)","ref":"Sahih (Albânî). Sıfatü's-Salâh, s. 163","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_869.json","ar":"اَلتَّحِيَّاتُ لِلَّهِ اَلزَّاكِيَاتُ لِلَّهِ، اَلطَّيِّبَاتُ الصَّلَوَتُ لِلَّهِ، اَلسَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهٗ، اَلسَّلَامُ عَلَيْنَا وَعَلٰى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَّا إِلٰهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهٗ ورَسُولُهُ","latin":"Ettahiyyâtü lillâhi ezkiyâtü lillâhi, ettayyibâtü's-salevâtü lillâh, esselâmü aleyke eyyühen-Nebiyyü ve rahmetullâhi ve berekâtühü, esselâmü aleynâ ve alâ ibâdillâhis-sâlihîn. Eşhedü en lâ ilâhe illAllâhü ve eşhedü enne Muhammeden abdühû ve Resûlühû.","tr":"Bütün tebrikler, bütün güzel ameller ve bütün dualar Allah'a aittir. Sana selâm olsun, ey Peygamber, Allah'ın rahmeti ve bereketi de. Bize ve Allah'ın sâlih kullarına da selâm olsun. Allah'tan başka ilâh olmadığına şahadet ederim ve Muhammed'in (sallallahu aleyhi ve sellem) O'nun kulu ve Resûlü olduğuna şahadet ederim.","en":"All the blessed compliments, all the good deeds and all the holy prayers are only for Allah. Peace be on you, O Prophet, and Allah’s mercy and blessings (are on you). And peace be on us and on the good (pious) worshipers of Allah. I bear witness that there is no true God except Allah. I further testify that Muhammad (peace be upon him) is the Messenger of Allah."},{"id":871,"title":"Rükûda Okunacak Dua","ref":"Sahih (el-Aynî). Nuhbetü'l-Efkâr: 4/247","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_871.json","ar":"اَللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، أَنْتَ رَبِّي، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعَظْمِي وَعَصَبِي وَمَا اِسْتَقَلَّتْ بِهِ قَدَمِي لِلَّهِ رَبِّ الْعَالَمِينَ","latin":"Allâhümme leke reka'tü ve bike âmentü ve leke eslemtü, ente rabbî, haşea leke sem'î ve basarî ve muhkhî ve azmî ve asabî ve mestetalle bihi kadamî lillâhi rabbil-âlemîn","tr":"Ey Allah'ım! Sana rükû ettim, Sana iman ettim ve Sana teslim oldum. Sen benim Rabbimsin; kulağım, gözüm, beyin, kemiklerim, sinirlerim ve ayaklarımın taşıdığım her şey (yani varlığım) âlemlerin Rabbi Allah'ın huzurunda huşû içindedir.","en":"O Allah, I have bowed down to You, I have believed, I have surrendered. You are my Rabb, my ear-eye, my brain, my bones, my spine and my legs, all that you are carrying (i.e. my existence) have been humbled before Allah Almighty."},{"id":872,"title":"Senâ Duası (Sübhâneke Allâhümme ve Bihamdik)","ref":"Müslim: 399","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_872.json","ar":"سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلٰهَ غَيْرُكَ","latin":"Sübhânekellâhümme ve bihamdik, ve tebârekesmük, ve teâlâ ceddük, ve lâ ilâhe ğayrük","tr":"Ey Allah'ım! Sen her türlü eksiklikten münezzehsin ve hamd Sana aittir. Senin adın mübarektir, azametin yücedir. Senden başka ibadete layık ilâh yoktur.","en":"Glory is to You O Allah, and praise. Blessed is Your Name and Exalted is Your Majesty. There is none worthy of worship but You."},{"id":873,"title":"Rükû Duası","ref":"Sahih. Nesâî: 1131","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_873.json","ar":"سُبْحَانَكَ اَللَّهُمَّ وَبِحَمْدِكَ لَا إِلَهَ إِلَّا أَنْتَ","latin":"Sübhânekellâhümme ve bihamdik, lâ ilâhe illâ ent","tr":"Ey Allah'ım! Sen her türlü eksiklikten münezzehsin ve hamd Sana aittir. Senden başka ibadete layık ilâh yoktur.","en":"O Allah glory is to You; there is no worthy of worship except You."},{"id":874,"title":"Namazda Rükûdan Sonra Okunacak Dua","ref":"Sahih. Ebû Dâvûd: 874","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_874.json","ar":"لِرَبِّيَ الْحَمْدُ","latin":"Li-Rabbiyel hamd","tr":"Rabbime hamd olsun.","en":"To my Lord belongs all praise"},{"id":875,"title":"Dua-i Meşhure","ref":"Buhârî: 6371","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_875.json","ar":"اَللَّهُمَّ إِنِّي أَعُوْذُ بِكَ مِنَ الْكَسَلِ، وَأَعُوْذُ بِكَ مِنَ الْجُبْنِ، وَأَعُوْذُ بِكَ مِنَ الْهَرَمِ، وَأَعُوْذُ بِكَ مِنَ الْبُخْلِ","latin":"Allâhümme innî eûzü bike minel-kesel, ve eûzü bike minel-cübn, ve eûzü bike minel-haram, ve eûzü bike minel-buhl","tr":"Ey Allah'ım! Tembellikten Sana sığınırım, korkaklıktan Sana sığınırım, bunaklık derecesindeki ihtiyarlıktan Sana sığınırım ve cimrilikten Sana sığınırım.","en":"O Allah! I seek refuge with You from laziness, and seek refuge with You from cowardice, and seek refuge with You from geriatric old age, and seek refuge with You from miserliness."},{"id":876,"title":"Rükûdan Sonra Okunacak Dua","ref":"Müslim: 476","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_876.json","ar":"اَللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَىْءٍ بَعْدُ، اَللَّهُمَّ طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ اَللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الأَبْيَضُ مِنَ الْوَسَخِ","latin":"Allâhümme rabbenâ lekel hamd, mil-es semâvâti ve mil-el ardi ve mil-e mâ şi'te min şey'in ba'dü, Allâhümme tahhirnî biss-selci vel-beredi vel-mâil-bârid, Allâhümme tahhirnî minezzünûbi vel-hatâyâ kemâ yünekkass-sevbül-ebyadu minel-vesah","tr":"Ey Allah'ım! Ey Rabbimiz! Gökleri dolduracak, yeri dolduracak ve bunlardan sonra dilediğin şeyleri dolduracak kadar Sana hamd olsun. Ey Allah'ım! Beni kar, dolu ve soğuk suyla temizle. Ey Allah'ım! Beyaz elbisenin kirden temizlendiği gibi beni günahlardan ve hatalardan temizle.","en":"O Allah! our Lord, unto Thee be praise that would fill the heavens and the earth and fill that which will please Thee besides (them). O Allah! purify me with snow, (water of) hail and with cold water; O Allah. cleanse me from the sins and errors just as a white garment is cleansed from dirt."},{"id":879,"title":"Güvenli Yolculuk Duası (Yolcu Duası)","ref":"Hasen. Tirmizî: 3445","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_879.json","ar":"اَللَّهُمَّ اطْوِ لَهُ الْأَرْضَ وَهَوِّنْ عَلَيْهِ السَّفَرَ","latin":"Allâhümmutvi lehül-arda ve havvin aleyhis-sefer","tr":"Ey Allah'ım! Ona mesafeyi kısalt ve yolculuğunu kolaylaştır.","en":"O Allah make near for him the distance, and ease for him the journey."},{"id":880,"title":"Cemreye Taş Attıktan Sonra Okunacak Dua","ref":"Sahih Sened (Şuayb el-Arnaût). Müsned: 7/150","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_880.json","ar":"اَللَّهُمَّ اجْعَلْهُ حَجًّا مَّبْرُورًا، وَّذَنْۢبًا مَّغْفُوْرًا.","latin":"Allâhümmec'alhü haccen mebrûren ve zenben mağfûrâ","tr":"Ey Allah'ım! Bu haccı hac-ı mebrûr (hayırla dolu ve günahlardan arınmış hac) yap ve tüm günahları bağışla.","en":"O Allah, make this Hajj - Hajj Mabrur (full of goodness and free from sins) and forgive all sins."},{"id":881,"title":"Hac'ta Okunacak Dua (Hac Duası)","ref":"Sahih Li Ğayrihî (Albânî). Sahîhü't-Tergîb: 1122","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_881.json","ar":"اَللَّهُمَّ حَجَّةً لَا رِيَاءَ فِيْهَا وَلَا سُمْعَةَ","latin":"Allâhümme hacceten lâ riyâe fîhâ ve lâ sum'ah","tr":"Ey Allah'ım! Bu haccı içinde gösteriş olmayan ve şöhret aranmayan bir hac eyle.","en":"O Allah, make this Hajj a Hajj in which there is no showing off nor reputation sought."},{"id":883,"title":"Hacı İçin Uğurlama Duası","ref":"Hasen (Albânî). Sahîhü'l-Câmî: 3579","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_883.json","ar":"زَوَّدَكَ اللَّهُ التَّقْوَى وَغَفَرَ ذَۢنْبَكَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ","latin":"Zevvedekellâhüt-takvâ, ve ğafere zenbeke, ve yessere lekel-hayra haysü mâ künte","tr":"Allah sana takvayı azık olarak versin, günahını bağışlasın ve nerede olursan ol iyiliği sana kolaylaştırsın.","en":"May Allah give you piety as your provision, forgive your sins, and make goodness easy for you wherever you are."},{"id":884,"title":"Sa'y Sırasında Yeşil Işıklar Arasında Okunacak Dua","ref":"Mevkûf Sahih (İbn Hacer). el-Fütûhâtü'r-Rabbâniyye: 4/401","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_884.json","ar":"رَبِّ اغْفِرْ وَارْحَمْ، إِنَّكَ أَنْتَ الأَعَزُّ الأَكْرَمُ","latin":"Rabbigfir verham, inneke entel-a'azzül-ekrem","tr":"Ey Rabbim! Bağışla ve merhamet et; şüphesiz Sen en güçlü ve en cömert olansın.","en":"O Allah! Forgive me, You are the Mighty, the Merciful"},{"id":885,"title":"Safâ ve Merve İçin Dua","ref":"Müslim: 1218","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_885.json","ar":"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَآئِرِ اللَّهِ، أَبْدَأُ بِمَا بَدَأَ اللَّهُ بِهِ","latin":"İnnes-Safâ vel-Mervete min şeâirillâh. Ebdeü bimâ bedaallâhu bih.","tr":"Şüphesiz Safâ ve Merve Allah'ın nişanelerindendirİ. Allah'ın başladığı yerden başlıyorum.","en":"Surely Safa-Marwa is a sign of Allah. I am starting with what Allah has started"},{"id":886,"title":"Kâbe'ye Yönelince Okunacak Dua","ref":"Sahih. İbn Mâce: 2512","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_886.json","ar":"لَا إِلَهَ إِلَّا اللَّهُ‏ وَحْدَهُ ‏لَا شَرِيْكَ لَهُ‏، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ يُحْيِي وَيُمِيْتُ وَهَوُ عَلَى كُلِّ شَيْءٍ قَدِيْرٌ، لَا إِلَهَ إِلَّا اَللَّهُ وَحْدَهُ لَا شَرِيْكَ لَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَةُ.","latin":"Lâ ilâhe illallâhü vahdehû lâ şerîke leh, lehül-mülkü ve lehül-hamdü yuhyî ve yümîtü ve hüve alâ külli şey'in kadîr, lâ ilâhe illallâhü vahdehû lâ şerîke leh, enceze va'dehû ve nasara abdehû ve hezeme'l-ahzâbe vahdeh","tr":"Allah'tan başka ibadete layık ilâh yoktur, O birdir, ortağı yoktur. Mülk O'nundur ve hamd O'nadır. O, hayat verir ve ölüm verir; O her şeye kadirdir. Allah'tan başka ibadete layık ilâh yoktur, O birdir, ortağı yoktur. Vaadini yerine getirdi, kuluna yardım etti ve düşmanları tek başına bozguna uğrattı.","en":"None has the right to be worshipped but Allah alone, Who has no partner. His is the kingdom. Praise be to Him. He gives lives and he gives death. He has power over all things. None has the right to be worshipped but Allah alone, Who has no partner. He has fulfilled His promise, has helped His servant, and He alone has defeated His enemies."},{"id":887,"title":"Hac ve Umre İçin Dua","ref":"Menâsikü'l-Hac, Albânî, s. 16","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_887.json","ar":"لَبَّيْكَ اَللَّهمَّ بِحَجَّةٍ (لَبَّيْكَ حَجًّا)","latin":"Labbeyk Allâhümme bi-hacceh (Labbeyk haccen)","tr":"Ey Allah'ım! Hac için huzurundayım.","en":"O Allah! I am present for the purpose of Hajj."},{"id":888,"title":"Umre İçin Dua","ref":"Menâsikü'l-Hac, Albânî, s. 16","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_888.json","ar":"لَبَّيْكَ اللَّهمَّ بِعُمْرَةٍ","latin":"Labbeyk Allâhümme bi-umre","tr":"Ey Allah'ım! Umre için huzurundayım.","en":"O Allah! I am present for the purpose of 'Umrah."},{"id":889,"title":"Kâbe'yi Ziyaret Ederken Okunacak Dua","ref":"Hasen (Albânî). Beyhakî: 5/73","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_889.json","ar":"اَللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْك السَّلَامُ فَحَيِّنَا رَبَّنَا بِالسَّلَامِ","latin":"Allâhümme entes-selâm ve minkes-selâm, fe-hayyinâ rabbenâ bis-selâm","tr":"Ey Allah'ım! Sen selâmsın (esenlik kaynağısın) ve selâm Sendendir. Ey Rabbimiz! Bizi selâmet içinde yaşat.","en":"O, Allah! You are the peace (holy). Peace from you. Therefore, O our Lord! Keep us alive in peace."},{"id":891,"title":"Kurban Duası (Hac'ta)","ref":"İrvâü'l-Ğalîl: 1118","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_891.json","ar":"بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ اَللَّهُمَّ إِنَّ هَذَا مِنْكَ وَلَكَ اَللَّهُمَّ تَقَبَّلْ مِنِّي","latin":"Bismillâhi vallâhu ekber, Allâhümme inne hâzâ minke ve lek, Allâhümme tekabbel minnî","tr":"Allah'ın adıyla kesiyorum. Allah en büyüktür. Ey Allah'ım! Bu Sendendir ve Sana aittir. Ey Allah'ım! Benden kabul et.\n\nEğer aile adına kesiliyorsa 'Tekabbel Minnî'den sonra 'Ve min ehlî beytî' eklenir. Kurban başkası adına ya da akika hayvanı olarak kesiliyorsa 'Tekabbel Min'den sonra o kişinin ya da çocuğun adı söylenir. Bu konuda başka herhangi bir duanın sahih olmadığı bilinmektedir.","en":"I am sacrificing with the name of Allah. And Allah is the Greatest. O Allah! It's from you and for you. O Allah! Please accept it from me.\n\nIf it is on behalf of the family, then Wamin Ahli Baiti will be added after ‘Takbabbal Minni’. If the sacrifice is from someone else or if it is an Akika animal, take the name of that person or child after ‘Takabbal Min’. It is clear that no additional Dua on this subject is authentic."},{"id":892,"title":"Helal Rızık İçin Dua","ref":"Hasen (Albânî). Sahîhü'l-Câmî: 1677","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_892.json","ar":"اَللَّهُمَّ اغْفِرْ لِيْ خَطَايَايَ وَذُنُوبِيْ كُلَّهَا، اَللَّهُمَّ انْعِشْنِيْ وَأَحْيِنِيْ وَارْزُقْنِيْ وَاهْدِنِيْ لِصَالِحِ الْأَعْمَالِ وَالْأَخْلَاقِ، إِنَّهٗ لَا يَهْدِيْ لِصَالِحِهَا وَلَا يَصْرِفُ سَيِّئَهَا إِلَّا أَنْتَ.","latin":"Allâhümmağfir lî hatâyâye ve zünûbî küllehâ, Allâhümmen'iş-nî ve ahyinî verzuknî vehdini li-sâlihil-a'mâli vel-ahlâkı, innehû lâ yehdî li-sâlihihâ ve lâ yasrifu seyyiehâ illâ ent","tr":"Ey Allah'ım! Tüm hatalarımı ve günahlarımı bağışla. Ey Allah'ım! Beni yükselt, bana iyi bir hayat ver ve helal rızık ver. Beni güzel amellere ve güzel ahlaka ilet; zira güzel amellere ve güzel ahlaka ancak Sen iletebilirsin, kötü amellerden ve kötü ahlaktan ancak Sen uzaklaştırabilirsin.","en":"O Allah, forgive me all my sins. O Allah, grant me high rank. Give me a good life and halal food. Guide me also into the good behaviors and to avoid displaying some profane ones. Surely no one can guide me to good deeds and good morals except you. No one can save me from evil deeds and inferior character except you."},{"id":893,"title":"Tehlike Anında Okunacak Dua (İnnâ Lillâhi ve İnnâ İleyhi Râciûn)","ref":"Sahih. Tirmizî: 3511","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_893.json","ar":"إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُوْنَ، اَللَّهُمَّ عِنْدَكَ أَحْتَسِبُ مُصِيْبَتِيْ فَأْجُرْنِيْ فِيْهَا وَأَبْدِلْنِيْ مِنْهَا خَيْرًا.","latin":"İnnâ lillâhi ve innâ ileyhi râciûn, Allâhümme indeke ahtesibü musîbetî fecirnî fîhâ ve ebdilnî minhâ hayren","tr":"Şüphesiz biz Allah'a aitiz ve O'na döneceğiz. Ey Allah'ım! Musibetimi Sana arz ediyorum; bana bu konuda ecir ver ve onu benim için daha iyisiyle değiştir.","en":"Indeed, to Allah we belong and to Him we shall return. O Allah, I seek reward with You for my affliction, so reward me for it, and replace it for me with something better."},{"id":894,"title":"Kayıp Eşyaların Geri Dönmesi İçin Dua","ref":"Mevkûf Hasen (Beyhakî). ed-Da'vetü'l-Kebîr: 2/18","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_894.json","ar":"اَللَّهُمَّ رَادَّ الضَّالَّةِ وَهَادِيَ الضَّلَالَةِ أَنْتَ تَهْدِيْ مِنَ الضَّلَالَةِ، اُرْدُدْ عَلَيَّ ضَالَّتِيْ بِقُدْرَتِكَ وَسُلْطَانِكَ فَإِنَّهَا مِنْ عَطَائِكَ وَفَضْلِكَ.","latin":"Allâhümme râddad-dâlleti ve hâdiyad-dalâleti ente tehdî mined-dalâle, urdud aleyye dâlletî bi-kudretike ve sultâniki feinenhâ min atâike ve fadlik","tr":"Ey Allah'ım! Kaybedilenleri iade eden, yolu şaşıranları doğruya yönelten! Sen sapkınlıktan doğruya iletirsin. Kaybettiğimi güç ve sultanlığınla geri ver; zira bu şey Senin bağışından ve lütfundandır.","en":"O Allah, the Returner of lost things, the Guide to the lost, You are the Guide to the lost. You, in your power and strength, give me back what I lost. Because, this object is given by you and I got it by your grace."},{"id":895,"title":"Stres ve Kaygı İçin Dua","ref":"Hasen (Şuayb el-Arnaût). Tahrîcü Siyeri A'lâmi'n-Nübelâ: 16/551","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_895.json","ar":"لَا إِلٰهَ إِلَّا اللَّهُ الْحَلِيْمُ الْكَرِيْمُ، سُبْحَانَ اللَّهِ رَبِّ السَّمٰوَاتِ السَّبْعِ وَرَبِّ الْعَرْشِ الْعَظِيْمِ، اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِيْنَ","latin":"Lâ ilâhe illallâhül-halîmül-kerîm, sübhânallâhi rabbis-semâvâtis-seb'i ve rabbil-arşil-azîm, elhamdülillâhi rabbil-âlemîn","tr":"Allah'tan başka ilâh yoktur; O, sabırlı ve cömert olandır. Yedi göğün Rabbi ve yüce Arş'ın Rabbini tenzih ederim. Hamd, âlemlerin Rabbi Allah'a mahsustur.","en":"There is no true God but Allah the Most Patient, the Most Honorable. I am proclaiming the holiness of the Lord of the seven heavens and the Lord of the glorious throne. All praise is due to Allah, the Lord of the worlds."},{"id":896,"title":"Savaşta ve Mücadelede Yardım İçin Dua","ref":"Sahih (Albânî). Silsiletü's-Sahîha: 1061","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_896.json","ar":"اَللَّهُمَّ بِكَ أُقَاتِلُ وَبِكَ أُصَاوِلُ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Allâhümme bike ukâtilü ve bike üsâvilü ve lâ havle ve lâ kuvvete illâ billâh","tr":"Ey Allah'ım! Senin yardımınla savaşıyorum, Senin yardımınla saldırıyorum. Güç ve kuvvet ancak Allah iledir.","en":"O Allah, I fight with Your help, I attack with Your help. No power or ability is (effective) without your help."},{"id":897,"title":"Savaştan Önce Mesnun Dua","ref":"Müslim: 1731","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_897.json","ar":"اُغْزُوا بِاسْمِ اللَّهِ فِي سَبِيْلِ اللَّهِ قَاتِلُوا مَنْ كَفَرَ بِاللَّهِ اُغْزُوا وَلَا تَغُلُّوا وَلَا تَغْدِرُوا وَلَا تَمْثُلُوا وَلَا تَقْتُلُوا وَلِيْدًا","latin":"Uğzû bismillâhi fî sebîlillâhi kâtilû men kefere billâh. Uğzû ve lâ tağullû ve lâ tağdirû ve lâ temsilû ve lâ taktülû veleden","tr":"Allah'ın adıyla ve Allah'ın yolunda savaşın; Allah'ı inkâr edenlerle çarpışın. Savaşın; ama ganimetlere hainlik etmeyin, ahdi bozmayın, ölülere zarar vermeyin ve çocuk öldürmeyin.\n\nKüçük ya da büyük bir ordunun emirliğine (ya da çağın hükümdarı adına) biri tayin edildiğinde, kendisini ve yanındaki Müslümanları (askerleri) güzel muameleyle vasiyetle uğurlar. Sonra şunu söyler — (yukarıda geçen dua)","en":"Fight in the name of Allaah and in the path of Allaah and with him who disbelieves in Allaah fight and do not be treacherous and do not be dishonest about boot yand do not deface (in killing) and do not kill a child.\n\nIf someone is made the amir (commander) of a small or large army (or on behalf of a contemporary ruler) he will bequeath to him the fear of Allah about himself and to treat the Muslims (Soldiers) under him well. Then say - (the Dua is mentioned above)"},{"id":898,"title":"Birini Gülerken Gördüğünde Söylenecek Nebevî Dua","ref":"Buhârî: 3294","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_898.json","ar":"أَضْحَكَ اللَّهُ سِنَّكَ","latin":"Edhakallâhü sinneke","tr":"Allah seni daima mutlu kılsın.","en":"May Allah keep you happy always."},{"id":899,"title":"Borç Ödemek İçin Nebevî Dua","ref":"Buhârî: 2305","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_899.json","ar":"أَوْفَيْتَنِيْ أَوْفَى اللَّهُ بِكَ","latin":"Evfeyteni evfallahu bike","tr":"Borcumu tam olarak ödedin, Allah da sana tam olarak karşılık versin.","en":"You have repaid my debt in full, may Allah reward you in full."},{"id":900,"title":"Peygamber'in Savaş Tavsiyeleri (Güvenlik Duası)","ref":"Buhârî: 2966","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_900.json","ar":"يَا أَيُّهَا النَّاسُ لَا تَتَمَنَّوْا لِقَاءَ الْعَدُوِّ وَسَلُوْا اللَّهَ الْعَافِيَةَ، فَإِذَا لَقِيْتُمُوْهُمْ فَاصْبِرُوْا، وَاعْلَمُوْا أَنَّ الْجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ.","latin":"Yâ eyyühen-nâs, lâ tetemennev likâel-adüvvi ve sellullâhel-âfiyeh, fâ idhâ lekîtümûhüm fasbiru vâ'lemû ennel-cennete tahte zilâlis-süyûf","tr":"Ey insanlar! Düşmanla karşılaşmayı arzulamayın; Allah'tan afiyet dileyin. Ama düşmanla karşılaşırsanız, sabredin ve bilin ki Cennet kılıçların gölgesi altındadır.","en":"O people! Do not wish to face the enemy (in a battle) and ask Allah to save you (from calamities) but if you should face the enemy, then be patient and let it be known to you that Paradise is under the shades of swords."},{"id":901,"title":"Düşmana Karşı En Güçlü Dua","ref":"Buhârî: 2966","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_901.json","ar":"اَللَّهُمَّ مُنْزِلَ الْكِتَابِ، وَمُجْرِيَ السَّحَابِ، وَهَازِمَ الْأَحْزَابِ، اِهْزِمْهُمْ وَانْصُرْنَا عَلَيْهِمْ.","latin":"Allâhümme münzilel-kitâbi ve mücriyes-sehâbi ve hâzilel-ahzâb, ihzimhüm vensurnâ aleyhim","tr":"Ey Allah'ım! Kitabı indiren, bulutları sevk eden ve Ahzâb'ı bozguna uğratan! Onları boz ve bize karşı bize zafer ver.","en":"O Allah! The Revealer of the (Holy) Book, the Mover of the clouds, and Defeater of Al-Ahzab (i.e. the clans of infidels), defeat them infidels and bestow victory upon us."},{"id":902,"title":"Düşmanla Yüz Yüze Gelince Söylenecek Söz (Mesnun Dua)","ref":"Buhârî: 4197","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_902.json","ar":"إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِيْنَ","latin":"İnnâ idhâ nezelnâ bi-sâhati kavmin, fesâe sabâhul-münzerîn","tr":"Biz bir topluluğun meydanına indiğimizde, uyarılmış olanların sabahı ne kötü olur.","en":"Surely when we approach a (hostile) nation (to fight), then evil will be the morning for those who have been warned.\""},{"id":903,"title":"İlim İçin Güçlü İslami Dua","ref":"Sahih (Albânî). Silsiletü's-Sahîha: 3151","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_903.json","ar":"اَللَّهُمَّ انْفَعْنِيْ بِمَا عَلَّمْتَنِيْ وَعَلِّمْنِيْ مَا يَنْفَعُنِيْ وَارْزُقْنِيْ عِلْمًا تَنْفَعُنِيْ بِهِ.","latin":"Allâhümmen-fa'nî bimâ allemtenî ve allimnî mâ yenfa'ünî verzuknî ilmen tenfa'ünî bih","tr":"Ey Allah'ım! Bana öğrettiğin bilgiyle beni faydalandır. Bana faydalı olacak ilmi öğret ve beni onunla faydalandıracağın bir ilim ver.","en":"O Allah, benefit me with the knowledge You have bestowed on me. Give me the knowledge that will benefit me and give me the knowledge by which you will benefit me."},{"id":904,"title":"İslami Selamlama (Esselâmü Aleyküm ve Rahmetullah)","ref":"Sahih (Albânî). Ebû Dâvûd: 5195","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_904.json","ar":"اَلسَّلَامُ عَلَيْكُمْ","latin":"Esselâmü aleyküm","tr":"Size selâm olsun!\n\nBir başkası gelip şöyle dedi:","en":"Peace be upon you!\n\nAnother man came and said:"},{"id":905,"title":"Yemek Bittikten Sonra Okunacak Dua","ref":"Sahih (Ahmed Şâkir). Umdetü't-Tefsîr: 1/865","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_905.json","ar":"اَلْحَمْدُ لِلَّهِ الَّذِيْ يُطْعِمُ وَلَا يُطْعَمُ، مَنَّ عَلَيْنَا فَهَدَانَا وَأَطْعَمَنَا وَسَقَانَا وَكُلَّ بَلَاءٍ حَسَنٍ أَبْلَانَا، اَلْحَمْدُ لِلَّهِ غَيرَ مُوَدَّعٍ وَّلَا مُكَافَأٍ وَّلَا مُكَافَأٍ وَّلَا مَكْفُوْرٍ وَّلَا مُسْتَغْنًى عَنْهُ، اَلْحَمْدُ لِلَّهِ الَّذِيْ أَطْعَمَ مِنَ الطَّعَامِ وَسَقٰى مِنَ الشَّرَابِ وَكَسٰی مِنَ العُرْيِ وَهَدٰى مِنَ الضَّلَالَةِ وَبَصَّرَ مِنَ العَمْيِ وَفَضَّلَ عَلٰى كَثِيْرٍ مِمَّنْ خَلَقَ تَفْضِيلًا، اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ.","latin":"Elhamdülillâhillezî ut'eme ve lâ yut'am, menne aleynâ fe-hedânâ ve at'amenâ ve sekânâ ve külle belâin hasenin eblenâ, elhamdülillâhi ğayre müvedda'in ve lâ mükâfain ve lâ mükâfain ve lâ mekfûrin ve lâ müstağnan anh, elhamdülillâhillezî at'ame minet-ta'âmi ve sekâ mineş-şerâbi ve kesâ minel-üryi ve-hedâ mined-dalâleti ve bessara minel-amyâi ve faddele mimmen halaqa tafdîlen, elhamdülillâhi rabbil-âlemîn","tr":"Hamd, yediren fakat yemeyen Allah'adır. Bize lütfetti, hidayet etti, yedirdi, içirdi ve bize her güzel nimeti bahşetti. Hamd, hiçbir zaman terk edilemeyen, karşılığı ödenemeyen, nankörlük edilemeyen ve ihtiyaç duyulmaktan vazgeçilemeyen Allah'adır. Hamd, bize yiyecek yediren, su içiren, giydiren, sapkınlıktan koruyan, körlükten (küfür karanlığından) aydınlatan ve yarattıklarının pek çoğuna üstün kılan Allah'adır. Hamd, âlemlerin Rabbi Allah'adır.","en":"All praise is due to Allah, Who feeds (His servants) but does not eat. He has begged us to guide us (to the true religion). He has fed us, made us drink and bestowed on us all the advanced blessings. All praise is due to Allah, Who can never be forsaken, Whose exchange can never be repaid, Whose ungratefulness can not be done, From whom there can be no need. Many thanks to Allah, Who has shown us the right path (to feed us, to give us water to drink, to clothe us, to protect us from error). (From disbelief) from darkness (by faith) has given to Allah. Has given us superiority over many creations. All praise is due to Allah."},{"id":906,"title":"Yemekten Sonra Okunacak Dua","ref":"Sahih (Albânî). Kelimü't-Tayyib: 190","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_906.json","ar":"اَللَّهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ، وَأَغْنَيْتَ وَأَقْنَيْتَ، وَهَدَيْتَ وَأَحْيَيْتَ، فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ","latin":"Allâhümme at'amte ve eskayte ve ağneyte ve eknayte ve hedayte ve ahyayte, fe lekel-hamdü alâ mâ a'tayt","tr":"Ey Allah'ım! Yedin ve içirdin, zengin kıldın ve yeterince verdin, hidayet ettin ve hayat verdin; verdiğin şeyler için Sana hamd olsun.","en":"O Allah you gave me food and drink, You had enriched (me) and sufficed (me), (You) had guided (me) and gave (me) life, therefore, I praise you for what you had given (me)."},{"id":907,"title":"Yağmur Duası (Salâtü'l-İstiskâ)","ref":"Hasen. Ebû Dâvûd: 1173","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_907.json","ar":"اَلْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَٰنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ لَا إِلٰهَ إِلَّا اللَّهُ يَفْعَلُ مَا يُرِيْدُ اَللَّهُمَّ أَنْتَ اللَّهُ لَا إِلٰهَ إِلَّا أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ أَنْزِلْ عَلَيْنَا الْغَيْثَ وَاجْعَلْ مَا أَنْزَلْتَ لَنَا قُوَّةً وَّبَلَاغًا إِلٰى حِيْنٍ.","latin":"Elhamdülillâhi rabbil-âlemîn, er-rahmânir-rahîm, mâliki yevmid-dîn, lâ ilâhe illallâhü yef'alü mâ yürîd, Allâhümme entel-lâhü lâ ilâhe illâ entel-ğaniyyü ve nahnül-fükarâ, enzil aleynel-ğays, vec'al mâ enzelte lenâ kuvveten ve belâğan ilâ hîn","tr":"Hamd âlemlerin Rabbi, Rahmân ve Rahîm, Din Günü'nün Sahibi Allah'adır. Allah'tan başka ilâh yoktur; O dilediğini yapar. Ey Allah'ım! Sen Allah'sın; Senden başka ilâh yoktur. Sen zenginsin, biz ise fakiriz. Üzerimize yağmur indir; indirdiğini bizim için bir süreye kadar güç ve yeterliliğe vesile kıl.\n\nSonra her iki eli (göğe doğru) kaldır; koltuk altlarının beyazlığı görünecek kadar yükselt. Ardından (kıbleye dönerek) halka arkanı dön, elbiseni ters çevir (altı üste, üstü alta, sağ tarafı sola, sol tarafı sağa). Bu esnada elleri (aynı şekilde) yukarıda tut. Sonra halka geri dön, minberden in ve iki rekât Salâtü'l-İstiskâ kıl.","en":"Praise be to Allah, the Lord of the Universe, the Compassionate, the Merciful, the Master of the Day of Judgment. There is no god but Allah Who does what He wishes. O Allah, Thou art Allah, there is no deity but Thou, the Rich, while we are the poor. Send down the rain upon us and make what Thou sendest down a strength and satisfaction for a time.\n\nThen raise both hands (towards the sky so high), So that the whiteness of the armpits (i.e. the inner part of the armpits) can be seen. Then, with the back to the assembled people (facing the Ka'bah), turn your cloth over (lower part up, upper part down, right part left, and left part right). At this time keep the hand (in the same way towards the sky) high. Then you will return to the people, get down from the pulpit, and pray two rak'aats of Salatul istesqaah."},{"id":908,"title":"Şiddetli Yağmurdan Korunma Duası","ref":"Sahih. İbn Mâce: 3889","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_908.json","ar":"اَللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ شَرِّ مَا أُرْسِلَ بِهِ اَللَّهُمَّ سَيْبًا نَافِعًا.","latin":"Allâhümme innâ neûzü bike min şerri mâ ürsile bih, Allâhümme sayyiben nâfi'an","tr":"Ey Allah'ım! Yağmurun gönderildiği şeyin şerrinden Sana sığınırız. Ey Allah'ım! Bunu faydalı bir yağmur eyle.","en":"O Allah, we seek refuge with You from the evil of that with which it is sent. O Allah, make it a beneficial rain."},{"id":909,"title":"Yağmur Hasarından Korunma Duası","ref":"Sahih. Tirmizî: 2252","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_909.json","ar":"اَللَّهُمَّ إِنَّا نَسْأَلُكَ مِنْ خَيْرِ هٰذِهِ الرِّيْحِ، وَخَيْرِ مَا فِيْهَا، وَخَيْرِ مَا أُمِرَتْ بِهِ وَنَعُوْذُ بِكَ مِنْ شَرِّ هٰذِهِ الرِّيْحِ وَشَرِّ مَا فِيْهَا وَشَرِّ مَا أُمِرَتْ بِهِ","latin":"Allâhümme innâ nes'elüke min hayri hâzihir-rîh, ve hayri mâ fîhâ ve hayri mâ ümiret bih, ve neûzü bike min şerri hâzihir-rîh ve şerri mâ fîhâ ve şerri mâ ümiret bih","tr":"Ey Allah'ım! Bu rüzgârın hayrını, içindeki hayırları ve emredildiği hayırları Senden dileriz. Bu rüzgârın şerrinden, içindeki şerlerden ve emredildiği şerlerden de Sana sığınırız.","en":"O Allah! Indeed we ask you of the good of this wind, and the good of what is in it, and the good of what it has been commanded. And we seek refuge in You from the evil of this wind, and the evil of what is in it, and the evil of what it has been commanded."},{"id":910,"title":"Güvenlik ve Bereket İçin Fırtına Duası","ref":"Hasen (Albânî). Silsiletü's-Sahîha: 2058","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_910.json","ar":"اَللَّهُمَّ لَقْحًا، لَا عَقِيْمًا","latin":"Allâhümme lakyâ lâ akyâ","tr":"Ey Allah'ım! Bunu bereketli bir yağmur yap, kısır bir rüzgar etme.","en":"O Allah, make (this storm) a rainstorm, do not make it barren."},{"id":911,"title":"Yağmur Güvenliği İçin Dua","ref":"Sahih (İbn Hacer el-Askalânî). Fethu'l-Bârî: 2/604, Sahih (Vâdi'î). Sahîhü'l-Müsned: 73","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_911.json","ar":"اَللَّهُمَّ إِنِّيْ أَسْأَلُكَ مِنْ خَيْرِ مَا أُمِرَتْ بِهِ، وَأَعُوْذُ بِكَ مِنْ شَرِّ مَا أُمِرَتْ بِهِ","latin":"Allâhümme innî es'elüke min hayri mâ ümiret bih, ve eûzü bike min şerri mâ ümiret bih","tr":"Ey Allah'ım! Bu fırtınaya emredilen hayırları Senden dilerim ve bu fırtınaya emredilen şerlerden Sana sığınırım.","en":"O Allah, I seek refuge in You from the evil that has been directed to this storm, and I seek refuge in You from the evil that has been directed to this storm."},{"id":912,"title":"Yağmur İçin Dua","ref":"Sahih. Ebû Dâvûd: 5099","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_912.json","ar":"اللَّهُمَّ صَيِّبًا هَنِيْئًا","latin":"Allâhümme sayyiben henîâ","tr":"Ey Allah'ım! Faydalı ve bereketli bir yağmur indir.","en":"O Allah! send a beneficial downpour."},{"id":913,"title":"İyileşmez Hastalık İçin Dua","ref":"Buhârî: 5671","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_913.json","ar":"اَللَّهُمَّ أَحْيِنِيْ مَا كَانَتِ الْحَيَاةُ خَيْرًا لِّيْ، وَتَوَفَّنِيْ إِذَا كَانَتِ الْوَفَاةُ خَيْرًا لِّيْ","latin":"Allâhümme ahyinî mâ kânetil-hayâtü hayren lî, ve teveffenî idhâ kânetil-vefâtü hayren lî","tr":"Ey Allah'ım! Yaşamak benim için hayırlı olduğu müddetçe beni yaşat; ölüm benim için hayırlı olduğunda ise canımı al.","en":"O Allah! Keep me alive as long as life is better for me, and let me die if death is better for me."},{"id":914,"title":"Hasta Kişi İçin Dua (Şifa Duası)","ref":"Sahih. Ebû Dâvûd: 3107","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_914.json","ar":"اَللَّهُمَّ اشْفِ عَبْدَكَ يَنْكَأُ لَكَ عَدُوًّا، أَوْ يَمْشِيْ لَكَ إِلٰى جَنَازَةٍ.","latin":"Allâhümmeşfi abdeke yenkau leke adüvvan ev yemşî leke ilâ cenâze","tr":"Ey Allah'ım! Kulunu şifa ver; böylece Senin yolunda düşmana karşı çarpışabilsin ya da cenaze namazına yürüyebilsin.","en":"O Allah, cure Thy servant, who may then wreak havoc on an enemy for your sake, or walk at a funeral for your sake."},{"id":915,"title":"Şehadet İçin Güçlü Dua","ref":"Buhârî: 1890","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_915.json","ar":"اَللَّهُمَّ ارْزُقْنِيْ شَهَادَةً فِيْ سَبِيْلِكَ، وَاجْعَلْ مَوْتِيْ فِي بَلَدِ رَسُوْلِكَ (ﷺ).","latin":"Allâhümmer-zuknî şehâdeten fî sebîlik, vec'al mevtî fî beledi resûlik (sallallahu aleyhi ve sellem)","tr":"Ey Allah'ım! Bana yolunda şehadeti nasip et ve ölümümü Resûlünün şehrinde (Medine'de) kıl.","en":"O Allah! Grant me martyrdom in Your cause, and let my death be in the city of Your Apostle (Madina)."},{"id":916,"title":"Ağrı Giderme Duası (Mesnun Dua)","ref":"Sahih. Tirmizî: 3588","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_916.json","ar":"أَعُوْذُ بِعِزَّةِ اللَّهِ وَقُدْرَتَهٖ مِنْ شَرِّ مَا أَجِدُ مِنْ وَجَعِي هٰذَا","latin":"Eûzü bi-izzatillâhi ve kudretihî min şerri mâ ecidü min veca'î hâzâ","tr":"Hissettiğim bu ağrının şerrinden Allah'ın izzetine ve kudretine sığınırım.","en":"I seek refuge in Allah’s might and power from the evil of this pain I feel."},{"id":917,"title":"Ölüme Kadar İmanı Koruma Duası","ref":"Zâid Sened (Muhammed ibn Abdilvehhâb). el-Hadîs li-İbn Abdilvehhâb: 3/145","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_917.json","ar":"اَللَّهُمَّ إِنَّكَ قُلْتَ : اُدْعُوْنِيْ أَسْتَجِبْ لَكُمْ، وَإِنَّكَ لَا تُخْلِفُ الْمِيعَادَ، وَإِنِّيْ أَسْأَلُكَ كَمَا هَدَيْتَنِيْ لِلْإِسْلَامِ أَنْ لَّا تَنْزِعَهُ مِنِّيْ حَتّٰى تَتَوَفَّانِيْ وَأَنَا مُسْلِمٌ","latin":"Allâhümme inneke kulte: ud'ûnî estecib leküm, ve inneke lâ tühliful-mîâd, ve innî es'elüke kemâ hedeytenî lil-islâmi en lâ tenziah minnî hattâ teteveffenî ve enâ müslimün","tr":"Ey Allah'ım! Şüphesiz Sen 'Bana dua edin, size icabet edeyim' buyurdun ve Sen vaadinden dönmezsin. Ben de Senden; beni İslam'a hidayet ettiğin gibi, onu Müslüman olarak vefat edene kadar benden almamanlığını dilerim.","en":"O Allah, surely you have said, pray to Me, I will answer your prayers. Surely you do not break the promise. I pray to you, do not deprive me of the way you have given me Islam (and the blessings of faith). Finally, let me die on Islam."},{"id":918,"title":"Ağrı Giderme İçin Güçlü Dua","ref":"Sahih Li Ğayrihî (Albânî). Silsiletü's-Sahîha: 1415","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_918.json","ar":"أَعُوْذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهٖ عَلٰى كُلِّ شَيْءٍ مِّنْ شَرِّ مَا أَجِدُ","latin":"Eûzü bi-izzatillâhi ve kudretihî alâ külli şey'in min şerri mâ ecid","tr":"Hissettiğim ağrının şerrinden, Allah'ın her şey üzerindeki izzetine ve kudretine sığınırım.","en":"I seek refuge in the dignity of Allah and His might over all things from the pain I feel."},{"id":919,"title":"Korunma İçin Mâşâallah Duası (Kehf Sûresi)","ref":"Kehf Sûresi: 39","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_919.json","ar":"مَا شَاءَ اللَّهُ لَا قُوَّةَ إِلَّا بِاللَّهِ","latin":"Mâ şâallâhü lâ kuvvete illâ billâh","tr":"Allah'ın dilediği olur; güç ve kuvvet ancak Allah iledir.","en":"(This is) what Allah wills, and there is no might except by Allah."},{"id":920,"title":"Günahların Bağışlanması İçin Dua (Mesnun Dua)","ref":"Sahih (Şuayb el-Arnaût). İbn Hibbân: 954","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_920.json","ar":"اَللَّهُمَّ اغْفِرْ لِيْ جِدِّيْ وَهَزْلِيْ وَخَطَئِيْ وَعَمْدِيْ وَكُلُّ ذٰلِكَ عِنْدِيْ","latin":"Allâhümmağfir lî ciddî ve hezlî ve hataî ve amdî ve küllü zâlike indî","tr":"Ey Allah'ım! Ciddiye alarak ve şaka yollu yaptıklarımı, hatalarımı ve kasıtlı işlediklerimi bağışla; bunların hepsi bende mevcuttur.","en":"O Allah, forgive me all the sins I have committed knowingly, the mistakes I have made with laughter, the mistakes I have made willingly, the mistakes I have made reluctantly."},{"id":921,"title":"Günahlar ve Hatalar İçin Bağışlanma Duası","ref":"Sahih (Albânî). Sahîhü'l-Mevârid: 2059","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_921.json","ar":"اَللَّهُمَّ اغْفِرْ لِيْ ذُنُوْبِيْ وَخَطَئِيْ وَعَمْدِيْ","latin":"Allâhümmağfir lî zünûbî ve hatâye ve amdî","tr":"Ey Allah'ım! Tüm günahlarımı bağışla; kasıtsız yapılanları da, kasıtlı yapılanları da.","en":"O Allah, forgive my (all) sins. Even unintentional sins, even sins committed willingly."},{"id":922,"title":"Sebat İçin Dua (Mesnun Dua)","ref":"Tüm senetlerle sabit (Albânî). Silsiletü's-Sahîha: 1823","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_922.json","ar":"يَا وَلِيَّ الْإِسْلَامِ وَأَهْلِهُ ثَبِّتْنِيْ بِهِ حَتّٰى أَلْقَاكَ.","latin":"Yâ veliyyel-islâmi ve ehlih, sebbitnî bihî hattâ elkâk","tr":"Ey İslam'ın ve Müslümanların dostu! Seninle kavuşma şerefine erişeceğim güne kadar beni İslam üzere sabit kıl.","en":"O guardian of Islam and Muslims, keep me steadfast on Islam till the day when I will have the good fortune to meet you."},{"id":923,"title":"Muhacirler ve Ensâr İçin Bağışlanma Duası","ref":"Müslim: 1805","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_923.json","ar":"اَللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ الآخِرَه فَاغْفِرْ لِلْمُهَاجِرِينَ وَالْأَنْصَارِ","latin":"Allâhümme lâ aişe illâ aişel-âhire, fağfir lil-muhâcirîne vel-ensâr","tr":"Ey Allah'ım! Ahiret hayatından başka gerçek bir hayat yoktur; Muhacirleri ve Ensârı bağışla.","en":"O Allah, there is no (real) life except the Hereafter, so forgive the Muhajirs and the Ansar."},{"id":924,"title":"Günahlar ve Hatalar İçin Bağışlanma Duası","ref":"Buhârî: 6399","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_924.json","ar":"اَللَّهُمَّ اغْفِرْ لِي خَطِيْئَتِي وَجَهْلِي، وَإِسْرَافِي فِي أَمْرِي، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، اَللَّهُمَّ اغْفِرْ لِي هَزْلِي وَجِدِّي وَخَطَايَايَ وَعَمْدِي، وَكُلُّ ذَلِكَ عِنْدِي","latin":"Allâhümmağfir lî hatîetî ve cehlî ve isrâfî fî emrî ve mâ ente a'lemü bihî minnî, Allâhümmağfir lî hezlî ve ciddî ve hatâyâye ve amdî ve küllü zâlike indî","tr":"Ey Allah'ım! Hatamı, cehaletime düşmemi, işlerimdeki aşırılığımı ve Sen benim hakkımda benden daha iyi bildiklerimi bağışla. Ey Allah'ım! Şaka yollu ve ciddi olarak yaptıklarımı, istemeyerek ve bilerek işlediklerimi bağışla; bunların hepsi bende mevcuttur.","en":"O Allah, forgive my sin, my ignorance, my excessiveness in my affairs, and whatever You are better aware (of my affairs) than myself. O Allah, grant me forgiveness [of the faults which I committed] jestingly or in earnest, and which I committed inadvertently and deliberately; and indeed, all of these [failings] are in me."},{"id":925,"title":"Bağışlanma ve Kalp Temizliği İçin Dua","ref":"Sahih (Albânî). Müsned Ahmed: 22265","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_925.json","ar":"اَللَّهُمَّ اغْفِرْ ذَۢنْبِي وَطَهِّرْ قَلْبِي، وَحَصِّنْ فَرْجِي","latin":"Allâhümmağfir zenbî ve tahhir kalbî ve hassin fercî","tr":"Ey Allah'ım! Günahımı bağışla, kalbimi temizle ve iffetimi koru.","en":"O Allah forgive my sin, cleanse my heart and guard my chastity."},{"id":926,"title":"Bayram Tekbiri (Tekbirü'l-Îd)","ref":"Hasen (Albânî). Musannef: 5650","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_926.json","ar":"اَللَّهُ أَكْبرُ اَللَّهُ أَكْبَرُ، لَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ اَللَّهُ أَكْبَرُ وَلِلَّهِ الْحَمْدُ","latin":"Allahu Ekber, Allahu Ekber, lâ ilâhe illallâhü vallahu Ekber, Allahu Ekber ve lillâhil hamd","tr":"Allah en büyüktür. Allah en büyüktür. Allah'tan başka ibadete layık ilâh yoktur. Allah en büyüktür. Allah en büyüktür. Hamd Allah'adır.","en":"Allah is great. Allah is great. There is no worthy of worship except Allah. Allah is great. Allah is great. All praise is due to Allah."},{"id":927,"title":"Bayram Tekbiri","ref":"İrvâü'l-Ğalîl, Albânî: 3/125","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_927.json","ar":"اَللَّهُ أَكْبَرُ، اَللَّهُ أَكْبَرُ، اَللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ، اَللَّهُ أَكْبَرُ وَأَجَلُّ، اَللَّهُ أَكْبَرُ عَلىَ مَا هَدَانَا","latin":"Allahu Ekber, Allahu Ekber, Allahu Ekber, ve lillâhil hamd, Allahu Ekber ve ecell, Allahu Ekber alâ mâ hedânâ","tr":"Allah en büyüktür. Allah en büyüktür. Allah en büyüktür. Hamd Allah'adır. Allah en büyük ve en yücedir. Allah bizi hidayete erdirdiği için en büyüktür.","en":"Allah is great. Allah is great. Allah is great. All praise is due to Allah. Allah is great and Most High. Allah is great because He has guided us."},{"id":928,"title":"Bayram Tekbiri (Allahu Ekber Kebîrâ)","ref":"[1] İrvâü'l-Ğalîl, Albânî: 3/126 [2] Buhârî: 971 [3] Es'iletün ve ecvibetün fî salâtil-îdeyn: s. 31-32","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_928.json","ar":"اَللَّهُ أَكْبَرُ كَبِيْرًا، اَللَّهُ أَكْبَرُ كَبِيْرًا، اَللَّهُ أَكْبَرُ وَأَجَلُّ، اَللَّهُ أَكْبَرُ، وَلِلَّهِ الْحَمْدُ","latin":"Allahu Ekber kebîrâ, Allahu Ekber kebîrâ, Allahu Ekber ve ecell, Allahu Ekber, ve lillâhil hamd. [1]","tr":"Allah en büyük, pek büyüktür. Allah en büyük, pek büyüktür. Allah büyük ve en yücedir. Allah en büyüktür. Hamd Allah'adır.\n\nKadınlar da bu tekbiri getirecek; ancak mahrem olmayan erkeklerin seslerini duymaması için kısık sesle yapacaklardır. Ümmü Atiyye (radıyallahu anhâ) şöyle dedi: 'Hayızdaki kadınları da bayram namazı kılınan yere götürürdük. Erkeklerin arkasında duruyorlardı; erkeklerin tekbirini duyunca onlar da tekbir getiriyorlar, duaları duyunca onlar da dua ediyorlardı. O günün bereketini ve kutsiyetini umuyorlardı.' [2] Öte yandan, toplu hâlde aynı anda veya tek sesle tekbir getirmek bidattir. Zira Peygamber'in (sallallahu aleyhi ve sellem) sünneti şudur: Allah zikrinde her kişi kendi zikrini tek başına yapacaktır. Bu nedenle Peygamber'in ve sahâbîlerin ilkesinden kimsenin sapması doğru değildir. [3]","en":"Allah is the Greatest, Most Great. Allah is the Greatest, Most Great. Allah is great and Most High. Allah is the Greatest, All praise is due to Allah.\n\nWomen will also recite this takbeer, but in a low voice. So that non mahram can't hear the sound of this takbeer. Umm Atiyah (RA) said, ‘Even we used to take menstruating women out to the Eidgah. They stood behind the men; They used to recite takbeer after hearing their takbeer and they also used to recite dua after hearing their dua. They hoped for the blessings and holiness of that day.' [2] On the other hand, it is bid'ah to recite the takbeer of the congregation in one voice or the recitation of the takbeer by all at the same time. Since the sunnah of the Prophet (ﷺ) is: In the dhikr of Allaah, each person will recite his own dhikr alone. So it is not right for anyone to deviate from the ideals of him and his companions. [3]"},{"id":929,"title":"Bayram Tebrik Duası (Tekabbelallahu Minnâ ve Minküm)","ref":"Hasen (İbn Hacer el-Askalânî). Fethu'l-Bârî: 2/517","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_929.json","ar":"تَقَبَّلَ اللَّهُ مِنَّا وَمِنْكَ","latin":"Tekabbelallahu minnâ ve minke","tr":"Allah (iyi amelleri) bizden ve senden kabul etsin.\n\nÇoğul kipinde 'Minke' yerine 'Minküm' kullanılır.","en":"May Allah accept it (good deeds) from us and you.\n\nIn the case of plural, 'Minka' will be replaced by 'Minkum'."},{"id":941,"title":"Hataların Bağışlanması İçin Dua (Rabbenâ Duası)","ref":"Bakara Sûresi: 2/286","url":"https://quran.com/2/286","ar":"رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا","latin":"Rabbi zidnî ilmâ","tr":"Ey Rabbimiz! Unutur ya da hata yaparsak bizi sorumlu tutma.","en":"Our Lord, do not impose blame upon us if we have forgotten or erred."},{"id":965,"title":"Ağır Yüklerden Kurtulma Duası","ref":"Bakara Sûresi: 2/286","url":"https://quran.com/2/286","ar":"رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا","latin":"Rabbenâ ve lâ tahmil aleynâ isran kemâ hameltehû alellezîne min kablinâ.","tr":"Ey Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yük yükleme.","en":"Our Lord, and lay not upon us a burden like that which You laid upon those before us."},{"id":966,"title":"Rahatlama ve Bağışlanma İçin Rabbenâ Duası (Bakara Sûresi)","ref":"Bakara Sûresi: 2/286","url":"https://quran.com/2/286","ar":"رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ","latin":"Rabbenâ ve lâ tühammilnâ mâ lâ tâkate lenâ bih; va'fü annâ vağfir lenâ verhamnâ; Ente Mevlânâ fensurnâ alel-kavmil-kâfirîn.","tr":"Ey Rabbimiz! Bize taşıyamayacağımız yükü yükleme. Bizi affet, bizi bağışla ve bize merhamet et. Sen bizim Mevlâmızsın; kâfir topluma karşı bize yardım et.","en":"Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people."},{"id":968,"title":"Kıyamet Günü İçin Dua (Rabbenâ Duası)","ref":"Âl-i İmrân Sûresi: 3/9","url":"https://quran.com/3/9","ar":"رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لَّا رَيْبَ فِيهِ ۚ إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ ‎﴿٩﴾‏","latin":"Rabbenâ inneke câmiun-nâsi li-Yevmil-lâ reybe fîh; innallâhe lâ yuhlifül-mîâd.","tr":"Ey Rabbimiz! Şüphesiz Sen insanları, hakkında hiç şüphe olmayan bir günde toplayacaksın. Gerçekten Allah vaadinden dönmez.","en":"Our Lord, surely You will gather the people for a Day about which there is no doubt. Indeed, Allah does not fail in His promise."},{"id":972,"title":"Cehennem Azabından Korunma Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi: 3/191","url":"https://quran.com/3/191","ar":"رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَاطِلًا سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ ﴿١٩١﴾","latin":"Rabbenâ mâ halekte hâżâ bâtilâ Sübhâneke fekınâ azâben-Nâr.","tr":"Ey Rabbimiz! Sen bunu boşuna yaratmadın; Sen her türlü noksanlıktan münezzehsin. Bizi cehennem azabından koru.","en":"Our Lord, You did not create this aimlessly; exalted are You [above such a thing]; then protect us from the punishment of the Fire."},{"id":973,"title":"Zalimlerin Şerrinden Korunma İçin Rabbenâ Duası (Âl-i İmrân Sûresi)","ref":"Âl-i İmrân Sûresi: 3/192","url":"https://quran.com/3/192","ar":"رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ ۖ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ ﴿١٩٢﴾","latin":"Rabbenâ inneke men tudhilün-Nâre fekad ahzeytehû ve mâ liz-zâlimîne min ensâr.","tr":"Ey Rabbimiz! Cehenneme kimi atarsan şüphesiz onu rezil etmiş olursun; zalimlerin hiçbir yardımcısı yoktur.","en":"Our Lord, indeed whoever You admit to the Fire - You have disgraced him, and for the wrongdoers there are no helpers."},{"id":974,"title":"Allah'a İman ve İnanç İçin Dua (Rabbenâ Duası)","ref":"Âl-i İmrân Sûresi: 3/193","url":"https://quran.com/3/193","ar":"رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِيًا يُنَادِي لِلْإِيمَانِ أَنْ آمِنُوا بِرَبِّكُمْ فَآمَنَّا","latin":"Rabbenâ innenâ semi'nâ münâdiyyen yünâdî lil-îmâni en âminû bi-Rabbiküm fe-âmennâ.","tr":"(193) Ey Rabbimiz! Gerçekten biz, 'Rabbinize iman edin' diye imana çağıran bir davetçiyi duyduk ve iman ettik.","en":"(193) Our Lord, indeed we have heard a caller calling to faith, [saying], 'Believe in your Lord,' and we have believed."},{"id":975,"title":"Bağışlanma ve Hayırlı Ölüm İçin Rabbenâ Duası","ref":"Âl-i İmrân Sûresi: 3/193","url":"https://quran.com/3/193","ar":"رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الْأَبْرَارِ ﴿١٩٣﴾","latin":"Rabbenâ fağfir lenâ żünûbenâ ve keffir annâ seyyiâtinâ ve teveffenâ meal-ebrâr.","tr":"Ey Rabbimiz! Günahlarımızı bağışla, kötülüklerimizi ört ve bizi iyilerle birlikte vefat ettir.","en":"Our Lord, so forgive us our sins and remove from us our misdeeds and cause us to die with the righteous."},{"id":976,"title":"Allah'ın Vaadi ve Koruma İçin Dua (Rabbenâ Duası)","ref":"Âl-i İmrân Sûresi: 3/194","url":"https://quran.com/3/194","ar":"رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَىٰ رُسُلِكَ وَلَا تُخْزِنَا يَوْمَ الْقِيَامَةِ ۗ إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ ﴿١٩٤﴾","latin":"Rabbenâ ve âtinâ mâ veadtenâ alâ rusülike ve lâ tuhzinâ Yevmel-Kıyâmeh; inneke lâ tühliful-mîâd.","tr":"Ey Rabbimiz! Peygamberlerin aracılığıyla bize vaat ettiğini ver ve bizi kıyamet günü mahcup etme. Şüphesiz Sen vaadinden dönmezsin.","en":"Our Lord, and grant us what You promised us through Your messengers and do not disgrace us on the Day of Resurrection. Indeed, You do not fail in [Your] promise.\""},{"id":983,"title":"Zulüm ve Küfürden Korunma İçin Dua (Rabbenâ Duası)","ref":"Yûnus Sûresi: 10/85-86","url":"https://quran.com/10/85","ar":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلْقَوْمِ الظَّالِمِينَ ﴿٨٥﴾ وَنَجِّنَا بِرَحْمَتِكَ مِنَ الْقَوْمِ الْكَافِرِينَ ﴿٨٦﴾","latin":"Rabbenâ lâ tec'alnâ fitnetal-lil-kavmiz-zâlimîn. Ve neccınâ birahmetike minel-kavmil-kâfirîn.","tr":"(85) Ey Rabbimiz! Bizi zalim kavim için fitne (deneme aracı) kılma. (86) Ve bizi kâfir kavimden rahmetinle kurtar.","en":"(85) Our Lord, make us not [objects of] trial for the wrongdoing people (86) And save us by Your mercy from the disbelieving people."},{"id":984,"title":"Allah'ın Her Şeyden Haberdar Olduğuna Dair Dua (Rabbenâ Duası)","ref":"İbrâhim Sûresi: 14/38","url":"https://quran.com/14/38","ar":"رَبَّنَا إِنَّكَ تَعْلَمُ مَا نُخْفِي وَمَا نُعْلِنُ ۗ وَمَا يَخْفَىٰ عَلَى اللَّهِ مِن شَيْءٍ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ ‎﴿٣٨﴾","latin":"Rabbenâ inneke ta'lemü mâ nuhfî ve mâ nu'lin; ve mâ yahfâ alallâhi min şey'in fil-ardı ve lâ fis-semâ.","tr":"Ey Rabbimiz! Şüphesiz Sen gizlediğimizi de açıkladığımızı da bilirsin. Yerde ve gökte hiçbir şey Allah'tan gizli kalmaz.","en":"Our Lord, indeed You know what we conceal and what we declare, and nothing is hidden from Allah on the earth or in the heaven."},{"id":986,"title":"Anne-Baba ve Mü'minler İçin Bağışlanma Duası (Rabbenâ Duası)","ref":"İbrâhim Sûresi: 14/41","url":"https://quran.com/14/41","ar":"رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ ﴿٤١﴾","latin":"Rabbenâ'ğfir lî ve li-vâlideyye ve lil-mü'minîne yevme yekûmül-hisâb.","tr":"Ey Rabbimiz! Hesap günü beni, anne-babamı ve tüm mü'minleri bağışla.","en":"Our Lord, forgive me and my parents and the believers the Day when the account is established."},{"id":988,"title":"Zulümden Korunma Duası (Rabbenâ Duası)","ref":"Tâhâ Sûresi: 20/45","url":"https://quran.com/20/45","ar":"رَبَّنَا إِنَّنَا نَخَافُ أَن يَفْرُطَ عَلَيْنَا أَوْ أَن يَطْغَىٰ ‎﴿٤٥﴾‏","latin":"Rabbenâ innenâ nehâfü en yefruta aleynâ ev en yatğâ.","tr":"Ey Rabbimiz! Gerçekten biz, onun bize karşı aşırı gitmesinden veya azmasından korkuyoruz.","en":"Our Lord, indeed we are afraid that he will hasten [punishment] against us or that he will transgress."},{"id":992,"title":"Bağışlanma Duası (Rabbenâ Lâ Ğafûrun Şekûr)","ref":"Fâtır Sûresi: 35/34","url":"https://quran.com/35/34","ar":"رَبَّنَا لَغَفُورٌ شَكُورٌ ‎﴿٣٤﴾","latin":"Rabbenâ lâ-Ğafûrun Şekûr.","tr":"Rabbimiz şüphesiz çok bağışlayıcı ve şükrün karşılığını verendir.","en":"Our Lord is Forgiving and Appreciative -"},{"id":994,"title":"Ailenin Ebedî Cennete Girmesi İçin Rabbenâ Duası (Ğâfir Sûresi)","ref":"Ğâfir Sûresi: 40/8-9","url":"https://quran.com/40/8","ar":"رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدتَّهُمْ وَمَن صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ ۚ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ‎﴿٨﴾‏ وَقِهِمُ السَّيِّئَاتِ ۚ وَمَن تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ ۚ وَذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ ‎﴿٩﴾","latin":"Rabbenâ ve edhilhüm cennâti adninil-letî veadtehüm ve men salaha min âbâihim ve ezvâcihim ve zürriyyâtihim; inneke Entel-Azîzül-Hakîm. Ve kıhimüs-seyyiât; ve men tekıs-seyyiâti yevme'ižin fekad rahimteh; ve żâlike hüvel-fevzül-azîm.","tr":"(8) Ey Rabbimiz! Onları, babalarından, eşlerinden ve soylarından sâlih olanlarla birlikte onlara vaat ettiğin Adn cennetlerine koy. Şüphesiz Sen Azîz'sin, Hakîm'sin. (9) O günde kötülüklerden kimi korursan gerçekten ona merhamet etmiş olursun; işte bu büyük kurtuluştur.","en":"(8) Our Lord, and admit them to gardens of perpetual residence which You have promised them and whoever was righteous among their fathers, their spouses and their offspring. Indeed, it is You who is the Exalted in Might, the Wise. (9) And he whom You protect from evil consequences that Day - You will have given him mercy. And that is the great attainment."},{"id":995,"title":"Müslümanlar Arasında Bağışlanma ve Birlik İçin Dua (Haşr Sûresi)","ref":"Haşr Sûresi: 59/10","url":"https://quran.com/59/10","ar":"رَبَّنَا اغْفِرْ لَنَا وَلِإِخْوَانِنَا الَّذِينَ سَبَقُونَا بِالْإِيمَانِ وَلَا تَجْعَلْ فِي قُلُوبِنَا غِلًّا لِّلَّذِينَ آمَنُوا","latin":"Rabbenâ'ğfir lenâ ve li-ihvâninalleżîne sebekûnâ bil-îmâni ve lâ tec'al fî kulûbinâ ğıllen lillezîne âmenû. Rabbenâ inneke Raûfün Rahîm.","tr":"Ey Rabbimiz! Bizi ve bizden önce imanla geçen kardeşlerimizi bağışla; iman edenlere karşı kalplerimizde kin bırakma. Ey Rabbimiz! Şüphesiz Sen Raûf'sun, Rahîm'sin.","en":"Our Lord, forgive us and our brothers who preceded us in faith and put not in our hearts [any] resentment toward those who have believed. Our Lord, indeed You are Kind and Merciful."},{"id":996,"title":"Şefkat ve Merhamet İçin Rabbenâ Duası","ref":"Haşr Sûresi: 59/10","url":"https://quran.com/59/10","ar":"رَبَّنَا إِنَّكَ رَءُوفٌ رَّحِيمٌ","latin":"Rabbenâ inneke Raûfün Rahîm.","tr":"Ey Rabbimiz! Şüphesiz Sen Raûf'sun (çok şefkatlisin) ve Rahîm'sin (çok merhametlisin).","en":"Our Lord, indeed You are Kind and Merciful."},{"id":997,"title":"Allah'a Tevekkül Duası (Mümtehine Sûresi)","ref":"Mümtehine Sûresi: 60/4","url":"https://quran.com/60/4","ar":"رَّبَّنَا عَلَيْكَ تَوَكَّلْنَا وَإِلَيْكَ أَنَبْنَا وَإِلَيْكَ الْمَصِيرُ ﴿٤﴾","latin":"Rabbenâ aleyke tevekkelnâ ve ileyke enebnâ ve ileykel-masîr.","tr":"Ey Rabbimiz! Sana tevekkül ettik, Sana yöneldik ve dönüş yalnızca Sanadır.","en":"Our Lord, upon You we have relied, and to You we have returned, and to You is the destination."},{"id":998,"title":"Allah'tan Bağışlanma ve Korunma Duası (Rabbenâ Duası)","ref":"Mümtehine Sûresi: 60/5","url":"https://quran.com/60/5","ar":"رَبَّنَا لَا تَجْعَلْنَا فِتْنَةً لِّلَّذِينَ كَفَرُوا وَاغْفِرْ لَنَا رَبَّنَا ۖ إِنَّكَ أَنتَ الْعَزِيزُ الْحَكِيمُ ﴿٥﴾","latin":"Rabbenâ lâ tec'alnâ fitnetan lillezîne keferû vağfir lenâ Rabbenâ inneke Entel-Azîzül-Hakîm.","tr":"Ey Rabbimiz! Bizi kâfirlere fitne (deneme aracı) kılma ve bizi bağışla. Ey Rabbimiz! Şüphesiz Sen Azîz'sin, Hakîm'sin.","en":"Our Lord, make us not [objects of] torment for the disbelievers and forgive us, our Lord. Indeed, it is You who is the Exalted in Might, the Wise."},{"id":1001,"title":"Allah'a Şükür İçin Güçlü Akşam Duası","ref":"Hasen (İbn Hacer). Netâicü'l-Efkâr: 2/380","url":"https://github.com/islamicapi/masnun-dua/blob/5b615c53c271f348432cc8913b81f7a220aea114/translation/tr/dua_1001.json","ar":"اَللَّهُمَّ مَا أَمْسَى بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ، فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","latin":"Allâhümme mâ emse bî min ni'metin ev bi-ehadin min halkıke femınke vahdeke lâ şerîke lek, felakel-hamdu ve lekeş-şükr.","tr":"Ey Allah'ım! Bu akşam bende veya yarattıklarından herhangi birinde bulunan her nimet, yalnızca Senden gelir, Senin ortağın yoktur. Hamd ve şükür yalnızca Sanadır.\n\nBu duayı sabah okuyan, o günün şükür borcunu yerine getirmiş olur; akşam okuyan ise o gecenin şükür borcunu ödemiş olur.","en":"O Allah, what blessing I have received in this evening or any of Your creation, is from You alone, without any partner, so for You is all praise and unto You all thanks.\n\nWhoever recites this in the morning, has completed his obligation to thank Allah for that day; and whoever says it in the evening, has completed his obligation for that night."}]);})();
